    public function creditHistoryget(Request $request)
    {
        $id = $request->query('partner_id', $request->input('partner_id'));

        if (!$id) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Partner ID is required.',
                'data' => null,
            ], 400);
        }

        $partner = Partner::query()->find($id);
        if (!$partner) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Partner not found.',
                'data' => null,
            ], 404);
        }

        try {
            // Allocation model: no prepaid wallet reconcile.
            $creditLimit = (float) ($partner->credit_limit ?? 0);
            $creditUsed = round(PartnerCreditService::summarizeUsedCredit((int) $id), 2);
            $remainingCreditLimit = round(PartnerCreditService::remainingPurchaseAllowance((int) $id), 2);
            $walletBalance = $remainingCreditLimit;
            $creditLimitReached = PartnerCreditService::isCreditLimitFullyUsed((int) $id);

            $ordersQuery = Order::query()
                ->where('partner_id', $id)
                ->where('order_type', 'b2b')
                ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) != 'draft'");

            $totalOrders = (int) (clone $ordersQuery)->count();

            $totalRevenue = (float) (clone $ordersQuery)
                ->whereIn('status', ['completed', 'success', 'paid', 'delivered', 'active'])
                ->sum('total_amount');

            $totalCustomers = (int) Customer::query()->where('partner_id', $id)->count();

            $expiringCutoff = now()->addDays(30)->toDateString();
            $totalSubscriptions = (int) Order::query()
                ->where('partner_id', $id)
                ->where('order_type', 'b2b')
                ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) != 'draft'")
                ->whereNotIn('status', ['rejected', 'cancelled', 'failed'])
                ->whereNotIn('order_category', ['renewed', 'upgraded'])
                ->where('status', '!=', 'cancelled')
                ->where(function ($q) use ($expiringCutoff) {
                    $q->whereNull('subscription_end_date')
                        ->orWhere('subscription_end_date', '>', $expiringCutoff);
                })
                ->count();

            $renewalsThisMonth = (int) Order::query()
                ->where('partner_id', $id)
                ->where('order_type', 'b2b')
                ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) != 'draft'")
                ->whereBetween('subscription_end_date', [now()->startOfMonth(), now()->endOfMonth()])
                ->count();

            $countUnpaid = 0.0;
            $countOverdue = 0.0;
            $countPending = 0.0;
            $countPaid = 0.0;
            $today = now()->toDateString();

            $partnerOrderIds = Order::query()
                ->where('partner_id', $id)
                ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) != 'draft'")
                ->pluck('id');

            $partnerInvoices = Invoice::query()
                ->where(function ($q) use ($id, $partnerOrderIds) {
                    $q->where('partner_id', $id);
                    if ($partnerOrderIds->isNotEmpty()) {
                        $q->orWhereIn('order_id', $partnerOrderIds);
                    }
                })
                ->where(function ($q) {
                    $q->whereNull('action_type')
                        ->orWhereRaw("LOWER(TRIM(COALESCE(action_type, ''))) <> 'credit_note'");
                })
                ->whereRaw("UPPER(TRIM(COALESCE(bill_no_full, ''))) NOT LIKE 'CN/%'")
                ->get(['id', 'net_amt', 'status', 'order_id', 'due_date']);

            $paidInvoiceIds = $this->buildPaidInvoiceIdSet(
                $partnerInvoices->pluck('id')->map(fn ($invId) => (int) $invId)->filter()->values()->all()
            );

            $invoiceOrderIds = $partnerInvoices
                ->pluck('order_id')
                ->filter()
                ->map(fn ($oid) => (int) $oid)
                ->unique()
                ->values()
                ->all();

            $ordersById = $invoiceOrderIds === []
                ? collect()
                : Order::query()->whereIn('id', $invoiceOrderIds)->get()->keyBy('id');

            $refundStatusByOrderId = $this->buildInvoiceRefundStatusByOrderId($invoiceOrderIds);

            foreach ($partnerInvoices as $inv) {
                $amount = (float) ($inv->net_amt ?? 0);
                $order = !empty($inv->order_id) ? $ordersById->get((int) $inv->order_id) : null;
                // Skip invoices tied to draft orders
                if ($order && strtolower(trim((string) ($order->status ?? ''))) === 'draft') {
                    continue;
                }
                $display = $this->resolvePartnerInvoiceDisplayStatus(
                    $inv,
                    $order,
                    $refundStatusByOrderId[(int) ($inv->order_id ?? 0)] ?? null,
                    isset($paidInvoiceIds[(int) ($inv->id ?? 0)])
                );

                if ($display['status'] === 'Paid') {
                    $countPaid += $amount;
                } elseif ($display['status'] === 'Cancelled') {
                    continue;
                } elseif ($inv->due_date && $inv->due_date < $today) {
                    $countOverdue += $amount;
                } else {
                    $countPending += $amount;
                }
            }

            $countUnpaid = (float) ($countPending + $countOverdue);

            $invoiceKpis = [
                'UNPAID INVOICES' => (float) round($countUnpaid, 2),
                'OVERDUE INVOICES' => (float) round($countOverdue, 2),
                'PENDING INVOICES' => (float) round($countPending, 2),
                'PAID INVOICES' => (float) round($countPaid, 2),
            ];

            $orderIds = $partnerOrderIds->all();
            $planIdList = [];
            if ($orderIds !== []) {
                $planIdList = OrderItem::query()
                    ->whereIn('order_id', $orderIds)
                    ->whereNotNull('plan_id')
                    ->pluck('plan_id')
                    ->unique()
                    ->values()
                    ->all();
            }

            $planNamesMap = [];
            if ($planIdList !== []) {
                foreach (Plan::query()->whereIn('id', $planIdList)->get(['id', 'title', 'name']) as $p) {
                    $planNamesMap[$p->id] = $p->title ?: ($p->name ?: ('Plan #' . $p->id));
                }
            }

            $transactionHistory = [];
            $recentOrders = Order::query()
                ->with(['customer', 'plan'])
                ->where('partner_id', $id)
                ->where('order_type', 'b2b')
                ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) != 'draft'")
                ->latest('id')
                ->limit(10)
                ->get();

            $recentOrderItemMap = OrderItem::query()
                ->whereIn('order_id', $recentOrders->pluck('id')->all())
                ->whereNotNull('plan_id')
                ->get(['order_id', 'plan_id'])
                ->groupBy('order_id');

            $partnerName = (string) ($partner->name ?? '₹');
            foreach ($recentOrders as $order) {
                $planNames = [];
                foreach ($recentOrderItemMap->get((int) $order->id, collect()) as $row) {
                    $pid = (int) ($row->plan_id ?? 0);
                    if ($pid > 0) {
                        $planNames[] = $planNamesMap[$pid] ?? ('Plan #' . $pid);
                    }
                }

                $planNamesStr = $planNames !== []
                    ? implode(', ', $planNames)
                    : (optional($order->plan)->title
                        ?? optional($order->plan)->name
                        ?? '₹');
                $companyObj = Customer::where('id', $order->user_id)->first();
                $companyNameVal = $companyObj ? $companyObj->company_name : null;

                $rawCategory = strtolower(trim((string) ($order->order_category ?? '')));
                if ($order->transfer_domain == 'yes') {
                    $category = 'Transfer';
                } elseif ($rawCategory === 'upgrade') {
                    $category = 'Upgrade';
                } elseif (in_array($rawCategory, ['partial_upgrade', 'partial-upgrade'], true)) {
                    $category = 'Partial Upgrade';
                } elseif (in_array($rawCategory, ['renewal', 'renewed'], true)) {
                    $category = 'Renewal';
                } elseif ($rawCategory === 'downgrade') {
                    $category = 'Downgrade';
                } elseif ($rawCategory === 'addon') {
                    $category = 'Add-on';
                } elseif ($rawCategory !== '') {
                    $category = ucwords(str_replace(['_', '-'], ' ', $rawCategory));
                } else {
                    $category = 'New';
                }

                $transactionHistory[] = [
                    'order_id' => $order->id,
                    'order_no' => $order->order_no ?? null,
                    'partner' => $partnerName,
                    'company_name' => $companyNameVal,
                    'customer' => optional($order->customer)->name
                        ?? optional($order->customer)->company_name
                        ?? optional($order->customer)->email
                        ?? '₹',
                    'category' => $category,
                    'domain' => $order->domain_name ?? '₹',
                    'plan' => $planNamesStr,
                    'plan_id' => $order->plan_id,
                    'amount' => (float) ($order->total_amount ?? $order->subtotal ?? 0),
                    'credit_used' => (float) ($order->credit_used ?? 0),
                    'status' => $order->status,
                    'date' => $order->created_at
                        ? Carbon::parse($order->created_at)->format('d M Y, H:i')
                        : '₹',
                ];
            }

            $renewalsHistory = [];
            $now = Carbon::now()->startOfDay();
            $renewalsQ = Order::query()
                ->with('plan')
                ->where('partner_id', $id)
                ->where('order_type', 'b2b')
                ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) != 'draft'")
                // Postgres: NOT IN excludes NULL rows too, so explicitly keep order_category = NULL.
                ->where(function ($q) {
                    $q->whereNull('order_category')
                        ->orWhereNotIn('order_category', ['renewed', 'upgraded']);
                })
                ->whereNotNull('subscription_end_date')
                ->where('subscription_end_date', '<=', $now->copy()->addDays(30)->endOfDay())
                // After invoice payment, orders may be marked `paid/success`, so include them.
                ->whereIn('status', ['completed', 'active', 'processing', 'paid', 'success'])
                ->orderBy('subscription_end_date')
                ->limit(10)
                ->get();

            $renewalOrderItemMap = OrderItem::query()
                ->whereIn('order_id', $renewalsQ->pluck('id')->all())
                ->whereNotNull('plan_id')
                ->get(['order_id', 'plan_id', 'quantity'])
                ->groupBy('order_id');
                

            foreach ($renewalsQ as $order) {
                $renewalDate = $order->subscription_end_date
                    ? Carbon::parse($order->subscription_end_date)
                    : null;
                $daysLeft = $renewalDate ? $now->diffInDays($renewalDate, false) : 0;
                $renewalItems = $renewalOrderItemMap->get((int) $order->id, collect());
                $licenseCount = (int) $renewalItems->sum(
                    fn ($item) => max(0, (int) ($item->quantity ?? 0))
                );
                if ($licenseCount <= 0) {
                    $licenseCount = max(0, (int) ($order->quantity ?? $order->licenses ?? 0));
                }

                $planNames = [];
                foreach ($renewalItems as $row) {
                    $pid = (int) ($row->plan_id ?? 0);
                    if ($pid > 0) {
                        $planNames[] = $planNamesMap[$pid] ?? ('Plan #' . $pid);
                    }
                }

                if ($planNames !== []) {
                    $planName = implode(', ', $planNames);
                    $planCount = count($planNames);
                } elseif ($order->plan || !empty($order->plan_id)) {
                    $planName = $order->plan->title ?? $order->plan->name ?? ('Plan #' . $order->plan_id);
                    $planCount = 1;
                } else {
                    $planName = '₹';
                    $planCount = 0;
                }

                // Fix: Get company name for each renewal order's user_id, but guard for null
                $renewalCompanyObj = Customer::where('id', $order->user_id)->first();
                $renewalCompanyNameVal = $renewalCompanyObj ? $renewalCompanyObj->company_name : null;

                $renewalsHistory[] = [
                    'order_id' => $order->id,
                    'order_no' => $order->order_no ?? null,
                    'plan_id' => $order->plan_id ?? null,
                    'plan_name' => $planName,
                    'plan_count' => $planCount,
                    'license_count' => $licenseCount,
                    'company_name' => $renewalCompanyNameVal,
                    'subscription_start_date' => $order->subscription_start_date
                        ? Carbon::parse($order->subscription_start_date)->format('Y-m-d')
                        : null,
                    'subscription_end_date' => $order->subscription_end_date
                        ? Carbon::parse($order->subscription_end_date)->format('Y-m-d')
                        : null,
                    'renewal_date' => $renewalDate ? $renewalDate->format('Y-m-d') : null,
                    'days_left' => $daysLeft,
                    'status' => $daysLeft <= 0 ? 'Expired' : 'Expiring',
                    'domain' => $order->domain_name ?? '₹',
                    'amount' => (float) ($order->total_amount ?? 0),
                ];
            }

            $formatDate = function ($dateVal) {
                if (empty($dateVal)) {
                    return null;
                }
                try {
                    return Carbon::parse($dateVal)->format('d-m-Y');
                } catch (\Exception $e) {
                    return $dateVal;
                }
            };

            $partnerArray = [
                'id' => $partner->id,
                'name' => $partner->name,
                'email' => $partner->email,
                'mobile' => $partner->mobile,
                'company_name' => $partner->company_name,
                'legal_name' => $partner->legal_name,
                'trade_name' => $partner->trade_name,
                'gstin' => $partner->gstin,
                'pan_no' => $partner->pan_no,
                'company_address' => $partner->company_address,
                'address' => $partner->address,
                'country' => $partner->country,
                'state' => $partner->state,
                'city' => $partner->city,
                'postcode' => $partner->postcode,
                'pincode' => $partner->pincode,
                'gst_status' => $partner->gst_status,
                'last_updated' => $formatDate($partner->last_updated),
                'constitution' => $partner->constitution,
                'registration_date' => $formatDate($partner->registration_date),
                'nature_of_business' => $partner->nature_of_business,
                'gst_id' => $partner->gst_id ?? null,
                'email_verified' => $partner->email_verified,
                'created_at' => $formatDate($partner->created_at),
                'updated_at' => $formatDate($partner->updated_at),
                'approveby' => $partner->approveby,
                'status' => $partner->status,
                'rejection_reason' => $partner->rejection_reason,
                'approve_datetime' => $formatDate($partner->approve_datetime),
                'credit_limit' => $creditLimit,
                'credit_used' => $creditUsed,
                'remaining_credit_limit' => $remainingCreditLimit,
                'credit_limit_reached' => $creditLimitReached,
                'wallet_balance' => $walletBalance,
                'available_balance' => $remainingCreditLimit,
            ];

            $kpisArray = [
                [
                    'key' => 'Total Revenue',
                    'value' => '₹' . $this->formatIndianCurrency($totalRevenue),
                ],

                [
                    'key' => 'Active Customers',
                    'value' => $totalCustomers,
                ],
                [
                    'key' => 'Total Subscriptions',
                    'value' => $totalSubscriptions,
                ],
                [
                    'key' => 'Renewals This Month',
                    'value' => $renewalsThisMonth,
                ],
            ];

            return response()->json([
                'success' => true,
                'error' => false,
                'message' => 'Credit history fetched successfully.',
                'data' => [
                    'partner' => $partnerArray,
                    'credit_summary' => [
                        'credit_limit' => round($creditLimit, 2),
                        'credit_used' => $creditUsed,
                        'remaining_credit_limit' => $remainingCreditLimit,
                        'available_balance' => $remainingCreditLimit,
                        'credit_limit_reached' => $creditLimitReached,
                        'wallet_balance' => round($walletBalance, 2),
                    ],
                    'kpis' => $kpisArray,
                    'invoice_kpis' => $invoiceKpis,
                    'transaction_history' => $transactionHistory,
                    'renewals_history' => $renewalsHistory,
                ],
            ], 200);
        } catch (\Throwable $globalErr) {
            Log::error('creditHistoryget_failed', [
                'partner_id' => $id,
                'error' => $globalErr->getMessage(),
            ]);

            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Failed to fetch credit history: ' . $globalErr->getMessage(),
                'data' => null,
            ], 500);
        }
    }

    private function formatIndianCurrency($amount)
    {
        $amount = (float) $amount;

        if ($amount >= 10000000) {
            return round($amount / 10000000, 2) . ' Cr';
        } elseif ($amount >= 100000) {
            return round($amount / 100000, 2) . ' Lac';
        } elseif ($amount >= 1000) {
            return round($amount / 1000, 2) . ' K';
        }

        return number_format($amount, 2);
    }

    /**
     * Numeric price with 2 decimals (e.g. "792.00") for API number fields.
     */
    private function formatPlanPriceValue(mixed $amount): ?string
    {
        if ($amount === null || $amount === '') {
            return null;
        }

        return number_format((float) $amount, 2, '.', '');
    }

    /**
     * Display price for partner services UI (e.g. /services/tizzy).
     */
    private function formatPlanPrice(mixed $amount): ?string
    {
        if ($amount === null || $amount === '') {
            return null;
        }

        return '₹' . number_format((float) $amount, 2);
    }

    public function creditHistory(Request $request)
    {
        $id = $request->query('partner_id', $request->input('partner_id'));

        if (!$id) {
            return response()->json([
                "success" => false,
                "error" => true,
                "message" => "Partner ID is required.",
                "data" => null
            ], 400);
        }

        $partner = Partner::find($id);
        if (!$partner) {
            return response()->json([
                "success" => false,
                "error" => true,
                "message" => "Partner not found.",
                "data" => null
            ], 404);
        }

        // Allocation model: available = credit_limit âˆ’ consumed (no prepaid wallet).
        $creditLimit = (float) ($partner->credit_limit ?? 0);
        $creditUsed = 0.0;
        try {
            $creditUsed = round(PartnerCreditService::summarizeUsedCredit((int) $id), 2);
        } catch (\Throwable $e) {
            $creditUsed = 0.0;
        }
        $walletBalance = round(PartnerCreditService::remainingPurchaseAllowance((int) $id), 2);

        $totalOrders = 0;
        $successfulOrders = 0;
        $totalRevenue = 0.0;
        $totalCustomers = 0;
        $totalSubscriptions = 0;
        $renewalsThisMonth = 0;

        $ordersQuery = Order::where('partner_id', $id)
            ->where('order_type', 'b2b');

        try {
            $totalOrders = (int) (clone $ordersQuery)->count();
        } catch (\Exception $e) {
            $totalOrders = 0;
        }

        try {
            $creditUsed = round(PartnerCreditService::summarizeUsedCredit((int) $id), 2);
        } catch (\Exception $e) {
            $creditUsed = 0.0;
        }

        $revenueQuery = Order::where('partner_id', $id)->where('order_type', 'b2b')->whereIn('status', ['completed', 'success', 'paid', 'delivered']);
        try {
            $totalRevenue = (float) $revenueQuery->sum('total_amount');
        } catch (\Exception $e) {
            try {
                $totalRevenue = (float) $revenueQuery->sum('subtotal');
            } catch (\Exception $e) {
                try {
                    $totalRevenue = (float) $revenueQuery->sum('credit_used');
                } catch (\Exception $e) {
                    $totalRevenue = 0.0;
                }
            }
        }

        // Customers
        $totalCustomers = (int) Customer::where('partner_id', $id)->where('status', 1)->count();

        $expiringCutoff = now()->addDays(30)->toDateString();
        $subscriptionsQuery = Order::where('partner_id', $id)
            ->where('order_type', 'b2b')
            ->whereNotIn('status', ['rejected', 'cancelled', 'failed'])
            ->whereNotIn('order_category', ['renewed'])
            ->where(function ($q) use ($expiringCutoff) {
                $q->whereNull('subscription_end_date')
                    ->orWhere('subscription_end_date', '>', $expiringCutoff);
            });

        $totalSubscriptions = (int) (clone $subscriptionsQuery)->count();


        $activeSubscriptions = (int) (clone $subscriptionsQuery)
            ->where('status', 'completed')
            ->count();

        // Renewals This Month
        $renewalsThisMonth = (int) Order::where('partner_id', $id)
            ->where('order_type', 'b2b')
            ->whereBetween('subscription_end_date', [now()->startOfMonth(), now()->endOfMonth()])
            ->count();

        // Format function for dates
        $formatDate = function ($dateVal) {
            if (empty($dateVal)) return null;
            try {
                return \Carbon\Carbon::parse($dateVal)->format('d-m-Y');
            } catch (\Exception $e) {
                return $dateVal;
            }
        };
        if($partner->aadhaar_mandatory == 'yes'){
            $aadhaar_mandatory = true;
        }else{
            $aadhaar_mandatory = false;
        }
        // Build partner array
        $partnerArray = [
            'id' => $partner->id,
            'name' => $partner->name,
            'email' => $partner->email,
            'mobile' => $partner->mobile,
            'company_name' => $partner->company_name,
            'legal_name' => $partner->legal_name,
            'trade_name' => $partner->trade_name,
            'gstin' => $partner->gstin,
            'pan_no' => $partner->pan_no,
            'company_address' => $partner->company_address,
            'address' => $partner->address,
            'country' => $partner->country,
            'state' => $partner->state,
            'city' => $partner->city,
            'postcode' => $partner->postcode,
            'pincode' => $partner->pincode,
            'gst_status' => $partner->gst_status,
            'last_updated' => $formatDate($partner->last_updated),
            'constitution' => $partner->constitution,
            'registration_date' => $formatDate($partner->registration_date),
            'nature_of_business' => $partner->nature_of_business,
            'gst_id' => $partner->gst_id ?? null,
            'email_verified' => $partner->email_verified,
            'created_at' => $formatDate($partner->created_at),
            'updated_at' => $formatDate($partner->updated_at),
            'approveby' => $partner->approveby,
            'status' => $partner->status,
            'rejection_reason' => $partner->rejection_reason,
            'approve_datetime' => $formatDate($partner->approve_datetime),
            'credit_limit' => (float) $creditLimit,
            'wallet_balance' => (float) $walletBalance,
            'available_balance' => (float) $walletBalance,
            'aadhaar_mandatory' => $aadhaar_mandatory,
        ];

        $kpisArray = [
            'credit_limit' => $creditLimit,
            'wallet_balance' => (float) $walletBalance,
            'available_balance' => (float) $walletBalance,
            'credit_used' => $creditUsed,
            'total_orders' => $totalOrders,
            'successful_orders' => $successfulOrders,
            'total_revenue' => $totalRevenue,
            'total_customers' => $totalCustomers,
            'total_subscriptions' => $totalSubscriptions,
            'active_subscriptions' => $activeSubscriptions,
            'renewals_this_month' => $renewalsThisMonth,
        ];

        $data = [
            'partner' => $partnerArray,
            'kpis' => $kpisArray
        ];

        // Success response
        return response()->json([
            "success" => true,
            "error" => false,
            "message" => "Credit history fetched successfully.",
            "data" => $data
        ], 200);
    }

    public function orderhistory(Request $request)
    {
        $partnerId = $request->partner_id;

        if (!$partnerId) {
            return response()->json([
                'success' => false,
                'message' => 'Partner ID is required',
                'data' => null
            ], 400);
        }

        // status=completed | pending,cancelled (comma separated); draft is hidden unless asked for
        $statusFilter = collect(explode(',', strtolower((string) $request->input('status', ''))))
            ->map(fn ($s) => trim($s))->filter(fn ($s) => $s !== '' && $s !== 'all')->values()->all();
        if (in_array('cancelled', $statusFilter, true)) {
            $statusFilter[] = 'canceled';
        }
        $statusCol = "LOWER(TRIM(COALESCE(status, '')))";
        $providerId = (int) $request->input('provider_id', 0);
        $search = trim((string) $request->input('search', ''));
        $like = '%' . addcslashes($search, '%_\\') . '%';

        $ordersQuery = Order::with(['customer', 'plan', 'partner'])
            ->where('partner_id', $partnerId)
            ->when($statusFilter, fn ($q) => $q->whereIn(DB::raw($statusCol), $statusFilter),
                fn ($q) => $q->whereRaw("{$statusCol} != 'draft'"))
            ->when($providerId > 0, function ($q) use ($providerId) {
                $planIds = Plan::query()->where('provider_id', $providerId)->pluck('id')->all();
                $q->where(fn ($w) => $w->whereIn('plan_id', $planIds)
                    ->orWhereHas('items', fn ($i) => $i->whereIn('plan_id', $planIds)));
            })
            // search: order no, domain, customer name/company/email/mobile, plan name
            ->when($search !== '', function ($q) use ($like) {
                $planIds = Plan::query()->where('name', 'ILIKE', $like)->pluck('id')->all();
                $q->where(fn ($w) => $w->where('order_no', 'ILIKE', $like)
                    ->orWhere('domain_name', 'ILIKE', $like)
                    ->orWhereHas('customer', fn ($c) => $c->where('name', 'ILIKE', $like)
                        ->orWhere('company_name', 'ILIKE', $like)
                        ->orWhere('email', 'ILIKE', $like)
                        ->orWhereRaw('CAST(mobile AS TEXT) ILIKE ?', [$like]))
                    ->when($planIds, fn ($p) => $p->orWhereIn('plan_id', $planIds)));
            })
            ->latest();

        // Paginate only when page_no / per_page is sent, so existing callers still get the full list
        $pagination = null;
        if ($request->filled('page_no') || $request->filled('page') || $request->filled('per_page')) {
            $perPage = max(1, min(100, (int) $request->input('per_page', 10)));
            $pageNo = max(1, (int) $request->input('page_no', $request->input('page', 1)));
            $paginator = $ordersQuery->paginate($perPage, ['*'], 'page', $pageNo);
            $orders = $paginator->getCollection();
            $pagination = [
                'total' => $paginator->total(),
                'per_page' => $paginator->perPage(),
                'current_page' => $paginator->currentPage(),
                'last_page' => $paginator->lastPage(),
                'from' => $paginator->firstItem(),
                'to' => $paginator->lastItem(),
            ];
        } else {
            $orders = $ordersQuery->get();
        }

        if ($orders->isEmpty()) {
            return response()->json([
                'success' => true,
                'message' => 'No completed orders found',
                'data' => [],
                'pagination' => $pagination,
            ]);
        }

        $data = $orders->map(function ($order) {
            // Fetch invoice number for each order (safe, avoids $orders->id error)
            $invoice = InvoiceMst::query()->where('order_id', $order->id)->first();
            $invoiceno = $invoice;

            $status = strtolower(trim((string) ($order->status ?? '')));
            $isCancelled = in_array($status, ['cancelled', 'canceled', 'rejected', 'failed', 'void'], true);
            $cancelledReason = $isCancelled
                ? trim((string) ($order->order_note ?? $order->cancellation_reason ?? $order->cancel_reason ?? ''))
                : null;
            if ($cancelledReason === '') {
                $cancelledReason = null;
            }

            return [
                'order_id' => $order->id,
                'order_no' => $order->order_no,
                'invoice_no' => $invoiceno,
                
                'partner' => $order->partner->name ?? ' ',

                // Add cust_id separately
                'cust_id' => $order->user_id ?? null,

                'customer' => $order->customer->name
                    ?? $order->customer->company_name
                    ?? $order->customer->email
                    ?? '₹',

                'company_name' => $order->customer->company_name ?? '',

                'domain_name' => $order->domain_name ?? ' ',
                'order_category' => match (strtolower(trim((string) ($order->order_category ?? '')))) {
                    'upgrade', 'upgraded' => 'upgraded plan',
                    'partial_upgrade' => 'partial upgrade',
                    'addon', 'license_add' => 'license add',
                    'new' => 'new plan',
                    'downgrade', 'downgraded' => 'downgraded plan',
                    'renewed', 'renewal' => 'renewed plan',
                    default => $order->order_category ?? '',
                },

                'plan' => $order->plan->title
                    ?? $order->plan->name
                    ?? '₹',

                'plan_id' => $order->plan_id,
                'provider_id' => $order->plan->provider_id ?? null,

                'subtotal' => round((float) ($order->subtotal ?? 0), 2),
                'gst' => round((float) ($order->gst_amount ?? $order->tax_amount ?? 0), 2),
                'gst_amount' => round((float) ($order->gst_amount ?? $order->tax_amount ?? 0), 2),
                'gst_rate' => round((float) ($order->gst_rate ?? 0), 2),
                'coupon' => strtoupper(trim((string) ($order->promo_code ?? ''))),
                'discount_amount' => round((float) ($order->discount_amount ?? 0), 2),
                'remaining_value' => round((float) ($order->pro_rata_adjustment ?? 0), 2),
                'pro_rata_adjustment' => round((float) ($order->pro_rata_adjustment ?? 0), 2),

                'amount' => (float) (
                    $order->total_amount
                    ?? $order->subtotal
                    ?? 0
                ),

                'credit_used' => (float) ($order->credit_used ?? 0),

                'status' => $order->status,
                'cancelled_reason' => $cancelledReason,

                'date' => $order->created_at
                    ? \Carbon\Carbon::parse($order->created_at)->format('d M Y, H:i')
                    : '₹',
            ] + $this->partnerOrderActionFlags($order);
        });

        return response()->json([
            'success' => true,
            'message' => 'Completed order history fetched successfully',
            'data' => $data,
            'pagination' => $pagination,
        ]);
    }

    /**
     * Single transaction detail for partner panel (companion to transaction-history).
     * Body: partner_id, order_id
     */
    
    public function transactionDetails(Request $request)
    {
        $validator = Validator::make($request->all(), [
            'partner_id' => 'required|integer',
            'order_id' => 'required|integer',
        ]);

        if ($validator->fails()) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => $validator->errors()->first(),
                'data' => null,
            ], 400);
        }

        $partnerId = (int) $request->input('partner_id');
        $orderId = (int) $request->input('order_id');

        $partner = Partner::find($partnerId);
        if (!$partner) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Partner not found.',
                'data' => null,
            ], 404);
        }

        $order = Order::with(['customer', 'plan', 'partner', 'provider'])
            ->where('id', $orderId)
            ->where('partner_id', $partnerId)
            ->where('status', '!=', 'draft')
            ->first();

        if (!$order) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Transaction not found for this partner.',
                'data' => null,
            ], 404);
        }

        $invoice = InvoiceMst::query()->where('order_id', $order->id)->first();
        $poRow = OrderPoDetail::query()->where('order_id', (int) $order->id)->first();

        $orderItems = OrderItem::query()
            ->where('order_id', (int) $order->id)
            ->where(function ($q) {
                $q->whereNull('status')
                    ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted')");
            })
            ->orderBy('id')
            ->get();

        $planIds = $orderItems
            ->pluck('plan_id')
            ->filter()
            ->map(fn($id) => (int) $id)
            ->unique()
            ->values()
            ->all();

        $plansById = $planIds === []
            ? collect()
            : Plan::query()->whereIn('id', $planIds)->get()->keyBy('id');

        $providerIds = $plansById
            ->pluck('provider_id')
            ->filter()
            ->map(fn($id) => (int) $id)
            ->unique()
            ->values()
            ->all();

        if ((int) ($order->provider_id ?? 0) > 0) {
            $providerIds[] = (int) $order->provider_id;
            $providerIds = array_values(array_unique($providerIds));
        }

        $providersById = $providerIds === []
            ? collect()
            : Provider::query()->whereIn('id', $providerIds)->get()->keyBy('id');

        $status = strtolower(trim((string) ($order->status ?? '')));
        $isCancelled = in_array($status, ['cancelled', 'canceled', 'rejected', 'failed', 'void'], true);
        $cancelledReason = $isCancelled
            ? trim((string) ($order->order_note ?? $order->cancellation_reason ?? $order->cancel_reason ?? ''))
            : null;
        if ($cancelledReason === '') {
            $cancelledReason = null;
        }

        $formatDate = static function ($value, string $fallback = '-'): string {
            if (empty($value)) {
                return $fallback;
            }
            try {
                return Carbon::parse((string) $value)->format('d M Y');
            } catch (\Throwable $e) {
                return $fallback;
            }
        };

        $formatDateTime = static function ($value, string $fallback = '-'): string {
            if (empty($value)) {
                return $fallback;
            }
            try {
                return Carbon::parse((string) $value)->format('d M Y, H:i');
            } catch (\Throwable $e) {
                return $fallback;
            }
        };

        $firstNonEmpty = static function (...$candidates): string {
            foreach ($candidates as $candidate) {
                $value = trim((string) ($candidate ?? ''));
                if ($value !== '') {
                    return $value;
                }
            }

            return '';
        };

        $cycleUnitLabel = static function (?string $cycle): string {
            $cycle = strtolower(trim((string) $cycle));
            if (str_contains($cycle, 'month')) {
                return 'Per User / Per Month';
            }
            if (str_contains($cycle, 'quarter')) {
                return 'Per User / Per Quarter';
            }
            if (str_contains($cycle, 'year') || in_array($cycle, ['annual', 'annually'], true)) {
                return 'Per User / Per Year';
            }

            return 'Per User';
        };

        $billingCycle = trim((string) ($order->duration ?? optional($order->plan)->billing_cycle ?? ''));
        $enrollment_category = $this->resolveEnrollmentTypeLabel($order);
        $enrollmentType = $enrollment_category;
        if (strtolower(trim((string) ($order->domain_transfer ?? ''))) === 'yes') {
            $enrollmentType = 'Transfer Service';
        } else {
            $enrollmentType = 'New Service';
        }

        // Display status for UI (Processing / Pending / Active / …)
        $changeKind = $this->partnerPlanChangeOrderKind($order);
        $orderStatusDisplay = match (true) {
            $isCancelled => 'Cancelled',
            $changeKind === 'upgrade' && in_array($status, ['pending', 'processing', 'draft'], true)
            => 'Upgrade Pending',
            $changeKind === 'downgrade' && in_array($status, ['pending', 'processing', 'draft'], true)
            => 'Downgrade Pending',
            $changeKind === 'renewal' && in_array($status, ['pending', 'processing'], true)
            => 'Renewal Pending',
            $status === 'processing' => 'Processing',
            $status === 'pending' => 'Pending',
            $status === 'draft' => 'Draft',
            in_array($status, ['completed', 'active', 'paid', 'success'], true) => 'Active',
            $status === 'upgraded' => 'Upgraded',
            $status === 'downgraded' => 'Downgraded',
            $status === 'renewed' => 'Renewed',
            $status !== '' => ucwords(str_replace(['_', '-'], ' ', $status)),
            default => '-',
        };
        $isProcessingOrder = in_array($status, ['processing', 'pending', 'waiting'], true)
            || in_array($orderStatusDisplay, ['Processing', 'Pending', 'Upgrade Pending', 'Downgrade Pending', 'Renewal Pending'], true);

        $customer = $order->customer;
        $customerIdDisplay = trim((string) (optional($customer)->customer_no ?? ''));
        if ($customerIdDisplay === '' && (int) (optional($customer)->id ?? $order->user_id ?? 0) > 0) {
            $customerIdDisplay = str_pad((string) ((int) (optional($customer)->id ?? $order->user_id)), 5, '0', STR_PAD_LEFT);
        }
        if ($customerIdDisplay === '') {
            $customerIdDisplay = '-';
        }

        $companyName = trim((string) (
            optional($customer)->company_name
            ?? optional($customer)->name
            ?? '-'
        ));
        $contactName = trim((string) (optional($customer)->name ?? '-'));
        $customerEmail = trim((string) (optional($customer)->email ?? '-'));
        $customerMobile = trim((string) (optional($customer)->mobile ?? '-'));
        if ($customerMobile !== '-' && $customerMobile !== '' && !str_starts_with($customerMobile, '+')) {
            $customerMobile = '+91 ' . $customerMobile;
        }

        $invoiceNo = trim((string) (
            optional($invoice)->bill_no_full
            ?? optional($invoice)->invoice_no
            ?? optional($invoice)->bill_no
            ?? ''
        ));
        if ($invoiceNo === '') {
            $invoiceNo = '-';
        }

        $invoiceDate = $formatDate(optional($invoice)->bill_date ?? optional($invoice)->created_at);

        // Real payment txn id only — never fall back to order_no / invoice no.
        $transactionId = $firstNonEmpty(
            $order->razorpay_payment_id,
            $order->upi_transaction_id,
            $order->cheque_ref_no,
            optional($invoice)->payment_ref_no ?? null,
            optional($invoice)->transaction_id ?? null,
            optional($invoice)->utr ?? null
        );

        // Optional gateway txn from invoice payment ledger
        if (
            $transactionId === '' && $invoice && class_exists(\App\Models\InvoicePaymentTransactionItem::class)
            && class_exists(\App\Models\InvoicePaymentTransaction::class)
        ) {
            try {
                $txnIds = \App\Models\InvoicePaymentTransactionItem::query()
                    ->where('invoice_id', (int) $invoice->id)
                    ->pluck('invoice_payment_transaction_id')
                    ->map(fn($id) => (int) $id)
                    ->filter(fn($id) => $id > 0)
                    ->unique()
                    ->values()
                    ->all();

                if ($txnIds !== []) {
                    $paymentTxn = \App\Models\InvoicePaymentTransaction::query()
                        ->whereIn('id', $txnIds)
                        ->orderByDesc('id')
                        ->first();

                    if ($paymentTxn) {
                        $transactionId = $firstNonEmpty(
                            $paymentTxn->razorpay_payment_id ?? null,
                            $paymentTxn->payment_id ?? null,
                            $paymentTxn->gateway_payment_id ?? null,
                            $paymentTxn->utr ?? null,
                            $paymentTxn->transaction_ref ?? null,
                            $paymentTxn->reference_no ?? null
                        );
                        if ($transactionId === '' && (int) ($paymentTxn->id ?? 0) > 0) {
                            $transactionId = 'TXN-' . (int) $paymentTxn->id;
                        }
                    }
                }
            } catch (\Throwable $e) {
                // keep empty — UI shows '-'
            }
        }

        $hasGatewayTxnId = $transactionId !== '';

        // Always expose a transaction id (payment ref preferred; else TXN{order_pk} — never order_no).
        if ($transactionId === '') {
            $transactionId = 'TXN' . str_pad((string) (int) $order->id, 5, '0', STR_PAD_LEFT);
        }

        $utr = $firstNonEmpty(
            $order->upi_transaction_id,
            $order->cheque_ref_no,
            optional($invoice)->utr ?? null,
            $order->razorpay_payment_id
        );
        if ($utr === '') {
            $utr = '-';
        }

        $processingAt = $order->created_at
            ?? optional($invoice)->created_at
            ?? null;
        $transactionAt = optional($invoice)->paid_at
            ?? optional($invoice)->payment_date
            ?? $order->paid_at
            ?? $order->created_at;
        $processingTime = $formatDateTime($processingAt);
        $transactionDate = $formatDateTime($transactionAt);

        // Active time = when subscription/order became active.
        $isActiveOrder = in_array($status, ['completed', 'active', 'paid', 'success'], true)
            || in_array($orderStatusDisplay, ['Active', 'Expiring'], true);
        $activeAt = null;
        if ($isActiveOrder) {
            $activeAt = $order->activated_at
                ?? $order->subscription_start_date
                ?? optional($invoice)->paid_at
                ?? optional($invoice)->payment_date
                ?? $order->updated_at
                ?? $order->created_at;
        }
        $activeTime = $formatDateTime($activeAt);

        $invoicePaymentRaw = strtolower(trim((string) (
            optional($invoice)->payment_status
            ?? optional($invoice)->status
            ?? ''
        )));
        $creditUsedForStatus = (float) ($order->credit_used ?? 0);
        $hasPaymentProof = $hasGatewayTxnId
            || $creditUsedForStatus > 0
            || trim((string) ($order->razorpay_payment_id ?? '')) !== '';

        $paymentStatus = match (true) {
            $isCancelled => 'Cancelled',
            in_array($invoicePaymentRaw, ['paid', 'success', 'completed', 'captured'], true) => 'Paid',
            in_array($invoicePaymentRaw, ['unpaid', 'pending_payment', 'incomplete'], true) => 'Unpaid',
            in_array($invoicePaymentRaw, ['cancelled', 'canceled', 'rejected', 'failed', 'void'], true) => 'Cancelled',
            $hasPaymentProof => 'Paid',
            in_array($status, ['pending', 'draft', 'waiting'], true) => 'Unpaid',
            // processing after purchase is typically paid (wallet / online)
            $status === 'processing' => 'Paid',
            in_array($status, ['completed', 'active', 'paid', 'success'], true) => 'Paid',
            $invoicePaymentRaw !== '' && !in_array($invoicePaymentRaw, ['processing', 'pending'], true)
            => ucfirst($invoicePaymentRaw),
            default => '-',
        };

        $invoiceLinks = $this->buildOrderInvoiceLinks([(int) $order->id]);
        $downloadInvoiceUrl = null;
        if ($invoice) {
            $downloadInvoiceUrl = $this->resolveInvoicePdfUrl($invoice, (int) $order->id, $invoiceLinks);
        } elseif (!empty($invoiceLinks[(int) $order->id])) {
            $downloadInvoiceUrl = $invoiceLinks[(int) $order->id];
        }

        $domainName = OrderDomainHelper::resolveForOrder(
            $order,
            (int) ($order->cart_id ?? $order->source_cart_id ?? 0)
        );
        if ($domainName !== '') {
            OrderDomainHelper::persistOnOrderIfMissing((int) $order->id, $domainName);
            $order->domain_name = $domainName;
        } else {
            $domainName = '-';
        }
        $orderNo = trim((string) ($order->order_no ?? '-'));
        if ($orderNo === '') {
            $orderNo = '-';
        }

        $startDate = $formatDate($order->subscription_start_date);
        $endDate = $formatDate($order->subscription_end_date);
        $renewalDate = $formatDate($order->renewal_at ?? $order->subscription_end_date);

        $subscriptions = $orderItems->map(function ($item) use (
            $plansById,
            $providersById,
            $order,
            $billingCycle,
            $domainName,
            $orderNo,
            $renewalDate,
            $isCancelled,
            $isProcessingOrder,
            $orderStatusDisplay,
            $cycleUnitLabel
        ) {
            $plan = $plansById->get((int) ($item->plan_id ?? 0));
            $planName = trim((string) ($item->item_name ?? optional($plan)->name ?? optional($plan)->title ?? ''));
            if ($planName === '') {
                $planName = '-';
            }

            $qty = max(1, (int) ($item->quantity ?? $order->quantity ?? 1));
            $unitPrice = (float) ($item->unit_price ?? optional($plan)->price ?? 0);
            $lineTotal = (float) ($item->total_amount ?? ($unitPrice * $qty));
            $itemCycle = trim((string) (optional($plan)->billing_cycle ?? $order->duration ?? $billingCycle));
            $priceLabel = '₹' . number_format($unitPrice, 0) . ' ' . $cycleUnitLabel($itemCycle);

            $subscriptionNo = trim((string) ($item->subscription_id ?? $item->subscription_no ?? ''));
            if ($subscriptionNo === '' && (int) ($item->id ?? 0) > 0) {
                $subscriptionNo = 'SUB-' . str_pad((string) $item->id, 5, '0', STR_PAD_LEFT);
            }
            if ($subscriptionNo === '') {
                $subscriptionNo = '-';
            }

            $lineProvider = '-';
            if ((int) (optional($plan)->provider_id ?? 0) > 0) {
                $lineProvider = trim((string) (optional($providersById->get((int) $plan->provider_id))->name ?? '-'));
            }

            $itemStatusRaw = strtolower(trim((string) ($item->status ?? '')));
            $itemExpired = false;
            $itemEndDate = $item->subscription_end_date ?? $order->subscription_end_date;
            if (!empty($itemEndDate)) {
                try {
                    $itemExpired = Carbon::parse($itemEndDate)->endOfDay()->isPast();
                } catch (\Throwable $e) {
                    $itemExpired = false;
                }
            }
            $itemStatus = match (true) {
                $isCancelled => 'Cancelled',
                $isProcessingOrder => in_array($orderStatusDisplay, ['Pending', 'Upgrade Pending', 'Downgrade Pending', 'Renewal Pending'], true)
                    ? $orderStatusDisplay
                    : 'Processing',
                in_array($itemStatusRaw, ['pending', 'processing', 'waiting'], true) => 'Processing',
                in_array($itemStatusRaw, ['cancelled', 'canceled', 'rejected', 'failed', 'void'], true) => 'Cancelled',
                in_array($itemStatusRaw, ['upgraded', 'downgraded', 'renewed', 'suspended', 'inactive', 'deleted', 'delete'], true)
                => ucwords(str_replace(['_', '-'], ' ', $itemStatusRaw)),
                $itemExpired => 'Expired',
                in_array($itemStatusRaw, ['active', 'completed', 'paid', 'success', ''], true) => 'Active',
                $itemStatusRaw !== '' => ucwords(str_replace(['_', '-'], ' ', $itemStatusRaw)),
                default => 'Active',
            };

            return [
                'order_sub_id' => (int) ($item->id ?? 0),
                'plan_id' => (int) ($item->plan_id ?? 0) ?: null,
                'plan_name' => $planName,
                'provider_name' => $lineProvider,
                'unit_price' => round($unitPrice, 2),
                'price_label' => $priceLabel,
                'billing_cycle' => $itemCycle !== '' ? ucfirst($itemCycle) : '-',
                'status' => $itemStatus,
                'order_ref' => $orderNo,
                'subscription_no' => $subscriptionNo,
                'domain' => $domainName,
                'users' => $qty,
                'users_label' => $qty . ' ' . ($qty === 1 ? 'User' : 'Users'),
                'renewal_date' => $renewalDate,
                'subtotal' => round($lineTotal, 2),
            ];
        })->values()->all();

        // Fallback single line when order_items are missing
        if ($subscriptions === [] && (int) ($order->plan_id ?? 0) > 0) {
            $plan = $order->plan;
            $qty = max(1, (int) ($order->quantity ?? 1));
            $unitPrice = (float) (optional($plan)->price ?? $order->price ?? 0);
            $itemCycle = trim((string) (optional($plan)->billing_cycle ?? $billingCycle));
            $orderSubscriptionExpired = false;
            if (!empty($order->subscription_end_date)) {
                try {
                    $orderSubscriptionExpired = Carbon::parse($order->subscription_end_date)->endOfDay()->isPast();
                } catch (\Throwable $e) {
                    $orderSubscriptionExpired = false;
                }
            }
            $fallbackStatus = $isCancelled
                ? 'Cancelled'
                : ($isProcessingOrder
                    ? (in_array($orderStatusDisplay, ['Pending', 'Upgrade Pending', 'Downgrade Pending', 'Renewal Pending'], true)
                        ? $orderStatusDisplay
                        : 'Processing')
                    : ($orderSubscriptionExpired ? 'Expired' : 'Active'));
            $subscriptions[] = [
                'order_sub_id' => null,
                'plan_id' => (int) ($order->plan_id ?? 0),
                'plan_name' => trim((string) (optional($plan)->name ?? optional($plan)->title ?? '-')),
                'provider_name' => trim((string) (optional($order->provider)->name ?? '-')),
                'unit_price' => round($unitPrice, 2),
                'price_label' => '₹' . number_format($unitPrice, 0) . ' ' . $cycleUnitLabel($itemCycle),
                'billing_cycle' => $itemCycle !== '' ? ucfirst($itemCycle) : '-',
                'status' => $fallbackStatus,
                'order_ref' => $orderNo,
                'subscription_no' => '-',
                'domain' => $domainName,
                'users' => $qty,
                'users_label' => $qty . ' ' . ($qty === 1 ? 'User' : 'Users'),
                'renewal_date' => $renewalDate,
                'subtotal' => round((float) ($order->subtotal ?? ($unitPrice * $qty)), 2),
            ];
        }

        $serviceAmount = round((float) (
            optional($invoice)->taxable_total
            ?? $order->subtotal
            ?? collect($subscriptions)->sum('subtotal')
            ?? 0
        ), 2);

        $discountAmount = round((float) ($order->discount_amount ?? 0), 2);
        $lineTaxType = '';
        $poTaxType = '';
        if ($invoice) {
            try {
                $invoiceLines = InvoiceSub::query()
                    ->where('invoice_mst_id', (int) $invoice->id)
                    ->get(['tax_type', 'cgst', 'sgst', 'igst']);
                if ($invoiceLines->isNotEmpty()) {
                    $lineTaxType = (string) ($invoiceLines->first()->tax_type ?? '');
                }
            } catch (\Throwable $e) {
                // invoice_sub columns may differ on older billing DBs
            }
        }
        try {
            $poLines = OrderPoSub::query()
                ->where('order_id', (int) $order->id)
                ->get(['tax_type']);
            if ($poLines->isNotEmpty()) {
                $poTaxType = (string) ($poLines->first()->tax_type ?? '');
            }
        } catch (\Throwable $e) {
            // order_po_sub may be missing on some orders
        }

        $companyGstin = '';
        try {
            $companySettings = AdminSetting::query()->orderByDesc('id')->first();
            $companyGstin = trim((string) (
                optional($companySettings)->gstin
                ?? optional($companySettings)->gst_no
                ?? optional($companySettings)->company_gstin
                ?? ''
            ));
        } catch (\Throwable $e) {
            $companyGstin = '';
        }

        $customerGstin = $firstNonEmpty(
            $order->po_manual_gstin ?? null,
            optional($poRow)->manual_gstin ?? null,
            optional($poRow)->po_manual_gstin ?? null,
            $order->customer_gstin ?? null,
            optional($customer)->gstin ?? null
        );

        $gstAmount = max(0.0, round((float) ($order->gst_amount ?? $order->tax_amount ?? 0), 2));
        $gstRate = (float) ($order->gst_rate ?? 18.0);
        $custState = '';
        if (preg_match('/^(\d{2})[A-Z0-9]{13}$/', strtoupper(trim((string) $customerGstin)), $m)) {
            $custState = $m[1];
        }
        $coState = '27';
        if (preg_match('/^(\d{2})[A-Z0-9]{13}$/', strtoupper(trim((string) $companyGstin)), $m)) {
            $coState = $m[1];
        }
        $explicitTaxType = strtolower(trim((string) (optional($invoice)->tax_type ?? $order->tax_type ?? $lineTaxType ?? $poTaxType ?? '')));
        $isInterState = ($custState !== '' && $custState !== $coState) || $explicitTaxType === 'igst';
        $taxType = $isInterState ? 'igst' : 'cgst_sgst';
        $cgst = (float) (optional($invoice)->cgst_total ?? $order->cgst_total ?? ($isInterState ? 0.0 : round($gstAmount / 2, 2)));
        $sgst = (float) (optional($invoice)->sgst_total ?? $order->sgst_total ?? ($isInterState ? 0.0 : round($gstAmount - $cgst, 2)));
        $igst = (float) (optional($invoice)->igst_total ?? $order->igst_total ?? ($isInterState ? $gstAmount : 0.0));
        $showIgst = $isInterState || $igst > 0;

        $gstBreakdown = [
            'gst_amount' => $gstAmount,
            'gst_rate' => $gstRate,
            'tax_type' => $taxType,
            'show_igst' => $showIgst,
            'cgst' => $cgst,
            'sgst' => $sgst,
            'igst' => $igst,
            'cgst_label' => '₹' . number_format($cgst, 2),
            'sgst_label' => '₹' . number_format($sgst, 2),
            'igst_label' => '₹' . number_format($igst, 2),
            'gst_label' => '₹' . number_format($gstAmount, 2),
        ];

        $totalAmount = round((float) (
            optional($invoice)->net_amt
            ?? $order->total_amount
            ?? ($serviceAmount + (float) $gstBreakdown['gst_amount'] - $discountAmount)
        ), 2);
        $creditUsed = round((float) ($order->credit_used ?? 0), 2);

        $sourcePo = $this->resolveParentOrderPoPayload((int) $order->id);
        $poNumber = trim((string) ($sourcePo['po_number'] ?? optional($poRow)->po_number ?? ''));
        $poDate = $formatDate(optional($poRow)->po_date ?? optional($poRow)->created_at);
        $poAmount = round((float) (optional($poRow)->po_amount ?? $totalAmount), 2);
        $approvalDate = $formatDate(
            optional($poRow)->aadhar_verified_at
                ?? optional($poRow)->approved_date
                ?? optional($poRow)->updated_at
                ?? optional($poRow)->po_date
        );
        $poLink = $sourcePo['po_link'] ?? optional($poRow)->po_document_url ?? ($order->po_document_url ?? null);

        $creditNote = null;
        $hasCreditNote = false;
        try {
            $creditNote = app(\App\Services\OrderCancellationCreditNoteService::class)
                ->resolveCreditNotesByOrderIds([(int) $order->id])[(int) $order->id] ?? null;
            $hasCreditNote = is_array($creditNote)
                && !empty($creditNote['credit_note_id'] ?? $creditNote['credit_note_no'] ?? null);
        } catch (\Throwable $e) {
            Log::warning('transaction_details_credit_note_failed', [
                'order_id' => (int) $order->id,
                'error' => $e->getMessage(),
            ]);
        }

        // Dynamic remaining value resolution
        $orderCat = strtolower(trim((string) ($order->order_category ?? $order->category ?? '')));
        $isPlanChangeOrder = in_array($orderCat, ['upgrade', 'upgraded', 'downgrade', 'downgraded', 'upgrade service', 'downgrade service'], true)
            || (int) ($order->parent_order_id ?? 0) > 0
            || (int) ($order->previous_plan_id ?? 0) > 0
            || preg_match('/upgrade|downgrade/i', (string) ($enrollmentType ?? '')) === 1;

        $remainingValue = max(0.0, round((float) ($order->remaining_value ?? $order->pro_rata_adjustment ?? 0), 2));

        if ($remainingValue <= 0) {
            foreach ($orderItems as $it) {
                $remainingValue += (float) ($it->prorated_credit ?? $it->pro_rata_adjustment ?? $it->remaining_value ?? 0);
            }
            $remainingValue = max(0.0, round($remainingValue, 2));
        }

        if ($remainingValue <= 0 && $isPlanChangeOrder) {
            $orderDisc = max(0.0, round((float) ($order->discount_amount ?? 0), 2));
            if ($orderDisc > 0 && trim((string) ($order->promo_code ?? '')) === '') {
                $remainingValue = $orderDisc;
            }
        }

        if ($remainingValue <= 0) {
            $cartId = (int) ($order->source_cart_id ?? $order->cart_id ?? 0);
            if ($cartId > 0) {
                try {
                    $cartProRata = round((float) (\App\Models\Cart::query()->whereKey($cartId)->value('pro_rata_adjustment') ?? 0), 2);
                    if ($cartProRata > 0) {
                        $remainingValue = $cartProRata;
                    }
                } catch (\Throwable $e) {
                    // continue
                }
            }
        }

        if ($remainingValue <= 0 && $isPlanChangeOrder) {
            $grossSub = (float) $orderItems->sum('total_amount');
            if ($grossSub > $serviceAmount + 0.009) {
                $couponOnly = trim((string) ($order->promo_code ?? '')) !== '' ? (float) ($order->discount_amount ?? 0) : 0.0;
                $derived = round($grossSub - $serviceAmount - $couponOnly, 2);
                if ($derived >= 0.01) {
                    $remainingValue = $derived;
                }
            }
        }

        $remainingValue = max(0.0, round((float) $remainingValue, 2));
        $couponCode = strtoupper(trim((string) ($order->promo_code ?? '')));

        $paymentBreakdown = [
            'service_amount' => round($serviceAmount, 2),
            'service_amount_label' => '₹' . number_format($serviceAmount, 2),
            'discount_amount' => round($discountAmount, 2),
            'discount_amount_label' => $discountAmount > 0 ? ('-₹' . number_format($discountAmount, 2)) : '₹0.00',
            'coupon_code' => $couponCode !== '' ? $couponCode : null,
            'remaining_value' => round($remainingValue, 2),
            'remaining_value_label' => $remainingValue > 0 ? ('-₹' . number_format($remainingValue, 2)) : '₹0.00',
            'pro_rata_adjustment' => round($remainingValue, 2),
            'applied_pro_rata' => round($remainingValue, 2),
            'tax_type' => (string) ($gstBreakdown['tax_type'] ?? 'cgst_sgst'),
            'show_igst' => (bool) ($gstBreakdown['show_igst'] ?? false),
            'gst_amount' => round($gstAmount, 2),
            'gst_amount_label' => '₹' . number_format($gstAmount, 2),
            'cgst' => round($cgst, 2),
            'cgst_label' => '₹' . number_format($cgst, 2),
            'sgst' => round($sgst, 2),
            'sgst_label' => '₹' . number_format($sgst, 2),
            'igst' => round($igst, 2),
            'igst_label' => '₹' . number_format($igst, 2),
            'credit_used' => round($creditUsed, 2),
            'credit_used_label' => '₹' . number_format($creditUsed, 2),
            'total_amount' => round($totalAmount, 2),
            'total_amount_label' => '₹' . number_format($totalAmount, 2),
        ];

        $data = [
            // Left column — Customer Information
            'customer_information' => [
                'customer_id' => $customerIdDisplay,
                'cust_id' => (int) (optional($customer)->id ?? $order->user_id ?? 0) ?: null,
                'company_name' => $companyName,
                'contact_name' => $contactName,
                'email' => $customerEmail !== '' ? $customerEmail : '-',
                'contact_no' => $customerMobile !== '' ? $customerMobile : '-',
                'avatar_initial' => strtoupper(substr($companyName !== '-' ? $companyName : 'C', 0, 1)),
            ],

            // Left column — Payment & Billing
            'payment_and_billing' => [
                'invoice_number' => $invoiceNo,
                'invoice_date' => $invoiceDate,
                'transaction_date' => $transactionDate,
                'processing_time' => $processingTime,
                'active_time' => $activeTime,
                'transaction_id' => $transactionId,
                'utr' => $utr,
                'payment_status' => $invoice->status ?? 'NOT_GENERATED',
                'remaining_value' => $remainingValue,
                'remaining_value_label' => $remainingValue > 0 ? ('-₹' . number_format($remainingValue, 2)) : '₹0.00',
                'download_invoice_url' => $downloadInvoiceUrl,
            ],

            // Left column — Subscription Details
            'subscription_details' => [
                'domain_name' => $domainName,
                'order_id' => $orderNo,
                'order_pk' => (int) $order->id,
                'subscription_start_date' => $startDate,
                'subscription_end_date' => $endDate,
                'subscriptions' => $subscriptions,
            ],

            // Right column — Order Summary
            'order_summary' => [
                'order_id' => $orderNo,
                'order_pk' => (int) $order->id,
                'enrollment_type' => $enrollmentType,
                'amount_paid' => $totalAmount,
                'amount_paid_label' => '₹' . number_format($totalAmount, 2),
                'status' => $orderStatusDisplay,
                'status_raw' => (string) ($order->status ?? ''),
                'processing_time' => $processingTime,
                'active_time' => $activeTime,
                'is_processing' => $isProcessingOrder,
                'is_active' => $isActiveOrder,
                'is_cancelled' => $isCancelled,
                'cancelled_reason' => $cancelledReason,
                'tax_type' => (string) ($gstBreakdown['tax_type'] ?? 'cgst_sgst'),
                'show_igst' => (bool) ($gstBreakdown['show_igst'] ?? false),
            ],

            // Right column — Payment Breakdown
            'payment_breakdown' => $paymentBreakdown,

            // Right column â€” Invoice & E-Invoice Details (PO / E-Invoice tabs)
            'invoice_and_einvoice' => [
                'download_invoice_url' => $downloadInvoiceUrl,
                'active_tab' => 'po',
                'po' => [
                    'po_number' => $poNumber !== '' ? $poNumber : '-',
                    'po_date' => $poDate,
                    'po_amount' => $poAmount,
                    'po_amount_label' => '₹' . number_format($poAmount, 2),
                    'approval_date' => $approvalDate,
                    'po_mode' => (string) ($sourcePo['po_mode'] ?? optional($poRow)->po_mode ?? 'generated'),
                    'po_link' => $poLink,
                    'is_uploaded_po' => (bool) ($sourcePo['is_uploaded'] ?? false),
                ],
                'e_invoice' => [
                    'invoice_number' => $invoiceNo,
                    'invoice_date' => $invoiceDate,
                    'invoice_amount' => $totalAmount,
                    'invoice_amount_label' => '₹' . number_format($totalAmount, 2),
                    'invoice_pdf_url' => $downloadInvoiceUrl,
                    'irn' => trim((string) (optional($invoice)->irn ?? '')) ?: null,
                    'ack_no' => trim((string) (optional($invoice)->ack_no ?? '')) ?: null,
                    'status' => isset($invoice) && isset($invoice->irn) && trim($invoice->irn) !== ''
                        ? ((isset($invoice->is_cancelled) && $invoice->is_cancelled) ? 'CANCELLED' : 'ACTIVE')
                        : 'NOT_GENERATED',
                ],

            ],

            'credit_note' => [
                'has_credit_note' => $hasCreditNote,
                'details' => $creditNote,
            ],

            'actions' => $this->partnerOrderActionFlags($order),
        ];

        return response()->json([
            'success' => true,
            'error' => false,
            'message' => 'Transaction details fetched successfully',
            'data' => $data,
        ], 200);
    }

    public function domainHistory(Request $request)
    {
        $request->validate([
            'partner_id' => 'required|integer',
            'domain_names' => 'required|array',
            'domain_names.*' => 'required|string'
        ]);

        // Clean domains
        $domains = collect($request->domain_names)
            ->map(function ($domain) {
                return trim(strtolower($domain));
            })
            ->toArray();

        $history = Order::with(['plan:id,name', 'items.plan:id,name'])
            ->where('partner_id', $request->partner_id)
            ->whereIn(
                \DB::raw('LOWER(domain_name)'),
                $domains
            )
            ->orderByDesc('subscription_start_date')
            ->orderByDesc('id')
            ->get();

        $historyOrderIds = $history->pluck('id')->filter()->map(fn($id) => (int) $id)->values()->all();
        $planChangeContext = $this->buildPlanChangeContextForOrders($historyOrderIds);
        $domainHistoryLinks = $this->buildDomainHistoryPlanChangeLinks(
            $history,
            $planChangeContext['child_change_orders_by_parent'],
            $planChangeContext['child_order_items'],
            $planChangeContext['new_plans_by_id']
        );

        // Parents that later got a real renewal child â†’ label those roots as Renewed.
        // Do NOT count upgrade/downgrade (CH) children â€” that incorrectly shows "Renewed"
        // after a plain upgrade (e.g. blinkeye Business Standard).
        $renewedParentIds = Order::query()
            ->where('partner_id', $request->partner_id)
            ->whereIn('parent_order_id', $historyOrderIds ?: [-1])
            ->where(function ($q) {
                $q->whereIn('order_category', ['renewal', 'renew', 'renewed'])
                    ->orWhere('order_no', 'ilike', 'RN%');
            })
            ->whereNotIn('order_category', ['upgrade', 'downgrade', 'upgraded', 'downgraded'])
            ->pluck('parent_order_id')
            ->map(fn($id) => (int) $id)
            ->unique()
            ->all();

        // Group by domain â€” one history row per plan line so old upgraded parent plans stay visible.
        $groupedData = $history->groupBy(function ($item) {
            return strtolower($item->domain_name);
        })->map(function ($items, $domain) use ($renewedParentIds, $domainHistoryLinks) {
            return [
                'domain_name' => $domain,
                'history' => $items->flatMap(function ($item) use ($renewedParentIds, $domainHistoryLinks) {
                    $startDate = $item->subscription_start_date
                        ? \Carbon\Carbon::parse($item->subscription_start_date)->format('d M, Y')
                        : '-';

                    $endDate = $item->subscription_end_date
                        ? \Carbon\Carbon::parse($item->subscription_end_date)->format('d M, Y')
                        : '-';

                    
                    $rawOrderStatus = strtolower(trim((string) ($item->status ?? '')));
                    $rawCategory = strtolower(trim((string) ($item->order_category ?? '')));
                    $parentOrderId = (int) ($item->parent_order_id ?? 0);
                    $wasLaterRenewed = in_array((int) $item->id, $renewedParentIds, true);
                    $period = (
                        $item->subscription_start_date &&
                        $item->subscription_end_date
                    )
                        ? $startDate . ' - ' . $endDate
                        : '-';

                    $transferFlag = strtolower(trim((string) ($items->transfer_domain ?? '')));
                    $enrollmentType = ($transferFlag == 'yes') ? 'Transfer Service' : 'New Service';

                    $orderItems = collect($item->items ?? []);
                    if ($orderItems->isEmpty()) {
                        $statusLabel = $this->formatDomainHistoryStatusLabel(
                            $rawOrderStatus,
                            $rawCategory,
                            $parentOrderId,
                            $wasLaterRenewed
                        );
                        $link = $domainHistoryLinks['by_order_id'][(int) $item->id] ?? null;

                        return $this->expandDomainHistoryRows([
                            'id' => $item->id,
                            'order_id' => $item->id, 
                            'order_sub_id' => null,
                            'plan_id'=> $item->plan_id,
                            'partner_id' => $item->partner_id,
                            'order_no' => $item->order_no ?? null,
                            'order_status' => $rawOrderStatus !== '' ? $rawOrderStatus : null,
                            'order_category' => $rawCategory !== '' ? $rawCategory : 'new',
                            'plan_name' => optional($item->plan)->name ?? '-',
                            'price' => $item->total_amount ?? 0,
                            'license' => $item->quantity ?? 0,
                            'start_date' => $startDate,
                            'end_date' => $endDate,
                            'period' => $period,
                            'enrollment_type' => $enrollmentType,
                        ], $statusLabel, $link);
                    }

                    return $orderItems->flatMap(function ($oi) use (
                        $item,
                        $rawOrderStatus,
                        $rawCategory,
                        $parentOrderId,
                        $wasLaterRenewed,
                        $startDate,
                        $endDate,
                        $period,
                        $enrollmentType,
                        $orderItems,    
                        $domainHistoryLinks
                    ) {
                        $itemStatus = strtolower(trim((string) ($oi->status ?? '')));
                        // Prefer plan-line terminal status so old parent plans show as Upgraded/etc.
                        $statusForLabel = in_array($itemStatus, [
                            'upgraded',
                            'partially_upgraded',
                            'partial_upgrade',
                            'downgraded',
                            'partially_downgraded',
                            'renewed',
                            'partially_renewed',
                            'cancelled',
                            'canceled',
                            'partially_cancelled',
                            'rejected',
                            'failed',
                        ], true)
                            ? $itemStatus
                            : $rawOrderStatus;
                        $categoryForLabel = $rawCategory;
                        if (str_contains($itemStatus, 'upgraded') || str_contains($itemStatus, 'upgrade')) {
                            $categoryForLabel = 'upgraded';
                        } elseif (str_contains($itemStatus, 'downgraded') || str_contains($itemStatus, 'downgrade')) {
                            $categoryForLabel = 'downgraded';
                        } elseif (str_contains($itemStatus, 'renewed') || str_contains($itemStatus, 'renew')) {
                            $categoryForLabel = 'renewed';
                        }

                        // Only this plan line is Renewed â€” not every sibling on the parent
                        // just because some child order exists (upgrade used to trigger that).
                        $lineWasLaterRenewed = $itemStatus === 'renewed'
                            || (
                                $wasLaterRenewed
                                && $orderItems->count() === 1
                                && !in_array($itemStatus, ['upgraded', 'downgraded'], true)
                            );

                        $linePrice = $oi->total_amount
                            ?? $oi->subtotal
                            ?? $oi->amount
                            ?? null;
                        if ($linePrice === null) {
                            $linePrice = $item->total_amount ?? 0;
                        }

                        $statusLabel = $this->formatDomainHistoryStatusLabel(
                            $statusForLabel,
                            $categoryForLabel,
                            $parentOrderId,
                            $lineWasLaterRenewed
                        );
                        $link = $domainHistoryLinks['by_order_sub_id'][(int) $oi->id] ?? null;
                        // Prefer line-level link only. Order-level fallback wrongly labels
                        // sibling Active plans as Upgraded when only 1 of N was changed.
                        if ($link === null && $orderItems->count() === 1) {
                            $link = $domainHistoryLinks['by_order_id'][(int) $item->id] ?? null;
                        }

                        return $this->expandDomainHistoryRows([
                            'id' => $item->id,
                            'order_id'=>$item->id,
                            'order_sub_id' => $oi->id ?? null,
                            'plan_id'=>$item->plan_id,
                            'partner_id' => $item->partner_id,
                            'order_no' => $item->order_no ?? null,
                            'order_status' => $rawOrderStatus !== '' ? $rawOrderStatus : null,
                            'order_category' => $rawCategory !== '' ? $rawCategory : 'new',
                            'plan_name' => optional($oi->plan)->name
                                ?? optional($item->plan)->name
                                ?? '-',
                            'price' => $linePrice,
                            'license' => $oi->quantity ?? $item->quantity ?? 0,
                            'start_date' => $startDate,
                            'end_date' => $endDate,
                            'period' => $period,
                            'enrollment_type' => $enrollmentType,
                        ], $statusLabel, $link);
                    })->values()->all();
                })->sort(function ($a, $b) {
                    $sortA = (int) ($a['history_sort'] ?? $a['id'] ?? 0);
                    $sortB = (int) ($b['history_sort'] ?? $b['id'] ?? 0);
                    if ($sortA !== $sortB) {
                        return $sortB <=> $sortA;
                    }
                    $fromA = (($a['change_relation'] ?? '') === 'from') ? 1 : 0;
                    $fromB = (($b['change_relation'] ?? '') === 'from') ? 1 : 0;
                    if ($fromA !== $fromB) {
                        return $fromB <=> $fromA;
                    }

                    return (int) ($b['id'] ?? 0) <=> (int) ($a['id'] ?? 0);
                })->map(function ($row) {
                    unset($row['history_sort']);

                    return $row;
                })->values(),
            ];
        })->values();

        // search (any text field: order no, plan, status, period ...) + pagination on each domain's history rows.
        // Pagination applies only when page_no / per_page is sent, so existing callers still get the full history.
        $search = mb_strtolower(trim((string) $request->input('search', '')));
        $paginate = $request->filled('per_page') || $request->filled('page_no') || $request->filled('page');
        $pageNo = max(1, (int) $request->input('page_no', $request->input('page', 1)));
        $groupedData = $groupedData->map(function ($group) use ($search, $paginate, $pageNo, $request) {
            $rows = collect($group['history']);
            if ($search !== '') {
                $rows = $rows->filter(fn ($row) => str_contains(
                    mb_strtolower(implode(' ', array_filter((array) $row, fn ($v) => is_string($v) || is_numeric($v)))),
                    $search
                ))->values();
            }
            $total = $rows->count();
            $perPage = $paginate ? max(1, min(100, (int) $request->input('per_page', 10))) : max(1, $total);
            $page = $paginate ? $pageNo : 1;
            $group['history'] = $rows->forPage($page, $perPage)->values();
            $group['pagination'] = [
                'total' => $total,
                'per_page' => $perPage,
                'current_page' => $page,
                'last_page' => max(1, (int) ceil($total / $perPage)),
                'from' => $group['history']->isEmpty() ? null : ($page - 1) * $perPage + 1,
                'to' => $group['history']->isEmpty() ? null : ($page - 1) * $perPage + $group['history']->count(),
            ];

            return $group;
        })->values();

        return response()->json([
            'success' => true,
            'message' => 'Domain history fetched successfully',
            'total_domains' => $groupedData->count(),
            'data' => $groupedData,
        ]);
    }

    
    private function formatDomainHistoryStatusLabel(
        string $rawStatus,
        string $rawCategory,
        int $parentOrderId = 0,
        bool $wasLaterRenewed = false
    ): string {
        if (in_array($rawStatus, ['rejected', 'cancelled', 'canceled', 'failed'], true)) {
            return 'Cancelled';
        }
        if (in_array($rawCategory, ['license_add', 'addon'], true)) {
            if (in_array($rawStatus, ['pending', 'processing'], true)) {
                return 'License Add Pending';
            }
            if ($rawStatus === 'draft') {
                return 'Draft';
            }

            return 'License Added';
        }
        if (in_array($rawStatus, ['pending', 'processing', 'draft'], true)) {
            if ($rawCategory === 'upgrade') {
                return 'Upgrade Pending';
            }
            if ($rawCategory === 'downgrade') {
                return 'Downgrade Pending';
            }
            if (in_array($rawCategory, ['renewal', 'renew'], true) && $rawStatus !== 'draft') {
                return 'Renewal Pending';
            }

            return $rawStatus === 'draft' ? 'Draft' : ($rawStatus === 'pending' ? 'Pending' : 'Processing');
        }
        if ($rawCategory === 'renewed' || $wasLaterRenewed || $rawStatus === 'renewed') {
            return 'Renewed';
        }
        if (in_array($rawCategory, ['renewal', 'renew'], true)) {
            return in_array($rawStatus, ['completed', 'paid', 'success', 'active'], true) ? 'Active' : 'Renewal';
        }
        if (in_array($rawCategory, ['upgrade', 'partial_upgrade'], true)) {
            return in_array($rawStatus, ['completed', 'paid', 'success', 'active'], true) ? 'Active' : ($rawCategory === 'partial_upgrade' ? 'Partial Upgrade' : 'Upgrade');
        }
        if (in_array($rawCategory, ['upgraded', 'partially_upgraded'], true) || in_array($rawStatus, ['upgraded', 'partially_upgraded'], true)) {
            return 'Upgraded';
        }
        if (in_array($rawCategory, ['downgrade', 'partial_downgrade'], true)) {
            return in_array($rawStatus, ['completed', 'paid', 'success', 'active'], true) ? 'Active' : ($rawCategory === 'partial_downgrade' ? 'Partial Downgrade' : 'Downgrade');
        }
        if (in_array($rawCategory, ['downgraded', 'partially_downgraded'], true) || in_array($rawStatus, ['downgraded', 'partially_downgraded'], true)) {
            return 'Downgraded';
        }
        // Parent-linked child with no clear category: treat as renewal only when not an upgrade/downgrade/license-add.
        if (
            $parentOrderId > 0
            && !in_array($rawCategory, [
                'upgrade',
                'downgrade',
                'upgraded',
                'downgraded',
                'license_add',
                'addon',
                'partial_upgrade',
                'partial_downgrade',
                'partially_upgraded',
                'partially_downgraded',
            ], true)
        ) {
            return 'Renewal';
        }

        if (in_array($rawStatus, ['completed', 'paid', 'success', 'active'], true)) {
            return 'Active';
        }

        return 'New Subscription';
    }

    /**
     * Map source / target plan lines for domain history "upgraded to / from" labels.
     *
     * @return array{
     *   by_order_sub_id: array<int, array<string, mixed>>,
     *   by_order_id: array<int, array<string, mixed>>
     * }
     */
    private function buildDomainHistoryPlanChangeLinks(
        $historyOrders,
        $childChangeOrdersByParent,
        $childOrderItems,
        $newPlansById
    ): array {
        $byOrderSubId = [];
        $byOrderId = [];
        $sourcePlanIds = [];
        $sourceSubIds = [];
        $missingNewPlanIds = [];

        // Oldest first so a leftover source line keeps every change in order
        // (plan upgrade, then a later same-plan license change) instead of
        // only the newest child overwriting the badge.
        $allChildren = collect($childChangeOrdersByParent ?? [])
            ->flatten(1)
            ->filter()
            ->sortBy(fn($row) => (int) ($row->id ?? 0))
            ->values();
        foreach ($allChildren as $childOrder) {
            $childItems = collect($childOrderItems->get((int) $childOrder->id) ?? []);
            // groupBy may stringify keys
            if ($childItems->isEmpty()) {
                $childItems = collect($childOrderItems->get((string) (int) $childOrder->id) ?? []);
            }
            $childItemModel = $childItems->first();
            $childMeta = is_array($childItemModel->meta ?? null) ? $childItemModel->meta : [];
            foreach (
                [
                    (int) ($childOrder->parent_order_sub_id ?? 0),
                    (int) ($childItemModel->previous_order_sub_id ?? 0),
                    (int) ($childMeta['previous_order_sub_id'] ?? 0),
                ] as $sid
            ) {
                if ($sid > 0) {
                    $sourceSubIds[] = $sid;
                }
            }
            $oldPlanId = (int) ($childMeta['old_plan_id'] ?? $childOrder->previous_plan_id ?? 0);
            if ($oldPlanId > 0) {
                $sourcePlanIds[] = $oldPlanId;
            }
            $newPlanId = (int) ($childItemModel->plan_id ?? $childOrder->plan_id ?? 0);
            if ($newPlanId > 0 && !$newPlansById->has($newPlanId)) {
                $missingNewPlanIds[] = $newPlanId;
            }
        }

        $sourceItemsById = $sourceSubIds !== []
            ? OrderItem::query()
            ->with('plan:id,name')
            ->whereIn('id', array_values(array_unique($sourceSubIds)))
            ->get()
            ->keyBy('id')
            : collect();

        $sourcePlansById = $sourcePlanIds !== []
            ? Plan::query()->whereIn('id', array_values(array_unique($sourcePlanIds)))->get()->keyBy('id')
            : collect();

        if ($missingNewPlanIds !== []) {
            $extraPlans = Plan::query()
                ->whereIn('id', array_values(array_unique($missingNewPlanIds)))
                ->get()
                ->keyBy('id');
            $newPlansById = $newPlansById->union($extraPlans);
        }

        foreach ($allChildren as $childOrder) {
            $childId = (int) $childOrder->id;
            $childStatus = strtolower(trim((string) ($childOrder->status ?? '')));
            if (!in_array($childStatus, ['completed', 'paid', 'success', 'active', 'pending', 'processing'], true)) {
                continue;
            }

            // Prefer price/prefix inference so CH downgrades aren't labeled as upgrades.
            $inferredKind = $this->partnerPlanChangeOrderKind($childOrder);
            $changeCategory = strtolower(trim((string) ($childOrder->order_category ?? '')));
            if ($this->isLicenseAddOrder($childOrder) || in_array($changeCategory, ['license_add', 'addon'], true)) {
                $changeType = 'license_add';
            } elseif ($inferredKind === 'renewal' || $this->isRenewalChangeOrder($childOrder)) {
                $changeType = 'renewal';
            } elseif (
                $inferredKind === 'downgrade'
                || in_array($changeCategory, ['downgrade', 'downgraded'], true)
            ) {
                $changeType = 'downgrade';
            } elseif (
                $inferredKind === 'upgrade'
                || in_array($changeCategory, ['upgrade', 'upgraded'], true)
            ) {
                $changeType = 'upgrade';
            } else {
                $changeType = 'upgrade';
            }

            $childItems = collect($childOrderItems->get($childId) ?? []);
            if ($childItems->isEmpty()) {
                $childItems = collect($childOrderItems->get((string) $childId) ?? []);
            }
            $childItemModel = $childItems->first();
            $childMeta = is_array($childItemModel->meta ?? null) ? $childItemModel->meta : [];
            $newPlanId = (int) ($childItemModel->plan_id ?? $childOrder->plan_id ?? 0);
            $newPlanName = trim((string) (
                optional($newPlansById->get($newPlanId))->name
                ?? optional(optional($childItemModel)->plan)->name
                ?? $childOrder->plan_name
                ?? ''
            ));
            if ($newPlanName === '' && $newPlanId > 0) {
                $newPlanName = trim((string) (optional(Plan::query()->find($newPlanId))->name ?? ''));
            }

            $candidateSourceIds = array_values(array_unique(array_filter([
                (int) ($childOrder->parent_order_sub_id ?? 0),
                (int) ($childItemModel->previous_order_sub_id ?? 0),
                (int) ($childMeta['previous_order_sub_id'] ?? 0),
            ])));

            $oldPlanId = (int) ($childMeta['old_plan_id'] ?? $childOrder->previous_plan_id ?? 0);
            $oldPlanName = '';
            if ($candidateSourceIds !== []) {
                $src = $sourceItemsById->get($candidateSourceIds[0]);
                $oldPlanName = (string) (optional(optional($src)->plan)->name ?? '');
                if ($oldPlanId <= 0) {
                    $oldPlanId = (int) (optional($src)->plan_id ?? 0);
                }
            }
            if ($oldPlanName === '' && $oldPlanId > 0) {
                $oldPlanName = (string) (optional($sourcePlansById->get($oldPlanId))->name ?? '');
            }

            // Fallback: match source line on parent by status / old_plan_id.
            $parentOrderId = (int) ($childOrder->parent_order_id ?? 0);
            if ($candidateSourceIds === [] && $parentOrderId > 0) {
                $parentOrder = collect($historyOrders)->firstWhere('id', $parentOrderId);
                $parentItems = collect(optional($parentOrder)->items ?? []);
                $terminalStatus = $changeType === 'downgrade'
                    ? 'downgraded'
                    : ($changeType === 'renewal' ? 'renewed' : 'upgraded');

                $replaced = $parentItems->filter(function ($oi) use ($oldPlanId, $terminalStatus) {
                    $st = strtolower(trim((string) ($oi->status ?? '')));
                    $planMatch = $oldPlanId <= 0 || (int) $oi->plan_id === $oldPlanId;
                    if ($st === $terminalStatus && $planMatch) {
                        return true;
                    }
                    // Pending change: source line may still be active.
                    if (
                        $oldPlanId > 0
                        && (int) $oi->plan_id === $oldPlanId
                        && in_array($st, ['', 'active', 'completed', 'paid', 'success'], true)
                    ) {
                        return true;
                    }

                    return false;
                });

                if ($replaced->isEmpty() && $oldPlanId > 0) {
                    $replaced = $parentItems->filter(
                        fn($oi) => (int) ($oi->plan_id ?? 0) === $oldPlanId
                    );
                }
                if ($replaced->isEmpty() && $parentItems->count() === 1) {
                    $replaced = $parentItems;
                }

                if ($replaced->count() >= 1) {
                    $src = $replaced->first();
                    $candidateSourceIds[] = (int) $src->id;
                    if ($oldPlanName === '') {
                        $oldPlanName = (string) (optional($src->plan)->name ?? '');
                    }
                    if ($oldPlanId <= 0) {
                        $oldPlanId = (int) ($src->plan_id ?? 0);
                    }
                }
            }

            $toLicenses = max(1, (int) (
                $childItems->sum(fn($row) => max(1, (int) ($row->quantity ?? 1)))
                ?: ($childOrder->quantity ?? 1)
            ));
            $fromLicenses = 0;
            $samePlanLicenseChange = false;
            $childIsPending = in_array($childStatus, ['pending', 'processing', 'draft'], true);
            if ($candidateSourceIds !== []) {
                $srcForQty = $sourceItemsById->get($candidateSourceIds[0]);
                if ($srcForQty) {
                    $srcQtyNow = max(1, (int) ($srcForQty->quantity ?? 1));
                    $srcPlanId = (int) ($srcForQty->plan_id ?? 0);
                    $srcStatus = strtolower(trim((string) ($srcForQty->status ?? 'active')));
                    if ($srcStatus === '') {
                        $srcStatus = 'active';
                    }
                    $samePlan = $srcPlanId > 0 && $newPlanId > 0 && $srcPlanId === $newPlanId;
                    $fullyReplaced = in_array($srcStatus, [
                        'upgraded',
                        'downgraded',
                        'renewed',
                        'partially_upgraded',
                        'partial_upgrade',
                        'partially_downgraded',
                        'partially_renewed'
                    ], true);

                    $metaOldQty = (int) ($childMeta['old_quantity'] ?? $childMeta['old_licenses'] ?? $childMeta['previous_quantity'] ?? 0);

                    if ($metaOldQty > 0) {
                        $fromLicenses = $metaOldQty;
                    } else {
                        // The source order item is immutable, so its quantity represents the original total quantity.
                        $fromLicenses = $srcQtyNow;
                    }

                    $samePlanLicenseChange = $samePlan
                        && $fromLicenses > 0
                        && $fromLicenses !== $toLicenses;

                    if ($changeType === 'license_add') {
                        $addedLicenses = max(1, $toLicenses);
                        $fromLicenses = $srcQtyNow;
                        $toLicenses = $fromLicenses + $addedLicenses;
                        $samePlanLicenseChange = true;
                    }
                }
            }
            if ($fromLicenses <= 0) {
                $fromLicenses = $toLicenses;
            }

            $toLink = [
                'change_type' => $changeType,
                'change_relation' => 'to',
                'related_plan_id' => $newPlanId > 0 ? $newPlanId : null,
                'related_plan_name' => $newPlanName !== '' ? $newPlanName : null,
                'from_licenses' => $fromLicenses,
                'to_licenses' => $toLicenses,
                'same_plan_license_change' => $samePlanLicenseChange,
                'child_order_id' => $childId,
            ];
            $fromLink = [
                'change_type' => $changeType,
                'change_relation' => 'from',
                'related_plan_id' => $oldPlanId > 0 ? $oldPlanId : null,
                'related_plan_name' => $oldPlanName !== '' ? $oldPlanName : null,
                'from_licenses' => $fromLicenses,
                'to_licenses' => $toLicenses,
                'same_plan_license_change' => $samePlanLicenseChange,
                'child_order_id' => $childId,
            ];

            foreach ($candidateSourceIds as $sourceSubId) {
                $this->appendDomainHistorySourceLink($byOrderSubId, (int) $sourceSubId, $toLink);
            }

            if ($childItemModel && (int) ($childItemModel->id ?? 0) > 0) {
                $byOrderSubId[(int) $childItemModel->id] = $fromLink;
            }
            if (!isset($byOrderId[$childId])) {
                $byOrderId[$childId] = $fromLink;
            }
            // Parent-level "to" link only for single-plan parents â€” multi-plan uses by_order_sub_id
            // so sibling Active lines are not labeled Upgraded.
            if ($parentOrderId > 0 && $newPlanName !== '' && !isset($byOrderId[$parentOrderId])) {
                $parentOrder = collect($historyOrders)->firstWhere('id', $parentOrderId);
                $parentItemCount = collect(optional($parentOrder)->items ?? [])
                    ->filter(function ($oi) {
                        $st = strtolower(trim((string) ($oi->status ?? '')));
                        return !in_array($st, ['delete', 'deleted'], true);
                    })
                    ->count();
                if ($parentItemCount <= 1) {
                    $byOrderId[$parentOrderId] = $toLink;
                }
            } elseif ($parentOrderId > 0 && $candidateSourceIds === [] && !isset($byOrderId[$parentOrderId])) {
                $parentOrder = collect($historyOrders)->firstWhere('id', $parentOrderId);
                $parentItemCount = collect(optional($parentOrder)->items ?? [])->count();
                if ($parentItemCount <= 1) {
                    $byOrderId[$parentOrderId] = $toLink;
                }
            }
        }

        return [
            'by_order_sub_id' => $byOrderSubId,
            'by_order_id' => $byOrderId,
        ];
    }

    /**
     * Keep every child change on a leftover source line (plan upgrade then later seat change).
     */
    private function appendDomainHistorySourceLink(array &$byOrderSubId, int $sourceSubId, array $toLink): void
    {
        if ($sourceSubId <= 0) {
            return;
        }

        if (!isset($byOrderSubId[$sourceSubId])) {
            $byOrderSubId[$sourceSubId] = $toLink;
            $byOrderSubId[$sourceSubId]['events'] = [$toLink];

            return;
        }

        $events = $byOrderSubId[$sourceSubId]['events'] ?? [$byOrderSubId[$sourceSubId]];
        foreach ($events as $existing) {
            if (
                (string) ($existing['change_type'] ?? '') === (string) ($toLink['change_type'] ?? '')
                && (int) ($existing['related_plan_id'] ?? 0) === (int) ($toLink['related_plan_id'] ?? 0)
                && (int) ($existing['from_licenses'] ?? 0) === (int) ($toLink['from_licenses'] ?? 0)
                && (int) ($existing['to_licenses'] ?? 0) === (int) ($toLink['to_licenses'] ?? 0)
                && (bool) ($existing['same_plan_license_change'] ?? false) === (bool) ($toLink['same_plan_license_change'] ?? false)
            ) {
                return;
            }
        }

        $events[] = $toLink;
        $merged = $toLink;
        $merged['events'] = $events;
        $byOrderSubId[$sourceSubId] = $merged;
    }

    /**
     * @return array<int, array<string, mixed>>
     */
    private function domainHistoryLinkEvents(?array $link): array
    {
        if ($link === null) {
            return [];
        }

        $events = $link['events'] ?? null;
        if (is_array($events) && $events !== []) {
            return array_values($events);
        }

        return [$link];
    }

    /**
     * One history card per leftover change (latest child first).
     *
     * @return array<int, array<string, mixed>>
     */
    private function expandDomainHistoryRows(array $base, string $statusLabel, ?array $link): array
    {
        $events = $this->domainHistoryLinkEvents($link);
        if ($events === []) {
            $events = [null];
        } else {
            usort(
                $events,
                fn($a, $b) => (int) ($b['child_order_id'] ?? 0) <=> (int) ($a['child_order_id'] ?? 0)
            );
        }

        $rows = [];
        foreach ($events as $index => $event) {
            $eventLink = is_array($event) ? $event : null;
            if (is_array($eventLink)) {
                unset($eventLink['events']);
            }

            $childId = (int) ($eventLink['child_order_id'] ?? 0);
            $orderId = (int) ($base['id'] ?? 0);
            $row = $base;
            $row['status'] = $this->formatDomainHistoryStatusWithPlanLink($statusLabel, $eventLink);
            $row['status_label'] = $statusLabel;
            $row['status_detail'] = $this->formatDomainHistoryStatusDetail($statusLabel, $eventLink);
            $row['status_events'] = $this->formatDomainHistoryStatusEvents($statusLabel, $eventLink);
            $row['related_plan_name'] = $eventLink['related_plan_name'] ?? null;
            $row['related_plan_id'] = $eventLink['related_plan_id'] ?? null;
            $row['change_type'] = $eventLink['change_type'] ?? null;
            $row['change_relation'] = $eventLink['change_relation'] ?? null;
            $row['from_licenses'] = isset($eventLink['from_licenses']) ? (int) $eventLink['from_licenses'] : null;
            $row['to_licenses'] = isset($eventLink['to_licenses']) ? (int) $eventLink['to_licenses'] : null;

            $relation = (string) ($eventLink['change_relation'] ?? '');
            if ($relation === 'to' && $row['from_licenses'] > 0 && $row['to_licenses'] > 0 && $row['from_licenses'] > $row['to_licenses']) {
                $row['license'] = $row['from_licenses'] - $row['to_licenses'];
            }

            $row['same_plan_license_change'] = (bool) ($eventLink['same_plan_license_change'] ?? false);
            $row['child_order_id'] = $childId > 0 ? $childId : null;
            $row['history_key'] = $orderId . '-' . (int) ($base['order_sub_id'] ?? 0) . '-' . $childId . '-' . $index;
            $row['history_sort'] = $childId > 0 ? $childId : $orderId;
            $rows[] = $row;
        }

        return $rows;
    }

    /**
     * Badge text: "Licenses upgraded from 1 to 2" / "Upgraded to Plan X".
     */
    private function formatDomainHistoryStatusWithPlanLink(string $statusLabel, ?array $link): string
    {
        if ($link === null) {
            return $statusLabel;
        }

        return $this->formatOneDomainHistoryStatusWithPlanLink($statusLabel, $link);
    }

    /**
     * @return array<int, string>
     */
    private function formatDomainHistoryStatusEvents(string $statusLabel, ?array $link): array
    {
        if ($link === null) {
            return [];
        }

        $parts = [];
        foreach ($this->domainHistoryLinkEvents($link) as $event) {
            $part = $this->formatOneDomainHistoryStatusWithPlanLink($statusLabel, $event);
            if ($part === '' || $part === $statusLabel || in_array($part, $parts, true)) {
                continue;
            }
            $parts[] = $part;
        }

        return $parts;
    }

    private function formatOneDomainHistoryStatusWithPlanLink(string $statusLabel, array $link): string
    {
        $licenseLabel = $this->formatDomainHistoryLicenseChangeLabel($statusLabel, $link);
        if ($licenseLabel !== null) {
            return $licenseLabel;
        }

        $related = trim((string) ($link['related_plan_name'] ?? ''));
        if ($related === '') {
            return $statusLabel;
        }

        $relation = (string) ($link['change_relation'] ?? '');
        $changeType = (string) ($link['change_type'] ?? '');

        if ($relation === 'to') {
            if (strcasecmp($statusLabel, 'Downgraded') === 0 || $changeType === 'downgrade') {
                return $this->appendLicenseChangeToPlanLabel('Downgraded to ' . $related, $link);
            }
            if (strcasecmp($statusLabel, 'Renewed') === 0 || $changeType === 'renewal') {
                return $this->appendLicenseChangeToPlanLabel('Renewed to ' . $related, $link);
            }
            if (strcasecmp($statusLabel, 'Upgraded') === 0 || $changeType === 'upgrade') {
                return $this->appendLicenseChangeToPlanLabel('Upgraded to ' . $related, $link);
            }
        }

        if ($relation === 'from') {
            if (in_array($statusLabel, ['Active', 'Upgrade Pending', 'Downgrade Pending', 'Renewal Pending'], true)) {
                return $statusLabel;
            }
        }

        return $statusLabel;
    }

    /**
     * Partial / same-plan license change — only on the OLD source line (relation=to).
     * New CH child (relation=from) stays Active / Upgrade Pending.
     */
    private function formatDomainHistoryLicenseChangeLabel(string $statusLabel, array $link): ?string
    {
        $fromLicenses = (int) ($link['from_licenses'] ?? 0);
        $toLicenses = (int) ($link['to_licenses'] ?? 0);
        if ($fromLicenses <= 0 || $toLicenses <= 0 || $fromLicenses === $toLicenses) {
            return null;
        }

        $relation = (string) ($link['change_relation'] ?? '');
        // New CH / RN row must stay Active (or Pending) — never rewrite as "upgraded from".
        if ($relation === 'from') {
            return null;
        }
        // Only the old source line (relation=to).
        if ($relation !== 'to') {
            return null;
        }

        $changeType = (string) ($link['change_type'] ?? 'upgrade');
        $samePlan = !empty($link['same_plan_license_change']);

        // License-only badge is for SAME plan seat changes.
        // Plan upgrade (Silver → Platinum) must say "Upgraded to {plan}", not "Licenses upgraded from X to Y".
        if (!$samePlan) {
            return null;
        }

        if ($changeType === 'downgrade' || strcasecmp($statusLabel, 'Downgraded') === 0) {
            return 'Licenses downgraded from ' . $fromLicenses . ' to ' . $toLicenses;
        }
        if ($changeType === 'renewal' || strcasecmp($statusLabel, 'Renewed') === 0) {
            return 'Licenses renewed from ' . $fromLicenses . ' to ' . $toLicenses;
        }
        if ($changeType === 'upgrade' || strcasecmp($statusLabel, 'Upgraded') === 0) {
            return 'Licenses upgraded from ' . $fromLicenses . ' to ' . $toLicenses;
        }

        return null;
    }

    /**
     * When the plan changed and seats also changed: "Upgraded to Platinum (1 → 2 licenses)".
     */
    private function appendLicenseChangeToPlanLabel(string $label, array $link): string
    {
        $fromLicenses = (int) ($link['from_licenses'] ?? 0);
        $toLicenses = (int) ($link['to_licenses'] ?? 0);
        if ($fromLicenses <= 0 || $toLicenses <= 0 || $fromLicenses === $toLicenses) {
            return $label;
        }

        return $label . ' (' . $fromLicenses . ' → ' . $toLicenses . ' licenses)';
    }

    /**
     * Full sentence for UI subtitle / tooltip (all domains).
     */
    private function formatDomainHistoryStatusDetail(string $statusLabel, ?array $link): ?string
    {
        if ($link === null) {
            return null;
        }

        $parts = [];
        foreach ($this->domainHistoryLinkEvents($link) as $event) {
            $part = $this->formatOneDomainHistoryStatusDetail($statusLabel, $event);
            if ($part === null || $part === '' || in_array($part, $parts, true)) {
                continue;
            }
            $parts[] = $part;
        }

        return $parts === [] ? null : implode('; ', $parts);
    }

    private function formatOneDomainHistoryStatusDetail(string $statusLabel, array $link): ?string
    {
        $fromLicenses = (int) ($link['from_licenses'] ?? 0);
        $toLicenses = (int) ($link['to_licenses'] ?? 0);
        $samePlan = !empty($link['same_plan_license_change']);
        $changeType = (string) ($link['change_type'] ?? 'upgrade');
        $relation = (string) ($link['change_relation'] ?? '');

        // New order stays Active — license story belongs on the old source row only.
        if ($relation === 'from') {
            if (in_array($statusLabel, ['Active', 'Upgrade Pending', 'Downgrade Pending', 'Renewal Pending'], true)) {
                return null;
            }
        }

        if (
            $relation === 'to'
            && $samePlan
            && $fromLicenses > 0
            && $toLicenses > 0
            && $fromLicenses !== $toLicenses
        ) {
            if ($changeType === 'downgrade') {
                return 'Licenses were downgraded from ' . $fromLicenses . ' to ' . $toLicenses;
            }
            if ($changeType === 'renewal') {
                return 'Licenses were renewed from ' . $fromLicenses . ' to ' . $toLicenses;
            }

            return 'Licenses were upgraded from ' . $fromLicenses . ' to ' . $toLicenses;
        }

        $related = trim((string) ($link['related_plan_name'] ?? ''));
        if ($related === '') {
            return null;
        }

        $isPartial = ($fromLicenses > 0 && $toLicenses > 0 && $fromLicenses > $toLicenses);

        if ($relation === 'to') {
            if ($changeType === 'downgrade' || strcasecmp($statusLabel, 'Downgraded') === 0) {
                return 'This plan was ' . ($isPartial ? 'partially downgraded' : 'downgraded') . ' to ' . $related . ($fromLicenses > 0 && $toLicenses > 0 && $fromLicenses !== $toLicenses ? ' (licenses ' . $fromLicenses . ' → ' . $toLicenses . ')' : '');
            }
            if ($changeType === 'renewal' || strcasecmp($statusLabel, 'Renewed') === 0) {
                return 'This plan was ' . ($isPartial ? 'partially renewed' : 'renewed') . ' to ' . $related . ($fromLicenses > 0 && $toLicenses > 0 && $fromLicenses !== $toLicenses ? ' (licenses ' . $fromLicenses . ' → ' . $toLicenses . ')' : '');
            }

            $detail = 'This plan was ' . ($isPartial ? 'partially upgraded' : 'upgraded') . ' to ' . $related;
            if ($fromLicenses > 0 && $toLicenses > 0 && $fromLicenses !== $toLicenses) {
                $detail .= ' (licenses ' . $fromLicenses . ' → ' . $toLicenses . ')';
            }

            return $detail;
        }

        if ($relation === 'from') {
            if ($changeType === 'downgrade') {
                return ($isPartial ? 'Partially downgraded' : 'Downgraded') . ' from ' . $related;
            }
            if ($changeType === 'renewal') {
                return ($isPartial ? 'Partially renewed' : 'Renewed') . ' from ' . $related;
            }

            return ($isPartial ? 'Partially upgraded' : 'Upgraded') . ' from ' . $related;
        }

        return null;
    }

    public function renewalsindex(Request $request)
    {
        $partnerId = $request->input('partner_id');

        if (!$partnerId) {
            return response()->json([
                'success' => false,
                'message' => 'partner_id is required in request body',
            ], 422);
        }

        $today = \Carbon\Carbon::now()->startOfDay();

        // Default days = 30
        $days = $request->input('days', 30);
        $days = is_numeric($days) ? (int) $days : 30;
        if ($days < 0) $days = 0;

        $filterDaysLeftRaw = $request->get('filter_days_left', '');
        $filterDaysLeftExact = ($filterDaysLeftRaw !== '' && is_numeric($filterDaysLeftRaw))
            ? (int) $filterDaysLeftRaw
            : null;

        if ($filterDaysLeftExact !== null && $filterDaysLeftExact > $days) {
            $days = $filterDaysLeftExact;
        }

        $renewalThreshold = $today->copy()->addDays($days)->endOfDay();

        $search    = $request->input('search');
        $requestId = $request->input('request_id');

        // Plan fields safe selection
        $planSelectFields = ['id', 'name', 'title'];

        if (\Schema::hasColumn('plans', 'provider_id')) {
            $planSelectFields[] = 'provider_id';
        }

        $ordersQuery = Order::with([
            'plan' => function ($query) use ($planSelectFields) {
                $query->select($planSelectFields);
            },
            'customer.partner:id,name',
            'customer:id,name,email,mobile,partner_id'
        ])
            ->where('partner_id', $partnerId)
            ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('draft', 'cancelled', 'canceled', 'rejected', 'failed', 'void')")
            ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) IN ('completed', 'active', 'paid', 'success', 'upgraded', 'downgraded', 'renewed')")
            ->where(function ($q) use ($renewalThreshold) {
                $q->where(function ($q2) use ($renewalThreshold) {
                    $q2->whereNotNull('subscription_end_date')
                        ->where('subscription_end_date', '<=', $renewalThreshold);
                })->orWhere(function ($q2) use ($renewalThreshold) {
                    $q2->whereNull('subscription_end_date')
                        ->whereExists(function ($sub) use ($renewalThreshold) {
                            $sub->selectRaw('1')
                                ->from('order_items')
                                ->whereColumn('order_items.order_id', 'orders.id')
                                ->whereNotNull('subscription_end_date')
                                ->where('subscription_end_date', '<=', $renewalThreshold);
                        });
                });
            });

        if (\Schema::connection('pgsql_billing')->hasColumn('orders', 'order_type')) {
            $ordersQuery->where('order_type', 'b2b');
        }

        // Fully replaced parents are dropped in PHP when leftover qty is 0.
        // Do not SQL-exclude NULL / upgraded / renewed categories — leftover seats still renew.

        if (!empty($requestId)) {
            $ordersQuery->where('id', $requestId);
        }

        // search / provider_id / status / pagination are applied on the built rows below
        $orders = $ordersQuery->orderBy('subscription_end_date')->get();

        $orderIds = $orders->pluck('id')->map(fn($id) => (int) $id)->filter()->values()->all();
        $planChangeContext = $this->buildPlanChangeContextForOrders($orderIds);
        $orderItemMap = $orderIds !== []
            ? OrderItem::query()->whereIn('order_id', $orderIds)->get()->groupBy('order_id')
            : collect();

        // 2 plans + upgrade 1 → keep parent in renewals for leftover plan only.
        $orders = $orders->filter(function ($order) use ($planChangeContext, $orderItemMap) {
            $orderId = (int) $order->id;
            $orderItems = $this->uniqueSubscriptionOrderItems(
                $orderItemMap->get($orderId, collect())
            );
            if ($orderItems->isEmpty()) {
                return true;
            }

            $childChangeOrders = $planChangeContext['child_change_orders_by_parent']->get($orderId, collect());
            $upgradeStateBySourceSubId = $childChangeOrders->isEmpty()
                ? []
                : $this->buildUpgradeStateBySourceSubId(
                    $orderId,
                    $childChangeOrders,
                    $planChangeContext['child_order_items'],
                    $planChangeContext['new_plans_by_id']
                );

            $renewableCount = $orderItems->filter(function ($item) use (
                $upgradeStateBySourceSubId,
                $planChangeContext,
                $childChangeOrders
            ) {
                $itemStatus = strtolower(trim((string) ($item->status ?? 'active')));
                if ($itemStatus === '') {
                    $itemStatus = 'active';
                }
                if (in_array($itemStatus, ['upgraded', 'downgraded', 'renewed', 'delete',  'cancelled'], true)) {
                    return false;
                }

                $id = (int) ($item->id ?? 0);
                if ($id > 0 && isset($upgradeStateBySourceSubId[$id])) {
                    $moved = $this->resolveMovedLicensesForSourceLine(
                        $id,
                        $upgradeStateBySourceSubId,
                        $planChangeContext['child_order_items'],
                        $childChangeOrders
                    );
                    $lineQty = max(1, (int) ($item->quantity ?? 1));
                    $leftoverQty = $this->leftoverQtyAfterPlanChange(
                        $lineQty,
                        $moved,
                        $itemStatus,
                        $this->mappedChangeIsSamePlan($item, $upgradeStateBySourceSubId)
                    );

                    return $leftoverQty !== null && $leftoverQty > 0;
                }

                return true;
            })->count();

            return $renewableCount > 0;
        })->values();

        // License-add (addon) child orders renew with their parent subscription: fold their seats into the
        // parent row instead of listing the same subscription twice. Parent = parent_order_id, else same domain.
        $orderIdsInList = $orders->pluck('id')->map(fn ($id) => (int) $id)->flip();
        $parentIdByDomain = $orders->reject(fn ($o) => $this->isLicenseAddOrder($o))
            ->groupBy(fn ($o) => strtolower(trim((string) ($o->domain_name ?? ''))))
            ->map(fn ($group) => (int) $group->first()->id);
        $addonLicensesByParent = [];
        $orders = $orders->reject(function ($order) use ($orderIdsInList, $parentIdByDomain, $orderItemMap, &$addonLicensesByParent) {
            if (!$this->isLicenseAddOrder($order)) {
                return false;
            }
            $parentId = (int) ($order->parent_order_id ?? 0);
            if ($parentId <= 0 || !isset($orderIdsInList[$parentId])) {
                $parentId = (int) ($parentIdByDomain[strtolower(trim((string) ($order->domain_name ?? '')))] ?? 0);
            }
            if ($parentId <= 0 || $parentId === (int) $order->id) {
                return false;
            }
            $qty = (int) $orderItemMap->get((int) $order->id, collect())
                ->reject(fn ($i) => in_array(strtolower(trim((string) ($i->status ?? ''))), ['delete', 'deleted', 'cancelled', 'canceled'], true))
                ->sum(fn ($i) => max(0, (int) ($i->quantity ?? 0)));
            $addonLicensesByParent[$parentId] = ($addonLicensesByParent[$parentId] ?? 0) + ($qty ?: (int) ($order->quantity ?? 0));

            return true;
        })->values();

        // Provider mapping
        $providerIdNameMap = [];

        if (\Schema::hasColumn('plans', 'provider_id')) {
            $providerIds = $orders->pluck('plan.provider_id')->filter()->unique();

            if ($providerIds->count() > 0) {
                $providerIdNameMap = $this->provider->newQuery()
                    ->whereIn('id', $providerIds)
                    ->pluck('name', 'id')
                    ->toArray();
            }
        }

        $leftoverPlanIds = [];
        foreach ($orders as $order) {
            foreach ($orderItemMap->get((int) $order->id, collect()) as $item) {
                $s = strtolower(trim((string) ($item->status ?? 'active')));
                if ($s === '') {
                    $s = 'active';
                }
                if (!in_array($s, ['upgraded', 'downgraded', 'renewed', 'delete', 'deleted', 'cancelled', 'canceled'], true) && (int) ($item->plan_id ?? 0) > 0) {
                    $leftoverPlanIds[] = (int) $item->plan_id;
                }
            }
        }
        $leftoverPlanIds = array_values(array_unique($leftoverPlanIds));
        $leftoverPlanNameMap = $leftoverPlanIds !== []
            ? Plan::query()->whereIn('id', $leftoverPlanIds)->pluck('name', 'id')->toArray()
            : [];

        $now = \Carbon\Carbon::now()->startOfDay();

        $renewals = $orders->map(function ($order) use (
            $now,
            $providerIdNameMap,
            $orderItemMap,
            $planChangeContext,
            $leftoverPlanNameMap,
            $addonLicensesByParent
        ) {
            $renewalDate = $order->subscription_end_date
                ? \Carbon\Carbon::parse($order->subscription_end_date)->startOfDay()
                : null;
            if (!$renewalDate) {
                foreach ($orderItemMap->get((int) $order->id, collect()) as $item) {
                    if (empty($item->subscription_end_date)) {
                        continue;
                    }
                    try {
                        $itemEnd = \Carbon\Carbon::parse($item->subscription_end_date)->startOfDay();
                        if (!$renewalDate || $itemEnd->lt($renewalDate)) {
                            $renewalDate = $itemEnd;
                        }
                    } catch (\Throwable $e) {
                        // skip unparseable line dates
                    }
                }
            }

            $daysLeft = $renewalDate ? (int) $now->diffInDays($renewalDate, false) : 0;
            // Never expose negative days — expired subscriptions show 0 with status Expired
            $isExpired = $daysLeft <= 0;
            $daysLeftDisplay = $isExpired ? 0 : $daysLeft;

            $subscriptionStartDate = $order->subscription_start_date
                ? \Carbon\Carbon::parse($order->subscription_start_date)->format('Y-m-d')
                : '₹';

            $subscriptionEndDate = $renewalDate
                ? $renewalDate->format('Y-m-d')
                : ($order->subscription_end_date
                    ? \Carbon\Carbon::parse($order->subscription_end_date)->format('Y-m-d')
                    : '₹');

            $providerId = null;
            $providerName = '₹';

            if ($order->plan) {
                if (isset($order->plan->provider_id)) {
                    $providerId = $order->plan->provider_id;
                    $providerName = $providerIdNameMap[$providerId] ?? '₹';
                }
            }

            $orderId = (int) $order->id;
            $orderItems = $this->uniqueSubscriptionOrderItems(
                $orderItemMap->get($orderId, collect())
            );
            $childChangeOrders = $planChangeContext['child_change_orders_by_parent']->get($orderId, collect());
            $upgradeStateBySourceSubId = $childChangeOrders->isEmpty()
                ? []
                : $this->buildUpgradeStateBySourceSubId(
                    $orderId,
                    $childChangeOrders,
                    $planChangeContext['child_order_items'],
                    $planChangeContext['new_plans_by_id']
                );

            $leftoverItems = $orderItems->filter(function ($item) use (
                $upgradeStateBySourceSubId,
                $planChangeContext,
                $childChangeOrders
            ) {
                $itemStatus = strtolower(trim((string) ($item->status ?? 'active')));
                if ($itemStatus === '') {
                    $itemStatus = 'active';
                }
                if (in_array($itemStatus, ['upgraded', 'downgraded', 'renewed', 'delete', 'deleted', 'cancelled', 'canceled'], true)) {
                    return false;
                }
                $id = (int) ($item->id ?? 0);
                if ($id > 0 && isset($upgradeStateBySourceSubId[$id])) {
                    $moved = $this->resolveMovedLicensesForSourceLine(
                        $id,
                        $upgradeStateBySourceSubId,
                        $planChangeContext['child_order_items'],
                        $childChangeOrders
                    );
                    $lineQty = max(1, (int) ($item->quantity ?? 1));
                    $leftoverQty = $this->leftoverQtyAfterPlanChange(
                        $lineQty,
                        $moved,
                        $itemStatus,
                        $this->mappedChangeIsSamePlan($item, $upgradeStateBySourceSubId)
                    );

                    return $leftoverQty !== null && $leftoverQty > 0;
                }

                return true;
            })->values();

            $licenseCount = 0;
            $planNames = [];
            foreach ($leftoverItems as $item) {
                $id = (int) ($item->id ?? 0);
                $qty = max(0, (int) ($item->quantity ?? 0));
                if ($id > 0 && isset($upgradeStateBySourceSubId[$id])) {
                    $moved = $this->resolveMovedLicensesForSourceLine(
                        $id,
                        $upgradeStateBySourceSubId,
                        $planChangeContext['child_order_items'],
                        $childChangeOrders
                    );
                    if ($moved > 0 && $qty > $moved) {
                        $qty = $qty - $moved;
                    }
                }
                $licenseCount += $qty;
                $pid = (int) ($item->plan_id ?? 0);
                if ($pid > 0) {
                    $planNames[] = $leftoverPlanNameMap[$pid] ?? ('Plan #' . $pid);
                }
            }
            $planNames = array_values(array_unique($planNames));
            if ($licenseCount <= 0) {
                $licenseCount = (int) ($order->quantity ?? 0);
            }
            $licenseCount += $addonLicensesByParent[$orderId] ?? 0;

            $planLabel = $planNames !== []
                ? implode(', ', $planNames)
                : (optional($order->plan)->name
                    ?? optional($order->plan)->title
                    ?? ('Plan #' . $order->plan_id));

            $domainNames = [];
            $rawDomain = trim((string) ($order->domain_name ?? ''));
            if ($rawDomain !== '') {
                $domainNames = array_values(array_filter(array_map('trim', preg_split('/[,;\n]+/', $rawDomain))));
            }
            $company_name = $this->customer->where('id', $order->user_id)->first()->company_name ?? '';
           
            return [
                'order_id'                => $order->id,
                'order_no'                => $order->order_no ?? '-',
                'partner_id'              => $order->partner_id,
                'provider_id'             => $providerId,
                'provider_name'           => $providerName,
                'license_count'           => $licenseCount,
                'partner_name'            => optional($order->customer->partner)->name ?? '₹',
                'company_name'            => $company_name ?? '',
                'customer_name'           => optional($order->customer)->name ?? '₹',
                'email'                   => optional($order->customer)->email ?? '₹',
                'mobile'                  => optional($order->customer)->mobile ?? '₹',
                'domain'                  => $domainNames,
                'plan'                    => $planLabel,
                'subscription_start_date' => $subscriptionStartDate,
                'subscription_end_date'   => $subscriptionEndDate,
                'renewal_date'            => $renewalDate ? $renewalDate->format('Y-m-d') : '₹',
                'days_left'               => $daysLeftDisplay,
                'status'                  => $isExpired ? 'Expired' : 'Expiring',
                'is_urgent'               => !$isExpired && $daysLeftDisplay <= 10,
            ];
        })->values();

        // search: order no, domain, company, customer, email, mobile, plan (case-insensitive)
        $searchTerm = mb_strtolower(trim((string) $search));
        $providerFilter = (int) $request->input('provider_id', 0);
        $renewals = $renewals->filter(function ($row) use ($searchTerm, $providerFilter) {
            if ($providerFilter > 0 && (int) $row['provider_id'] !== $providerFilter) {
                return false;
            }
            if ($searchTerm === '') {
                return true;
            }
            $haystack = implode(' ', [
                $row['order_no'], implode(' ', $row['domain']), $row['company_name'],
                $row['customer_name'], $row['email'], $row['mobile'], $row['plan'],
            ]);

            return str_contains(mb_strtolower($haystack), $searchTerm);
        })->values();

        // Chip counts follow search/provider but not the status filter
        $counts = [
            ['key' => 'Expiring', 'value' => $renewals->where('status', 'Expiring')->count()],
            ['key' => 'Expired', 'value' => $renewals->where('status', 'Expired')->count()],
        ];

        $statusFilter = strtolower(trim((string) $request->input('status', '')));
        if (in_array($statusFilter, ['expiring', 'expired'], true)) {
            $renewals = $renewals->filter(fn ($row) => strtolower($row['status']) === $statusFilter)->values();
        }

        // Paginate only when page_no / per_page is sent, so older app builds still get the full list
        $total = $renewals->count();
        $paginate = $request->filled('per_page') || $request->filled('page_no') || $request->filled('page');
        $perPage = $paginate ? max(1, min(100, (int) $request->input('per_page', 10))) : max(1, $total);
        $pageNo = $paginate ? max(1, (int) $request->input('page_no', $request->input('page', 1))) : 1;
        $pageRows = $renewals->forPage($pageNo, $perPage)->values();
        $lastPage = max(1, (int) ceil($total / $perPage));

        return response()->json([
            'success'    => true,
            'message'    => 'Renewals fetched successfully',
            'partner_id' => $partnerId,
            'total'      => $total,
            'counts'     => $counts,
            'data'       => $pageRows,
            'pagination' => [
                'total'        => $total,
                'per_page'     => $perPage,
                'current_page' => $pageNo,
                'last_page'    => $lastPage,
                'from'         => $pageRows->isEmpty() ? null : ($pageNo - 1) * $perPage + 1,
                'to'           => $pageRows->isEmpty() ? null : ($pageNo - 1) * $perPage + $pageRows->count(),
            ],
        ]);
    }

    public function renewalsCustomer(Request $request)
    {
        $request->validate([
            'order_id' => 'required|integer'
        ]);

        // Get the order with relations
        $renewal = Order::with([
            'customer',
            'partner',
            'plan.provider',
        ])->find($request->order_id);

        if (!$renewal) {
            return response()->json([
                'success' => false,
                'message' => 'Customer renewal not found'
            ], 404);
        }

        // All items for the order (direct query to avoid runtime relation issues)
        $orderItems = OrderItem::with('plan.provider')
            ->where('order_id', (int) $renewal->id)
            ->orderBy('id')
            ->get();
        if ($orderItems->isEmpty()) {
            return response()->json([
                'success' => false,
                'message' => 'No items found for this order'
            ], 404);
        }

        $orderCategory = strtolower(trim((string) ($renewal->order_category ?? '')));
        $orderStatusRaw = strtolower(trim((string) ($renewal->status ?? '')));

        $planChangeContext = $this->buildPlanChangeContextForOrders([(int) $renewal->id]);
        $childChangeOrders = $planChangeContext['child_change_orders_by_parent']->get((int) $renewal->id, collect());
        $upgradeStateBySourceSubId = $this->buildUpgradeStateBySourceSubId(
            (int) $renewal->id,
            $childChangeOrders,
            $planChangeContext['child_order_items'],
            $planChangeContext['new_plans_by_id']
        );

        $hasLeftoverPlans = $orderItems->contains(function ($item) use (
            $upgradeStateBySourceSubId,
            $planChangeContext,
            $childChangeOrders
        ) {
            $itemStatus = strtolower(trim((string) ($item->status ?? 'active')));
            if ($itemStatus === '') {
                $itemStatus = 'active';
            }
            if (in_array($itemStatus, ['upgraded', 'downgraded', 'renewed', 'delete', 'deleted', 'cancelled', 'canceled'], true)) {
                return false;
            }
            $itemId = (int) ($item->id ?? 0);
            if ($itemId > 0 && isset($upgradeStateBySourceSubId[$itemId])) {
                $moved = $this->resolveMovedLicensesForSourceLine(
                    $itemId,
                    $upgradeStateBySourceSubId,
                    $planChangeContext['child_order_items'],
                    $childChangeOrders
                );
                $qty = max(1, (int) ($item->quantity ?? 1));
                $leftoverQty = $this->leftoverQtyAfterPlanChange(
                    $qty,
                    $moved,
                    $itemStatus,
                    $this->mappedChangeIsSamePlan($item, $upgradeStateBySourceSubId)
                );

                return $leftoverQty !== null && $leftoverQty > 0;
            }

            return true;
        });

        if (
            !$hasLeftoverPlans
            && (
                in_array($orderCategory, ['upgraded', 'downgraded', 'renewed'], true)
                || in_array($orderStatusRaw, ['upgraded', 'downgraded', 'renewed'], true)
            )
        ) {
            return response()->json([
                'success' => false,
                'message' => 'This subscription has already been upgraded or renewed and is not available for parent renewal.',
            ], 422);
        }

        // Collect status, default to 'unknown' if not present
        $orderStatus = $renewal->status ?? 'unknown';

        // Use first order item for plan/provider if all items are same, otherwise treat each as distinct
        $walletBalance = optional($renewal->partner)->wallet_balance ?? 0;
        $companyInfo = [
            'customer_id'   => $renewal->user_id,
            'company_name'  => optional($renewal->partner)->company_name
                ?? optional($renewal->partner)->name
                ?? '',
            'customer_name' => optional($renewal->customer)->name ?? '',
            'domain'        => $renewal->domain_name ?? '',
            'email'         => optional($renewal->customer)->email ?? '',
            'mobile'        => optional($renewal->customer)->mobile ?? '',
            'order_status'  => $orderStatus, // Added order status here
        ];

        // Skip upgraded source plans; leftover Active plans stay renewable on parent.
        $licenseCount = 0;
        $subtotal = 0;
        $plansInfo = [];
        foreach ($orderItems as $item) {
            $itemStatus = strtolower(trim((string) ($item->status ?? 'active')));
            if ($itemStatus === '') {
                $itemStatus = 'active';
            }
            if (in_array($itemStatus, ['upgraded', 'downgraded', 'renewed', 'delete', 'deleted', 'cancelled'], true)) {
                continue;
            }

            $itemId = (int) ($item->id ?? 0);
            $qty = max(1, (int) ($item->quantity ?? 1));
            if ($itemId > 0 && isset($upgradeStateBySourceSubId[$itemId])) {
                $moved = $this->resolveMovedLicensesForSourceLine(
                    $itemId,
                    $upgradeStateBySourceSubId,
                    $planChangeContext['child_order_items'],
                    $childChangeOrders
                );
                if ($moved > 0 && $qty > $moved) {
                    $qty = $qty - $moved;
                } else {
                    continue;
                }
            }

            $plan = $item->plan ?? $renewal->plan;
            $provider = optional($plan)->provider;
            $licenseCount += $qty;
            $plansInfo[] = [
                'order_sub_id' => $item->id,
                'provider_id'   => optional($plan)->provider_id ?? null,
                'provider_name' => optional($provider)->name ?? '',
                'plan_name'     => optional($plan)->name ?? '',
                'plan_type'     => optional($plan)->plan_type ?? '',
                'customer_limit' => optional($plan)->customer_limit ?? null,
                'plan_id'       => optional($plan)->id ?? null,
                'licenses'      => $qty,
                'price_per_license_per_year' => round(optional($plan)->price ?? 0, 2),
                'subtotal'      => round((optional($plan)->price ?? 0) * $qty, 2),
                'domain'        => $renewal->domain_name ?? '',
                'subscription_start_date' => $renewal->subscription_start_date ? $renewal->subscription_start_date->format('d M Y') : null,
                'subscription_end_date' => $renewal->subscription_end_date ? $renewal->subscription_end_date->format('d M Y') : null,
                'status'  => $orderStatus,
            ];
            $subtotal += (optional($plan)->price ?? 0) * $qty;
        }

        if ($plansInfo === []) {
            return response()->json([
                'success' => false,
                'message' => 'No renewable plans remain on this parent order (already upgraded or renewed).',
            ], 422);
        }

        // GST and totals (assuming all same GST rate)
        $gstPercentage = 18;
        $gstAmount = ($subtotal * $gstPercentage) / 100;
        $totalAmount = $subtotal + $gstAmount;

        $sourcePo = $this->resolveParentOrderPoPayload((int) $renewal->id);

        $data = [
            'company_info' => $companyInfo,
            'plans' => $plansInfo, // List of items/plans for this order

            'renew_plan' => [
                'continue_same_subscription' => true,
                'renew_from' =>
                $renewal->subscription_end_date
                    ? $renewal->subscription_end_date->format('d M Y')
                    : null,
                'duration' => ($renewal->duration ?? 12) . ' months',
                'price_per_year_all' => round($subtotal, 2),
            ],

            'renewal_summary' => [
                'total_licenses'                => $licenseCount,
                'subtotal'                      => round($subtotal, 2),
                'gst_percentage'                => $gstPercentage,
                'gst_amount'                    => round($gstAmount, 2),
                'total_amount'                  => round($totalAmount, 2),
            ],

            'wallet_info' => $this->partnerB2bWalletInfo(
                (int) ($renewal->partner_id ?? 0),
                (float) $totalAmount
            ),
            'order_status' => $orderStatus, // Also echo top-level for easy access
            'po' => $sourcePo,
            'po_link' => $sourcePo['po_link'] ?? null,
            'po_mode' => $sourcePo['po_mode'] ?? 'generated',
            'po_number' => $sourcePo['po_number'] ?? '',
            'final_po_link' => $sourcePo['final_po_link'] ?? null,
            'is_uploaded_po' => (bool) ($sourcePo['is_uploaded'] ?? false),
        ];

        return response()->json([
            'success' => true,
            'message' => 'Renewal details fetched successfully',
            'data'    => $data, // Only one object, all plans/items and summary inside
        ]);
    }

    public function pandinghistory(Request $request)
    {
        $partnerId = $request->input('partner_id');

        if (!$partnerId) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Partner ID is required.',
                'data' => null,
            ], 400);
        }

        // Check if partner exists
        $partner = Partner::find($partnerId);
        if (!$partner) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Partner not found.',
                'data' => null,
            ], 404);
        }

        $ordersQuery = $this->order->newQuery()
            ->where('partner_id', $partnerId)
            ->whereIn('status', ['processing', 'waiting', 'unpaid', 'incomplete', '0', 'pending_payment'])
            ->where('order_type', 'b2b')
            ->orderByDesc('id');

        $orders = $ordersQuery->get();

        if ($orders->isEmpty()) {
            return response()->json([
                'success' => true,
                'error' => false,
                'message' => 'No pending orders found.',
                'data' => [],
            ], 200);
        }

        // Build orders list - Try to get domain from orders table first
        $ordersList = [];
        foreach ($orders as $order) {
            // Try to get domain from multiple possible sources
            $domainDisplay = '₹';

            // Check if domain is directly stored in orders table
            if (!empty($order->domain)) {
                $domainDisplay = $order->domain;
            }
            // Check if domain_name column exists
            elseif (!empty($order->domain_name)) {
                $domainDisplay = $order->domain_name;
            }
            // Check if there's a domain_id and domains table exists
            elseif (!empty($order->domain_id) && Schema::hasTable('domains')) {
                $domain = Domain::where('id', $order->domain_id)->first();
                if ($domain) {
                    $domainDisplay = $domain->name ?? $domain->domain ?? $domain->domain_name ?? 'Domain #' . $order->domain_id;
                }
            }
            // Check if product or service name contains domain info
            elseif (!empty($order->product_name)) {
                $domainDisplay = $order->product_name;
            }

            // Get customer name
            $customerDisplay = '₹';
            $customerId = $order->customer_id ?? $order->user_id ?? null;
            if ($customerId) {
                $customer = $this->customer->newQuery()->where('id', $customerId)->first();
                if ($customer) {
                    $customerDisplay = $customer->name ?? $customer->company_name ?? $customer->email ?? 'Customer #' . $customerId;
                }
            }

            // Get plan name
            $planName = '₹';
            $planId = $order->plan_id ?? null;
            if ($planId) {
                $plan = $this->plan->newQuery()->where('id', $planId)->first();
                if ($plan) {
                    $planName = $plan->title ?? $plan->name ?? $plan->plan_name ?? 'Plan #' . $planId;
                }
            }

            // Optional: Get pending reason if available
            $pendingReason = '₹';
            if (!empty($order->pending_reason)) {
                $pendingReason = $order->pending_reason;
            } elseif (!empty($order->failure_reason)) {
                $pendingReason = $order->failure_reason;
            } elseif (!empty($order->remarks)) {
                $pendingReason = $order->remarks;
            }

            $ordersList[] = [
                'order_id' => $order->id,
                'customer' => $customerDisplay,
                'domain' => $domainDisplay,
                'plan' => $planName,
                'plan_id' => $planId,
                'amount' => (float)($order->amount ?? $order->total_amount ?? $order->subtotal ?? 0),
                'credit_used' => (float)($order->credit_used ?? 0),
                'status' => $order->status ?? 'pending',
                'pending_reason' => $pendingReason,
                'date' => $order->created_at ? \Illuminate\Support\Carbon::parse($order->created_at)->format('d M Y, H:i') : '₹'
            ];
        }

        return response()->json([
            'success' => true,
            'error' => false,
            'message' => 'Pending orders fetched successfully.',
            'data' => $ordersList,
        ], 200);
    }

