    public function variants(Request $request): JsonResponse
    {
        $providerId = $request->input('provider_id');

        // Validate provider_id presence
        if (!$providerId) {
            return response()->json([
                'success' => false,
                'message' => 'provider_id is required',
                'data' => null,
            ], 400);
        }

        // Fetch the provider model
        $provider = Provider::find($providerId);

        // Ensure the provider exists
        if (!$provider) {
            return response()->json([
                'success' => false,
                'message' => 'Provider not found',
                'data' => null,
            ], 404);
        }

        $search = $request->input('search');

        // Query for main variants (no parent) under the provider
        $query = Variant::where('provider_id', $providerId)
            ->whereNull('parent_variant_id');

        // Optional search by variant name
        if (!empty($search)) {
            $query->where('name', 'LIKE', "%{$search}%");
        }

        // Eager load children variants and plans count for both main and child variants
        $variants = $query
            ->with([
                // Child (sub) variants including their respective plans count
                'children' => function ($q) {
                    $q->withCount('plans');
                }
            ])
            ->withCount('plans') // Plans count for this main variant
            ->orderBy('id', 'desc')
            ->get();

        // Structure the variant data as required by frontend/enterprises
        $result = $variants->map(function ($variant) {
            return [
                'id' => $variant->id,
                'parent_variant_id' => $variant->parent_variant_id,
                'provider_id' => $variant->provider_id,
                'name' => $variant->name,
                // Enterprise-specific status, defaulting to 'inactive' if not set
                'status' => $variant->status ?? 'inactive',
                'created_at' => $variant->created_at,
                'updated_at' => $variant->updated_at,
                // Total plans count for the main variant
                'plans_count' => $variant->plans_count ?? 0,
                // All direct child (sub) variants + their plan count
                'children' => $variant->children->map(function ($child) {
                    return [
                        'id' => $child->id,
                        'parent_variant_id' => $child->parent_variant_id,
                        'provider_id' => $child->provider_id,
                        'name' => $child->name,
                        // Enterprise-friendly status
                        'status' => $child->status ?? 'inactive',
                        'created_at' => $child->created_at,
                        'updated_at' => $child->updated_at,
                        // Plans count for the sub-variant
                        'plans_count' => $child->plans_count ?? 0,
                    ];
                })
            ];
        });

        return response()->json([
            'success' => true,
            'message' => 'Provider variants fetched successfully',
            'data' => [
                // Full provider info, formatted for the enterprise dashboard
                'provider' => [
                    'id' => $provider->id,
                    'name' => $provider->name,
                    'slug' => $provider->slug,
                    'description' => $provider->description,
                    'logo' => $provider->logo,
                    'type' => $provider->type,
                    'status' => $provider->status,
                    'created_at' => $provider->created_at,
                    'updated_at' => $provider->updated_at,
                ],
                // List of variants with children and plans count, for enterprise views
                'variants' => $result
            ]
        ]);
    }

    public function register(Request $request): JsonResponse
    {
        if (!$request->filled('company_name') && $request->filled('companyname')) {
            $request->merge(['company_name' => $request->input('companyname')]);
        }
        if (!$request->filled('aadhaar_mandatory') && $request->filled('aadhar_mendatary')) {
            $request->merge(['aadhaar_mandatory' => $request->input('aadhar_mendatary')]);
        }
        $aadhaarMandatory = strtolower((string) $request->input('aadhaar_mandatory', 'yes'));
        $request->merge(['aadhaar_mandatory' => $aadhaarMandatory]);
        $natureOfBusiness = $request->input('nature_of_business');
        if (is_array($natureOfBusiness)) {
            $natureOfBusiness = implode(', ', array_filter(array_map(static function ($item) {
                return trim((string) $item);
            }, $natureOfBusiness)));
            $request->merge(['nature_of_business' => $natureOfBusiness]);
        }

        $email = strtolower(trim((string) $request->input('email', '')));
        $mobile = trim((string) $request->input('mobile', ''));
        $gstin = strtoupper(trim((string) $request->input('gstin', '')));
        if ($gstin !== '') {
            $request->merge(['gstin' => $gstin]);
        }

        $incompleteResolution = $this->resolveIncompleteRegistrationPartner($email, $mobile);
        if ($incompleteResolution['error'] !== null) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => $incompleteResolution['error'],
                'data' => null,
            ], 422);
        }

        /** @var Partner|null $incompletePartner */
        $incompletePartner = $incompleteResolution['partner'];
        $ignorePartnerId = $incompletePartner?->id;

        $byGstin = $gstin !== ''
            ? Partner::query()->whereRaw('UPPER(TRIM(gstin)) = ?', [$gstin])->first()
            : null;

        if ($byGstin && $this->isIncompleteRegistrationPartner($byGstin)) {
            $gstPartnerEmail = strtolower(trim((string) ($byGstin->email ?? '')));
            $gstPartnerMobile = trim((string) ($byGstin->mobile ?? ''));
            $gstPartnerGstin = strtoupper(trim((string) ($byGstin->gstin ?? '')));

            if ($gstPartnerEmail === $email && $gstPartnerMobile === $mobile && $gstPartnerGstin === $gstin) {
                $incompletePartner = $byGstin;
                $ignorePartnerId = $byGstin->id;
            } elseif (
                $incompletePartner
                && (int) $incompletePartner->id === (int) $byGstin->id
                && $gstPartnerEmail === $email
                && $gstPartnerMobile === $mobile
            ) {
                $ignorePartnerId = $incompletePartner->id;
            } elseif (
                $incompletePartner
                && (int) $incompletePartner->id !== (int) $byGstin->id
            ) {
                return response()->json([
                    'success' => false,
                    'error' => true,
                    'message' => 'Email, mobile and GSTIN belong to different pending registrations. Use the same details or contact support.',
                    'data' => null,
                ], 422);
            }
        } elseif (
            $incompletePartner
            && $gstin !== ''
            && $this->isIncompleteRegistrationPartner($incompletePartner)
        ) {
            $partnerEmail = strtolower(trim((string) ($incompletePartner->email ?? '')));
            $partnerMobile = trim((string) ($incompletePartner->mobile ?? ''));
            $partnerGstin = strtoupper(trim((string) ($incompletePartner->gstin ?? '')));

            if ($partnerEmail === $email && $partnerMobile === $mobile && $partnerGstin === $gstin) {
                $ignorePartnerId = $incompletePartner->id;
            }
        }

        $validator = Validator::make($request->all(), [
            'name' => 'required|string|max:255',
            'email' => [
                'required',
                'email',
                Rule::unique('pgsql_auth.partners', 'email')->ignore($ignorePartnerId),
            ],
            'mobile' => [
                'required',
                'string',
                Rule::unique('pgsql_auth.partners', 'mobile')->ignore($ignorePartnerId),
            ],
            'gstin' => [
                'required',
                'string',
                'size:15',
                'regex:/^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z]{1}[1-9A-Z]{1}Z[0-9A-Z]{1}$/',
                function (string $attribute, mixed $value, \Closure $fail) use ($ignorePartnerId, $email, $mobile): void {
                    $gst = strtoupper(trim((string) $value));
                    if ($gst === '') {
                        return;
                    }

                    $existing = Partner::query()
                        ->whereRaw('UPPER(TRIM(gstin)) = ?', [$gst])
                        ->first();

                    if (!$existing) {
                        return;
                    }

                    if ($ignorePartnerId !== null && (int) $existing->id === (int) $ignorePartnerId) {
                        return;
                    }

                    if ($this->isIncompleteRegistrationPartner($existing)) {
                        $existingEmail = strtolower(trim((string) ($existing->email ?? '')));
                        $existingMobile = trim((string) ($existing->mobile ?? ''));
                        if ($existingEmail === $email && $existingMobile === $mobile) {
                            return;
                        }
                    }

                    $fail('The gstin has already been taken.');
                },
            ],
            'company_name' => 'required|string',
            'company_address' => 'required|string',
            'legal_name' => 'string',
            'trade_name' => 'string',
            'address' => 'string',
            'gst_status' => 'string',
            'last_updated' => 'date',
            'constitution' => 'string',
            'registration_date' => 'date',
            'nature_of_business' => 'nullable',
            'postcode' => 'string',
            'pincode' => 'string',
            'state' => 'string',
            'city' => 'nullable',
            'country' => 'string',
            'aadhaar_mandatory' => 'nullable|in:yes,no',
            'pan_no' => 'string',
        ]);

        if ($validator->fails()) {
            $json = [
                'success' => false,
                'error' => true,
                'email' => $validator->errors()->first('email'),
                'mobile' => $validator->errors()->first('mobile'),
                'gstin' => $validator->errors()->first('gstin'),
                'company_name' => $validator->errors()->first('company_name'),
                'company_address' => $validator->errors()->first('company_address'),
                'name' => $validator->errors()->first('name'),
                'terms_and_conditions' => $validator->errors()->first('terms_and_conditions'),
                'legal_name' => $validator->errors()->first('legal_name'),
                'trade_name' => $validator->errors()->first('trade_name'),
                'address' => $validator->errors()->first('address'),
                'gst_status' => $validator->errors()->first('gst_status'),
                'last_updated' => $validator->errors()->first('last_updated'),
                'constitution' => $validator->errors()->first('constitution'),
                'registration_date' => $validator->errors()->first('registration_date'),
                'nature_of_business' => $validator->errors()->first('nature_of_business'),
                'postcode' => $validator->errors()->first('postcode'),
                'pincode' => $validator->errors()->first('pincode'),
                'state' => $validator->errors()->first('state'),
                'city' => $validator->errors()->first('city'),
                'country' => $validator->errors()->first('country'),
                'aadhaar_mandatory' => $validator->errors()->first('aadhaar_mandatory'),
                'pan_no' => $validator->errors()->first('pan_no'),
            ];
            return response()->json($json, 422);
        }

        try {
            DB::beginTransaction();

            $payload = [
                'name' => $request->name,
                'email' => $email,
                'mobile' => $mobile,
                'gstin' => strtoupper((string) $request->gstin),
                'pan_no' => $request->input('pan_no'),
                'company_name' => $request->company_name,
                'company_address' => $request->company_address ?? null,
                'legal_name' => $request->input('legal_name', $request->company_name),
                'trade_name' => $request->input('trade_name', $request->company_name),
                'address' => $request->input('address', $request->company_address),
                'country' => $request->input('country', 'India'),
                'state' => $request->input('state'),
                'city' => $request->input('city'),
                'postcode' => $request->input('postcode', $request->input('pincode')),
                'pincode' => $request->input('pincode'),
                'gst_status' => $request->input('gst_status'),
                'last_updated' => $request->input('last_updated'),
                'constitution' => $request->input('constitution'),
                'registration_date' => $request->input('registration_date'),
                'nature_of_business' => $natureOfBusiness ?? $request->input('nature_of_business'),
                'aadhaar_mandatory' => $aadhaarMandatory,
                'email_verified' => 0,
                'status' => 'pending',
            ];

            $registrationResumed = false;

            if ($incompletePartner) {
                $incompletePartner->update($payload);
                $partner = $incompletePartner->fresh();
                $registrationResumed = true;

                PartnerOtp::query()
                    ->where('partner_id', $partner->id)
                    ->where('type', 'verify_email')
                    ->delete();
            } else {
                $partner = Partner::create($payload);
            }

            $partner->setAttribute('aadhaar_mandatory', $aadhaarMandatory);

            $this->createAndSendOtp($partner, 'verify_email', 10);

            DB::commit();

            return response()->json([
                'success' => true,
                'error' => false,
                'message' => $registrationResumed
                    ? 'Registration updated. OTP sent to your email.'
                    : 'Registration successful. OTP sent to your email.',
                'registration_resumed' => $registrationResumed,
                'data' => $partner,
                'redirect' => url('/partner/verify-otp'),
            ], $registrationResumed ? 200 : 201);
        } catch (\Exception $e) {
            DB::rollBack();
            return $this->errorResponse('Registration failed: ' . $e->getMessage(), 500);
        }
    }

    public function resendOtp(Request $request)
    {
        $email = $request->expectsJson() ? $request->email : session('pending_verification_email');

        if (!$email) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Session expired or email missing. Please register again.',
                'data' => null,
            ], 400);
        }

        $user = Partner::where('email', $email)->first();

        if (!$user) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'User not found.',
                'data' => null,
            ], 404);
        }

        try {
            $this->createAndSendOtp($user, 'verify_email', 5);

            return response()->json([
                'success' => true,
                'error' => false,
                'message' => 'A new OTP has been sent to your email.',
                'data' => null,
            ], 200);
        } catch (\Exception $e) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Failed to resend OTP: ' . $e->getMessage(),
                'data' => null,
            ], 500);
        }
    }

    public function me(Request $request): JsonResponse
    {
        return response()->json([
            'success' => true,
            'error' => false,
            'message' => 'Profile fetched.',
            'data' => [
                'partner' => $this->partnerPayload($request->user()),
            ]
        ], 200);
    }

    public function logout(Request $request): JsonResponse
    {
        $partner = $request->user();
        $sessionService = app(PartnerUserSessionService::class);

        if (!$partner && $request->bearerToken()) {
            $accessToken = PersonalAccessToken::findToken($request->bearerToken());
            if ($accessToken && $accessToken->tokenable instanceof Partner) {
                $partner = $accessToken->tokenable;
                $sessionService->closeByToken((int) $accessToken->id);
                $accessToken->delete();
            }
        } else {
            $currentToken = $partner?->currentAccessToken();
            if ($currentToken && isset($currentToken->id)) {
                $sessionService->closeByToken((int) $currentToken->id);
            }
            $currentToken?->delete();
        }

        if ($partner) {
            $partner->update(['current_session_token' => null]);
        }

        return response()->json([
            'success' => true,
            'error' => false,
            'message' => 'Logged out successfully.',
            'data' => null
        ], 200);
    }

    public function forgotPassword(Request $request): JsonResponse
    {
        $validator = Validator::make($request->all(), [
            'email' => ['required', 'email', 'exists:pgsql_auth.partners,email'],
        ]);

        if ($validator->fails()) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Validation failed.',
                'data' => $validator->errors()
            ], 422);
        }

        $partner = Partner::where('email', $request->email)->first();
        if (!$partner) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Partner not found.',
                'data' => null,
            ], 404);
        }
        $this->createAndSendOtp($partner, 'forgot_password', 5);

        return response()->json([
            'success' => true,
            'error' => false,
            'message' => 'Password reset OTP sent.',
            'data' => [
                'email' => $partner->email,
            ]
        ], 200);
    }

    public function verifyResetOtp(Request $request): JsonResponse
    {
        $validator = Validator::make($request->all(), [
            'email' => ['required', 'email', 'exists:pgsql_auth.partners,email'],
            'otp' => ['required', 'digits:6'],
        ]);

        if ($validator->fails()) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Validation failed.',
                'data' => $validator->errors()
            ], 422);
        }

        $partner = Partner::where('email', $request->email)->first();
        if (!$partner) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Partner not found.',
                'data' => null,
            ], 404);
        }
        $otpRecord = PartnerOtp::where('partner_id', $partner->id)
            ->where('type', 'forgot_password')
            ->where('otp', $request->otp)
            ->latest('id')
            ->first();

        if (!$otpRecord || $otpRecord->expires_at <= now()) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Invalid or expired OTP.',
                'data' => null
            ], 400);
        }

        $otpRecord->update(['verified' => 1]);

        return response()->json([
            'success' => true,
            'error' => false,
            'message' => 'OTP verified.',
            'data' => [
                'email' => $partner->email,
            ]
        ], 200);
    }

    public function resetPassword(Request $request): JsonResponse
    {
        $validator = Validator::make($request->all(), [
            'email' => ['required', 'email', 'exists:pgsql_auth.partners,email'],
            'password' => ['required', 'string', 'min:8', 'confirmed'],
        ]);

        if ($validator->fails()) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Validation failed.',
                'data' => $validator->errors()
            ], 422);
        }

        $partner = Partner::where('email', $request->email)->first();
        if (!$partner) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Partner not found.',
                'data' => null,
            ], 404);
        }

        $otpRecord = PartnerOtp::where('partner_id', $partner->id)
            ->where('type', 'forgot_password')
            ->where('verified', 1)
            ->latest('id')
            ->first();

        if (!$otpRecord) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'OTP verification is required before password reset.',
                'data' => null
            ], 400);
        }

        $partner->update([
            'password' => Hash::make($request->password),
        ]);

        $otpRecord->delete();

        return response()->json([
            'success' => true,
            'error' => false,
            'message' => 'Password updated successfully.',
            'data' => null
        ], 200);
    }

    public function sendOtp(Request $request): JsonResponse
    {
        $identifier = trim((string) ($request->input('email', $request->input('mobile', ''))));
        foreach ($request->all() as $input) {
            if (
                is_string($input)
                && preg_match('/<\s*script|SELECT\s+.*\s+FROM|UNION\s+SELECT|OR\s+["\']?\d+=["\']?\d+|\.\.\/\//i', $input)
            ) {
                PartnerLoginLog::create([
                    'partner_id' => null,
                    'identifier' => $identifier !== '' ? $identifier : 'unknown',
                    'action' => 'suspicious_activity',
                    'ip_address' => $request->ip(),
                    'user_agent' => $request->userAgent(),
                    'payload' => 'Potential script or SQL injection pattern detected.',
                    'created_at' => now(),
                ]);

                return response()->json([
                    'success' => false,
                    'message' => 'Suspicious activity detected.',
                    'data' => null,
                ], 403);
            }
        }

        $validator = Validator::make($request->all(), [
            'email' => ['sometimes', 'email'],
            'mobile' => ['sometimes', 'string'],
        ]);

        if ($validator->fails()) {
            return response()->json([
                'success' => false,
                'message' => 'Validation failed.',
                'data' => $validator->errors()
            ], 422);
        }

        if (!$request->filled('email') && !$request->filled('mobile')) {
            return response()->json([
                'success' => false,
                'message' => 'Email or mobile is required.',
                'data' => null,
            ], 422);
        }

        $loginField = $request->filled('email') ? 'email' : 'mobile';
        $identifier = $loginField === 'email'
            ? trim((string) $request->email)
            : trim((string) $request->mobile);

        $resolved = $this->resolvePartnerLoginActor($loginField, $identifier);
        $partner = $resolved['partner'];
        $partnerUser = $resolved['partner_user'];
        $loginAs = $resolved['login_as'];

        $isPlayStoreReviewer =
            $loginField === 'mobile'
            && (bool) config('services.playstore_reviewer.enabled')
            && trim((string) ($request->mobile ?? '')) === trim((string) config('services.playstore_reviewer.mobile'));

        // Blocked partner user (via partner-user-deactivate-device block_device) → clear error instead of "not registered"
        if (!$partner && !$isPlayStoreReviewer && PartnerUser::query()
            ->where($loginField, $identifier)
            ->whereRaw('LOWER(TRIM(status)) = ?', ['blocked'])
            ->exists()) {
            PartnerLoginLog::create([
                'partner_id' => null,
                'identifier' => $identifier,
                'action' => 'login_failed',
                'ip_address' => $request->ip(),
                'user_agent' => $request->userAgent(),
                'payload' => 'Blocked partner user tried to request OTP.',
                'created_at' => now(),
            ]);

            return response()->json([
                'success' => false,
                'message' => 'Your account has been blocked by your administrator. Please contact your partner admin.',
                'data' => ['blocked' => true],
            ], 403);
        }

        // Reviewer mobile bypasses partner-not-found (no SMS / no PartnerOtp)
        if (!$partner && !$isPlayStoreReviewer) {
            PartnerLoginLog::create([
                'partner_id' => null,
                'identifier' => $identifier !== '' ? $identifier : 'unknown',
                'action' => 'login_failed',
                'ip_address' => $request->ip(),
                'user_agent' => $request->userAgent(),
                'payload' => 'User identifier not found or email not verified / partner user inactive.',
                'created_at' => now(),
            ]);

            return response()->json([
                'success' => false,
                'message' => 'Partner not registered or partner not found.',
                'data' => null,
            ], 404);
        }

        // Active login already exists (live token that verify-otp would revoke)
        $isPartnerUser = $loginAs === 'partner_user' && $partnerUser;
        $deviceId = trim((string) $request->input('device_id', $request->input('deviceId', '')));
        // partner_sessions: partner user → partner_user_id = user id; main partner → partner_user_id NULL
        $activeSession = $isPlayStoreReviewer ? null : rescue(fn () => \App\Models\PartnerSession::query()
            ->where('partner_id', (int) $partner->id)
            ->when($isPartnerUser,
                fn ($q) => $q->where('partner_user_id', (int) $partnerUser->id),
                fn ($q) => $q->whereNull('partner_user_id'))
            ->whereNull('logout')
            // Same device re-login is not "another device"
            ->when($deviceId !== '', fn ($q) => $q->where(fn ($w) => $w->whereNull('device_id')->orWhere('device_id', '!=', $deviceId)))
            ->whereIn('token_id', PersonalAccessToken::query()->select('id'))
            ->latest('id')
            ->first(['id', 'token_id', 'device_name', 'platform', 'ip_address', 'logged_in']), null, false);
        $alreadyLoggedIn = $activeSession !== null;

        // Not confirmed by the user yet → no OTP, existing session stays intact
        if ($alreadyLoggedIn && !$request->boolean('isAlreadyLoggedIn')) {
            return response()->json([
                'success' => false,
                'isAlreadyLoggedIn' => true,
                'message' => 'User is already logged in on another device.',
                'data' => [
                    'session_id' => (int) $activeSession->id,
                    'device_name' => $activeSession->device_name,
                    'platform' => $activeSession->platform,
                    'ip_address' => $activeSession->ip_address,
                    'logged_in_at' => optional($activeSession->logged_in)->toDateTimeString(),
                ],
            ], 200);
        }

        if (!$isPlayStoreReviewer) {
            $this->createAndSendOtp($partner, 'login', 5, $loginField, $partnerUser);
        }

        // Replace-session intent, consumed by verify-otp
        if ($alreadyLoggedIn) {
            Cache::put('partner_login_replace:' . $partner->id . ':' . ($isPartnerUser ? $partnerUser->id : 0), true, now()->addMinutes(10));
        }

        PartnerLoginLog::create([
            'partner_id' => $partner?->id,
            'identifier' => $identifier,
            'action' => 'otp_sent',
            'ip_address' => $request->ip(),
            'user_agent' => $request->userAgent(),
            'payload' => $isPlayStoreReviewer
                ? 'playstore_reviewer_otp_request'
                : ($loginAs === 'partner_user'
                    ? 'partner_user_otp_request:' . ($partnerUser?->id ?? '')
                    : null),
            'created_at' => now(),
        ]);

        return response()->json([
            'success' => true,
            'isAlreadyLoggedIn' => false,
            'message' => 'OTP sent successfully.',
            'data' => [
                'already_logged_in' => false,
                'login_as' => $isPlayStoreReviewer ? 'partner' : $loginAs,
            ],
        ], 200);
    }

    public function verifyOtp(Request $request): JsonResponse
    {
        if (!$request->filled('device_id') && $request->filled('deviceId')) {
            $request->merge(['device_id' => $request->input('deviceId')]);
        }

        $rules = [
            'otp' => 'required|digits:6',
            // Device & login info (partner users), sent by the app.
            'device_id' => ['nullable', 'string', 'max:191'],
            'device_name' => ['nullable', 'string', 'max:120'],
            'device_type' => ['nullable', 'string', Rule::in(['mobile', 'tablet', 'desktop'])],
            'platform' => ['nullable', 'string', 'max:30'],
        ];

        if ($request->filled('mobile')) {
            $rules['mobile'] = ['required', 'string'];
        } else {
            $rules['email'] = ['required', 'email'];
        }

        $validator = Validator::make($request->all(), $rules);

        if ($validator->fails()) {
            return response()->json([
                'success' => false,
                'message' => 'Validation failed.',
                'data' => $validator->errors()
            ], 422);
        }

        $loginField = $request->filled('mobile') ? 'mobile' : 'email';
        $identifier = $loginField === 'mobile'
            ? trim((string) $request->mobile)
            : trim((string) $request->email);

        $resolved = $this->resolvePartnerLoginActor($loginField, $identifier);
        $partner = $resolved['partner'];
        $partnerUser = $resolved['partner_user'];
        $loginAs = $resolved['login_as'];

        $isPlayStoreReviewer =
            $request->filled('mobile')
            && (bool) config('services.playstore_reviewer.enabled')
            && trim((string) $request->mobile) === trim((string) config('services.playstore_reviewer.mobile'));

        // Reviewer: ensure a partner row exists so Sanctum token can be issued (no extra method)
        if (!$partner && $isPlayStoreReviewer) {
            $reviewMobile = trim((string) config('services.playstore_reviewer.mobile'));
            $partner = Partner::firstOrCreate(
                ['mobile' => $reviewMobile],
                [
                    'name' => 'Play Store Reviewer',
                    'email' => 'playstore.reviewer.' . $reviewMobile . '@tizzy.local',
                    'company_name' => 'Play Store Reviewer',
                    'status' => 'approved',
                    'email_verified' => true,
                ]
            );
            $loginAs = 'partner';
            $partnerUser = null;
        }

        if (!$partner) {
            return response()->json([
                'success' => false,
                'message' => 'Invalid email or mobile.',
                'data' => null,
            ], 400);
        }

        // Blocked device gate: checked before the OTP is consumed and before any token is issued
        if ($loginAs === 'partner_user' && $partnerUser
            && app(PartnerUserSessionService::class)->isDeviceBlocked($partnerUser, $request->input('device_id'))) {
            PartnerLoginLog::create([
                'partner_id' => $partner->id,
                'identifier' => $identifier,
                'action' => 'login_failed',
                'ip_address' => $request->ip(),
                'user_agent' => $request->userAgent(),
                'payload' => 'Blocked device: ' . (string) $request->input('device_id', '(no device_id)'),
                'created_at' => now(),
            ]);

            return response()->json([
                'success' => false,
                'message' => 'This device has been blocked by your administrator. Please contact your partner admin.',
                'data' => null,
            ], 403);
        }

        $throttleKey = 'otp-verify:' . ($isPlayStoreReviewer
            ? 'playstore:' . $identifier
            : ($loginAs === 'partner_user' ? 'pu:' . ($partnerUser?->id ?? 0) : $partner->id));

        if (RateLimiter::tooManyAttempts($throttleKey, 4)) {
            $seconds = RateLimiter::availableIn($throttleKey);

            PartnerLoginLog::create([
                'partner_id' => $partner->id,
                'identifier' => $identifier,
                'action' => 'login_failed',
                'ip_address' => $request->ip(),
                'user_agent' => $request->userAgent(),
                'payload' => 'Account temporarily blocked. Too many wrong OTP attempts.',
                'created_at' => now(),
            ]);

            return response()->json([
                'success' => false,
                'message' => "Too many incorrect attempts. You are blocked for {$seconds} seconds.",
                'data' => null,
            ], 429);
        }

        if ($isPlayStoreReviewer) {
            $reviewerOtp = (string) config('services.playstore_reviewer.otp');
            if ((string) $request->otp !== $reviewerOtp) {
                RateLimiter::hit($throttleKey, 900);
                $attemptsLeft = RateLimiter::remaining($throttleKey, 3);

                PartnerLoginLog::create([
                    'partner_id' => $partner->id,
                    'identifier' => $identifier,
                    'action' => 'login_failed',
                    'ip_address' => $request->ip(),
                    'user_agent' => $request->userAgent(),
                    'payload' => "Incorrect OTP entered. Remaining attempts: {$attemptsLeft}",
                    'created_at' => now(),
                ]);

                return response()->json([
                    'success' => false,
                    'message' => "Invalid or expired OTP. You have {$attemptsLeft} attempts remaining.",
                    'data' => null,
                ], 400);
            }
        } else {
            $otpQuery = PartnerOtp::where('partner_id', $partner->id)
                ->where('otp', $request->otp)
                ->where('type', 'login')
                ->where('verified', 0)
                ->where('expires_at', '>', now());

            if (
                $loginAs === 'partner_user'
                && $partnerUser
                && Schema::connection('pgsql_auth')->hasColumn('partner_otps', 'partner_user_id')
            ) {
                $otpQuery->where(function ($q) use ($partnerUser) {
                    $q->where('partner_user_id', $partnerUser->id)
                        ->orWhereNull('partner_user_id');
                });
            }

            $otpRecord = $otpQuery->latest('id')->first();

            if (!$otpRecord) {
                RateLimiter::hit($throttleKey, 900);
                $attemptsLeft = RateLimiter::remaining($throttleKey, 3);

                PartnerLoginLog::create([
                    'partner_id' => $partner->id,
                    'identifier' => $identifier,
                    'action' => 'login_failed',
                    'ip_address' => $request->ip(),
                    'user_agent' => $request->userAgent(),
                    'payload' => "Incorrect OTP entered. Remaining attempts: {$attemptsLeft}",
                    'created_at' => now(),
                ]);

                return response()->json([
                    'success' => false,
                    'message' => "Invalid or expired OTP. You have {$attemptsLeft} attempts remaining.",
                    'data' => null,
                ], 400);
            }

            $otpRecord->update(['verified' => 1]);
        }

        RateLimiter::clear($throttleKey);

        $sessionService = app(PartnerUserSessionService::class);
        
        if ($loginAs === 'partner_user' && $partnerUser) {
            // Delete only this specific partner_user's old sessions and tokens
            $sessionService->deactivate($partnerUser);
            
            $newAccessToken = $partner->createToken('mobile-partner-user');
            // Do NOT overwrite current_session_token of the main partner!
        } else {
            // Main partner login: Revoke older main partner tokens and close their sessions
            $partner->tokens()->where('name', '!=', 'mobile-partner-user')->delete();
            rescue(fn () => \App\Models\PartnerSession::query()
                ->where('partner_id', (int) $partner->id)
                ->whereNull('partner_user_id')
                ->whereNull('logout')
                ->update(['logout' => now()]), null, false);
            
            $newAccessToken = $partner->createToken('mobile');
            $partner->update(['current_session_token' => 'api:' . $newAccessToken->accessToken->id]);
        }
        // Old sessions are revoked above, so the replace-session intent is done
        Cache::forget('partner_login_replace:' . $partner->id . ':' . ($loginAs === 'partner_user' && $partnerUser ? $partnerUser->id : 0));
        $token = $newAccessToken->plainTextToken;
        $approved = $partner->status;

        if ($partnerUser) {
            $partnerUser->last_login_at = now();
            $partnerUser->save();
        }

        // Partner user → partner_user_id set; main partner → partner_user_id NULL
        if (!$isPlayStoreReviewer) {
            $sessionService->record($partner, $loginAs === 'partner_user' ? $partnerUser : null, (int) $newAccessToken->accessToken->id, $request);
        }

        $permissions = [];
        if ($loginAs === 'partner_user' && $partnerUser) {
            $permissions = $this->mapPartnerModulePermissions(
                PartnerPermission::query()
                    ->where('partner_user_id', $partnerUser->id)
                    ->get()
                    ->keyBy('module_key')
            )->all();
        }

        PartnerLoginLog::create([
            'partner_id' => $partner->id,
            'identifier' => $identifier,
            'action' => 'login_success',
            'ip_address' => $request->ip(),
            'user_agent' => $request->userAgent(),
            'payload' => $isPlayStoreReviewer
                ? 'playstore_reviewer_login'
                : ($loginAs === 'partner_user' ? 'partner_user_login:' . $partnerUser->id : null),
            'created_at' => now(),
        ]);

        $data = [
            'status' => $approved,
            'token' => $token,
            'token_type' => 'Bearer',
            'login_as' => $isPlayStoreReviewer ? 'partner' : $loginAs,
            'partner' => $this->partnerPayload($partner, $isPlayStoreReviewer ? null : $partnerUser),
        ];

        if ($loginAs === 'partner_user' && $partnerUser && !$isPlayStoreReviewer) {
            $data['partner_user'] = [
                'partner_user_id' => (int) $partnerUser->id,
                'partner_id' => (int) $partner->id,
                'name' => (string) ($partnerUser->name ?? ''),
                'email' => (string) ($partnerUser->email ?? ''),
                'mobile' => (string) ($partnerUser->mobile ?? ''),
                'employee_id' => (string) ($partnerUser->employee_id ?? ''),
                'designation' => (string) ($partnerUser->designation ?? ''),
                'status' => (string) ($partnerUser->status ?? 'active'),
            ];
            $data['permissions'] = $permissions;
        }

        return response()->json([
            'success' => true,
            'message' => 'Login successful.',
            'data' => $data,
        ], 200);
    }

    public function verifyRegistrationEmailOtp(Request $request): JsonResponse
    {
        $validator = Validator::make($request->all(), [
            'email' => ['required', 'email', 'exists:pgsql_auth.partners,email'],
            'otp' => ['required', 'digits:6'],
        ]);

        if ($validator->fails()) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Validation failed.',
                'data' => $validator->errors() ?? (object)[],
            ], 422);
        }

        $partner = Partner::where('email', $request->email)->first();
        if (!$partner) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Partner not found.',
                'data' => [],
            ], 404);
        }

        $otpRecord = PartnerOtp::where('partner_id', $partner->id)
            ->where('otp', $request->otp)
            ->where('type', 'verify_email')
            ->where('expires_at', '>', now())
            ->latest('id')
            ->first();

        if (!$otpRecord) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Invalid or expired OTP.',
                'data' => [],
            ], 400);
        }

        $otpRecord->delete();
        $partner->email_verified = 1;
        $partner->save();

        return response()->json([
            'success' => true,
            'error' => false,
            'message' => 'Email verified successfully.',
            // Returning partner data so client never sees null; you can include relevant keys as needed
            'data' => [
                'partner' => [
                    'id' => (int) $partner->id,
                    'name' => (string) ($partner->name ?? ''),
                    'email' => (string) ($partner->email ?? ''),
                    'email_verified' => (bool) $partner->email_verified,
                ],
            ],
        ], 200);
    }

