    public function plans(Request $request): JsonResponse
    {
        try {

            $provider_id = (int) $request->input('provider_id');
            $variantInput = $request->input('variant_id', $request->input('variant'));

            /*
            |--------------------------------------------------------------------------
            | Validation
            |--------------------------------------------------------------------------
            */
            // if ($provider_id <= 0 || $variantInput === null || $variantInput === '') {
            //     return response()->json([
            //         'success' => false,
            //         'error'   => true,
            //         'message' => 'provider_id and variant_id are required',
            //         'data'    => null,
            //     ], 400);
            // }

            $resolvedVariantId = null;
            if (is_numeric($variantInput)) {
                $resolvedVariantId = (int) $variantInput;
            } else {
                $variantKey = strtolower(trim((string) $variantInput));
                $nameFromSlug = str_replace('-', ' ', $variantKey);
                $variantRow = Variant::query()
                    ->where('provider_id', $provider_id)
                    ->where(function ($q) use ($variantKey, $nameFromSlug) {
                        $q->whereRaw('LOWER(TRIM(name)) = ?', [$variantKey])
                            ->orWhereRaw('LOWER(TRIM(name)) = ?', [$nameFromSlug]);
                    })
                    ->first();

                if (!$variantRow) {
                    return response()->json([
                        'success' => false,
                        'error'   => true,
                        'message' => 'Variant not found',
                        'data'    => null,
                    ], 404);
                }

                $resolvedVariantId = (int) $variantRow->id;
            }

            /*
            |--------------------------------------------------------------------------
            | Fetch Provider
            |--------------------------------------------------------------------------
            */
            $provider = Provider::where('id', $provider_id)->where('status', 'active')->first();


            if (!$provider) {
                return response()->json([
                    'success' => false,
                    'error'   => true,
                    'message' => 'Provider not found',
                    'data'    => null,
                ], 404);
            }

            /*
            |--------------------------------------------------------------------------
            | Cart Data - plan_id from cart_items, provider_id from carts
            | $cartProviderIds ==  False if cart is empty or provider is in cart; true otherwise
            |--------------------------------------------------------------------------
            */
            $cartPlanIds = [];
            $cartProviderIds = false;
            $planIdsByProvider = [];
            $cartProviderIdList = false;
            $partner_id = $request->input('partner_id', $request->input('partnerId'));

            $carts = Cart::query()
                ->where('partner_id', (int) $partner_id)
                ->where('type', 'standard')
                ->where('status', 'active')
                ->get();


            // print_r($carts);
            // die;

            $cartIds = $carts->pluck('id')->all();

            $cartItems = collect();
            if ($cartIds !== []) {
                $cartItems = CartItem::query()
                    ->whereIn('cart_id', $cartIds)
                    ->whereNotNull('plan_id')
                    ->get(['cart_id', 'plan_id']);
            }

            $cartItemCount = $cartItems->count();

            if ($cartItemCount === 0) {
                $cartProviderIdList = false;
                $cartProviderIds = false;
                $hasgoogleplans = false;
            } else {
                $cartProviderIdListObj = $carts->pluck('provider_id')->filter()->unique()->values()->all();
                $providerIdInt = (int) $provider_id;

                $cartProviderIdList = array_map('intval', $cartProviderIdListObj);

                $planIds = $cartItems->pluck('plan_id')->unique()->map(static fn($id) => (int) $id)->values();
                $planProviderMap = $planIds->isNotEmpty()
                    ? Plan::query()
                    ->whereIn('id', $planIds)
                    ->pluck('provider_id', 'id')
                    ->map(static fn($pid) => (int) $pid)
                    ->all()
                    : [];

                $googlePlanCount = 0;
                $cartPlanIds = [];
                foreach ($cartItems as $cartItem) {
                    $planId = (int) $cartItem->plan_id;
                    $cartPlanIds[] = $planId;

                    $planProviderId = (int) ($planProviderMap[$planId] ?? 0);
                    if ($planProviderId <= 0) {
                        $cart = $carts->firstWhere('id', $cartItem->cart_id);
                        $planProviderId = (int) ($cart->provider_id ?? 0);
                    }
                    if ($planProviderId === 3) {
                        $googlePlanCount++;
                    }
                }
                $cartPlanIds = array_values(array_unique($cartPlanIds));

                $hasgoogleplans = $googlePlanCount >= 1
                    || ($carts->contains(static fn($cart) => (int) ($cart->provider_id ?? 0) === 3));

                foreach ($cartItems as $cartItem) {
                    $planId = (int) $cartItem->plan_id;
                    $pid = (int) ($planProviderMap[$planId] ?? 0);
                    if ($pid <= 0) {
                        $cart = $carts->firstWhere('id', $cartItem->cart_id);
                        $pid = (int) ($cart->provider_id ?? 0);
                    }
                    if ($pid === 0 || $planId <= 0) {
                        continue;
                    }
                    if (!isset($planIdsByProvider[$pid])) {
                        $planIdsByProvider[$pid] = [];
                    }
                    $planIdsByProvider[$pid][] = $planId;
                }

                if (empty($cartProviderIdList) || in_array($providerIdInt, $cartProviderIdList, true)) {
                    $cartProviderIds = false;
                } else {
                    $cartProviderIds = true;
                }
            }

            /*
            |--------------------------------------------------------------------------
            | Build Query for plans of requested provider/variant
            |--------------------------------------------------------------------------
            */
            $query = Plan::where('provider_id', $provider_id);

            if (
                isset($provider->has_variant) &&
                $provider->has_variant === 'yes'
            ) {
                $query->where('variant_id', $resolvedVariantId);
            }

            $query->where('status', 1);

            /*
            |--------------------------------------------------------------------------
            | Fetch Plans
            |--------------------------------------------------------------------------
            */
            $plans = $query
                ->orderBy('sr_no', 'ASC')
                ->get();

            /*
            |--------------------------------------------------------------------------
            | Format Plans
            |--------------------------------------------------------------------------
            */
            $partnerDiscountType = 'market_value';
            $partnerDiscountTypeLabel = \App\Support\PartnerDiscountType::label('market_value');
            if (!empty($partner_id)) {
                $partnerRow = Partner::query()->find((int) $partner_id);
                if ($partnerRow) {
                    $partnerDiscountType = \App\Support\PartnerDiscountType::normalize(
                        (string) ($partnerRow->partner_discount_type ?? '')
                    );
                    $partnerDiscountTypeLabel = \App\Support\PartnerDiscountType::label($partnerDiscountType);
                }
            }

            // Pass $hasgoogleplans into the closure so each plan entry is aware
            $plans = $plans->map(function ($plan) use ($cartPlanIds, $cartProviderIds, $hasgoogleplans, $partnerDiscountType, $partnerDiscountTypeLabel) {
                $featuresArray = [];
                if (!empty($plan->features)) {
                    $rawFeatures = explode('|', $plan->features);
                    foreach ($rawFeatures as $feature) {
                        $feature = trim($feature);
                        $feature = str_replace('check-arrow', '', $feature);

                        if ($feature !== '') {
                            $featuresArray[] = $feature;
                        }
                    }
                }

                /*
                |--------------------------------------------------------------------------
                | Cart Logic
                |--------------------------------------------------------------------------
                */
                $plan_is_in_cart = in_array((int) $plan->id, $cartPlanIds, true);

                /*
                |--------------------------------------------------------------------------
                | Prices â€” Market (actual_price) and Distributor (price).
                | Always return both when available; `price` = partner-type applicable amount.
                |--------------------------------------------------------------------------
                */
                $priceMeta = \App\Support\PartnerDiscountType::fromPlan($plan, $partnerDiscountType);
                $applicablePrice = (float) $priceMeta['price'];
                $marketPrice = $priceMeta['market_price'];
                $distributorPrice = $priceMeta['distributor_price'];
                $actualPrice = $priceMeta['actual_price'];
                $priceType = $priceMeta['price_type'];

                /*
                |--------------------------------------------------------------------------
                | Enquiry logic
                |--------------------------------------------------------------------------
                */
                $enquiry = true;
                if ($applicablePrice > 0) {
                    $enquiry = false;
                }

                return [
                    'sr_no'            => $plan->sr_no,
                    'id'               => $plan->id,
                    'provider_id'      => $plan->provider_id,
                    'category_id'      => $plan->category_id,
                    'variant_id'       => $plan->variant_id,
                    'name'             => $plan->name,
                    'slug'             => $plan->slug,
                    'storage'          => $plan->storage,
                    // Partner-assigned price type + applicable unit price.
                    'price_type'       => $priceType,
                    'price_type_label' => $partnerDiscountTypeLabel,
                    'price'            => $this->formatPlanPriceValue($applicablePrice),
                    'formatted_price'  => $this->formatPlanPrice($applicablePrice),
                    'distributor_price' => $this->formatPlanPriceValue($distributorPrice),
                    'formatted_distributor_price' => $this->formatPlanPrice($distributorPrice),
                    'actual_price'     => $this->formatPlanPriceValue($actualPrice),
                    'formatted_actual_price' => $this->formatPlanPrice($actualPrice),
                    'market_price'     => $this->formatPlanPriceValue($marketPrice),
                    'formatted_market_price' => $this->formatPlanPrice($marketPrice),
                    'billing_cycle'    => $plan->billing_cycle,
                    'customer_limit'   => $plan->customer_limit,
                    'status'           => $plan->status,

                    // $cartProviderIds ==  False if cart is empty or provider is in cart; true otherwise
                    'provider_in_cart' => $cartProviderIds,
                    'plan_is_in_cart'  => $plan_is_in_cart,

                    'features'         => $featuresArray,
                    'created_at'       => $plan->created_at,
                    'updated_at'       => $plan->updated_at,
                    'enquiry'          => $enquiry,
                    'hasgoogleplans'   => $hasgoogleplans,
                ];
            });

            /*
            |--------------------------------------------------------------------------
            | Response
            |--------------------------------------------------------------------------
            */
            return response()->json([
                'success' => true,
                'error'   => false,
                'message' => 'Provider plans fetched successfully.',
                'data' => [
                    'provider' => $provider,
                    'plans'    => $plans,
                    'hasgoogleplans' => $hasgoogleplans,
                    'partner_discount_type' => $partnerDiscountType,
                    'partner_discount_type_label' => $partnerDiscountTypeLabel,
                ],
            ], 200);
        } catch (\Exception $e) {
            return response()->json([
                'success' => false,
                'error'   => true,
                'message' => 'Failed to fetch provider plans',
                'error_details' => $e->getMessage()
            ], 500);
        }
    }
    private function isIncompleteRegistrationPartner(?Partner $partner): bool
    {
        if (!$partner) {
            return false;
        }

        if ((bool) ($partner->email_verified ?? false)) {
            return false;
        }

        $status = strtolower(trim((string) ($partner->status ?? 'pending')));

        return in_array($status, ['pending', '0', ''], true);
    }

    /**
     * Resume signup when OTP was never verified (same user editing details).
     *
     * @return array{partner: ?Partner, error: ?string}
     */
    private function resolveIncompleteRegistrationPartner(string $email, string $mobile): array
    {
        $email = strtolower(trim($email));
        $mobile = trim($mobile);

        $byEmail = $email !== ''
            ? Partner::query()->whereRaw('LOWER(TRIM(email)) = ?', [$email])->first()
            : null;

        $byMobile = $mobile !== ''
            ? Partner::query()->where('mobile', $mobile)->first()
            : null;

        if (
            $byEmail
            && $byMobile
            && (int) $byEmail->id !== (int) $byMobile->id
            && $this->isIncompleteRegistrationPartner($byEmail)
            && $this->isIncompleteRegistrationPartner($byMobile)
        ) {
            return [
                'partner' => null,
                'error' => 'Email and mobile belong to different pending registrations. Use the same details or contact support.',
            ];
        }

        if ($byEmail && $this->isIncompleteRegistrationPartner($byEmail)) {
            return ['partner' => $byEmail, 'error' => null];
        }

        if ($byMobile && $this->isIncompleteRegistrationPartner($byMobile)) {
            return ['partner' => $byMobile, 'error' => null];
        }

        return ['partner' => null, 'error' => null];
    }

    private function createAndSendOtp(
        Partner $partner,
        string $type,
        int $ttlMinutes,
        ?string $loginField = null,
        ?PartnerUser $partnerUser = null
    ): void {
        $otp = random_int(100000, 999999);

        $otpPayload = [
            'partner_id' => $partner->id,
            'otp' => (string) $otp,
            'type' => $type,
            'login_field' => $loginField,
            'expires_at' => now()->addMinutes($ttlMinutes),
            'verified' => 0,
        ];

        if (
            $partnerUser
            && Schema::connection('pgsql_auth')->hasColumn('partner_otps', 'partner_user_id')
        ) {
            $otpPayload['partner_user_id'] = $partnerUser->id;
        }

        PartnerOtp::create($otpPayload);

        $mailTo = trim((string) ($partnerUser?->email ?: $partner->email));
        $smsTo = trim((string) ($partnerUser?->mobile ?: $partner->mobile ?? ''));

        if ($mailTo !== '') {
            try {
                Mail::to($mailTo)->send(new PartnerOtpMail($otp));
            } catch (\Throwable $e) {
                Log::error('Failed to send OTP email', [
                    'email' => $mailTo,
                    'partner_id' => $partner->id,
                    'partner_user_id' => $partnerUser?->id,
                    'type' => $type,
                    'error' => $e->getMessage(),
                ]);
            }
        }

        $this->sendOtpSms($smsTo, (string) $otp, $ttlMinutes, $type);
    }

    /**
     * Resolve login actor: Partner owner first, else active PartnerUser + parent Partner.
     *
     * @return array{partner: ?Partner, partner_user: ?PartnerUser, login_as: string}
     */
    private function resolvePartnerLoginActor(string $loginField, string $identifier): array
    {
        $partner = null;
        $partnerUser = null;
        $loginAs = 'partner';

        if ($loginField === 'email') {
            $partner = Partner::where('email', $identifier)->first();
            if ($partner && !$partner->email_verified) {
                $partner = null;
            }
            if (!$partner) {
                $partnerUser = PartnerUser::query()
                    ->where('email', $identifier)
                    ->where(function ($q) {
                        $q->whereNull('status')
                            ->orWhereRaw('LOWER(TRIM(status)) = ?', ['active']);
                    })
                    ->first();
            }
        } else {
            $partner = Partner::where('mobile', $identifier)->first();
            if (!$partner) {
                $partnerUser = PartnerUser::query()
                    ->where('mobile', $identifier)
                    ->where(function ($q) {
                        $q->whereNull('status')
                            ->orWhereRaw('LOWER(TRIM(status)) = ?', ['active']);
                    })
                    ->first();
            }
        }

        if ($partnerUser) {
            $parent = Partner::query()->whereKey((int) $partnerUser->partner_id)->first();
            if (!$parent) {
                return [
                    'partner' => null,
                    'partner_user' => null,
                    'login_as' => 'partner',
                ];
            }
            $partner = $parent;
            $loginAs = 'partner_user';
        }

        return [
            'partner' => $partner,
            'partner_user' => $partnerUser,
            'login_as' => $loginAs,
        ];
    }

    public function createAndSendOtp_for_user(User $user, string $type = 'verify_email', int $ttlMinutes = 10): void
    {
        $otp = random_int(100000, 999999);

        EmailOtp::create([
            'user_id' => $user->id,
            'otp' => $otp,
            'type' => $type,
            'expires_at' => now()->addMinutes($ttlMinutes),
            'verified' => 0,
        ]);

        try {
            Mail::to($user->email)->send(new UserOtpMail($otp, (string) ($user->name ?? 'User')));
        } catch (\Throwable $e) {
            Log::error('Failed to send user OTP email', [
                'email' => $user->email,
                'user_id' => $user->id,
                'type' => $type,
                'error' => $e->getMessage(),
            ]);
        }

        $this->sendOtpSms((string) ($user->mobile ?? ''), (string) $otp, $ttlMinutes, $type);
    }

    private function sendOtpSms(string $mobile, string $otp, int $expiryMinutes, string $type): void
    {
        $minutes = $expiryMinutes > 0 ? $expiryMinutes : 5;
        $sent = app(\App\Services\SmsService::class)->sendOtpRegistration(
            $mobile,
            $otp,
            $minutes
        );

        if (!$sent) {
            Log::warning('Partner OTP SMS sending failed.', [
                'number' => $mobile,
                'type' => $type,
            ]);
        }

        if ($mobile !== '' && class_exists(\App\Services\WhatsAppService::class)) {
            try {
                Log::info('Partner OTP WhatsApp attempt', [
                    'number' => $mobile,
                    'type' => $type,
                    'minutes' => $minutes,
                ]);
                $waSent = app(\App\Services\WhatsAppService::class)->sendRegistrationOtp($mobile, $otp, $minutes);
                Log::info('Partner OTP WhatsApp result', [
                    'number' => $mobile,
                    'type' => $type,
                    'success' => $waSent,
                ]);
                if (!$waSent) {
                    Log::warning('Partner OTP WhatsApp sending failed.', [
                        'number' => $mobile,
                        'type' => $type,
                    ]);
                }
            } catch (\Throwable $e) {
                Log::warning('Partner OTP WhatsApp exception.', [
                    'number' => $mobile,
                    'type' => $type,
                    'error' => $e->getMessage(),
                ]);
            }
        }
    }

    private function getSmsGatewaySettings(): array
    {
        $row = SmsSetting::where('provider', 'jmd_sms')
            ->where('is_active', 1)
            ->orderBy('id', 'desc')
            ->first();

        if (!$row) {
            return [];
        }

        return [
            'base_url' => (string) ($row->base_url ?? ''),
            'user' => (string) ($row->user ?? ''),
            'password' => (string) ($row->password ?? ''),
            'senderid' => (string) ($row->senderid ?? ''),
            'channel' => (string) ($row->channel ?? ''),
            'dcs' => (string) ($row->dcs ?? ''),
            'flashsms' => (string) ($row->flashsms ?? ''),
            'route' => (string) ($row->route ?? ''),
            'peid' => (string) ($row->peid ?? ''),
            'template_id' => (string) ($row->template_id ?? ''),
        ];
    }

    private function normalizeIndianMobile(string $mobile): ?string
    {
        $digits = preg_replace('/\D+/', '', $mobile);
        if (!is_string($digits) || $digits === '') {
            return null;
        }

        if (str_starts_with($digits, '00')) {
            $digits = substr($digits, 2);
        }

        if (strlen($digits) === 11 && str_starts_with($digits, '0')) {
            $digits = substr($digits, 1);
        }

        if (strlen($digits) === 10) {
            return '91' . $digits;
        }

        if (strlen($digits) >= 11 && strlen($digits) <= 15) {
            return $digits;
        }

        return null;
    }

    public function verifyUserOtp_for_user(User $user, string $otp, string $type = 'verify_email'): bool
    {
        $otpRecord = EmailOtp::where('user_id', $user->id)
            ->where('otp', $otp)
            ->where('type', $type)
            ->where('verified', 0)
            ->where('expires_at', '>', now())
            ->latest('id')
            ->first();

        if (!$otpRecord) {
            return false;
        }

        $otpRecord->update(['verified' => 1]);
        return true;
    }

    /**
     * Logged-in partner (Bearer token) or partner_id from request/query/body.
     */
    private function resolvePartnerId(Request $request): ?int
    {
        $user = $request->user();
        if ($user instanceof Partner) {
            return (int) $user->id;
        }

        if ($request->bearerToken()) {
            $accessToken = PersonalAccessToken::findToken($request->bearerToken());
            if ($accessToken && $accessToken->tokenable instanceof Partner) {
                return (int) $accessToken->tokenable->id;
            }
        }

        $raw = $this->firstNonEmptyRequestValue($request, [
            'partner_id',
            'partnerId',
            'partnerID',
            'data.partner_id',
            'data.partnerId',
        ]);
        if ($raw === null) {
            return null;
        }

        $id = (int) $raw;

        return $id > 0 ? $id : null;
    }

    /**
     * First non-empty scalar from request body, query string, or nested keys.
     */
    private function firstNonEmptyRequestValue(Request $request, array $keys): mixed
    {
        foreach ($keys as $key) {
            $value = str_contains($key, '.')
                ? data_get($request->all(), $key)
                : $request->input($key, $request->query($key));

            if ($this->isPresentRequestScalar($value)) {
                return $value;
            }
        }

        return null;
    }

    private function isPresentRequestScalar(mixed $value): bool
    {
        if ($value === null) {
            return false;
        }

        if (is_string($value)) {
            return trim($value) !== '';
        }

        if (is_numeric($value)) {
            return (int) $value > 0;
        }

        return false;
    }

    /**
     * Login profile payload.
     * Always: id + partner_id = partners.id (company).
     * When partner user logs in: partner_user_id + name/email/mobile from partner_users.
     */
    private function partnerPayload(Partner $partner, ?PartnerUser $partnerUser = null): array
    {
        // Always partners table primary key (company account id)
        $companyPartnerId = (int) $partner->id;

        if ($partnerUser) {
            return [
                'id' => $companyPartnerId,
                'partner_id' => $companyPartnerId,
                'partner_user_id' => (int) $partnerUser->id,
                'name' => (string) ($partnerUser->name ?? $partner->name ?? ''),
                'email' => (string) ($partnerUser->email ?? $partner->email ?? ''),
                'mobile' => (string) ($partnerUser->mobile ?? $partner->mobile ?? ''),
                'company_name' => (string) ($partner->company_name ?? ''),
                'email_verified' => (bool) $partner->email_verified,
                'login_as' => 'partner_user',
            ];
        }

        return [
            'id' => $companyPartnerId,
            'partner_id' => $companyPartnerId,
            'partner_user_id' => null,
            'name' => (string) ($partner->name ?? ''),
            'email' => (string) ($partner->email ?? ''),
            'mobile' => (string) ($partner->mobile ?? ''),
            'company_name' => (string) ($partner->company_name ?? ''),
            'email_verified' => (bool) $partner->email_verified,
            'login_as' => 'partner',
        ];
    }

