    public function createPromotion(Request $request)
    {
        try {
            // Validation rules
            $validator = Validator::make($request->all(), [
                'code' => 'required|string|max:50|unique:promocodes,code',
                'discount_percent' => 'required|integer|min:1|max:100',
                'status' => 'sometimes|boolean|in:0,1',
            ]);

            if ($validator->fails()) {
                return response()->json([
                    'success' => false,
                    'message' => 'Validation failed',
                    'errors' => $validator->errors()
                ], 422);
            }

            // Create promocode
            $promocode = Promocode::create([
                'code' => strtoupper($request->code),
                'discount_percent' => $request->discount_percent,
                'status' => $request->status ?? 1,
            ]);

            return response()->json([
                'success' => true,
                'message' => 'Promotion created successfully',
                'data' => [
                    'id' => $promocode->id,
                    'code' => $promocode->code,
                    'discount_percent' => $promocode->discount_percent,
                    'status' => $promocode->status,
                    'created_at' => optional($promocode->created_at)->format('d-m-Y H:i:s'),
                    'updated_at' => optional($promocode->updated_at)->format('d-m-Y H:i:s'),
                ]
            ], 201);
        } catch (\Throwable $e) {
            return response()->json([
                'success' => false,
                'message' => 'Failed to create promotion: ' . $e->getMessage()
            ], 500);
        }
    }


