    public function updatePromotion(Request $request, $id)
    {
        try {
            $promocode = Promocode::find($id);

            if (!$promocode) {
                return response()->json([
                    'success' => false,
                    'message' => 'Promotion not found'
                ], 404);
            }

            // Validation rules
            $validator = Validator::make($request->all(), [
                'code' => 'sometimes|string|max:50|unique:promocodes,code,' . $id,
                'discount_percent' => 'sometimes|integer|min:1|max:100',
                'status' => 'sometimes|boolean|in:0,1',
            ]);

            if ($validator->fails()) {
                return response()->json([
                    'success' => false,
                    'message' => 'Validation failed',
                    'errors' => $validator->errors()
                ], 422);
            }

            // Update promocode
            if ($request->has('code')) {
                $promocode->code = strtoupper($request->code);
            }
            if ($request->has('discount_percent')) {
                $promocode->discount_percent = $request->discount_percent;
            }
            if ($request->has('status')) {
                $promocode->status = $request->status;
            }

            $promocode->save();

            return response()->json([
                'success' => true,
                'message' => 'Promotion updated successfully',
                'data' => [
                    'id' => $promocode->id,
                    'code' => $promocode->code,
                    'discount_percent' => $promocode->discount_percent,
                    'status' => $promocode->status,
                    'created_at' => optional($promocode->created_at)->format('d-m-Y H:i:s'),
                    'updated_at' => optional($promocode->updated_at)->format('d-m-Y H:i:s'),
                ]
            ]);
        } catch (\Throwable $e) {
            return response()->json([
                'success' => false,
                'message' => 'Failed to update promotion: ' . $e->getMessage()
            ], 500);
        }
    }

