    public function validateCoupon(Request $request)
    {
        try {
            $validator = Validator::make($request->all(), [
                'code' => 'required|string|exists:promocodes,code',
                'order_amount' => 'nullable|numeric|min:0'
            ]);

            if ($validator->fails()) {
                return response()->json([
                    'success' => false,
                    'message' => 'Validation failed',
                    'errors' => $validator->errors()
                ], 422);
            }

            $promocode = Promocode::where('code', strtoupper($request->code))->first();

            // Check if promocode exists
            if (!$promocode) {
                return response()->json([
                    'success' => false,
                    'message' => 'Invalid coupon code'
                ], 404);
            }

            // Check promocode status
            if ($promocode->status == 1) { // Active
                // Calculate discount if order amount is provided
                $discountAmount = 0;
                $finalAmount = null;

                if ($request->has('order_amount') && $request->order_amount > 0) {
                    $discountAmount = ($request->order_amount * $promocode->discount_percent) / 100;
                    $finalAmount = $request->order_amount - $discountAmount;
                }

                return response()->json([
                    'success' => true,
                    'message' => 'Coupon applied successfully',
                    'data' => [
                        'id' => $promocode->id,
                        'code' => $promocode->code,
                        'discount_percent' => $promocode->discount_percent,
                        'formatted_discount' => $promocode->formatted_discount,
                        'status' => $promocode->status,
                        'is_valid' => true,
                        'original_amount' => $request->order_amount ?? null,
                        'discount_amount' => $discountAmount > 0 ? round($discountAmount, 2) : null,
                        'final_amount' => $finalAmount ? round($finalAmount, 2) : null,
                        'created_at' => optional($promocode->created_at)->format('d-m-Y H:i:s'),
                        'updated_at' => optional($promocode->updated_at)->format('d-m-Y H:i:s'),
                    ]
                ]);
            } else { // Disactive
                return response()->json([
                    'success' => false,
                    'message' => 'Invalid Coupon',
                    'status' => $promocode->status,
                    'is_valid' => false,
                ], 400);
            }
        } catch (\Throwable $e) {
            return response()->json([
                'success' => false,
                'message' => 'Failed to validate coupon: ' . $e->getMessage()
            ], 500);
        }
    }

