    public function orderindex(Request $request)
    {
        try {
            $pid = $request->partner_id ?? $request->query('partner_id');

            if (!$pid) {
                return response()->json([
                    'success' => false,
                    'message' => 'partner_id is required'
                ], 422);
            }

            // Pagination (POST body or query — route is POST /order-list)
            $perPage = (int) $request->input('per_page', 10);
            $pageNo = (int) $request->input('page_no', $request->input('page', 1));
            $perPage = $perPage > 0 ? $perPage : 10;
            $pageNo = $pageNo > 0 ? $pageNo : 1;
            $today = now();

            // Use pagination for orders
            $ordersQuery = Order::with(['customer', 'plan'])
                ->where('partner_id', $pid)
                ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) != 'draft'")
                // Completed downgrade CH marked status=upgraded must not appear in order-list
                ->whereRaw("NOT (
                    LOWER(TRIM(COALESCE(status, ''))) = 'upgraded'
                    AND LOWER(TRIM(COALESCE(order_category, ''))) = 'downgrade'
                )")
                ->orderByDesc('id');

            $providerId = (int) ($request->input('provider_id') ?? $request->query('provider_id') ?? $request->input('providerId') ?? $request->provider_id ?? 0);
            if ($providerId > 0) {
                $planIds = Plan::query()->where('provider_id', $providerId)->pluck('id')->all();
                $hasProviderCol = Schema::connection('pgsql_billing')->hasColumn('orders', 'provider_id');

                $ordersQuery->where(function ($q) use ($providerId, $planIds, $hasProviderCol) {
                    if ($hasProviderCol) {
                        $q->where('provider_id', $providerId);
                    }

                    if (!empty($planIds)) {
                        if ($hasProviderCol) {
                            $q->orWhereIn('plan_id', $planIds)
                                ->orWhereHas('items', function ($itemQ) use ($planIds) {
                                    $itemQ->whereIn('plan_id', $planIds);
                                });
                        } else {
                            $q->whereIn('plan_id', $planIds)
                                ->orWhereHas('items', function ($itemQ) use ($planIds) {
                                    $itemQ->whereIn('plan_id', $planIds);
                                });
                        }
                    } elseif (!$hasProviderCol) {
                        $q->whereRaw('1 = 0');
                    }
                });
            }

            $customerId = (int) ($request->input('customer_id') ?? $request->query('customer_id') ?? $request->input('customerId') ?? $request->input('user_id') ?? 0);
            if ($customerId > 0) {
                $ordersQuery->where('user_id', $customerId);
            }

            // search: order no, domain, customer name/company/email/mobile, plan name (case-insensitive)
            $search = trim((string) $request->input('search', ''));
            if ($search !== '') {
                $like = '%' . addcslashes($search, '%_\\') . '%';
                $searchPlanIds = Plan::query()->where('name', 'ILIKE', $like)->pluck('id')->all();
                $ordersQuery->where(function ($q) use ($like, $searchPlanIds) {
                    $q->where('order_no', 'ILIKE', $like)
                        ->orWhere('domain_name', 'ILIKE', $like)
                        ->orWhereHas('customer', function ($c) use ($like) {
                            $c->where('name', 'ILIKE', $like)
                                ->orWhere('company_name', 'ILIKE', $like)
                                ->orWhere('email', 'ILIKE', $like)
                                ->orWhereRaw('CAST(mobile AS TEXT) ILIKE ?', [$like]);
                        });
                    if ($searchPlanIds) {
                        $q->orWhereIn('plan_id', $searchPlanIds)
                            ->orWhereHas('items', fn ($i) => $i->whereIn('plan_id', $searchPlanIds));
                    }
                });
            }

            // status=active | expiring,expired (comma separated). Display status is computed below, so when it is
            // set every matching order is loaded, filtered on the computed status, then paginated in PHP.
            $statusFilter = collect(explode(',', strtolower((string) $request->input('status', ''))))
                ->map(fn ($s) => trim($s))
                ->filter(fn ($s) => $s !== '' && $s !== 'all')
                ->values()->all();
            if (in_array('processing', $statusFilter, true)) {
                $statusFilter[] = 'pending';
            }

            $paginatedOrders = $statusFilter
                ? $ordersQuery->paginate(max(1, (clone $ordersQuery)->reorder()->count()), ['*'], 'page', 1)
                : $ordersQuery->paginate($perPage, ['*'], 'page', $pageNo);

            $orders = $paginatedOrders->getCollection();

            $orderItemMap = OrderItem::with('plan')
                ->whereIn('order_id', $orders->pluck('id')->all())
                ->where(function ($q) {
                    $q->whereNull('status')
                        ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted')");
                })
                ->orderBy('id')
                ->get()
                ->groupBy('order_id');

            $planChangeContext = $this->buildPlanChangeContextForOrders($orders->pluck('id')->all());
            $supersededByParentId = $this->buildSupersededSubscriptionStatusByParentId(
                $orders->pluck('id')->map(fn($id) => (int) $id)->all()
            );
            $creditNotesByOrderId = app(\App\Services\OrderCancellationCreditNoteService::class)
                ->resolveCreditNotesByOrderIds($orders->pluck('id')->map(fn($id) => (int) $id)->all());
            $poByOrderId = OrderPoDetail::query()
                ->whereIn('order_id', $orders->pluck('id')->all())
                ->get()
                ->keyBy(fn($row) => (int) $row->order_id);

            // We'll use these variables to properly track each summary status
            $activeCount = 0;
            $expiringCount = 0;
            $expiredCount = 0;
            $processingCount = 0;

            $order_details = [];

            // Same plan rule as subscriptionDetails (loadActivatedLicenseAddChildren): a license-add child belongs to
            // the parent when its plan_id is empty / equal, or its order_items carry the parent plan.
            $parentPlanIdOf = fn ($parent) => (int) ($parent->plan_id ?? 0)
                ?: (int) optional($orderItemMap->get((int) $parent->id, collect())->first())->plan_id;
            $addonMatchesParentPlan = function ($child, int $parentPlanId): bool {
                $childPlanId = (int) ($child->plan_id ?? 0);
                if ($parentPlanId <= 0 || $childPlanId <= 0 || $childPlanId === $parentPlanId) {
                    return true;
                }

                return OrderItem::query()
                    ->where('order_id', (int) $child->id)
                    ->where('plan_id', $parentPlanId)
                    ->where(fn ($q) => $q->whereNull('status')
                        ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted')"))
                    ->exists();
            };

            // --- BUILD MAP OF LICENSE-ADD CHILDREN TO MERGE WITH PARENTS ---
            $pageOrderIds = $orders->pluck('id')->filter()->map(fn($id) => (int) $id)->values()->all();
            $validAddonStatuses = ['completed', 'paid', 'success', 'active', 'processing', 'pending'];
            $validAddonStatusesSql = "'" . implode("','", $validAddonStatuses) . "'";

            // 1. Get all license-add orders from current page
            $licenseAddOrders = $orders->filter(function ($order) {
                return $this->isLicenseAddOrder($order);
            });

            // Build map of parent_id => license-add child orders
            $licenseAddChildrenByParent = [];
            $licenseAddChildIds = [];
            foreach ($licenseAddOrders as $childOrder) {
                $parentId = (int) ($childOrder->parent_order_id ?? 0);
                if ($parentId > 0) {
                    if (!isset($licenseAddChildrenByParent[$parentId])) {
                        $licenseAddChildrenByParent[$parentId] = [];
                    }
                    $licenseAddChildrenByParent[$parentId][] = $childOrder;
                    $licenseAddChildIds[] = (int) $childOrder->id;
                }
            }

            // 2. Also query DB for children of all page orders (handles parent on page 1, child on page 2)
            if (!empty($pageOrderIds)) {
                $dbChildren = Order::query()
                    ->whereIn('parent_order_id', $pageOrderIds)
                    ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) IN ($validAddonStatusesSql)")
                    ->orderBy('id')
                    ->get()
                    ->filter(fn($child) => $this->isLicenseAddOrder($child));
              

                foreach ($dbChildren as $childOrder) {
                    $parentId = (int) ($childOrder->parent_order_id ?? 0);
                    if ($parentId > 0) {
                        if (!isset($licenseAddChildrenByParent[$parentId])) {
                            $licenseAddChildrenByParent[$parentId] = [];
                        }
                        if (!collect($licenseAddChildrenByParent[$parentId])->contains('id', $childOrder->id)) {
                            $licenseAddChildrenByParent[$parentId][] = $childOrder;
                        }
                        $licenseAddChildIds[] = (int) $childOrder->id;
                    }
                }

                // 3. Also match unlinked addon orders for the same partner_id + domain_name
                $domainsByPartner = [];
                foreach ($orders as $o) {
                    if (!empty($o->domain_name) && (int) $o->partner_id > 0) {
                        $domainsByPartner[(int) $o->partner_id][] = (string) $o->domain_name;
                    }
                }
                foreach ($domainsByPartner as $pId => $doms) {
                    $doms = array_values(array_unique(array_filter($doms)));
                    if (empty($doms)) continue;

                    $unlinkedAddons = Order::query()
                        ->where('partner_id', $pId)
                        ->whereIn('domain_name', $doms)
                        ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) IN ($validAddonStatusesSql)")
                        ->whereRaw("LOWER(TRIM(COALESCE(order_category, ''))) NOT IN ('renewal', 'renew', 'renewed', 'downgrade', 'downgraded')")
                        ->whereRaw("order_no NOT ILIKE 'RN%'")
                        ->whereRaw("order_no NOT ILIKE 'CH%'")
                        ->whereNotIn('id', $licenseAddChildIds)
                        ->orderBy('id')
                        ->get()
                        ->filter(fn($cand) => $this->isLicenseAddOrder($cand));

                    foreach ($unlinkedAddons as $unlinked) {
                        $matchingParent = $orders->first(function ($po) use ($unlinked, $parentPlanIdOf, $addonMatchesParentPlan) {
                            return (int) $po->id !== (int) $unlinked->id
                                && (int) $po->partner_id === (int) $unlinked->partner_id
                                && strcasecmp((string) $po->domain_name, (string) $unlinked->domain_name) === 0
                                && $addonMatchesParentPlan($unlinked, $parentPlanIdOf($po))
                                && empty($po->parent_order_id)
                                && !in_array(strtolower(trim((string) $po->order_category)), ['addon', 'license_add'], true)
                                && (int) $po->id < (int) $unlinked->id;
                        });

                        if ($matchingParent) {
                            $parentOrderId = (int) $matchingParent->id;
                            if (empty($unlinked->parent_order_id)) {
                                Order::where('id', $unlinked->id)->update([
                                    'parent_order_id' => $parentOrderId,
                                    'order_category' => in_array(strtolower(trim((string) ($unlinked->order_category ?? ''))), ['license_add', 'addon'], true) ? $unlinked->order_category : 'addon',
                                ]);
                                $unlinked->parent_order_id = $parentOrderId;
                                $unlinked->order_category = 'addon';
                            }
                            if (!isset($licenseAddChildrenByParent[$parentOrderId])) {
                                $licenseAddChildrenByParent[$parentOrderId] = [];
                            }
                            if (!collect($licenseAddChildrenByParent[$parentOrderId])->contains('id', $unlinked->id)) {
                                $licenseAddChildrenByParent[$parentOrderId][] = $unlinked;
                            }
                            $licenseAddChildIds[] = (int) $unlinked->id;
                        }
                    }
                }
            }
            $licenseAddChildIds = array_values(array_unique($licenseAddChildIds));

            // Track which parent orders have been merged
            $mergedParentIds = [];

            // Parent IDs that already have an *activated* RN/CH on this page.
            $parentsCoveredByPageChildren = [];
            foreach ($orders as $pageOrder) {
                if (!$this->isPartnerPlanChangeOrder($pageOrder)) {
                    continue;
                }
                if (!$this->isActivatedPlanChangeOrder($pageOrder)) {
                    continue;
                }
                $parentId = (int) ($pageOrder->parent_order_id ?? 0);
                if ($parentId <= 0) {
                    continue;
                }
                $parentsCoveredByPageChildren[$parentId]
                    = ($parentsCoveredByPageChildren[$parentId] ?? 0) + 1;
            }

            // --- FIRST PASS: Identify which parent orders should be merged ---
            // Only activated license-adds merge into parent (processing/pending stay as own rows).
            // Must match parent plan_id (same plan seats only).
            $activatedAddonStatuses = ['completed', 'paid', 'success', 'active'];
            $parentOrdersToMerge = [];
            foreach ($orders as $order) {
                $orderId = (int) $order->id;
                $parentPlanId = $parentPlanIdOf($order);
                if (isset($licenseAddChildrenByParent[$orderId])) {
                    $hasActivatedChild = false;
                    foreach ($licenseAddChildrenByParent[$orderId] as $child) {
                        $childStatus = strtolower(trim((string) ($child->status ?? '')));
                        if (
                            in_array($childStatus, $activatedAddonStatuses, true)
                            && $addonMatchesParentPlan($child, $parentPlanId)
                        ) {
                            $hasActivatedChild = true;
                            break;
                        }
                    }
                    if ($hasActivatedChild) {
                        $parentOrdersToMerge[$orderId] = true;
                    }
                }
            }

            foreach ($orders as $order) {
                $orderId = (int) $order->id;
                $parentId = (int) ($order->parent_order_id ?? 0);

                $orderStatus = strtolower(trim((string) ($order->status ?? '')));
                $orderCategory = strtolower(trim((string) ($order->order_category ?? '')));
                // status=upgraded + order_category=downgrade → hide from order-list
                if ($orderStatus === 'upgraded' && $orderCategory === 'downgrade') {
                    continue;
                }

                // --- CHECK IF THIS IS A LICENSE-ADD CHILD ---
                $isLicenseAdd = $this->isLicenseAddOrder($order) || in_array($orderId, $licenseAddChildIds, true);

                $isActivated = in_array($orderStatus, $activatedAddonStatuses, true);
                $samePlanAsParent = false;
                if ($isLicenseAdd && $parentId > 0) {
                    $parentOrder = $orders->firstWhere('id', $parentId) ?: Order::find($parentId);
                    $samePlanAsParent = $parentOrder !== null
                        && $addonMatchesParentPlan($order, $parentPlanIdOf($parentOrder));
                }

                // --- SKIP only activated same-plan license-add children (merge into parent) ---
                // processing / pending / different plan_id addon orders remain visible.
                if ($isLicenseAdd && $isActivated && $samePlanAsParent && ($parentId > 0 || in_array($orderId, $licenseAddChildIds, true))) {
                    continue;
                }
                if ($isLicenseAdd && $parentId > 0 && isset($parentOrdersToMerge[$parentId]) && $isActivated && $samePlanAsParent) {
                    continue;
                }

                // If this is a license-add child that is NOT activated (still processing), SHOW IT
                if ($isLicenseAdd && !$isActivated && $parentId > 0) {
                    // Show it as a separate order (processing state)
                    // Let it flow through to the normal processing logic
                }

                // CH/RN change orders must always appear (Downgrade/Upgrade/Renewal Pending).
                $isPlanChangeOrderSelf = $this->isPartnerPlanChangeOrder($order);

                // After activated downgrade: hide parent ORD (show CH only).
                // Single-plan / fully claimed parents stay hidden even if item status was not stamped.
                if (!$isPlanChangeOrderSelf) {
                    $dgChildren = $planChangeContext['child_change_orders_by_parent']->get($orderId, collect());
                    if ($dgChildren->isEmpty()) {
                        $dgChildren = Order::query()
                            ->where('parent_order_id', $orderId)
                            ->where(function ($q) {
                                $q->whereRaw("LOWER(TRIM(COALESCE(order_category, ''))) IN ('downgrade', 'downgraded')")
                                    ->orWhereRaw("UPPER(TRIM(COALESCE(order_no, ''))) LIKE 'CH%'");
                            })
                            ->get();
                    }
                    $activatedDowngradeChildren = $dgChildren->filter(function ($child) {
                        $cat = strtolower(trim((string) ($child->order_category ?? '')));
                        $kind = $this->isPartnerPlanChangeOrder($child)
                            ? $this->partnerPlanChangeOrderKind($child)
                            : null;
                        if (!($kind === 'downgrade' || in_array($cat, ['downgrade', 'downgraded'], true))) {
                            return false;
                        }
                        if ($this->isActivatedPlanChangeOrder($child)) {
                            return true;
                        }
                        // Fallback: category=downgrade + live status (even if order_no is atypical)
                        $st = strtolower(trim((string) ($child->status ?? '')));

                        return in_array($st, ['completed', 'paid', 'success', 'active', 'upgraded', 'downgraded'], true);
                    });

                    if ($activatedDowngradeChildren->isNotEmpty()) {
                        $dgParentItems = $this->uniqueSubscriptionOrderItems(
                            $orderItemMap->get($orderId, collect())
                        );
                        $dgLeftoverLive = $dgParentItems->filter(function ($item) {
                            $s = strtolower(trim((string) ($item->status ?? 'active')));
                            if ($s === '') {
                                $s = 'active';
                            }

                            return !in_array($s, ['delete', 'deleted', 'upgraded', 'downgraded', 'renewed'], true);
                        });

                        // Full downgrade / single plan line → parent must not appear in order-list
                        if ($dgLeftoverLive->isEmpty() || $dgParentItems->count() <= 1) {
                            continue;
                        }
                    }
                }

                // Same-page RN/CH already covers this ORD → drop parent only when NO leftover
                // unclaimed Active plans remain. Never hide just because 1 plan is left
                // (3 plans → upgrade 1 → upgrade 1 more → 1 Active must still show).
                if (
                    isset($parentsCoveredByPageChildren[(int) $order->id])
                ) {
                    $pageItems = $this->uniqueSubscriptionOrderItems(
                        $orderItemMap->get((int) $order->id, collect())
                    );
                    $pageChildren = $planChangeContext['child_change_orders_by_parent']->get((int) $order->id, collect());
                    $pageUpgradeState = $this->buildUpgradeStateBySourceSubId(
                        (int) $order->id,
                        $pageChildren,
                        $planChangeContext['child_order_items'],
                        $planChangeContext['new_plans_by_id']
                    );
                    $pageUnclaimedActive = $pageItems->filter(function ($item) use ($pageUpgradeState, $pageChildren, $planChangeContext) {
                        return $this->parentSourceLineRemainsOnParent(
                            $item,
                            $pageUpgradeState,
                            $planChangeContext['child_order_items'],
                            $pageChildren
                        );
                    })->count();

                    if ($pageUnclaimedActive === 0) {
                        continue;
                    }
                }

                // Hide parent ORD only after every remaining line is claimed by an *activated* child.
                if (true) {
                    $earlyChildren = $planChangeContext['child_change_orders_by_parent']->get((int) $order->id, collect());
                    $liveChangeChildCount = $earlyChildren->filter(function ($child) {
                        return $this->isActivatedPlanChangeOrder($child);
                    })->count();

                    if ($liveChangeChildCount > 0) {
                        $earlyItems = $this->uniqueSubscriptionOrderItems(
                            $orderItemMap->get((int) $order->id, collect())
                        );
                        $earlyUpgradeState = $this->buildUpgradeStateBySourceSubId(
                            (int) $order->id,
                            $earlyChildren,
                            $planChangeContext['child_order_items'],
                            $planChangeContext['new_plans_by_id']
                        );
                        $earlyUnclaimedActive = $earlyItems->filter(function ($item) use ($earlyUpgradeState, $earlyChildren, $planChangeContext) {
                            return $this->parentSourceLineRemainsOnParent(
                                $item,
                                $earlyUpgradeState,
                                $planChangeContext['child_order_items'],
                                $earlyChildren
                            );
                        })->count();

                        if ($earlyUnclaimedActive === 0) {
                            continue;
                        }
                    }
                }

                $orderItems = $this->uniqueSubscriptionOrderItems(
                    $orderItemMap->get((int) $order->id, collect())
                );

                // --- MERGE LICENSE-ADD CHILDREN INTO PARENT ---
                $hasMergedLicenseAdd = false;
                $mergedExtraLicenses = 0;
                $mergedLicenseAddOrders = [];

                if (isset($licenseAddChildrenByParent[$orderId])) {
                    $parentPlanId = $parentPlanIdOf($order);
                    foreach ($licenseAddChildrenByParent[$orderId] as $child) {
                        $childStatus = strtolower(trim((string) ($child->status ?? '')));
                        // Activated + same plan (subscriptionDetails rule) — merge into parent
                        if (
                            in_array($childStatus, $activatedAddonStatuses, true)
                            && $addonMatchesParentPlan($child, $parentPlanId)
                        ) {
                            $hasMergedLicenseAdd = true;
                            $childItems = OrderItem::query()
                                ->where('order_id', $child->id)
                                ->where(function ($q) {
                                    $q->whereNull('status')
                                        ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted')");
                                })
                                ->get();

                            $childQtySum = 0;
                            foreach ($childItems as $childItem) {
                                // Only seats for the same plan_id
                                if ((int) ($childItem->plan_id ?? 0) > 0
                                    && (int) ($childItem->plan_id ?? 0) !== $parentPlanId) {
                                    continue;
                                }
                                $childQtySum += max(1, (int) ($childItem->quantity ?? 1));
                            }
                            if ($childQtySum <= 0) {
                                $childQtySum = max(1, (int) ($child->quantity ?? $child->licenses ?? 1));
                            }
                            $mergedExtraLicenses += $childQtySum;
                            $mergedLicenseAddOrders[] = $child;
                            $mergedParentIds[$orderId] = true;
                        }
                    }
                }

                // --- UPDATE PARENT ITEMS WITH MERGED LICENSES ---
                if ($hasMergedLicenseAdd && $orderItems->isNotEmpty()) {
                    $parentPlanId = (int) ($order->plan_id ?? 0);
                    foreach ($mergedLicenseAddOrders as $childOrder) {
                        $childItems = OrderItem::query()
                            ->where('order_id', $childOrder->id)
                            ->where(function ($q) {
                                $q->whereNull('status')
                                    ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted')");
                            })
                            ->get();

                        if ($childItems->isNotEmpty()) {
                            foreach ($childItems as $childItem) {
                                $itemPlanId = (int) ($childItem->plan_id ?? 0);
                                if ($itemPlanId > 0 && $parentPlanId > 0 && $itemPlanId !== $parentPlanId) {
                                    continue;
                                }
                                $addQty = max(1, (int) ($childItem->quantity ?? 1));
                                // Same plan_id line only (no cross-plan fallback)
                                $parentItem = $orderItems->first(function ($item) use ($childItem, $parentPlanId) {
                                    $pid = (int) ($item->plan_id ?? 0);
                                    $cid = (int) ($childItem->plan_id ?? 0);
                                    if ($cid > 0) {
                                        return $pid === $cid;
                                    }
                                    return $parentPlanId > 0 && $pid === $parentPlanId;
                                });

                                if ($parentItem) {
                                    $newQuantity = ((int) ($parentItem->quantity ?? 1)) + $addQty;
                                    $parentItem->quantity = $newQuantity;
                                    $unitPrice = (float) ($parentItem->unit_price ?? 0);
                                    $parentItem->total_amount = round($unitPrice * $newQuantity, 2);
                                }
                            }
                        } else {
                            $childQty = max(1, (int) ($childOrder->quantity ?? $childOrder->licenses ?? 1));
                            $parentItem = $orderItems->first(function ($item) use ($childOrder, $parentPlanId) {
                                $pid = (int) ($item->plan_id ?? 0);
                                $cid = (int) ($childOrder->plan_id ?? 0);
                                if ($cid > 0) {
                                    return $pid === $cid;
                                }
                                return $parentPlanId > 0 && $pid === $parentPlanId;
                            });
                            if ($parentItem) {
                                $newQuantity = ((int) ($parentItem->quantity ?? 1)) + $childQty;
                                $parentItem->quantity = $newQuantity;
                                $unitPrice = (float) ($parentItem->unit_price ?? 0);
                                $parentItem->total_amount = round($unitPrice * $newQuantity, 2);
                            }
                        }
                    }

                    $order->quantity = ((int) ($order->quantity ?? 1)) + $mergedExtraLicenses;
                    $order->licenses = $order->quantity;
                }

                $replacement = $supersededByParentId[(int) $order->id] ?? null;
                $partial = $this->resolvePartialReplacementForOrder($order, $orderItems, $replacement);
                $remainingAfterReplace = $partial['remaining_licenses'];
                $pendingRenewalLicenses = (int) ($partial['pending_renewal_licenses'] ?? 0);
                $liveItems = $partial['live_items'];
                $liveQty = $partial['live_qty'];
                // License-add seats are additive — never let upgrade leftover math wipe the merge.
                if ($hasMergedLicenseAdd && $mergedExtraLicenses > 0) {
                    $mergedLiveQty = (int) $orderItems->sum(fn($row) => max(1, (int) ($row->quantity ?? 1)));
                    if ($mergedLiveQty <= 0) {
                        $mergedLiveQty = max(1, (int) ($order->quantity ?? $order->licenses ?? 1));
                    }
                    $liveQty = max($liveQty, $mergedLiveQty);
                    $remainingAfterReplace = max($remainingAfterReplace, $mergedLiveQty);
                    $partial['live_qty'] = $liveQty;
                    $partial['remaining_licenses'] = $remainingAfterReplace;
                }
                $treatAsLive = $remainingAfterReplace > 0;
                $supersededStatus = $treatAsLive ? null : $partial['superseded_status'];

                $orderLevel = $this->resolveSubscriptionOrderLevelStatus(
                    $order,
                    $today,
                    $orderItems,
                    $supersededStatus,
                    $treatAsLive
                );
                $daysToExpire = $orderLevel['days_to_expire'];

                $orderStatus = strtolower(trim((string) ($order->status ?? '')));
                $isCancelledOrder = in_array($orderStatus, ['cancelled', 'canceled', 'rejected'], true);

                $childChangeOrders = $planChangeContext['child_change_orders_by_parent']->get((int) $order->id, collect());
                $upgradeStateBySourceSubId = $this->buildUpgradeStateBySourceSubId(
                    (int) $order->id,
                    $childChangeOrders,
                    $planChangeContext['child_order_items'],
                    $planChangeContext['new_plans_by_id']
                );

                // Visible plan lines for THIS order (hide upgraded/pending source plans).
                $visibleLines = [];
                foreach ($orderItems as $item) {
                    $itemStatus = strtolower(trim((string) ($item->status ?? 'active')));
                    if ($itemStatus === '') {
                        $itemStatus = 'active';
                    }
                    if (in_array($itemStatus, ['delete', 'deleted'], true)) {
                        continue;
                    }

                    $itemQty = max(1, (int) ($item->quantity ?? 1));
                    $pendingListChangeQty = (int) ($partial['pending_upgrade_licenses'] ?? 0)
                        + (int) ($partial['pending_downgrade_licenses'] ?? 0)
                        + (int) ($partial['pending_renewal_licenses'] ?? 0);
                    // Do not clamp after license-add merge — that was resetting e.g. 10 → 2.
                    if (
                        !$hasMergedLicenseAdd
                        && !$isCancelledOrder
                        && $treatAsLive
                        && $remainingAfterReplace > 0
                        && in_array($itemStatus, ['active', 'completed', 'paid', 'success'], true)
                        && $itemQty > $remainingAfterReplace
                        && $liveItems->count() <= 1
                    ) {
                        $itemQty = $remainingAfterReplace;
                    }

                    $planChangeStatus = $this->resolvePlanChangeStatusForItem(
                        $item,
                        (int) $order->id,
                        $upgradeStateBySourceSubId,
                        $childChangeOrders,
                        $planChangeContext['child_order_items'],
                        $planChangeContext['new_plans_by_id']
                    );

                    $planLineDisplay = $this->resolveSubscriptionPlanLineDisplay(
                        $order,
                        $planChangeStatus,
                        $itemStatus,
                        $orderLevel['status'],
                        $partial,
                        is_array($replacement) ? $replacement : null,
                        $treatAsLive,
                        (bool) ($partial['is_fully_replaced'] ?? false)
                    );
                    $resolvedPlanChangeStatus = (string) ($planLineDisplay['plan_change_status'] ?? $planChangeStatus);
                    $lineStatus = (string) ($planLineDisplay['status'] ?? $orderLevel['status']);
                    $lineStatus = $this->preferPlanWiseStatus(
                        $order,
                        $itemStatus,
                        $resolvedPlanChangeStatus,
                        $lineStatus,
                        $isCancelledOrder
                    );

                    $movedLicenses = $this->resolveMovedLicensesForSourceLine(
                        (int) ($item->id ?? 0),
                        $upgradeStateBySourceSubId,
                        $planChangeContext['child_order_items'],
                        $childChangeOrders
                    );

                    $lineHideUpgrade = !$isCancelledOrder && (
                        $this->isPendingPlanChangeOrder($order)
                        || in_array(strtolower($resolvedPlanChangeStatus), [
                            'upgrade_pending',
                            'downgrade_pending',
                            'renewal_pending',
                            'upgraded',
                            'downgraded',
                            'renewed',
                        ], true)
                        || in_array($itemStatus, ['upgraded', 'downgraded', 'renewed'], true)
                    );

                    if ($this->shouldHideReplacedSourcePlanFromCurrentList($order, $itemStatus, $resolvedPlanChangeStatus, $lineStatus)) {
                        $leftoverQty = $this->leftoverQtyAfterPlanChange(
                            $itemQty,
                            $movedLicenses,
                            $itemStatus,
                            $this->mappedChangeIsSamePlan($item, $upgradeStateBySourceSubId)
                        );
                        if ($leftoverQty !== null && $leftoverQty > 0) {
                            $itemQty = $leftoverQty;
                            $resolvedPlanChangeStatus = 'active';
                            $lineStatus = (string) ($orderLevel['status'] ?? 'Active');
                            if (in_array(strtolower($lineStatus), ['upgrade pending', 'downgrade pending', 'renewal pending', 'upgraded', 'downgraded', 'renewed'], true)) {
                                $lineStatus = in_array(strtolower($orderStatus), ['pending', 'processing', 'draft'], true) ? (
                                    $orderStatus === 'draft' ? 'Draft' : ($orderStatus === 'pending' ? 'Pending' : 'Processing')
                                ) : 'Active';
                            }
                            $lineHideUpgrade = false;
                        } else {
                            continue;
                        }
                    } elseif (
                        !$isPlanChangeOrderSelf
                        && in_array(strtolower($resolvedPlanChangeStatus), [
                            'upgrade_pending',
                            'downgrade_pending',
                            'renewal_pending',
                        ], true)
                    ) {
                        $lineStatus = in_array(strtolower($orderStatus), ['pending', 'processing', 'draft'], true) ? (
                            $orderStatus === 'draft' ? 'Draft' : ($orderStatus === 'pending' ? 'Pending' : 'Processing')
                        ) : 'Active';
                        $resolvedPlanChangeStatus = 'active';
                        $lineHideUpgrade = true;
                    }

                    $plan = $item->plan ?? Plan::where('id', $item->plan_id)->first();
                    $lineUpgradeFlags = $this->upgradeButtonFlags(!$lineHideUpgrade, null, [
                        'provider_id' => (int) ($plan->provider_id ?? $provider_id ?? 0),
                    ]);
                    $visibleLines[] = [
                        'item' => $item,
                        'plan' => $plan,
                        'qty' => $itemQty,
                        'item_status' => $itemStatus,
                        'plan_change_status' => $resolvedPlanChangeStatus,
                        'status' => $lineStatus,
                        'renewal_status' => $planLineDisplay['renewal_status'] ?? null,
                        'can_upgrade' => $lineUpgradeFlags['can_upgrade'],
                        'can_partial_upgrade' => $lineUpgradeFlags['can_partial_upgrade'],
                        'can_add_license' => $lineUpgradeFlags['can_add_license'],
                        'hide_upgrade' => $lineUpgradeFlags['hide_upgrade'],
                        'hide_partial_upgrade' => $lineUpgradeFlags['hide_partial_upgrade'],
                        'change_via' => $lineUpgradeFlags['change_via'],
                        'requires_request' => $lineUpgradeFlags['requires_request'],
                    ];
                }

                if ($visibleLines === []) {
                    if (
                        $orderItems->isNotEmpty()
                        && $childChangeOrders->contains(fn($child) => $this->isActivatedPlanChangeOrder($child))
                    ) {
                        continue;
                    }
                    $plan = $order->plan ?? Plan::where('id', $order->plan_id)->first();
                    $changeKind = $this->partnerPlanChangeOrderKind($order);
                    $fallbackStatus = $orderLevel['status'];
                    if (
                        $isPlanChangeOrderSelf && $changeKind === 'downgrade'
                        && in_array($orderStatus, ['pending', 'processing'], true)
                    ) {
                        $fallbackStatus = 'Downgrade Pending';
                    } elseif (
                        $isPlanChangeOrderSelf && $changeKind === 'upgrade'
                        && in_array($orderStatus, ['pending', 'processing'], true)
                    ) {
                        $fallbackStatus = 'Upgrade Pending';
                    } elseif (
                        $isPlanChangeOrderSelf && $changeKind === 'renewal'
                        && in_array($orderStatus, ['pending', 'processing'], true)
                    ) {
                        $fallbackStatus = 'Renewal Pending';
                    }
                    $fallbackFlags = $this->upgradeButtonFlags(
                        $isCancelledOrder || !$this->isPendingPlanChangeOrder($order),
                        null,
                        ['provider_id' => (int) ($plan->provider_id ?? 0)]
                    );
                    $visibleLines[] = [
                        'item' => null,
                        'plan' => $plan,
                        'qty' => max(1, (int) ($liveQty > 0 ? $liveQty : ($order->quantity ?? 1))),
                        'item_status' => 'active',
                        'plan_change_status' => $changeKind ? ($changeKind . '_pending') : '',
                        'status' => $fallbackStatus,
                        'renewal_status' => null,
                        'can_upgrade' => $fallbackFlags['can_upgrade'],
                        'can_partial_upgrade' => $fallbackFlags['can_partial_upgrade'],
                        'can_add_license' => $fallbackFlags['can_add_license'],
                        'hide_upgrade' => $fallbackFlags['hide_upgrade'],
                        'hide_partial_upgrade' => $fallbackFlags['hide_partial_upgrade'],
                        'change_via' => $fallbackFlags['change_via'],
                        'requires_request' => $fallbackFlags['requires_request'],
                    ];
                }

                // Parent fully claimed by CH/RN → hide. Never apply this to the CH/RN row.
                $liveLines = $orderItems->filter(function ($item) {
                    $s = strtolower(trim((string) ($item->status ?? 'active')));
                    if ($s === '') {
                        $s = 'active';
                    }

                    return !in_array($s, ['delete', 'deleted'], true);
                })->values();

                $liveItemIds = $liveLines
                    ->map(fn($item) => (int) $item->id)
                    ->filter(fn($id) => $id > 0)
                    ->values();

                $activeChangeChildren = $childChangeOrders->filter(function ($child) {
                    return $this->isActivatedPlanChangeOrder($child);
                })->values();

                if ($liveLines->isNotEmpty() && $activeChangeChildren->isNotEmpty()) {
                    $remainingOnParent = $liveLines->filter(function ($item) use ($upgradeStateBySourceSubId, $childChangeOrders, $planChangeContext) {
                        return $this->parentSourceLineRemainsOnParent(
                            $item,
                            $upgradeStateBySourceSubId,
                            $planChangeContext['child_order_items'],
                            $childChangeOrders
                        );
                    });

                    if ($remainingOnParent->isEmpty() || ($partial['is_fully_replaced'] ?? false)) {
                        continue;
                    }
                }

                if (
                    $liveItemIds->isNotEmpty()
                    && $activeChangeChildren->isNotEmpty()
                    && $liveLines->every(function ($item) use ($upgradeStateBySourceSubId, $childChangeOrders, $planChangeContext) {
                        return !$this->parentSourceLineRemainsOnParent(
                            $item,
                            $upgradeStateBySourceSubId,
                            $planChangeContext['child_order_items'],
                            $childChangeOrders
                        );
                    })
                ) {
                    continue;
                }

                if ($childChangeOrders->isNotEmpty() && $activeChangeChildren->isNotEmpty()) {
                    $pendingChangeLicenses = (int) ($partial['pending_downgrade_licenses'] ?? 0)
                        + (int) ($partial['pending_upgrade_licenses'] ?? 0)
                        + (int) ($partial['pending_renewal_licenses'] ?? 0);
                    $hasPendingChild = $childChangeOrders->contains(fn($c) => $this->isPendingPlanChangeOrder($c));
                    if (!$hasPendingChild && $pendingChangeLicenses > 0 && $remainingAfterReplace <= 0) {
                        continue;
                    }
                    if ($visibleLines === [] && $activeChangeChildren->isNotEmpty() && !$hasPendingChild) {
                        continue;
                    }
                }

                $customer = Customer::where('id', $order->user_id)->first();
                $customerName = $customer ? $customer->company_name : '-';
                $customer_name = $customer ? $customer->name : '-';
                $domain = $order->domain_name ?? '-';
                $renewalDate = $order->subscription_end_date ? $order->subscription_end_date : '₹';
                $daysLeft = $daysToExpire !== null ? $daysToExpire : 'null';
                $transfer_domain = $order->transfer_domain ?? $order->domain_transfer ?? null;
                $categoryProbe = clone $order;
                $categoryProbe->transfer_domain = null;
                if (isset($categoryProbe->domain_transfer)) {
                    $categoryProbe->domain_transfer = null;
                }
                $enrollment_category = $this->resolveEnrollmentTypeLabel($categoryProbe);
                $transferFlag = strtolower(trim((string) $transfer_domain));
                $enrollment_type = in_array($transferFlag, ['yes', '1', 'true'], true)
                    ? 'Transfer Service'
                    : 'New Service';
                $creditNote = $creditNotesByOrderId[(int) $order->id] ?? null;
                $hasCreditNote = is_array($creditNote) && !empty($creditNote['credit_note_id'] ?? $creditNote['credit_note_no'] ?? null);
                $resolvedPo = $this->resolveParentOrderPoPayload((int) $order->id);

                $primary = $visibleLines[0];
                $plan = $primary['plan'];
                $provider_id = $plan ? $plan->provider_id : null;
                $planNames = collect($visibleLines)
                    ->map(fn($line) => trim((string) (optional($line['plan'])->name ?? '')))
                    ->filter()
                    ->values();
                $planName = (string) ($planNames->first() ?? '');
                $plansCount = max(1, $planNames->count());
                $totalLicenses = (int) collect($visibleLines)->sum('qty');
                if ($hasMergedLicenseAdd && (int) ($order->quantity ?? 0) > $totalLicenses) {
                    $totalLicenses = (int) $order->quantity;
                }
                if ($totalLicenses <= 0) {
                    $totalLicenses = max(1, (int) ($order->quantity ?? $order->licenses ?? 1));
                }

                $statusPriority = [
                    'upgrade pending' => 50,
                    'downgrade pending' => 49,
                    'renewal pending' => 48,
                    'processing' => 40,
                    'pending' => 39,
                    'expiring' => 30,
                    'expired' => 20,
                    'active' => 10,
                    'cancelled' => 5,
                ];
                $status = (string) ($primary['status'] ?? $orderLevel['status']);
                $renewalStatus = $primary['renewal_status'] ?? null;
                $planChangeStatus = (string) ($primary['plan_change_status'] ?? '');
                $itemStatus = (string) ($primary['item_status'] ?? 'active');
                $bestScore = $statusPriority[strtolower(trim($status))] ?? 0;
                foreach ($visibleLines as $line) {
                    $candidate = (string) ($line['status'] ?? '');
                    $score = $statusPriority[strtolower(trim($candidate))] ?? 0;
                    if ($score > $bestScore) {
                        $bestScore = $score;
                        $status = $candidate;
                        $renewalStatus = $line['renewal_status'] ?? $renewalStatus;
                        $planChangeStatus = (string) ($line['plan_change_status'] ?? $planChangeStatus);
                        $itemStatus = (string) ($line['item_status'] ?? $itemStatus);
                    }
                }

                if ($isPlanChangeOrderSelf) {
                    $status = $this->preferPlanWiseStatus(
                        $order,
                        $itemStatus,
                        $planChangeStatus,
                        $status,
                        $isCancelledOrder
                    );
                } elseif (!$isCancelledOrder) {
                    if (in_array($orderStatus, ['pending', 'processing', 'draft'], true)) {
                        $status = $orderStatus === 'draft' ? 'Draft' : ($orderStatus === 'pending' ? 'Pending' : 'Processing');
                        $planChangeStatus = 'processing';
                    } else {
                        $hasPendingChild = $childChangeOrders->contains(fn($c) => $this->isPendingPlanChangeOrder($c));
                        if ($hasPendingChild || $treatAsLive) {
                            if ($treatAsLive && !in_array(strtolower($status), ['expiring', 'expired'], true)) {
                                $status = 'Active';
                                $planChangeStatus = 'active';
                            }
                        }
                    }
                }

                // --- IF THIS PARENT HAS MERGED LICENSE-ADD CHILDREN, UPDATE STATUS ---
                if ($hasMergedLicenseAdd && !$isCancelledOrder) {
                    if (strtolower($status) !== 'active') {
                        $status = 'Active';
                    }
                    $mergedLicenseAddNote = 'Licenses added: +' . $mergedExtraLicenses . ' license(s)';
                }

                $statusDisplay = [
                    'status' => $status,
                    'renewal_status' => $renewalStatus,
                    'statuses' => array_values(array_filter([
                        $status,
                        $renewalStatus,
                    ])),
                    'status_detail' => $hasMergedLicenseAdd ? ($mergedLicenseAddNote ?? null) : null,
                ];

                $displayKey = strtolower(trim((string) $statusDisplay['status']));
                if ($displayKey === 'active') {
                    $activeCount += 1;
                } elseif ($displayKey === 'expiring') {
                    $expiringCount += 1;
                } elseif ($displayKey === 'expired') {
                    $expiredCount += 1;
                } elseif (in_array($displayKey, ['processing', 'pending', 'upgrade pending', 'downgrade pending', 'renewal pending'], true)) {
                    $processingCount += 1;
                }

                $listUpgradeFlags = $this->upgradeButtonFlags(
                    $isCancelledOrder
                        || (
                            !$this->isPendingPlanChangeOrder($order)
                            && (int) ($partial['pending_upgrade_licenses'] ?? 0) <= 0
                            && (int) ($partial['pending_downgrade_licenses'] ?? 0) <= 0
                            && collect($visibleLines)->contains(fn($line) => empty($line['hide_upgrade']))
                        ),
                    null,
                    ['provider_id' => (int) ($provider_id ?? 0)]
                );

                $orderDetail = [
                    'id'               => $order->id,
                    'order_sub_id'     => optional($primary['item'])->id,
                    'provider_id'      => $provider_id,
                    'order_id'         => $order->id,
                    'order_no'         => $order->order_no,
                    'customer_id'      => $order->user_id,
                    'company_name'     => $customerName,
                    'ownerName'        => $customerName,
                    'customer_name'    => $customer_name,
                    'domain'           => $domain,
                    'status'           => $status,
                    'is_cancelled'     => $isCancelledOrder,
                    'renewal_status'   => $statusDisplay['renewal_status'],
                    'statuses'         => $statusDisplay['statuses'],
                    'status_detail'    => $statusDisplay['status_detail'],
                    'plan_change_status' => $planChangeStatus,
                    'item_status'      => $itemStatus,
                    'currentPlan'      => $planName,
                    'plans_count'      => $plansCount,
                    'plan_names'       => $planNames->values()->all(),
                    'plans'            => collect($visibleLines)->map(function ($line) use ($order) {
                        $lineQty = (int) ($line['qty'] ?? 0);
                        if ($lineQty <= 0) {
                            $lineQty = max(1, (int) ($order->quantity ?? $order->licenses ?? 1));
                        }
                        return [
                            'order_sub_id' => optional($line['item'])->id,
                            'plan_id' => optional($line['plan'])->id,
                            'plan_name' => optional($line['plan'])->name ?? '',
                            'licenses' => $lineQty,
                            'status' => (string) ($line['status'] ?? ''),
                            'item_status' => (string) ($line['item_status'] ?? ''),
                            'plan_change_status' => (string) ($line['plan_change_status'] ?? ''),
                            'renewal_status' => $line['renewal_status'] ?? null,
                            'can_upgrade' => (bool) ($line['can_upgrade'] ?? true),
                            'can_partial_upgrade' => (bool) ($line['can_partial_upgrade'] ?? true),
                            'can_add_license' => (bool) ($line['can_add_license'] ?? true),
                            'hide_upgrade' => (bool) ($line['hide_upgrade'] ?? false),
                            'hide_partial_upgrade' => (bool) ($line['hide_partial_upgrade'] ?? false),
                            'change_via' => $line['change_via'] ?? 'cart',
                            'requires_request' => (bool) ($line['requires_request'] ?? false),
                        ];
                    })->values()->all(),
                    'licenses'         => (string) $totalLicenses,
                    'pending_renewal_licenses' => $pendingRenewalLicenses > 0 ? $pendingRenewalLicenses : null,
                    'can_upgrade'      => $listUpgradeFlags['can_upgrade'],
                    'can_partial_upgrade' => $listUpgradeFlags['can_partial_upgrade'],
                    'can_add_license'  => $listUpgradeFlags['can_add_license'],
                    'hide_upgrade'     => $listUpgradeFlags['hide_upgrade'],
                    'hide_partial_upgrade' => $listUpgradeFlags['hide_partial_upgrade'],
                    'change_via'       => $listUpgradeFlags['change_via'] ?? 'cart',
                    'requires_request' => (bool) ($listUpgradeFlags['requires_request'] ?? false),
                    'renewalDate'      => date('d-m-Y', strtotime($renewalDate)),
                    'due_date'         => date('d-m-Y', strtotime($renewalDate)),
                    'days_left'        => $daysLeft,
                    'enrollment_category' => $enrollment_category,
                    'enrollment_type'  => $enrollment_type,
                    'po_mode'          => (string) ($resolvedPo['po_mode'] ?? (($poByOrderId[(int) $order->id] ?? null)?->po_mode ?? null)),
                    'po_number'        => (string) ($resolvedPo['po_number'] ?? (($poByOrderId[(int) $order->id] ?? null)?->po_number ?? '')),
                    'po_link'          => $resolvedPo['po_link']
                        ?? ($poByOrderId[(int) $order->id] ?? null)?->po_document_url
                        ?? ($order->po_document_url ?? null),
                    'is_uploaded_po'   => (bool) ($resolvedPo['is_uploaded'] ?? false),
                    'has_credit_note'  => $hasCreditNote,
                    'credit_note'      => $creditNote,
                    'credit_note_id'   => $creditNote['credit_note_id'] ?? null,
                    'credit_note_no'   => $creditNote['credit_note_no'] ?? null,
                    'credit_note_amount' => $creditNote['credit_note_amount'] ?? null,
                    'credit_note_link' => $creditNote['credit_note_link'] ?? null,
                    'credit_note_status' => $creditNote['credit_note_status'] ?? null,
                    'wallet_credited' => $creditNote['wallet_credited'] ?? false,
                    'wallet_withdrawable' => $creditNote['wallet_withdrawable'] ?? false,
                    'wallet_status' => $creditNote['wallet_status'] ?? null,
                ];

                // --- ADD LICENSE-ADD HISTORY IF MERGED ---
                if ($hasMergedLicenseAdd) {
                    $orderDetail['has_license_add_history'] = true;
                    $orderDetail['license_add_history'] = collect($mergedLicenseAddOrders)->map(function ($child) {
                        return [
                            'order_id' => $child->id,
                            'order_no' => $child->order_no,
                            'added_licenses' => (int) ($child->quantity ?? 1),
                            'created_at' => $child->created_at ? $child->created_at->format('d-m-Y H:i:s') : null,
                            'status' => $child->status,
                        ];
                    })->values()->all();
                }

                $order_details[] = $orderDetail + $this->partnerOrderActionFlags($order, $provider_id ? (int) $provider_id : null);
            }

            // --- CRITICAL: FINAL FILTER - Remove activated same-plan license-add children that were merged ---
            // processing / pending / different plan_id addon rows must stay visible.
            $order_details = array_values(array_filter($order_details, function ($row) use ($mergedParentIds, $licenseAddChildIds, $activatedAddonStatuses, $orders) {
                $orderId = (int) ($row['order_id'] ?? 0);

                // If this is a merged parent, keep it
                if (isset($mergedParentIds[$orderId])) {
                    return true;
                }

                if (in_array($orderId, $licenseAddChildIds, true)) {
                    $order = Order::find($orderId);
                    $st = strtolower(trim((string) ($order->status ?? $row['status'] ?? '')));
                    $parentId = (int) ($order->parent_order_id ?? 0);
                    $parentPlanId = (int) (optional($orders->firstWhere('id', $parentId))->plan_id
                        ?? optional(Order::find($parentId))->plan_id
                        ?? 0);
                    $samePlan = $parentPlanId > 0 && $parentPlanId === (int) ($order->plan_id ?? 0);
                    // Hide only activated same-plan addon children; keep processing/pending/other plan
                    if (in_array($st, $activatedAddonStatuses, true) && $samePlan) {
                        return false;
                    }

                    return true;
                }

                // Check if this is a license-add child order
                $order = Order::find($orderId);
                if ($order && (int) ($order->parent_order_id ?? 0) > 0) {
                    $isLicenseAdd = $this->isLicenseAddOrder($order);

                    $parentId = (int) ($order->parent_order_id ?? 0);
                    $st = strtolower(trim((string) ($order->status ?? '')));
                    $parentPlanId = (int) (optional($orders->firstWhere('id', $parentId))->plan_id
                        ?? optional(Order::find($parentId))->plan_id
                        ?? 0);
                    $samePlan = $parentPlanId > 0 && $parentPlanId === (int) ($order->plan_id ?? 0);

                    // If this is an activated same-plan license-add child AND its parent was merged, remove it
                    if ($isLicenseAdd && isset($mergedParentIds[$parentId]) && in_array($st, $activatedAddonStatuses, true) && $samePlan) {
                        return false;
                    }
                }

                return true;
            }));

            // Final de-dupe: hide parent ORD only when fully replaced.
            $hideParentOrderIds = [];
            $hideParentOrderNos = [];
            foreach ($order_details as $row) {
                $ono = strtoupper(trim((string) ($row['order_no'] ?? '')));
                $oid = (int) ($row['order_id'] ?? 0);
                if (!str_starts_with($ono, 'RN') && !str_starts_with($ono, 'CH')) {
                    continue;
                }

                $src = $orders->firstWhere('id', $oid);
                if (!$src) continue;

                $parentId = (int) ($src->parent_order_id ?? 0);
                if ($parentId <= 0) {
                    continue;
                }

                $parentItems = $this->uniqueSubscriptionOrderItems(
                    $orderItemMap->get($parentId, collect())
                );
                $childOrdersForParent = $planChangeContext['child_change_orders_by_parent']->get($parentId, collect());
                $upgradeStateForParent = $this->buildUpgradeStateBySourceSubId(
                    $parentId,
                    $childOrdersForParent,
                    $planChangeContext['child_order_items'],
                    $planChangeContext['new_plans_by_id']
                );

                $remainingActiveLines = $parentItems->filter(function ($item) use ($upgradeStateForParent, $childOrdersForParent, $planChangeContext) {
                    return $this->parentSourceLineRemainsOnParent(
                        $item,
                        $upgradeStateForParent,
                        $planChangeContext['child_order_items'],
                        $childOrdersForParent
                    );
                });

                if ($remainingActiveLines->isNotEmpty()) {
                    continue;
                }

                $childIsActivated = $this->isActivatedPlanChangeOrder($src);
                if (!$childIsActivated) {
                    continue;
                }

                $hideParentOrderIds[$parentId] = true;
                if (str_starts_with($ono, 'RN') && preg_match('/^RN(.+)$/', $ono, $m)) {
                    $hideParentOrderNos['ORD' . $m[1]] = true;
                }
            }

            // Don't hide parent orders that have merged license-add children
            foreach ($mergedParentIds as $mergedParentId => $value) {
                unset($hideParentOrderIds[$mergedParentId]);
            }

            if ($hideParentOrderIds !== [] || $hideParentOrderNos !== []) {
                $order_details = array_values(array_filter($order_details, function (array $row) use ($hideParentOrderIds, $hideParentOrderNos) {
                    $ono = strtoupper(trim((string) ($row['order_no'] ?? '')));
                    $oid = (int) ($row['order_id'] ?? 0);
                    
                    if (isset($hideParentOrderIds[$oid])) {
                        return false;
                    }
                    if (isset($hideParentOrderNos[$ono])) {
                        return false;
                    }
                    
                    if (str_starts_with($ono, 'RN') || str_starts_with($ono, 'CH')) {
                        return true;
                    }

                    return true;
                }));

                $activeCount = 0;
                $expiringCount = 0;
                $expiredCount = 0;
                $processingCount = 0;
                foreach ($order_details as $row) {
                    $displayKey = strtolower(trim((string) ($row['status'] ?? '')));
                    if ($displayKey === 'active') {
                        $activeCount += 1;
                    } elseif ($displayKey === 'expiring') {
                        $expiringCount += 1;
                    } elseif ($displayKey === 'expired') {
                        $expiredCount += 1;
                    } elseif (in_array($displayKey, ['processing', 'pending', 'upgrade pending', 'downgrade pending', 'renewal pending'], true)) {
                        $processingCount += 1;
                    }
                }
            }

            if ($statusFilter) {
                $order_details = array_values(array_filter($order_details, function (array $row) use ($statusFilter) {
                    $labels = array_map(fn ($s) => strtolower(trim((string) $s)), (array) ($row['statuses'] ?? [$row['status'] ?? '']));

                    return array_intersect($labels, $statusFilter) !== [];
                }));
                $filteredTotal = count($order_details);
                $order_details = array_slice($order_details, ($pageNo - 1) * $perPage, $perPage);
                $paginatedOrders = new \Illuminate\Pagination\LengthAwarePaginator($order_details, $filteredTotal, $perPage, $pageNo);
            }

            $summary = [
                [
                    'key'   => 'Active Subscriptions',
                    'value' => $activeCount
                ],
                [
                    'key'   => 'Processing Orders',
                    'value' => $processingCount
                ],
                [
                    'key'   => 'Expiring Subscriptions',
                    'value' => $expiringCount
                ],
                [
                    'key'   => 'Expired Subscriptions',
                    'value' => $expiredCount
                ]
            ];

            return response()->json([
                'success' => true,
                'message' => 'Orders fetched successfully',
                'data'    => [
                    'provider_id'   => $providerId > 0 ? $providerId : null,
                    'customer_id'   => $customerId > 0 ? $customerId : null,
                    'order_details' => $order_details,
                    'summary' => $summary,
                    'pagination' => [
                        'total' => $paginatedOrders->total(),
                        'per_page' => $paginatedOrders->perPage(),
                        'current_page' => $paginatedOrders->currentPage(),
                        'last_page' => $paginatedOrders->lastPage(),
                        'from' => $paginatedOrders->firstItem(),
                        'to' => $paginatedOrders->lastItem(),
                    ]
                ]
            ], 200);
        } catch (\Exception $e) {
            return response()->json([
                'success' => false,
                'message' => 'Failed to fetch data',
                'error'   => $e->getMessage()
            ], 500);
        }
    }

    public function checkDomainAvailability(Request $request)
    {
        $domain = strtolower(trim((string) $request->query('domain_name', '')));
        $providerId = OrderDomainHelper::resolveProviderIdFromRequest($request);

        // Empty domain check
        if ($domain === '') {
            return response()->json([
                'success' => false,
                'message' => 'Please enter domain name.',
                'data' => [
                    'available' => false,
                ],
            ], 422);
        }

        // Domain format validation
        if (!preg_match(OrderDomainHelper::DOMAIN_SEGMENT_PATTERN, $domain)) {
            return response()->json([
                'success' => false,
                'message' => 'Please enter a valid domain name.',
                'data' => [
                    'available' => false,
                ],
            ], 422);
        }

        // Microsoft tenant domains are valid only with Microsoft 365 plans.
        if (preg_match('/\.onmicrosoft\.com$/i', $domain) && !OrderDomainHelper::isMicrosoftProvider($providerId > 0 ? $providerId : null)) {
            return response()->json([
                'success' => false,
                'message' => '.onmicrosoft.com domains can only be used with Microsoft 365.',
                'data' => [
                    'available' => false,
                ],
            ], 422);
        }

        // Domain already tied to another provider's plan(s) → block for this provider.
        $usedPlans = OrderDomainHelper::existingPlansForDomain($domain);
        $usedProviderIds = OrderDomainHelper::existingProviderIdsForDomain($domain);

        if ($providerId > 0 && OrderDomainHelper::isDomainUsedByOtherProvider($domain, $providerId)) {
            return response()->json([
                'success' => false,
                'message' => OrderDomainHelper::otherProviderConflictMessage(),
                'data' => [
                    'available' => false,
                    'used_provider_ids' => $usedProviderIds,
                    'used_plans' => $usedPlans,
                ],
            ], 422);
        }

        // Domain already on a live order (processing / pending / completed / active / etc.)
        // — only cancelled / draft / failed / rejected / void free it for reuse.
        if (OrderDomainHelper::isDomainInUseOnActiveOrder($domain)) {
            return response()->json([
                'success' => false,
                'message' => OrderDomainHelper::domainInUseMessage(),
                'data' => [
                    'available' => false,
                    'in_use' => true,
                    'used_provider_ids' => $usedProviderIds,
                    'used_plans' => $usedPlans,
                ],
            ], 422);
        }

        try {
            // External registration check
            $openForRegistration = $this->isDomainAvailableForRegistration($domain);

            Log::info('orders-check-domain result', [
                'domain' => $domain,
                'provider_id' => $providerId,
                'used_provider_ids' => $usedProviderIds,
                'used_plans_count' => count($usedPlans),
                'openForRegistration' => $openForRegistration,
            ]);

            if ($openForRegistration) {
                return response()->json([
                    'success' => true,
                    'message' => 'This domain is not registered yet. Please purchase/register the domain first before placing order.',
                    'data' => [
                        'available' => false,
                        'used_provider_ids' => $usedProviderIds,
                        'used_plans' => $usedPlans,
                    ],
                ]);
            }

            return response()->json([
                'success' => true,
                'message' => 'Domain is Valid.',
                'data' => [
                    'available' => true,
                    'used_provider_ids' => $usedProviderIds,
                    'used_plans' => $usedPlans,
                ],
            ]);
        } catch (\Throwable $e) {

            Log::warning('Orders domain check failed', [
                'domain' => $domain,
                'error'  => $e->getMessage(),
            ]);

            return response()->json([
                'success' => true,
                'message' => 'Could not verify domain right now; you may continue.',
                'data' => [
                    'available' => true,
                    'used_provider_ids' => $usedProviderIds,
                    'used_plans' => $usedPlans,
                ],
            ]);
        }
    }

    private function isDomainAvailableForRegistration($domain)
    {
        return !checkdnsrr($domain, 'A') &&
            !checkdnsrr($domain, 'MX') &&
            !checkdnsrr($domain, 'NS');
    }

    public function poDetailsStore(Request $request)
    {
        $validated = $request->validate([
            'partner_id'      => 'required|exists:pgsql_auth.partners,id',
            'order_id'        => 'required|exists:pgsql_billing.orders,id',
            'name'            => 'required|string|max:255',
            'email'           => 'required|email|max:255',
            'mobile'          => 'required|string|max:15',
            'gstin'           => 'nullable|string|max:20',
            'company_name'    => 'required|string|max:255',
            'company_address' => 'required|string',
            'city'            => 'required|string|max:100',
            'state'           => 'required|string|max:100',
            'country'         => 'required|string|max:100',
            'pincode'         => 'required|string|max:10',
            'status'          => 'nullable|string'
        ]);

        try {

            /*
            |--------------------------------------------------------------------------
            | Fetch Existing Customer
            |--------------------------------------------------------------------------
            */
            $customer = Customer::where('email', $validated['email'])
                ->where('partner_id', $validated['partner_id'])
                ->first();

            $isNewCustomer = false;

            /*
            |--------------------------------------------------------------------------
            | First Time Save in Customer Table
            |--------------------------------------------------------------------------
            */
            if (!$customer) {

                $customer = Customer::create([
                    'partner_id'      => $validated['partner_id'],
                    'name'            => $validated['name'],
                    'email'           => $validated['email'],
                    'mobile'          => $validated['mobile'],
                    'gstin'           => $validated['gstin'] ?? null,
                    'company_name'    => $validated['company_name'],
                    'company_address' => $validated['company_address'],
                    'city'            => $validated['city'],
                    'state'           => $validated['state'],
                    'country'         => $validated['country'],
                    'pincode'         => $validated['pincode'],
                    'status'          => $validated['status'] ?? 'active'
                ]);

                $isNewCustomer = true;
            }

            /*
            |--------------------------------------------------------------------------
            | 2nd Time Fetch & Save/Update in order_po_details 
            |--------------------------------------------------------------------------
            */
            $poDetail = OrderPoDetail::updateOrCreate(
                ['order_id' => $validated['order_id']],
                [
                    'manual_name'            => $customer->name,
                    'manual_email'           => $customer->email,
                    'manual_mobile'          => $customer->mobile,
                    'manual_gstin'           => $customer->gstin,
                    'manual_company_name'    => $customer->company_name,
                    'manual_company_address' => $customer->company_address,
                    'manual_city'            => $customer->city,
                    'manual_state'           => $customer->state,
                    'manual_country'         => $customer->country,
                    'manual_pincode'         => $customer->pincode,
                    'journey_status'         => 'saved'
                ]
            );

            return response()->json([
                'success' => true,
                'message' => $isNewCustomer
                    ? 'Customer saved and PO details created'
                    : 'Existing customer fetched and PO details updated',

                'customer_details' => [
                    'customer_id' => $customer->id,
                    'name'        => $customer->name,
                    'email'       => $customer->email
                ],

                'po_details' => [
                    'po_id' => $poDetail->id,
                    'order_id' => $poDetail->order_id,
                    'journey_status' => $poDetail->journey_status
                ]

            ], 201);
        } catch (\Exception $e) {

            return response()->json([
                'success' => false,
                'message' => 'Process failed',
                'error'   => $e->getMessage()
            ], 500);
        }
    }

    public function orderView(Request $request)
    {
