            $orderItems = $this->fetchOrderItemsForView((int) $order->id);
            $creditNote = app(\App\Services\OrderCancellationCreditNoteService::class)
                ->resolveCreditNotesByOrderIds([(int) $order->id])[(int) $order->id] ?? null;
            $poRow = OrderPoDetail::query()->where('order_id', (int) $order->id)->first();
            $orderStatusRaw = strtolower(trim((string) ($order->status ?? '')));
            $isCancelledOrder = in_array($orderStatusRaw, ['cancelled', 'canceled', 'rejected'], true);
            $hasCreditNote = is_array($creditNote) && !empty($creditNote['credit_note_id'] ?? $creditNote['credit_note_no'] ?? null);
            $displayStatus = $isCancelledOrder ? 'Cancelled' : (string) ($order->status ?? '-');

