                        'order_no' => $order->order_no ?? '-',
                        'domain_name' => $order->domain_name ?? '-',
                        'previous_domain' => $order->previous_domain ?? '-',
                        'order_type' => $order->order_type ?? '-',
                        'quantity' => $order->quantity ?? 0,
                        'licenses' => $order->licenses ?? 0,
                        'status' => $displayStatus,
                        'is_cancelled' => $isCancelledOrder,
                        'order_note' => $order->order_note ?? '-',
                        'subscription_start_date' => $order->subscription_start_date
                            ? date('d-m-Y', strtotime($order->subscription_start_date))
                            : '-',
                        'subscription_end_date' => $order->subscription_end_date
                            ? date('d-m-Y', strtotime($order->subscription_end_date))
                            : '-',
                        'created_at' => $order->created_at
                            ? $order->created_at->format('d-m-Y h:i A')
                            : '-',
                        'po_mode' => (string) ($poRow->po_mode ?? 'generated'),
                        'po_number' => (string) ($poRow->po_number ?? ''),
                        'po_link' => $poRow->po_document_url ?? ($order->po_document_url ?? null),
                        'has_credit_note' => $hasCreditNote,
