    public function orderEdit(Request $request)
    {
        try {

            $request->validate([
                'order_id' => 'required|integer',

                'plan_id' => 'nullable|exists:pgsql_product.plans,id',
                'partner_id' => 'nullable|exists:pgsql_auth.partners,id',
                'user_id' => 'nullable|exists:pgsql_billing.customers,id',

                'domain_name' => 'nullable|string',
                'previous_domain' => 'nullable|string',

                'quantity' => 'nullable|integer|min:1',
                'licenses' => 'nullable|integer|min:1',

                'status' => 'nullable|string',
                'order_type' => 'nullable|string',

                'discount' => 'nullable|numeric|min:0|max:100',
                'apply_gst' => 'nullable|in:yes,no',
                'gst_rate' => 'nullable|numeric|min:0|max:100',

                'promocode' => 'nullable|string',
                'order_note' => 'nullable|string',

                'amount' => 'nullable|numeric|min:0'
            ]);

            DB::beginTransaction();

            $requestedOrderId = (int) $request->order_id;
            $order = Order::find($requestedOrderId);

            // If the order_id is the parent subscription, resolve the latest upgrade/partial-upgrade child order.
            if (!$order) {
                $order = Order::query()
                    ->where('parent_order_id', $requestedOrderId)
                    ->whereIn('order_category', ['upgrade', 'partial-upgrade', 'partial_upgrade'])
                    ->orderByDesc('id')
                    ->first();
            }

            if (!$order) {
                DB::rollBack();
                return response()->json([
                    'success' => false,
                    'message' => 'Order not found.',
                ], 404);
            }
            $editFlags = $this->partnerOrderActionFlags($order);
            if (empty($editFlags['can_edit'])) {
                DB::rollBack();

                return response()->json([
                    'success' => false,
                    'message' => (string) ($editFlags['edit_blocked_reason'] ?? 'Order cannot be edited.'),
                    'actions' => $editFlags,
                ], 422);
            }

            $plan = Plan::find($request->plan_id ?? $order->plan_id);
            $partner = Partner::find($request->partner_id ?? $order->partner_id);
            $customer = Customer::find($request->user_id ?? $order->user_id);

            $baseAmount = $request->amount ?? $order->base_price;
            $quantity = $request->quantity ?? $order->quantity;
            $licenses = $request->licenses ?? $order->licenses;

            $subtotal = $baseAmount * $licenses;

            // Discount
            $discount = $request->discount ?? $order->discount;
            $discountAmount = ($subtotal * $discount) / 100;

            $afterDiscount = $subtotal - $discountAmount;

            // Promocode
            $promocodeDiscount = 0;
            $promoAmount = 0;

            if ($request->filled('promocode')) {

                $promo = Promocode::where('code', $request->promocode)
                    ->where('status', 1)
                    ->first();

                if (!$promo) {
                    return response()->json([
                        'success' => false,
                        'message' => 'Invalid promo code'
                    ], 422);
                }

                $promocodeDiscount = $promo->discount_percent;
                $promoAmount = ($afterDiscount * $promocodeDiscount) / 100;
                $afterDiscount -= $promoAmount;
            }

            // GST
            $applyGst = $request->apply_gst ?? $order->apply_gst;
            $gstRate = $request->gst_rate ?? $order->gst_rate;

            $gstAmount = ($applyGst === 'yes')
                ? ($afterDiscount * $gstRate) / 100
                : 0;

            $totalAmount = $afterDiscount + $gstAmount;

            $order->update([
                'plan_id' => $plan->id,
                'partner_id' => $partner->id,
                'user_id' => $customer->id,

                'domain_name' => $request->domain_name ?? $order->domain_name,
                'previous_domain' => $request->previous_domain ?? $order->previous_domain,

                'quantity' => $quantity,
                'licenses' => $licenses,

                'status' => $request->status ?? $order->status,
                'order_type' => $request->order_type ?? $order->order_type,

                'discount' => $discount,
                'discount_amount' => $discountAmount,

                'promocode' => $request->promocode ?? $order->promocode,
                'promocode_discount' => $promocodeDiscount,

                'apply_gst' => $applyGst,
                'gst_rate' => $gstRate,
                'gst_amount' => $gstAmount,

                'subtotal' => $subtotal,
                'after_discount' => $afterDiscount,
                'total_amount' => $totalAmount,
                'final_amount' => $totalAmount,

                'order_note' => $request->order_note ?? $order->order_note,
                'base_price' => $baseAmount
            ]);

            DB::commit();

            return response()->json([
                'success' => true,
                'message' => 'Order updated successfully',

                'data' => [

                    'order' => $order->fresh(),

                    'customer' => [
                        'id' => $customer->id,
                        'name' => $customer->name,
                        'company_name' => $customer->company_name,
                        'email' => $customer->email,
                        'mobile' => $customer->mobile
                    ],

                    'partner' => [
                        'id' => $partner->id,
                        'name' => $partner->name
                    ],

                    'plan' => [
                        'id' => $plan->id,
                        'name' => $plan->name,
                        'price' => $plan->price
                    ],

                    'calculation' => [
                        'subtotal' => $subtotal,
                        'discount_amount' => $discountAmount,
                        'promo_amount' => $promoAmount,
                        'gst_amount' => $gstAmount,
                        'total_amount' => $totalAmount,
                        'final_amount' => $totalAmount
                    ]
                ]
            ]);
        } catch (\Exception $e) {

            DB::rollBack();

            return response()->json([
                'success' => false,
                'message' => 'Something went wrong',
                'error' => $e->getMessage()
            ], 500);
        }
    }

    public function orderUpdate(Request $request)
    {
        try {

            $request->validate([
                'order_id' => 'required|integer',

                'status' => 'nullable|string',
                'quantity' => 'nullable|integer|min:1',
                'licenses' => 'nullable|integer|min:1',

                'discount' => 'nullable|numeric|min:0|max:100',
                'apply_gst' => 'nullable|in:yes,no',
                'gst_rate' => 'nullable|numeric|min:0|max:100',

                'promocode' => 'nullable|string',
                'amount' => 'nullable|numeric|min:0',
                'order_note' => 'nullable|string'
            ]);

            DB::beginTransaction();

            $requestedOrderId = (int) $request->order_id;
            $order = Order::find($requestedOrderId);

            // If the order_id is the parent subscription, resolve the latest upgrade/partial-upgrade child order.
            if (!$order) {
                $order = Order::query()
                    ->where('parent_order_id', $requestedOrderId)
                    ->whereIn('order_category', ['upgrade', 'partial-upgrade', 'partial_upgrade'])
                    ->orderByDesc('id')
                    ->first();
            }

            if (!$order) {
                DB::rollBack();
                return response()->json([
                    'success' => false,
                    'message' => 'Order not found.',
                ], 404);
            }

            $editFlags = $this->partnerOrderActionFlags($order);
            if (empty($editFlags['can_edit'])) {
                DB::rollBack();

                return response()->json([
                    'success' => false,
                    'message' => (string) ($editFlags['edit_blocked_reason'] ?? 'Order cannot be edited.'),
                    'actions' => $editFlags,
                ], 422);
            }
            $previousStatus = strtolower(trim((string) $order->status));

            $baseAmount = $request->amount ?? $order->base_price;
            $quantity = $request->quantity ?? $order->quantity;
            $licenses = $request->licenses ?? $order->licenses;

            $subtotal = $baseAmount * $licenses;

            // Discount
            $discount = $request->discount ?? $order->discount;
            $discountAmount = ($subtotal * $discount) / 100;

            $afterDiscount = $subtotal - $discountAmount;

            // Promocode
            $promocodeDiscount = 0;
            $promoAmount = 0;

            if ($request->filled('promocode')) {

                $promo = Promocode::where('code', $request->promocode)
                    ->where('status', 1)
                    ->first();

                if (!$promo) {
                    return response()->json([
                        'success' => false,
                        'message' => 'Invalid promo code'
                    ], 422);
                }

                $promocodeDiscount = $promo->discount_percent;
                $promoAmount = ($afterDiscount * $promocodeDiscount) / 100;

                $afterDiscount -= $promoAmount;
            }

            // GST
            $applyGst = $request->apply_gst ?? $order->apply_gst;
            $gstRate = $request->gst_rate ?? $order->gst_rate;

            $gstAmount = 0;

            if ($applyGst === 'yes') {
                $gstAmount = ($afterDiscount * $gstRate) / 100;
            }

            $totalAmount = $afterDiscount + $gstAmount;

            $newStatus = strtolower(trim((string) ($request->status ?? $order->status)));
            $activeStatuses = ['completed', 'paid', 'success', 'active'];
            $activating = in_array($newStatus, $activeStatuses, true)
                && !in_array($previousStatus, $activeStatuses, true);
            $partnerId = (int) ($order->partner_id ?? 0);

            if (
                $activating
                && $partnerId > 0
                && strtolower(trim((string) ($order->order_type ?? ''))) === 'b2b'
            ) {
                $creditCheck = PartnerCreditService::validateB2bPurchaseAmount(
                    $partnerId,
                    (float) $totalAmount,
                    false,
                    (int) $order->id
                );
                if (empty($creditCheck['ok'])) {
                    DB::rollBack();

                    return response()->json([
                        'success' => false,
                        'message' => (string) ($creditCheck['message'] ?? PartnerCreditService::CREDIT_LIMIT_REACHED_MESSAGE),
                        'code' => (string) ($creditCheck['code'] ?? 'credit_limit_exceeded'),
                    ], 422);
                }
            }

            $order->update([
                'status' => $request->status ?? $order->status,

                'quantity' => $quantity,
                'licenses' => $licenses,

                'discount' => $discount,
                'discount_amount' => $discountAmount,

                'promocode' => $request->promocode ?? $order->promocode,
                'promocode_discount' => $promocodeDiscount,

                'apply_gst' => $applyGst,
                'gst_rate' => $gstRate,
                'gst_amount' => $gstAmount,

                'subtotal' => $subtotal,
                'after_discount' => $afterDiscount,
                'total_amount' => $totalAmount,
                'final_amount' => $totalAmount,

                'base_price' => $baseAmount,
                'order_note' => $request->order_note ?? $order->order_note
            ]);

            DB::commit();

            if ($activating && $partnerId > 0) {
                try {
                    $order->refresh();
                    if (
                        strtolower(trim((string) ($order->order_type ?? ''))) === 'b2b'
                        && (float) ($order->credit_used ?? 0) <= 0.01
                        && (float) $totalAmount > 0
                    ) {
                        $order->update(['credit_used' => round((float) $totalAmount, 2)]);
                    }
                    $orderRow = $order->fresh()->toArray();
                    $orderRow['status'] = 'completed';
                    PartnerCreditService::syncB2bOrderWalletLedger((int) $order->id, $orderRow);
                } catch (\Throwable $e) {
                    $order->update(['status' => $previousStatus, 'credit_used' => 0]);

                    return response()->json([
                        'success' => false,
                        'message' => $e->getMessage(),
                        'code' => 'credit_limit_exceeded',
                    ], 422);
                }

                try {
                    app(BillingController::class)->sendOrderPlacedEmailForOrder((int) $order->id, true);
                } catch (\Throwable $e) {
                    Log::warning('Partner orderUpdate: partner email failed', [
                        'order_id' => $order->id,
                        'error' => $e->getMessage(),
                    ]);
                }
            }

            return response()->json([
                'success' => true,
                'message' => 'Order updated successfully',
                'data' => $order->fresh()
            ]);
        } catch (\Exception $e) {

            DB::rollBack();

            return response()->json([
                'success' => false,
                'message' => 'Something went wrong',
                'error' => $e->getMessage()
            ], 500);
        }
    }

    public function addToCart(Request $request)
    {
        // Frontend sends license_count; keep licenses as alias.
        if (!$request->filled('licenses') && $request->filled('license_count')) {
            $request->merge(['licenses' => (int) $request->input('license_count')]);
        }

        $validated = $request->validate([
            'partner_id'   => 'required|exists:pgsql_auth.partners,id',
            'cart_id'      => 'nullable|integer|exists:pgsql_billing.carts,id',
            'customer_id'  => 'nullable|exists:pgsql_billing.customers,id',
            'plan_id'      => 'required|exists:pgsql_product.plans,id',
            'domain_name'  => 'nullable',
            'licenses'     => 'nullable|integer|min:1',
            'license_count' => 'nullable|integer|min:1',
            'coupen'       => 'nullable|string',
        ]);

        $partnerId  = (int) $validated['partner_id'];
        $customerId = $validated['customer_id'] ?? null;
        $planId     = (int) $validated['plan_id'];
        $licenses   = (int) ($validated['licenses'] ?? $validated['license_count'] ?? 0);
        if ($licenses < 1) {
            $licenses = 1;
        }

        $plan = Plan::find($planId);
        if (!$plan) {
            return response()->json([
                'success' => false,
                'message' => 'Plan not found',
            ], 404);
        }

        $domainName = OrderDomainHelper::normalizeStored($validated['domain_name'] ?? '');
        $domainName = strtolower(trim($domainName));
        if ($domainName !== '') {
            $providerIdForDomain = (int) ($plan->provider_id ?? 0);
            $segments = OrderDomainHelper::parseSegments($domainName, $providerIdForDomain > 0 ? $providerIdForDomain : null);
            if ($segments === []) {
                $segments = [$domainName];
            }
            foreach ($segments as $segment) {
                if ($providerIdForDomain > 0 && OrderDomainHelper::isDomainUsedByOtherProvider($segment, $providerIdForDomain)) {
                    return response()->json([
                        'success' => false,
                        'message' => OrderDomainHelper::otherProviderConflictMessage(),
                        'data' => [
                            'available' => false,
                            'used_plans' => OrderDomainHelper::existingPlansForDomain($segment),
                        ],
                    ], 422);
                }
                if (OrderDomainHelper::isDomainInUseOnActiveOrder($segment)) {
                    return response()->json([
                        'success' => false,
                        'message' => OrderDomainHelper::domainInUseMessage(),
                        'data' => [
                            'available' => false,
                            'in_use' => true,
                            'used_plans' => OrderDomainHelper::existingPlansForDomain($segment),
                        ],
                    ], 422);
                }
            }
        }

        $partner = Partner::select('id', 'wallet_balance', 'credit_limit')->find($partnerId);
        if (!$partner) {
            return response()->json([
                'success' => false,
                'message' => 'Partner not found',
            ], 404);
        }

        if (PartnerCreditService::isCreditLimitFullyUsed($partnerId)) {
            return response()->json([
                'success' => false,
                'message' => 'Credit limit reached. You cannot buy items.',
                'code' => 'credit_limit_reached',
                'data' => $this->partnerB2bWalletInfo($partnerId, 0),
            ], 422);
        }

        $cartService = app(PartnerCartService::class);
        $providerId = $plan->provider_id ? (int) $plan->provider_id : null;
        $coupon = $validated['coupen'] ?? null;

        // Keep adding into the draft cart when a draft is open (do not cancel draft).
        $draftLinkedCart = $this->findActiveDraftCartForPartner($partnerId);
        if ($draftLinkedCart) {
            $cart = $draftLinkedCart;
            if ($coupon !== null && $coupon !== '') {
                $cart->coupen = $coupon;
                $cart->save();
            }
        } else {
            $cart = $cartService->resolvePartnerCart(
                $partnerId,
                Cart::TYPE_STANDARD,
                !empty($validated['cart_id']) ? (int) $validated['cart_id'] : null,
                $providerId,
                $coupon
            );
        }

        if (!$cart) {
            return response()->json([
                'success' => false,
                'message' => 'Cart not found for this partner',
            ], 404);
        }

        // Same plan â†’ append once (2 + 4 = 6). Do NOT also pass total into upsertStandardLine
        // (that service appends again and caused 2+4 â†’ 8).
        $addedLicenses = max(1, $licenses);
        $existingSamePlanItems = CartItem::query()
            ->where('cart_id', (int) $cart->id)
            ->where('plan_id', $planId)
            ->orderBy('id')
            ->get();

        if ($existingSamePlanItems->isNotEmpty()) {
            $keepItem = $existingSamePlanItems->first();
            if ($existingSamePlanItems->count() > 1) {
                CartItem::query()
                    ->where('cart_id', (int) $cart->id)
                    ->where('plan_id', $planId)
                    ->where('id', '!=', (int) $keepItem->id)
                    ->delete();
            }

            $licenses = max(0, (int) ($keepItem->licenses ?? 0)) + $addedLicenses;
            $gstPercentage = (float) ($cart->gst_percentage ?? 18);
            $couponPercent = $cartService->resolveCouponDiscountPercent($cart->coupen ?? $coupon);
            $amounts = $cartService->calculateLineAmounts($plan, $licenses, $gstPercentage, $couponPercent);

            $keepItem->licenses = $licenses;
            $keepItem->unit_price = $amounts['unit_price'] ?? $keepItem->unit_price;
            // Unit price is already yearly (per user / per year) â†’ unit Ã— licenses.
            $keepItem->grand_total = $cartService->lineGrossTotal(
                (float) ($amounts['unit_price'] ?? $keepItem->unit_price ?? 0),
                $licenses
            );
            $keepItem->save();

            if ($customerId) {
                $cart->customer_id = (int) $customerId;
            }
            if ($domainName !== '') {
                $cart->domain_name = $domainName;
            }
            $cart->save();

            $item = $keepItem->fresh(['plan']);
        } else {
            $licenses = $addedLicenses;
            $item = $cartService->upsertStandardLine(
                $cart,
                $plan,
                $licenses,
                $customerId ? (int) $customerId : null,
                $domainName !== '' ? $domainName : null
            );
        }

        $cart = $cartService->recalculateCartTotals((int) $cart->id) ?? $cart->fresh(['items.plan', 'customer']);
        $item = $item ? $item->fresh(['plan']) : $item;

        // Final safety: one row per plan_id with exact total (never re-append here).
        $samePlanItems = CartItem::query()
            ->where('cart_id', (int) $cart->id)
            ->where('plan_id', $planId)
            ->orderBy('id')
            ->get();
        if ($samePlanItems->count() > 1) {
            $keep = $samePlanItems->firstWhere('id', (int) ($item->id ?? 0)) ?? $samePlanItems->first();
            CartItem::query()
                ->where('cart_id', (int) $cart->id)
                ->where('plan_id', $planId)
                ->where('id', '!=', (int) $keep->id)
                ->delete();
            $keep->licenses = max(1, $licenses);
            $keep->save();
            $item = $keep->fresh(['plan']);
            $cart = $cartService->recalculateCartTotals((int) $cart->id) ?? $cart->fresh(['items.plan', 'customer']);
        }

        // Drop orphan drafts (plans removed earlier) so newly added plans stay draft_cart false.
        $this->syncDraftOrdersWithCartPlans($partnerId, $cart);
        $cart = $cart->fresh(['items.plan', 'customer']) ?? $cart;

        $data = $cartService->formatCartWithItemsResponse($cart, $partner, $item);
        $licenseCount = $this->resolveCartLicenseCount($cart);
        $lineLicenses = (int) ($item->licenses ?? $licenses);
        $signRequired = strtolower(trim((string) (
            Partner::query()->whereKey($partnerId)->value('aadhaar_mandatory') ?? 'no'
        ))) === 'yes';
        $draftOrder = $this->resolveDraftOrderForCart($partnerId, $cart);
        $cartIdForFlags = (int) ($cart->id ?? 0);
        $topFlags = $this->syncedDraftFlags($draftOrder, $signRequired, $cartIdForFlags);
        $draftPlanIds = $this->resolveAllDraftPlanIdsForCart($partnerId, $cart);
        $itemFlags = $this->draftFlagsForPlan($planId, $draftOrder, $signRequired, $draftPlanIds, $cartIdForFlags);
        if (is_array($data)) {
            $data['licenses'] = $lineLicenses;
            $data['license_count'] = $licenseCount;
            $data['added_licenses'] = $addedLicenses;
            $data['sign_required'] = $signRequired ? 'yes' : 'no';
            // This line only: true if plan was in draft; newly added plan â†’ false.
            $data = array_merge($data, $itemFlags);
        }

        return response()->json(array_merge([
            'success' => true,
            'message' => !empty($topFlags['draft_cart'])
                ? 'Item added. Draft order still pending Aadhaar for draft plans.'
                : 'Item added to cart successfully',
            'data' => $data,
            'licenses' => $lineLicenses,
            'license_count' => $licenseCount,
            'sign_required' => $signRequired ? 'yes' : 'no',
        ], $topFlags));
    }

    public function updateCart(Request $request)
    {
        try {
            $this->normalizeUpgradeCartRequest($request);

            // Frontend may send license_count instead of licenses.
            if (!$request->filled('licenses') && $request->filled('license_count')) {
                $request->merge(['licenses' => (int) $request->input('license_count')]);
            }

            // Temp pending cart orders use cart_id in the order_id field.
            // When editing that flow, prefer the referenced cart as main_cart_id.
            $rawOrderId = (int) ($request->input('order_id') ?? 0);
            if ($rawOrderId > 0 && !Order::query()->whereKey($rawOrderId)->exists()) {
                $tempCart = Cart::query()->whereKey($rawOrderId)->first();
                if ($tempCart) {
                    $previousMainCartId = (int) ($request->input('main_cart_id') ?? 0);
                    $request->merge(['main_cart_id' => $rawOrderId]);
                    $rawCartId = (int) ($request->input('cart_id') ?? 0);
                    if ($rawCartId === $rawOrderId || ($previousMainCartId > 0 && $rawCartId === $previousMainCartId)) {
                        $request->merge(['cart_id' => null]);
                    }
                }
            }

            // Clear order_id if it's actually a cart ID (frontend quirk on upgrade flows).
            $this->sanitizeOrderIdInRequest($request);

            $validated = $request->validate([
                'main_cart_id' => 'required_without:cart_id|integer',
                'cart_id' => 'required_without:main_cart_id|integer',
                'order_id' => 'nullable|integer',
                'order_sub_id' => 'nullable|integer',
                'from_plan_id' => 'nullable|integer',
                'current_plan_id' => 'nullable|integer',
                'plan_id' => 'nullable|integer',
                'target_plan_id' => 'nullable|integer',
                'new_plan_id' => 'nullable|integer',
                'to_plan_id' => 'nullable|integer',
                'selected_plan_id' => 'nullable|integer',
                'customer_id' => 'nullable',
                'company_name' => 'nullable|string',
                'domain_name' => 'nullable',
                'transfer_domain' => 'nullable|in:yes,no',
                'coupen' => 'nullable|string',
                'licenses' => 'nullable|integer',
                'license_count' => 'nullable|integer|min:1',
            ]);
        } catch (\Illuminate\Validation\ValidationException $e) {
            return response()->json([
                'success' => false,
                'message' => 'Validation failed',
                'errors' => $e->errors(),
            ], 422);
        }

        try {
            $cartCalc = app(PartnerCartService::class);

            $mainCartId = isset($validated['main_cart_id']) ? (int) $validated['main_cart_id'] : null;
            $cartId = isset($validated['cart_id']) ? (int) $validated['cart_id'] : null;

            $parentCart = null;
            $cartItems = null;

            if ($mainCartId) {
                $parentCart = Cart::with(['items.plan', 'partner', 'customer'])->find($mainCartId);

                if (!$parentCart) {
                    return response()->json([
                        'success' => false,
                        'message' => 'Cart not found',
                    ], 404);
                }

                if ($cartId) {
                    if ($mainCartId && $cartId === $mainCartId) {
                        $cartId = null;
                    }
                }

                if ($cartId) {
                    $cartItem = CartItem::with(['plan'])->where('id', $cartId)->first();
                    if (!$cartItem) {
                        return response()->json([
                            'success' => false,
                            'message' => 'Cart item not found under specified main_cart_id' . $cartId,
                        ], 404);
                    }
                    $cartItems = collect([$cartItem]);
                } else {
                    $cartItems = $parentCart->items()->with(['plan'])->get();
                }
            } elseif ($cartId) {
                $cartItem = CartItem::with(['cart.partner', 'cart.customer', 'cart', 'plan'])->find($cartId);
                if (!$cartItem) {
                    return response()->json([
                        'success' => false,
                        'message' => 'Cart item not found',
                    ], 404);
                }
                $parentCart = $cartItem->cart()->with(['partner', 'customer'])->first();
                $cartItems = collect([$cartItem->load('plan')]);
            } else {
                return response()->json([
                    'success' => false,
                    'message' => 'Either main_cart_id or cart_id is required',
                ], 404);
            }

            // --- NEW: Check for Tizzy/Google providers in plan change carts ---
            // Determine provider from cart items
            $providerId = null;
            if ($cartItems && $cartItems->count() > 0) {
                $firstItem = $cartItems->first();
                if ($firstItem && $firstItem->plan) {
                    $providerId = (int) ($firstItem->plan->provider_id ?? 0);
                }
            }
            if (!$providerId && $parentCart && $parentCart->provider_id) {
                $providerId = (int) $parentCart->provider_id;
            }

            // Check if this is a plan change (upgrade/downgrade/license add)
            $isUpgradeCart = strtolower(trim((string) $parentCart->type)) === Cart::TYPE_UPGRADE;
            $isDowngradeCart = strtolower(trim((string) $parentCart->type)) === Cart::TYPE_DOWNGRADE;
            $isLicenseAddCart = strtolower(trim((string) $parentCart->type)) === 'license_add'
                || str_contains(strtolower((string) ($parentCart->item_type ?? '')), 'mode:license_add');
            $isRenewCart = strtolower(trim((string) $parentCart->type)) === Cart::TYPE_RENEW;
            $oldTotalLicenses = 0;
            $newTotalLicenses = 0;
            $currentLicenses = 0;

            // --- BLOCK: Tizzy (1) or Google (3) plan changes ---
            // Upgrade/downgrade require a request; license-add counts can be edited directly.
            $isTizzyOrGoogleProvider = ($providerId === 1 || $providerId === 3);

            // if ($isTizzyOrGoogleProvider && ($isUpgradeCart || $isDowngradeCart)) {
            //     $action = $isUpgradeCart ? 'upgrade' : 'downgrade';
            //     $providerName = $providerId === 1 ? 'Tizzy' : 'Google';

            //     return response()->json([
            //         'success' => true,
            //         'requires_request' => true,
            //         'change_via' => 'request',
            //         'action' => $action,
            //         'provider_id' => $providerId,
            //         'provider_name' => $providerName,
            //         'message' => $providerName . ' ' . $action . ' must be submitted as a request. Direct cart checkout is only for Microsoft.',
            //         'data' => [
            //             'submit_via' => 'POST /api/partner/upgrade-request or /api/partner/downgrade-request or /api/partner/license-add-request',
            //             'partner_id' => (int) $parentCart->partner_id,
            //             'cart_id' => (int) $parentCart->id,
            //             'provider_id' => $providerId,
            //             'current_plan_id' => (int) ($validated['current_plan_id'] ?? $validated['from_plan_id'] ?? 0),
            //             'requested_plan_id' => (int) ($cartItems->first()->plan_id ?? 0),
            //             'licenses' => (int) ($validated['licenses'] ?? $validated['license_count'] ?? 0),
            //             'customer_id' => (int) ($validated['customer_id'] ?? $parentCart->customer_id ?? 0),
            //             'order_id' => (int) ($validated['order_id'] ?? $parentCart->order_id ?? 0),
            //             'order_sub_id' => (int) ($validated['order_sub_id'] ?? $parentCart->order_sub_id ?? 0),
            //         ]
            //     ], 422);
            // }

            if ($cartItems->count() === 0 && $parentCart) {
                if (CartItem::query()->where('cart_id', $parentCart->id)->count() === 0) {
                    $parentCart->customer_id = null;
                    $parentCart->provider_id = null;
                    $parentCart->domain_name = null;
                    $parentCart->transfer_domain = null;
                    $parentCart->discount_amount = 0;
                    $parentCart->coupen = null;
                    $parentCart->gst_amount = 0;
                    $parentCart->grand_total = 0;
                    if (Schema::connection('pgsql_billing')->hasColumn('carts', 'subtotal')) {
                        $parentCart->subtotal = 0;
                    }
                    $parentCart->save();
                    $parentCart = $parentCart->fresh(['items.plan', 'customer']);
                }

                $storedDomains = $parentCart->domain_name ?? '';
                $domainList = [];
                if (is_array($storedDomains)) {
                    $domainList = array_values(array_filter(array_map('trim', $storedDomains)));
                } elseif (is_string($storedDomains) && trim($storedDomains) !== '') {
                    $decoded = json_decode($storedDomains, true);
                    $domainList = is_array($decoded)
                        ? array_values(array_filter(array_map('trim', $decoded)))
                        : array_values(array_filter(array_map('trim', explode(',', $storedDomains))));
                }

                return response()->json([
                    'success' => false,
                    'message' => 'No cart items found to update. Cart metadata cleared.',
                    'data' => [
                        'main_cart_id' => $parentCart->id,
                        'customer_id' => $parentCart->customer_id,
                        'provider_id' => $parentCart->provider_id,
                        'domain_name' => $domainList,
                        'transfer_domain' => $parentCart->transfer_domain ?? null,
                    ],
                ], 404);
            }

            $customer = null;
            $companyName = $validated['company_name'] ?? '-';

            $updatingDomainOnly = (
                ($request->has('domain_name') || $request->has('transfer_domain'))
                && !$request->has('customer_id')
                && !$request->has('company_name')
                && !$request->has('coupen')
                && !$request->has('licenses')
            );

            if (!$updatingDomainOnly) {
                $customerId = array_key_exists('customer_id', $validated) ? $validated['customer_id'] : null;
                if (!is_null($customerId) && $customerId !== '') {
                    $customerId = (int) $customerId;
                    $customer = Customer::find($customerId);
                    if (!$customer) {
                        return response()->json([
                            'success' => false,
                            'message' => 'Customer not found',
                        ], 404);
                    }

                    if ($request->filled('company_name')) {
                        $customer->company_name = $request->company_name;
                        $customer->save();
                        $customer->refresh();
                    }

                    $parentCart->customer_id = $customerId;
                    $parentCart->save();
                    $parentCart->refresh();
                    $companyName = $customer->company_name;
                } elseif ($parentCart && $request->has('customer_id') && (is_null($customerId) || $customerId === '')) {
                    $parentCart->customer_id = null;
                    $parentCart->save();
                }
            } else {
                $customer = $parentCart->customer;
                $companyName = optional($customer)->company_name ?? ($validated['company_name'] ?? '-');
            }

            $domainRaw = $request->has('domain_name')
                ? $request->input('domain_name')
                : ($validated['domain_name'] ?? null);
            $domainArray = [];
            if (is_array($domainRaw)) {
                $domainArray = array_values(array_filter(array_map(
                    static fn($value): string => strtolower(trim((string) $value)),
                    $domainRaw
                )));
            } elseif ($domainRaw !== null && $domainRaw !== '') {
                $normalizedDomain = OrderDomainHelper::normalizeStored($domainRaw);
                $domainArray = $normalizedDomain !== ''
                    ? array_values(array_filter(array_map('trim', explode(',', $normalizedDomain))))
                    : [];
            }

            $domainNameWasSet = false;
            if ($request->has('domain_name')) {
                $parentCart->domain_name = OrderDomainHelper::dedupeList(implode(',', $domainArray));
                $parentCart->save();
                $domainNameWasSet = true;
            }

            if ($domainNameWasSet && (empty($domainArray) || (count($domainArray) === 1 && $domainArray[0] === ''))) {
                $parentCart->transfer_domain = 'no';
                $parentCart->save();
                $parentCart->refresh();
            } elseif ($request->has('transfer_domain')) {
                $transferDomain = strtolower(trim((string) $validated['transfer_domain']));
                if (in_array($transferDomain, ['yes', 'no'], true)) {
                    $parentCart->transfer_domain = $transferDomain;
                    $parentCart->save();
                    $parentCart->refresh();
                }
            }

            $gstPercentage = (float) ($parentCart->gst_percentage ?? 18);

            if ($request->has('coupen')) {
                $coupenRaw = trim((string) $request->input('coupen', ''));
                if ($coupenRaw === '') {
                    $parentCart->coupen = null;
                } else {
                    $promo = Promocode::query()
                        ->whereRaw('UPPER(code) = ?', [strtoupper($coupenRaw)])
                        ->where('status', 1)
                        ->first();
                    if (!$promo) {
                        return response()->json([
                            'success' => false,
                            'message' => 'Invalid or inactive promo code',
                        ], 422);
                    }
                    $parentCart->coupen = strtoupper($coupenRaw);
                }
                $parentCart->save();
            }

            $coupen = $parentCart->coupen;
            $couponPercent = $cartCalc->resolveCouponDiscountPercent($coupen);
            $calculation = [];
            $subscriptionStartDate = null;
            $subscriptionEndDate = null;
            $orderSubId = 0;
            $fromPlanId = 0;
            $selectedOrderId = isset($validated['order_id'])
                ? (int) $validated['order_id']
                : (int) ($parentCart->order_id ?? 0);
            $resolvedOrderId = $selectedOrderId > 0 ? $selectedOrderId : null;

            $licenseDecreaseMeta = null;
            if ($isRenewCart && $request->has('licenses')) {
                $requestedLicenses = max(1, (int) $request->get('licenses'));
                $parentOrderId = (int) ($parentCart->order_id ?? $selectedOrderId ?? 0);
                if ($parentOrderId > 0) {
                    $svc = app(\App\Services\LicenseDecreaseRequestService::class);
                    $parentOrder = Order::query()->whereKey($parentOrderId)->first();
                    // Scope to the plan being edited — not whole-order total (false 1 vs 3).
                    $planIdForGuard = 0;
                    if ($cartItems && $cartItems->count() === 1) {
                        $planIdForGuard = (int) ($cartItems->first()->plan_id ?? 0);
                    } elseif ($request->filled('plan_id')) {
                        $planIdForGuard = (int) $request->input('plan_id');
                    }
                    $currentLicenses = $parentOrder
                        ? \App\Services\LicenseDecreaseRequestService::currentLicensesForOrder(
                            $parentOrder,
                            $planIdForGuard > 0 ? $planIdForGuard : null
                        )
                        : 0;
                    if (
                        $requestedLicenses < $currentLicenses
                        && !$svc->isDecreaseAllowed(
                            (int) $parentCart->partner_id,
                            $parentOrderId,
                            $requestedLicenses,
                            $planIdForGuard > 0 ? $planIdForGuard : null
                        )
                    ) {
                        $licenseDecreaseMeta = [
                            'requires_approval' => true,
                            'code' => 'license_decrease_approval_required',
                            'message' => 'License decrease requires SuperAdmin approval. Call POST /api/partner/license-decrease-request.',
                            'submit_via' => 'POST /api/partner/license-decrease-request',
                            'order_id' => $parentOrderId,
                            'cart_id' => (int) $parentCart->id,
                            'plan_id' => $planIdForGuard > 0 ? $planIdForGuard : null,
                            'current_licenses' => $currentLicenses,
                            'requested_licenses' => $requestedLicenses,
                            'status' => null,
                        ];
                    }
                }
            }

            foreach ($cartItems as $item) {
                // Multi-plan renew/upgrade: do not stamp one `licenses` onto every line.
                $licenses = (int) $item->licenses;
                if ($request->has('licenses')) {
                    $reqLicenses = max(1, (int) $request->get('licenses'));
                    $reqPlanId = (int) $request->input('plan_id', 0);
                    if ($cartItems->count() === 1) {
                        $licenses = $reqLicenses;
                    } elseif ($reqPlanId > 0 && (int) ($item->plan_id ?? 0) === $reqPlanId) {
                        $licenses = $reqLicenses;
                    } elseif (!$isRenewCart && !$isUpgradeCart && !$isDowngradeCart && !$isLicenseAddCart) {
                        $licenses = $reqLicenses;
                    }
                }

                if ($isUpgradeCart || $isDowngradeCart || $isRenewCart || $isLicenseAddCart) {
                    $item->licenses = max(1, $licenses);
                    $item->save();

                    // --- FIX: Preserve licenses in request for upgradeCartDetails ---
                    // This ensures upgradeCartDetails can read the correct upgraded_licenses
                    $request->merge(['licenses' => $licenses, 'license_count' => $licenses]);
                    continue;
                }

                $amounts = $cartCalc->calculateLineAmounts(
                    $item->plan,
                    $licenses,
                    $gstPercentage,
                    $couponPercent
                );

                $item->licenses = $licenses;
                $item->unit_price = $amounts['unit_price'];
                // Unit price is already yearly — unit × licenses.
                $item->grand_total = $cartCalc->lineGrossTotal((float) $amounts['unit_price'], $licenses);
                $item->save();
            }

            $responseItem = $cartItems->first();

            if ($isUpgradeCart || $isDowngradeCart || $isLicenseAddCart) {
                $planChangeItem = $cartItems->first()->fresh(['plan']);
                $licenses = $request->has('licenses')
                    ? max(1, (int) $request->get('licenses'))
                    : max(1, (int) $planChangeItem->licenses);
                $partnerId = (int) $parentCart->partner_id;
                [$orderSubId, $fromPlanId] = $this->resolveUpgradeSourceLineHints($request, $validated, $parentCart);

                $targetPlanId = (int) (
                    $request->input('target_plan_id')
                    ?? $request->input('new_plan_id')
                    ?? $request->input('to_plan_id')
                    ?? $request->input('selected_plan_id')
                    ?? 0
                );
                if ($targetPlanId <= 0 && $request->has('plan_id')) {
                    $reqPlanId = (int) $request->input('plan_id');
                    if ($reqPlanId > 0 && $reqPlanId !== $fromPlanId) {
                        $targetPlanId = $reqPlanId;
                    }
                }

                if ($targetPlanId > 0 && (int) $planChangeItem->plan_id !== $targetPlanId) {
                    $targetPlanObj = Plan::find($targetPlanId);
                    if ($targetPlanObj) {
                        $planChangeItem->plan_id = $targetPlanObj->id;
                        $planChangeItem->unit_price = round((float) ($targetPlanObj->price ?? 0), 2);
                        $planChangeItem->save();
                        $planChangeItem = $planChangeItem->fresh(['plan']);
                        $parentCart->provider_id = $targetPlanObj->provider_id;
                        $parentCart->save();
                    }
                }

                $orderIdHint = $selectedOrderId > 0
                    ? $selectedOrderId
                    : (int) ($parentCart->order_id ?? 0);

                // Same source resolution as upgradeAddToCart so remaining_days and
                // subscription dates stay in sync across add-to-cart and update-cart.
                [$sourceOrder, $sourceItem, $orderId] = $this->resolveUpgradeSourceSubscription(
                    $partnerId,
                    (int) ($parentCart->customer_id ?? 0) ?: null,
                    $orderIdHint > 0 ? $orderIdHint : null,
                    $orderSubId > 0 ? $orderSubId : null,
                    $fromPlanId > 0 ? $fromPlanId : null
                );

                if (!$sourceOrder && $orderIdHint > 0) {
                    $sourceOrder = Order::query()
                        ->whereKey($orderIdHint)
                        ->where('partner_id', $partnerId)
                        ->first();
                    if ($sourceOrder && !$sourceItem) {
                        $itemQuery = OrderItem::query()
                            ->where('order_id', $orderIdHint)
                            ->where(function ($q) {
                                $q->whereNull('status')->orWhere('status', '!=', 'delete');
                            });
                        if ($orderSubId > 0) {
                            $itemQuery->whereKey($orderSubId);
                        } elseif ($fromPlanId > 0) {
                            $itemQuery->where('plan_id', $fromPlanId);
                        }
                        $sourceItem = $itemQuery->orderBy('id')->first();
                    }
                    if ($sourceOrder) {
                        $orderId = (int) $sourceOrder->id;
                    }
                }

                if ($orderId > 0) {
                    $resolvedOrderId = $orderId;
                    $parentCart->order_id = $orderId;
                }

                $this->rememberUpgradeSourceLine($parentCart, $sourceItem);
                if ($sourceOrder) {
                    $cartCalc->assignCartTransferDomain(
                        $parentCart,
                        (string) ($sourceOrder->transfer_domain ?? '')
                    );
                }

                $sourcePlanId = (int) ($sourceItem->plan_id ?? $sourceOrder->plan_id ?? 0);
                $cartPlanId = (int) ($planChangeItem->plan_id ?? 0);
                $licenseTotals = $this->resolveUpgradeLicenseTotals($sourceOrder, $sourceItem);
                $oldTotalLicenses = (int) ($licenseTotals['old_total_licenses'] ?? 0);
                $newTotalLicenses = (int) ($licenseTotals['new_total_licenses'] ?? 0);
                $currentLicenses = max(1, (int) ($licenseTotals['current_licenses'] ?? 1));
                $providerId = (int) ($planChangeItem->plan->provider_id ?? $parentCart->provider_id ?? 0);
                $isPartialUpgradeCart = str_contains(strtolower((string) ($parentCart->item_type ?? '')), 'mode:partial')
                    || $request->attributes->get('_upgrade_mode') === 'partial'
                    || strtolower(trim((string) $request->input('upgrade_mode', ''))) === 'partial';
                if (!$isPartialUpgradeCart && $isUpgradeCart && $licenses < $currentLicenses) {
                    $isPartialUpgradeCart = true;
                    $request->attributes->set('_upgrade_mode', 'partial');
                }

                if (
                    $this->isRequestBasedChangeProvider($providerId)
                    && ($isUpgradeCart || $isDowngradeCart)
                ) {
                    $action = $isLicenseAddCart
                        ? 'license add'
                        : ($isDowngradeCart
                            ? 'downgrade'
                            : ($isPartialUpgradeCart ? 'partial upgrade' : 'upgrade'));

                    return $this->changeRequestRequiredResponse($action, $providerId);
                }

                if (!$isDowngradeCart && !$isLicenseAddCart && $sourcePlanId > 0 && $cartPlanId > 0 && $sourcePlanId === $cartPlanId) {
                    return response()->json([
                        'success' => false,
                        'message' => 'License add is separate from upgrade and partial upgrade. Extra seats on the same plan must use license add.',
                        'use_endpoint' => 'license-add-to-cart',
                        'current_plan_id' => $sourcePlanId,
                        'current_licenses' => $currentLicenses,
                    ], 422);
                }

                if ($isLicenseAddCart) {
                    $licenses = max(1, $licenses);
                } elseif ($isDowngradeCart) {
                    $licenses = $currentLicenses;
                } elseif ($isPartialUpgradeCart) {
                    if ($licenses >= $currentLicenses) {
                        $licenses = max(1, $currentLicenses - 1);
                    }
                } elseif ($licenses !== $currentLicenses) {
                    $licenses = $currentLicenses;
                }

                $subscriptionDates = $this->formatUpgradeSubscriptionDates($sourceOrder, $sourceItem, $planChangeItem);
                $subscriptionStartDate = $subscriptionDates['start'];
                $subscriptionEndDate = $subscriptionDates['end'];

                // Same calculation as update_plan.blade.php / upgradeAddToCart:
                // remaining_value = (current_unit_price / 365) x remaining_days x min(licenses, current_licenses)
                // subtotal = new_unit_price x licenses
                $newUnitPrice = round((float) ($planChangeItem->plan->price ?? 0), 2);
                $calculation = $isLicenseAddCart
                    ? $this->resolveLicenseAddProration(
                        $sourceOrder,
                        $sourceItem,
                        $newUnitPrice,
                        $licenses,
                        $gstPercentage,
                        $couponPercent
                    )
                    : $this->resolveUpgradeProration(
                        $sourceOrder,
                        $sourceItem,
                        $newUnitPrice,
                        $licenses,
                        $gstPercentage,
                        $couponPercent,
                        (int) ($planChangeItem->plan_id ?? 0) ?: null
                    );

                $parentCart->pro_rata_adjustment = $calculation['pro_rata_adjustment'];
                $parentCart->discount_amount = $calculation['coupon_discount'] ?? 0;
                $parentCart->gst_amount = $calculation['gst_amount'];
                $parentCart->grand_total = $calculation['final_payable'];
                if (Schema::connection('pgsql_billing')->hasColumn('carts', 'subtotal')) {
                    $parentCart->subtotal = $calculation['new_plan_cost'];
                }
                $parentCart->save();

                $planChangeItem->licenses = $licenses;
                $planChangeItem->unit_price = $calculation['new_unit_price'];
                $planChangeItem->grand_total = $calculation['new_plan_cost'] ?? $planChangeItem->grand_total;
                $planChangeItem->save();
                $parentCart->refresh();
                $responseItem = $planChangeItem->fresh(['plan']);
            } elseif ($isRenewCart && !$updatingDomainOnly) {
                $partnerId = (int) $parentCart->partner_id;
                $orderId = app(B2bSubscriptionRenewalService::class)->resolveSubscriptionId(
                    $partnerId,
                    $selectedOrderId,
                    (int) ($parentCart->customer_id ?? 0) ?: null,
                    null
                );
                $order = Order::query()->whereKey($orderId)->where('partner_id', $partnerId)->first();
                if (!$order) {
                    return response()->json([
                        'success' => false,
                        'message' => 'Order not found for this partner.',
                    ], 404);
                }

                if ($gstPercentage <= 0) {
                    $gstPercentage = round((float) ($order->gst_rate ?? $order->gst_percentage ?? 18), 2);
                    $parentCart->gst_percentage = $gstPercentage;
                }

                $cartSubtotal = 0.0;
                $orderSubId = (int) ($validated['order_sub_id'] ?? 0);
                foreach ($parentCart->items()->get() as $renewItem) {
                    $planId = (int) ($renewItem->plan_id ?? 0);
                    $licenses = max(1, (int) $renewItem->licenses);
                    $selectedItem = null;
                    if ($orderSubId > 0) {
                        $selectedItem = OrderItem::query()
                            ->whereKey($orderSubId)
                            ->where('order_id', $orderId)
                            ->where('status', '!=', 'delete')
                            ->first();
                    }
                    if (!$selectedItem && $planId > 0) {
                        $selectedItem = OrderItem::query()
                            ->where('order_id', $orderId)
                            ->where('plan_id', $planId)
                            ->where('status', '!=', 'delete')
                            ->orderByDesc('id')
                            ->first();
                    }

                    $unitPrice = 0.0;
                    if ($selectedItem) {
                        $unitPrice = round((float) ($selectedItem->unit_price ?? 0), 2);
                        if ($unitPrice <= 0) {
                            $baseQty = max(1, (int) ($selectedItem->quantity ?? 1));
                            $baseTotal = (float) ($selectedItem->total_amount ?? 0);
                            if ($baseTotal > 0) {
                                $unitPrice = round($baseTotal / $baseQty, 2);
                            }
                        }
                    }
                    if ($unitPrice <= 0) {
                        $unitPrice = round((float) ($order->price ?? 0), 2);
                    }

                    $lineSubtotal = round(max(0, $unitPrice * $licenses), 2);
                    $renewItem->unit_price = $unitPrice;
                    $renewItem->grand_total = $lineSubtotal;
                    $renewItem->save();
                    $cartSubtotal += $lineSubtotal;
                }

                $couponDiscount = $couponPercent > 0
                    ? round(($cartSubtotal * $couponPercent) / 100, 2)
                    : 0.0;
                $taxable = max(0, round($cartSubtotal - $couponDiscount, 2));
                $gstAmount = $taxable > 0
                    ? round(($taxable * $gstPercentage) / 100, 2)
                    : 0.0;
                $grandTotal = round($taxable + $gstAmount, 2);

                $parentCart->discount_amount = $couponDiscount;
                $parentCart->gst_amount = $gstAmount;
                $parentCart->grand_total = $grandTotal;
                $parentCart->save();
                $parentCart->refresh();

                $calculation = [
                    'subtotal' => round($cartSubtotal, 2),
                    'coupon_discount' => $couponDiscount,
                    'gst_amount' => $gstAmount,
                    'final_payable' => $grandTotal,
                    'payable_amount' => $grandTotal,
                ];
                $selectedOrderId = $orderId;
                $resolvedOrderId = $orderId;
                $responseItem = $cartItems->count() === 1
                    ? $cartItems->first()->fresh(['plan'])
                    : ($cartId
                        ? CartItem::query()->with('plan')->whereKey((int) $cartId)->first()
                        : $cartItems->first()->fresh(['plan']));
            } elseif (!$isUpgradeCart && !$isDowngradeCart && !$isRenewCart && !$isLicenseAddCart) {
                $parentCart = $cartCalc->recalculateCartTotals((int) $parentCart->id) ?? $parentCart->refresh();
                $responseItem = $cartItems->count() === 1
                    ? $cartItems->first()->fresh(['plan'])
                    : ($cartId
                        ? CartItem::query()->with('plan')->whereKey((int) $cartId)->first()
                        : $cartItems->first()->fresh(['plan']));
            }

            if (CartItem::query()->where('cart_id', $parentCart->id)->count() === 0) {
                $parentCart->customer_id = null;
                $parentCart->provider_id = null;
                $parentCart->domain_name = null;
                $parentCart->transfer_domain = null;
                $parentCart->discount_amount = 0;
                $parentCart->coupen = null;
                $parentCart->save();
                $parentCart = $parentCart->fresh(['items.plan', 'customer', 'partner']);
            }

            // Keep draft only for plans still in cart; cancel removed draft plans.
            $updatePartnerId = (int) ($parentCart->partner_id ?? 0);
            if ($updatePartnerId > 0 && !$isUpgradeCart && !$isDowngradeCart && !$isRenewCart && !$isLicenseAddCart) {
                if (CartItem::query()->where('cart_id', $parentCart->id)->count() === 0) {
                    $this->cancelDraftOrderForCart($updatePartnerId, (int) $parentCart->id);
                } else {
                    $this->syncDraftOrdersWithCartPlans($updatePartnerId, $parentCart);
                }
                $parentCart = $parentCart->fresh(['items.plan', 'customer', 'partner']) ?? $parentCart;
            }

            $item = $responseItem ?: $cartItems->first();
            if (($isRenewCart || $isUpgradeCart || $isDowngradeCart || $isLicenseAddCart) && $item) {
                $item = CartItem::query()->with('plan')->whereKey((int) $item->id)->first() ?? $item;
            }
            $plan = $item->plan;
            $partner = $parentCart->partner;
            $createdAt = $parentCart->created_at;
            $updatedAt = $parentCart->updated_at;

            $storedDomains = $parentCart->domain_name ?? '';
            $responseDomainArray = [];
            if (is_array($storedDomains)) {
                $responseDomainArray = array_values(array_filter(array_map('trim', $storedDomains)));
            } elseif (is_string($storedDomains) && trim($storedDomains) !== '') {
                $decoded = json_decode($storedDomains, true);
                $responseDomainArray = is_array($decoded)
                    ? array_values(array_filter(array_map('trim', $decoded)))
                    : array_values(array_filter(array_map('trim', explode(',', $storedDomains))));
            }

            $lineAmounts = $isUpgradeCart || $isDowngradeCart || $isRenewCart || $isLicenseAddCart
                ? [
                    'subtotal' => round((float) ($calculation['new_plan_cost'] ?? $calculation['subtotal'] ?? 0), 2),
                    'plan_discount_amount' => 0,
                    'coupon_discount_amount' => round((float) ($calculation['coupon_discount'] ?? 0), 2),
                    'discount_amount' => round((float) ($calculation['coupon_discount'] ?? 0), 2),
                ]
                : $cartCalc->calculateLineAmounts(
                    $plan,
                    (int) $item->licenses,
                    $gstPercentage,
                    $couponPercent
                );

            $currentplandetails = [];
            $responseOrderSubId = $orderSubId ?? 0;
            if (($isUpgradeCart || $isDowngradeCart || $isLicenseAddCart) && empty($responseOrderSubId)) {
                $responseOrderSubId = $this->recallUpgradeSourceSubId($parentCart);
            }
            if ($responseOrderSubId > 0) {
                $detailObj = OrderItem::query()->whereKey((int) $responseOrderSubId)->first();
                if ($detailObj) {
                    $currentplandetails = $detailObj->toArray();
                }
            } elseif (!empty($validated['order_sub_id'])) {
                $detailObj = OrderItem::query()->whereKey((int) $validated['order_sub_id'])->first();
                if ($detailObj) {
                    $currentplandetails = $detailObj->toArray();
                }
            }

            if ($subscriptionStartDate === null && !empty($item->subscription_start_date)) {
                $subscriptionStartDate = \Carbon\Carbon::parse($item->subscription_start_date)->format('Y-m-d');
            }
            if ($subscriptionEndDate === null && !empty($item->subscription_end_date)) {
                $subscriptionEndDate = \Carbon\Carbon::parse($item->subscription_end_date)->format('Y-m-d');
            }

            if ($subscriptionStartDate === null && !empty($currentplandetails['subscription_start_date'])) {
                $subscriptionStartDate = \Carbon\Carbon::parse($currentplandetails['subscription_start_date'])->format('Y-m-d');
            }
            if ($subscriptionEndDate === null && !empty($currentplandetails['subscription_end_date'])) {
                $subscriptionEndDate = \Carbon\Carbon::parse($currentplandetails['subscription_end_date'])->format('Y-m-d');
            }

            $payableAmount = round((float) (
                $calculation['final_payable'] ?? $parentCart->grand_total ?? 0
            ), 2);
            $creditDetails = $this->partnerB2bCreditSummary((int) $parentCart->partner_id, $payableAmount);
            $signRequired = strtolower(trim((string) (
                Partner::query()->whereKey((int) $parentCart->partner_id)->value('aadhaar_mandatory') ?? 'no'
            ))) === 'yes';
            $draftOrder = $this->resolveDraftOrderForCart((int) $parentCart->partner_id, $parentCart);
            $draftFlags = $this->syncedDraftFlags($draftOrder, $signRequired, (int) $parentCart->id);
            if ($resolvedOrderId === null && !empty($draftFlags['order_id'])) {
                $resolvedOrderId = (int) $draftFlags['order_id'];
            }
            return response()->json([
                'success' => true,
                'message' => 'Cart updated successfully',
                'data' => array_merge([
                    'main_cart_id' => $parentCart->id,
                    'cart_id' => $item->id,
                    'order_id' => $resolvedOrderId,
                    'partner_id' => $parentCart->partner_id,
                    'customer_id' => $parentCart->customer_id,
                    'provider_id' => $parentCart->provider_id ?? ($plan->provider_id ?? null),
                    'company_name' => $companyName,
                    'plan_id' => $item->plan_id,
                    'partner' => [
                        'name' => optional($partner)->name,
                        'email' => optional($partner)->email,
                        'mobile' => optional($partner)->mobile,
                        'wallet_balance' => round(PartnerCreditService::remainingPurchaseAllowance((int) ($parentCart->partner_id ?? 0)), 2),
                        'available_balance' => round(PartnerCreditService::remainingPurchaseAllowance((int) ($parentCart->partner_id ?? 0)), 2),
                        'credit_limit' => round((float) (optional($partner)->credit_limit ?? 0), 2),
                    ],
                    'customer' => [
                        'id' => optional($customer)->id ?? optional($parentCart->customer)->id,
                        'name' => optional($customer)->name ?? optional($parentCart->customer)->name,
                        'email' => optional($customer)->email ?? optional($parentCart->customer)->email,
                        'mobile' => optional($customer)->mobile ?? optional($parentCart->customer)->mobile,
                        'company_name' => optional($customer)->company_name ?? optional($parentCart->customer)->company_name ?? '-',
                        'address' => optional($customer)->address ?? optional($parentCart->customer)->address,
                    ],
                    'plan' => [
                        'plan_name' => $plan->name ?? '',
                        'title' => $plan->title ?? '',
                        'storage' => $plan->storage ?? '',
                        'billing_cycle' => $plan->billing_cycle ?? '',
                        'actual_price' => $plan->actual_price ?? 0,
                        'selling_price' => $plan->price ?? 0,
                        'provider_id' => $parentCart->provider_id ?? ($plan->provider_id ?? null),
                    ],
                    'current_plan_details' => $currentplandetails,
                    'domain_name' => $responseDomainArray,
                    'transfer_domain' => $parentCart->transfer_domain ?? null,
                    'subscription_start_date' => date('d-m-Y', strtotime($subscriptionStartDate)),
                    'subscription_end_date' => date('d-m-Y', strtotime($subscriptionEndDate)),
                    'licenses' => (int) ($request->input('licenses', $item->licenses ?? 1)),

                    'unit_price' => round((float) (
                        $isRenewCart
                        ? ($item->unit_price ?? 0)
                        : ($calculation['new_unit_price'] ?? $item->unit_price ?? 0)
                    ), 2),
                    'coupen' => $coupen,
                    'coupon_discount_percent' => $couponPercent,
                    'remaining_value' => round((float) (
                        $calculation['remaining_value']
                        ?? (($isUpgradeCart || $isDowngradeCart) ? ($parentCart->pro_rata_adjustment ?? 0) : 0)
                    ), 2),
                    'remaining_credit' => round((float) (
                        $calculation['remaining_credit']
                        ?? (($isUpgradeCart || $isDowngradeCart) ? ($parentCart->pro_rata_adjustment ?? 0) : 0)
                    ), 2),
                    'pro_rata_adjustment' => round((float) (
                        $calculation['pro_rata_adjustment']
                        ?? (($isUpgradeCart || $isDowngradeCart) ? ($parentCart->pro_rata_adjustment ?? 0) : 0)
                    ), 2),
                    'applied_pro_rata' => round((float) ($calculation['applied_pro_rata'] ?? 0), 2),
                    'new_plan_cost' => round((float) ($calculation['new_plan_cost'] ?? $lineAmounts['subtotal'] ?? 0), 2),
                    'subtotal' => round((float) ($calculation['new_plan_cost'] ?? $lineAmounts['subtotal'] ?? 0), 2),
                    'credit_licenses' => (int) ($calculation['credit_licenses'] ?? 0),
                    'old_total_licenses' => (int) ($oldTotalLicenses ?? 0),
                    'new_total_licenses' => (int) ($newTotalLicenses ?? 0),
                    'current_licenses' => (int) (($currentLicenses > 0) ? $currentLicenses : ($calculation['current_licenses'] ?? 0)),
                    'total_licenses' => (int) (($currentLicenses > 0) ? $currentLicenses : ($calculation['current_licenses'] ?? 0)),
                    'current_unit_price' => round((float) ($calculation['current_unit_price'] ?? 0), 2),
                    'daily_rate_per_license' => round((float) ($calculation['daily_rate_per_license'] ?? 0), 2),
                    'remaining_days' => (int) ($calculation['remaining_days'] ?? 0),
                    'taxable_amount' => round((float) ($calculation['taxable_amount'] ?? 0), 2),
                    'gst_amount' => round((float) ($calculation['gst_amount'] ?? $parentCart->gst_amount ?? 0), 2),
                    'final_payable' => round((float) ($calculation['final_payable'] ?? $parentCart->grand_total ?? 0), 2),
                    'pricing' => [
                        'subtotal' => $lineAmounts['subtotal'],
                        'new_plan_cost' => round((float) ($calculation['new_plan_cost'] ?? $lineAmounts['subtotal']), 2),
                        'remaining_credit' => round((float) ($calculation['remaining_credit'] ?? 0), 2),
                        'remaining_value' => round((float) ($calculation['remaining_value'] ?? 0), 2),
                        'wallet_credit' => round((float) ($calculation['wallet_credit'] ?? 0), 2),
                        'remaining_days' => (int) ($calculation['remaining_days'] ?? 0),
                        'credit_licenses' => (int) ($calculation['credit_licenses'] ?? 0),
                        'current_licenses' => (int) ($calculation['current_licenses'] ?? 0),
                        'current_unit_price' => round((float) ($calculation['current_unit_price'] ?? 0), 2),
                        'daily_rate_per_license' => round((float) ($calculation['daily_rate_per_license'] ?? 0), 2),
                        'final_payable' => round((float) ($calculation['final_payable'] ?? $parentCart->grand_total ?? 0), 2),
                        'plan_discount_amount' => $lineAmounts['plan_discount_amount'],
                        'coupon_discount_amount' => $lineAmounts['coupon_discount_amount'],
                        'discount_amount' => $lineAmounts['discount_amount'],
                        'pro_rata_adjustment' => round((float) ($calculation['pro_rata_adjustment'] ?? 0), 2),
                        'applied_pro_rata' => round((float) ($calculation['applied_pro_rata'] ?? 0), 2),
                        'gst_percentage' => round($gstPercentage, 2),
                        'gst_amount' => round((float) ($calculation['gst_amount'] ?? $parentCart->gst_amount ?? 0), 2),
                        'taxable_amount' => round((float) ($calculation['taxable_amount'] ?? 0), 2),
                        'grand_total' => round((float) ($calculation['final_payable'] ?? $parentCart->grand_total ?? 0), 2),
                        'item_grand_total' => round((float) (
                            ($isUpgradeCart || $isDowngradeCart || $isLicenseAddCart)
                            ? ($calculation['new_plan_cost'] ?? $item->grand_total ?? 0)
                            : $item->grand_total
                        ), 2),
                    ],
                    'created_at' => $createdAt?->format('Y-m-d H:i:s'),
                    'updated_at' => $updatedAt?->format('Y-m-d H:i:s'),
                    'credit_limit' => $creditDetails['credit_limit'],
                    'credit_used' => $creditDetails['credit_used'],
                    'remaining_credit_limit' => $creditDetails['remaining_credit_limit'],
                    'credit_limit_reached' => $creditDetails['credit_limit_reached'],
                    'can_purchase' => $creditDetails['can_purchase'],
                    'purchase_block_message' => $creditDetails['purchase_block_message'],
                    'license_decrease' => $licenseDecreaseMeta,
                ], $draftFlags),
            ]);
        } catch (\Throwable $e) {
            return response()->json([
                'success' => false,
                'message' => 'An error occurred while updating the cart',
                'error' => $e->getMessage(),
            ], 500);
        }
    }


    public function fetchupdated(Request $request)
    {
        try {
            $request->validate([
                'partner_id' => 'required|numeric|exists:pgsql_auth.partners,id',
                'plan_id'    => 'required|numeric|exists:pgsql_product.plans,id',
            ]);

            $partnerId = (int) $request->query('partner_id');
            $planId = (int) $request->query('plan_id');
            $cartService = app(PartnerCartService::class);

            $item = null;
            $parentCart = $cartService->getActiveCartWithItems($partnerId, Cart::TYPE_STANDARD);
            if ($parentCart) {
                $item = $parentCart->items->firstWhere('plan_id', $planId);
            }

            if ($item) {
                $item->load(['plan', 'cart.partner', 'cart.customer']);
                $customer = $item->cart->customer;
                $plan = $item->plan;
                $partner = $item->cart->partner;
                $walletBalance = round(PartnerCreditService::remainingPurchaseAllowance((int) ($item->cart->partner_id ?? 0)), 2);
                $gstPercentage = (float) ($item->cart->gst_percentage ?? 18);
                $amounts = $cartService->calculateLineAmounts($plan, (int) $item->licenses, $gstPercentage);

                $planName = $plan ? ($plan->title ?? $plan->name ?? '-') : '-';
                $providerId = $plan->provider_id ?? null;
                $providerName = '-';
                if ($providerId) {
                    $provider = Provider::select('id', 'name')->find($providerId);
                    $providerName = $provider->name ?? '-';
                }

                $createdAt = optional($item->cart->created_at)->format('Y-m-d H:i:s');
                $endDate = null;
                if (!empty($item->subscription_end_date)) {
                    try {
                        $endDate = Carbon::parse($item->subscription_end_date)->format('Y-m-d H:i:s');
                    } catch (\Exception $ex) {
                        $endDate = $item->subscription_end_date;
                    }
                }

                return response()->json([
                    'success' => true,
                    'message' => 'Cart details fetched successfully',
                    'data' => [
                        'cart_id'         => $item->id,
                        'partner_id'      => $item->cart->partner_id,
                        'customer_id'     => $item->cart->customer_id,
                        'company_name'    => $customer ? ($customer->company_name ?? '-') : '-',
                        'plan_id'         => $item->plan_id,
                        'plan_name'       => $planName,
                        'provider_id'     => $providerId,
                        'provider_name'   => $providerName,
                        'domain_name'     => $cartService->cartDomainNameString($item->cart),
                        'licenses'        => $item->licenses,
                        'unit_price'      => $item->unit_price,
                        'coupen'          => $item->cart->coupen,
                        'discount_amount' => $amounts['discount_amount'],
                        'gst_percentage'  => $gstPercentage,
                        'gst_amount'      => round((float) ($item->cart->gst_amount ?? 0), 2),
                        'grand_total'     => round((float) ($item->cart->grand_total ?? 0), 2),
                        'wallet_balance'  => (float) $walletBalance,
                        'created_at'      => $createdAt,
                        'end_date'        => $endDate,
                    ],
                ]);
            }

            return response()->json([
                'success' => false,
                'message' => 'Cart not found',
                'data' => null,
            ], 404);
        } catch (\Illuminate\Validation\ValidationException $ex) {
            return response()->json([
                'success' => false,
                'message' => 'Validation error',
                'errors'  => $ex->errors(),
            ], 422);
        } catch (\Exception $e) {
            return response()->json([
                'success' => false,
                'message' => 'An error occurred while fetching cart details',
                'error' => $e->getMessage(),
            ], 500);
        }
    }


    public function deleteCart(Request $request)
    {
        try {
            $validated = $request->validate([
                'cart_id' => 'required|integer',
                'main_cart_id' => 'nullable|integer|exists:pgsql_billing.carts,id',
                'partner_id' => 'nullable|exists:pgsql_auth.partners,id',
                'transfer_domain' => 'nullable|in:yes,no',
            ]);
        } catch (\Illuminate\Validation\ValidationException $e) {
            return response()->json([
                'success' => false,
                'message' => 'Validation failed',
                'errors' => $e->errors(),
            ], 422);
        }

        try {
            $cartService = app(PartnerCartService::class);
            $result = $cartService->deleteCartItemOrParent((int) $validated['cart_id']);

            if (!$result['deleted']) {
                return response()->json([
                    'success' => false,
                    'message' => 'Cart not found',
                ], 404);
            }

            $parentCart = $result['cart'];
            if ($parentCart && $request->has('transfer_domain')) {
                $remainingItems = CartItem::query()->where('cart_id', $parentCart->id)->count();
                if ($remainingItems > 0) {
                    $cartService->assignCartTransferDomain($parentCart, $validated['transfer_domain']);
                    $parentCart = $parentCart->fresh(['items.plan', 'customer']);
                }
            }

            $partnerId = (int) ($validated['partner_id'] ?? ($parentCart->partner_id ?? 0));
            $parentCartId = (int) ($result['parent_cart_id'] ?? ($parentCart->id ?? 0));
            $remainingItems = $parentCartId > 0
                ? (int) CartItem::query()->where('cart_id', $parentCartId)->count()
                : 0;

            // Remove draft when its plan(s) were deleted (or cart emptied).
            if ($partnerId > 0 && $parentCartId > 0) {
                if ($remainingItems <= 0) {
                    $this->cancelDraftOrderForCart($partnerId, $parentCartId);
                    $parentCart = null;
                } elseif ($parentCart) {
                    $parentCart = $parentCart->fresh(['items.plan', 'customer']) ?? $parentCart;
                    $this->syncDraftOrdersWithCartPlans($partnerId, $parentCart);
                    $parentCart = $parentCart->fresh(['items.plan', 'customer']) ?? $parentCart;
                }
            }

            $signRequired = false;
            if ($partnerId > 0) {
                $signRequired = strtolower(trim((string) (
                    Partner::query()->whereKey($partnerId)->value('aadhaar_mandatory') ?? 'no'
                ))) === 'yes';
            }
            $draftOrder = ($parentCart && $remainingItems > 0)
                ? $this->resolveDraftOrderForCart($partnerId, $parentCart)
                : null;
            $draftFlags = $this->syncedDraftFlags(
                $draftOrder,
                $signRequired,
                ($parentCart && $remainingItems > 0) ? (int) $parentCart->id : 0
            );

            $data = [
                'item_id' => $result['item_id'],
                'parent_cart_id' => $result['parent_cart_id'],
                'parent_deleted' => $remainingItems <= 0,
                'sign_required' => $signRequired ? 'yes' : 'no',
            ];
            $data = array_merge($data, $draftFlags);

            if ($parentCart && $remainingItems > 0) {
                $partner = Partner::select('id', 'wallet_balance')->find($partnerId);
                if ($partner) {
                    $data = array_merge(
                        $cartService->formatCartWithItemsResponse($parentCart, $partner),
                        $draftFlags,
                        ['sign_required' => $signRequired ? 'yes' : 'no']
                    );
                } else {
                    $data['transfer_domain'] = $cartService->cartTransferDomain($parentCart);
                    $data['customer_id'] = $parentCart->customer_id;
                    $data['provider_id'] = $parentCart->provider_id;
                    $data['domain_name'] = $cartService->cartDomainNameToArray($parentCart);
                }
            }

            return response()->json(array_merge([
                'success' => true,
                'message' => $remainingItems <= 0
                    ? 'Cart cleared. Draft removed.'
                    : 'Cart item removed successfully',
                'data' => $data,
                'sign_required' => $signRequired ? 'yes' : 'no',
            ], $draftFlags));
        } catch (\Throwable $e) {
            return response()->json([
                'success' => false,
                'message' => 'An error occurred while deleting the cart item',
                'error' => $e->getMessage(),
            ], 500);
        }
    }

    /**
     * Partial upgrade = fewer seats moved to a higher plan.
     * Parent order keeps leftover seats; the new CH order shows the upgraded subset.
     */
    public function partialUpgradeAddToCart(Request $request)
    {
        try {

            /*
        |--------------------------------------------------------------------------
        | Normalize request
        |--------------------------------------------------------------------------
        */

            $this->normalizeUpgradeCartRequest($request);
            $this->sanitizeOrderIdInRequest($request);

            if (!$request->filled('licenses') && $request->filled('license_count')) {
                $request->merge([
                    'licenses' => (int) $request->input('license_count')
                ]);
            }

            /*
        |--------------------------------------------------------------------------
        | Validate request
        |--------------------------------------------------------------------------
        */

            $validated = $request->validate([
                'partner_id' => 'required|exists:pgsql_auth.partners,id',
                'plan_id' => 'nullable|integer|exists:pgsql_product.plans,id',
                'order_id' => 'nullable|integer|exists:pgsql_billing.orders,id',
                'order_sub_id' => 'nullable|integer',
                'order_item_id' => 'nullable|integer',
                'from_plan_id' => 'nullable|integer',
                'current_plan_id' => 'nullable|integer',
                'customer_id' => 'nullable|exists:pgsql_billing.customers,id',
                'company_name' => 'nullable|string',
                'licenses' => 'nullable|integer|min:1',
                'license_count' => 'nullable|integer|min:1',
                'main_cart_id' => 'nullable|integer',
                'cart_id' => 'nullable|integer',
            ]);

            /*
        |--------------------------------------------------------------------------
        | Target plan
        |--------------------------------------------------------------------------
        */

            $targetPlanId = (int) ($validated['plan_id'] ?? 0);

            if ($targetPlanId <= 0) {
                return response()->json([
                    'success' => false,
                    'message' => 'plan_id is required for partial upgrade. Send the target higher plan as plan_id.',
                    'errors' => [
                        'plan_id' => [
                            'The plan id field is required.'
                        ]
                    ],
                ], 422);
            }

            $partnerId = (int) $validated['partner_id'];

            $customerId = !empty($validated['customer_id'])
                ? (int) $validated['customer_id']
                : null;

            $licenses = (int) (
                $validated['licenses']
                ?? $validated['license_count']
                ?? 0
            );

            if ($licenses <= 0) {
                $licenses = (int) $request->input(
                    'licenses',
                    $request->input('license_count', 0)
                );
            }

            /*
        |--------------------------------------------------------------------------
        | Resolve source hints
        |--------------------------------------------------------------------------
        */

            [$orderSubIdHint, $fromPlanIdHint] =
                $this->resolveUpgradeSourceLineHints(
                    $request,
                    $validated
                );

            /*
        |--------------------------------------------------------------------------
        | Resolve subscription order
        |--------------------------------------------------------------------------
        */

            $subscriptionOrderId = null;

            if ($customerId) {
                try {

                    $subscriptionOrderId =
                        app(B2bSubscriptionUpgradeService::class)
                        ->resolveSubscriptionId(
                            $partnerId,

                            isset($validated['order_id'])
                                && (int) $validated['order_id'] > 0
                                ? (int) $validated['order_id']
                                : null,

                            $customerId,
                            null
                        );
                } catch (\Illuminate\Validation\ValidationException $e) {

                    return response()->json([
                        'success' => false,
                        'message' => collect($e->errors())
                            ->flatten()
                            ->first()
                            ?: 'Subscription not found for customer.',
                        'errors' => $e->errors(),
                    ], 422);
                }
            }

            if (
                !$subscriptionOrderId
                && isset($validated['order_id'])
                && (int) $validated['order_id'] > 0
            ) {
                $subscriptionOrderId = (int) $validated['order_id'];
            }

            if (!$subscriptionOrderId) {
                return response()->json([
                    'success' => false,
                    'message' => 'order_id or customer_id is required for partial upgrade.',
                ], 422);
            }

            /*
        |--------------------------------------------------------------------------
        | Resolve source subscription
        |--------------------------------------------------------------------------
        */

            [$sourceOrder, $sourceItem, $resolvedOrderId] =
                $this->resolveUpgradeSourceSubscription(
                    $partnerId,
                    $customerId,
                    $subscriptionOrderId,

                    $orderSubIdHint > 0
                        ? $orderSubIdHint
                        : null,

                    $fromPlanIdHint > 0
                        ? $fromPlanIdHint
                        : null
                );

            if (!$sourceOrder) {
                return response()->json([
                    'success' => false,
                    'message' => 'Active subscription not found for partial upgrade.',
                ], 404);
            }

            /*
        |--------------------------------------------------------------------------
        | Current plan
        |--------------------------------------------------------------------------
        */

            $currentPlanId = (int) (
                $sourceItem->plan_id
                ?? $sourceOrder->plan_id
                ?? 0
            );

            if ($currentPlanId <= 0) {
                return response()->json([
                    'success' => false,
                    'message' => 'Current plan not found on subscription.',
                ], 422);
            }

            /*
        |--------------------------------------------------------------------------
        | TOTAL LICENSE CALCULATION
        |--------------------------------------------------------------------------
        |
        | OLD = current subscription line
        | NEW = activated license-add seats on the same plan
        | TOTAL = old + new (used for upgrade / partial upgrade)
        |
        */

            $licenseTotals = $this->resolveUpgradeLicenseTotals($sourceOrder, $sourceItem);
            $oldTotalLicenses = (int) $licenseTotals['old_total_licenses'];
            $newTotalLicenses = (int) $licenseTotals['new_total_licenses'];
            $currentLicenses = (int) $licenseTotals['current_licenses'];

            /*
        |--------------------------------------------------------------------------
        | DEBUG
        |--------------------------------------------------------------------------
        */

            Log::info(
                'PARTIAL UPGRADE TOTAL LICENSE DEBUG',
                [
                    'source_order_id' => $sourceOrder->id ?? null,

                    'old_total_licenses' =>
                    $oldTotalLicenses,

                    'new_total_licenses' =>
                    $newTotalLicenses,

                    'TOTAL_LICENSES' =>
                    $currentLicenses,

                    'REQUESTED_LICENSES' =>
                    $licenses,
                ]
            );

            /*
        |--------------------------------------------------------------------------
        | Target plan
        |--------------------------------------------------------------------------
        */

            $requestedPlan = Plan::query()->find($targetPlanId);

            if (!$requestedPlan) {

                return response()->json([
                    'success' => false,
                    'message' => 'Target plan not found.',
                ], 404);
            }

            /*
        |--------------------------------------------------------------------------
        | Same plan check
        |--------------------------------------------------------------------------
        */

            if ((int) $requestedPlan->id === $currentPlanId) {

                return response()->json([
                    'success' => false,
                    'message' =>
                    'You cannot upgrade to the same plan. Please select a higher plan.',

                    'data' => [

                        'current_plan_id' =>
                        $currentPlanId,

                        'selected_plan_id' =>
                        $requestedPlan->id,

                        'current_plan_name' =>
                        optional(
                            Plan::find($currentPlanId)
                        )->name,

                        'selected_plan_name' =>
                        $requestedPlan->name,
                    ],

                ], 422);
            }

            /*
        |--------------------------------------------------------------------------
        | Higher plan check
        |--------------------------------------------------------------------------
        */

            if (!$this->isHigherPlan(
                $requestedPlan,
                $currentPlanId
            )) {

                return response()->json([
                    'success' => false,

                    'message' =>
                    'Partial upgrade must move selected licenses to a higher plan.',

                    'current_plan_id' =>
                    $currentPlanId,

                    'requested_plan_id' =>
                    $requestedPlan->id,

                    'requested_plan_name' =>
                    $requestedPlan->name,

                    'current_plan_price' =>
                    $this->planRankPrice(
                        Plan::find($currentPlanId)
                    ),

                    'requested_plan_price' =>
                    $this->planRankPrice(
                        $requestedPlan
                    ),
                ], 422);
            }

            /*
        |--------------------------------------------------------------------------
        | Validate partial license quantity
        |--------------------------------------------------------------------------
        */

            if ($licenses <= 0) {
                $licenses = 1;
            }

            /*
        |--------------------------------------------------------------------------
        | Partial upgrade requires at least 2 TOTAL licenses
        |--------------------------------------------------------------------------
        */

            if ($currentLicenses <= 1) {

                return response()->json([
                    'success' => false,

                    'message' =>
                    'You have only '
                        . $currentLicenses
                        . ' license. Partial upgrade requires at least 2 licenses.',

                    'use_endpoint' =>
                    'upgrade-add-to-cart',

                    'current_licenses' =>
                    $currentLicenses,

                    'old_total_licenses' =>
                    $oldTotalLicenses,

                    'new_total_licenses' =>
                    $newTotalLicenses,

                ], 422);
            }

            /*
        |--------------------------------------------------------------------------
        | Cannot move all licenses
        |--------------------------------------------------------------------------
        */

            if ($licenses >= $currentLicenses) {

                return response()->json([
                    'success' => false,

                    'message' =>
                    'Partial upgrade must select fewer than the current '
                        . $currentLicenses
                        . ' licenses.',

                    'use_endpoint' =>
                    'upgrade-add-to-cart',

                    /*
                |--------------------------------------------------------------------------
                | OLD
                |--------------------------------------------------------------------------
                */

                    'old_total_licenses' =>
                    $oldTotalLicenses,

                    /*
                |--------------------------------------------------------------------------
                | NEW
                |--------------------------------------------------------------------------
                */

                    'new_total_licenses' =>
                    $newTotalLicenses,

                    /*
                |--------------------------------------------------------------------------
                | TOTAL OLD + NEW
                |--------------------------------------------------------------------------
                */

                    'current_licenses' =>
                    $currentLicenses,

                    'total_licenses' =>
                    $currentLicenses,

                    'suggestion' =>
                    'Select between 1 and '
                        . ($currentLicenses - 1)
                        . ' licenses.',
                ], 422);
            }

            /*
        |--------------------------------------------------------------------------
        | Provider
        |--------------------------------------------------------------------------
        */

            $providerId = (int) (
                $requestedPlan->provider_id ?? 0
            );

            if ($providerId <= 0) {

                $providerId = (int) (
                    Plan::query()
                    ->whereKey($currentPlanId)
                    ->value('provider_id')
                    ?? 0
                );
            }

            /*
        |--------------------------------------------------------------------------
        | Prepare upgrade request
        |--------------------------------------------------------------------------
        */

            $request->merge([

                'plan_id' =>
                (int) $requestedPlan->id,

                'from_plan_id' =>
                $currentPlanId,

                'current_plan_id' =>
                $currentPlanId,

                'order_id' =>
                (int) $sourceOrder->id,

                'licenses' =>
                $licenses,

                'license_count' =>
                $licenses,

                'order_category' =>
                'partial_upgrade',

                'upgrade_type' =>
                'partial',

                'is_partial_upgrade' =>
                true,

                'partial_upgrade' =>
                true,

                'parent_order_id' =>
                (int) $sourceOrder->id,

                'total_licenses_for_proration' =>
                $currentLicenses, // <-- CRITICAL FIX: Pass total licenses for proration
            ]);

            /*
        |--------------------------------------------------------------------------
        | Source order item
        |--------------------------------------------------------------------------
        */

            if (
                $sourceItem
                && (int) ($sourceItem->id ?? 0) > 0
            ) {

                $request->merge([

                    'order_sub_id' =>
                    (int) $sourceItem->id,

                    'order_item_id' =>
                    (int) $sourceItem->id,

                    'previous_order_sub_id' =>
                    (int) $sourceItem->id,

                    'previous_plan_id' =>
                    $currentPlanId,

                    'old_plan_id' =>
                    $currentPlanId,
                ]);
            }

            if ($customerId) {

                $request->merge([
                    'customer_id' =>
                    $customerId
                ]);
            }

            /*
        |--------------------------------------------------------------------------
        | Request attributes
        |--------------------------------------------------------------------------
        */

            $request->attributes->set(
                '_upgrade_mode',
                'partial'
            );

            $request->attributes->set(
                '_bypass_request_block',
                true
            );

            /*
        |--------------------------------------------------------------------------
        | Logging
        |--------------------------------------------------------------------------
        */

            Log::info(
                'partialUpgradeAddToCart calling upgradeAddToCart',
                [

                    'plan_id' =>
                    (int) $requestedPlan->id,

                    'from_plan_id' =>
                    $currentPlanId,

                    'order_id' =>
                    (int) $sourceOrder->id,

                    'parent_order_id' =>
                    (int) $sourceOrder->id,

                    /*
                | Selected
                */

                    'licenses' =>
                    $licenses,

                    /*
                | OLD
                */

                    'old_total_licenses' =>
                    $oldTotalLicenses,

                    /*
                | NEW
                */

                    'new_total_licenses' =>
                    $newTotalLicenses,

                    /*
                | TOTAL
                */

                    'current_licenses' =>
                    $currentLicenses,

                    /*
                | Remaining
                */

                    'remaining_licenses' =>
                    $currentLicenses - $licenses,

                    'upgrade_mode' =>
                    'partial',

                    'order_category' =>
                    'partial_upgrade',

                    'order_sub_id' =>
                    $request->input('order_sub_id'),

                    'previous_order_sub_id' =>
                    $request->input(
                        'previous_order_sub_id'
                    ),

                    'total_licenses_for_proration' =>
                    $currentLicenses,
                ]
            );

            /*
        |--------------------------------------------------------------------------
        | Create cart
        |--------------------------------------------------------------------------
        */

            $addToCartResponse =
                $this->upgradeAddToCart($request);

            $payload = json_decode(
                $addToCartResponse->getContent(),
                true
            );

            if (!($payload['success'] ?? false)) {
                return $addToCartResponse;
            }

            /*
        |--------------------------------------------------------------------------
        | Cart response
        |--------------------------------------------------------------------------
        */

            $mainCartId = (int) (

                $payload['data']['main_cart_id']
                ?? $payload['cart_data']['main_cart_id']
                ?? 0
            );

            $plans =
                $payload['data']['plans']
                ?? $payload['cart_data']['plans']
                ?? [];

            $currentPlanDetails =
                $payload['data']['currentplandetails']
                ?? $payload['cart_data']['current_plan']
                ?? [];

            Log::info(
                'partialUpgradeAddToCart cart created',
                [
                    'main_cart_id' =>
                    $mainCartId,

                    'plans_count' =>
                    count($plans),

                    'old_total_licenses' =>
                    $oldTotalLicenses,

                    'new_total_licenses' =>
                    $newTotalLicenses,

                    'total_licenses' =>
                    $currentLicenses,
                ]
            );

            /*
        |--------------------------------------------------------------------------
        | Plan objects
        |--------------------------------------------------------------------------
        */

            $sourcePlanObj =
                Plan::query()->find(
                    $currentPlanId
                );

            $targetPlanObj =
                Plan::query()->find(
                    $targetPlanId
                );

            /*
        |--------------------------------------------------------------------------
        | Provider name
        |--------------------------------------------------------------------------
        */

            $providerName =
                $providerId === 1
                ? 'Tizzy'
                : (
                    $providerId === 2
                    ? 'Microsoft'
                    : (
                        $providerId === 3
                        ? 'Google'
                        : ''
                    )
                );

            /*
        |--------------------------------------------------------------------------
        | Create enquiry/request
        |--------------------------------------------------------------------------
        */

            $enquiryId = null;

            if ($partnerId > 0) {

                try {

                    $lines = [

                        $providerName
                            . ' partial upgrade request',

                        'Order ID: '
                            . (int) $sourceOrder->id,

                        'Order sub ID: '
                            . (int) (
                                $sourceItem->id ?? 0
                            ),

                        'Current plan ID: '
                            . $currentPlanId,

                        'Requested plan ID: '
                            . $targetPlanId,

                        /*
                    | OLD
                    */

                        'Old total licenses: '
                            . $oldTotalLicenses,

                        /*
                    | NEW
                    */

                        'New/upgrade licenses: '
                            . $newTotalLicenses,

                        /*
                    | TOTAL
                    */

                        'Total licenses: '
                            . $currentLicenses,

                        /*
                    | Selected
                    */

                        'Upgraded licenses: '
                            . $licenses,

                        /*
                    | Remaining
                    */

                        'Remaining licenses: '
                            . max(
                                0,
                                $currentLicenses - $licenses
                            ),

                        'Customer ID: '
                            . ($customerId ?? 0),
                    ];

                    $enquiry =
                        Enquiry::query()->create([

                            'partner_id' =>
                            $partnerId,

                            'message' =>
                            implode(
                                "\n",
                                $lines
                            ),

                            'status' =>
                            'new',
                        ]);

                    $enquiryId =
                        (int) (
                            $enquiry->id ?? 0
                        );
                } catch (\Throwable $e) {

                    Log::warning(
                        'Failed to create enquiry for partial upgrade',
                        [
                            'partner_id' =>
                            $partnerId,

                            'error' =>
                            $e->getMessage(),
                        ]
                    );
                }
            }

            /*
        |--------------------------------------------------------------------------
        | Current plan response
        |--------------------------------------------------------------------------
        */

            $currentPlanData =
                $sourcePlanObj
                ? [

                    'id' =>
                    (int) $sourcePlanObj->id,

                    'plan_id' =>
                    (int) $sourcePlanObj->id,

                    'name' =>
                    (string) (
                        $sourcePlanObj->name
                        ?? $sourcePlanObj->title
                        ?? ''
                    ),

                    'title' =>
                    (string) (
                        $sourcePlanObj->title
                        ?? $sourcePlanObj->name
                        ?? ''
                    ),

                    'plan_name' =>
                    (string) (
                        $sourcePlanObj->name
                        ?? $sourcePlanObj->title
                        ?? ''
                    ),

                    'price' =>
                    (float) (
                        $sourcePlanObj->price ?? 0
                    ),

                    'amount' =>
                    (float) (
                        $sourcePlanObj->price ?? 0
                    ),

                    /*
                    | TOTAL OLD + NEW
                    */

                    'licenses' =>
                    $currentLicenses,

                    'old_total_licenses' =>
                    $oldTotalLicenses,

                    'new_total_licenses' =>
                    $newTotalLicenses,

                    'provider_id' =>
                    (int) (
                        $sourcePlanObj->provider_id ?? 0
                    ),

                    'provider_name' =>
                    $providerName,

                    // <-- CRITICAL FIX: Add remaining licenses info
                    'remaining_licenses' =>
                    max(0, $currentLicenses - $licenses),

                    'upgraded_licenses' =>
                    $licenses,

                ]
                : [];

            /*
        |--------------------------------------------------------------------------
        | Target plan response
        |--------------------------------------------------------------------------
        */

            $targetPlanData =
                $targetPlanObj
                ? [

                    'id' =>
                    (int) $targetPlanObj->id,

                    'plan_id' =>
                    (int) $targetPlanObj->id,

                    'name' =>
                    (string) (
                        $targetPlanObj->name
                        ?? $targetPlanObj->title
                        ?? ''
                    ),

                    'title' =>
                    (string) (
                        $targetPlanObj->title
                        ?? $targetPlanObj->name
                        ?? ''
                    ),

                    'plan_name' =>
                    (string) (
                        $targetPlanObj->name
                        ?? $targetPlanObj->title
                        ?? ''
                    ),

                    'price' =>
                    (float) (
                        $targetPlanObj->price ?? 0
                    ),

                    'amount' =>
                    (float) (
                        $targetPlanObj->price ?? 0
                    ),

                    'licenses' =>
                    $licenses,

                    'provider_id' =>
                    (int) (
                        $targetPlanObj->provider_id ?? 0
                    ),

                    'provider_name' =>
                    $providerName,

                ]
                : [];

            /*
        |--------------------------------------------------------------------------
        | Remaining licenses
        |--------------------------------------------------------------------------
        */

            $remainingLicenses =
                max(
                    0,
                    $currentLicenses - $licenses
                );

            /*
        |--------------------------------------------------------------------------
        | Get proration calculation from the cart response
        |--------------------------------------------------------------------------
        */

            $cartPricing = [];
            if (!empty($plans) && is_array($plans)) {
                $firstPlan = $plans[0] ?? [];
                $cartPricing = [
                    'remaining_value' => (float) ($firstPlan['remaining_value'] ?? 0),
                    'remaining_credit' => (float) ($firstPlan['remaining_credit'] ?? 0),
                    'pro_rata_adjustment' => (float) ($firstPlan['pro_rata_adjustment'] ?? 0),
                    'applied_pro_rata' => (float) ($firstPlan['applied_pro_rata'] ?? 0),
                    'new_plan_cost' => (float) ($firstPlan['subtotal'] ?? $firstPlan['new_plan_cost'] ?? 0),
                    'subtotal' => (float) ($firstPlan['subtotal'] ?? 0),
                    'gst_amount' => (float) ($firstPlan['gst_amount'] ?? 0),
                    'final_payable' => (float) ($firstPlan['final_payable'] ?? 0),
                    'remaining_days' => (int) ($firstPlan['remaining_days'] ?? 0),
                    'credit_licenses' => (int) ($firstPlan['credit_licenses'] ?? 0),
                    'current_licenses' => (int) ($firstPlan['current_licenses'] ?? $currentLicenses),
                    'total_licenses' => (int) ($firstPlan['total_licenses'] ?? $currentLicenses),
                ];
            }

            /*
        |--------------------------------------------------------------------------
        | Final response data
        |--------------------------------------------------------------------------
        */

            $responseData = [

                'request_id' =>
                $enquiryId,

                'action' =>
                'partial upgrade',

                'action_type' =>
                'partial upgrade',

                'upgrade_type' =>
                'partial',

                'is_partial_upgrade' =>
                true,

                /*
            | Provider
            */

                'provider_id' =>
                $providerId,

                'provider_name' =>
                $providerName,

                /*
            | Request handling
            */

                'requires_request' =>
                true,

                'change_via' =>
                'request',

                /*
            | Source
            */

                'order_id' =>
                (int) $sourceOrder->id,

                'parent_order_id' =>
                (int) $sourceOrder->id,

                'order_sub_id' =>
                $sourceItem
                    ? (int) $sourceItem->id
                    : null,

                /*
            | Plans
            */

                'current_plan_id' =>
                $currentPlanId,

                'selected_plan_id' =>
                $targetPlanId,

                'current_plan' =>
                $currentPlanData,

                'selected_plan' =>
                $targetPlanData,

                'requested_plan' =>
                $targetPlanData,

                'currentplandetails' =>
                $currentPlanData,

                'plans' =>
                $targetPlanData
                    ? [$targetPlanData]
                    : [],

                /*
            |--------------------------------------------------------------------------
            | LICENSE COUNTS
            |--------------------------------------------------------------------------
            */

                'old_total_licenses' =>
                $oldTotalLicenses,

                'new_total_licenses' =>
                $newTotalLicenses,

                'current_licenses' =>
                $currentLicenses,

                'total_licenses' =>
                $currentLicenses,

                'upgraded_licenses' =>
                $licenses,

                'remaining_licenses' =>
                $remainingLicenses,

                /*
            |--------------------------------------------------------------------------
            | PRORATION CALCULATION
            |--------------------------------------------------------------------------
            */

                'remaining_value' =>
                $cartPricing['remaining_value'] ?? 0,

                'remaining_credit' =>
                $cartPricing['remaining_credit'] ?? 0,

                'pro_rata_adjustment' =>
                $cartPricing['pro_rata_adjustment'] ?? 0,

                'applied_pro_rata' =>
                $cartPricing['applied_pro_rata'] ?? 0,

                'new_plan_cost' =>
                $cartPricing['new_plan_cost'] ?? 0,

                'subtotal' =>
                $cartPricing['subtotal'] ?? 0,

                'gst_amount' =>
                $cartPricing['gst_amount'] ?? 0,

                'final_payable' =>
                $cartPricing['final_payable'] ?? 0,

                'remaining_days' =>
                $cartPricing['remaining_days'] ?? 0,

                'credit_licenses' =>
                $cartPricing['credit_licenses'] ?? 0,

                /*
            | Cart
            */

                'main_cart_id' =>
                $mainCartId,

                'cart_created' =>
                true,

                'cart_data' => [

                    'main_cart_id' =>
                    $mainCartId,

                    'plans' =>
                    $plans,

                    'current_plan' =>
                    $currentPlanDetails,

                    'current_plan_id' =>
                    $currentPlanId,

                    'target_plan_id' =>
                    $targetPlanId,

                    /*
                | OLD
                */

                    'old_total_licenses' =>
                    $oldTotalLicenses,

                    /*
                | NEW
                */

                    'new_total_licenses' =>
                    $newTotalLicenses,

                    /*
                | TOTAL
                */

                    'current_licenses' =>
                    $currentLicenses,

                    'total_licenses' =>
                    $currentLicenses,

                    /*
                | SELECTED
                */

                    'upgraded_licenses' =>
                    $licenses,

                    /*
                | REMAINING
                */

                    'remaining_licenses' =>
                    $remainingLicenses,

                    'upgrade_type' =>
                    'partial',

                    'is_partial_upgrade' =>
                    true,

                    // <-- CRITICAL FIX: Add proration details to cart_data
                    'remaining_value' =>
                    $cartPricing['remaining_value'] ?? 0,

                    'pro_rata_adjustment' =>
                    $cartPricing['pro_rata_adjustment'] ?? 0,

                    'applied_pro_rata' =>
                    $cartPricing['applied_pro_rata'] ?? 0,

                    'remaining_days' =>
                    $cartPricing['remaining_days'] ?? 0,

                    'credit_licenses' =>
                    $cartPricing['credit_licenses'] ?? 0,

                    'final_payable' =>
                    $cartPricing['final_payable'] ?? 0,
                ],

                /*
            | API request information
            */

                'request_endpoint' =>
                '/api/partner/partial-upgrade-request',

                'request_message' =>
                'This '
                    . $providerName
                    . ' partial upgrade requires a request for approval.',

                // <-- CRITICAL FIX: Add remaining days and value for UI
                'remaining_days' =>
                $cartPricing['remaining_days'] ?? 0,

                'remaining_value' =>
                $cartPricing['remaining_value'] ?? 0,

                'pro_rata_adjustment' =>
                $cartPricing['pro_rata_adjustment'] ?? 0,
            ];

            /*
        |--------------------------------------------------------------------------
        | Final JSON
        |--------------------------------------------------------------------------
        */

            return response()->json([

                'success' =>
                true,

                'message' =>
                $providerName
                    . ' partial upgrade request has been submitted. '
                    . 'Cart has been created with the new plan.',

                'data' =>
                $responseData,

            ], 200);
        } catch (\Illuminate\Validation\ValidationException $e) {

            return response()->json([

                'success' =>
                false,

                'message' =>
                'Validation failed',

                'errors' =>
                $e->errors(),

            ], 422);
        } catch (\Throwable $e) {

            \Log::error(
                'partialUpgradeAddToCart error',
                [
                    'message' =>
                    $e->getMessage(),

                    'trace' =>
                    $e->getTraceAsString(),
                ]
            );

            return response()->json([

                'success' =>
                false,

                'message' =>
                'An error occurred while adding partial upgrade to cart.',

                'error' =>
                $e->getMessage(),

            ], 500);
        }
    }
    /**
     * Microsoft: extra seats on the current plan (not upgrade / partial).
     * Google / Tizzy: submit a license-add request instead of cart checkout.
     */
    public function licenseAddToCart(Request $request)
    {
        try {
            $this->normalizeUpgradeCartRequest($request);
            $this->sanitizeOrderIdInRequest($request);

            if (!$request->filled('licenses') && $request->filled('license_count')) {
                $request->merge(['licenses' => (int) $request->input('license_count')]);
            }

            $validated = $request->validate([
                'partner_id' => 'required|exists:pgsql_auth.partners,id',
                'plan_id' => 'nullable|integer|exists:pgsql_product.plans,id',
                'order_id' => 'nullable|integer|exists:pgsql_billing.orders,id',
                'order_sub_id' => 'nullable|integer',
                'order_item_id' => 'nullable|integer',
                'from_plan_id' => 'nullable|integer',
                'current_plan_id' => 'nullable|integer',
                'customer_id' => 'nullable|exists:pgsql_billing.customers,id',
                'company_name' => 'nullable|string',
                'licenses' => 'required|integer|min:1',
                'license_count' => 'nullable|integer|min:1',
                'main_cart_id' => 'nullable|integer',
                'cart_id' => 'nullable|integer',
            ]);

            $mainCartId = (int) ($validated['main_cart_id'] ?? $request->input('cart_id') ?? 0);
            $isApprovedRequest = false;
            if ($mainCartId > 0) {
                $isApprovedRequest = \App\Models\PurchaseRequest::where('cart_id', $mainCartId)
                    ->where('status', \App\Models\PurchaseRequest::STATUS_APPROVED)
                    ->exists();
            }

            $partnerId = (int) $validated['partner_id'];
            $customerId = !empty($validated['customer_id']) ? (int) $validated['customer_id'] : null;
            $extraLicenses = (int) ($validated['licenses'] ?? $validated['license_count'] ?? 0);
            [$orderSubIdHint, $fromPlanIdHint] = $this->resolveUpgradeSourceLineHints($request, $validated);

            $subscriptionOrderId = null;
            if ($customerId) {
                try {
                    $subscriptionOrderId = app(B2bSubscriptionUpgradeService::class)->resolveSubscriptionId(
                        $partnerId,
                        isset($validated['order_id']) && (int) $validated['order_id'] > 0 ? (int) $validated['order_id'] : null,
                        $customerId,
                        null,
                    );
                } catch (\Illuminate\Validation\ValidationException $e) {
                    return response()->json([
                        'success' => false,
                        'message' => collect($e->errors())->flatten()->first() ?: 'Subscription not found for customer.',
                        'errors' => $e->errors(),
                    ], 422);
                }
            }
            if (!$subscriptionOrderId && isset($validated['order_id']) && (int) $validated['order_id'] > 0) {
                $subscriptionOrderId = (int) $validated['order_id'];
            }
            if (!$subscriptionOrderId) {
                return response()->json([
                    'success' => false,
                    'message' => 'order_id or customer_id is required for license add.',
                ], 422);
            }

            [$sourceOrder, $sourceItem] = array_slice(
                $this->resolveUpgradeSourceSubscription(
                    $partnerId,
                    $customerId,
                    $subscriptionOrderId,
                    $orderSubIdHint > 0 ? $orderSubIdHint : null,
                    $fromPlanIdHint > 0 ? $fromPlanIdHint : null
                ),
                0,
                2
            );
            if (!$sourceOrder) {
                return response()->json([
                    'success' => false,
                    'message' => 'Active subscription not found for license add.',
                ], 404);
            }

            $currentPlanId = (int) ($sourceItem->plan_id ?? $sourceOrder->plan_id ?? 0);
            $requestedPlanId = (int) ($validated['plan_id'] ?? $currentPlanId);
            if ($requestedPlanId > 0 && $currentPlanId > 0 && $requestedPlanId !== $currentPlanId) {
                return response()->json([
                    'success' => false,
                    'message' => 'License add must stay on the current plan. Use upgrade or partial upgrade to move to a higher plan.',
                    'current_plan_id' => $currentPlanId,
                    'use_endpoint' => 'upgrade-add-to-cart',
                ], 422);
            }

            $plan = Plan::query()->find($currentPlanId > 0 ? $currentPlanId : $requestedPlanId);
            if (!$plan) {
                return response()->json([
                    'success' => false,
                    'message' => 'Plan not found',
                ], 404);
            }

            $providerId = (int) ($plan->provider_id ?? 0);
            $licenseTotals = $this->resolveUpgradeLicenseTotals($sourceOrder, $sourceItem);
            $oldTotalLicenses = (int) $licenseTotals['old_total_licenses'];
            $newTotalLicenses = (int) $licenseTotals['new_total_licenses'];
            $currentLicenses = max(1, (int) $licenseTotals['current_licenses']);
            $totalLicenses = $currentLicenses;

            // --- GET PROCESSING ORDERS FOR CREDIT CHECK (Provider Independent) ---
            $processingOrdersAmount = 0;
            $processingOrdersCount = 0;
            try {
                $processingOrders = Order::query()
                    ->where('partner_id', $partnerId)
                    ->where('order_type', 'b2b')
                    ->whereIn('status', ['processing', 'pending', 'waiting'])
                    ->get();

                $processingOrdersCount = $processingOrders->count();
                foreach ($processingOrders as $order) {
                    $amount = round((float) ($order->total_amount ?? $order->subtotal ?? 0), 2);
                    $processingOrdersAmount += $amount;
                }
            } catch (\Throwable $e) {
                Log::warning('Failed to fetch processing orders for credit check', [
                    'partner_id' => $partnerId,
                    'error' => $e->getMessage(),
                ]);
            }

            $partner = Partner::find($partnerId);
            $walletBalance = round(PartnerCreditService::remainingPurchaseAllowance((int) $partnerId), 2);
            $signRequired = strtolower(trim((string) ($partner->aadhaar_mandatory ?? 'no'))) === 'yes';

            // --- CREDIT CALCULATIONS ---
            $creditLimit = round((float) ($partner->credit_limit ?? 0), 2);
            $creditUsedTotal = round(PartnerCreditService::summarizeUsedCredit((int) $partnerId), 2);
            $remainingLimit = round(PartnerCreditService::remainingPurchaseAllowance((int) $partnerId), 2);
            $creditLimitReached = PartnerCreditService::isCreditLimitFullyUsed((int) $partnerId);

            // --- CREDIT LOCKED BY PROCESSING ORDERS (Provider Independent) ---
            $creditLockedByProcessing = false;
            $creditLockedMessage = null;
            $availableCreditForPurchase = $remainingLimit;

            if ($processingOrdersAmount > 0 && $processingOrdersAmount > $availableCreditForPurchase) {
                $creditLockedByProcessing = true;
                $creditLockedMessage = '₹' . number_format($processingOrdersAmount, 2) . ' worth of orders are in processing state. Available credit: ₹' . number_format($availableCreditForPurchase, 2);
            } elseif ($processingOrdersAmount > 0 && $availableCreditForPurchase <= 0) {
                $creditLockedByProcessing = true;
                $creditLockedMessage = 'Credit balance is fully utilized by ' . $processingOrdersCount . ' processing order(s).';
            } elseif ($processingOrdersAmount > 0 && $creditLimitReached) {
                $creditLockedByProcessing = true;
                $creditLockedMessage = 'Credit limit is fully used by ' . $processingOrdersCount . ' processing order(s).';
            } elseif ($processingOrdersAmount > 0 && $availableCreditForPurchase > 0 && $availableCreditForPurchase >= $processingOrdersAmount) {
                $creditLockedByProcessing = false;
                $creditLockedMessage = null;
            } else {
                $creditLockedByProcessing = false;
                $creditLockedMessage = null;
            }

            // --- CREATE CART AND CART ITEM FOR ALL PROVIDERS (Including Google/Tizzy) ---
            if (!$customerId) {
                $customerId = (int) ($sourceOrder->user_id ?? 0) ?: null;
            }
            $companyName = null;
            if ($customerId) {
                $companyName = Customer::query()
                    ->where('id', $customerId)
                    ->where('partner_id', $partnerId)
                    ->value('company_name');
            }

            $domainName = $this->subscriptionDomainNameForCart(null, (int) $sourceOrder->id);
            $cartService = app(PartnerCartService::class);
            $cart = null;

            if ($isApprovedRequest && $mainCartId > 0) {
                $cart = Cart::query()
                    ->with(['items.plan'])
                    ->where('id', $mainCartId)
                    ->where('partner_id', $partnerId)
                    ->first();
            }

            if (!$cart) {
                $cartService->deleteActiveCartsByType($partnerId, 'license_add');

                $cartQuery = Cart::query()
                    ->with(['items.plan'])
                    ->where('partner_id', $partnerId)
                    ->ofType('license_add')
                    ->active()
                    ->orderByDesc('id');
                if ($customerId) {
                    $cartQuery->where('customer_id', $customerId);
                }
                if (Schema::connection('pgsql_billing')->hasColumn('carts', 'order_id')) {
                    $cartQuery->where(function ($q) use ($sourceOrder) {
                        $q->where('order_id', (int) $sourceOrder->id)
                            ->orWhereNull('order_id')
                            ->orWhere('order_id', 0);
                    });
                }
                $cart = $cartQuery->first();
            }

            if ($cart) {
                $cart->provider_id = $plan->provider_id;
                if ($customerId) {
                    $cart->customer_id = $customerId;
                }
                if (!empty($domainName) && Schema::connection('pgsql_billing')->hasColumn('carts', 'domain_name')) {
                    $cart->domain_name = $domainName;
                }
                if (Schema::connection('pgsql_billing')->hasColumn('carts', 'order_id')) {
                    $cart->order_id = (int) $sourceOrder->id;
                }
                $cart->status = Cart::STATUS_ACTIVE;
                $cart->gst_percentage = (float) ($cart->gst_percentage ?? 18) ?: 18;
                $cart->save();

                $item = $cart->items->first();
                if ($item) {
                    $item->plan_id = $plan->id;
                    $item->licenses = $extraLicenses;
                    $item->unit_price = round((float) ($plan->price ?? $item->unit_price ?? 0), 2);
                    $item->grand_total = round(((float) $item->unit_price) * max(1, (int) $extraLicenses), 2);
                    $item->save();
                    $item->load(['cart', 'plan']);
                } else {
                    $item = $cartService->createUpgradeLine($cart, $plan, $customerId, $extraLicenses);
                    $item->load('cart');
                }
            } else {
                $cartPayload = [
                    'session_id'      => (string) Str::uuid(),
                    'partner_id'      => $partnerId,
                    'provider_id'     => $plan->provider_id,
                    'customer_id'     => $customerId,
                    'type'            => 'license_add',
                    'status'          => Cart::STATUS_ACTIVE,
                    'currency'        => 'INR',
                    'gst_percentage'  => 18,
                    'discount_amount' => 0,
                    'gst_amount'      => 0,
                    'grand_total'     => 0,
                ];
                if (!empty($domainName) && Schema::connection('pgsql_billing')->hasColumn('carts', 'domain_name')) {
                    $cartPayload['domain_name'] = $domainName;
                }
                if (Schema::connection('pgsql_billing')->hasColumn('carts', 'order_id')) {
                    $cartPayload['order_id'] = (int) $sourceOrder->id;
                }
                $cart = Cart::create($cartPayload);
                $item = $cartService->createUpgradeLine($cart, $plan, $customerId, $extraLicenses);
                $item->load('cart');
            }

            $request->attributes->set('_upgrade_mode', 'license_add');
            $newUnitPrice = round((float) ($plan->price ?? 0), 2);
            $calculation = $this->resolveLicenseAddProration(
                $sourceOrder,
                $sourceItem,
                $newUnitPrice,
                $extraLicenses,
                (float) ($cart->gst_percentage ?? 18),
                0.0
            );
            $cart->pro_rata_adjustment = 0;
            $cart->discount_amount = $calculation['coupon_discount'] ?? 0;
            $cart->gst_amount = $calculation['gst_amount'];
            $cart->grand_total = $calculation['final_payable'];
            if (Schema::connection('pgsql_billing')->hasColumn('carts', 'subtotal')) {
                $cart->subtotal = $calculation['new_plan_cost'];
            }
            $this->rememberUpgradeSourceLine($cart, $sourceItem);
            $cart->save();
            $item->licenses = $extraLicenses;
            $item->unit_price = $calculation['new_unit_price'];
            $item->grand_total = $calculation['new_plan_cost'] ?? $item->grand_total;
            $item->save();
            $cartService->assignCartTransferDomain($cart, (string) ($sourceOrder->transfer_domain ?? ''));
            $cart = $cart->refresh();

            if (!$isApprovedRequest) {
                $isApprovedRequest = \App\Models\PurchaseRequest::where('cart_id', (int) $cart->id)
                    ->where('status', \App\Models\PurchaseRequest::STATUS_APPROVED)
                    ->exists();
            }

            // --- GOOGLE/TIZZY PROVIDER - RETURN REQUEST RESPONSE WITH CART DATA ---
            if ($this->isRequestBasedChangeProvider($providerId) && !$isApprovedRequest) {
                $providerName = $providerId === 1 ? 'Tizzy' : 'Google';

                // --- CALCULATE ESTIMATED DATES FROM SOURCE ORDER ---
                $estimatedStartDate = null;
                $estimatedEndDate = null;
                $startDateFormatted = null;
                $endDateFormatted = null;
                $dateCalculationType = null;
                $dateCalculationNote = null;

                if ($sourceOrder) {
                    $sourceEndDate = $sourceOrder->subscription_end_date;
                    $sourceStartDate = $sourceOrder->subscription_start_date;

                    if ($providerId === 1) {
                        $dateCalculationType = 'Tizzy: 1 year minus 1 day';
                        if ($sourceEndDate) {
                            $estimatedStart = Carbon::parse($sourceEndDate)->addDay();
                            $estimatedEnd = $estimatedStart->copy()->addYear()->subDay();
                            $dateCalculationNote = 'Tizzy: Start = end date + 1 day, End = start + 1 year - 1 day.';
                        } elseif ($sourceStartDate) {
                            $estimatedStart = Carbon::parse($sourceStartDate);
                            $estimatedEnd = $estimatedStart->copy()->addYear()->subDay();
                            $dateCalculationNote = 'Tizzy: Using current start date as reference, End = start + 1 year - 1 day.';
                        } else {
                            $estimatedStart = Carbon::now();
                            $estimatedEnd = $estimatedStart->copy()->addYear()->subDay();
                            $dateCalculationNote = 'Tizzy: No dates available, using current date.';
                        }
                    } else {
                        $dateCalculationType = 'Google: Anniversary date';
                        if ($sourceStartDate) {
                            $estimatedStart = Carbon::parse($sourceStartDate);
                            $estimatedEnd = $estimatedStart->copy()->addYear();
                            $dateCalculationNote = 'Google: Subscription starts on anniversary date.';
                        } elseif ($sourceEndDate) {
                            $estimatedStart = Carbon::parse($sourceEndDate);
                            $estimatedEnd = $estimatedStart->copy()->addYear();
                            $dateCalculationNote = 'Google: Using current end date as reference.';
                        } else {
                            $estimatedStart = Carbon::now();
                            $estimatedEnd = $estimatedStart->copy()->addYear();
                            $dateCalculationNote = 'Google: No dates available, using current date.';
                        }
                    }

                    $estimatedStartDate = $estimatedStart->format('d-m-Y');
                    $estimatedEndDate = $estimatedEnd->format('d-m-Y');
                    $startDateFormatted = $estimatedStart->format('d-m-Y');
                    $endDateFormatted = $estimatedEnd->format('d-m-Y');
                }

                // Create enquiry for tracking
                $enquiryId = null;
                try {
                    $lines = [
                        $providerName . ' license add request',
                        'Order ID: ' . (int) ($sourceOrder->id ?? 0),
                        'Order Sub ID: ' . (int) ($sourceItem->id ?? 0),
                        'Current plan ID: ' . $currentPlanId,
                        'Requested plan ID: ' . $requestedPlanId,
                        'Current licenses: ' . $currentLicenses,
                        'Licenses to add: ' . $extraLicenses,
                        'Customer ID: ' . ($customerId ?? 0),
                        'Date calculation: ' . ($dateCalculationNote ?? 'N/A'),
                    ];
                    $enquiry = Enquiry::query()->create([
                        'partner_id' => $partnerId,
                        'message' => implode("\n", $lines),
                        'status' => 'new',
                    ]);
                    $enquiryId = (int) ($enquiry->id ?? 0);
                } catch (\Throwable $e) {
                    Log::warning('Failed to create enquiry for license add', [
                        'partner_id' => $partnerId,
                        'error' => $e->getMessage(),
                    ]);
                }

                $canPurchase = !$creditLimitReached;

                // Build plan array like CartDetails
                $planArray = [
                    'id' => $plan->id,
                    'sr_no' => $plan->sr_no,
                    'provider_id' => $plan->provider_id,
                    'category_id' => $plan->category_id,
                    'program_id' => $plan->program_id,
                    'variant_id' => $plan->variant_id,
                    'name' => $plan->name,
                    'title' => $plan->title,
                    'slug' => $plan->slug,
                    'storage' => $plan->storage,
                    'price' => $plan->price,
                    'actual_price' => $plan->actual_price,
                    'billing_cycle' => $plan->billing_cycle,
                    'customer_limit' => $plan->customer_limit,
                    'status' => $plan->status,
                    'features' => $plan->getFeaturesArrayAttribute(),
                    'plan_type' => $plan->plan_type,
                    'created_at' => $plan->created_at,
                    'updated_at' => $plan->updated_at,
                ];
                $subtotal = round((float) ($plan->price ?? 0) * $extraLicenses, 2);
                // Build cart item data with actual IDs
                $cartItemData = [
                    'item_id' => $item->id ?? null,
                    'cart_id' => $item->id ?? null,
                    'main_cart_id' => (int) $cart->id,
                    'partner_id' => $partnerId,
                    'customer_id' => $customerId,
                    'company_name' => $validated['company_name'] ?? $companyName,
                    'plan_id' => (int) $plan->id,
                    'plan_name' => $plan->name ?? '',
                    'plan' => $planArray,
                    'provider_id' => $plan->provider_id,
                    'licenses' => $extraLicenses,
                    'license_count' => $extraLicenses,
                    'added_licenses' => $extraLicenses,
                    'price_per_unit' => round((float) ($plan->price ?? 0), 2),
                    'unit_price' => round((float) ($plan->price ?? 0), 2),
                    'subtotal' => $subtotal,
                    'total_amount' => $cart->grand_total,
                    'discount' => 0,
                    'discount_amount' => 0,
                    'tax_percentage' => 18,
                    'tax_amount' => $cart->gst_amount,
                    'domain_name' => !empty($domainName) ? [$domainName] : [],
                    'transfer_domain' => 'no',
                    'status' => 'pending_approval',
                    'coupon_code' => '',
                    'coupon_discount_percent' => 0,
                    'cart_discount_amount' => 0,
                    'limited_offer' => 0,
                    'billing_cycle' => $plan->billing_cycle ?? 'yearly',
                    'billing_cycle_end_rule' => 'same_anniversary_date',
                    'customer_limit' => $plan->customer_limit,
                    'subscription_start_date' => $estimatedStartDate,
                    'subscription_end_date' => $estimatedEndDate,
                    'start_date' => $startDateFormatted,
                    'end_date' => $endDateFormatted,
                    'date_calculation_type' => $dateCalculationType,
                    'date_estimation_note' => $dateCalculationNote,
                    'dates_are_estimated' => true,
                    'created_at' => now()->format('d-m-Y'),
                    'updated_at' => now()->format('Y-m-d'),
                    'is_active' => true,
                    'requires_request' => false,
                    'change_via' => 'request',
                    'request_id' => $enquiryId,
                    'request_endpoint' => '/api/partner/license-add-request',
                    'request_message' => 'This ' . $providerName . ' license add requires a request for approval.',
                    'action_type' => 'license_add',
                    'provider_name' => $providerName,
                    'current_plan_id' => $currentPlanId,
                    'old_total_licenses' => $oldTotalLicenses,
                    'new_total_licenses' => $newTotalLicenses,
                    'current_licenses' => $currentLicenses,
                    'current_plan_licenses' => $currentLicenses,
                    'total_licenses' => $totalLicenses,
                    'added_licenses' => $extraLicenses,
                    'new_plan_cost' => round((float) ($plan->price ?? 0) * $extraLicenses, 2),
                    'final_payable' => 0,
                    'grand_total' => 0,
                    'gst_percentage' => 18,
                    'gst_amount' => $cart->gst_amount,
                    'taxable_amount' => 0,
                    'remaining_days' => 0,
                    'remaining_value' => 0,
                    'pro_rata_adjustment' => 0,
                    'applied_pro_rata' => 0,
                    'remaining_credit' => 0,
                    'wallet_credit' => 0,
                    'credit_licenses' => 0,
                    'daily_rate_per_license' => 0,
                    'sign_required' => $signRequired ? 'yes' : 'no',
                    'draft_cart' => false,
                    'aadhaar_pending' => false,
                    'draft_order' => null,
                    // --- CREDIT FIELDS (Google/Tizzy: credit_applicable = false) ---
                    'credit_limit' => $creditLimit,
                    'credit_used' => $creditUsedTotal,
                    'remaining_credit_limit' => $remainingLimit,
                    'credit_limit_reached' => $creditLimitReached,
                    'can_purchase' => $canPurchase,
                    'purchase_block_message' => $creditLockedByProcessing
                        ? $creditLockedMessage
                        : 'Request in processing/order status. Credit will be applied upon approval.',
                    'credit_applicable' => false,
                    'credit_zero_reason' => $creditLockedByProcessing
                        ? $creditLockedMessage
                        : 'Request in processing/order status. Credit will be applied upon approval.',
                    'is_credit_applicable' => false,
                    'credit_blocked' => true,
                    'credit_block_reason' => 'License add request is pending approval.',
                    'processing_orders_amount' => round($processingOrdersAmount, 2),
                    'processing_orders_count' => $processingOrdersCount,
                    'credit_locked_by_processing_orders' => $creditLockedByProcessing,
                    'credit_lock_message' => $creditLockedMessage,
                    'available_credit_for_purchase' => round($availableCreditForPurchase, 2),
                    'wallet_balance' => $walletBalance,
                    'available_balance' => $walletBalance,
            ];

            // Return response with cart data
            return response()->json([
                'success' => true,
                'message' => $providerName . ' license add request has been submitted. Cart has been created with the selected plan.',
                'data' => [$cartItemData],
                'main_cart_id' => (int) $cart->id,
                'cart_id' => $item->id ?? null,
                'domain_name' => !empty($domainName) ? [$domainName] : [],
                'wallet_balance' => $walletBalance,
                'sign_required' => $signRequired ? 'yes' : 'no',
                'license_count' => $extraLicenses,
                'credit_limit' => $creditLimit,
                'credit_used' => $creditUsedTotal,
                'remaining_credit_limit' => $remainingLimit,
                'credit_limit_reached' => $creditLimitReached,
                'can_purchase' => $canPurchase,
                'purchase_block_message' => $creditLockedByProcessing
                    ? $creditLockedMessage
                    : 'Request in processing/order status. Credit will be applied upon approval.',
                'draft_cart' => false,
                'draft_order' => null,
                'aadhaar_pending' => false,
                'order_id' => (int) $sourceOrder->id,
                'ordId' => (int) $sourceOrder->id,
                'old_total_licenses' => $oldTotalLicenses,
                'new_total_licenses' => $newTotalLicenses,
                'current_licenses' => $currentLicenses,
                'total_licenses' => $totalLicenses,
                'added_licenses' => $extraLicenses,
                'request_id' => $enquiryId,
                'provider_name' => $providerName,
                'credit_applicable' => false,
                'credit_zero_reason' => $creditLockedByProcessing
                    ? $creditLockedMessage
                    : 'Request in processing/order status. Credit will be applied upon approval.',
                'is_credit_applicable' => false,
                'credit_blocked' => true,
                'credit_block_reason' => 'License add request is pending approval.',
                'processing_orders_amount' => round($processingOrdersAmount, 2),
                'processing_orders_count' => $processingOrdersCount,
                'credit_locked_by_processing_orders' => $creditLockedByProcessing,
                'credit_lock_message' => $creditLockedMessage,
                'available_credit_for_purchase' => round($availableCreditForPurchase, 2),
            ]);
            }

            // --- MICROSOFT PROVIDER - CONTINUE WITH NORMAL RESPONSE ---
            $domainName = $this->applySubscriptionDomainToCart($cart, $sourceOrder, (int) $sourceOrder->id);

            // --- FOR MICROSOFT: 1 year minus 1 day ---
            $subscriptionDates = $this->formatUpgradeSubscriptionDates($sourceOrder, $sourceItem, $item);

            if (!empty($subscriptionDates['start'])) {
                $start = Carbon::parse($subscriptionDates['start']);
                $end = $start->copy()->addYear()->subDay();
                $subscriptionDates['end'] = $end->format('d-m-Y');
            }

            // --- CALCULATE CAN PURCHASE ---
            $payableAmount = round((float) ($cart->grand_total ?? 0), 2);

            $canPurchase = false;
            if (!$creditLimitReached) {
                if ($payableAmount <= 0.005) {
                    $canPurchase = true;
                } elseif ($payableAmount <= $availableCreditForPurchase) {
                    $canPurchase = true;
                } elseif ($creditLockedByProcessing && $payableAmount <= ($availableCreditForPurchase + $processingOrdersAmount)) {
                    $canPurchase = true;
                }
            }

            // --- BUILD PURCHASE BLOCK MESSAGE ---
            $purchaseBlockMessage = null;
            if ($creditLockedByProcessing) {
                $purchaseBlockMessage = 'Credit is locked because ₹' . number_format($processingOrdersAmount, 2) . ' worth of orders are in processing state. Available credit: ₹' . number_format($availableCreditForPurchase, 2);
            } elseif ($creditLimitReached) {
                $purchaseBlockMessage = 'Credit limit reached. You cannot buy additional items.';
            } elseif (!$canPurchase && $payableAmount > $availableCreditForPurchase) {
                $purchaseBlockMessage = 'Insufficient credit. Required: ₹' . number_format($payableAmount, 2) . ', Available: ₹' . number_format($availableCreditForPurchase, 2);
            } else {
                $purchaseBlockMessage = 'Sufficient credit allocation available to complete this purchase';
            }

            // Build plan array
            $planArray = [
                'id' => $plan->id,
                'sr_no' => $plan->sr_no,
                'provider_id' => $plan->provider_id,
                'category_id' => $plan->category_id,
                'program_id' => $plan->program_id,
                'variant_id' => $plan->variant_id,
                'name' => $plan->name,
                'title' => $plan->title,
                'slug' => $plan->slug,
                'storage' => $plan->storage,
                'price' => $plan->price,
                'actual_price' => $plan->actual_price,
                'billing_cycle' => $plan->billing_cycle,
                'customer_limit' => $plan->customer_limit,
                'status' => $plan->status,
                'features' => $plan->getFeaturesArrayAttribute(),
                'plan_type' => $plan->plan_type,
                'created_at' => $plan->created_at,
                'updated_at' => $plan->updated_at,
            ];

            // Build cart item data
            $cartItemData = [
                'item_id' => $item->id ?? null,
                'cart_id' => $item->id ?? null,
                'main_cart_id' => (int) $cart->id,
                'partner_id' => $partnerId,
                'customer_id' => $customerId,
                'company_name' => $companyName,
                'plan_id' => (int) $plan->id,
                'plan_name' => $plan->name ?? '',
                'plan' => $planArray,
                'provider_id' => $plan->provider_id,
                'licenses' => $extraLicenses,
                'license_count' => $extraLicenses,
                'added_licenses' => $extraLicenses,
                'price_per_unit' => round((float) ($calculation['new_unit_price'] ?? $item->unit_price ?? 0), 2),
                'unit_price' => round((float) ($calculation['new_unit_price'] ?? $item->unit_price ?? 0), 2),
                'subtotal' => round((float) ($calculation['new_plan_cost'] ?? 0), 2),
                'total_amount' => round((float) ($calculation['new_plan_cost'] ?? 0), 2),
                'discount' => 0,
                'discount_amount' => round((float) ($calculation['coupon_discount'] ?? 0), 2),
                'tax_percentage' => $cart->gst_percentage ?? 18,
                'tax_amount' => round((float) ($calculation['gst_amount'] ?? $cart->gst_amount ?? 0), 2),
                'domain_name' => !empty($domainName) ? [$domainName] : ($cart->domain_name ? [$cart->domain_name] : []),
                'transfer_domain' => $cart->transfer_domain ?? 'no',
                'status' => $cart->status ?? 'active',
                'coupon_code' => strtoupper($cart->coupen ?? ''),
                'coupon_discount_percent' => 0,
                'cart_discount_amount' => round((float) ($calculation['coupon_discount'] ?? 0), 2),
                'limited_offer' => 0,
                'billing_cycle' => $plan->billing_cycle ?? 'yearly',
                'billing_cycle_end_rule' => 'same_anniversary_date',
                'customer_limit' => $plan->customer_limit,
                'subscription_start_date' => $subscriptionDates['start'] ? date('d-m-Y', strtotime($subscriptionDates['start'])) : null,
                'subscription_end_date' => $subscriptionDates['end'] ? date('d-m-Y', strtotime($subscriptionDates['end'])) : null,
                'start_date' => $subscriptionDates['start'],
                'end_date' => $subscriptionDates['end'],
                'date_calculation_type' => 'Microsoft: 1 year minus 1 day',
                'dates_are_estimated' => false,
                'date_estimation_note' => null,
                'created_at' => $cart->created_at ? $cart->created_at->format('d-m-Y') : null,
                'updated_at' => $cart->updated_at ? $cart->updated_at->format('Y-m-d') : null,
                'is_active' => true,
                'type' => 'license_add',
                'upgrade_mode' => 'license_add',
                'remaining_value' => 0,
                'pro_rata_adjustment' => 0,
                'applied_pro_rata' => 0,
                'new_plan_cost' => round((float) ($calculation['new_plan_cost'] ?? 0), 2),
                'credit_licenses' => 0,
                'remaining_days' => (int) ($calculation['remaining_days'] ?? 0),
                'daily_rate_per_license' => round((float) ($calculation['daily_rate_per_license'] ?? 0), 2),
                'taxable_amount' => round((float) ($calculation['taxable_amount'] ?? 0), 2),
                'gst_percentage' => $cart->gst_percentage ?? 18,
                'gst_amount' => round((float) ($calculation['gst_amount'] ?? $cart->gst_amount ?? 0), 2),
                'grand_total' => round((float) ($calculation['final_payable'] ?? $cart->grand_total ?? 0), 2),
                'final_payable' => round((float) ($calculation['final_payable'] ?? $cart->grand_total ?? 0), 2),
                'coupon_discount_percent' => 0,
                'remaining_credit' => 0,
                'wallet_credit' => 0,
                'current_plan_id' => $currentPlanId,
                'old_total_licenses' => $oldTotalLicenses,
                'new_total_licenses' => $newTotalLicenses,
                'current_licenses' => $currentLicenses,
                'current_plan_licenses' => $currentLicenses,
                'total_licenses' => $totalLicenses,
                'added_licenses' => $extraLicenses,
                'credit_limit' => $creditLimit,
                'credit_used' => $creditUsedTotal,
                'remaining_credit_limit' => $remainingLimit,
                'credit_limit_reached' => $creditLimitReached,
                'can_purchase' => $canPurchase,
                'purchase_block_message' => $purchaseBlockMessage,
                'credit_applicable' => true,
                'credit_zero_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
                'is_credit_applicable' => true,
                'credit_blocked' => $creditLockedByProcessing,
                'credit_block_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
                'processing_orders_amount' => round($processingOrdersAmount, 2),
                'processing_orders_count' => $processingOrdersCount,
                'credit_locked_by_processing_orders' => $creditLockedByProcessing,
                'credit_lock_message' => $creditLockedMessage,
                'available_credit_for_purchase' => round($availableCreditForPurchase, 2),
                'wallet_balance' => $walletBalance,
                'available_balance' => $walletBalance,
                'requires_request' => false,
                'change_via' => 'cart',
            ];

            // Get draft flags
            $draftFlags = $this->syncedDraftFlags(
                $this->resolveDraftOrderForCart($partnerId, $cart),
                $signRequired,
                (int) $cart->id
            );
            $draftCart = (bool) $draftFlags['draft_cart'];
            $licenseCount = $this->resolveCartLicenseCount($cart);

            // Merge all data into cart item
            $cartItemData = array_merge($cartItemData, $draftFlags, [
                'sign_required' => $signRequired ? 'yes' : 'no',
                'license_count' => $licenseCount,
                'draft_cart' => $draftCart,
                'aadhaar_pending' => (bool) $draftFlags['aadhaar_pending'],
                'draft_order' => $draftFlags['draft_order'],
            ]);

            // Return response in exact CartDetails format
            return response()->json(array_merge([
                'success' => true,
                'message' => $draftCart
                    ? 'Licenses added. Draft order pending Aadhaar verification.'
                    : 'Licenses added to cart successfully.',
                'data' => [$cartItemData],
                'domain_name' => !empty($domainName) ? [$domainName] : ($cart->domain_name ? [$cart->domain_name] : []),
                'wallet_balance' => $walletBalance,
                'sign_required' => $signRequired ? 'yes' : 'no',
                'license_count' => $licenseCount,
                'old_total_licenses' => $oldTotalLicenses,
                'new_total_licenses' => $newTotalLicenses,
                'current_licenses' => $currentLicenses,
                'total_licenses' => $currentLicenses,
                'added_licenses' => $extraLicenses,
                'credit_limit' => $creditLimit,
                'credit_used' => $creditUsedTotal,
                'remaining_credit_limit' => $remainingLimit,
                'credit_limit_reached' => $creditLimitReached,
                'can_purchase' => $canPurchase,
                'purchase_block_message' => $purchaseBlockMessage,
                'credit_applicable' => true,
                'credit_zero_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
                'is_credit_applicable' => true,
                'credit_blocked' => $creditLockedByProcessing,
                'credit_block_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
                'processing_orders_amount' => round($processingOrdersAmount, 2),
                'processing_orders_count' => $processingOrdersCount,
                'credit_locked_by_processing_orders' => $creditLockedByProcessing,
                'credit_lock_message' => $creditLockedMessage,
                'available_credit_for_purchase' => round($availableCreditForPurchase, 2),
            ], $draftFlags));
        } catch (\Illuminate\Validation\ValidationException $e) {
            return response()->json([
                'success' => false,
                'message' => 'Validation failed',
                'errors' => $e->errors(),
            ], 422);
        } catch (\Throwable $e) {
            return response()->json([
                'success' => false,
                'message' => 'An error occurred while adding licenses to cart',
                'error' => $e->getMessage(),
            ], 500);
        }
    }

    public function upgradeAddToCart(Request $request)
    {
        try {
            // Log the incoming request
            Log::info('upgradeAddToCart called', $request->all());

            $this->normalizeUpgradeCartRequest($request);
            $this->sanitizeOrderIdInRequest($request);

            // --- FIX: Check if this is a partial upgrade ---
            $isPartialUpgrade = $request->attributes->get('_upgrade_mode') === 'partial';

            // --- CRITICAL: Get the licenses BEFORE any validation ---
            $originalLicenses = (int) $request->input('licenses', $request->input('license_count', 0));

            Log::info('upgradeAddToCart initial licenses', [
                'original_licenses' => $originalLicenses,
                'is_partial' => $isPartialUpgrade,
            ]);

            if (!$request->filled('plan_id')) {
                return response()->json([
                    'success' => false,
                    'message' => 'plan_id is required. Please select a plan to upgrade to.',
                    'data' => [
                        'hint' => 'Send the selected plan ID (the one you want to upgrade TO)',
                        'received' => $request->all()
                    ]
                ], 422);
            }

            // Frontend may send license_count instead of licenses.
            if (!$request->filled('licenses') && $request->filled('license_count')) {
                $request->merge(['licenses' => (int) $request->input('license_count')]);
            }

            $validated = $request->validate([
                'partner_id'   => 'required|exists:pgsql_auth.partners,id',
                'plan_id'      => 'required|exists:pgsql_product.plans,id',
                'order_id'     => 'nullable|integer|exists:pgsql_billing.orders,id',
                'order_sub_id' => 'nullable|integer',
                'order_item_id' => 'nullable|integer',
                'from_plan_id' => 'nullable|integer',
                'current_plan_id' => 'nullable|integer',
                'customer_id'  => 'nullable|exists:pgsql_billing.customers,id',
                'company_name' => 'nullable|string',
                'licenses'     => 'nullable|integer|min:1',
                'license_count' => 'nullable|integer|min:1',
            ]);

            $partnerId = (int)$validated['partner_id'];

            // --- CRITICAL: Preserve the licenses from the request ---
            $licensesFromRequest = !empty($validated['licenses'])
                ? (int) $validated['licenses']
                : (!empty($validated['license_count']) ? (int) $validated['license_count'] : null);

            if ($licensesFromRequest === null && $originalLicenses > 0) {
                $licensesFromRequest = $originalLicenses;
            }

            Log::info('upgradeAddToCart licenses from request', [
                'licenses_from_request' => $licensesFromRequest,
                'is_partial' => $isPartialUpgrade,
            ]);

            [$orderSubIdHint, $fromPlanIdHint] = $this->resolveUpgradeSourceLineHints($request, $validated);

            // --- CRITICAL: Get the target plan ---
            $targetPlan = Plan::find($validated['plan_id']);
            if (!$targetPlan) {
                return response()->json([
                    'success' => false,
                    'message' => 'Plan not found',
                ], 404);
            }

            Log::info('Target plan', [
                'target_plan_id' => $targetPlan->id,
                'target_plan_name' => $targetPlan->name,
                'provider_id' => $targetPlan->provider_id,
                'plan_id_from_request' => $validated['plan_id'],
            ]);

            $guardOrderId = isset($validated['order_id']) ? (int) $validated['order_id'] : 0;
            $guardCustomerId = !empty($validated['customer_id']) ? (int) $validated['customer_id'] : null;

            // --- Get source (current) subscription and validate ---
            $sourceOrder = null;
            $sourceItem = null;
            $sourcePlanId = 0;
            $currentLicenses = 1;
            $oldTotalLicenses = 0;
            $newTotalLicenses = 0;
            $providerId = (int) ($targetPlan->provider_id ?? 0);

            // --- FIX: For partial upgrades, use the from_plan_id from the request ---
            $sourcePlanIdFromRequest = (int) ($validated['from_plan_id'] ?? $request->input('from_plan_id', 0));

            if ($sourcePlanIdFromRequest > 0) {
                $sourcePlanId = $sourcePlanIdFromRequest;
                Log::info('Using from_plan_id from request', ['source_plan_id' => $sourcePlanId]);
            }

            // --- Resolve source subscription ---
            if ($guardOrderId > 0 || $guardCustomerId) {
                [$sourceOrder, $sourceItem, $resolvedOrderId] = $this->resolveUpgradeSourceSubscription(
                    $partnerId,
                    $guardCustomerId,
                    $guardOrderId > 0 ? $guardOrderId : null,
                    $orderSubIdHint > 0 ? $orderSubIdHint : null,
                    $fromPlanIdHint > 0 ? $fromPlanIdHint : null
                );

                if ($sourceOrder) {
                    // --- CRITICAL FIX: Get TOTAL licenses including activated license-add children ---
                    // This is the same logic used in orderIndex and subscriptionDetails
                    $licenseTotals = $this->resolveUpgradeLicenseTotals($sourceOrder, $sourceItem);
                    $oldTotalLicenses = (int) $licenseTotals['old_total_licenses'];
                    $newTotalLicenses = (int) $licenseTotals['new_total_licenses'];
                    $currentLicenses = (int) $licenseTotals['current_licenses']; // <-- This is the total including license-add

                    Log::info('License totals including license-add children', [
                        'old_total_licenses' => $oldTotalLicenses,
                        'new_total_licenses' => $newTotalLicenses,
                        'current_licenses' => $currentLicenses,
                        'source_order_id' => $sourceOrder->id,
                        'source_item_quantity' => $sourceItem->quantity ?? null,
                    ]);

                    if ($sourcePlanId <= 0) {
                        $sourcePlanId = (int) ($sourceItem->plan_id ?? $sourceOrder->plan_id ?? 0);
                    }
                }

                Log::info('Source plan from order', [
                    'source_plan_id' => $sourcePlanId,
                    'source_plan_name' => optional(Plan::find($sourcePlanId))->name,
                    'current_licenses' => $currentLicenses,
                    'source_item_quantity' => $sourceItem->quantity ?? null,
                    'source_order_quantity' => $sourceOrder->quantity ?? null,
                ]);
            }

            // --- Log the comparison ---
            Log::info('Plan comparison for upgrade', [
                'source_plan_id' => $sourcePlanId,
                'target_plan_id' => $targetPlan->id,
                'is_partial' => $isPartialUpgrade,
                'current_licenses' => $currentLicenses,
                'licenses_from_request' => $licensesFromRequest,
            ]);

            // --- VALIDATION 1: Cannot upgrade to the SAME plan ---
            if ($sourcePlanId > 0 && (int) $targetPlan->id === $sourcePlanId) {
                return response()->json([
                    'success' => false,
                    'message' => 'You cannot upgrade to the same plan. Please select a higher plan.',
                    'data' => [
                        'current_plan_id' => $sourcePlanId,
                        'selected_plan_id' => (int) $targetPlan->id,
                        'current_plan_name' => optional(Plan::find($sourcePlanId))->name,
                        'selected_plan_name' => $targetPlan->name,
                    ]
                ], 422);
            }

            // --- VALIDATION 2: Must upgrade to a HIGHER plan ---
            if ($sourcePlanId > 0) {
                $isHigher = $this->isHigherPlan($targetPlan, $sourcePlanId);

                $sourcePlanObj = Plan::find($sourcePlanId);
                Log::info('Plan comparison for upgrade', [
                    'source_plan_id' => $sourcePlanId,
                    'source_plan_name' => $sourcePlanObj->name ?? 'Unknown',
                    'source_sr_no' => $sourcePlanObj->sr_no ?? 'null',
                    'source_price' => $sourcePlanObj->price ?? 'null',
                    'target_plan_id' => $targetPlan->id,
                    'target_plan_name' => $targetPlan->name,
                    'target_sr_no' => $targetPlan->sr_no ?? 'null',
                    'target_price' => $targetPlan->price ?? 'null',
                    'is_higher' => $isHigher,
                ]);

                if (!$isHigher) {
                    return response()->json([
                        'success' => false,
                        'message' => 'Upgrade must move to a higher plan. Please select a plan with higher rank/price.',
                        'data' => [
                            'current_plan_id' => $sourcePlanId,
                            'current_plan_name' => $sourcePlanObj->name ?? 'Unknown',
                            'selected_plan_id' => (int) $targetPlan->id,
                            'selected_plan_name' => $targetPlan->name,
                            'current_plan_price' => (float) ($sourcePlanObj->price ?? 0),
                            'selected_plan_price' => (float) $targetPlan->price,
                            'current_plan_sr_no' => (int) ($sourcePlanObj->sr_no ?? 0),
                            'selected_plan_sr_no' => (int) $targetPlan->sr_no,
                            'is_higher_check' => $isHigher,
                        ]
                    ], 422);
                }
            }

            // --- CRITICAL FIX: Determine the licenses to use ---
            // For full upgrade, use TOTAL licenses (original + license-add)
            // For partial upgrade, use the requested subset
            $licenses = null;

            if ($isPartialUpgrade) {
                $licenses = $licensesFromRequest;

                Log::info('Partial upgrade using licenses from request', [
                    'licenses' => $licenses,
                    'current_licenses' => $currentLicenses,
                ]);

                if ($licenses === null || $licenses <= 0) {
                    return response()->json([
                        'success' => false,
                        'message' => 'Number of licenses to upgrade is required for partial upgrade.',
                        'current_licenses' => $currentLicenses,
                        'suggestion' => 'Select between 1 and ' . ($currentLicenses - 1) . ' licenses for partial upgrade.',
                    ], 422);
                }

                // Validate against TOTAL licenses (including license-add)
                if ($licenses >= $currentLicenses) {
                    return response()->json([
                        'success' => false,
                        'message' => 'Partial upgrade must select fewer than the current ' . $currentLicenses . ' licenses. Use full upgrade to move all seats.',
                        'use_endpoint' => 'upgrade-add-to-cart',
                        'current_licenses' => $currentLicenses,
                        'suggestion' => 'Select between 1 and ' . ($currentLicenses - 1) . ' licenses for partial upgrade.',
                    ], 422);
                }
            } else {
                // Full upgrade moves ALL licenses (original + license-add)
                $licenses = $currentLicenses;

                Log::info('Full upgrade using total licenses', [
                    'licenses' => $licenses,
                    'current_licenses' => $currentLicenses,
                    'old_total_licenses' => $oldTotalLicenses,
                    'new_total_licenses' => $newTotalLicenses,
                ]);
            }

            if ($licenses === null) {
                $licenses = 1;
            }

            $request->merge([
                'licenses' => $licenses,
                'license_count' => $licenses,
            ]);

            Log::info('upgradeAddToCart final licenses set', [
                'licenses' => $licenses,
                'is_partial' => $isPartialUpgrade,
                'current_licenses' => $currentLicenses,
            ]);

            // --- Get customer and company ---
            $customerId = !empty($validated['customer_id']) ? (int)$validated['customer_id'] : null;
            $companyName = null;
            if ($customerId) {
                $customer = Customer::where('id', $customerId)->where('partner_id', $partnerId)->first();
                if ($customer) {
                    $companyName = $customer->company_name;
                }
            } elseif (!empty($validated['company_name'])) {
                $customer = Customer::where('company_name', $validated['company_name'])
                    ->where('partner_id', $partnerId)
                    ->first();
                $companyName = $validated['company_name'];
                if ($customer) {
                    $customerId = $customer->id;
                    $companyName = $customer->company_name;
                }
            }

            // --- Resolve subscription order id ---
            $subscriptionOrderId = null;
            if ($customerId) {
                try {
                    $subscriptionOrderId = app(B2bSubscriptionUpgradeService::class)->resolveSubscriptionId(
                        $partnerId,
                        isset($validated['order_id']) && (int) $validated['order_id'] > 0 ? (int) $validated['order_id'] : null,
                        $customerId,
                        null,
                    );
                } catch (\Illuminate\Validation\ValidationException $e) {
                    return response()->json([
                        'success' => false,
                        'message' => collect($e->errors())->flatten()->first() ?: 'Subscription not found for customer.',
                        'errors' => $e->errors(),
                    ], 422);
                }
            }
            if (!$subscriptionOrderId && isset($validated['order_id']) && (int) $validated['order_id'] > 0) {
                $subscriptionOrderId = (int) $validated['order_id'];
            }

            if ($licenses === null) {
                $licenses = 1;
            }

            Log::info('upgradeAddToCart creating cart with licenses', [
                'licenses' => $licenses,
                'is_partial' => $isPartialUpgrade,
                'current_licenses' => $currentLicenses,
            ]);

            // --- Get domain from source subscription ---
            $domainName = $this->subscriptionDomainNameForCart(null, (int) $subscriptionOrderId);

            // --- Create or update upgrade cart ---
            $cartService = app(PartnerCartService::class);
            $cartService->deleteActiveCartsByType($partnerId, Cart::TYPE_UPGRADE);

            $cartQuery = Cart::query()
                ->with(['items.plan'])
                ->where('partner_id', $partnerId)
                ->ofType(Cart::TYPE_UPGRADE)
                ->active()
                ->orderByDesc('id');
            if ($customerId) {
                $cartQuery->where('customer_id', $customerId);
            }

            if ($subscriptionOrderId > 0 && Schema::connection('pgsql_billing')->hasColumn('carts', 'order_id')) {
                $cartQuery->where(function ($q) use ($subscriptionOrderId) {
                    $q->where('order_id', $subscriptionOrderId)
                        ->orWhereNull('order_id')
                        ->orWhere('order_id', 0);
                });
            }
            $cart = $cartQuery->first();

            if ($cart) {
                $cart->provider_id = $targetPlan->provider_id;
                if ($customerId) {
                    $cart->customer_id = $customerId;
                }
                if (!empty($domainName) && Schema::connection('pgsql_billing')->hasColumn('carts', 'domain_name')) {
                    $cart->domain_name = $domainName;
                }
                if ($subscriptionOrderId && Schema::connection('pgsql_billing')->hasColumn('carts', 'order_id')) {
                    $cart->order_id = $subscriptionOrderId;
                }
                $cart->status = Cart::STATUS_ACTIVE;
                $cart->gst_percentage = (float) ($cart->gst_percentage ?? 18) ?: 18;
                $cart->save();

                $item = $cart->items->first();
                if ($item) {
                    $item->plan_id = $targetPlan->id;
                    $item->licenses = $licenses;
                    $item->unit_price = round((float) ($targetPlan->price ?? $item->unit_price ?? 0), 2);
                    $item->grand_total = round(((float) $item->unit_price) * max(1, (int) $licenses), 2);
                    $item->save();
                    $item->load(['cart', 'plan']);
                } else {
                    $item = $cartService->createUpgradeLine($cart, $targetPlan, $customerId, $licenses);
                    $item->load('cart');
                }
            } else {
                $cartPayload = [
                    'session_id'      => (string) Str::uuid(),
                    'partner_id'      => $partnerId,
                    'provider_id'     => $targetPlan->provider_id,
                    'customer_id'     => $customerId,
                    'type'            => Cart::TYPE_UPGRADE,
                    'status'          => Cart::STATUS_ACTIVE,
                    'currency'        => 'INR',
                    'gst_percentage'  => 18,
                    'discount_amount' => 0,
                    'gst_amount'      => 0,
                    'grand_total'     => 0,
                ];
                if (!empty($domainName) && Schema::connection('pgsql_billing')->hasColumn('carts', 'domain_name')) {
                    $cartPayload['domain_name'] = $domainName;
                }
                if ($subscriptionOrderId && Schema::connection('pgsql_billing')->hasColumn('carts', 'order_id')) {
                    $cartPayload['order_id'] = $subscriptionOrderId;
                }

                $cart = Cart::create($cartPayload);
                $item = $cartService->createUpgradeLine($cart, $targetPlan, $customerId, $licenses);
                $item->load('cart');
            }

            // --- Calculate proration ---
            $calculation = [];
            $sourceOrder = null;
            $sourceItem = null;
            if ($subscriptionOrderId) {
                [$sourceOrder, $sourceItem] = array_slice(
                    $this->resolveUpgradeSourceSubscription(
                        $partnerId,
                        $customerId,
                        $subscriptionOrderId,
                        $orderSubIdHint > 0 ? $orderSubIdHint : null,
                        $fromPlanIdHint > 0 ? $fromPlanIdHint : null
                    ),
                    0,
                    2
                );

                $newUnitPrice = round((float) ($targetPlan->price ?? 0), 2);
                $calculation = $this->resolveUpgradeProration(
                    $sourceOrder,
                    $sourceItem,
                    $newUnitPrice,
                    $licenses,
                    (float) ($cart->gst_percentage ?? 18),
                    0.0,
                    (int) $targetPlan->id
                );
                $calculation['current_licenses'] = $currentLicenses;

                $cart->pro_rata_adjustment = $calculation['pro_rata_adjustment'];
                $cart->discount_amount = $calculation['coupon_discount'] ?? 0;
                $cart->gst_amount = $calculation['gst_amount'];
                $cart->grand_total = $calculation['final_payable'];
                if (Schema::connection('pgsql_billing')->hasColumn('carts', 'subtotal')) {
                    $cart->subtotal = $calculation['new_plan_cost'];
                }
                $this->rememberUpgradeSourceLine($cart, $sourceItem);
                $cart->save();
                $cartService->assignCartTransferDomain($cart, (string) ($sourceOrder->transfer_domain ?? ''));

                $item->licenses = $licenses;
                $item->unit_price = $calculation['new_unit_price'];
                $item->grand_total = $calculation['new_plan_cost'] ?? $item->grand_total;
                $item->save();
                $cart = $cart->refresh();
                $domainName = $this->applySubscriptionDomainToCart($cart, $sourceOrder, (int) $subscriptionOrderId);
            }

            $item->refresh();
            Log::info('upgradeAddToCart final cart item', [
                'cart_item_id' => $item->id,
                'plan_id' => $item->plan_id,
                'licenses' => $item->licenses,
                'unit_price' => $item->unit_price,
                'grand_total' => $item->grand_total,
                'is_partial' => $isPartialUpgrade,
                'cart_id' => $cart->id,
            ]);

            $subscriptionDates = $this->formatUpgradeSubscriptionDates($sourceOrder, $sourceItem, $item);
            $subscriptionStartDate = $subscriptionDates['start'];
            $subscriptionEndDate = $subscriptionDates['end'];

            // --- Get current plan details ---
            $currentPlan = null;
            if ($subscriptionOrderId) {
                $orderItemRow = $sourceItem;
                if (!$orderItemRow) {
                    $orderItemRow = $this->orderItem->newQuery()
                        ->where('order_id', $subscriptionOrderId)
                        ->when($orderSubIdHint > 0, fn($q) => $q->whereKey($orderSubIdHint))
                        ->when($orderSubIdHint <= 0 && $fromPlanIdHint > 0, fn($q) => $q->where('plan_id', $fromPlanIdHint))
                        ->where(function ($q) {
                            $q->whereNull('status')->orWhere('status', '!=', 'delete');
                        })
                        ->orderBy('id')
                        ->first();
                }
                $sourceOrder = $sourceOrder ?: $this->order->newQuery()
                    ->where('id', $subscriptionOrderId)
                    ->where('partner_id', $partnerId)
                    ->first();

                if ($orderItemRow && $sourceOrder) {
                    $sourcePlan = $this->plan->newQuery()->where('id', (int) $orderItemRow->plan_id)->first();
                    $currentPlan = (object) [
                        'id' => $orderItemRow->id,
                        'order_id' => $orderItemRow->order_id,
                        'plan_id' => $orderItemRow->plan_id,
                        'variant_id' => $orderItemRow->variant_id ?? null,
                        'plan_name' => $sourcePlan->name ?? '',
                        'provider_id' => $sourcePlan->provider_id ?? null,
                        'unit_price' => $orderItemRow->unit_price ?? 0,
                        'quantity' => $orderItemRow->quantity ?? 1,
                        'discount_amount' => $orderItemRow->discount_amount ?? '0.00',
                        'tax_amount' => $orderItemRow->tax_amount ?? '0.00',
                        'tax_rate' => $orderItemRow->tax_rate ?? '0.00',
                        'total_amount' => $orderItemRow->total_amount ?? '0.00',
                        'subscription_start_date' => $sourceOrder->subscription_start_date,
                        'subscription_end_date' => $sourceOrder->subscription_end_date,
                        'promo_code' => $sourceOrder->promo_code ?? null,
                        'created_at' => $orderItemRow->created_at,
                    ];
                } elseif ($sourceOrder) {
                    $sourcePlan = $this->plan->newQuery()->where('id', (int) $sourceOrder->plan_id)->first();
                    $currentPlan = (object) [
                        'order_id' => $sourceOrder->id,
                        'plan_id' => $sourceOrder->plan_id,
                        'subscription_start_date' => $sourceOrder->subscription_start_date,
                        'subscription_end_date' => $sourceOrder->subscription_end_date,
                        'promo_code' => $sourceOrder->promo_code ?? null,
                        'unit_price' => $sourceOrder->price ?? 0,
                        'quantity' => $sourceOrder->quantity ?? 1,
                        'plan_name' => $sourcePlan->name ?? '',
                        'provider_id' => $sourcePlan->provider_id ?? null,
                    ];
                }
            }

            $currentPlanDetailsArr = $currentPlan ? [
                'id'                       => $currentPlan->id ?? null,
                'order_id'                 => $currentPlan->order_id ?? null,
                'plan_id'                  => $currentPlan->plan_id ?? null,
                'variant_id'               => $currentPlan->variant_id ?? null,
                'plan_name'                => $currentPlan->plan_name ?? '',
                'provider_id'              => $currentPlan->provider_id ?? null,
                'unit_price'               => $currentPlan->unit_price ?? 0,
                'quantity'                 => $currentLicenses > 0 ? $currentLicenses : ($currentPlan->quantity ?? 1),
                'old_total_licenses'       => $oldTotalLicenses,
                'new_total_licenses'       => $newTotalLicenses,
                'current_licenses'         => $currentLicenses,
                'total_licenses'           => $currentLicenses,
                'discount_amount'          => $currentPlan->discount_amount ?? "0.00",
                'tax_amount'               => $currentPlan->tax_amount ?? "0.00",
                'tax_rate'                 => $currentPlan->tax_rate ?? "0.00",
                'total_amount'             => $currentPlan->total_amount ?? "0.00",
                'subscription_start_date'  => date('d-m-Y', strtotime($currentPlan->subscription_start_date)),
                'subscription_end_date'    => date('Y-m-d', strtotime($currentPlan->subscription_end_date)),
                'promo_code'               => $currentPlan->promo_code ?? null,
                'created_at'               => $currentPlan->created_at ?? null,
                'updated_at'               => $currentPlan->updated_at ?? null,
                'item_name'                => $currentPlan->item_name ?? '',
            ] : [];

            // --- Build plans array ---
            $plans = [];

            $targetProviderId = (int) ($targetPlan->provider_id ?? 0);
            $targetProviderName = 'Unknown';
            if ($targetProviderId > 0) {
                $targetProvider = Provider::query()->find($targetProviderId);
                if ($targetProvider) {
                    $targetProviderName = $targetProvider->name ?? 'Unknown';
                }
            }

            $requiresRequest = in_array($targetProviderId, [1, 3]);
            $changeVia = $requiresRequest ? 'request' : 'cart';
            $providerNameForDisplay = $targetProviderId === 1 ? 'Tizzy' : ($targetProviderId === 3 ? 'Google' : 'Microsoft');

            // Get current provider info
            $currentProviderId = $currentPlanDetailsArr['provider_id'] ?? null;
            $currentProviderName = $currentPlanDetailsArr['provider_name'] ?? 'Unknown';

            $itemArr = [
                'cart_id'                   => $item->id ?? null,
                'main_cart_id'              => (int)$cart->id,
                'provider_in_cart'          => $targetPlan->provider_id,
                'provider_id'               => $targetProviderId,
                'company_name'              => $companyName,
                'plan_name'                 => $targetPlan->name ?? '',
                'licenses'                  => $licenses,
                'current_plan_licenses'     => (int) ($calculation['current_licenses'] ?? $currentLicenses),
                'old_total_licenses'        => $oldTotalLicenses,
                'new_total_licenses'        => $newTotalLicenses,
                'total_licenses'            => $currentLicenses,
                'credit_licenses'           => (int) ($calculation['credit_licenses'] ?? 0),
                'current_unit_price'        => round((float) ($calculation['current_unit_price'] ?? 0), 2),
                'customer_id'               => $customerId,
                'type'                      => $cart->type ?? 'upgrade',
                'unit_price'                => round((float) ($calculation['new_unit_price'] ?? $item->unit_price ?? 0), 2),
                'subtotal'                  => round((float) ($calculation['new_plan_cost'] ?? 0), 2),
                'new_plan_cost'             => round((float) ($calculation['new_plan_cost'] ?? 0), 2),
                'remaining_credit'          => round((float) ($calculation['remaining_credit'] ?? 0), 2),
                'remaining_value'           => round((float) ($calculation['remaining_value'] ?? 0), 2),
                'pro_rata_adjustment'       => round((float) ($calculation['pro_rata_adjustment'] ?? 0), 2),
                'applied_pro_rata'          => round((float) ($calculation['applied_pro_rata'] ?? 0), 2),
                'wallet_credit'             => round((float) ($calculation['wallet_credit'] ?? 0), 2),
                'remaining_days'            => (int) ($calculation['remaining_days'] ?? 0),
                'daily_rate_per_license'    => round((float) ($calculation['daily_rate_per_license'] ?? 0), 2),
                'final_payable'             => round((float) ($calculation['final_payable'] ?? $cart->grand_total ?? 0), 2),
                'taxable_amount'            => round((float) ($calculation['taxable_amount'] ?? 0), 2),
                'price_after_discount'      => round((float) ($calculation['taxable_amount'] ?? 0), 2),
                'coupon_code'               => $cart->coupen ?? null,
                'coupon_discount_percent'   => 0,
                'gst_percentage'            => $cart->gst_percentage ?? 18,
                'gst_amount'                => round((float) ($calculation['gst_amount'] ?? $cart->gst_amount ?? 0), 2),
                'discount_amount'           => round((float) ($calculation['coupon_discount'] ?? $cart->discount_amount ?? 0), 2),
                'grand_total'               => round((float) ($calculation['final_payable'] ?? $cart->grand_total ?? 0), 2),
                'domain_name'               => !empty($domainName) ? $domainName : ($cart->domain_name ?? null),
                'subscription_start_date'   => $subscriptionStartDate,
                'subscription_end_date'     => $subscriptionEndDate,
                'upgrade_mode'              => $isPartialUpgrade ? 'partial' : 'full',
                'created_at'                => $item->created_at ?? null,
                'updated_at'                => $item->updated_at ?? null,
                // --- FLAGS ---
                'is_current_plan'           => false,
                'is_upgrading_to'           => true,
                'requires_request'          => $requiresRequest,
                'change_via'                => $changeVia,
                'provider_name'             => $providerNameForDisplay,
                // --- CURRENT PLAN INFO ---
                'current_plan_id'           => $sourcePlanId > 0 ? $sourcePlanId : null,
                'current_plan_name'         => $currentPlanDetailsArr['plan_name'] ?? null,
                'current_plan_provider_id'  => $currentProviderId,
                'current_plan_provider_name' => $currentProviderName,
                'current_licenses'          => $currentLicenses > 0 ? $currentLicenses : null,
                'old_total_licenses'        => $oldTotalLicenses,
                'new_total_licenses'        => $newTotalLicenses,
                'total_licenses'            => $currentLicenses,
            ];
            $plans[] = $itemArr;

            // --- Get wallet balance ---
            $partner = Partner::find($partnerId);
            $walletBalance = $partner
                ? (string) round(PartnerCreditService::remainingPurchaseAllowance((int) $partnerId), 2)
                : '0.00';

            // --- CRITICAL FIX: For Tizzy/Google, return the cart data with the request response ---
            if ($requiresRequest && !$request->attributes->get('_bypass_request_block')) {
                // Get the source plan details for the request response
                $sourcePlanObj = $sourcePlanId > 0 ? Plan::find($sourcePlanId) : null;

                $requestData = [
                    'request_id' => null,
                    'action' => $isPartialUpgrade ? 'partial upgrade' : 'upgrade',
                    'provider_id' => $targetProviderId,
                    'provider_name' => $providerNameForDisplay,
                    'requires_request' => true,
                    'change_via' => 'request',
                    'current_plan_id' => $sourcePlanId,
                    'selected_plan_id' => $targetPlan->id,
                    'old_total_licenses' => $oldTotalLicenses,
                    'new_total_licenses' => $newTotalLicenses,
                    'current_licenses' => $currentLicenses,
                    'total_licenses' => $currentLicenses,
                    'plans' => $plans,
                    'current_plan' => $sourcePlanObj ? [
                        'id' => $sourcePlanObj->id,
                        'plan_id' => $sourcePlanObj->id,
                        'name' => $sourcePlanObj->name ?? $sourcePlanObj->title ?? '',
                        'title' => $sourcePlanObj->title ?? $sourcePlanObj->name ?? '',
                        'price' => $sourcePlanObj->price ?? 0,
                        'licenses' => $currentLicenses,
                        'provider_id' => $sourcePlanObj->provider_id ?? null,
                    ] : null,
                    'selected_plan' => [
                        'id' => $targetPlan->id,
                        'plan_id' => $targetPlan->id,
                        'name' => $targetPlan->name ?? $targetPlan->title ?? '',
                        'title' => $targetPlan->title ?? $targetPlan->name ?? '',
                        'price' => $targetPlan->price ?? 0,
                        'licenses' => $licenses,
                        'provider_id' => $targetPlan->provider_id ?? null,
                    ],
                    'requested_plan' => [
                        'id' => $targetPlan->id,
                        'plan_id' => $targetPlan->id,
                        'name' => $targetPlan->name ?? $targetPlan->title ?? '',
                        'title' => $targetPlan->title ?? $targetPlan->name ?? '',
                        'price' => $targetPlan->price ?? 0,
                        'licenses' => $licenses,
                        'provider_id' => $targetPlan->provider_id ?? null,
                    ],
                    'action_type' => $isPartialUpgrade ? 'partial_upgrade' : 'upgrade',
                    'request_endpoint' => '/api/partner/upgrade-request',
                    'request_message' => 'This ' . $providerNameForDisplay . ' upgrade requires a request for approval.',
                    // --- Include cart data so the frontend can show the cart ---
                    'main_cart_id' => (int) $cart->id,
                    'cart_created' => true,
                ];

                return response()->json([
                    'success' => true,
                    'message' => 'Upgrade request submitted for approval. Cart has been created.',
                    'data' => $requestData,
                    'cart_data' => [
                        'main_cart_id' => (int) $cart->id,
                        'plans' => $plans,
                        'current_plan' => $currentPlanDetailsArr,
                        'target_plan' => [
                            'plan_id' => $targetPlan->id,
                            'plan_name' => $targetPlan->name ?? '',
                            'licenses' => $licenses,
                        ],
                    ],
                    'wallet_balance' => $walletBalance,
                ], 200);
            }

            // --- For Microsoft, return normal response ---
            Log::info('upgradeAddToCart success', [
                'main_cart_id' => (int) $cart->id,
                'target_plan_id' => $targetPlan->id,
                'licenses' => $licenses,
                'is_partial' => $isPartialUpgrade,
            ]);

            return response()->json([
                'success' => true,
                'wallet_balance' => $walletBalance,
                'main_cart_id' => (int) $cart->id,
                'data' => [
                    'main_cart_id' => (int) $cart->id,
                    'upgrade_mode' => $isPartialUpgrade ? 'partial' : 'full',
                    'currentplandetails' => $currentPlanDetailsArr,
                    'plans' => $plans,
                    'remaining_credit' => round((float) ($calculation['remaining_credit'] ?? 0), 2),
                    'remaining_value' => round((float) ($calculation['remaining_value'] ?? 0), 2),
                    'pro_rata_adjustment' => round((float) ($calculation['pro_rata_adjustment'] ?? 0), 2),
                    'applied_pro_rata' => round((float) ($calculation['applied_pro_rata'] ?? 0), 2),
                    'new_plan_cost' => round((float) ($calculation['new_plan_cost'] ?? 0), 2),
                    'subtotal' => round((float) ($calculation['new_plan_cost'] ?? 0), 2),
                    'credit_licenses' => (int) ($calculation['credit_licenses'] ?? 0),
                    'old_total_licenses' => $oldTotalLicenses,
                    'new_total_licenses' => $newTotalLicenses,
                    'current_licenses' => (int) ($calculation['current_licenses'] ?? $currentLicenses),
                    'total_licenses' => $currentLicenses,
                    'current_unit_price' => round((float) ($calculation['current_unit_price'] ?? 0), 2),
                    'daily_rate_per_license' => round((float) ($calculation['daily_rate_per_license'] ?? 0), 2),
                    'taxable_amount' => round((float) ($calculation['taxable_amount'] ?? 0), 2),
                    'gst_amount' => round((float) ($calculation['gst_amount'] ?? 0), 2),
                    'wallet_credit' => round((float) ($calculation['wallet_credit'] ?? 0), 2),
                    'final_payable' => round((float) ($calculation['final_payable'] ?? $cart->grand_total ?? 0), 2),
                    'remaining_days' => (int) ($calculation['remaining_days'] ?? 0),
                    'requires_request' => $requiresRequest,
                    'change_via' => $changeVia,
                    'provider_id' => $targetProviderId,
                    'provider_name' => $providerNameForDisplay,
                    'action_type' => 'upgrade',
                    'request_endpoint' => $requiresRequest ? '/api/partner/upgrade-request' : null,
                ],
            ]);
        } catch (\Illuminate\Validation\ValidationException $e) {
            return response()->json([
                'success' => false,
                'message' => 'Validation failed',
                'errors'  => $e->errors(),
            ], 422);
        } catch (\Throwable $e) {
            \Log::error('upgradeAddToCart error', [
                'message' => $e->getMessage(),
                'trace' => $e->getTraceAsString(),
            ]);
            return response()->json([
                'success' => false,
                'message' => 'An error occurred while adding upgrade to cart',
                'error'   => $e->getMessage(),
            ], 500);
        }
    }
    public function upgradeCartDetails(Request $request)
    {
        $this->normalizeUpgradeCartRequest($request);

        // Mobile may send cart_id instead of main_cart_id.
        if (!$request->filled('main_cart_id')) {
            foreach (['cart_id', 'mainCartId', 'cartId'] as $key) {
                $value = $request->input($key);
                if ($value !== null && $value !== '' && (int) $value > 0) {
                    $request->merge(['main_cart_id' => (int) $value]);
                    break;
                }
            }
        }

        // Temp pending cart edit flow may send cart_id in order_id.
        if (!$request->filled('main_cart_id')) {
            $rawOrderId = (int) ($request->input('order_id') ?? 0);
            if ($rawOrderId > 0 && !Order::query()->whereKey($rawOrderId)->exists()) {
                $tempCart = Cart::query()->whereKey($rawOrderId)->first();
                if ($tempCart) {
                    $request->merge(['main_cart_id' => $rawOrderId]);
                }
            }
        }

        $requestedMainCartId = (int) ($request->input('main_cart_id') ?? 0);
        if ($requestedMainCartId > 0) {
            $cartExists = Cart::query()->whereKey($requestedMainCartId)->exists();
            if (!$cartExists) {
                return response()->json([
                    'success' => false,
                    'message' => 'Cart not found for the given main_cart_id.',
                    'data' => [
                        'main_cart_id' => $requestedMainCartId,
                    ],
                ], 404);
            }
        }

        // Frontend may send license_count instead of licenses.
        if (!$request->filled('licenses') && $request->filled('license_count')) {
            $request->merge(['licenses' => (int) $request->input('license_count')]);
        }

        $partnerIdHint = (int) $request->input('partner_id', 0);
        $requestedMainCartId = (int) ($request->input('main_cart_id') ?? 0);
        if ($partnerIdHint > 0 && $requestedMainCartId > 0) {
            $requestedCart = Cart::query()
                ->whereKey($requestedMainCartId)
                ->where('partner_id', $partnerIdHint)
                ->first(['id', 'status', 'order_id']);
            if ($requestedCart && strtolower(trim((string) ($requestedCart->status ?? ''))) === Cart::STATUS_CONVERTED) {
                $convertedOrderId = (int) ($requestedCart->order_id ?? 0);

                return response()->json([
                    'success' => false,
                    'message' => 'This cart has already been converted to an order. Checkout is complete; use a new cart for another purchase.',
                    'data' => [
                        'main_cart_id' => (int) $requestedCart->id,
                        'order_id' => $convertedOrderId > 0 ? $convertedOrderId : null,
                        'status' => Cart::STATUS_CONVERTED,
                    ],
                ], 422);
            }
        }

        if ($partnerIdHint > 0) {
            $resolvedMainCartId = $this->resolveUpgradeMainCartId($request, $partnerIdHint);
            if ($resolvedMainCartId > 0) {
                $request->merge(['main_cart_id' => $resolvedMainCartId]);
            } elseif ($request->filled('main_cart_id')) {
                $request->request->remove('main_cart_id');
            }
        }

        $this->sanitizeOrderIdInRequest($request);

        $validated = $request->validate([
            'order_sub_id' => 'nullable',
            'partner_id' => 'required|exists:pgsql_auth.partners,id',
            'main_cart_id' => 'nullable|integer',
            'licenses' => 'nullable|integer|min:1',
            'license_count' => 'nullable|integer|min:1',
            'is_upgrade' => 'nullable|boolean',
            'plan_id' => 'nullable|exists:pgsql_product.plans,id',
            'order_id' => 'nullable|integer|exists:pgsql_billing.orders,id',
            'customer_id' => 'nullable|exists:pgsql_billing.customers,id',
            'upgrade_mode' => 'nullable|string|in:partial,full',
        ]);

        $partnerId = (int) $validated['partner_id'];
        $partner = Partner::find($partnerId);

        // --- GET PROCESSING ORDERS FOR CREDIT CHECK (Provider Independent) ---
        $processingOrdersAmount = 0;
        $processingOrdersCount = 0;
        try {
            $processingOrders = Order::query()
                ->where('partner_id', $partnerId)
                ->where('order_type', 'b2b')
                ->whereIn('status', ['processing', 'pending', 'waiting'])
                ->get();

            $processingOrdersCount = $processingOrders->count();
            foreach ($processingOrders as $order) {
                $amount = round((float) ($order->total_amount ?? $order->subtotal ?? 0), 2);
                $processingOrdersAmount += $amount;
            }
        } catch (\Throwable $e) {
            Log::warning('Failed to fetch processing orders for credit check', [
                'partner_id' => $partnerId,
                'error' => $e->getMessage(),
            ]);
        }

        // --- CREDIT CALCULATIONS ---
        $creditLimit = round((float) ($partner->credit_limit ?? 0), 2);
        $creditUsedTotal = round(PartnerCreditService::summarizeUsedCredit((int) $partnerId), 2);
        $remainingLimit = round(PartnerCreditService::remainingPurchaseAllowance((int) $partnerId), 2);
        $creditLimitReached = PartnerCreditService::isCreditLimitFullyUsed((int) $partnerId);

        // --- CREDIT LOCKED BY PROCESSING ORDERS (Provider Independent) ---
        $creditLockedByProcessing = false;
        $creditLockedMessage = null;
        $availableCreditForPurchase = $remainingLimit;

        if ($processingOrdersAmount > 0 && $processingOrdersAmount > $availableCreditForPurchase) {
            $creditLockedByProcessing = true;
            $creditLockedMessage = '₹' . number_format($processingOrdersAmount, 2) . ' worth of orders are in processing state. Available credit: ₹' . number_format($availableCreditForPurchase, 2);
        } elseif ($processingOrdersAmount > 0 && $availableCreditForPurchase <= 0) {
            $creditLockedByProcessing = true;
            $creditLockedMessage = 'Credit balance is fully utilized by ' . $processingOrdersCount . ' processing order(s).';
        } elseif ($processingOrdersAmount > 0 && $creditLimitReached) {
            $creditLockedByProcessing = true;
            $creditLockedMessage = 'Credit limit is fully used by ' . $processingOrdersCount . ' processing order(s).';
        } elseif ($processingOrdersAmount > 0 && $availableCreditForPurchase > 0 && $availableCreditForPurchase >= $processingOrdersAmount) {
            $creditLockedByProcessing = false;
            $creditLockedMessage = null;
        } else {
            $creditLockedByProcessing = false;
            $creditLockedMessage = null;
        }

        $walletBalance = round(PartnerCreditService::remainingPurchaseAllowance((int) $partnerId), 2);

        // --- Calculate Can Purchase based on final payable ---
        $payableAmount = 0;
        $canPurchase = false;
        $purchaseBlockMessage = null;

        $requestedUpgradeMode = strtolower(trim((string) (
            $request->attributes->get('_upgrade_mode')
            ?? $validated['upgrade_mode']
            ?? ''
        )));
        $forcePartialMode = $requestedUpgradeMode === 'partial';
        $isUpgrade = $forcePartialMode
            || !array_key_exists('is_upgrade', $validated)
            || filter_var($validated['is_upgrade'], FILTER_VALIDATE_BOOLEAN);

        $autoPlanId = $this->resolveUpgradePlanIdFromRequest($request);

        // Partial details: reuse active upgrade cart when only partner_id is sent after partial-upgrade-add-to-cart.
        if (empty($validated['main_cart_id'])) {
            $peekCartType = $isUpgrade ? Cart::TYPE_UPGRADE : Cart::TYPE_DOWNGRADE;
            $peekCustomerId = !empty($validated['customer_id']) ? (int) $validated['customer_id'] : 0;
            $peekOrderId = (int) ($validated['order_id'] ?? 0);
            $peekQuery = Cart::query()
                ->ofType($peekCartType)
                ->where('partner_id', $partnerId)
                ->active()
                ->orderByDesc('id');
            if ($peekCustomerId > 0) {
                $peekQuery->where('customer_id', $peekCustomerId);
            }
            if ($peekOrderId > 0 && Schema::connection('pgsql_billing')->hasColumn('carts', 'order_id')) {
                $peekQuery->where(function ($q) use ($peekOrderId) {
                    $q->where('order_id', $peekOrderId)
                        ->orWhereNull('order_id')
                        ->orWhere('order_id', 0);
                });
            }
            $peekCart = $peekQuery->first();
            if (!$peekCart) {
                $peekFallback = Cart::query()
                    ->ofType($peekCartType)
                    ->where('partner_id', $partnerId)
                    ->whereNotIn('status', [Cart::STATUS_CONVERTED, 'inactive'])
                    ->orderByDesc('id');
                if ($peekCustomerId > 0) {
                    $peekFallback->where('customer_id', $peekCustomerId);
                }
                if ($peekOrderId > 0 && Schema::connection('pgsql_billing')->hasColumn('carts', 'order_id')) {
                    $peekFallback->where(function ($q) use ($peekOrderId) {
                        $q->where('order_id', $peekOrderId)
                            ->orWhereNull('order_id')
                            ->orWhere('order_id', 0);
                    });
                }
                $peekCart = $peekFallback->first();
            }
            if ($peekCart) {
                $peekPlanId = (int) ($peekCart->items->first()->plan_id ?? 0);
                if ($autoPlanId <= 0 || $peekPlanId === $autoPlanId) {
                    $validated['main_cart_id'] = (int) $peekCart->id;
                    $request->merge(['main_cart_id' => (int) $peekCart->id]);
                }
            }
        }

        // --- Initialize license count variables ---
        $totalLicenses = 0;
        $remainingLicenses = 0;
        $upgradedLicenses = 0;
        $oldTotalLicenses = 0;
        $newTotalLicenses = 0;
        $sourcePlanId = 0;
        $sourceOrderId = 0;
        $sourceItemId = 0;
        $peekCart = null;

        // For partial upgrades, explicitly resolve the source (current) plan
        if ($forcePartialMode) {
            $partialOrderId = (int) ($validated['order_id'] ?? 0);
            $partialCustomerId = !empty($validated['customer_id']) ? (int) $validated['customer_id'] : null;
            $partialOrderSubId = (int) ($validated['order_sub_id'] ?? 0);

            // --- CRITICAL FIX: Get the licenses from the request and never let the
            // source total overwrite the selected upgrade quantity. ---
            $upgradedLicenses = $this->resolveSelectedPartialUpgradeLicenses(
                $request,
                null,
                0,
                1
            );

            // --- FIX: If licenses is not in request, try to get it from the cart item ---
            if ($upgradedLicenses <= 0 && $forcePartialMode && !empty($validated['main_cart_id'])) {
                $cartForLicenses = Cart::query()
                    ->with(['items'])
                    ->whereKey((int) $validated['main_cart_id'])
                    ->where('partner_id', $partnerId)
                    ->first();
                if ($cartForLicenses && $cartForLicenses->items->isNotEmpty()) {
                    $cartItem = $cartForLicenses->items->first();
                    $upgradedLicenses = (int) ($cartItem->licenses ?? 1);
                    $request->merge(['licenses' => $upgradedLicenses, 'license_count' => $upgradedLicenses]);
                    Log::info('upgradeCartDetails got licenses from cart item', [
                        'cart_id' => $validated['main_cart_id'],
                        'upgraded_licenses' => $upgradedLicenses,
                    ]);
                }
            }

            if (empty($partialOrderId) && !empty($validated['main_cart_id'])) {
                $peekCart = Cart::query()
                    ->whereKey((int) $validated['main_cart_id'])
                    ->where('partner_id', $partnerId)
                    ->first();
                if ($peekCart) {
                    $partialOrderId = (int) ($peekCart->order_id ?? 0);
                    if ($partialOrderSubId <= 0) {
                        $partialOrderSubId = $this->recallUpgradeSourceSubId($peekCart);
                    }
                    $fromPlanId = $this->recallUpgradeSourcePlanId($peekCart);
                    if ($fromPlanId > 0) {
                        $request->merge([
                            'from_plan_id' => $fromPlanId,
                            'current_plan_id' => $fromPlanId,
                        ]);
                    }
                }
            }

            if ($partialOrderId > 0 || $partialCustomerId || $partialOrderSubId > 0) {
                $sourcePlanId = 0;
                $sourceOrder = null;
                $sourceItem = null;

                if ($partialOrderSubId > 0) {
                    $sourceItem = OrderItem::query()
                        ->whereKey($partialOrderSubId)
                        ->where(function ($q) {
                            $q->whereNull('status')
                                ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted')");
                        })
                        ->first();
                    if ($sourceItem) {
                        $sourcePlanId = (int) ($sourceItem->plan_id ?? 0);
                        $sourceOrder = Order::query()
                            ->whereKey((int) $sourceItem->order_id)
                            ->where('partner_id', $partnerId)
                            ->first();
                    }
                }

                if ($sourcePlanId <= 0 && $partialOrderId > 0) {
                    $sourceOrder = Order::query()
                        ->whereKey($partialOrderId)
                        ->where('partner_id', $partnerId)
                        ->first();
                    if ($sourceOrder) {
                        $sourcePlanId = (int) ($sourceOrder->plan_id ?? 0);
                        if ($sourcePlanId <= 0) {
                            $item = OrderItem::query()
                                ->where('order_id', $partialOrderId)
                                ->where(function ($q) {
                                    $q->whereNull('status')
                                        ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted')");
                                })
                                ->orderBy('id')
                                ->first();
                            if ($item) {
                                $sourcePlanId = (int) ($item->plan_id ?? 0);
                                $sourceItem = $item;
                            }
                        }
                    }
                }

                if ($sourcePlanId <= 0 && $partialCustomerId > 0) {
                    try {
                        $subscriptionOrderId = app(B2bSubscriptionUpgradeService::class)->resolveSubscriptionId(
                            $partnerId,
                            $partialOrderId > 0 ? $partialOrderId : null,
                            $partialCustomerId,
                            null
                        );
                        if ($subscriptionOrderId > 0) {
                            $sourceOrder = Order::query()
                                ->whereKey($subscriptionOrderId)
                                ->where('partner_id', $partnerId)
                                ->first();
                            if ($sourceOrder) {
                                $sourcePlanId = (int) ($sourceOrder->plan_id ?? 0);
                                if ($sourcePlanId <= 0) {
                                    $item = OrderItem::query()
                                        ->where('order_id', $subscriptionOrderId)
                                        ->where(function ($q) {
                                            $q->whereNull('status')
                                                ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted')");
                                        })
                                        ->orderBy('id')
                                        ->first();
                                    if ($item) {
                                        $sourcePlanId = (int) ($item->plan_id ?? 0);
                                        $sourceItem = $item;
                                    }
                                }
                            }
                        }
                    } catch (\Throwable $e) {
                        // Silent fail
                    }
                }

                if ($sourcePlanId > 0 && $sourceOrder) {
                    // --- CRITICAL FIX: Get TOTAL licenses including activated license-add children ---
                    $licenseTotals = $this->resolveUpgradeLicenseTotals($sourceOrder, $sourceItem);
                    $totalLicenses = (int) $licenseTotals['current_licenses'];
                    $oldTotalLicenses = (int) $licenseTotals['old_total_licenses'];
                    $newTotalLicenses = (int) $licenseTotals['new_total_licenses'];
                    $upgradedLicenses = $this->resolveSelectedPartialUpgradeLicenses(
                        $request,
                        null,
                        $totalLicenses,
                        1
                    );

                    // --- CRITICAL FIX: Calculate remaining licenses ---
                    $remainingLicenses = max(0, $totalLicenses - $upgradedLicenses);

                    Log::info('upgradeCartDetails resolved source plan with license-add', [
                        'source_plan_id' => $sourcePlanId,
                        'source_plan_name' => optional(Plan::find($sourcePlanId))->name,
                        'source_order_id' => $sourceOrder->id,
                        'source_item_id' => $sourceItem->id ?? null,
                        'total_licenses' => $totalLicenses,
                        'upgrade_licenses' => $upgradedLicenses,
                        'remaining_licenses' => $remainingLicenses,
                        'old_total_licenses' => $oldTotalLicenses,
                        'new_total_licenses' => $newTotalLicenses,
                        'cart_id' => $peekCart->id ?? null,
                        'is_partial' => $forcePartialMode,
                    ]);

                    $sourcePlan = Plan::query()->find($sourcePlanId);

                    $currentplandetails = [
                        'id' => $sourceItem->id ?? null,
                        'order_id' => (int) $sourceOrder->id,
                        'plan_id' => $sourcePlanId,
                        'plan_name' => $sourcePlan->name ?? $sourcePlan->title ?? '',
                        'provider_id' => $sourcePlan->provider_id ?? null,
                        'provider_name' => optional(Provider::find($sourcePlan->provider_id))->name ?? 'Unknown',
                        'unit_price' => $sourceItem->unit_price ?? $sourcePlan->price ?? 0,
                        'quantity' => $totalLicenses,
                        'sr_no' => $sourcePlan->sr_no ?? 0,
                        'subscription_start_date' => $sourceOrder->subscription_start_date
                            ? date('d-m-Y', strtotime($sourceOrder->subscription_start_date))
                            : null,
                        'subscription_end_date' => $sourceOrder->subscription_end_date
                            ? date('d-m-Y', strtotime($sourceOrder->subscription_end_date))
                            : null,
                        'status' => $sourceOrder->status ?? 'active',
                        'old_total_licenses' => $oldTotalLicenses,
                        'new_total_licenses' => $newTotalLicenses,
                        'total_licenses' => $totalLicenses,
                        'remaining_licenses' => $remainingLicenses,
                        'upgraded_licenses' => $upgradedLicenses,
                    ];

                    $request->merge([
                        'from_plan_id' => $sourcePlanId,
                        'current_plan_id' => $sourcePlanId,
                        'order_id' => (int) $sourceOrder->id,
                    ]);
                    if ($sourceItem && (int) ($sourceItem->id ?? 0) > 0) {
                        $request->merge([
                            'order_sub_id' => (int) $sourceItem->id,
                            'order_item_id' => (int) $sourceItem->id,
                        ]);
                    }

                    $validated['from_plan_id'] = $sourcePlanId;
                    $validated['current_plan_id'] = $sourcePlanId;
                    $validated['order_id'] = (int) $sourceOrder->id;
                    $validated['total_licenses'] = $totalLicenses;
                    $validated['remaining_licenses'] = $remainingLicenses;
                    $validated['upgraded_licenses'] = $upgradedLicenses;
                    if ($sourceItem && (int) ($sourceItem->id ?? 0) > 0) {
                        $validated['order_sub_id'] = (int) $sourceItem->id;
                    }
                }
            }
        }

        // Partial details page: lock plan_id to current subscription line before any cart auto-create.
        if ($forcePartialMode) {
            $partialOrderId = (int) ($validated['order_id'] ?? 0);
            $partialCustomerId = !empty($validated['customer_id']) ? (int) $validated['customer_id'] : null;
            [$partialSubIdHint, $partialFromPlanHint] = $this->resolveUpgradeSourceLineHints($request, $validated);

            if ($partialOrderId <= 0 && !empty($validated['main_cart_id'])) {
                $peekCart = Cart::query()
                    ->whereKey((int) $validated['main_cart_id'])
                    ->where('partner_id', $partnerId)
                    ->first();
                if ($peekCart) {
                    $partialOrderId = (int) ($peekCart->order_id ?? 0);
                    if ($partialSubIdHint <= 0) {
                        $partialSubIdHint = $this->recallUpgradeSourceSubId($peekCart);
                    }
                    if ($partialFromPlanHint <= 0) {
                        $partialFromPlanHint = $this->recallUpgradeSourcePlanId($peekCart);
                    }
                }
            }

            if ($partialOrderId > 0 || $partialCustomerId || $partialSubIdHint > 0) {
                [$partialSourceOrder, $partialSourceItem] = array_slice(
                    $this->resolveUpgradeSourceSubscription(
                        $partnerId,
                        $partialCustomerId,
                        $partialOrderId > 0 ? $partialOrderId : null,
                        $partialSubIdHint > 0 ? $partialSubIdHint : null,
                        $partialFromPlanHint > 0 ? $partialFromPlanHint : null
                    ),
                    0,
                    2
                );
                $lockedPlanId = (int) ($partialSourceItem->plan_id ?? $partialSourceOrder->plan_id ?? 0);
                if ($lockedPlanId > 0) {
                    // --- CRITICAL FIX: Get TOTAL licenses including activated license-add children ---
                    if ($partialSourceOrder) {
                        $licenseTotals = $this->resolveUpgradeLicenseTotals($partialSourceOrder, $partialSourceItem);
                        $totalLicenses = (int) $licenseTotals['current_licenses'];
                        $validated['total_licenses'] = $totalLicenses;

                        // Use the selected partial-upgrade count, not the full current total.
                        $upgradedLicenses = $this->resolveSelectedPartialUpgradeLicenses(
                            $request,
                            $peekCart,
                            $totalLicenses,
                            1
                        );
                        $remainingLicenses = max(0, $totalLicenses - $upgradedLicenses);
                        $validated['remaining_licenses'] = $remainingLicenses;
                        $validated['upgraded_licenses'] = $upgradedLicenses;
                    }

                    $request->merge([
                        'plan_id' => $lockedPlanId,
                        'from_plan_id' => $lockedPlanId,
                        'current_plan_id' => $lockedPlanId,
                    ]);
                    if ($partialSourceOrder && (int) ($partialSourceOrder->id ?? 0) > 0) {
                        $request->merge(['order_id' => (int) $partialSourceOrder->id]);
                    }
                    if ($partialSourceItem && (int) ($partialSourceItem->id ?? 0) > 0) {
                        $request->merge([
                            'order_sub_id' => (int) $partialSourceItem->id,
                            'order_item_id' => (int) $partialSourceItem->id,
                        ]);
                    }
                    $validated['plan_id'] = $lockedPlanId;
                }
            }
        }

        if (empty($validated['main_cart_id'])) {
            $existingCartType = $isUpgrade ? Cart::TYPE_UPGRADE : Cart::TYPE_DOWNGRADE;
            $existingCart = Cart::query()
                ->with(['items'])
                ->ofType($existingCartType)
                ->where('partner_id', $partnerId)
                ->active()
                ->orderByDesc('id')
                ->first();

            if (!$existingCart) {
                $existingCart = Cart::query()
                    ->with(['items'])
                    ->ofType($existingCartType)
                    ->where('partner_id', $partnerId)
                    ->whereNotIn('status', [Cart::STATUS_CONVERTED, 'inactive'])
                    ->orderByDesc('id')
                    ->first();
            }

            $autoPlanId = $this->resolveUpgradePlanIdFromRequest($request);
            $currentLockedPlanId = (int) ($request->input('from_plan_id') ?? $request->input('current_plan_id') ?? 0);
            $existingCartPlanId = $existingCart ? (int) ($existingCart->items->first()->plan_id ?? 0) : 0;
            $needsCart = $autoPlanId > 0
                && (
                    !$existingCart
                    || $existingCart->items->isEmpty()
                    || ($autoPlanId !== $currentLockedPlanId && $existingCartPlanId !== $autoPlanId)
                );
            if ($needsCart) {
                if ($isUpgrade) {
                    $createError = $this->ensureUpgradeCartFromRequest($request);
                } else {
                    $createError = $this->ensureDowngradeCartFromRequest($request);
                }
                if ($createError !== null) {
                    return $createError;
                }
                // Pick up main_cart_id merged by ensure* helpers.
                if ($request->filled('main_cart_id')) {
                    $validated['main_cart_id'] = (int) $request->input('main_cart_id');
                }
            }
        }

        $walletBalance = round(PartnerCreditService::remainingPurchaseAllowance((int) $partnerId), 2);
        $cartType = $isUpgrade ? Cart::TYPE_UPGRADE : Cart::TYPE_DOWNGRADE;
        $mainCartId = (int) ($validated['main_cart_id'] ?? 0);

        if ($mainCartId > 0) {
            $cart = Cart::query()
                ->with(['items.plan', 'customer'])
                ->where('partner_id', $partnerId)
                ->whereKey($mainCartId)
                ->first();

            if (
                $cart
                && $cart->status === 'pending_approval'
                && PurchaseRequest::query()
                    ->where('cart_id', $cart->id)
                    ->where('partner_id', $partnerId)
                    ->where('status', PurchaseRequest::STATUS_APPROVED)
                    ->exists()
            ) {
                $cart->status = Cart::STATUS_ACTIVE;
                $cart->save();
            }

            if ($cart && strtolower(trim((string) ($cart->status ?? ''))) === Cart::STATUS_CONVERTED) {
                $convertedOrderId = (int) ($cart->order_id ?? 0);

                return response()->json([
                    'success' => false,
                    'message' => 'This cart has already been converted to an order. Checkout is complete; use a new cart for another purchase.',
                    'data' => [
                        'main_cart_id' => (int) $cart->id,
                        'order_id' => $convertedOrderId > 0 ? $convertedOrderId : null,
                        'status' => Cart::STATUS_CONVERTED,
                    ],
                ], 422);
            }

            if (!$cart || in_array((string) ($cart->status ?? ''), ['inactive'], true)) {
                $cart = null;
                $validated['main_cart_id'] = null;
                $mainCartId = 0;
            }
        } else {
            $cart = null;
        }

        if ($mainCartId <= 0 || !$cart) {
            $cart = Cart::query()
                ->with(['items.plan', 'customer'])
                ->ofType($cartType)
                ->where('partner_id', $partnerId)
                ->active()
                ->orderByDesc('id')
                ->first();

            if (!$cart) {
                $cart = Cart::query()
                    ->with(['items.plan', 'customer'])
                    ->ofType($cartType)
                    ->where('partner_id', $partnerId)
                    ->whereNotIn('status', [Cart::STATUS_CONVERTED, 'inactive'])
                    ->orderByDesc('id')
                    ->first();
            }
        }

        if ($cart && $cart->items->isEmpty()) {
            $cart->setRelation(
                'items',
                CartItem::query()->with('plan')->where('cart_id', (int) $cart->id)->get()
            );
        }
        $cartStatus = $cart ? (string) ($cart->status ?? Cart::STATUS_ACTIVE) : null;
        $peekCart = $cart;

        if ($cart) {
            if (empty($validated['order_sub_id'])) {
                $rememberedSubId = $this->recallUpgradeSourceSubId($cart);
                if ($rememberedSubId > 0) {
                    $validated['order_sub_id'] = $rememberedSubId;
                    $request->merge([
                        'order_sub_id' => $rememberedSubId,
                        'order_item_id' => $rememberedSubId,
                    ]);
                }
            }
            if (empty($validated['order_id']) && (int) ($cart->order_id ?? 0) > 0) {
                $validated['order_id'] = (int) $cart->order_id;
                $request->merge(['order_id' => (int) $cart->order_id]);
            }
            if ($forcePartialMode && (int) ($validated['plan_id'] ?? 0) <= 0) {
                $cartPlanId = (int) ($cart->items->first()->plan_id ?? 0);
                if ($cartPlanId > 0) {
                    $validated['plan_id'] = $cartPlanId;
                    $request->merge([
                        'plan_id' => $cartPlanId,
                        'from_plan_id' => $cartPlanId,
                        'current_plan_id' => $cartPlanId,
                    ]);
                }
            }
        }

        $coupon_code = null;
        $cartCoupen = null;
        if ($cart) {
            $cartCoupen = trim((string) ($cart->coupen ?? $cart->coupon ?? ''));
            if ($cartCoupen !== '') {
                $coupon_code = strtoupper($cartCoupen);
            }
        }
        $promoDiscountPercent = 0;

        if ($cartCoupen !== null && $cartCoupen !== '') {
            $promocode = Promocode::query()
                ->whereRaw('UPPER(code) = ?', [strtoupper($cartCoupen)])
                ->where('status', 1)
                ->first();
            if ($promocode && isset($promocode->discount_percent)) {
                $promoDiscountPercent = (float) $promocode->discount_percent;
            }
        }

        // --- CRITICAL FIX: Get the source plan from the cart ---
        $sourcePlanId = 0;
        $sourceOrderId = 0;
        $sourceItemId = 0;
        $totalLicenses = 0;
        $remainingLicenses = 0;
        $upgradedLicenses = 0;
        $oldTotalLicenses = 0;
        $newTotalLicenses = 0;
        $currentPlanDetails = [];
        $currentplandetails = [];

        if ($cart) {
            // Try to get source plan from cart's order_sub_id
            if (Schema::connection('pgsql_billing')->hasColumn('carts', 'order_sub_id') && (int) ($cart->order_sub_id ?? 0) > 0) {
                $sourceItemId = (int) $cart->order_sub_id;
            }

            // Try to get source plan from cart's item_type
            if ($sourceItemId <= 0) {
                $itemType = trim((string) ($cart->item_type ?? ''));
                if (preg_match('/order_sub:(\d+)/', $itemType, $m)) {
                    $sourceItemId = (int) $m[1];
                }
                if (preg_match('/:plan:(\d+)/', $itemType, $m)) {
                    $sourcePlanId = (int) $m[1];
                }
            }

            // Try to get from cache
            if ($sourceItemId <= 0) {
                $sourceItemId = $this->recallUpgradeSourceSubId($cart);
            }
            if ($sourcePlanId <= 0) {
                $sourcePlanId = $this->recallUpgradeSourcePlanId($cart);
            }

            // Get source order ID from cart
            $sourceOrderId = (int) ($cart->order_id ?? 0);

            // If we have a source item ID, get the plan details
            if ($sourceItemId > 0) {
                $sourceItem = OrderItem::query()
                    ->whereKey($sourceItemId)
                    ->first();
                if ($sourceItem) {
                    $sourcePlanId = (int) ($sourceItem->plan_id ?? $sourcePlanId);
                    $sourceOrderId = (int) ($sourceItem->order_id ?? $sourceOrderId);
                    $totalLicenses = (int) ($sourceItem->quantity ?? 1);
                    $currentPlanDetails = $sourceItem->toArray();
                }
            }

            // If we still don't have a source plan, try to get it from the order
            if ($sourcePlanId <= 0 && $sourceOrderId > 0) {
                $sourceOrder = Order::query()
                    ->whereKey($sourceOrderId)
                    ->where('partner_id', $partnerId)
                    ->first();
                if ($sourceOrder) {
                    $sourcePlanId = (int) ($sourceOrder->plan_id ?? 0);
                    if ($sourcePlanId <= 0) {
                        $item = OrderItem::query()
                            ->where('order_id', $sourceOrderId)
                            ->where(function ($q) {
                                $q->whereNull('status')
                                    ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted')");
                            })
                            ->orderBy('id')
                            ->first();
                        if ($item) {
                            $sourcePlanId = (int) $item->plan_id;
                            $sourceItemId = (int) $item->id;
                            $totalLicenses = (int) ($item->quantity ?? 1);
                            $currentPlanDetails = $item->toArray();
                        }
                    }
                    $totalLicenses = (int) ($sourceOrder->quantity ?? $totalLicenses);
                }
            }

            // --- CRITICAL FIX: Get TOTAL licenses including activated license-add children ---
            if ($sourceOrderId > 0) {
                $sourceOrder = Order::query()->whereKey($sourceOrderId)->first();
                if ($sourceOrder) {
                    $sourceItem = null;
                    if ($sourceItemId > 0) {
                        $sourceItem = OrderItem::query()->whereKey($sourceItemId)->first();
                    }

                    // Use resolveUpgradeLicenseTotals to get total including license-add
                    $licenseTotals = $this->resolveUpgradeLicenseTotals($sourceOrder, $sourceItem);
                    $oldTotalLicenses = (int) $licenseTotals['old_total_licenses'];
                    $newTotalLicenses = (int) $licenseTotals['new_total_licenses'];
                    $totalLicenses = (int) $licenseTotals['current_licenses'];

                    $upgradedLicenses = $this->resolveSelectedPartialUpgradeLicenses(
                        $request,
                        $cart,
                        $totalLicenses,
                        1
                    );
                    $remainingLicenses = max(0, $totalLicenses - $upgradedLicenses);

                    Log::info('upgradeCartDetails license totals', [
                        'source_order_id' => $sourceOrderId,
                        'old_total_licenses' => $oldTotalLicenses,
                        'new_total_licenses' => $newTotalLicenses,
                        'total_licenses' => $totalLicenses,
                        'upgraded_licenses' => $upgradedLicenses,
                        'remaining_licenses' => $remainingLicenses,
                        'source_item_id' => $sourceItemId,
                        'is_partial' => $forcePartialMode,
                    ]);
                }
            }

            // --- Build current plan details from source plan ---
            if ($sourcePlanId > 0) {
                $sourcePlan = Plan::query()->find($sourcePlanId);
                $sourceOrder = $sourceOrderId > 0 ? Order::query()->find($sourceOrderId) : null;

                if ($sourcePlan) {
                    $currentplandetails = [
                        'id' => $sourceItemId > 0 ? $sourceItemId : null,
                        'order_id' => $sourceOrderId > 0 ? $sourceOrderId : null,
                        'plan_id' => $sourcePlan->id,
                        'plan_name' => $sourcePlan->name ?? $sourcePlan->title ?? '',
                        'provider_id' => $sourcePlan->provider_id ?? null,
                        'provider_name' => optional(Provider::find($sourcePlan->provider_id))->name ?? 'Unknown',
                        'unit_price' => $sourcePlan->price ?? 0,
                        'quantity' => $totalLicenses > 0 ? $totalLicenses : 1,
                        'sr_no' => $sourcePlan->sr_no ?? 0,
                        'customer_limit' => $sourcePlan->customer_limit ?? null,
                        'subscription_start_date' => $sourceOrder && $sourceOrder->subscription_start_date
                            ? date('d-m-Y', strtotime($sourceOrder->subscription_start_date))
                            : null,
                        'subscription_end_date' => $sourceOrder && $sourceOrder->subscription_end_date
                            ? date('d-m-Y', strtotime($sourceOrder->subscription_end_date))
                            : null,
                        'status' => $sourceOrder->status ?? 'active',
                        'old_total_licenses' => $oldTotalLicenses,
                        'new_total_licenses' => $newTotalLicenses,
                        'total_licenses' => $totalLicenses,
                        'remaining_licenses' => $remainingLicenses,
                        'upgraded_licenses' => $upgradedLicenses,
                    ];

                    $request->merge([
                        'from_plan_id' => $sourcePlanId,
                        'current_plan_id' => $sourcePlanId,
                        'order_id' => $sourceOrderId,
                        'order_sub_id' => $sourceItemId,
                    ]);

                    Log::info('upgradeCartDetails resolved source plan', [
                        'source_plan_id' => $sourcePlanId,
                        'source_plan_name' => $sourcePlan->name,
                        'source_order_id' => $sourceOrderId,
                        'source_item_id' => $sourceItemId,
                        'total_licenses' => $totalLicenses,
                        'remaining_licenses' => $remainingLicenses,
                        'upgraded_licenses' => $upgradedLicenses,
                        'cart_id' => $cart->id,
                        'cart_type' => $cart->type,
                    ]);
                }
            }
        }

        // If we don't have current plan details, try to get from order_sub_id
        if (empty($currentplandetails) && !empty($validated['order_sub_id'])) {
            $detailItem = $this->orderItem->newQuery()
                ->where('id', (int) $validated['order_sub_id'])
                ->first();
            $detailOrder = $detailItem
                ? $this->order->newQuery()->where('id', (int) $detailItem->order_id)->first()
                : null;
            $detailPlan = ($detailItem && $detailItem->plan_id)
                ? $this->plan->newQuery()->where('id', (int) $detailItem->plan_id)->first()
                : null;
            if ($detailItem && $detailOrder) {
                // --- CRITICAL FIX: Get total licenses including license-add ---
                $licenseTotals = $this->resolveUpgradeLicenseTotals($detailOrder, $detailItem);
                $totalLicenses = (int) $licenseTotals['current_licenses'];

                $upgradedLicenses = $this->resolveSelectedPartialUpgradeLicenses(
                    $request,
                    $cart,
                    $totalLicenses,
                    1
                );
                $remainingLicenses = max(0, $totalLicenses - $upgradedLicenses);

                $detailObj = (object) array_merge($detailItem->toArray(), [
                    'subscription_start_date' => $detailOrder->subscription_start_date
                        ? date('d-m-Y', strtotime($detailOrder->subscription_start_date))
                        : null,
                    'subscription_end_date' => $detailOrder->subscription_end_date
                        ? date('d-m-Y', strtotime($detailOrder->subscription_end_date))
                        : null,
                    'promo_code' => $detailOrder->promo_code,
                    'plan_name' => $detailPlan->name ?? '',
                    'provider_id' => $detailPlan->provider_id ?? null,
                    'provider_name' => optional(Provider::find($detailPlan->provider_id))->name ?? 'Unknown',
                    'quantity' => $totalLicenses,
                    'old_total_licenses' => $licenseTotals['old_total_licenses'],
                    'new_total_licenses' => $licenseTotals['new_total_licenses'],
                    'total_licenses' => $totalLicenses,
                    'remaining_licenses' => $remainingLicenses,
                    'upgraded_licenses' => $upgradedLicenses,
                    'customer_limit' => $detailPlan->customer_limit ?? null,
                ]);
                $currentplandetails = (array) $detailObj;
            }
        }

        $subscriptionStartDate = $currentplandetails['subscription_start_date'] ?? '-';
        $subscriptionEndDate = $currentplandetails['subscription_end_date'] ?? '-';
        $currentPlanQuantity = $totalLicenses > 0 ? $totalLicenses : null;

        // --- Build target plans from cart items ---
        $targetPlans = [];
        $detectedUpgradeMode = $forcePartialMode ? 'partial' : 'full';

        if ($cart && $cart->items->isNotEmpty()) {
            $isApprovedRequest = \App\Models\PurchaseRequest::where('cart_id', $cart->id)
                ->where('status', \App\Models\PurchaseRequest::STATUS_APPROVED)
                ->exists();

            // Get provider_id from the cart item's plan
            $providerId = 0;
            $firstItem = $cart->items->first();
            if ($firstItem && $firstItem->plan) {
                $providerId = (int) ($firstItem->plan->provider_id ?? 0);
            }
            if ($providerId === 0) {
                $providerId = (int) ($cart->provider_id ?? 0);
            }

            $requiresRequest = in_array($providerId, [1, 3]) && !$isApprovedRequest;
            $changeVia = $requiresRequest ? 'request' : 'cart';
            $providerName = $providerId === 1 ? 'Tizzy' : ($providerId === 3 ? 'Google' : 'Microsoft');

            $cart->loadMissing('customer');
            $subscriptionOrderId = (int) ($cart->order_id ?? $validated['order_id'] ?? 0);
            $cartService = app(PartnerCartService::class);

            foreach ($cart->items as $item) {
                // --- THIS IS THE TARGET PLAN (what user is upgrading TO) ---
                $targetPlan = $item->plan;
                $customer = $cart->customer;

                $licenses = !empty($validated['licenses'])
                    ? max(1, (int) $validated['licenses'])
                    : max(1, (int) ($item->licenses ?? 1));
                $taxPercentage = (float) ($cart->gst_percentage ?? 18);

                // Get target plan details
                $targetPlanId = (int) ($targetPlan->id ?? $item->plan_id ?? 0);
                $targetPlanName = $targetPlan->name ?? $targetPlan->title ?? '';
                $targetProviderId = (int) ($targetPlan->provider_id ?? $providerId ?? 0);

                // Get target provider name
                $targetProviderName = $providerName;
                if ($targetProviderId > 0 && $targetProviderId !== $providerId) {
                    $targetProvider = Provider::query()->find($targetProviderId);
                    if ($targetProvider) {
                        $targetProviderName = $targetProvider->name ?? 'Unknown';
                    }
                }

                // Calculate proration if we have source order
                $calculation = [];
                $sourceOrder = null;
                $sourceItem = null;

                if ($subscriptionOrderId > 0) {
                    [$sourceOrder, $sourceItem] = array_slice(
                        $this->resolveUpgradeSourceSubscription(
                            $partnerId,
                            !empty($validated['customer_id']) ? (int) $validated['customer_id'] : null,
                            $subscriptionOrderId,
                            $sourceItemId > 0 ? $sourceItemId : null,
                            $sourcePlanId > 0 ? $sourcePlanId : null
                        ),
                        0,
                        2
                    );

                    if ($sourceOrder) {
                        // Copy parent order transfer_domain onto upgrade/downgrade cart
                        $cartService->assignCartTransferDomain(
                            $cart,
                            (string) ($sourceOrder->transfer_domain ?? '')
                        );

                        // --- CRITICAL FIX: Get total licenses including license-add for proration ---
                        $licenseTotals = $this->resolveUpgradeLicenseTotals($sourceOrder, $sourceItem);
                        $totalCurrentLicenses = (int) $licenseTotals['current_licenses'];

                        $newUnitPrice = round((float) ($targetPlan->price ?? 0), 2);

                        // Always pass merged total (old + license-add) so remaining credit uses all seats.
                        $calculation = $this->resolveUpgradeProration(
                            $sourceOrder,
                            $sourceItem,
                            $newUnitPrice,
                            $licenses,
                            $taxPercentage,
                            (float) $promoDiscountPercent,
                            (int) $targetPlan->id,
                            $totalCurrentLicenses
                        );

                        // Override current_licenses in calculation with total including license-add
                        $calculation['current_licenses'] = $totalCurrentLicenses;
                        $calculation['total_licenses'] = $totalCurrentLicenses;
                        $calculation['remaining_licenses'] = max(0, $totalCurrentLicenses - $licenses);
                        $calculation['upgraded_licenses'] = $licenses;
                    }
                }

                // --- CRITICAL: Get the current plan info for reference ---
                $currentPlanForItem = [];
                if ($sourcePlanId > 0) {
                    $sourcePlanObj = Plan::query()->find($sourcePlanId);
                    if ($sourcePlanObj) {
                        $currentPlanForItem = [
                            'id' => (int) $sourcePlanObj->id,
                            'plan_id' => (int) $sourcePlanObj->id,
                            'name' => (string) ($sourcePlanObj->name ?? $sourcePlanObj->title ?? ''),
                            'title' => (string) ($sourcePlanObj->title ?? $sourcePlanObj->name ?? ''),
                            'price' => (float) ($sourcePlanObj->price ?? 0),
                            'provider_id' => (int) ($sourcePlanObj->provider_id ?? 0),
                            'customer_limit' => $sourcePlanObj->customer_limit ?? null,
                            'total_licenses' => $totalLicenses > 0 ? $totalLicenses : null,
                            'remaining_licenses' => $remainingLicenses > 0 ? $remainingLicenses : null,
                            'upgraded_licenses' => $upgradedLicenses > 0 ? $upgradedLicenses : null,
                        ];
                    }
                }

                $targetPlans[] = [
                    'coupon_code' => $coupon_code,
                    'provider_in_cart' => isset($detailObj) && $detailObj ? $detailObj->provider_id : null,
                    'item_id' => $item->id,
                    'cart_id' => $item->id,
                    'main_cart_id' => (int) $item->cart_id,
                    'status' => $cartStatus,
                    'provider_id' => $targetProviderId,
                    'provider_name' => $targetProviderName,
                    'type' => $cart->type ?? ($isUpgrade ? Cart::TYPE_UPGRADE : Cart::TYPE_DOWNGRADE),
                    'plan_id' => $targetPlanId,
                    'plan_name' => $targetPlanName,
                    'customer_limit' => $targetPlan->customer_limit ?? null,
                    'customer_id' => $cart->customer_id,
                    'company_name' => $customer->company_name ?? null,
                    'domain_name' => $cart->domain_name ?? null,
                    'licenses' => $licenses,
                    'license_count' => $licenses,
                    'current_plan_licenses' => (int) ($calculation['current_licenses'] ?? $totalLicenses ?? 0),
                    'total_licenses' => (int) ($calculation['total_licenses'] ?? $totalLicenses ?? 0),
                    'remaining_licenses' => (int) ($calculation['remaining_licenses'] ?? $remainingLicenses ?? 0),
                    'upgraded_licenses' => (int) ($calculation['upgraded_licenses'] ?? $upgradedLicenses ?? 0),
                    'credit_licenses' => (int) ($calculation['credit_licenses'] ?? 0),
                    'licenses_delta' => $licenses - ($totalLicenses ?? 0),
                    'unit_price' => $calculation['new_unit_price'] ?? 0,
                    'subtotal' => round((float) ($calculation['new_plan_cost'] ?? 0), 2),
                    'new_plan_cost' => round((float) ($calculation['new_plan_cost'] ?? 0), 2),
                    'remaining_credit' => round((float) ($calculation['remaining_credit'] ?? 0), 2),
                    'remaining_value' => round((float) ($calculation['remaining_value'] ?? 0), 2),
                    'pro_rata_adjustment' => round((float) ($calculation['pro_rata_adjustment'] ?? 0), 2),
                    'applied_pro_rata' => round((float) ($calculation['applied_pro_rata'] ?? 0), 2),
                    'wallet_credit' => round((float) ($calculation['wallet_credit'] ?? 0), 2),
                    'remaining_days' => (int) ($calculation['remaining_days'] ?? 0),
                    'daily_rate_per_license' => $calculation['daily_rate_per_license'] ?? 0,
                    'final_payable' => round((float) ($calculation['final_payable'] ?? 0), 2),
                    'taxable_amount' => round((float) ($calculation['taxable_amount'] ?? 0), 2),
                    'coupon_discount_percent' => round((float) $promoDiscountPercent),
                    'discount_amount' => number_format($calculation['coupon_discount'] ?? 0, 2, '.', ''),
                    'price_after_discount' => round((float) ($calculation['taxable_amount'] ?? 0), 2),
                    'gst_percentage' => round($taxPercentage),
                    'gst_amount' => round((float) ($calculation['gst_amount'] ?? 0), 2),
                    'grand_total' => round((float) ($calculation['final_payable'] ?? 0), 2),
                    'subscription_start_date' => $subscriptionStartDate,
                    'subscription_end_date' => $subscriptionEndDate,
                    'upgrade_mode' => $detectedUpgradeMode,
                    'is_partial' => $detectedUpgradeMode === 'partial',
                    'wallet_balance' => number_format($walletBalance, 2, '.', ''),
                    'created_at' => optional($item->cart->created_at)->format('Y-m-d H:i:s'),
                    'updated_at' => optional($item->cart->updated_at)->format('Y-m-d H:i:s'),
                    // --- FLAGS ---
                    'is_current_plan' => false,
                    'is_upgrading_to' => $isUpgrade,
                    'is_downgrading_to' => !$isUpgrade,
                    'requires_request' => $requiresRequest,
                    'change_via' => $changeVia,
                    // --- CURRENT PLAN INFO ---
                    'current_plan' => $currentPlanForItem,
                    'current_plan_id' => $sourcePlanId > 0 ? $sourcePlanId : null,
                    'current_plan_name' => $currentplandetails['plan_name'] ?? null,
                    'current_licenses' => $totalLicenses > 0 ? $totalLicenses : null,
                    'old_total_licenses' => $oldTotalLicenses,
                    'new_total_licenses' => $newTotalLicenses,
                    // --- CREDIT KEYS PER PLAN ---
                    'credit_limit' => $creditLimit,
                    'credit_used' => $creditUsedTotal,
                    'remaining_credit_limit' => $remainingLimit,
                    'credit_limit_reached' => $creditLimitReached,
                    'credit_applicable' => true,
                    'credit_zero_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
                    'is_credit_applicable' => true,
                    'credit_blocked' => $creditLockedByProcessing,
                    'credit_block_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
                    'processing_orders_amount' => round($processingOrdersAmount, 2),
                    'processing_orders_count' => $processingOrdersCount,
                    'credit_locked_by_processing_orders' => $creditLockedByProcessing,
                    'credit_lock_message' => $creditLockedMessage,
                    'available_credit_for_purchase' => round($availableCreditForPurchase, 2),
                ];
            }
        }

        // --- Build the final response ---
        $firstPlan = $targetPlans[0] ?? [];

        // --- Calculate Can Purchase based on final payable ---
        $payableAmount = (float) ($firstPlan['final_payable'] ?? 0);

        $canPurchase = false;
        if (!$creditLimitReached) {
            if ($payableAmount <= 0.005) {
                $canPurchase = true;
            } elseif ($payableAmount <= $availableCreditForPurchase) {
                $canPurchase = true;
            } elseif ($creditLockedByProcessing && $payableAmount <= ($availableCreditForPurchase + $processingOrdersAmount)) {
                $canPurchase = true;
            }
        }

        // --- BUILD PURCHASE BLOCK MESSAGE ---
        $purchaseBlockMessage = null;
        if ($creditLockedByProcessing) {
            $purchaseBlockMessage = 'Credit is locked because ₹' . number_format($processingOrdersAmount, 2) . ' worth of orders are in processing state. Available credit: ₹' . number_format($availableCreditForPurchase, 2);
        } elseif ($creditLimitReached) {
            $purchaseBlockMessage = 'Credit limit reached. You cannot buy additional items.';
        } elseif (!$canPurchase && $payableAmount > $availableCreditForPurchase) {
            $purchaseBlockMessage = 'Insufficient credit. Required: ₹' . number_format($payableAmount, 2) . ', Available: ₹' . number_format($availableCreditForPurchase, 2);
        } else {
            $purchaseBlockMessage = 'Sufficient credit allocation available to complete this purchase';
        }

        // --- CRITICAL: Get current and target plan IDs correctly ---
        $currentPlanIdFromSource = (int) ($validated['from_plan_id'] ?? $validated['current_plan_id'] ?? 0);
        if ($currentPlanIdFromSource <= 0 && !empty($currentplandetails['plan_id'])) {
            $currentPlanIdFromSource = (int) $currentplandetails['plan_id'];
        }

        // --- CRITICAL: Target plan ID is from the cart item (plan_id), not from the source ---
        $targetPlanIdFromCart = (int) ($firstPlan['plan_id'] ?? 0);
        $targetPlanNameFromCart = (string) ($firstPlan['plan_name'] ?? '');

        // Get target provider info
        $targetProviderId = (int) ($firstPlan['provider_id'] ?? 0);
        $targetProviderName = (string) ($firstPlan['provider_name'] ?? '');
        $targetRequiresRequest = (bool) ($firstPlan['requires_request'] ?? false);
        $targetChangeVia = (string) ($firstPlan['change_via'] ?? 'cart');

        // Get current plan info
        $currentPlanId = $currentPlanIdFromSource > 0 ? $currentPlanIdFromSource : null;
        $currentPlanName = $currentplandetails['plan_name'] ?? null;
        $currentProviderId = $currentplandetails['provider_id'] ?? null;
        $currentProviderName = $currentplandetails['provider_name'] ?? 'Unknown';

        // --- CRITICAL FIX: Ensure current and target are different ---
        if ($currentPlanId == $targetPlanIdFromCart && $targetPlanIdFromCart > 0) {
            $cartItemPlanId = $cart && $cart->items->isNotEmpty() ? (int) ($cart->items->first()->plan_id ?? 0) : 0;
            if ($cartItemPlanId > 0 && $cartItemPlanId != $currentPlanId) {
                $targetPlanIdFromCart = $cartItemPlanId;
                $targetPlanObj = Plan::query()->find($cartItemPlanId);
                if ($targetPlanObj) {
                    $targetPlanNameFromCart = $targetPlanObj->name ?? $targetPlanObj->title ?? '';
                    $targetProviderId = (int) ($targetPlanObj->provider_id ?? 0);
                    if ($targetProviderId > 0) {
                        $targetProvider = Provider::query()->find($targetProviderId);
                        $targetProviderName = $targetProvider->name ?? 'Unknown';
                    }
                    $targetRequiresRequest = in_array($targetProviderId, [1, 3]) && !$isApprovedRequest;
                    $targetChangeVia = $targetRequiresRequest ? 'request' : 'cart';
                }
            }
        }

        Log::info('upgradeCartDetails final response', [
            'current_plan_id' => $currentPlanId,
            'current_plan_name' => $currentPlanName,
            'total_licenses' => $totalLicenses,
            'remaining_licenses' => $remainingLicenses,
            'upgraded_licenses' => $upgradedLicenses,
            'target_plan_id' => $targetPlanIdFromCart,
            'target_plan_name' => $targetPlanNameFromCart,
            'target_licenses' => $firstPlan['licenses'] ?? null,
            'is_partial' => $forcePartialMode,
            'plans_count' => count($targetPlans),
            'credit_locked_by_processing_orders' => $creditLockedByProcessing,
            'old_total_licenses' => $oldTotalLicenses,
            'new_total_licenses' => $newTotalLicenses,
        ]);

        $data = [
            // --- CURRENT PLAN (source) ---
            'currentplandetails' => $currentplandetails,
            'current_plan_details' => $currentplandetails,
            'current_plan' => $currentplandetails,
            'current_plan_id' => $currentPlanId,
            'current_plan_name' => $currentPlanName,
            'current_licenses' => $totalLicenses > 0 ? $totalLicenses : null,
            'current_plan_licenses' => $totalLicenses > 0 ? $totalLicenses : null,

            // --- FIX: ADD THESE LICENSE COUNT FIELDS ---
            'total_licenses' => $totalLicenses > 0 ? $totalLicenses : null,
            'remaining_licenses' => $remainingLicenses > 0 ? $remainingLicenses : null,
            'upgraded_licenses' => $upgradedLicenses > 0 ? $upgradedLicenses : null,
            'old_total_licenses' => $oldTotalLicenses,
            'new_total_licenses' => $newTotalLicenses,

            // --- TARGET PLANS (what user is upgrading TO) ---
            'plans' => $targetPlans,
            'target_plan' => $firstPlan,
            'target_plan_id' => $targetPlanIdFromCart > 0 ? $targetPlanIdFromCart : null,
            'target_plan_name' => $targetPlanNameFromCart !== '' ? $targetPlanNameFromCart : null,
            'target_licenses' => $firstPlan['licenses'] ?? null,

            // --- Upgrade mode ---
            'upgrade_mode' => $detectedUpgradeMode,
            'is_partial' => $detectedUpgradeMode === 'partial',
            'main_cart_id' => $cart ? (int) $cart->id : null,
            'status' => $cartStatus,
            'coupen' => $coupon_code,
            'coupon_code' => $coupon_code,

            // --- License counts ---
            'license_count' => (int) collect($targetPlans)->sum(fn($p) => (int) ($p['licenses'] ?? 0)),
            'new_licenses' => (int) ($firstPlan['licenses'] ?? 0),
            'licenses_delta' => (int) ($firstPlan['licenses'] ?? 0) - ($totalLicenses ?? 0),
            'selected_licenses' => (int) ($upgradedLicenses > 0 ? $upgradedLicenses : ($firstPlan['licenses'] ?? 0)),

            // --- Pricing ---
            'remaining_credit' => round((float) ($firstPlan['remaining_credit'] ?? 0), 2),
            'remaining_value' => round((float) ($firstPlan['remaining_value'] ?? 0), 2),
            'pro_rata_adjustment' => round((float) ($firstPlan['pro_rata_adjustment'] ?? 0), 2),
            'applied_pro_rata' => round((float) ($firstPlan['applied_pro_rata'] ?? 0), 2),
            'new_plan_cost' => round((float) ($firstPlan['subtotal'] ?? $firstPlan['new_plan_cost'] ?? 0), 2),
            'subtotal' => round((float) ($firstPlan['subtotal'] ?? $firstPlan['new_plan_cost'] ?? 0), 2),
            'gst_amount' => round((float) ($firstPlan['gst_amount'] ?? 0), 2),
            'discount_amount' => round((float) ($firstPlan['discount_amount'] ?? 0), 2),
            'wallet_credit' => round((float) ($firstPlan['wallet_credit'] ?? 0), 2),
            'final_payable' => round((float) ($firstPlan['final_payable'] ?? 0), 2),
            'remaining_days' => (int) ($firstPlan['remaining_days'] ?? 0),

            // --- REQUEST FLAGS for Tizzy/Google ---
            'requires_request' => $targetRequiresRequest,
            'change_via' => $targetChangeVia,
            'provider_id' => $targetProviderId > 0 ? $targetProviderId : null,
            'provider_name' => $targetProviderName !== '' ? $targetProviderName : null,
            'action_type' => $isUpgrade ? 'upgrade' : 'downgrade',
            'request_endpoint' => $targetRequiresRequest
                ? ($isUpgrade ? '/api/partner/upgrade-request' : '/api/partner/downgrade-request')
                : null,
            'request_message' => $targetRequiresRequest
                ? ($isUpgrade
                    ? 'This upgrade requires SuperAdmin approval. A request will be submitted for review.'
                    : 'This downgrade requires SuperAdmin approval. A request will be submitted for review.')
                : null,

            // --- CREDIT KEYS ---
            'credit_limit' => $creditLimit,
            'credit_used' => $creditUsedTotal,
            'remaining_credit_limit' => $remainingLimit,
            'credit_limit_reached' => $creditLimitReached,
            'can_purchase' => $canPurchase,
            'purchase_block_message' => $purchaseBlockMessage,
            'credit_applicable' => true,
            'credit_zero_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
            'is_credit_applicable' => true,
            'credit_blocked' => $creditLockedByProcessing,
            'credit_block_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
            'processing_orders_amount' => round($processingOrdersAmount, 2),
            'processing_orders_count' => $processingOrdersCount,
            'credit_locked_by_processing_orders' => $creditLockedByProcessing,
            'credit_lock_message' => $creditLockedMessage,
            'available_credit_for_purchase' => round($availableCreditForPurchase, 2),
            'wallet_balance' => $walletBalance,
        ];

        // Add PO details
        $sourceOrderIdForPo = (int) ($cart ? ($cart->order_id ?? 0) : 0);
        if ($sourceOrderIdForPo <= 0) {
            $sourceOrderIdForPo = (int) ($validated['order_id'] ?? 0);
        }
        if ($sourceOrderIdForPo <= 0 && !empty($currentplandetails['order_id'])) {
            $sourceOrderIdForPo = (int) $currentplandetails['order_id'];
        }
        $sourcePo = $this->resolveParentOrderPoPayload($sourceOrderIdForPo);
        $data['po'] = $sourcePo;
        $data['po_link'] = $sourcePo['po_link'] ?? null;
        $data['po_mode'] = $sourcePo['po_mode'] ?? 'generated';
        $data['po_number'] = $sourcePo['po_number'] ?? '';
        $data['final_po_link'] = $sourcePo['final_po_link'] ?? null;
        $data['is_uploaded_po'] = (bool) ($sourcePo['is_uploaded'] ?? false);

        // Check if cart exists and has items
        if ((!$cart || $cart->items->isEmpty()) && $targetPlans === []) {
            if ($this->resolveUpgradePlanIdFromRequest($request) > 0) {
                if (!$request->attributes->get('_upgrade_cart_auto_created')) {
                    if ($isUpgrade) {
                        $createError = $this->ensureUpgradeCartFromRequest($request);
                    } else {
                        $createError = $this->ensureDowngradeCartFromRequest($request);
                    }
                    if ($createError !== null) {
                        return $createError;
                    }
                    $request->attributes->set('_upgrade_cart_auto_created', true);
                    return $this->upgradeCartDetails($request);
                }
            }

            $cartTypeName = $isUpgrade ? 'Upgrade' : 'Downgrade';

            return response()->json([
                'success' => false,
                'message' => $cart
                    ? "{$cartTypeName} cart has no items. Call partial-add-to-cart again."
                    : "{$cartTypeName} cart not found. Send main_cart_id from add-to-cart response.",
                'data' => [
                    'main_cart_id' => $mainCartId > 0 ? $mainCartId : null,
                    'plans' => [],
                    // --- CREDIT KEYS ---
                    'credit_limit' => $creditLimit,
                    'credit_used' => $creditUsedTotal,
                    'remaining_credit_limit' => $remainingLimit,
                    'credit_limit_reached' => $creditLimitReached,
                    'can_purchase' => false,
                    'purchase_block_message' => $creditLockedByProcessing ? $creditLockedMessage : 'Insufficient credit',
                    'credit_applicable' => true,
                    'credit_zero_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
                    'is_credit_applicable' => true,
                    'credit_blocked' => $creditLockedByProcessing,
                    'credit_block_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
                    'processing_orders_amount' => round($processingOrdersAmount, 2),
                    'processing_orders_count' => $processingOrdersCount,
                    'credit_locked_by_processing_orders' => $creditLockedByProcessing,
                    'credit_lock_message' => $creditLockedMessage,
                    'available_credit_for_purchase' => round($availableCreditForPurchase, 2),
                ],
            ], $cart ? 422 : 404);
        }

        return response()->json([
            'success' => true,
            'data' => $data,
            'wallet_balance' => $walletBalance,
            // --- CREDIT KEYS TOP LEVEL ---
            'credit_limit' => $creditLimit,
            'credit_used' => $creditUsedTotal,
            'remaining_credit_limit' => $remainingLimit,
            'credit_limit_reached' => $creditLimitReached,
            'can_purchase' => $canPurchase,
            'purchase_block_message' => $purchaseBlockMessage,
            'credit_applicable' => true,
            'credit_zero_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
            'is_credit_applicable' => true,
            'credit_blocked' => $creditLockedByProcessing,
            'credit_block_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
            'processing_orders_amount' => round($processingOrdersAmount, 2),
            'processing_orders_count' => $processingOrdersCount,
            'credit_locked_by_processing_orders' => $creditLockedByProcessing,
            'credit_lock_message' => $creditLockedMessage,
            'available_credit_for_purchase' => round($availableCreditForPurchase, 2),
        ]);
    }


    public function downgradeCart(Request $request)
    {
        try {
            $validated = $request->validate([
                'partner_id'   => 'required|exists:pgsql_auth.partners,id',
                'plan_id'      => 'nullable|exists:pgsql_product.plans,id',
                'order_id'     => 'nullable|integer|exists:pgsql_billing.orders,id',
                'customer_id'  => 'nullable|exists:pgsql_billing.customers,id',
                'order_sub_id' => 'nullable',
            ]);

            $partnerId = (int) $validated['partner_id'];
            $licenses = null;
            $mainCartId = null;
            $cartService = app(PartnerCartService::class);
            $cart = null;
            $item = null;
            $plan = null;

            if ($mainCartId) {
                $cart = Cart::with(['items.plan', 'customer'])
                    ->where('partner_id', $partnerId)
                    ->whereKey($mainCartId)
                    ->ofType(Cart::TYPE_DOWNGRADE)
                    ->first();

                if (!$cart || $cart->items->isEmpty()) {
                    return response()->json([
                        'success' => false,
                        'message' => 'Downgrade cart not found for this partner.',
                    ], 404);
                }

                $item = $cart->items->first();

                if (!empty($validated['plan_id'])) {
                    $plan = Plan::find($validated['plan_id']);
                    if (!$plan) {
                        return response()->json([
                            'success' => false,
                            'message' => 'Plan not found',
                        ], 404);
                    }
                    $item->plan_id = (int) $plan->id;
                    $item->unit_price = $plan->price;
                } else {
                    $plan = $item->plan ?? Plan::find($item->plan_id);
                }

                if ($licenses !== null) {
                    $item->licenses = max(1, $licenses);
                }

                $item->save();
                $item->load('cart');
            } else {
                if (empty($validated['plan_id'])) {
                    return response()->json([
                        'success' => false,
                        'message' => 'plan_id is required when creating a downgrade cart.',
                    ], 422);
                }

                $plan = Plan::find($validated['plan_id']);
                if (!$plan) {
                    return response()->json([
                        'success' => false,
                        'message' => 'Plan not found',
                    ], 404);
                }

                $customerId = !empty($validated['customer_id']) ? (int) $validated['customer_id'] : null;
                $companyName = null;
                if ($customerId) {
                    $customer = Customer::where('id', $customerId)->where('partner_id', $partnerId)->first();
                    if ($customer) {
                        $companyName = $customer->company_name;
                    }
                }

                $subscriptionOrderId = null;
                if ($customerId) {
                    try {
                        $subscriptionOrderId = app(B2bSubscriptionUpgradeService::class)->resolveSubscriptionId(
                            $partnerId,
                            isset($validated['order_id']) && (int) $validated['order_id'] > 0 ? (int) $validated['order_id'] : null,
                            $customerId,
                            null,
                        );
                    } catch (\Illuminate\Validation\ValidationException $e) {
                        return response()->json([
                            'success' => false,
                            'message' => collect($e->errors())->flatten()->first() ?: 'Subscription not found for customer.',
                            'errors' => $e->errors(),
                        ], 422);
                    }
                }
                if (!$subscriptionOrderId && isset($validated['order_id']) && (int) $validated['order_id'] > 0) {
                    $subscriptionOrderId = (int) $validated['order_id'];
                }

                $orderSubIdHint = !empty($validated['order_sub_id']) ? (int) $validated['order_sub_id'] : 0;
                $sourcePlanId = 0;
                $currentLicenses = 1;
                if ($subscriptionOrderId) {
                    [$dgSourceOrder, $dgSourceItem] = array_slice(
                        $this->resolveUpgradeSourceSubscription(
                            $partnerId,
                            $customerId,
                            $subscriptionOrderId,
                            $orderSubIdHint > 0 ? $orderSubIdHint : null,
                            null
                        ),
                        0,
                        2
                    );
                    $sourcePlanId = (int) ($dgSourceItem->plan_id ?? $dgSourceOrder->plan_id ?? 0);
                    $currentLicenses = max(1, (int) ($dgSourceItem->quantity ?? $dgSourceOrder->quantity ?? 1));
                }

                $providerId = (int) ($plan->provider_id ?? 0);
                if ($providerId <= 0 && $sourcePlanId > 0) {
                    $providerId = (int) (Plan::query()->whereKey($sourcePlanId)->value('provider_id') ?? 0);
                }
                // When called from upgrade-cart-details (bypass), always create the cart so plans[] can be returned.
                if (
                    $this->isRequestBasedChangeProvider($providerId)
                    && !$request->attributes->get('_bypass_request_block')
                ) {
                    return $this->changeRequestRequiredResponse('downgrade', $providerId, [
                        'plan_id' => (int) $plan->id,
                        'current_plan_id' => $sourcePlanId,
                        'licenses' => $currentLicenses,
                    ]);
                }
                if ($sourcePlanId > 0 && !$this->isLowerPlan($plan, $sourcePlanId)) {
                    return response()->json([
                        'success' => false,
                        'message' => 'Downgrade must move to a lower plan with the same license count.',
                        'current_plan_id' => $sourcePlanId,
                        'current_licenses' => $currentLicenses,
                    ], 422);
                }

                $licenses = $currentLicenses;

                $domainName = $this->subscriptionDomainNameForCart(null, (int) $subscriptionOrderId);

                $cartService->deleteActiveCartsByType($partnerId, Cart::TYPE_DOWNGRADE);

                $cart = Cart::query()
                    ->with(['items.plan'])
                    ->where('partner_id', $partnerId)
                    ->ofType(Cart::TYPE_DOWNGRADE)
                    ->active()
                    ->orderByDesc('id')
                    ->first();

                if ($cart) {
                    $cart->provider_id = $plan->provider_id;
                    if ($customerId) {
                        $cart->customer_id = $customerId;
                    }
                    if (!empty($domainName) && Schema::connection('pgsql_billing')->hasColumn('carts', 'domain_name')) {
                        $cart->domain_name = $domainName;
                    }
                    if ($subscriptionOrderId && Schema::connection('pgsql_billing')->hasColumn('carts', 'order_id')) {
                        $cart->order_id = $subscriptionOrderId;
                    }
                    $cart->status = Cart::STATUS_ACTIVE;
                    $cart->save();

                    $item = $cart->items->first();
                    if ($item) {
                        $item->plan_id = $plan->id;
                        $item->licenses = $licenses;
                        $item->unit_price = round((float) ($plan->price ?? $item->unit_price ?? 0), 2);
                        $item->grand_total = round(((float) $item->unit_price) * max(1, (int) $licenses), 2);
                        $item->save();
                        $item->load(['cart', 'plan']);
                    } else {
                        $item = $cartService->createUpgradeLine($cart, $plan, $customerId, $licenses);
                        $item->load('cart');
                    }
                } else {
                    $cartPayload = [
                        'session_id'      => (string) Str::uuid(),
                        'partner_id'      => $partnerId,
                        'provider_id'     => $plan->provider_id,
                        'customer_id'     => $customerId,
                        'type'            => Cart::TYPE_DOWNGRADE,
                        'status'          => Cart::STATUS_ACTIVE,
                        'currency'        => 'INR',
                        'gst_percentage'  => 18,
                        'discount_amount' => 0,
                        'gst_amount'      => 0,
                        'grand_total'     => 0,
                    ];
                    if (!empty($domainName) && Schema::connection('pgsql_billing')->hasColumn('carts', 'domain_name')) {
                        $cartPayload['domain_name'] = $domainName;
                    }

                    if (Schema::connection('pgsql_billing')->hasColumn('carts', 'order_id')) {
                        $cartPayload['order_id'] = $subscriptionOrderId;
                    }

                    $cart = Cart::create($cartPayload);
                    $item = $cartService->createUpgradeLine($cart, $plan, $customerId, $licenses);
                    $item->load('cart');
                }
            }

            if (!$plan) {
                $plan = $item->plan ?? Plan::find($item->plan_id);
            }
            if (!$plan) {
                return response()->json([
                    'success' => false,
                    'message' => 'Plan not found',
                ], 404);
            }

            $licenses = max(1, (int) ($item->licenses ?? $licenses ?? 1));
            $customerId = (int) ($cart->customer_id ?? 0) ?: null;
            $companyName = ($cart->customer && !empty($cart->customer->company_name))
                ? $cart->customer->company_name
                : null;

            $subscriptionOrderId = null;
            if ($customerId) {
                try {
                    $subscriptionOrderId = app(B2bSubscriptionUpgradeService::class)->resolveSubscriptionId(
                        $partnerId,
                        isset($validated['order_id']) && (int) $validated['order_id'] > 0 ? (int) $validated['order_id'] : null,
                        $customerId,
                        null,
                    );
                } catch (\Throwable $e) {
                    $subscriptionOrderId = isset($validated['order_id']) && (int) $validated['order_id'] > 0
                        ? (int) $validated['order_id']
                        : null;
                }
            } elseif (isset($validated['order_id']) && (int) $validated['order_id'] > 0) {
                $subscriptionOrderId = (int) $validated['order_id'];
            }

            $domainName = $this->applySubscriptionDomainToCart($cart, null, (int) ($subscriptionOrderId ?? 0));

            $calculation = [];
            $couponPercent = $cartService->resolveCouponDiscountPercent($cart->coupen);

            if ($subscriptionOrderId) {
                [$orderSubId, $fromPlanId] = $this->resolveUpgradeSourceLineHints($request, $validated, $cart);
                [$sourceOrder, $sourceItem, $resolvedOrderId] = $this->resolveUpgradeSourceSubscription(
                    $partnerId,
                    $customerId,
                    $subscriptionOrderId,
                    $orderSubId > 0 ? $orderSubId : null,
                    $fromPlanId > 0 ? $fromPlanId : null
                );

                if ($resolvedOrderId > 0 && Schema::connection('pgsql_billing')->hasColumn('carts', 'order_id')) {
                    $cart->order_id = $resolvedOrderId;
                }

                $newUnitPrice = round((float) ($plan->price ?? 0), 2);
                $calculation = $this->resolveUpgradeProration(
                    $sourceOrder,
                    $sourceItem,
                    $newUnitPrice,
                    $licenses,
                    (float) ($cart->gst_percentage ?? 18),
                    $couponPercent,
                    (int) $plan->id
                );

                $cart->pro_rata_adjustment = $calculation['pro_rata_adjustment'];
                $cart->discount_amount = $calculation['coupon_discount'] ?? 0;
                $cart->gst_amount = $calculation['gst_amount'];
                $cart->grand_total = $calculation['final_payable'];
                if (Schema::connection('pgsql_billing')->hasColumn('carts', 'subtotal')) {
                    $cart->subtotal = $calculation['new_plan_cost'];
                }
                $this->rememberUpgradeSourceLine($cart, $sourceItem);
                $cart->save();
                $cartService->assignCartTransferDomain($cart, (string) ($sourceOrder->transfer_domain ?? ''));

                $item->licenses = $licenses;
                $item->unit_price = $calculation['new_unit_price'];
                $item->grand_total = $calculation['new_plan_cost'] ?? $item->grand_total;
                $item->save();
                $cart = $cart->refresh();
                $domainName = $this->applySubscriptionDomainToCart($cart, $sourceOrder, (int) ($resolvedOrderId ?: $subscriptionOrderId));
            }

            $subscriptionStartDate = $item->subscription_start_date
                ? \Carbon\Carbon::parse($item->subscription_start_date)->format('Y-m-d')
                : null;
            $subscriptionEndDate = $item->subscription_end_date
                ? \Carbon\Carbon::parse($item->subscription_end_date)->format('Y-m-d')
                : null;

            $currentPlan = null;
            if (!empty($validated['order_sub_id'])) {
                $orderItemRow = $this->orderItem->newQuery()->where('id', $validated['order_sub_id'])->first();
                $sourceOrder = $orderItemRow
                    ? $this->order->newQuery()->where('id', (int) $orderItemRow->order_id)->first()
                    : null;
                if ($orderItemRow && $sourceOrder) {
                    $sourcePlan = $this->plan->newQuery()->where('id', (int) $orderItemRow->plan_id)->first();
                    $currentPlan = (object) array_merge($orderItemRow->toArray(), [
                        'plan_name' => $sourcePlan->name ?? '',
                        'provider_id' => $sourcePlan->provider_id ?? null,
                        'subscription_start_date' => $sourceOrder->subscription_start_date,
                        'subscription_end_date' => $sourceOrder->subscription_end_date,
                        'promo_code' => $sourceOrder->promo_code ?? null,
                    ]);
                }
            } elseif ($subscriptionOrderId) {
                $orderItemRow = $this->orderItem->newQuery()
                    ->where('order_id', $subscriptionOrderId)
                    ->orderBy('id')
                    ->first();
                $sourceOrder = $this->order->newQuery()
                    ->where('id', $subscriptionOrderId)
                    ->where('partner_id', $partnerId)
                    ->first();

                if ($orderItemRow && $sourceOrder) {
                    $sourcePlan = $this->plan->newQuery()->where('id', (int) $orderItemRow->plan_id)->first();
                    $currentPlan = (object) [
                        'id' => $orderItemRow->id,
                        'order_id' => $orderItemRow->order_id,
                        'plan_id' => $orderItemRow->plan_id,
                        'variant_id' => $orderItemRow->variant_id ?? null,
                        'plan_name' => $sourcePlan->name ?? '',
                        'provider_id' => $sourcePlan->provider_id ?? null,
                        'unit_price' => $orderItemRow->unit_price ?? 0,
                        'quantity' => $orderItemRow->quantity ?? 1,
                        'discount_amount' => $orderItemRow->discount_amount ?? '0.00',
                        'tax_amount' => $orderItemRow->tax_amount ?? '0.00',
                        'tax_rate' => $orderItemRow->tax_rate ?? '0.00',
                        'total_amount' => $orderItemRow->total_amount ?? '0.00',
                        'subscription_start_date' => date('d-m-Y', strtotime($sourceOrder->subscription_start_date)),
                        'subscription_end_date' => date('d-m-Y', strtotime($sourceOrder->subscription_end_date)),
                        'promo_code' => $sourceOrder->promo_code ?? null,
                        'created_at' => $orderItemRow->created_at,
                    ];
                } elseif ($sourceOrder) {
                    $sourcePlan = $this->plan->newQuery()->where('id', (int) $sourceOrder->plan_id)->first();
                    $currentPlan = (object) [
                        'order_id' => $sourceOrder->id,
                        'plan_id' => $sourceOrder->plan_id,
                        'subscription_start_date' => date('d-m-Y', strtotime($sourceOrder->subscription_start_date)),
                        'subscription_end_date' => date('d-m-Y', strtotime($sourceOrder->subscription_end_date)),
                        'promo_code' => $sourceOrder->promo_code ?? null,
                        'unit_price' => $sourceOrder->price ?? 0,
                        'quantity' => $sourceOrder->quantity ?? 1,
                        'plan_name' => $sourcePlan->name ?? '',
                        'provider_id' => $sourcePlan->provider_id ?? null,
                    ];
                }
            }

            $currentPlanDetailsArr = $currentPlan ? [
                'id'                       => $currentPlan->id ?? null,
                'order_id'                 => $currentPlan->order_id ?? null,
                'plan_id'                  => $currentPlan->plan_id ?? null,
                'variant_id'               => $currentPlan->variant_id ?? null,
                'plan_name'                => $currentPlan->plan_name ?? '',
                'provider_id'              => $currentPlan->provider_id ?? null,
                'unit_price'               => $currentPlan->unit_price ?? 0,
                'quantity'                 => $currentPlan->quantity ?? 1,
                'discount_amount'          => $currentPlan->discount_amount ?? '0.00',
                'tax_amount'               => $currentPlan->tax_amount ?? '0.00',
                'tax_rate'                 => $currentPlan->tax_rate ?? '0.00',
                'total_amount'             => $currentPlan->total_amount ?? '0.00',
                'subscription_start_date'  =>  date('d-m-Y', strtotime($currentPlan->subscription_start_date)),
                'subscription_end_date'    =>  date('d-m-Y', strtotime($currentPlan->subscription_end_date)),
                'promo_code'               => $currentPlan->promo_code ?? null,
                'created_at'               => $currentPlan->created_at ?? null,
                'updated_at'               => $currentPlan->updated_at ?? null,
                'item_name'                => $currentPlan->item_name ?? '',
            ] : [];

            $plans = [];
            $itemArr = [
                'cart_id'                   => $item->id ?? null,
                'main_cart_id'              => (int) $cart->id,
                'provider_in_cart'          => $plan->provider_id,
                'provider_id'               => $plan->provider_id,
                'company_name'              => $companyName,
                'plan_name'                 => $plan->name ?? '',
                'licenses'                  => $licenses,
                'customer_id'               => $customerId,
                'type'                      => $cart->type ?? Cart::TYPE_DOWNGRADE,
                'unit_price'                => (float) $item->unit_price,
                'subtotal'                  => round((float) ($cart->subtotal ?? $calculation['new_plan_cost'] ?? 0), 2),
                'new_plan_cost'             => round((float) ($calculation['new_plan_cost'] ?? $cart->subtotal ?? 0), 2),
                'remaining_credit'          => round((float) ($calculation['remaining_credit'] ?? $cart->pro_rata_adjustment ?? 0), 2),
                'remaining_value'           => round((float) ($calculation['remaining_value'] ?? $cart->pro_rata_adjustment ?? 0), 2),
                'pro_rata_adjustment'       => round((float) ($calculation['pro_rata_adjustment'] ?? $cart->pro_rata_adjustment ?? 0), 2),
                'applied_pro_rata'          => round((float) ($calculation['applied_pro_rata'] ?? 0), 2),
                'credit_licenses'           => (int) ($calculation['credit_licenses'] ?? 0),
                'current_licenses'          => (int) ($calculation['current_licenses'] ?? 0),
                'wallet_credit'             => round((float) ($calculation['wallet_credit'] ?? 0), 2),
                'remaining_days'            => (int) ($calculation['remaining_days'] ?? 0),
                'final_payable'             => round((float) ($calculation['final_payable'] ?? $cart->grand_total ?? 0), 2),
                'taxable_amount'            => round((float) ($calculation['taxable_amount'] ?? 0), 2),
                'price_after_discount'      => round((float) ($calculation['taxable_amount'] ?? 0), 2),
                'coupon_code'               => $cart->coupen ?? null,
                'coupon_discount_percent'   => round((float) $couponPercent),
                'gst_percentage'            => $cart->gst_percentage ?? 18,
                'gst_amount'                => round((float) ($calculation['gst_amount'] ?? $cart->gst_amount ?? 0), 2),
                'discount_amount'           => (float) ($cart->discount_amount ?? 0),
                'grand_total'               => (float) ($cart->grand_total ?? 0),
                'domain_name'               => !empty($domainName) ? $domainName : ($cart->domain_name ?? null),
                'subscription_start_date'   =>  date('d-m-Y', strtotime($subscriptionStartDate)),
                'subscription_end_date'       =>  date('d-m-Y', strtotime($subscriptionEndDate)),
                'created_at'                => $item->created_at ?? null,
                'updated_at'                => $item->updated_at ?? null,
            ];
            $plans[] = $itemArr;

            $partner = Partner::find($partnerId);
            $walletBalance = $partner
                ? (string) round(PartnerCreditService::remainingPurchaseAllowance((int) $partnerId), 2)
                : '0.00';
            $sourcePo = $this->resolveParentOrderPoPayload((int) ($subscriptionOrderId ?? $cart->order_id ?? $validated['order_id'] ?? 0));

            return response()->json([
                'success' => true,
                'wallet_balance' => $walletBalance,
                'data' => [
                    'currentplandetails' => $currentPlanDetailsArr,
                    'plans' => $plans,
                    'main_cart_id' => (int) $cart->id,
                    'remaining_credit' => round((float) ($calculation['remaining_credit'] ?? 0), 2),
                    'remaining_value' => round((float) ($calculation['remaining_value'] ?? 0), 2),
                    'applied_pro_rata' => round((float) ($calculation['applied_pro_rata'] ?? 0), 2),
                    'credit_licenses' => (int) ($calculation['credit_licenses'] ?? 0),
                    'current_licenses' => (int) ($calculation['current_licenses'] ?? 0),
                    'new_plan_cost' => round((float) ($calculation['new_plan_cost'] ?? 0), 2),
                    'taxable_amount' => round((float) ($calculation['taxable_amount'] ?? 0), 2),
                    'gst_amount' => round((float) ($calculation['gst_amount'] ?? 0), 2),
                    'final_payable' => round((float) ($calculation['final_payable'] ?? $cart->grand_total ?? 0), 2),
                    'wallet_credit' => round((float) ($calculation['wallet_credit'] ?? 0), 2),
                    'remaining_days' => (int) ($calculation['remaining_days'] ?? 0),
                    'po' => $sourcePo,
                    'po_link' => $sourcePo['po_link'] ?? null,
                    'po_mode' => $sourcePo['po_mode'] ?? 'generated',
                    'po_number' => $sourcePo['po_number'] ?? '',
                    'final_po_link' => $sourcePo['final_po_link'] ?? null,
                    'is_uploaded_po' => (bool) ($sourcePo['is_uploaded'] ?? false),
                ],
            ]);
        } catch (\Illuminate\Validation\ValidationException $e) {
            return response()->json([
                'success' => false,
                'message' => 'Validation failed',
                'errors'  => $e->errors(),
            ], 422);
        } catch (\Throwable $e) {
            return response()->json([
                'success' => false,
                'message' => 'An error occurred while processing downgrade cart',
                'error'   => $e->getMessage(),
            ], 500);
        }
    }

    public function CartDetails(Request $request)
    {
        $validated = $request->validate([
            'partner_id' => 'required|exists:pgsql_auth.partners,id',
            'cart_id'    => 'nullable|integer|exists:pgsql_billing.carts,id',
        ]);

        $partnerId = (int) $validated['partner_id'];
        $partner = Partner::find($partnerId);
        $walletBalance = round(PartnerCreditService::remainingPurchaseAllowance($partnerId), 2);
        $signRequired = strtolower(trim((string) ($partner->aadhaar_mandatory ?? 'no'))) === 'yes';

        $cartService = app(PartnerCartService::class);
        $payableAmount = 0.0;

        // --- GET PROCESSING ORDERS FOR CREDIT CHECK (Provider Independent) ---
        $processingOrdersAmount = 0;
        $processingOrdersCount = 0;
        try {
            $processingOrders = Order::query()
                ->where('partner_id', $partnerId)
                ->where('order_type', 'b2b')
                ->whereIn('status', ['processing', 'pending', 'waiting'])
                ->get();

            $processingOrdersCount = $processingOrders->count();
            foreach ($processingOrders as $order) {
                $amount = round((float) ($order->total_amount ?? $order->subtotal ?? 0), 2);
                $processingOrdersAmount += $amount;
            }
        } catch (\Throwable $e) {
            Log::warning('Failed to fetch processing orders for credit check', [
                'partner_id' => $partnerId,
                'error' => $e->getMessage(),
            ]);
        }

        // --- CREDIT CALCULATIONS ---
        $creditLimit = round((float) ($partner->credit_limit ?? 0), 2);
        $creditUsedTotal = round(PartnerCreditService::summarizeUsedCredit((int) $partnerId), 2);
        $remainingLimit = round(PartnerCreditService::remainingPurchaseAllowance((int) $partnerId), 2);
        $creditLimitReached = PartnerCreditService::isCreditLimitFullyUsed((int) $partnerId);

        // --- CREDIT LOCKED BY PROCESSING ORDERS (Provider Independent) ---
        $creditLockedByProcessing = false;
        $creditLockedMessage = null;
        $availableCreditForPurchase = $remainingLimit;

        if ($processingOrdersAmount > 0 && $processingOrdersAmount > $availableCreditForPurchase) {
            $creditLockedByProcessing = true;
            $creditLockedMessage = '₹' . number_format($processingOrdersAmount, 2) . ' worth of orders are in processing state. Available credit: ₹' . number_format($availableCreditForPurchase, 2);
        } elseif ($processingOrdersAmount > 0 && $availableCreditForPurchase <= 0) {
            $creditLockedByProcessing = true;
            $creditLockedMessage = 'Credit balance is fully utilized by ' . $processingOrdersCount . ' processing order(s).';
        } elseif ($processingOrdersAmount > 0 && $creditLimitReached) {
            $creditLockedByProcessing = true;
            $creditLockedMessage = 'Credit limit is fully used by ' . $processingOrdersCount . ' processing order(s).';
        } elseif ($processingOrdersAmount > 0 && $availableCreditForPurchase > 0 && $availableCreditForPurchase >= $processingOrdersAmount) {
            $creditLockedByProcessing = false;
            $creditLockedMessage = null;
        } else {
            $creditLockedByProcessing = false;
            $creditLockedMessage = null;
        }

        if (!empty($validated['cart_id'])) {
            $cart = Cart::with(['items', 'partner', 'customer'])->find((int)$validated['cart_id']);
            if (!$cart || $cart->partner_id != $partnerId) {
                return response()->json([
                    'success' => false,
                    'message' => 'Cart not found for this partner.',
                    'data' => null,
                    'wallet_balance' => $walletBalance,
                    'sign_required' => $signRequired ? 'yes' : 'no',
                    'draft_cart' => false,
                    // --- CREDIT KEYS ---
                    'credit_limit' => $creditLimit,
                    'credit_used' => $creditUsedTotal,
                    'remaining_credit_limit' => $remainingLimit,
                    'credit_limit_reached' => $creditLimitReached,
                    'credit_applicable' => true,
                    'is_credit_applicable' => true,
                    'credit_blocked' => $creditLockedByProcessing,
                    'credit_block_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
                    'credit_zero_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
                    'processing_orders_amount' => round($processingOrdersAmount, 2),
                    'processing_orders_count' => $processingOrdersCount,
                    'credit_locked_by_processing_orders' => $creditLockedByProcessing,
                    'credit_lock_message' => $creditLockedMessage,
                    'available_credit_for_purchase' => round($availableCreditForPurchase, 2),
                    'can_purchase' => !$creditLimitReached,
                    'purchase_block_message' => $creditLockedByProcessing ? $creditLockedMessage : 'Sufficient credit allocation available to complete this purchase',
                ], 404);
            }

            $cartData = $cartService->formatCartWithItemsResponse($cart, $partner);
            $domainNameArray = $cartService->cartDomainNameToArray($cart);
            $cartData['domain_name'] = $domainNameArray;
            if (is_array($cartData['items'] ?? null)) {
                foreach ($cartData['items'] as $i => $itemRow) {
                    if (is_array($itemRow)) {
                        $cartData['items'][$i]['domain_name'] = $domainNameArray;
                    }
                }
            }

            // Add coupen code to response if exists
            $cartData['coupen'] = isset($cart->coupen) ? $cart->coupen : null;

            $payableAmount = round((float) ($cart->grand_total ?? 0), 2);
            if ($payableAmount <= 0.005 && $cart->items->isNotEmpty()) {
                $pricing = $cartService->buildCartDeductionSummary($cart);
                $payableAmount = round((float) ($pricing['grand_total'] ?? 0), 2);
            }

            // --- CALCULATE CAN PURCHASE ---
            $canPurchase = false;
            if (!$creditLimitReached) {
                if ($payableAmount <= 0.005) {
                    $canPurchase = true;
                } elseif ($payableAmount <= $availableCreditForPurchase) {
                    $canPurchase = true;
                } elseif ($creditLockedByProcessing && $payableAmount <= ($availableCreditForPurchase + $processingOrdersAmount)) {
                    $canPurchase = true;
                }
            }

            // --- BUILD PURCHASE BLOCK MESSAGE ---
            $purchaseBlockMessage = null;
            if ($creditLockedByProcessing) {
                $purchaseBlockMessage = 'Credit is locked because ₹' . number_format($processingOrdersAmount, 2) . ' worth of orders are in processing state. Available credit: ₹' . number_format($availableCreditForPurchase, 2);
            } elseif ($creditLimitReached) {
                $purchaseBlockMessage = 'Credit limit reached. You cannot buy additional items.';
            } elseif (!$canPurchase && $payableAmount > $availableCreditForPurchase) {
                $purchaseBlockMessage = 'Insufficient credit. Required: ₹' . number_format($payableAmount, 2) . ', Available: ₹' . number_format($availableCreditForPurchase, 2);
            } else {
                $purchaseBlockMessage = 'Sufficient credit allocation available to complete this purchase';
            }

            $creditDetails = [
                'credit_limit' => $creditLimit,
                'credit_used' => $creditUsedTotal,
                'remaining_credit_limit' => $remainingLimit,
                'credit_limit_reached' => $creditLimitReached,
                'can_purchase' => $canPurchase,
                'purchase_block_message' => $purchaseBlockMessage,
                'credit_applicable' => true,
                'credit_zero_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
                'is_credit_applicable' => true,
                'credit_blocked' => $creditLockedByProcessing,
                'credit_block_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
                'processing_orders_amount' => round($processingOrdersAmount, 2),
                'processing_orders_count' => $processingOrdersCount,
                'credit_locked_by_processing_orders' => $creditLockedByProcessing,
                'credit_lock_message' => $creditLockedMessage,
                'available_credit_for_purchase' => round($availableCreditForPurchase, 2),
            ];

            $this->clearSuccessfulPurchaseDraftState($partnerId, $cart);
            $cart = Cart::query()
                ->with(['items.plan', 'customer'])
                ->whereKey((int) $cart->id)
                ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) = 'active'")
                ->first();
            if (!$cart) {
                return response()->json([
                    'success' => true,
                    'message' => 'Partner cart details fetched successfully.',
                    'data' => null,
                    'wallet_balance' => $walletBalance,
                    'sign_required' => $signRequired ? 'yes' : 'no',
                    'draft_cart' => false,
                    'draft_order' => null,
                    'aadhaar_pending' => false,
                    'license_count' => 0,
                    // --- CREDIT KEYS ---
                    'credit_limit' => $creditLimit,
                    'credit_used' => $creditUsedTotal,
                    'remaining_credit_limit' => $remainingLimit,
                    'credit_limit_reached' => $creditLimitReached,
                    'can_purchase' => $canPurchase,
                    'purchase_block_message' => $purchaseBlockMessage,
                    'credit_applicable' => true,
                    'credit_zero_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
                    'is_credit_applicable' => true,
                    'credit_blocked' => $creditLockedByProcessing,
                    'credit_block_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
                    'processing_orders_amount' => round($processingOrdersAmount, 2),
                    'processing_orders_count' => $processingOrdersCount,
                    'credit_locked_by_processing_orders' => $creditLockedByProcessing,
                    'credit_lock_message' => $creditLockedMessage,
                    'available_credit_for_purchase' => round($availableCreditForPurchase, 2),
                ]);
            }
            $draftFlags = $this->syncedDraftFlags(
                $this->resolveDraftOrderForCart($partnerId, $cart),
                $signRequired,
                (int) $cart->id
            );
            $draftCart = (bool) $draftFlags['draft_cart'];
            $draftOrder = $draftFlags['draft_order'];
            $licenseCount = $this->resolveCartLicenseCount($cart);
            $cartData = array_merge($cartData, $creditDetails, $draftFlags, [
                'sign_required' => $signRequired ? 'yes' : 'no',
                'license_count' => $licenseCount,
            ]);

            return response()->json(array_merge([
                'success' => true,
                'message' => $draftCart
                    ? 'Draft order saved. Complete Aadhaar verification to place the order.'
                    : 'Partner cart details fetched successfully.',
                'data' => $cartData,
                'domain_name' => $domainNameArray,
                'wallet_balance' => $walletBalance,
                'sign_required' => $signRequired ? 'yes' : 'no',
                'license_count' => $licenseCount,
                // --- CREDIT KEYS ---
                'credit_limit' => $creditLimit,
                'credit_used' => $creditUsedTotal,
                'remaining_credit_limit' => $remainingLimit,
                'credit_limit_reached' => $creditLimitReached,
                'can_purchase' => $canPurchase,
                'purchase_block_message' => $purchaseBlockMessage,
                'credit_applicable' => true,
                'credit_zero_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
                'is_credit_applicable' => true,
                'credit_blocked' => $creditLockedByProcessing,
                'credit_block_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
                'processing_orders_amount' => round($processingOrdersAmount, 2),
                'processing_orders_count' => $processingOrdersCount,
                'credit_locked_by_processing_orders' => $creditLockedByProcessing,
                'credit_lock_message' => $creditLockedMessage,
                'available_credit_for_purchase' => round($availableCreditForPurchase, 2),
            ], $draftFlags));
        }

        $cart = $this->findActiveDraftCartForPartner($partnerId)
            ?? $cartService->getActiveCartWithItems($partnerId, Cart::TYPE_STANDARD);

        if ($cart) {
            $this->clearSuccessfulPurchaseDraftState($partnerId, $cart);
            $this->syncDraftOrdersWithCartPlans($partnerId, $cart);
            $cart = Cart::query()
                ->with(['items.plan', 'customer'])
                ->whereKey((int) $cart->id)
                ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) = 'active'")
                ->first();
        }

        $cartData = collect();
        if ($cart && $cart->items->isNotEmpty()) {
            if (strtolower(trim((string) ($cart->type ?? ''))) === Cart::TYPE_STANDARD) {
                $cartData = collect($cartService->formatStandardCartDetails($cart, (float) $walletBalance));
            } else {
                $formattedCart = $cartService->formatCartWithItemsResponse($cart, $partner);
                $itemRows = is_array($formattedCart['items'] ?? null) ? $formattedCart['items'] : [];
                $cartData = collect($itemRows)->values();
            }
        }

        // For standard details, get domain_name from the carts table and explode if needed
        $domainNameArray = $cart ? $cartService->cartDomainNameToArray($cart) : [];
        $coupen = null;
        if ($cart) {
            $coupen = isset($cart->coupen) ? $cart->coupen : null;
        }

        // Assign to every item (if you want it on each item in the array)
        if ($cart && $cart->items->isNotEmpty()) {
            $pricing = $cartService->buildCartDeductionSummary($cart);
            $payableAmount = round((float) ($pricing['grand_total'] ?? $cart->grand_total ?? 0), 2);
        }

        // --- CALCULATE CAN PURCHASE ---
        $canPurchase = false;
        if (!$creditLimitReached) {
            if ($payableAmount <= 0.005) {
                $canPurchase = true;
            } elseif ($payableAmount <= $availableCreditForPurchase) {
                $canPurchase = true;
            } elseif ($creditLockedByProcessing && $payableAmount <= ($availableCreditForPurchase + $processingOrdersAmount)) {
                $canPurchase = true;
            }
        }

        // --- BUILD PURCHASE BLOCK MESSAGE ---
        $purchaseBlockMessage = null;
        if ($creditLockedByProcessing) {
            $purchaseBlockMessage = 'Credit is locked because ₹' . number_format($processingOrdersAmount, 2) . ' worth of orders are in processing state. Available credit: ₹' . number_format($availableCreditForPurchase, 2);
        } elseif ($creditLimitReached) {
            $purchaseBlockMessage = 'Credit limit reached. You cannot buy additional items.';
        } elseif (!$canPurchase && $payableAmount > $availableCreditForPurchase) {
            $purchaseBlockMessage = 'Insufficient credit. Required: ₹' . number_format($payableAmount, 2) . ', Available: ₹' . number_format($availableCreditForPurchase, 2);
        } else {
            $purchaseBlockMessage = 'Sufficient credit allocation available to complete this purchase';
        }

        $creditDetails = [
            'credit_limit' => $creditLimit,
            'credit_used' => $creditUsedTotal,
            'remaining_credit_limit' => $remainingLimit,
            'credit_limit_reached' => $creditLimitReached,
            'can_purchase' => $canPurchase,
            'purchase_block_message' => $purchaseBlockMessage,
            'credit_applicable' => true,
            'credit_zero_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
            'is_credit_applicable' => true,
            'credit_blocked' => $creditLockedByProcessing,
            'credit_block_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
            'processing_orders_amount' => round($processingOrdersAmount, 2),
            'processing_orders_count' => $processingOrdersCount,
            'credit_locked_by_processing_orders' => $creditLockedByProcessing,
            'credit_lock_message' => $creditLockedMessage,
            'available_credit_for_purchase' => round($availableCreditForPurchase, 2),
        ];

        $draftOrder = $cart ? $this->resolveDraftOrderForCart($partnerId, $cart) : null;
        $cartIdForFlags = $cart ? (int) $cart->id : 0;
        $topFlags = $this->syncedDraftFlags($draftOrder, $signRequired, $cartIdForFlags);
        $draftCart = (bool) $topFlags['draft_cart'];
        $draftPlanIds = $cart
            ? $this->resolveAllDraftPlanIdsForCart($partnerId, $cart)
            : $this->resolveDraftPlanIds($draftOrder);
        $draftOrdersByPlan = $cart
            ? $this->resolveDraftOrdersByPlanId($partnerId, $cart)
            : [];
        $licenseCount = $this->resolveCartLicenseCount($cart);

        $cartData = $cartData->map(function ($item) use (
            $domainNameArray,
            $coupen,
            $creditDetails,
            $signRequired,
            $draftOrder,
            $draftPlanIds,
            $draftOrdersByPlan,
            $licenseCount,
            $cartIdForFlags
        ) {
            $planId = (int) ($item['plan_id'] ?? 0);
            $planDraftOrder = $draftOrdersByPlan[$planId] ?? $draftOrder;
            $itemFlags = $this->draftFlagsForPlan($planId, $planDraftOrder, $signRequired, $draftPlanIds, $cartIdForFlags);
            $item['domain_name'] = $domainNameArray;
            $item['coupon_code'] = strtoupper($coupen);
            // --- CREDIT KEYS PER ITEM ---
            $item['credit_limit'] = $creditDetails['credit_limit'];
            $item['credit_used'] = $creditDetails['credit_used'];
            $item['remaining_credit_limit'] = $creditDetails['remaining_credit_limit'];
            $item['credit_limit_reached'] = $creditDetails['credit_limit_reached'];
            $item['can_purchase'] = $creditDetails['can_purchase'];
            $item['purchase_block_message'] = $creditDetails['purchase_block_message'];
            $item['credit_applicable'] = $creditDetails['credit_applicable'];
            $item['credit_zero_reason'] = $creditDetails['credit_zero_reason'];
            $item['is_credit_applicable'] = $creditDetails['is_credit_applicable'];
            $item['credit_blocked'] = $creditDetails['credit_blocked'];
            $item['credit_block_reason'] = $creditDetails['credit_block_reason'];
            $item['processing_orders_amount'] = $creditDetails['processing_orders_amount'];
            $item['processing_orders_count'] = $creditDetails['processing_orders_count'];
            $item['credit_locked_by_processing_orders'] = $creditDetails['credit_locked_by_processing_orders'];
            $item['credit_lock_message'] = $creditDetails['credit_lock_message'];
            $item['available_credit_for_purchase'] = $creditDetails['available_credit_for_purchase'];
            $item['sign_required'] = $signRequired ? 'yes' : 'no';
            $item['draft_cart'] = false;
            $item['aadhaar_pending'] = $itemFlags['aadhaar_pending'];
            $item['draft_order'] = $itemFlags['draft_order'];
            $item['license_count'] = isset($item['licenses'])
                ? (int) $item['licenses']
                : $licenseCount;
            return $item;
        });

        // Purchased / empty cart → never keep draft flags.
        if (!$cart || $cartData->isEmpty()) {
            $topFlags = $this->syncedDraftFlags(null, $signRequired, 0);
            $draftCart = false;
            $licenseCount = 0;
        }

        if ($cartData->isEmpty() && $partnerId > 0 && PartnerCreditService::isCreditLimitFullyUsed($partnerId)) {
            return response()->json([
                'success' => false,
                'message' => 'Credit limit reached. You cannot buy items.',
                'code' => 'credit_limit_reached',
                'data' => $this->partnerB2bWalletInfo($partnerId, 0),
                'wallet_balance' => $walletBalance,
                'sign_required' => $signRequired ? 'yes' : 'no',
                'draft_cart' => false,
                'draft_order' => null,
                'aadhaar_pending' => false,
                'license_count' => 0,
                // --- CREDIT KEYS ---
                'credit_limit' => $creditLimit,
                'credit_used' => $creditUsedTotal,
                'remaining_credit_limit' => $remainingLimit,
                'credit_limit_reached' => $creditLimitReached,
                'can_purchase' => false,
                'purchase_block_message' => $creditLockedByProcessing ? $creditLockedMessage : 'Credit limit reached. You cannot buy additional items.',
                'credit_applicable' => true,
                'credit_zero_reason' => $creditLockedByProcessing ? $creditLockedMessage : 'Credit limit reached.',
                'is_credit_applicable' => true,
                'credit_blocked' => $creditLockedByProcessing,
                'credit_block_reason' => $creditLockedByProcessing ? $creditLockedMessage : 'Credit limit reached.',
                'processing_orders_amount' => round($processingOrdersAmount, 2),
                'processing_orders_count' => $processingOrdersCount,
                'credit_locked_by_processing_orders' => $creditLockedByProcessing,
                'credit_lock_message' => $creditLockedMessage,
                'available_credit_for_purchase' => round($availableCreditForPurchase, 2),
            ], 422);
        }

        return response()->json(array_merge([
            'success' => true,
            'message' => $draftCart
                ? 'Draft order saved. Complete Aadhaar verification to place the order.'
                : ($cartData->isEmpty()
                    ? 'No cart records found for the given partner.'
                    : 'Partner cart details fetched successfully.'),
            'data' => $cartData,
            'domain_name' => $domainNameArray,
            'wallet_balance' => $walletBalance,
            'sign_required' => $signRequired ? 'yes' : 'no',
            'license_count' => $licenseCount,
            // --- CREDIT KEYS TOP LEVEL ---
            'credit_limit' => $creditLimit,
            'credit_used' => $creditUsedTotal,
            'remaining_credit_limit' => $remainingLimit,
            'credit_limit_reached' => $creditLimitReached,
            'can_purchase' => $canPurchase,
            'purchase_block_message' => $purchaseBlockMessage,
            'credit_applicable' => true,
            'credit_zero_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
            'is_credit_applicable' => true,
            'credit_blocked' => $creditLockedByProcessing,
            'credit_block_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
            'processing_orders_amount' => round($processingOrdersAmount, 2),
            'processing_orders_count' => $processingOrdersCount,
            'credit_locked_by_processing_orders' => $creditLockedByProcessing,
            'credit_lock_message' => $creditLockedMessage,
            'available_credit_for_purchase' => round($availableCreditForPurchase, 2),
        ], $topFlags));
    }

    /**
     * Addon API: request order_id â†’ response shaped like getCartDetails for that order.
     *
     * POST body: { "order_id": 123, "partner_id": 1 (optional) }
     */
    public function addon(Request $request)
    {
        $validated = $request->validate([
            'order_id' => 'required|integer|exists:pgsql_billing.orders,id',
            'partner_id' => 'nullable|integer|exists:pgsql_auth.partners,id',
        ]);

        $orderId = (int) $validated['order_id'];
        $order = Order::query()->with(['plan', 'customer'])->find($orderId);
        if (!$order) {
            return response()->json([
                'success' => false,
                'message' => 'Order not found.',
                'data' => [],
            ], 404);
        }

        $partnerId = (int) ($validated['partner_id'] ?? $order->partner_id ?? 0);
        if ($partnerId <= 0) {
            return response()->json([
                'success' => false,
                'message' => 'partner_id is required.',
                'data' => [],
            ], 422);
        }

        if ((int) ($order->partner_id ?? 0) !== $partnerId) {
            return response()->json([
                'success' => false,
                'message' => 'Order does not belong to this partner.',
                'data' => [],
            ], 403);
        }

        $partner = Partner::find($partnerId);
        $walletBalance = round(PartnerCreditService::remainingPurchaseAllowance($partnerId), 2);
        $signRequired = strtolower(trim((string) ($partner->aadhaar_mandatory ?? 'no'))) === 'yes';

        $customer = Customer::query()->find((int) ($order->user_id ?? 0));
        $gstPercentage = (float) ($order->gst_rate ?? $order->gst_percentage ?? 18);
        if ($gstPercentage <= 0) {
            $gstPercentage = 18.0;
        }

        $orderItems = OrderItem::query()
            ->where('order_id', $orderId)
            ->where(function ($q) {
                $q->whereNull('status')
                    ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted')");
            })
            ->orderBy('id')
            ->get();
        $orderItems = $this->uniqueSubscriptionOrderItems($orderItems);

        $domainNameArray = [];
        $domainRaw = $order->domain_name ?? '';
        if (is_array($domainRaw)) {
            $domainNameArray = array_values(array_filter(array_map('trim', $domainRaw)));
        } elseif (is_string($domainRaw) && trim($domainRaw) !== '') {
            $domainNameArray = array_values(array_filter(array_map('trim', explode(',', $domainRaw))));
        }

        $cartData = collect();
        $licenseCount = 0;
        $subtotal = 0.0;

        foreach ($orderItems as $item) {
            $plan = Plan::query()->find((int) ($item->plan_id ?? $order->plan_id ?? 0));
            $licenses = max(1, (int) ($item->quantity ?? $order->quantity ?? 1));
            $unitPrice = round((float) ($item->unit_price ?? optional($plan)->price ?? $order->price ?? 0), 2);
            if ($unitPrice <= 0 && (float) ($item->total_amount ?? 0) > 0) {
                $unitPrice = round(((float) $item->total_amount) / $licenses, 2);
            }
            $lineTotal = round((float) ($item->total_amount ?? ($unitPrice * $licenses)), 2);
            if ($lineTotal <= 0) {
                $lineTotal = round($unitPrice * $licenses, 2);
            }

            $licenseCount += $licenses;
            $subtotal += $lineTotal;

            $startDate = $item->subscription_start_date ?? $order->subscription_start_date;
            $endDate = $item->subscription_end_date ?? $order->subscription_end_date;

            $cartData->push([
                'order_id' => $orderId,
                'order_no' => (string) ($order->order_no ?? ''),
                'order_sub_id' => (int) $item->id,
                'item_id' => (int) $item->id,
                'cart_id' => null,
                'main_cart_id' => null,
                'partner_id' => $partnerId,
                'customer_id' => (int) ($order->user_id ?? 0),
                'company_name' => $customer->company_name ?? null,
                'plan_id' => (int) (optional($plan)->id ?? $item->plan_id ?? 0),
                'plan_name' => (string) (optional($plan)->name ?? $item->item_name ?? ''),
                'plan' => $plan ? $plan->toArray() : null,
                'provider_id' => optional($plan)->provider_id ?? null,
                'licenses' => $licenses,
                'license_count' => $licenses,
                'price_per_unit' => $unitPrice,
                'unit_price' => $unitPrice,
                'subtotal' => $lineTotal,
                'total_amount' => $lineTotal,
                'discount' => round((float) ($item->discount_amount ?? 0), 2),
                'discount_amount' => round((float) ($item->discount_amount ?? 0), 2),
                'tax_percentage' => round($gstPercentage, 2),
                'tax_amount' => round((float) ($item->tax_amount ?? 0), 2),
                'domain_name' => $domainNameArray,
                'transfer_domain' => $order->transfer_domain ?? null,
                'status' => strtolower(trim((string) ($item->status ?? $order->status ?? 'active'))),
                'coupon_code' => strtoupper((string) ($order->promo_code ?? '')),
                'start_date' => $startDate ? date('d-m-Y', strtotime((string) $startDate)) : null,
                'end_date' => $endDate ? date('d-m-Y', strtotime((string) $endDate)) : null,
                'created_at' => $order->created_at ? date('d-m-Y', strtotime((string) $order->created_at)) : null,
                'updated_at' => $order->updated_at ? date('Y-m-d', strtotime((string) $order->updated_at)) : null,
                'is_active' => true,
                'type' => 'addon',
            ]);
        }

        // Fallback: order header only when no order items.
        if ($cartData->isEmpty()) {
            $plan = Plan::query()->find((int) ($order->plan_id ?? 0));
            $licenses = max(1, (int) ($order->quantity ?? 1));
            $unitPrice = round((float) (optional($plan)->price ?? $order->price ?? 0), 2);
            $lineTotal = round((float) ($order->subtotal ?? ($unitPrice * $licenses)), 2);
            $licenseCount = $licenses;
            $subtotal = $lineTotal;

            $cartData->push([
                'order_id' => $orderId,
                'order_no' => (string) ($order->order_no ?? ''),
                'order_sub_id' => null,
                'item_id' => null,
                'cart_id' => null,
                'main_cart_id' => null,
                'partner_id' => $partnerId,
                'customer_id' => (int) ($order->user_id ?? 0),
                'company_name' => $customer->company_name ?? null,
                'plan_id' => (int) (optional($plan)->id ?? $order->plan_id ?? 0),
                'plan_name' => (string) (optional($plan)->name ?? ''),
                'plan' => $plan ? $plan->toArray() : null,
                'provider_id' => optional($plan)->provider_id ?? null,
                'licenses' => $licenses,
                'license_count' => $licenses,
                'price_per_unit' => $unitPrice,
                'unit_price' => $unitPrice,
                'subtotal' => $lineTotal,
                'total_amount' => $lineTotal,
                'discount' => round((float) ($order->discount_amount ?? 0), 2),
                'discount_amount' => round((float) ($order->discount_amount ?? 0), 2),
                'tax_percentage' => round($gstPercentage, 2),
                'tax_amount' => round((float) ($order->gst_amount ?? $order->tax_amount ?? 0), 2),
                'domain_name' => $domainNameArray,
                'transfer_domain' => $order->transfer_domain ?? null,
                'status' => strtolower(trim((string) ($order->status ?? 'active'))),
                'coupon_code' => strtoupper((string) ($order->promo_code ?? '')),
                'start_date' => $order->subscription_start_date
                    ? date('d-m-Y', strtotime((string) $order->subscription_start_date))
                    : null,
                'end_date' => $order->subscription_end_date
                    ? date('d-m-Y', strtotime((string) $order->subscription_end_date))
                    : null,
                'created_at' => $order->created_at ? date('d-m-Y', strtotime((string) $order->created_at)) : null,
                'updated_at' => $order->updated_at ? date('Y-m-d', strtotime((string) $order->updated_at)) : null,
                'is_active' => true,
                'type' => 'addon',
            ]);
        }

        $discountAmount = round((float) ($order->discount_amount ?? 0), 2);
        $taxable = max(0, round($subtotal - $discountAmount, 2));
        $gstAmount = round((float) ($order->gst_amount ?? $order->tax_amount ?? 0), 2);
        if ($gstAmount <= 0 && $taxable > 0 && $gstPercentage > 0) {
            $gstAmount = round(($taxable * $gstPercentage) / 100, 2);
        }
        $grandTotal = round((float) ($order->total_amount ?? ($taxable + $gstAmount)), 2);
        if ($grandTotal <= 0) {
            $grandTotal = round($taxable + $gstAmount, 2);
        }

        $creditDetails = $this->partnerB2bCreditSummary($partnerId, $grandTotal);

        $cartData = $cartData->map(function ($item) use ($creditDetails, $signRequired, $walletBalance) {
            $item['credit_limit'] = $creditDetails['credit_limit'];
            $item['credit_used'] = $creditDetails['credit_used'];
            $item['remaining_credit_limit'] = $creditDetails['remaining_credit_limit'];
            $item['credit_limit_reached'] = $creditDetails['credit_limit_reached'];
            $item['can_purchase'] = $creditDetails['can_purchase'];
            $item['sign_required'] = $signRequired ? 'yes' : 'no';
            $item['draft_cart'] = false;
            $item['wallet_balance'] = $walletBalance;
            return $item;
        });

        return response()->json([
            'success' => true,
            'message' => $cartData->isEmpty()
                ? 'No addon cart details found for this order.'
                : 'Addon cart details fetched successfully.',
            'data' => $cartData->values(),
            'order_id' => $orderId,
            'order_no' => (string) ($order->order_no ?? ''),
            'wallet_balance' => $walletBalance,
            'sign_required' => $signRequired ? 'yes' : 'no',
            'draft_cart' => false,
            'license_count' => $licenseCount,
            'subtotal' => round($subtotal, 2),
            'discount_amount' => $discountAmount,
            'gst_percentage' => round($gstPercentage, 2),
            'gst_amount' => $gstAmount,
            'grand_total' => $grandTotal,
            'credit_limit' => $creditDetails['credit_limit'],
            'credit_used' => $creditDetails['credit_used'],
            'remaining_credit_limit' => $creditDetails['remaining_credit_limit'],
            'credit_limit_reached' => $creditDetails['credit_limit_reached'],
            'can_purchase' => $creditDetails['can_purchase'],
            'purchase_block_message' => $creditDetails['purchase_block_message'] ?? null,
        ]);
    }

    /**
     * Total licenses across all cart lines (add/update cart â†’ CartDetails).
     */
    private function resolveCartLicenseCount($cart): int
    {
        if (!$cart) {
            return 0;
        }

        $cartId = (int) ($cart->id ?? 0);
        if ($cartId > 0) {
            return (int) CartItem::query()
                ->where('cart_id', $cartId)
                ->sum('licenses');
        }

        $items = $cart->relationLoaded('items')
            ? $cart->items
            : collect();

        return (int) collect($items)->sum(function ($item) {
            return max(0, (int) ($item->licenses ?? 0));
        });
    }

    /**
     * draft_cart and draft_order must always match at cart level:
     * - draft / place-pending â†’ draft_cart true + draft_order null (temp PND in cart)
     * - no draft â†’ draft_cart false + draft_order null
     *
     * @return array{draft_cart: bool, draft_order: ?array, aadhaar_pending: bool}
     */
    private function syncedDraftFlags(?array $draftOrder, bool $signRequired = true, int $cartId = 0): array
    {
        // Cart-only place pending (temp PND + PO) â€” eSign no longer required.
        if ($cartId > 0 && app(PartnerCartService::class)->isCartPendingAadhaar($cartId)) {
            $cartService = app(PartnerCartService::class);
            $poMeta = $cartService->getCartPoMeta($cartId);
            $cartRow = Cart::query()->whereKey($cartId)->first();
            $partnerIdForRef = (int) ($cartRow->partner_id ?? 0);
            $pendingRef = $partnerIdForRef > 0
                ? $cartService->issueCartPendingEsignRef($cartId, $partnerIdForRef)
                : null;

            return [
                'draft_cart' => false,
                'draft_order' => null,
                'aadhaar_pending' => false,
                'place_order_required' => true,
                'order_id' => $cartId,
                'po_link' => $poMeta['po_link'] ?? null,
                'po_number' => $poMeta['po_number'] ?? null,
                'ordId' => $cartId,
                'pending_ref_id' => $pendingRef,
                'order_no' => $pendingRef,
                'temp_order_no' => $pendingRef,
                'is_temp_order' => true,
                'real_order' => false,
                'status' => 'pending_place',
                'cart_id' => $cartId,
            ];
        }

        if (!empty($draftOrder) && !empty($draftOrder['order_id'])) {
            return [
                'draft_cart' => true,
                'draft_order' => $draftOrder,
                'aadhaar_pending' => $signRequired,
                'order_id' => (int) $draftOrder['order_id'],
                'ordId' => (int) $draftOrder['order_id'],
            ];
        }

        return [
            'draft_cart' => false,
            'draft_order' => null,
            'aadhaar_pending' => false,
            'order_id' => 0,
            'ordId' => 0,
        ];
    }

    /**
     * Per-plan flags: only plans that were on the draft order stay draft_cart true.
     * Plans added after draft proceed â†’ draft_cart false / draft_order null.
     *
     * @param  list<int>|null  $draftPlanIds
     * @return array{draft_cart: bool, draft_order: ?array, aadhaar_pending: bool}
     */
    private function draftFlagsForPlan(
        int $planId,
        ?array $draftOrder,
        bool $signRequired = true,
        ?array $draftPlanIds = null,
        int $cartId = 0
    ): array {
        if ($planId <= 0) {
            return [
                'draft_cart' => false,
                'draft_order' => null,
                'aadhaar_pending' => false,
            ];
        }

        if ($cartId > 0 && app(PartnerCartService::class)->isCartPendingAadhaar($cartId)) {
            $cartService = app(PartnerCartService::class);
            $poMeta = $cartService->getCartPoMeta($cartId);
            $cartRow = Cart::query()->whereKey($cartId)->first();
            $partnerIdForRef = (int) ($cartRow->partner_id ?? 0);
            $pendingRef = $partnerIdForRef > 0
                ? $cartService->issueCartPendingEsignRef($cartId, $partnerIdForRef)
                : null;

            return [
                'draft_cart' => false,
                'draft_order' => null,
                'aadhaar_pending' => false,
                'place_order_required' => true,
                'order_id' => $cartId,
                'po_link' => $poMeta['po_link'] ?? null,
                'po_number' => $poMeta['po_number'] ?? null,
                'ordId' => $cartId,
                'pending_ref_id' => $pendingRef,
                'order_no' => $pendingRef,
                'temp_order_no' => $pendingRef,
                'is_temp_order' => true,
                'real_order' => false,
                'status' => 'pending_place',
                'cart_id' => $cartId,
            ];
        }

        $planIds = $draftPlanIds ?? $this->resolveDraftPlanIds($draftOrder);
        if ($planIds === [] || !in_array($planId, $planIds, true)) {
            return [
                'draft_cart' => false,
                'draft_order' => null,
                'aadhaar_pending' => false,
            ];
        }

        // Plan is on a draft even if primary draft_order payload is for another draft id.
        if (empty($draftOrder) || empty($draftOrder['order_id'])) {
            return [
                'draft_cart' => false,
                'draft_order' => [
                    'status' => 'draft',
                    'sign_required' => 'yes',
                    'aadhaar_pending' => true,
                ],
                'aadhaar_pending' => $signRequired,
            ];
        }

        return [
            'draft_cart' => false,
            'draft_order' => $draftOrder,
            'aadhaar_pending' => $signRequired,
        ];
    }

    /**
     * Union of plan IDs across every open draft linked to this cart.
     *
     * @return list<int>
     */
    private function resolveAllDraftPlanIdsForCart(int $partnerId, $cart): array
    {
        $orderIds = $this->resolveDraftOrderIdsForCart($partnerId, $cart);
        $planIds = [];
        foreach ($orderIds as $orderId) {
            $planIds = array_merge($planIds, $this->resolveDraftPlanIds(['order_id' => (int) $orderId]));
        }

        return array_values(array_unique(array_filter(array_map('intval', $planIds))));
    }

    /**
     * Map plan_id â†’ draft_order payload for each open draft on this cart.
     *
     * @return array<int, array>
     */
    private function resolveDraftOrdersByPlanId(int $partnerId, $cart): array
    {
        $map = [];
        $cartId = (int) ($cart->id ?? 0);
        foreach ($this->resolveDraftOrderIdsForCart($partnerId, $cart) as $orderId) {
            $orderId = (int) $orderId;
            $order = Order::query()->whereKey($orderId)->first(['id', 'order_no']);
            if (!$order) {
                continue;
            }
            $poRow = OrderPoDetail::query()->where('order_id', $orderId)->first();
            $payload = [
                'order_id' => $orderId,
                'order_no' => (string) ($order->order_no ?? ''),
                'status' => 'draft',
                'sign_required' => 'yes',
                'aadhaar_pending' => true,
                'po_link' => $poRow?->po_document_url ?? null,
                'po_number' => $poRow?->po_number ?? null,
                'cart_id' => $cartId,
            ];
            foreach ($this->resolveDraftPlanIds(['order_id' => $orderId]) as $planId) {
                $map[(int) $planId] = $payload;
            }
        }

        return $map;
    }

    /**
     * @return list<int>
     */
    private function resolveDraftOrderIdsForCart(int $partnerId, $cart): array
    {
        if (!$cart || $partnerId <= 0) {
            return [];
        }

        $cartId = (int) ($cart->id ?? 0);
        if ($cartId <= 0) {
            return [];
        }

        $ids = [];
        $list = Cache::get('cart_draft_orders_' . $cartId, []);
        if (is_array($list)) {
            foreach ($list as $id) {
                $ids[] = (int) $id;
            }
        }
        $primary = (int) Cache::get('cart_draft_order_' . $cartId, 0);
        if ($primary > 0) {
            $ids[] = $primary;
        }

        if (\Schema::connection('pgsql_billing')->hasColumn('orders', 'cart_id')) {
            $fromDb = Order::query()
                ->where('partner_id', $partnerId)
                ->where('cart_id', $cartId)
                ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) = 'draft'")
                ->orderBy('id')
                ->pluck('id')
                ->map(fn($id) => (int) $id)
                ->all();
            $ids = array_merge($ids, $fromDb);
        }

        $customerId = (int) ($cart->customer_id ?? 0);
        $domainName = trim((string) ($cart->domain_name ?? ''));
        if ($ids === [] && $customerId > 0) {
            $q = Order::query()
                ->where('partner_id', $partnerId)
                ->where('user_id', $customerId)
                ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) = 'draft'")
                ->where(function ($qq) {
                    $qq->whereNull('parent_order_id')->orWhere('parent_order_id', 0);
                })
                ->orderBy('id');
            if ($domainName !== '') {
                $q->where('domain_name', $domainName);
            }
            $ids = $q->pluck('id')->map(fn($id) => (int) $id)->all();
        }

        $ids = array_values(array_unique(array_filter(array_map('intval', $ids))));
        $ids = array_values(array_filter(
            $ids,
            fn($id) => $this->isActiveDraftOrder((int) $id, $partnerId)
        ));

        // Drop drafts whose plans were removed from this cart (new plans must stay draft_cart false).
        $cartPlanIds = $this->cartPlanIds((int) $cartId);
        if ($cartPlanIds === []) {
            return [];
        }

        return array_values(array_filter($ids, function ($orderId) use ($cartPlanIds) {
            $draftPlanIds = $this->resolveDraftPlanIds(['order_id' => (int) $orderId]);
            if ($draftPlanIds === []) {
                return false;
            }

            return array_intersect($draftPlanIds, $cartPlanIds) !== [];
        }));
    }

    /**
     * @return list<int>
     */
    private function cartPlanIds(int $cartId): array
    {
        if ($cartId <= 0) {
            return [];
        }

        return CartItem::query()
            ->where('cart_id', $cartId)
            ->pluck('plan_id')
            ->map(fn($id) => (int) $id)
            ->filter(fn($id) => $id > 0)
            ->unique()
            ->values()
            ->all();
    }

    /**
     * After cart update/delete: cancel drafts whose plans are no longer in the cart.
     * Remaining draft plans keep draft_cart true; newly added plans stay false.
     */
    private function syncDraftOrdersWithCartPlans(int $partnerId, $cart): void
    {
        if (!$cart || $partnerId <= 0) {
            return;
        }

        $cartId = (int) ($cart->id ?? 0);
        if ($cartId <= 0) {
            return;
        }

        $cartPlanIds = $this->cartPlanIds($cartId);

        // Collect linked draft ids WITHOUT the "still in cart" filter (so we can cancel orphans).
        $linkedIds = [];
        $list = Cache::get('cart_draft_orders_' . $cartId, []);
        if (is_array($list)) {
            foreach ($list as $id) {
                $linkedIds[] = (int) $id;
            }
        }
        $primary = (int) Cache::get('cart_draft_order_' . $cartId, 0);
        if ($primary > 0) {
            $linkedIds[] = $primary;
        }
        if (\Schema::connection('pgsql_billing')->hasColumn('carts', 'order_id')) {
            $linked = (int) (Cart::query()->whereKey($cartId)->value('order_id') ?? 0);
            if ($linked > 0) {
                $linkedIds[] = $linked;
            }
        }
        if (\Schema::connection('pgsql_billing')->hasColumn('orders', 'cart_id')) {
            $fromDb = Order::query()
                ->where('partner_id', $partnerId)
                ->where('cart_id', $cartId)
                ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) = 'draft'")
                ->pluck('id')
                ->map(fn($id) => (int) $id)
                ->all();
            $linkedIds = array_merge($linkedIds, $fromDb);
        }
        $linkedIds = array_values(array_unique(array_filter($linkedIds)));

        if ($cartPlanIds === []) {
            if ($linkedIds !== [] || $primary > 0) {
                $this->cancelDraftOrderForCart($partnerId, $cartId);
            }
            return;
        }

        foreach ($linkedIds as $draftId) {
            $draftId = (int) $draftId;
            if ($draftId <= 0 || !$this->isActiveDraftOrder($draftId, $partnerId)) {
                $this->clearDraftLinksForCart($cartId, $draftId);
                continue;
            }

            $draftPlanIds = $this->resolveDraftPlanIds(['order_id' => $draftId]);
            $stillInCart = array_values(array_intersect($draftPlanIds, $cartPlanIds));

            if ($stillInCart === []) {
                // Draft plan(s) removed from cart â†’ cancel draft so next add shows draft_cart false.
                Order::query()->whereKey($draftId)->update(['status' => 'cancelled']);
                $this->clearDraftLinksForCart($cartId, $draftId);
                continue;
            }

            // Keep draft, but only for plans still present in cart.
            Cache::put('draft_order_plan_ids_' . $draftId, $stillInCart, now()->addDays(7));
            Cache::put('draft_order_cart_' . $draftId, $cartId, now()->addDays(7));
        }

        // Refresh primary multi-draft list from survivors.
        $survivors = [];
        foreach ($linkedIds as $draftId) {
            $draftId = (int) $draftId;
            if ($this->isActiveDraftOrder($draftId, $partnerId)) {
                $draftPlanIds = $this->resolveDraftPlanIds(['order_id' => $draftId]);
                if (array_intersect($draftPlanIds, $cartPlanIds) !== []) {
                    $survivors[] = $draftId;
                }
            }
        }
        $survivors = array_values(array_unique($survivors));
        if ($survivors === []) {
            $this->clearDraftLinksForCart($cartId, 0);
        } else {
            Cache::put('cart_draft_orders_' . $cartId, $survivors, now()->addDays(7));
            Cache::put('cart_draft_order_' . $cartId, (int) $survivors[0], now()->addDays(7));
        }
    }

    /**
     * Plan IDs included when the draft order was created (snapshot + order_items).
     *
     * @return list<int>
     */
    private function resolveDraftPlanIds(?array $draftOrder): array
    {
        if (empty($draftOrder['order_id'])) {
            return [];
        }

        $orderId = (int) $draftOrder['order_id'];
        $cached = Cache::get('draft_order_plan_ids_' . $orderId);
        if (is_array($cached) && $cached !== []) {
            return array_values(array_unique(array_map('intval', $cached)));
        }

        $ids = OrderItem::query()
            ->where('order_id', $orderId)
            ->where(function ($q) {
                $q->whereNull('status')
                    ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted')");
            })
            ->pluck('plan_id')
            ->map(fn($id) => (int) $id)
            ->filter(fn($id) => $id > 0)
            ->unique()
            ->values()
            ->all();

        if ($ids !== []) {
            Cache::put('draft_order_plan_ids_' . $orderId, $ids, now()->addDays(7));
        }

        return $ids;
    }

    /**
     * Active cart that already has a draft or temp pending order.
     */
    private function findActiveDraftCartForPartner(int $partnerId): ?Cart
    {
        if ($partnerId <= 0) {
            return null;
        }

        $cartIds = [];

        if (\Schema::connection('pgsql_billing')->hasColumn('carts', 'order_id')) {
            $candidateCarts = Cart::query()
                ->where('partner_id', $partnerId)
                ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) = 'active'")
                ->whereNotNull('order_id')
                ->where('order_id', '>', 0)
                ->orderByDesc('id')
                ->limit(10)
                ->get(['id', 'order_id']);

            foreach ($candidateCarts as $row) {
                if ($this->isActiveDraftOrder((int) $row->order_id, $partnerId)) {
                    $cartIds[] = (int) $row->id;
                }
            }
        }

        $activeCartIds = Cart::query()
            ->where('partner_id', $partnerId)
            ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) = 'active'")
            ->orderByDesc('id')
            ->limit(20)
            ->pluck('id')
            ->map(fn($id) => (int) $id)
            ->all();

        foreach ($activeCartIds as $cid) {
            if (app(PartnerCartService::class)->isCartPendingAadhaar($cid)) {
                $cartIds[] = $cid;
                continue;
            }
            $cachedOrderId = (int) Cache::get('cart_draft_order_' . $cid, 0);
            if ($cachedOrderId > 0 && $this->isActiveDraftOrder($cachedOrderId, $partnerId)) {
                $cartIds[] = $cid;
            }
        }

        if (\Schema::connection('pgsql_billing')->hasColumn('orders', 'cart_id')) {
            $fromOrders = Order::query()
                ->where('partner_id', $partnerId)
                ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) = 'draft'")
                ->where(function ($q) {
                    $q->whereNull('parent_order_id')->orWhere('parent_order_id', 0);
                })
                ->whereNotNull('cart_id')
                ->where('cart_id', '>', 0)
                ->orderByDesc('id')
                ->limit(10)
                ->pluck('cart_id')
                ->map(fn($id) => (int) $id)
                ->all();
            $cartIds = array_merge($cartIds, $fromOrders);
        }

        $cartIds = array_values(array_unique(array_filter($cartIds)));

        // Rediscover via open draft orders (cache may have expired; orders.cart_id may be absent).
        if ($cartIds === []) {
            $draftOrders = Order::query()
                ->where('partner_id', $partnerId)
                ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) = 'draft'")
                ->where(function ($q) {
                    $q->whereNull('parent_order_id')->orWhere('parent_order_id', 0);
                })
                ->orderByDesc('id')
                ->limit(10)
                ->get(['id', 'user_id', 'domain_name']);

            foreach ($draftOrders as $draft) {
                $oid = (int) ($draft->id ?? 0);
                $draftPlanIds = $this->resolveDraftPlanIds(['order_id' => $oid]);
                if ($draftPlanIds === []) {
                    continue;
                }

                $linkedCartId = (int) Cache::get('draft_order_cart_' . $oid, 0);
                if ($linkedCartId > 0) {
                    $cartPlans = $this->cartPlanIds($linkedCartId);
                    if (array_intersect($draftPlanIds, $cartPlans) !== []) {
                        $cartIds[] = $linkedCartId;
                    } else {
                        // Draft plans gone from cart â€” cancel orphan draft.
                        Order::query()->whereKey($oid)->update(['status' => 'cancelled']);
                        $this->clearDraftLinksForCart($linkedCartId, $oid);
                    }
                    continue;
                }
                $customerId = (int) ($draft->user_id ?? 0);
                if ($customerId <= 0) {
                    continue;
                }
                $q = Cart::query()
                    ->where('partner_id', $partnerId)
                    ->where('customer_id', $customerId)
                    ->where('type', Cart::TYPE_STANDARD)
                    ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) = 'active'");
                $domainName = trim((string) ($draft->domain_name ?? ''));
                $foundId = 0;
                if ($domainName !== '') {
                    $foundId = (int) ((clone $q)->where('domain_name', $domainName)->orderByDesc('id')->value('id') ?? 0);
                    if ($foundId <= 0) {
                        $foundId = (int) ($q->orderByDesc('id')->value('id') ?? 0);
                    }
                } else {
                    $foundId = (int) ($q->orderByDesc('id')->value('id') ?? 0);
                }
                if ($foundId <= 0) {
                    continue;
                }
                $cartPlans = $this->cartPlanIds($foundId);
                // Only re-link when at least one draft plan is still in the cart.
                if (array_intersect($draftPlanIds, $cartPlans) === []) {
                    continue;
                }
                $cartIds[] = $foundId;
                Cache::put('cart_draft_order_' . $foundId, $oid, now()->addDays(7));
                Cache::put('draft_order_cart_' . $oid, $foundId, now()->addDays(7));
                $list = Cache::get('cart_draft_orders_' . $foundId, []);
                if (!is_array($list)) {
                    $list = [];
                }
                $list[] = $oid;
                Cache::put(
                    'cart_draft_orders_' . $foundId,
                    array_values(array_unique(array_filter(array_map('intval', $list)))),
                    now()->addDays(7)
                );
            }
            $cartIds = array_values(array_unique(array_filter($cartIds)));
        }

        // Keep only carts that still contain at least one draft plan.
        $cartIds = array_values(array_filter($cartIds, function ($cid) use ($partnerId) {
            $cid = (int) $cid;
            $cartPlans = $this->cartPlanIds($cid);
            if ($cartPlans === []) {
                return false;
            }
            $primary = (int) Cache::get('cart_draft_order_' . $cid, 0);
            $list = Cache::get('cart_draft_orders_' . $cid, []);
            $oids = is_array($list) ? array_map('intval', $list) : [];
            if ($primary > 0) {
                $oids[] = $primary;
            }
            foreach (array_unique($oids) as $oid) {
                if (!$this->isActiveDraftOrder((int) $oid, $partnerId)) {
                    continue;
                }
                $draftPlans = $this->resolveDraftPlanIds(['order_id' => (int) $oid]);
                if (array_intersect($draftPlans, $cartPlans) !== []) {
                    return true;
                }
            }
            return false;
        }));

        if ($cartIds === []) {
            return null;
        }

        return Cart::query()
            ->with(['items.plan', 'customer'])
            ->where('partner_id', $partnerId)
            ->where('type', Cart::TYPE_STANDARD)
            ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) = 'active'")
            ->whereIn('id', $cartIds)
            ->orderByDesc('id')
            ->first();
    }

    /**
     * Draft for THIS cart only.
     * draft_cart true + draft_order only while a real draft order is linked.
     * If draft was removed/cancelled/promoted â†’ clear links and return null (draft_cart false).
     */
    private function resolveDraftOrderForCart(int $partnerId, $cart): ?array
    {
        if (!$cart || $partnerId <= 0) {
            return null;
        }

        $cartId = (int) ($cart->id ?? 0);
        if ($cartId <= 0) {
            return null;
        }

        // Cart-only eSign pending: never expose a real draft order id.
        if (app(PartnerCartService::class)->isCartPendingAadhaar($cartId)) {
            app(PartnerCartService::class)->cancelOpenDraftOrdersForCart($cartId, $partnerId);
            return null;
        }

        $this->clearStaleDraftLinksForCart($partnerId, $cartId, $cart);

        $draftOrderIds = $this->resolveDraftOrderIdsForCart($partnerId, $cart);
        $draftOrderId = (int) ($draftOrderIds[0] ?? 0);

        // Legacy single-link paths (kept for carts that only have primary cache key).
        if ($draftOrderId <= 0) {
            $draftOrderId = (int) Cache::get('cart_draft_order_' . $cartId, 0);
            if ($draftOrderId > 0 && !$this->isActiveDraftOrder($draftOrderId, $partnerId)) {
                $this->clearDraftLinksForCart($cartId, $draftOrderId);
                $draftOrderId = 0;
            }
        }

        if ($draftOrderId <= 0 && \Schema::connection('pgsql_billing')->hasColumn('carts', 'order_id')) {
            $linkedOrderId = (int) (
                $cart->order_id
                ?? Cart::query()->whereKey($cartId)->value('order_id')
                ?? 0
            );
            if ($linkedOrderId > 0 && $this->isActiveDraftOrder($linkedOrderId, $partnerId)) {
                $draftOrderId = $linkedOrderId;
            } elseif ($linkedOrderId > 0 && !$this->cartKeepsParentOrderLink($cartId)) {
                // Parent subscription link on renew/upgrade must stay; only clear draft links.
                $this->clearDraftLinksForCart($cartId, $linkedOrderId);
            }
        }

        if ($draftOrderId <= 0 || !$this->isActiveDraftOrder($draftOrderId, $partnerId)) {
            // Do not wipe rediscovered empty state aggressively when cart simply has no draft.
            if ($draftOrderId > 0) {
                $this->clearDraftLinksForCart($cartId, $draftOrderId);
            }
            return null;
        }

        // Keep links in sync for this cart (supports multiple open drafts).
        $allIds = $draftOrderIds !== [] ? $draftOrderIds : [$draftOrderId];
        Cache::put('cart_draft_orders_' . $cartId, $allIds, now()->addDays(7));
        Cache::put('cart_draft_order_' . $cartId, $draftOrderId, now()->addDays(7));
        foreach ($allIds as $oid) {
            Cache::put('draft_order_cart_' . (int) $oid, $cartId, now()->addDays(7));
            $this->resolveDraftPlanIds(['order_id' => (int) $oid]);
        }
        if (\Schema::connection('pgsql_billing')->hasColumn('carts', 'order_id')) {
            Cart::query()->whereKey($cartId)->update(['order_id' => $draftOrderId]);
        }
        if (\Schema::connection('pgsql_billing')->hasColumn('orders', 'cart_id')) {
            foreach ($allIds as $oid) {
                Order::query()
                    ->whereKey((int) $oid)
                    ->where(function ($q) use ($cartId) {
                        $q->whereNull('cart_id')->orWhere('cart_id', 0)->orWhere('cart_id', '!=', $cartId);
                    })
                    ->update(['cart_id' => $cartId]);
            }
        }

        $order = Order::query()->whereKey($draftOrderId)->first();
        if (!$order) {
            $this->clearDraftLinksForCart($cartId, $draftOrderId);
            return null;
        }

        $poRow = OrderPoDetail::query()->where('order_id', $draftOrderId)->first();

        return [
            'order_id' => $draftOrderId,
            'order_no' => (string) ($order->order_no ?? ''),
            'status' => 'draft',
            'sign_required' => 'yes',
            'aadhaar_pending' => true,
            'po_link' => $poRow?->po_document_url ?? null,
            'po_number' => $poRow?->po_number ?? null,
            'cart_id' => $cartId,
        ];
    }

    /**
     * Drop cache / cart.order_id when linked order is no longer an active draft.
     */
    private function clearStaleDraftLinksForCart(int $partnerId, int $cartId, $cart = null): void
    {
        $candidates = [];

        $cached = (int) Cache::get('cart_draft_order_' . $cartId, 0);
        if ($cached > 0) {
            $candidates[] = $cached;
        }

        if (\Schema::connection('pgsql_billing')->hasColumn('carts', 'order_id')) {
            $linked = (int) (
                ($cart->order_id ?? null)
                ?? Cart::query()->whereKey($cartId)->value('order_id')
                ?? 0
            );
            // Parent subscription on renew/upgrade is not a draft link â€” skip it.
            if ($linked > 0 && !$this->cartKeepsParentOrderLink($cartId)) {
                $candidates[] = $linked;
            }
        }

        foreach (array_unique($candidates) as $orderId) {
            if (!$this->isActiveDraftOrder((int) $orderId, $partnerId)) {
                $this->clearDraftLinksForCart($cartId, (int) $orderId);
            }
        }
    }

    private function clearDraftLinksForCart(int $cartId, int $orderId = 0): void
    {
        if ($orderId > 0) {
            Cache::forget('draft_order_cart_' . $orderId);
            Cache::forget('draft_order_plan_ids_' . $orderId);
        }

        if ($cartId <= 0) {
            return;
        }

        $list = Cache::get('cart_draft_orders_' . $cartId, []);
        if (!is_array($list)) {
            $list = [];
        }
        $primary = (int) Cache::get('cart_draft_order_' . $cartId, 0);
        if ($primary > 0) {
            $list[] = $primary;
        }
        $list = array_values(array_unique(array_filter(array_map('intval', $list))));

        if ($orderId > 0) {
            $list = array_values(array_filter($list, static fn($id) => (int) $id !== (int) $orderId));
        } else {
            foreach ($list as $oid) {
                Cache::forget('draft_order_cart_' . $oid);
                Cache::forget('draft_order_plan_ids_' . $oid);
            }
            $list = [];
        }

        if ($list === []) {
            Cache::forget('cart_draft_orders_' . $cartId);
            Cache::forget('cart_draft_order_' . $cartId);
            // Preserve parent subscription id on renew/upgrade/downgrade carts.
            if (
                \Schema::connection('pgsql_billing')->hasColumn('carts', 'order_id')
                && !$this->cartKeepsParentOrderLink($cartId)
            ) {
                Cart::query()->whereKey($cartId)->update(['order_id' => null]);
            }
        } else {
            Cache::put('cart_draft_orders_' . $cartId, $list, now()->addDays(7));
            Cache::put('cart_draft_order_' . $cartId, (int) $list[0], now()->addDays(7));
            if (
                \Schema::connection('pgsql_billing')->hasColumn('carts', 'order_id')
                && !$this->cartKeepsParentOrderLink($cartId)
            ) {
                Cart::query()->whereKey($cartId)->update(['order_id' => (int) $list[0]]);
            }
        }
    }

    /**
     * Renew / upgrade / downgrade carts store the parent subscription on carts.order_id.
     */
    private function cartKeepsParentOrderLink(int $cartId): bool
    {
        if ($cartId <= 0) {
            return false;
        }

        $type = strtolower(trim((string) (
            Cart::query()->whereKey($cartId)->value('type') ?? ''
        )));

        return in_array($type, [
            Cart::TYPE_RENEW,
            Cart::TYPE_UPGRADE,
            Cart::TYPE_DOWNGRADE,
            'license_add',
        ], true);
    }

    /**
     * Cancel every open draft for partner (cart contents changed after proceed).
     * Next getCartDetails / addToCart shows draft_cart false until proceed again.
     */
    private function cancelAllActiveDraftsForPartner(int $partnerId): void
    {
        if ($partnerId <= 0) {
            return;
        }

        $hasOrdersCartId = \Schema::connection('pgsql_billing')->hasColumn('orders', 'cart_id');
        $selectCols = $hasOrdersCartId ? ['id', 'cart_id'] : ['id'];

        $draftOrders = Order::query()
            ->where('partner_id', $partnerId)
            ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) = 'draft'")
            ->where(function ($q) {
                $q->whereNull('parent_order_id')->orWhere('parent_order_id', 0);
            })
            ->orderByDesc('id')
            ->limit(20)
            ->get($selectCols);

        foreach ($draftOrders as $draft) {
            $orderId = (int) ($draft->id ?? 0);
            $cartId = 0;
            if ($hasOrdersCartId) {
                $cartId = (int) ($draft->cart_id ?? 0);
            }
            if ($cartId <= 0 && $orderId > 0) {
                $cartId = (int) Cache::get('draft_order_cart_' . $orderId, 0);
            }
            if ($cartId <= 0 && $orderId > 0 && \Schema::connection('pgsql_billing')->hasColumn('carts', 'order_id')) {
                $cartId = (int) (
                    Cart::query()
                    ->where('partner_id', $partnerId)
                    ->where('order_id', $orderId)
                    ->orderByDesc('id')
                    ->value('id') ?? 0
                );
            }

            if ($orderId > 0) {
                Order::query()->whereKey($orderId)->update(['status' => 'cancelled']);
            }
            if ($cartId > 0) {
                $this->clearDraftLinksForCart($cartId, $orderId);
            } elseif ($orderId > 0) {
                Cache::forget('draft_order_cart_' . $orderId);
            }
        }

        // Also clear carts.order_id that still point at cancelled/missing drafts
        if (\Schema::connection('pgsql_billing')->hasColumn('carts', 'order_id')) {
            $carts = Cart::query()
                ->where('partner_id', $partnerId)
                ->where('type', Cart::TYPE_STANDARD)
                ->whereNotNull('order_id')
                ->where('order_id', '>', 0)
                ->orderByDesc('id')
                ->limit(20)
                ->get(['id', 'order_id']);

            foreach ($carts as $cartRow) {
                if (!$this->isActiveDraftOrder((int) $cartRow->order_id, $partnerId)) {
                    $this->clearDraftLinksForCart((int) $cartRow->id, (int) $cartRow->order_id);
                }
            }
        }
    }

    /**
     * Cancel draft for cart (e.g. cart emptied) so next add-to-cart shows draft_cart false.
     */
    private function cancelDraftOrderForCart(int $partnerId, int $cartId): void
    {
        if ($partnerId <= 0 || $cartId <= 0) {
            return;
        }

        $draftIds = [];
        $cached = (int) Cache::get('cart_draft_order_' . $cartId, 0);
        if ($cached > 0) {
            $draftIds[] = $cached;
        }
        if (\Schema::connection('pgsql_billing')->hasColumn('carts', 'order_id')) {
            $linked = (int) (Cart::query()->whereKey($cartId)->value('order_id') ?? 0);
            if ($linked > 0) {
                $draftIds[] = $linked;
            }
        }
        if (\Schema::connection('pgsql_billing')->hasColumn('orders', 'cart_id')) {
            $fromOrder = (int) Order::query()
                ->where('partner_id', $partnerId)
                ->where('cart_id', $cartId)
                ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) = 'draft'")
                ->orderByDesc('id')
                ->value('id');
            if ($fromOrder > 0) {
                $draftIds[] = $fromOrder;
            }
        }

        foreach (array_unique($draftIds) as $draftId) {
            if ($this->isActiveDraftOrder((int) $draftId, $partnerId)) {
                Order::query()->whereKey((int) $draftId)->update(['status' => 'cancelled']);
            }
            $this->clearDraftLinksForCart($cartId, (int) $draftId);
        }

        app(PartnerCartService::class)->clearCartPendingAadhaar($cartId);
        $this->clearDraftLinksForCart($cartId, 0);
    }

    private function isActiveDraftOrder(int $orderId, int $partnerId): bool
    {
        if ($orderId <= 0 || $partnerId <= 0) {
            return false;
        }

        $row = Order::query()
            ->whereKey($orderId)
            ->where('partner_id', $partnerId)
            ->first(['id', 'status']);

        if (!$row || strtolower(trim((string) ($row->status ?? ''))) !== 'draft') {
            return false;
        }

        // Aadhaar already verified â†’ order is purchased/placed; never treat as draft in cart.
        $poVerified = (int) (OrderPoDetail::query()
            ->where('order_id', $orderId)
            ->value('aadhar_verified') ?? 0);
        if ($poVerified === 1) {
            return false;
        }

        return true;
    }

    /**
     * After successful purchase (processing/completed/aadhaar done): clear draft links,
     * empty/convert cart so getCartDetails returns no draft and no leftover items.
     */
    private function clearSuccessfulPurchaseDraftState(int $partnerId, $cart): void
    {
        if (!$cart || $partnerId <= 0) {
            return;
        }

        $cartId = (int) ($cart->id ?? 0);
        if ($cartId <= 0) {
            return;
        }

        // Place-pending / renew / upgrade / downgrade carts must keep items until Place Order.
        $cartType = strtolower(trim((string) ($cart->type ?? '')));
        $isPlanChangeCart = in_array($cartType, [
            Cart::TYPE_RENEW,
            Cart::TYPE_UPGRADE,
            Cart::TYPE_DOWNGRADE,
            'license_add',
        ], true);
        if ($isPlanChangeCart || app(PartnerCartService::class)->isCartPendingAadhaar($cartId)) {
            return;
        }

        $candidates = [];
        $list = Cache::get('cart_draft_orders_' . $cartId, []);
        if (is_array($list)) {
            $candidates = array_merge($candidates, array_map('intval', $list));
        }
        $primary = (int) Cache::get('cart_draft_order_' . $cartId, 0);
        if ($primary > 0) {
            $candidates[] = $primary;
        }
        // Do NOT treat carts.order_id as a purchase candidate here for plan-change carts
        // (that column holds the parent subscription id). Standard carts only:
        if (\Schema::connection('pgsql_billing')->hasColumn('carts', 'order_id')) {
            $linked = (int) (
                ($cart->order_id ?? null)
                ?? Cart::query()->whereKey($cartId)->value('order_id')
                ?? 0
            );
            if ($linked > 0) {
                $linkedStatus = strtolower(trim((string) (
                    Order::query()->whereKey($linked)->where('partner_id', $partnerId)->value('status') ?? ''
                )));
                // Only treat as purchased when this cart's own draft was promoted â€” not a live parent sub.
                $fromThisCart = false;
                if (\Schema::connection('pgsql_billing')->hasColumn('orders', 'cart_id')) {
                    $fromThisCart = (int) (Order::query()->whereKey($linked)->value('cart_id') ?? 0) === $cartId;
                }
                $cachedLink = (int) Cache::get('draft_order_cart_' . $linked, 0) === $cartId;
                if ($fromThisCart || $cachedLink || $linkedStatus === 'draft') {
                    $candidates[] = $linked;
                }
            }
        }
        if (\Schema::connection('pgsql_billing')->hasColumn('orders', 'cart_id')) {
            $fromOrders = Order::query()
                ->where('partner_id', $partnerId)
                ->where('cart_id', $cartId)
                ->orderByDesc('id')
                ->limit(20)
                ->pluck('id')
                ->map(fn($id) => (int) $id)
                ->all();
            $candidates = array_merge($candidates, $fromOrders);
        }

        // Linked via draft_order_cart reverse lookup for this cart's known drafts only.
        $candidates = array_values(array_unique(array_filter($candidates)));

        $hasRealDraft = false;
        $sawPurchase = false;
        $purchasedPlanIds = [];

        foreach ($candidates as $orderId) {
            $orderId = (int) $orderId;
            if ($orderId <= 0) {
                continue;
            }

            $status = strtolower(trim((string) (
                Order::query()->whereKey($orderId)->where('partner_id', $partnerId)->value('status') ?? ''
            )));
            $poVerified = (int) (OrderPoDetail::query()
                ->where('order_id', $orderId)
                ->value('aadhar_verified') ?? 0);
            $journeyStatus = strtolower(trim((string) (
                OrderPoDetail::query()->where('order_id', $orderId)->value('journey_status') ?? ''
            )));

            // Do not wipe cart lines for in-flight processing orders (may still rollback).
            $isPurchased = $poVerified === 1
                || $journeyStatus === 'placed'
                || in_array($status, ['completed', 'active', 'success'], true);

            if ($isPurchased) {
                $sawPurchase = true;
                $plans = OrderItem::query()
                    ->where('order_id', $orderId)
                    ->pluck('plan_id')
                    ->map(fn($id) => (int) $id)
                    ->filter(fn($id) => $id > 0)
                    ->all();
                $purchasedPlanIds = array_merge($purchasedPlanIds, $plans);
                $this->clearDraftLinksForCart($cartId, $orderId);
                Cache::forget('draft_order_plan_ids_' . $orderId);
                continue;
            }

            if ($status !== 'draft') {
                $this->clearDraftLinksForCart($cartId, $orderId);
                Cache::forget('draft_order_plan_ids_' . $orderId);
                continue;
            }

            $draftPlans = $this->resolveDraftPlanIds(['order_id' => $orderId]);
            $currentCartPlans = $this->cartPlanIds($cartId);
            if ($currentCartPlans === [] || array_intersect($draftPlans, $currentCartPlans) === []) {
                Order::query()->whereKey($orderId)->update(['status' => 'cancelled']);
                $this->clearDraftLinksForCart($cartId, $orderId);
                continue;
            }

            $hasRealDraft = true;
        }

        $purchasedPlanIds = array_values(array_unique(array_filter($purchasedPlanIds)));
        if ($purchasedPlanIds !== []) {
            CartItem::query()
                ->where('cart_id', $cartId)
                ->whereIn('plan_id', $purchasedPlanIds)
                ->delete();
        }

        $remainingItems = (int) CartItem::query()->where('cart_id', $cartId)->count();

        if (!$hasRealDraft || $remainingItems <= 0) {
            $this->clearDraftLinksForCart($cartId, 0);
            if ($sawPurchase || $remainingItems <= 0) {
                if ($sawPurchase) {
                    app(PartnerCartService::class)->clearCartPendingAadhaar($cartId);
                    CartItem::query()->where('cart_id', $cartId)->delete();
                    Cart::query()->whereKey($cartId)->update(['status' => 'converted']);
                    if (\Schema::connection('pgsql_billing')->hasColumn('carts', 'order_id')) {
                        Cart::query()->whereKey($cartId)->update(['order_id' => null]);
                    }
                } elseif ($remainingItems <= 0 && !$hasRealDraft) {
                    // Empty cart with no open draft â†’ clear links only (don't force convert empty new carts).
                    $this->clearDraftLinksForCart($cartId, 0);
                }
            }
        }
    }

    public function getcarts_and_CreditDetails($partnerId)
    {
        $partnerId = (int) $partnerId;
        $partner = Partner::find($partnerId);
        if (!$partner) {
            return response()->json([
                'success' => false,
                'message' => 'Partner not found',
                'data' => null,
            ], 404);
        }

        $remainingLimit = PartnerCreditService::remainingPurchaseAllowance($partnerId);
        $walletBalance = round($remainingLimit, 2);

        $cart = $this->findActiveDraftCartForPartner($partnerId);
        if (!$cart) {
            $cart = Cart::query()
                ->with('items')
                ->ofType(Cart::TYPE_STANDARD)
                ->active()
                ->where('partner_id', $partnerId)
                ->orderByDesc('id')
                ->first();
        } elseif (!$cart->relationLoaded('items')) {
            $cart = Cart::query()->with('items')->whereKey((int) $cart->id)->first() ?? $cart;
        }

        $cartItemCount = $cart ? $cart->items->count() : 0;

        $subtotal = 0.0;
        $discountAmount = 0.0;
        $taxable = 0.0;
        $gstPercentage = (float) ($cart->gst_percentage ?? 18);
        $gstAmount = 0.0;
        $grandTotal = 0.0;

        if ($cartItemCount > 0 && $cart->items->isNotEmpty()) {
            foreach ($cart->items as $item) {
                $qty = max(1, (int) ($item->licenses ?? 1));
                $unit = (float) ($item->grand_total ?? $item->unit_price ?? 0);
                if ($item->grand_total !== null) {
                    $subtotal += (float) $item->grand_total;
                } else {
                    $subtotal += $unit * $qty;
                }
            }
            $discountAmount = (float) ($cart->discount_amount ?? 0);
            $taxable = max(0.0, $subtotal - $discountAmount);
            $gstPercentage = (float) ($cart->gst_percentage ?? 18);
            $gstAmount = (float) ($cart->gst_amount ?? max(0.0, round($taxable * $gstPercentage / 100, 2)));
            $grandTotal = (float) ($cart->grand_total ?? round($taxable + $gstAmount, 2));
        } elseif ($cartItemCount > 0 && $cart && $cart->plan_id && $cart->licenses && $cart->unit_price) {
            $subtotal = (float) $cart->unit_price * (int) $cart->licenses;
            $discountAmount = (float) ($cart->discount_amount ?? 0);
            $taxable = max(0.0, $subtotal - $discountAmount);
            $gstPercentage = (float) ($cart->gst_percentage ?? 18);
            $gstAmount = (float) ($cart->gst_amount ?? max(0.0, round($taxable * $gstPercentage / 100, 2)));
            $grandTotal = (float) ($cart->grand_total ?? round($taxable + $gstAmount, 2));
        }

        $deductedAmount = $grandTotal;
        // No prepaid wallet deduct â€” allocation covers purchase; invoice paid later with real money.
        $creditsFromWallet = 0.0;
        $payableAfterWallet = round($deductedAmount, 2);
        $creditLimitReached = PartnerCreditService::isCreditLimitFullyUsed($partnerId);
        $creditCheck = PartnerCreditService::validateB2bPurchaseAmount($partnerId, $grandTotal);
        $canPurchase = !$creditLimitReached
            && ($grandTotal <= 0.005 || !empty($creditCheck['ok']));
        $isSufficient = $canPurchase;

        $signRequired = strtolower(trim((string) ($partner->aadhaar_mandatory ?? 'no'))) === 'yes';
        $mainCartId = (int) ($cart?->id ?? 0);
        $draftOrder = ($cart && $cartItemCount > 0)
            ? $this->resolveDraftOrderForCart($partnerId, $cart)
            : null;
        $draftFlags = $this->syncedDraftFlags($draftOrder, $signRequired, $mainCartId);

        return response()->json([
            'success' => true,
            'message' => 'Cart and credit details fetched successfully',
            'data' => array_merge([
                'main_cart_id' => $cart?->id,
                'cart_item_count' => $cartItemCount,
                'credit_limit' => round((float) ($partner->credit_limit ?? 0), 2),
                'credit_used' => round(PartnerCreditService::summarizeUsedCredit($partnerId), 2),
                'remaining_credit_limit' => round($remainingLimit, 2),
                'available_balance' => round($remainingLimit, 2),
                'wallet_balance' => $walletBalance,
                'credit_limit_reached' => $creditLimitReached,
                'can_purchase' => $canPurchase,
                'purchase_block_message' => $creditLimitReached
                    ? PartnerCreditService::CREDIT_LIMIT_REACHED_MESSAGE
                    : (empty($creditCheck['ok']) && $grandTotal > 0.005
                        ? (string) ($creditCheck['message'] ?? PartnerCreditService::CREDIT_LIMIT_REACHED_MESSAGE)
                        : null),
                'subtotal' => round($subtotal, 2),
                'discount_amount' => round($discountAmount, 2),
                'taxable_amount' => round($taxable, 2),
                'gst_percentage' => $gstPercentage,
                'gst_amount' => round($gstAmount, 2),
                'grand_total' => round($grandTotal, 2),
                'total_invoice_amount' => round($grandTotal, 2),
                'deducted_amount' => $deductedAmount,
                'credits_deducted' => round($creditsFromWallet, 2),
                'credits_used' => round($creditsFromWallet, 2),
                'payable_after_wallet' => $payableAfterWallet,
                'is_sufficient_balance' => $isSufficient,
                'sign_required' => $signRequired ? 'yes' : 'no',
                'partner_avilable' => isset($partner->id) && $partner->id == $partnerId ? 'yes' : 'no',

            ], $draftFlags),
        ]);
    }

    // cart_id
    public function getsummary(Request $request)
    {
        // Validate POST request data - now using cart_id to show cart-wise details
        $validated = $request->validate([
            'cart_id'     => 'required|integer|exists:pgsql_billing.carts,id',
        ]);

        $cartId = $validated['cart_id'];

        $cart = Cart::with(['partner', 'customer', 'plan', 'items.plan'])->find($cartId);

        if (!$cart) {
            return response()->json([
                'success' => false,
                'message' => 'Cart not found',
                'data'    => null,
            ], 404);
        }

        $cartService = app(PartnerCartService::class);
        $pricing = ($cart->items->isNotEmpty() || $cart->plan_id)
            ? $cartService->buildCartDeductionSummary($cart)
            : [
                'subtotal' => 0.0,
                'discount_amount' => round((float) ($cart->discount_amount ?? 0), 2),
                'taxable_amount' => round(max(0, (float) ($cart->grand_total ?? 0) - (float) ($cart->gst_amount ?? 0)), 2),
                'gst_percentage' => round((float) ($cart->gst_percentage ?? 18), 2),
                'gst_amount' => round((float) ($cart->gst_amount ?? 0), 2),
                'grand_total' => round((float) ($cart->grand_total ?? 0), 2),
                'total_invoice_amount' => round((float) ($cart->grand_total ?? 0), 2),
                'deducted_amount' => round((float) ($cart->grand_total ?? 0), 2),
                'credits_deducted' => round((float) ($cart->grand_total ?? 0), 2),
                'credits_used' => round((float) ($cart->grand_total ?? 0), 2),
            ];

        $deductedAmount = round((float) ($pricing['deducted_amount'] ?? 0), 2);
        $partnerId = (int) ($cart->partner_id ?? 0);
        $creditContext = $this->partnerB2bWalletInfo($partnerId, $deductedAmount);

        $plan = $cart->plan;
        $planInfo = null;
        if ($plan) {
            $planInfo = [];
            foreach ($plan->getAttributes() as $key => $value) {
                $planInfo[$key] = $value;
            }
            if (!array_key_exists('plan_id', $planInfo)) {
                $planInfo['plan_id'] = $plan->id;
            }
        }

        $cartData = [
            'cart_id' => $cart->id,
            'main_cart_id' => $cart->id,
            'partner_id' => $cart->partner_id,
            'customer_id' => $cart->customer_id,
            'plan_id' => $cart->plan_id,
            'domain_name' => $cart->domain_name,
            'licenses' => $cart->licenses,
            'unit_price' => $cart->unit_price,
            'coupen' => $cart->coupen,
            'discount_amount' => $pricing['discount_amount'],
            'gst_percentage' => $pricing['gst_percentage'],
            'gst_amount' => $pricing['gst_amount'],
            'grand_total' => $pricing['grand_total'],
            'subtotal' => $pricing['subtotal'],
            'taxable_amount' => $pricing['taxable_amount'],
            'total_invoice_amount' => $pricing['total_invoice_amount'],
            'deducted_amount' => $deductedAmount,
            'credits_deducted' => $deductedAmount,
            'credits_used' => $deductedAmount,
            'wallet_balance' => $creditContext['wallet_balance'],
            'available_balance' => $creditContext['available_balance'],
            'credit_limit' => $creditContext['credit_limit'],
            'credit_used' => $creditContext['credit_used'],
            'remaining_credit_limit' => $creditContext['remaining_credit_limit'],
            'credit_limit_reached' => $creditContext['credit_limit_reached'],
            'can_purchase' => $creditContext['can_purchase'],
            'purchase_block_message' => $creditContext['purchase_block_message'],
            'payable_after_wallet' => round($deductedAmount, 2),
            'is_sufficient_balance' => $creditContext['can_purchase'],
            'pricing' => $pricing,
            'created_at' => $cart->created_at ? $cart->created_at->format('Y-m-d') : null,
            'updated_at' => $cart->updated_at ? $cart->updated_at->format('Y-m-d') : null,
            'plan' => $planInfo,
        ];

        return response()->json([
            'success' => true,
            'message' => 'Cart information fetched successfully',
            'data' => $cartData,
            'deducted_amount' => $deductedAmount,
            'credits_deducted' => $deductedAmount,
            'credits_used' => $deductedAmount,
        ]);
    }

