    public function b2bBilling(Request $request)
    {
        $requestedPartnerId = $request->input('partner_id', $request->query('partner_id'));
        $partnerId = $this->resolvePartnerId($request);

        if (!$partnerId) {
            return response()->json([
                'success' => false,
                'message' => 'Partner ID is required',
                'data' => [
                    'invoice_data' => [],
                    'summary' => [],
                ]
            ], 400);
        }

        $authPartner = $request->user();
        if (
            $authPartner instanceof Partner
            && $requestedPartnerId !== null
            && $requestedPartnerId !== ''
            && (int) $requestedPartnerId !== (int) $authPartner->id
        ) {
            return response()->json([
                'success' => false,
                'message' => 'You can only access your own invoice data.',
                'data' => [
                    'invoice_data' => [],
                    'summary' => [],
                ],
            ], 403);
        }

        $partner = Partner::find($partnerId);
        if (!$partner) {
            return response()->json([
                'success' => false,
                'message' => 'Partner not found',
                'data' => [
                    'invoice_data' => [],
                    'summary' => [],
                ],
            ], 404);
        }

        try {
            // PERF: plain indexable comparisons on partner_id / action_type / bill_no_full instead of
            // wrapping columns in LOWER(TRIM(COALESCE(...))) / UPPER(...), which forced a full scan.
            // Credit notes belong on /credit-notes — keep them out of Invoices.
            $baseInvoiceQuery = $this->invoiceMst->newQuery()
                ->where('partner_id', $partnerId)
                ->where(fn ($q) => $q->whereNull('action_type')->orWhere('action_type', '!=', 'credit_note'))
                ->where(fn ($q) => $q->whereNull('bill_no_full')->orWhere('bill_no_full', 'NOT ILIKE', 'CN/%'));

            // PERF: light pass — only the columns the status / summary maths need (no SELECT *).
            // Summary totals, attempt counters and chip counts cover ALL invoices, so this pass stays
            // un-paginated, but it does no PDF / plan / customer work.
            $lightInvoices = (clone $baseInvoiceQuery)
                ->orderByDesc('id')
                ->get(['id', 'order_id', 'cust_id', 'status', 'net_amt', 'due_date']);

            try {
                $creditBalance = PartnerCreditService::remainingPurchaseAllowance((int) $partner->id);
            } catch (\Throwable $e) {
                Log::warning('b2b_billing_credit_balance_failed', [
                    'partner_id' => (int) $partnerId,
                    'error' => $e->getMessage(),
                ]);
                $creditBalance = 0.0;
            }

            $orderIds = $lightInvoices->pluck('order_id')->filter()->map(fn ($id) => (int) $id)->unique()->values()->all();

            // Batched lookups (one query each) shared by the light pass and the page rows.
            $ordersById = $orderIds === []
                ? collect()
                : $this->order->newQuery()->whereIn('id', $orderIds)->get()->keyBy('id');
            $refundStatusByOrderId = $this->buildInvoiceRefundStatusByOrderId($orderIds);
            $paidInvoiceIds = $this->buildPaidInvoiceIdSet(
                $lightInvoices->pluck('id')->map(fn ($id) => (int) $id)->filter()->values()->all()
            );

            // PERF: only unpaid orders can affect the shared payment gate, so skip paid ones up front.
            $unpaidOrders = $ordersById->reject(
                fn ($o) => in_array(strtolower($o->status ?? ''), ['paid', 'success'], true) || !empty($o->razorpay_payment_id)
            );

            $partnerPaymentGate = [
                'payment_link_expired' => false,
                'payment_link_allowed' => true,
                'failed_payment_attempts' => 0,
                'remaining_attempts' => Order::PAYMENT_LINK_MAX_ATTEMPTS,
                'remaining_hrs' => 0,
                'payment_link_expires_at' => null,
                'payment_link_message' => 'You have ' . Order::PAYMENT_LINK_MAX_ATTEMPTS . ' payment attempt(s) remaining across all invoices.',
            ];

            try {
                $maxFailed = 0;
                $linkExpired = false;
                $globalExpiresAt = null;
                $globalRemainingHrs = 0;
                $maxAttempts = Order::PAYMENT_LINK_MAX_ATTEMPTS;

                foreach ($unpaidOrders as $o) {
                    $meta = $o->paymentRetryMeta();
                    $failed = (int) ($meta['attempts'] ?? 0);
                    $maxFailed = max($maxFailed, $failed);
                    if (!empty($meta['expired_at']) || !empty($meta['cooldown_expires_at']) || $failed >= $maxAttempts) {
                        $linkExpired = true;
                    }
                    if (!empty($meta['expires_at']) && !$globalExpiresAt) {
                        $globalExpiresAt = $meta['expires_at'];
                    }
                    $globalRemainingHrs = max($globalRemainingHrs, $o->paymentLinkRemainingHoursForApi());
                }

                $remaining = max(0, $maxAttempts - $maxFailed);

                $partnerPaymentGate['failed_payment_attempts'] = $maxFailed;
                $partnerPaymentGate['remaining_attempts'] = $remaining;
                $partnerPaymentGate['remaining_hrs'] = $globalRemainingHrs;
                $partnerPaymentGate['payment_link_expired'] = $linkExpired;
                $partnerPaymentGate['payment_link_allowed'] = !$linkExpired;
                $partnerPaymentGate['payment_link_message'] = 'You have ' . $remaining . ' payment attempt(s) remaining across all invoices.';
                if ($globalExpiresAt) {
                    $partnerPaymentGate['payment_link_expires_at'] = $globalExpiresAt;
                }
            } catch (\Throwable $e) {
                Log::warning('b2b_billing_partner_payment_gate_failed', [
                    'partner_id' => (int) $partnerId,
                    'error' => $e->getMessage(),
                ]);
            }

            // One status pass over all invoices: summary totals + partner attempt counters.
            // PERF: the resolved display (status + retry info) is cached per invoice id and reused by the
            // page rows below, so the status logic never runs twice for the same invoice.
            $displayById = [];
            $paidInvoices = 0.0;
            $pendingInvoices = 0.0;
            $overdueInvoices = 0.0;
            $today = now()->toDateString();

            $partnerMax = Order::PAYMENT_LINK_MAX_ATTEMPTS;
            $partnerFailed = 0;
            $partnerHrs = 0;
            $partnerRemaining = $partnerMax;
            $partnerLocked = false;

            foreach ($lightInvoices as $inv) {
                try {
                    $order = !empty($inv->order_id) ? $ordersById->get((int) $inv->order_id) : null;
                    $display = $this->resolvePartnerInvoiceDisplayStatus(
                        $inv,
                        $order,
                        $refundStatusByOrderId[(int) ($inv->order_id ?? 0)] ?? null,
                        isset($paidInvoiceIds[(int) ($inv->id ?? 0)])
                    );

                    $amount = (float) ($inv->net_amt ?? 0);
                    if ($display['status'] === 'Paid') {
                        $paidInvoices += $amount;
                    } elseif ($display['status'] !== 'Cancelled') {
                        $dueDate = $inv->due_date ?? null;
                        if ($dueDate && $dueDate < $today) {
                            $overdueInvoices += $amount;
                        } else {
                            $pendingInvoices += $amount;
                        }
                    }

                    $display = $this->applyPaymentLinkRetryToInvoiceRow(
                        $display,
                        $order instanceof Order ? $order : null,
                        $partnerPaymentGate
                    );
                    $displayById[(int) $inv->id] = $display;

                    $partnerFailed = max($partnerFailed, (int) ($display['failed_payment_attempts'] ?? 0));
                    $partnerRemaining = min($partnerRemaining, (int) ($display['remaining_attempts'] ?? $partnerMax));
                    $partnerHrs = max($partnerHrs, (int) ($display['remaining_hrs'] ?? 0));
                    if (!empty($display['payment_link_expired'])) {
                        $partnerLocked = true;
                    }
                } catch (\Throwable $e) {
                    Log::warning('b2b_billing_invoice_row_failed', [
                        'invoice_id' => $inv->id ?? null,
                        'order_id' => $inv->order_id ?? null,
                        'error' => $e->getMessage(),
                    ]);
                }
            }

            try {
                $creditUsedTotal = round(PartnerCreditService::summarizeUsedCredit((int) $partnerId), 2);
            } catch (\Throwable $e) {
                $creditUsedTotal = 0.0;
            }
            $creditLimitTotal = round((float) ($partner->credit_limit ?? 0), 2);

            $attemptsLabel = $partnerRemaining . ' of ' . $partnerMax . ' remaining';
            $attemptsMessage = 'You have ' . $partnerRemaining . ' payment attempt(s) remaining.';

            $summary = [
                ['key' => 'Paid Invoices', 'value' => '₹' . number_format($paidInvoices, 2)],
                ['key' => 'Pending Invoices', 'value' => '₹' . number_format($pendingInvoices, 2)],
                ['key' => 'Overdue Invoices', 'value' => '₹' . number_format($overdueInvoices, 2)],
                ['key' => 'Payment Attempts Remaining', 'value' => (string) $partnerRemaining],
            ];

            $paymentAttempts = [
                'failed_payment_attempts' => $partnerFailed,
                'remaining_attempts' => $partnerRemaining,
                'max_attempts' => $partnerMax,
                'remaining_hrs' => $partnerHrs,
                'remaining_attempts_label' => $attemptsLabel,
                'payment_link_expired' => $partnerLocked,
                'payment_link_allowed' => (bool) ($partnerPaymentGate['payment_link_allowed'] ?? !$partnerLocked),
                'payment_link_expires_at' => $partnerPaymentGate['payment_link_expires_at'] ?? null,
                'payment_link_message' => $attemptsMessage,
            ];

            // PERF: search runs in SQL (same pgsql_billing DB → subqueries) instead of filtering built rows in PHP.
            // Matches invoice no, order no, domain, plan name, customer name / company (case-insensitive).
            $search = trim((string) $request->input('search', ''));
            $listQuery = clone $baseInvoiceQuery;
            if ($search !== '') {
                $like = '%' . addcslashes($search, '%_\\') . '%';
                $planIds = $this->plan->newQuery()->where('name', 'ILIKE', $like)->pluck('id')->all();

                $listQuery->where(function ($q) use ($like, $partnerId, $planIds) {
                    $q->where('bill_no_full', 'ILIKE', $like)
                        ->orWhereIn('order_id', $this->order->newQuery()->select('id')
                            ->where('partner_id', $partnerId)
                            ->where(fn ($o) => $o->where('order_no', 'ILIKE', $like)
                                ->orWhere('domain_name', 'ILIKE', $like)
                                ->when($planIds, fn ($p) => $p->orWhereIn('plan_id', $planIds))))
                        ->orWhereIn('cust_id', $this->customer->newQuery()->select('id')
                            ->where('partner_id', $partnerId)
                            ->where(fn ($c) => $c->where('name', 'ILIKE', $like)->orWhere('company_name', 'ILIKE', $like)));
                });
            }

            $matchingIds = $search !== ''
                ? (clone $listQuery)->pluck('id')->map(fn ($id) => (int) $id)->all()
                : array_keys($displayById);
            $matchingStatuses = array_map(fn ($id) => $displayById[$id]['status'] ?? null, $matchingIds);

            // Chip counts follow search but not the status filter
            $statusCount = collect(['Paid', 'Pending', 'Cancelled'])
                ->merge(array_filter($matchingStatuses))
                ->unique()
                ->values()
                ->map(fn ($s) => ['key' => $s, 'value' => count(array_keys($matchingStatuses, $s, true))])
                ->all();

            // status=paid | pending,cancelled (comma separated). Display status is computed in PHP, so the
            // matching ids come from the cached light pass and the DB query is narrowed with whereIn.
            $statusFilter = collect(explode(',', strtolower((string) $request->input('status', ''))))
                ->map(fn ($s) => trim($s))
                ->filter(fn ($s) => $s !== '' && $s !== 'all')
                ->values()
                ->all();
            if ($statusFilter) {
                $statusIds = array_values(array_filter(
                    $matchingIds,
                    fn ($id) => in_array(strtolower((string) ($displayById[$id]['status'] ?? '')), $statusFilter, true)
                ));
                $listQuery->whereIn('id', $statusIds ?: [-1]);
                $total = count($statusIds);
            } else {
                $total = count($matchingIds);
            }

            // PERF: DB-level pagination — only the current page's invoice rows are fetched in full.
            // Without page_no / per_page the whole (filtered) list is returned, as before.
            $paginate = $request->filled('per_page') || $request->filled('page_no') || $request->filled('page');
            $perPage = $paginate ? max(1, min(100, (int) $request->input('per_page', 10))) : max(1, $total);
            $pageNo = $paginate ? max(1, (int) $request->input('page_no', $request->input('page', 1))) : 1;
            $paginator = $listQuery->orderByDesc('id')->paginate($perPage, ['*'], 'page', $pageNo);
            $pageInvoices = collect($paginator->items());

            // PERF: heavy lookups only for the current page — invoice PDF links (regenerates the PDF per
            // order), plans and customers — instead of for every invoice the partner has.
            $pageOrderIds = $pageInvoices->pluck('order_id')->filter()->map(fn ($id) => (int) $id)->unique()->values()->all();
            $invoiceLinksByOrderId = $this->buildOrderInvoiceLinks($pageOrderIds);

            $planIds = $ordersById->only($pageOrderIds)->pluck('plan_id')->filter()->map(fn ($id) => (int) $id)->unique()->values()->all();
            $plansById = $planIds === []
                ? collect()
                : $this->plan->newQuery()->whereIn('id', $planIds)->get()->keyBy('id');

            $custIds = $pageInvoices->pluck('cust_id')->filter()->map(fn ($id) => (int) $id)->unique()->values()->all();
            $customersById = $custIds === []
                ? collect()
                : $this->customer->newQuery()->whereIn('id', $custIds)->get()->keyBy('id');

            $partnerName = trim((string) ($partner->name ?? $partner->company_name ?? '')) ?: '—';

            $invoiceData = $pageInvoices->map(function ($invoice) use (
                $ordersById,
                $plansById,
                $customersById,
                $partnerName,
                $invoiceLinksByOrderId,
                $displayById
            ) {
                try {
                    $display = $displayById[(int) $invoice->id] ?? null;
                    if ($display === null) {
                        return null;
                    }

                    $invoiceNo = trim((string) ($invoice->bill_no_full ?? '')) ?: '—';
                    $orderIdForRow = !empty($invoice->order_id) ? (int) $invoice->order_id : null;
                    $eInvoicePdfUrl = $this->resolveInvoicePdfUrl($invoice, $orderIdForRow, $invoiceLinksByOrderId);

                    $planName = '—';
                    $domainName = '—';
                    $orderType = 'B2B';
                    $creditUsed = 0.0;
                    $order = $orderIdForRow ? $ordersById->get($orderIdForRow) : null;
                    if ($order) {
                        $domainName = trim((string) ($order->domain_name ?? '')) ?: '—';
                        $orderType = strtoupper((string) ($order->order_type ?? 'b2b'));
                        $creditUsed = (float) ($order->credit_used ?? 0);
                        $plan = !empty($order->plan_id) ? $plansById->get((int) $order->plan_id) : null;
                        if ($plan) {
                            $planName = trim((string) ($plan->title ?? $plan->name ?? '')) ?: '—';
                        }
                    }

                    $customer = !empty($invoice->cust_id) ? $customersById->get((int) $invoice->cust_id) : null;
                    $customerName = $customer
                        ? (trim((string) ($customer->name ?? $customer->company_name ?? '')) ?: '—')
                        : '—';

                    $amount = round((float) ($invoice->net_amt ?? 0), 2);
                    if ($order) {
                        $orderTotal = round((float) ($order->total_amount ?? 0), 2);
                        if ($orderTotal > 0) {
                            $amount = $orderTotal;
                        }
                    }

                    return [
                        'invoice_id' => $invoice->id ?? null,
                        'order_id' => $orderIdForRow,
                        'invoice_no' => $invoiceNo,
                        'customer_name' => $customerName,
                        'domain_name' => $domainName,
                        'plan_name' => $planName,
                        'partner_name' => $partnerName,
                        'order_type' => $orderType,
                        'amount' => $amount,
                        'formatted_amount' => '₹' . number_format($amount, 2),
                        'credit_used' => $creditUsed,
                        'status' => $display['status'],
                        'refund_status' => $display['refund_status'],
                        'can_pay' => $display['can_pay'],
                        'payment_link_allowed' => (bool) ($display['payment_link_allowed'] ?? $display['can_pay']),
                        'failed_payment_attempts' => (int) ($display['failed_payment_attempts'] ?? 0),
                        'remaining_attempts' => (int) ($display['remaining_attempts'] ?? Order::PAYMENT_LINK_MAX_ATTEMPTS),
                        'remaining_hrs' => (int) ($display['remaining_hrs'] ?? 0),
                        'expired' => (bool) ($display['payment_link_expired'] ?? false),
                        'payment_link_expired' => (bool) ($display['payment_link_expired'] ?? false),
                        'payment_link_expires_at' => $display['payment_link_expires_at'] ?? null,
                        'payment_link_message' => $display['payment_link_message'] ?? null,
                        'payment_retry' => $display['payment_retry'] ?? [
                            'payment_link_expired' => (bool) ($display['payment_link_expired'] ?? false),
                            'payment_link_allowed' => (bool) ($display['payment_link_allowed'] ?? $display['can_pay']),
                            'failed_payment_attempts' => (int) ($display['failed_payment_attempts'] ?? 0),
                            'remaining_attempts' => (int) ($display['remaining_attempts'] ?? Order::PAYMENT_LINK_MAX_ATTEMPTS),
                            'remaining_hrs' => (int) ($display['remaining_hrs'] ?? 0),
                            'payment_link_expires_at' => $display['payment_link_expires_at'] ?? null,
                            'payment_link_message' => $display['payment_link_message'] ?? null,
                        ],
                        'date' => !empty($invoice->created_at)
                            ? Carbon::parse($invoice->created_at)->format('d M Y')
                            : '—',
                        'invoice_pdf_url' => $eInvoicePdfUrl,
                        'e_invoice_pdf_url' => $eInvoicePdfUrl,
                    ];
                } catch (\Throwable $e) {
                    Log::warning('b2b_billing_invoice_row_failed', [
                        'invoice_id' => $invoice->id ?? null,
                        'order_id' => $invoice->order_id ?? null,
                        'error' => $e->getMessage(),
                    ]);

                    return null;
                }
            })->filter()->values()->all();

            $pagination = [
                'total' => $paginator->total(),
                'per_page' => $paginator->perPage(),
                'current_page' => $paginator->currentPage(),
                'last_page' => $paginator->lastPage(),
                'from' => $paginator->firstItem(),
                'to' => $paginator->lastItem(),
            ];

            return response()->json([
                'success' => true,
                'message' => 'B2B billing records fetched successfully',
                'data' => [
                    'remaining_attempts' => $partnerRemaining,
                    'remainingAttempts' => $partnerRemaining,
                    'attempts_left' => $partnerRemaining,
                    'max_attempts' => $partnerMax,
                    'maxAttempts' => $partnerMax,
                    'failed_payment_attempts' => $partnerFailed,
                    'remaining_hrs' => $partnerHrs,
                    'remaining_attempts_label' => $attemptsLabel,
                    'payment_attempts_text' => $attemptsLabel,
                    'count' => [
                        ['key' => 'Payment Attempts Remaining', 'value' => $partnerRemaining],
                        ['key' => 'Failed Payment Attempts', 'value' => $partnerFailed],
                        ['key' => 'Max Attempts', 'value' => $partnerMax],
                    ],
                    'invoice_data' => $invoiceData,
                    'status_count' => $statusCount,
                    'pagination' => $pagination,
                    'summary' => $summary,
                    'credit_balance' => '₹' . number_format($creditBalance, 2),
                    'available_balance' => round((float) $creditBalance, 2),
                    'credit_limit' => $creditLimitTotal,
                    'credit_used' => $creditUsedTotal,
                    'remaining_credit_limit' => round((float) $creditBalance, 2),
                    'payment_attempts' => $paymentAttempts,
                    'payment_retry' => array_merge($partnerPaymentGate, $paymentAttempts),
                ],
            ]);
        } catch (\Exception $e) {
            Log::error('b2b_billing_failed', [
                'partner_id' => (int) ($partnerId ?? 0),
                'error' => $e->getMessage(),
                'file' => $e->getFile(),
                'line' => $e->getLine(),
            ]);

            return response()->json([
                'success' => false,
                'message' => $e->getMessage(),
                'error_file' => basename($e->getFile()),
                'error_line' => $e->getLine(),
                'data' => [
                    'invoice_data' => [],
                    'summary' => [],
                ]
            ], 500);
        }
    }

    public function upgrade(Request $request)
    {
        try {
            // Validate plan_id presence and existence in plans table
            $validated = $request->validate([
                'partner_id' => ['nullable', 'integer'],
                'order_id' => ['nullable', 'integer', 'exists:pgsql_billing.orders,id'],
                'order_sub_id' => ['nullable', 'integer'],
                'from_plan_id' => ['nullable', 'integer'],
                'current_plan_id' => ['nullable', 'integer'],
                'plan_id' => 'required|integer|exists:pgsql_product.plans,id',
                'licenses' => 'nullable|integer|min:1',
                'new_plan_id' => 'nullable|integer|exists:pgsql_product.plans,id',
                'provider_id' => ['nullable', 'integer'],
            ]);

            $partnerId = (int) ($validated['partner_id']
                ?? $request->input('partner_id', $request->input('partnerId')));
            if ($partnerId <= 0 && !empty($validated['order_id'])) {
                $partnerId = (int) (Order::query()->whereKey((int) $validated['order_id'])->value('partner_id') ?? 0);
            }
            $partnerDiscount = \App\Support\PartnerDiscountType::resolveForPartner($partnerId);
            $partnerDiscountType = $partnerDiscount['type'];
            $partnerDiscountTypeLabel = $partnerDiscount['label'];

            // --- CRITICAL: Get the CURRENT plan (the one being upgraded FROM) ---
            // This is the plan the user currently has, NOT the plan they want to upgrade TO
            $currentPlanId = (int) ($validated['plan_id']);
            $currentPlan = Plan::with(['provider'])->find($currentPlanId);

            if (!$currentPlan) {
                return response()->json([
                    'success' => false,
                    'message' => 'Current plan not found',
                ], 404);
            }

            // --- CRITICAL: Get the TARGET plan (the one user wants to upgrade TO) ---
            // This comes from new_plan_id or from the plan selection
            $targetPlanId = (int) ($validated['new_plan_id'] ?? $request->input('target_plan_id', 0));

            // If target_plan_id is not provided, we need to find higher plans
            $srNo = (int) ($currentPlan->sr_no ?? 0);
            $currentPrice = (float) ($currentPlan->price ?? $currentPlan->actual_price ?? 0);
            $providerId = (int) ($currentPlan->provider_id ?? 0);

            $currentPriceMeta = \App\Support\PartnerDiscountType::fromPlan(
                $currentPlan,
                $partnerDiscountType
            );

            // --- FIX: Get the target plan details for the response ---
            $targetPlan = null;
            if ($targetPlanId > 0) {
                $targetPlan = Plan::with(['provider'])->find($targetPlanId);
            }

            // Current plan details (what user currently has)
            $currentPlanResult = [
                'id' => $currentPlan->id,
                'plan_id' => $currentPlan->id,
                'name' => $currentPlan->name ?? $currentPlan->title ?? '-',
                'title' => $currentPlan->title ?? $currentPlan->name ?? '-',
                'sr_no' => $srNo,
                'provider_id' => $currentPlan->provider_id,
                'provider_name' => optional($currentPlan->provider)->name ?? '',
                'price' => $this->formatPlanPriceValue($currentPriceMeta['price']),
                'amount' => $this->formatPlanPriceValue($currentPriceMeta['price']),
                'formatted_price' => $this->formatPlanPrice($currentPriceMeta['price']),
                'price_type' => $currentPriceMeta['price_type'],
                'price_type_label' => $currentPriceMeta['price_type_label'],
                'remaining_days' => null,
                'current_licenses' => null,
                'remaining_value' => null,
                'pro_rata_adjustment' => null,
                'order_sub_id' => null,
            ];

            // --- FIX: Build target plan result ---
            $targetPlanResult = null;
            if ($targetPlan) {
                $targetPriceMeta = \App\Support\PartnerDiscountType::fromPlan(
                    $targetPlan,
                    $partnerDiscountType
                );
                $targetPlanResult = [
                    'id' => $targetPlan->id,
                    'plan_id' => $targetPlan->id,
                    'name' => $targetPlan->name ?? $targetPlan->title ?? '-',
                    'title' => $targetPlan->title ?? $targetPlan->name ?? '-',
                    'sr_no' => $targetPlan->sr_no,
                    'provider_id' => $targetPlan->provider_id,
                    'provider_name' => optional($targetPlan->provider)->name ?? '',
                    'price' => $this->formatPlanPriceValue($targetPriceMeta['price']),
                    'amount' => $this->formatPlanPriceValue($targetPriceMeta['price']),
                    'formatted_price' => $this->formatPlanPrice($targetPriceMeta['price']),
                    'price_type' => $targetPriceMeta['price_type'],
                    'price_type_label' => $targetPriceMeta['price_type_label'],
                    'features' => $targetPlan->getFeaturesArrayAttribute(),
                    'billing_cycle' => $targetPlan->billing_cycle,
                    'customer_limit' => $targetPlan->customer_limit,
                    'storage' => $targetPlan->storage,
                    'plan_type' => $targetPlan->plan_type,
                ];
            }

            $proration = null;
            if (!empty($validated['order_id'])) {
                $sourceOrder = Order::query()->find((int) $validated['order_id']);
                if ($sourceOrder) {
                    [$orderSubId, $fromPlanId] = $this->resolveUpgradeSourceLineHints($request, $validated);
                    if ($fromPlanId <= 0) {
                        $fromPlanId = $currentPlanId;
                    }
                    $sourceItemQuery = OrderItem::query()
                        ->where('order_id', (int) $sourceOrder->id)
                        ->where(function ($q) {
                            $q->whereNull('status')->orWhere('status', '!=', 'delete');
                        });
                    if ($orderSubId > 0) {
                        $sourceItemQuery->whereKey($orderSubId);
                    } elseif ($fromPlanId > 0) {
                        $sourceItemQuery->where('plan_id', $fromPlanId);
                    }
                    $sourceItem = $sourceItemQuery->orderBy('id')->first();
                    $upgradeLicenses = !empty($validated['licenses'])
                        ? max(1, (int) $validated['licenses'])
                        : max(1, (int) ($sourceItem->quantity ?? $sourceOrder->quantity ?? 1));
                    $newUnitPrice = 0.0;
                    if ($targetPlanId > 0) {
                        $newPlan = Plan::query()->find($targetPlanId);
                        if ($newPlan) {
                            $newPriceMeta = \App\Support\PartnerDiscountType::fromPlan(
                                $newPlan,
                                $partnerDiscountType
                            );
                            $newUnitPrice = (float) $newPriceMeta['price'];
                        }
                    }
                    $proration = app(UpgradeProrationService::class)->resolve(
                        $sourceOrder,
                        $sourceItem,
                        $newUnitPrice,
                        $upgradeLicenses,
                        18.0,
                        0.0,
                        $targetPlanId > 0 ? $targetPlanId : null
                    );
                    $currentPlanResult['remaining_days'] = (int) ($proration['remaining_days'] ?? 0);
                    $currentPlanResult['current_licenses'] = (int) ($proration['current_licenses'] ?? 0);
                    $currentPlanResult['remaining_value'] = $this->formatPlanPriceValue($proration['remaining_value'] ?? 0);
                    $currentPlanResult['pro_rata_adjustment'] = $this->formatPlanPriceValue($proration['pro_rata_adjustment'] ?? 0);
                    $currentPlanResult['order_sub_id'] = $sourceItem ? (int) $sourceItem->id : null;
                }
            }

            // --- FIX: Get UPGRADE plans (EXCLUDING the current plan) ---
            // These are plans that are HIGHER than the current plan
            $upgradePlans = Plan::query()
                ->where('provider_id', $providerId)
                ->where('status', 1)
                ->where('id', '!=', $currentPlan->id)  // EXCLUDE current plan
                ->where(function ($query) use ($srNo, $currentPrice) {
                    // Plan must be HIGHER than current plan
                    $query->where(function ($q) use ($srNo) {
                        // Higher sr_no means higher tier
                        $q->whereNotNull('sr_no')
                            ->whereRaw('CAST(sr_no AS INTEGER) > ?', [$srNo]);
                    })->orWhere(function ($q) use ($currentPrice) {
                        // Fallback: higher price (for plans without sr_no)
                        $q->whereNotNull('price')
                            ->where('price', '>', $currentPrice);
                    });
                })
                ->orderByRaw('CAST(sr_no AS INTEGER) ASC')
                ->orderBy('price', 'ASC')
                ->get()
                ->unique('id')  // Remove duplicates
                ->values()
                ->map(function ($p) use ($partnerDiscountType) {
                    $priceMeta = \App\Support\PartnerDiscountType::fromPlan($p, $partnerDiscountType);
                    $providerId = (int) ($p->provider_id ?? 0);
                    $requiresRequest = in_array($providerId, [1, 3]); // Tizzy or Google

                    return [
                        'plan_id' => $p->id,
                        'sr_no' => $p->sr_no,
                        'name' => $p->name ?? $p->title ?? '-',
                        'title' => $p->title ?? $p->name ?? '-',
                        'price' => $this->formatPlanPriceValue($priceMeta['price']),
                        'amount' => $this->formatPlanPriceValue($priceMeta['price']),
                        'formatted_price' => $this->formatPlanPrice($priceMeta['price']),
                        'price_type' => $priceMeta['price_type'],
                        'price_type_label' => $priceMeta['price_type_label'],
                        'market_price' => $this->formatPlanPriceValue($priceMeta['market_price']),
                        'formatted_market_price' => $this->formatPlanPrice($priceMeta['market_price']),
                        'distributor_price' => $this->formatPlanPriceValue($priceMeta['distributor_price']),
                        'formatted_distributor_price' => $this->formatPlanPrice($priceMeta['distributor_price']),
                        'actual_price' => $this->formatPlanPriceValue($priceMeta['actual_price']),
                        'formatted_actual_price' => $this->formatPlanPrice($priceMeta['actual_price']),
                        'features' => $p->getFeaturesArrayAttribute(),
                        'billing_cycle' => $p->billing_cycle,
                        'customer_limit' => $p->customer_limit,
                        'storage' => $p->storage,
                        'plan_type' => $p->plan_type,
                        'requires_request' => $requiresRequest,
                        'change_via' => $requiresRequest ? 'request' : 'cart',
                        'provider_name' => optional($p->provider)->name ?? '',
                    ];
                });

            // Filter out any plans that might still be the same as current (safety net)
            $upgradePlans = $upgradePlans->filter(function ($plan) use ($currentPlan) {
                return (int) $plan['plan_id'] !== (int) $currentPlan->id;
            })->values();

            // If a target plan was specified, check if it's valid and add it to the response
            $selectedTargetPlan = null;
            if ($targetPlanId > 0) {
                $selectedTargetPlan = $upgradePlans->firstWhere('plan_id', $targetPlanId);
                // If target plan not in the list (maybe it's the current plan or invalid)
                if (!$selectedTargetPlan && $targetPlan) {
                    // Still include it if it's a valid higher plan
                    $isHigher = $this->isHigherPlan($targetPlan, $currentPlanId);
                    if ($isHigher) {
                        $selectedTargetPlan = $targetPlanResult;
                    }
                }
            }

            // --- FIX: Check if provider requires request (Google/Tizzy) ---
            $isRequestBasedProvider = $this->isRequestBasedChangeProvider($providerId);
            
            // --- FIX: If Google/Tizzy, return the target plan in the response ---
            if ($isRequestBasedProvider && $targetPlanId > 0 && $targetPlan) {
                return response()->json([
                    'success' => true,
                    'message' => 'Upgrade plan details fetched successfully',
                    'data' => [
                        'request_id' => null,
                        'action' => 'upgrade',
                        'action_type' => 'upgrade',
                        'current_plan' => $currentPlanResult,
                        'current_plan_id' => $currentPlanId,
                        'currentplandetails' => $currentPlanResult,
                        'selected_plan' => $targetPlanResult,
                        'selected_plan_id' => $targetPlanId,
                        'requested_plan' => $targetPlanResult,
                        'plans' => $targetPlanResult ? [$targetPlanResult] : [],
                        'provider_id' => $providerId,
                        'provider_name' => optional($currentPlan->provider)->name ?? '',
                        'requires_request' => true,
                        'change_via' => 'request',
                        'request_endpoint' => '/api/partner/upgrade-request',
                        'request_message' => 'This ' . (optional($currentPlan->provider)->name ?? '') . ' upgrade requires a request for approval.',
                        'has_upgrades' => $upgradePlans->isNotEmpty(),
                        'upgrade_count' => $upgradePlans->count(),
                        'proration' => $proration,
                        'partner_discount_type' => $partnerDiscountType,
                        'partner_discount_type_label' => $partnerDiscountTypeLabel,
                        
                    ]
                ]);
            }

            return response()->json([
                'success' => true,
                'message' => 'Upgrade plan details fetched successfully',
                'data' => [
                    'current_plan' => $currentPlanResult,
                    'upgrade_plans' => $upgradePlans,
                    'selected_plan' => $selectedTargetPlan,
                    'has_upgrades' => $upgradePlans->isNotEmpty(),
                    'upgrade_count' => $upgradePlans->count(),
                    'proration' => $proration,
                    'partner_discount_type' => $partnerDiscountType,
                    'partner_discount_type_label' => $partnerDiscountTypeLabel,
                    'provider_id' => $providerId,
                    'requires_request' => $this->isRequestBasedChangeProvider($providerId),
                    'change_via' => $this->isRequestBasedChangeProvider($providerId) ? 'request' : 'cart',
                    'provider_name' => $providerId === 1 ? 'Tizzy' : ($providerId === 3 ? 'Google' : 'Microsoft'),
                ]
            ]);
        } catch (\Illuminate\Validation\ValidationException $e) {
            return response()->json([
                'success' => false,
                'message' => 'Validation Error',
                'errors'  => $e->errors()
            ], 422);
        } catch (\Exception $e) {
            return response()->json([
                'success' => false,
                'message' => 'Server Error',
                'error' => $e->getMessage()
            ], 500);
        }
    }
    public function downgrade(Request $request)
    {
        try {

            $validated = $request->validate([
                'partner_id' => ['nullable', 'integer'],
                'plan_id' => 'required|integer|exists:pgsql_product.plans,id',
                'variant_id' => ['nullable', 'integer'],
            ]);

            $partnerId = (int) ($validated['partner_id']
                ?? $request->input('partner_id', $request->input('partnerId')));
            $partnerDiscount = \App\Support\PartnerDiscountType::resolveForPartner($partnerId);
            $partnerDiscountType = $partnerDiscount['type'];
            $partnerDiscountTypeLabel = $partnerDiscount['label'];

            $currentPlan = Plan::with(['apps', 'provider'])->find($validated['plan_id']);

            if (!$currentPlan) {
                return response()->json([
                    'success' => false,
                    'message' => 'Plan not found',
                ], 404);
            }

            $currentPriceMeta = \App\Support\PartnerDiscountType::fromPlan(
                $currentPlan,
                $partnerDiscountType
            );
            $currentPrice = (float) $currentPriceMeta['price'];
            $providerId = (int) ($currentPlan->provider_id ?? 0);
            $variantId = (int) ($validated['variant_id'] ?? $currentPlan->variant_id ?? 0);

            if ($providerId <= 0) {
                return response()->json([
                    'success' => false,
                    'message' => 'Current plan has no provider configured.',
                ], 422);
            }

            // Only cheaper plans (partner price must be below current plan).
            // Lower sr_no alone is not a downgrade if the price is higher.
            $downgradeQuery = Plan::with(['provider', 'category', 'apps'])
                ->where('provider_id', $providerId)
                ->where('id', '!=', (int) $currentPlan->id)
                ->where(function ($q) {
                    $q->where('status', 1)
                        ->orWhereNull('status');
                });

            if ($variantId > 0) {
                $downgradeQuery->where('variant_id', $variantId);
            }

            if ($currentPrice > 0) {
                $downgradeQuery->where(function ($q) use ($currentPrice) {
                    $q->where(function ($priceQ) use ($currentPrice) {
                        $priceQ->whereNotNull('price')
                            ->where('price', '>', 0)
                            ->where('price', '<', $currentPrice);
                    })->orWhere(function ($priceQ) use ($currentPrice) {
                        $priceQ->whereNotNull('actual_price')
                            ->where('actual_price', '>', 0)
                            ->where('actual_price', '<', $currentPrice);
                    });
                });
            } else {
                $downgradeQuery->whereRaw('1 = 0');
            }

            $downgradePlans = $downgradeQuery
                ->orderBy('price', 'asc')
                ->orderBy('name', 'asc')
                ->get()
                ->unique('id')
                ->values()
                ->filter(function ($p) use ($partnerDiscountType, $currentPrice) {
                    $rowPrice = (float) (\App\Support\PartnerDiscountType::fromPlan($p, $partnerDiscountType)['price'] ?? 0);

                    return $currentPrice > 0 && $rowPrice > 0 && $rowPrice < $currentPrice;
                })
                ->map(function ($p) use ($partnerDiscountType) {
                    $priceMeta = \App\Support\PartnerDiscountType::fromPlan($p, $partnerDiscountType);

                    return [
                        'plan_id'       => $p->id,
                        'name'          => $p->name,
                        'title'         => $p->title,
                        'slug'          => $p->slug,
                        'sr_no'         => $p->sr_no,
                        'category'      => optional($p->category)->name ?? '-',
                        'provider'      => optional($p->provider)->name ?? '-',
                        'variant_id'    => $p->variant_id,
                        'plan_type'     => $p->plan_type,
                        'storage'       => $p->storage,
                        'price'         => $this->formatPlanPriceValue($priceMeta['price']),
                        'amount'        => $this->formatPlanPriceValue($priceMeta['price']),
                        'formatted_price' => $this->formatPlanPrice($priceMeta['price']),
                        'price_type'    => $priceMeta['price_type'],
                        'price_type_label' => $priceMeta['price_type_label'],
                        'actual_price'  => $this->formatPlanPriceValue($priceMeta['actual_price']),
                        'formatted_actual_price' => $this->formatPlanPrice($priceMeta['actual_price']),
                        'market_price'  => $this->formatPlanPriceValue($priceMeta['market_price']),
                        'formatted_market_price' => $this->formatPlanPrice($priceMeta['market_price']),
                        'distributor_price' => $this->formatPlanPriceValue($priceMeta['distributor_price']),
                        'formatted_distributor_price' => $this->formatPlanPrice($priceMeta['distributor_price']),
                        'billing_cycle' => $p->billing_cycle,
                        'features'      => $p->getFeaturesArrayAttribute(),
                        'apps'          => $p->apps->map(fn($a) => [
                            'id' => $a->id,
                            'name' => $a->name,
                        ]),
                        'customer_limit' => $p->customer_limit,
                        'description'   => $p->description,
                        'status'        => $p->status,
                    ];
                })
                ->values();

            return response()->json([
                'success' => true,
                'message' => 'Downgrade plan fetched successfully',
                'data' => [
                    'plan_id' => $currentPlan->id,
                    'variant_id' => $variantId > 0 ? $variantId : null,
                    'current_plan' => [
                        'plan_id' => $currentPlan->id,
                        'name' => $currentPlan->name,
                        'sr_no' => $currentPlan->sr_no,
                        'variant_id' => $variantId > 0 ? $variantId : ((int) ($currentPlan->variant_id ?? 0) ?: null),
                        'price' => $this->formatPlanPriceValue($currentPriceMeta['price']),
                        'amount' => $this->formatPlanPriceValue($currentPriceMeta['price']),
                        'formatted_price' => $this->formatPlanPrice($currentPriceMeta['price']),
                        'price_type' => $currentPriceMeta['price_type'],
                        'price_type_label' => $currentPriceMeta['price_type_label'],
                        'provider_id' => $providerId,
                        'provider' => optional($currentPlan->provider)->name ?? '-',
                    ],
                    'plans' => $downgradePlans,
                    'downgrade_plans' => $downgradePlans,
                    'count' => $downgradePlans->count(),
                    'partner_discount_type' => $partnerDiscountType,
                    'partner_discount_type_label' => $partnerDiscountTypeLabel,
                ],
            ]);
        } catch (\Exception $e) {
            return response()->json([
                'success' => false,
                'message' => 'Server Error',
                'error' => $e->getMessage(),
            ], 500);
        }
    }

    // Transfer code API - Simple way, only 3 fields in data response

    public function ordersAadhaarInit(Request $request)
    {
        $request->validate([
            'order_id' => ['required', 'integer'],
            'aadhaar_number' => ['required', 'digits:12'],
        ]);

        if (!Schema::hasTable('orders') || !Schema::hasTable('order_po_details')) {
            return response()->json(['success' => false, 'message' => 'Required tables are not available.'], 422);
        }
        $orderId = (int) $request->input('order_id');
        if (!$this->order->newQuery()->where('id', $orderId)->exists()) {
            return response()->json(['success' => false, 'message' => 'Order not found.'], 404);
        }

        $aadhaar = (string) $request->input('aadhaar_number');
        $masked = 'XXXXXXXX' . substr($aadhaar, -4);
        $refNo = 'AADH-' . strtoupper(Str::random(8));

        $payload = [
            'journey_status' => 'otp_pending',
            'aadhaar_masked' => $masked,
            'aadhaar_ref_no' => $refNo,
            'aadhar_verified' => 0,
            'updated_at' => now(),
        ];

        $row = $this->orderPoDetail->newQuery()->where('order_id', $orderId)->first();
        if ($row) {
            $this->orderPoDetail->newQuery()->where('order_id', $orderId)->update($payload);
        } else {
            $this->orderPoDetail->newQuery()->insert(array_merge(['order_id' => $orderId, 'created_at' => now()], $payload));
        }

        $this->order->newQuery()->where('id', $orderId)->update([
            'status' => 'pending',
            'updated_at' => now(),
        ]);

        return response()->json([
            'success' => true,
            'message' => 'Aadhaar init successful.',
            'data' => [
                'aadhaar_masked' => $masked,
                'aadhaar_ref_no' => $refNo,
                'mobile' => 'xxxxxxxx34',
            ],
        ]);
    }

    public function creditRequest(Request $request)
    {
        $validated = $request->validate([
            'partner_id' => ['required', 'exists:pgsql_auth.partners,id'],
            'order_id' => ['nullable'],
            'main_cart_id' => ['nullable', 'required_without:order_id', 'exists:pgsql_billing.carts,id'],
            'requested_amount' => ['required', 'numeric', 'min:1'],
            'remarks' => ['nullable', 'string'],
            'admin_note' => ['nullable', 'string'],
        ]);

        // Fix: map main_cart_id to cart_id in array if present
        $data = [
            'partner_id' => $validated['partner_id'],
            'order_id' => $validated['order_id'] ?? null,
            'requested_amount' => $validated['requested_amount'],
            'remarks' => $validated['remarks'] ?? null,
            'admin_note' => $validated['admin_note'] ?? null,
            'status' => 'pending',
        ];
        if (array_key_exists('main_cart_id', $validated) && $validated['main_cart_id']) {
            $data['cart_id'] = $validated['main_cart_id'];
        } else {
            $data['cart_id'] = null;
        }

        $creditRequest = CreditRequest::create($data);

        return response()->json([
            'success' => true,
            'message' => 'Credit request created successfully',
            'data' => $creditRequest
        ], 201);
    }

    public function postTransferCode(Request $request): JsonResponse
    {
        return $this->transferCodeSimple($request, false);
    }

    private function transferCodeSimple(Request $request, bool $fromQuery): JsonResponse
    {
        $type = $fromQuery ? $request->query('provider_type') : $request->input('provider_type');

        if (!in_array((int)$type, [1, 2, 3], true)) {
            return response()->json([
                'success' => false,
                'message' => 'Invalid type',
            ], 422);
        }

        // get admin_settings (id 1 or oldest)
        $settings = $this->adminSetting->newQuery()->where('id', 1)->first();

        if (!$settings) {
            return response()->json([
                'success' => false,
                'message' => 'Admin settings not found.',
            ], 404);
        }

        $field = '';
        $code = null;

        if ((int)$type === 1) { // Tizzy
            $Provider_Type = 'Tizzy';
            $field = $settings->transfert_code;
        } elseif ((int)$type === 2) { // Microsoft
            $Provider_Type = 'Microsoft';
            $field = $settings->microsoft_transfer_code;
        } else { // Google
            $Provider_Type = 'Google';
            $field = $settings->google_transfer_code;
        }

        if (Schema::hasColumn('admin_settings', $field)) {
            $code = $settings->{$field} ?? null;
        }

        return response()->json([
            'success' => true,
            'data' => [
                'Provider_Type' => $Provider_Type,
                'code' => $field,
                'transfer_code' => $code,
            ],
        ]);
    }

