    public function account_details(Request $request)
    {
        $request->validate([
            'partner_id' => ['required', 'integer', 'exists:pgsql_auth.partners,id'],
        ]);

        $partner = Partner::query()->whereKey((int) $request->partner_id)->first();
        if (!$partner) {
            return response()->json([
                'success' => false,
                'message' => 'Partner not found.',
                'data' => null,
            ], 404);
        }

        $companyAddress = trim((string) ($partner->company_address ?? ''));
        if ($companyAddress === '') {
            $companyAddress = trim((string) ($partner->address ?? ''));
        }

        $addressParts = array_values(array_filter([
            $companyAddress,
            trim((string) ($partner->city ?? '')),
            trim((string) ($partner->state ?? '')),
            trim((string) ($partner->pincode ?? $partner->postcode ?? '')),
            trim((string) ($partner->country ?? '')),
        ], static fn($part) => $part !== ''));

        $status = strtolower(trim((string) ($partner->status ?? '')));
        $isVerified = in_array($status, ['approved', 'active', 'verified'], true)
            || (bool) ($partner->email_verified ?? false);

        $partnerCode = 'P' . str_pad((string) $partner->id, 6, '0', STR_PAD_LEFT);

        $creditLimit = round((float) ($partner->credit_limit ?? 0), 2);
        $creditUsed = round(PartnerCreditService::summarizeUsedCredit((int) $partner->id), 2);
        $availableBalance = round(PartnerCreditService::remainingPurchaseAllowance((int) $partner->id), 2);

        $role = 'Admin';
        $name = (string) ($partner->name ?? '');
        $email = (string) ($partner->email ?? '');
        $mobile = (string) ($partner->mobile ?? '');

        // If a partner user is logged in, show their personal details instead
        $partnerUserId = $request->input('partner_user_id');
        if (!$partnerUserId && $request->user()?->currentAccessToken()?->name === 'mobile-partner-user') {
            $session = \App\Models\PartnerSession::where('token_id', $request->user()->currentAccessToken()->id)->first();
            $partnerUserId = $session?->partner_user_id;
        }

        if ($partnerUserId) {
            $partnerUser = \App\Models\PartnerUser::find($partnerUserId);
            if ($partnerUser) {
                $role = (string) ($partnerUser->designation ?? 'User');
                $name = (string) ($partnerUser->name ?? $name);
                $email = (string) ($partnerUser->email ?? $email);
                $mobile = (string) ($partnerUser->mobile ?? $mobile);
            }
        }

        return response()->json([
            'success' => true,
            'message' => 'Partner account details fetched successfully.',
            'data' => [
                'partner_id' => (int) $partner->id,
                'partner_code' => $partnerCode,
                'role' => $role,
                'name' => $name,
                'email' => $email,
                'mobile' => $mobile,
                'gstin' => (string) ($partner->gstin ?? ''),
                'pan_no' => (string) ($partner->pan_no ?? ''),
                'company_name' => (string) ($partner->company_name ?? ''),
                'company_address' => $companyAddress,
                'full_address' => implode(', ', $addressParts),
                'country' => (string) ($partner->country ?? ''),
                'state' => (string) ($partner->state ?? ''),
                'city' => (string) ($partner->city ?? ''),
                'pincode' => (string) ($partner->pincode ?? $partner->postcode ?? ''),
                'status' => (string) ($partner->status ?? ''),
                'is_verified' => $isVerified,
                'email_verified' => (bool) ($partner->email_verified ?? false),
                'wallet_balance' => $availableBalance,
                'available_balance' => $availableBalance,
                'credit_limit' => $creditLimit,
                'credit_used' => $creditUsed,
                'remaining_credit_limit' => $availableBalance,
                'credit_limit_reached' => PartnerCreditService::isCreditLimitFullyUsed((int) $partner->id),
            ],
        ], 200);
    }

    public function partnerApproval(Request $request)
    {
        $request->validate([
            'partner_id' => ['required', 'integer'],
        ]);

        $partner = Partner::find($request->partner_id);

        if (!$partner) {
            return response()->json([
                'success' => false,
                'message' => 'Partner not found.',
            ], 404);
        }

        $isApproved = $partner->status === 'approved';
        $token = null;
           
        if ($isApproved) {
            $newAccessToken = $partner->createToken('mobile');
           
            $token = $newAccessToken->plainTextToken;
            $partner->update([
                'current_session_token' => 'api:' . $newAccessToken->accessToken->id,
            ]);
        }

        return response()->json([
            'success' => true,
            'message' => $isApproved
                ? 'Partner approved and logged in successfully.'
                : 'Partner approval status fetched successfully.',
            'data' => [
                'partner_id' => $partner->id,
                'status' => $partner->status,
                'is_approved' => $isApproved,
                'token' => $token,
                'token_type' => $token ? 'Bearer' : null,
            ],
        ], 200);
    }


    public function subscriptionDetails(Request $request)
    {
        $request->validate([
            'order_id' => ['required', 'integer'],
        ]);

        $orderId = (int) $request->order_id;
        $order = Order::where('id', $orderId)->first();
        $licenseAddHistoryOrders = collect();

        // Same as orderIndex: an activated license-add child is shown on the parent
        // with combined licenses for the same plan — never as a separate subscription.
        if ($order && $this->isLicenseAddOrder($order)) {
            $parentId = (int) ($order->parent_order_id ?? 0);
            if ($parentId <= 0 && !empty($order->domain_name) && !empty($order->partner_id)) {
                $parentId = (int) (Order::query()
                    ->where('partner_id', $order->partner_id)
                    ->where('domain_name', $order->domain_name)
                    ->where('id', '!=', $order->id)
                    ->where(function ($q) {
                        $q->whereNull('parent_order_id')->orWhere('parent_order_id', 0);
                    })
                    ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('draft', 'cancelled', 'canceled', 'failed', 'rejected')")
                    ->orderBy('id')
                    ->value('id') ?? 0);
                if ($parentId > 0) {
                    Order::where('id', $order->id)->update(['parent_order_id' => $parentId]);
                    $order->parent_order_id = $parentId;
                }
            }
            if ($parentId > 0 && $this->isActivatedLicenseAddStatus($order)) {
                $parentOrder = Order::where('id', $parentId)->first();
                // Same as orderIndex: only redirect/merge when plan_id matches parent
                if (
                    $parentOrder
                    && (int) ($parentOrder->plan_id ?? 0) > 0
                    && (int) ($parentOrder->plan_id ?? 0) === (int) ($order->plan_id ?? 0)
                ) {
                    $order = $parentOrder;
                    $orderId = (int) $parentOrder->id;
                }
            }
        }

        if ($order && !$this->isLicenseAddOrder($order)) {
            $licenseAddHistoryOrders = $this->loadActivatedLicenseAddChildren($orderId, $order);
        }

        // Same SQL as merge check: activated addon children by parent_order_id
        // (do not rely only on helper filters — order-list uses this shape).
        $directAddonChildren = Order::query()
            ->where('parent_order_id', $orderId)
            ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) IN ('completed', 'paid', 'success', 'active')")
            ->whereRaw("LOWER(TRIM(COALESCE(order_category, ''))) = 'addon'")
            ->orderBy('id')
            ->get();
        $licenseAddHistoryOrders = collect($licenseAddHistoryOrders)
            ->concat($directAddonChildren)
            ->unique('id')
            ->values();

        $orderItems = OrderItem::where('order_id', $orderId)
            ->where(function ($q) {
                $q->whereNull('status')
                    ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted')");
            })
            ->orderBy('id')
            ->get();

        // Multi-copy bug: same plan line inserted multiple times on one order.
        // Keep one row per plan_id + quantity + item status (prefer latest id).
        $orderItems = $this->uniqueSubscriptionOrderItems($orderItems);

        // Parent qty before merge (SQL parent_item_qty).
        $parentQtyBeforeMergeByItemId = [];
        foreach ($orderItems as $oi) {
            $parentQtyBeforeMergeByItemId[(int) ($oi->id ?? 0)] = max(1, (int) ($oi->quantity ?? 1));
        }

        // Prefer orders.plan_id; fall back to first item plan (orderIndex uses both).
        $parentPlanId = (int) ($order->plan_id ?? 0);
        if ($parentPlanId <= 0) {
            foreach ($orderItems as $oi) {
                $pid = (int) ($oi->plan_id ?? 0);
                if ($pid > 0) {
                    $parentPlanId = $pid;
                    break;
                }
            }
        }
        // Keep activated addon children (same plan on order OR on order_items).
        $licenseAddHistoryOrders = $licenseAddHistoryOrders->filter(function ($child) use ($parentPlanId) {
            $childPlanId = (int) ($child->plan_id ?? 0);
            if ($parentPlanId <= 0) {
                return true;
            }
            if ($childPlanId <= 0 || $childPlanId === $parentPlanId) {
                return true;
            }

            return OrderItem::query()
                ->where('order_id', (int) $child->id)
                ->where('plan_id', $parentPlanId)
                ->where(function ($q) {
                    $q->whereNull('status')
                        ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted')");
                })
                ->exists();
        })->values();
        $hasMergedLicenseAdd = $licenseAddHistoryOrders->isNotEmpty();
        $mergedExtraLicenses = 0;
        if ($hasMergedLicenseAdd) {
            foreach ($licenseAddHistoryOrders as $child) {
                $childItems = OrderItem::query()
                    ->where('order_id', (int) $child->id)
                    ->where(function ($q) {
                        $q->whereNull('status')
                            ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted')");
                    })
                    ->get();
                $childQtySum = 0;
                foreach ($childItems as $childItem) {
                    if ((int) ($childItem->plan_id ?? 0) > 0
                        && $parentPlanId > 0
                        && (int) ($childItem->plan_id ?? 0) !== $parentPlanId) {
                        continue;
                    }
                    $childQtySum += max(1, (int) ($childItem->quantity ?? 1));
                }
                if ($childQtySum <= 0) {
                    $childQtySum = max(1, (int) ($child->quantity ?? $child->licenses ?? 1));
                }
                $mergedExtraLicenses += $childQtySum;
            }
        }
        $orderItems = $this->mergeLicenseAddItemsIntoParentItems($orderItems, $licenseAddHistoryOrders);

        if ($hasMergedLicenseAdd && $order) {
            $order->quantity = ((int) ($order->quantity ?? 1)) + $mergedExtraLicenses;
            $order->licenses = $order->quantity;
        }

        if ($order) {
            $resolvedDomain = OrderDomainHelper::resolveForOrder(
                $order,
                (int) ($order->cart_id ?? $order->source_cart_id ?? 0)
            );
            if ($resolvedDomain !== '') {
                OrderDomainHelper::persistOnOrderIfMissing((int) $order->id, $resolvedDomain);
                $order->domain_name = $resolvedDomain;
            }
        }

        $customer = Customer::where('id', $order->user_id)->first();

        $today = now();

        $supersededByParentId = $this->buildSupersededSubscriptionStatusByParentId([$orderId]);
        $replacement = $supersededByParentId[$orderId] ?? null;
        $partial = $this->resolvePartialReplacementForOrder($order, $orderItems, $replacement);
        $remainingLicenses = $partial['remaining_licenses'];
        $isFullyReplaced = $partial['is_fully_replaced'];
        // License-add seats are additive — never let upgrade leftover math wipe the merge.
        if ($hasMergedLicenseAdd && $mergedExtraLicenses > 0) {
            $mergedLiveQty = (int) $orderItems->sum(fn($row) => max(1, (int) ($row->quantity ?? 1)));
            if ($mergedLiveQty <= 0) {
                $mergedLiveQty = max(1, (int) ($order->quantity ?? $order->licenses ?? 1));
            }
            $remainingLicenses = max($remainingLicenses, $mergedLiveQty);
            $partial['remaining_licenses'] = $remainingLicenses;
            $partial['live_qty'] = max((int) ($partial['live_qty'] ?? 0), $mergedLiveQty);
            $isFullyReplaced = false;
        }
        $treatAsLive = $remainingLicenses > 0;
        $supersededStatus = $treatAsLive ? null : $partial['superseded_status'];

        $orderLevel = $this->resolveSubscriptionOrderLevelStatus(
            $order,
            $today,
            $orderItems,
            $supersededStatus,
            $treatAsLive
        );
        $status = $orderLevel['status'];
        // Keep Pending and Processing distinct. Apply change-order labels only when THIS
        // order is the upgrade/downgrade/renewal order (plan-wise parents stay Active/Expiring).
        $orderRawStatus = strtolower(trim((string) ($order->status ?? '')));
        $orderRawCategory = strtolower(trim((string) ($order->order_category ?? '')));
        $isCancelledOrder = in_array($orderRawStatus, ['cancelled', 'canceled', 'rejected'], true);
        $isChangeOrderSelf = in_array($orderRawCategory, ['upgrade', 'downgrade', 'renewal', 'renew'], true)
            || str_starts_with(strtoupper(trim((string) ($order->order_no ?? ''))), 'RN');
        if ($isCancelledOrder) {
            $status = 'Cancelled';
        } elseif ($isChangeOrderSelf) {
            $status = $this->preferPlanWiseStatus(
                $order,
                $orderRawStatus,
                $orderRawCategory === 'upgrade' ? 'upgrade_pending' : (
                    $orderRawCategory === 'downgrade' ? 'downgrade_pending' : (
                        in_array($orderRawCategory, ['renewal', 'renew'], true) ? 'renewal_pending' : ''
                    )
                ),
                $status,
                false
            );
        } elseif ($orderRawStatus === 'upgraded' || $orderRawCategory === 'upgraded') {
            // Whole order marked upgraded only when fully replaced.
            if (!$treatAsLive) {
                $status = 'Upgraded';
            }
        } elseif ($orderRawStatus === 'downgraded' || $orderRawCategory === 'downgraded') {
            if (!$treatAsLive) {
                $status = 'Downgraded';
            }
        } elseif ($orderRawStatus === 'renewed' || $orderRawCategory === 'renewed') {
            if (!$treatAsLive) {
                $status = 'Renewed';
            }
        } elseif ($orderRawStatus === 'pending' || strcasecmp((string) $status, 'Pending') === 0) {
            $status = 'Pending';
        } elseif ($orderRawStatus === 'processing' || strcasecmp((string) $status, 'Processing') === 0) {
            $status = 'Processing';
        }
        $daysToExpire = $orderLevel['days_to_expire'];
        $endDate = $orderLevel['end_date'];

        $creditNote = app(\App\Services\OrderCancellationCreditNoteService::class)
            ->resolveCreditNotesByOrderIds([(int) $order->id])[(int) $order->id] ?? null;
        $hasCreditNote = is_array($creditNote) && !empty($creditNote['credit_note_id'] ?? $creditNote['credit_note_no'] ?? null);

        $order_po_details = $this->orderPoDetail->newQuery()->where('order_id', $orderId)->first();

        $planChangeContext = $this->buildPlanChangeContextForOrders([$orderId]);
        $childChangeOrders = $planChangeContext['child_change_orders_by_parent']->get($orderId, collect());
        $childOrderItems = $planChangeContext['child_order_items'];
        $newPlansById = $planChangeContext['new_plans_by_id'];

        $upgradeStateBySourceSubId = $this->buildUpgradeStateBySourceSubId(
            $orderId,
            $childChangeOrders,
            $childOrderItems,
            $newPlansById
        );

        // Plans info
        $plansInfo = [];

        foreach ($orderItems as $item) {

            $plan = Plan::where('id', $item->plan_id)->first();
            $provider = optional($plan)->provider;
            $originalQty = max(1, (int) ($item->quantity ?? 1));
            $itemStatus = strtolower(trim((string) ($item->status ?? 'active')));
            if ($itemStatus === '') {
                $itemStatus = 'active';
            }

            $pendingRenewalQtyForLine = max(
                (int) ($partial['pending_renewal_licenses'] ?? 0),
                is_array($replacement) ? (int) ($replacement['pending_renewal_qty'] ?? 0) : 0
            );
            if ($itemStatus === 'renewed' && $treatAsLive && $pendingRenewalQtyForLine > 0) {
                continue;
            }

            // Calculate moved/upgraded licenses from child orders
            $childMovedQty = 0;
            foreach ($childChangeOrders as $co) {
                if (in_array(strtolower(trim((string) ($co->status ?? ''))), ['cancelled', 'canceled', 'rejected', 'failed'], true)) {
                    continue;
                }
                // Addon seats are additive — never treat as upgrade/moved qty.
                if ($this->isLicenseAddOrder($co)
                    || strtolower(trim((string) ($co->order_category ?? ''))) === 'addon') {
                    continue;
                }
                $coCategory = strtolower(trim((string) ($co->order_category ?? '')));
                $coOrderNo = strtoupper(trim((string) ($co->order_no ?? '')));
                $isChildUpgrade = in_array($coCategory, ['upgrade', 'upgraded', 'partial_upgrade', 'partial', 'partial upgrade', 'upgrade service', 'downgrade', 'downgraded', 'partial_downgrade', 'renewal', 'renew'], true)
                    || str_starts_with($coOrderNo, 'CH')
                    || str_starts_with($coOrderNo, 'UPG')
                    || str_starts_with($coOrderNo, 'RN')
                    || $this->isPartialUpgradeOrder($co, $coCategory);

                if (!$isChildUpgrade) {
                    continue;
                }

                $matchesItem = false;
                $coSubId = (int) ($co->parent_order_sub_id ?? 0);
                $coPrevPlan = (int) ($co->previous_plan_id ?? 0);
                if ($coSubId > 0 && $coSubId === (int) $item->id) {
                    $matchesItem = true;
                } elseif ($coPrevPlan > 0 && $coPrevPlan === (int) ($item->plan_id ?? $order->plan_id ?? 0)) {
                    $matchesItem = true;
                } elseif ($orderItems->count() <= 1) {
                    $matchesItem = true;
                }
                if ($matchesItem) {
                    $coChildItem = optional($childOrderItems->get((int) $co->id))->first();
                    $cQty = max(1, (int) ($coChildItem->quantity ?? $co->quantity ?? 1));
                    $childMovedQty += $cQty;
                }
            }

            $qty = $originalQty;
            if ($childMovedQty > 0 && !$hasMergedLicenseAdd) {
                $qty = max(0, $originalQty - $childMovedQty);
            } elseif (
                !$hasMergedLicenseAdd
                && $remainingLicenses > 0
                && $remainingLicenses < $originalQty
                && $orderItems->count() <= 1
            ) {
                // Do not clamp after license-add merge — that was resetting e.g. 10 → 2.
                $qty = $remainingLicenses;
            }

            $displayQty = $qty > 0 ? $qty : ($isFullyReplaced ? 0 : $originalQty);

            $planChangeStatus = $this->resolvePlanChangeStatusForItem(
                $item,
                $orderId,
                $upgradeStateBySourceSubId,
                $childChangeOrders,
                $childOrderItems,
                $newPlansById
            );
            $canUpgrade = true;
            $changeOrderId = null;
            $changeOrderNo = null;
            $changeOrderStatus = null;
            $newPlanId = null;
            $newPlanName = null;

            if (in_array($itemStatus, ['upgraded', 'downgraded'], true)) {
                $canUpgrade = false;
            } elseif ($isFullyReplaced || in_array($status, ['Renewed', 'Downgraded', 'Upgraded'], true)) {
                $canUpgrade = false;
            } elseif (isset($upgradeStateBySourceSubId[(int) $item->id])) {
                $mapped = $upgradeStateBySourceSubId[(int) $item->id];
                $changeOrderId = (int) ($mapped['change_order_id'] ?? 0);
                $changeOrderNo = (string) ($mapped['change_order_no'] ?? '');
                $changeOrderStatus = (string) ($mapped['change_order_status'] ?? '');
                $newPlanId = (int) ($mapped['new_plan_id'] ?? 0);
                $newPlanName = (string) ($mapped['new_plan_name'] ?? '');
                if (in_array($planChangeStatus, [
                    'upgraded',
                    'downgraded',
                    'renewed',
                    'upgrade_pending',
                    'downgrade_pending',
                    'renewal_pending',
                ], true)) {
                    $canUpgrade = false;
                }
            } else {
                foreach ($childChangeOrders as $childOrder) {
                    $matchesLine = false;
                    $parentSubId = (int) ($childOrder->parent_order_sub_id ?? 0);
                    $childItem = optional($childOrderItems->get((int) $childOrder->id))->first();
                    $childMeta = is_array($childItem->meta ?? null) ? $childItem->meta : [];
                    $previousSubId = (int) ($childItem->previous_order_sub_id ?? $childMeta['previous_order_sub_id'] ?? 0);
                    $isRenewalChild = $this->isRenewalChangeOrder($childOrder);
                    if ($previousSubId > 0 && $previousSubId === (int) $item->id) {
                        $matchesLine = true;
                    } elseif ($parentSubId > 0 && $parentSubId === (int) $item->id) {
                        $matchesLine = true;
                    } else {
                        $oldPlanId = (int) ($childMeta['old_plan_id'] ?? $childOrder->previous_plan_id ?? 0);
                        if ($oldPlanId <= 0 && $isRenewalChild) {
                            $oldPlanId = (int) ($childItem->plan_id ?? $childOrder->plan_id ?? 0);
                        }
                        if ($oldPlanId > 0 && $oldPlanId === (int) $item->plan_id) {
                            if ($parentSubId > 0 || $previousSubId > 0) {
                                $matchesLine = false;
                            } else {
                                $samePlanCount = (int) OrderItem::query()
                                    ->where('order_id', $orderId)
                                    ->where('plan_id', $oldPlanId)
                                    ->where(function ($q) {
                                        $q->whereNull('status')
                                            ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted', 'upgraded', 'downgraded', 'renewed')");
                                    })
                                    ->count();
                                $matchesLine = $samePlanCount === 1;
                            }
                        }
                    }

                    if (!$matchesLine) {
                        continue;
                    }

                    $childStatus = strtolower(trim((string) ($childOrder->status ?? '')));
                    $changeCategory = strtolower(trim((string) ($childOrder->order_category ?? 'upgrade')));
                    // Draft renew only â€” pending RN claims parent line like upgrade CH.
                    if ($isRenewalChild && $childStatus === 'draft') {
                        continue;
                    }
                    $newPlanId = (int) ($childOrder->plan_id ?? 0);
                    $newPlanName = (string) (optional($newPlansById->get($newPlanId))->name ?? $childOrder->plan_name ?? '');
                    $changeOrderId = (int) $childOrder->id;
                    $changeOrderNo = (string) ($childOrder->order_no ?? '');
                    $changeOrderStatus = $childStatus;



                    if (in_array($childStatus, ['pending', 'processing', 'draft'], true)) {
                        if ($isRenewalChild) {
                            $planChangeStatus = 'renewal_pending';
                        } else {
                            $planChangeStatus = $changeCategory === 'downgrade' ? 'downgrade_pending' : 'upgrade_pending';
                        }
                        $canUpgrade = false;
                    } elseif (in_array($childStatus, ['completed', 'paid', 'success', 'active'], true)) {
                        if ($isRenewalChild) {
                            $planChangeStatus = 'renewed';
                        } else {
                            $planChangeStatus = $changeCategory === 'downgrade' ? 'downgraded' : 'upgraded';
                        }
                        $canUpgrade = false;
                    }

                    break;
                }
            }

            $planLineDisplay = $this->resolveSubscriptionPlanLineDisplay(
                $order,
                $planChangeStatus,
                $itemStatus,
                $status,
                $partial,
                is_array($replacement) ? $replacement : null,
                $treatAsLive,
                $isFullyReplaced
            );
            $planChangeStatus = (string) ($planLineDisplay['plan_change_status'] ?? $planChangeStatus);
            $itemStatus = (string) ($planLineDisplay['item_status'] ?? $itemStatus);
            $planLineStatus = (string) ($planLineDisplay['status'] ?? $status);
            $planLineStatus = $this->preferPlanWiseStatus(
                $order,
                $itemStatus,
                $planChangeStatus,
                $planLineStatus,
                $isCancelledOrder
            );
            if (strcasecmp($planLineStatus, 'Pending') === 0) {
                $planLineStatus = 'Processing';
            }
            $planRenewalStatus = $planLineDisplay['renewal_status'] ?? null;
            $origPlanChangeStatus = $planChangeStatus;
            $initiateMessage = null;
            if (in_array(strtolower($planChangeStatus), ['upgrade_pending', 'downgrade_pending', 'renewal_pending'], true) || $this->isPendingPlanChangeOrder($order)) {
                $pcs = strtolower($planChangeStatus);
                if ($pcs === 'downgrade_pending') {
                    $initiateMessage = 'the plan is initiated in downgrade';
                } elseif ($pcs === 'renewal_pending') {
                    $initiateMessage = 'the plan is initiated in renew';
                } elseif ($pcs === 'upgrade_pending') {
                    // Check if it's a partial upgrade or add license
                    $childOrder = isset($upgradeStateBySourceSubId[(int) $item->id])
                        ? Order::find($upgradeStateBySourceSubId[(int) $item->id]['change_order_id'] ?? 0)
                        : $childChangeOrders->first(fn($co) => in_array(strtolower(trim($co->status ?? '')), ['pending', 'processing', 'draft'], true));
                    if ($childOrder && $this->isPartialUpgradeOrder($childOrder)) {
                        $initiateMessage = 'the plan is initiated in partial upgrade';
                    } elseif ($childOrder && strtolower(trim($childOrder->order_category ?? '')) === 'addon') {
                        $initiateMessage = 'the plan is initiated in add licence';
                    } else {
                        $initiateMessage = 'the plan is initiated in upgrade';
                    }
                } else {
                    $initiateMessage = 'the plan is initiated in upgrade';
                }
            }

            if (
                isset($upgradeStateBySourceSubId[(int) $item->id])
                && !$this->mappedChangeTargetsSourcePlan(
                    $item,
                    $upgradeStateBySourceSubId,
                    $childOrderItems,
                    $childChangeOrders
                )
            ) {
                $planChangeStatus = 'active';
                $itemStatus = in_array($itemStatus, ['active', 'completed', 'paid', 'success'], true)
                    ? $itemStatus
                    : 'active';
                $planLineStatus = in_array($status, ['Active', 'Expiring', 'Expired'], true)
                    ? $status
                    : 'Active';
                $canUpgrade = true;
                $changeOrderId = null;
                $changeOrderNo = null;
                $changeOrderStatus = null;
                $newPlanId = null;
                $newPlanName = null;
            }
            $movedLicenses = $this->resolveMovedLicensesForSourceLine(
                (int) ($item->id ?? 0),
                $upgradeStateBySourceSubId,
                $childOrderItems,
                $childChangeOrders
            );
            if (
                !$hasMergedLicenseAdd
                && $this->shouldHideReplacedSourcePlanFromCurrentList($order, $itemStatus, $planChangeStatus, $planLineStatus)
            ) {
                $leftoverQty = $this->leftoverQtyAfterPlanChange(
                    $qty,
                    $movedLicenses,
                    $itemStatus,
                    $this->mappedChangeIsSamePlan($item, $upgradeStateBySourceSubId)
                );
                if ($leftoverQty !== null && $leftoverQty > 0) {
                    $qty = $leftoverQty;
                    $planChangeStatus = 'active';
                    $itemStatus = 'active';
                    $planLineStatus = in_array($status, ['Active', 'Expiring', 'Expired'], true)
                        ? $status
                        : 'Active';
                    $canUpgrade = true;
                    $changeOrderId = null;
                    $changeOrderNo = null;
                    $changeOrderStatus = null;
                    $newPlanId = null;
                    $newPlanName = null;
                } else {
                    continue;
                }
            } elseif (
                $hasMergedLicenseAdd
                && $this->shouldHideReplacedSourcePlanFromCurrentList($order, $itemStatus, $planChangeStatus, $planLineStatus)
            ) {
                // Keep merged seats visible — do not hide/clamp parent line after addon merge.
                $planChangeStatus = 'active';
                $itemStatus = in_array($itemStatus, ['active', 'completed', 'paid', 'success'], true)
                    ? $itemStatus
                    : 'active';
                $planLineStatus = in_array($status, ['Active', 'Expiring', 'Expired'], true)
                    ? $status
                    : 'Active';
            } elseif (
                !$isChangeOrderSelf
                && in_array(strtolower($planChangeStatus), [
                    'upgrade_pending',
                    'downgrade_pending',
                    'renewal_pending',
                ], true)
            ) {
                // Pending full/partial upgrade: keep original plan + licenses on parent.
                $canUpgrade = false;
                $planChangeStatus = 'active';
                $itemStatus = in_array($itemStatus, ['active', 'completed', 'paid', 'success'], true)
                    ? $itemStatus
                    : 'active';
                $planLineStatus = in_array($status, ['Active', 'Expiring', 'Expired'], true)
                    ? $status
                    : 'Active';
                $newPlanId = null;
                $newPlanName = null;
            }

            $canUpgrade = !$isCancelledOrder
                ? (
                    !$this->isPendingPlanChangeOrder($order)
                    && !in_array($itemStatus, ['upgraded', 'downgraded', 'renewed'], true)
                    && !in_array(strtolower($origPlanChangeStatus), [
                        'upgraded',
                        'downgraded',
                        'renewed',
                    ], true)
                )
                : false;
            $upgradeFlags = $this->upgradeButtonFlags($canUpgrade, null, [
                'provider_id' => (int) (optional($plan)->provider_id ?? 0),
            ]);

            $hideUpgrade = $upgradeFlags['hide_upgrade'];
            $hidePartialUpgrade = $upgradeFlags['hide_partial_upgrade'];
            $hideAddLicense = $upgradeFlags['hide_add_license'];
            $hideDowngrade = $upgradeFlags['hide_upgrade'];
            $hideRenew = false;

            if ($initiateMessage !== null) {
                $pcs = strtolower($origPlanChangeStatus);
                $changeKind = null;
                $isPartial = false;
                $isAddon = false;

                if (in_array($pcs, ['upgrade_pending', 'downgrade_pending', 'renewal_pending'], true)) {
                    if ($pcs === 'upgrade_pending') {
                        $changeKind = 'upgrade';
                        $childOrder = isset($upgradeStateBySourceSubId[(int) $item->id])
                            ? Order::find($upgradeStateBySourceSubId[(int) $item->id]['change_order_id'] ?? 0)
                            : $childChangeOrders->first(fn($co) => in_array(strtolower(trim($co->status ?? '')), ['pending', 'processing', 'draft'], true));
                        if ($childOrder) {
                            $isPartial = $this->isPartialUpgradeOrder($childOrder);
                            $isAddon = strtolower(trim($childOrder->order_category ?? '')) === 'addon';
                        }
                    } elseif ($pcs === 'downgrade_pending') {
                        $changeKind = 'downgrade';
                    } elseif ($pcs === 'renewal_pending') {
                        $changeKind = 'renewal';
                    }
                } elseif ($this->isPendingPlanChangeOrder($order)) {
                    $changeKind = $this->partnerPlanChangeOrderKind($order);
                    $isPartial = $this->isPartialUpgradeOrder($order);
                    $isAddon = strtolower(trim($order->order_category ?? '')) === 'addon';
                }

                if ($changeKind !== null) {
                    if ($changeKind === 'upgrade') {
                        if ($isPartial) {
                            $hidePartialUpgrade = true;
                        } elseif ($isAddon) {
                            $hideAddLicense = true;
                        } else {
                            $hideUpgrade = true;
                        }
                    } elseif ($changeKind === 'downgrade') {
                        $hideDowngrade = true;
                    } elseif ($changeKind === 'renewal') {
                        $hideRenew = true;
                    }
                }
            }

            // Final license qty = SQL merge: parent_item_qty + addon_item_qty
            $displayQty = $qty > 0 ? $qty : ($isFullyReplaced ? 0 : $originalQty);
            if ($hasMergedLicenseAdd && $mergedExtraLicenses > 0) {
                $baseParentQty = (int) ($parentQtyBeforeMergeByItemId[(int) ($item->id ?? 0)] ?? 0);
                if ($baseParentQty <= 0) {
                    $baseParentQty = max(1, (int) ($item->quantity ?? 1) - $mergedExtraLicenses);
                    if ($baseParentQty < 1) {
                        $baseParentQty = 1;
                    }
                }
                // Exact same formula as the merge SQL query
                $sqlMergedQty = $baseParentQty + $mergedExtraLicenses;
                $displayQty = max(
                    $displayQty,
                    (int) ($item->quantity ?? 0),
                    $sqlMergedQty
                );
                if ($orderItems->count() <= 1) {
                    $displayQty = max(
                        $displayQty,
                        (int) ($order->quantity ?? 0),
                        (int) ($order->licenses ?? 0),
                        $sqlMergedQty
                    );
                }
                $qty = max((int) $qty, $displayQty);
                $originalQty = max($originalQty, $baseParentQty);
            }

            $plansInfo[] = [
                'order_sub_id' => $item->id ?? null,
                'subscription_no' => (string) ($item->subscription_id ?? ''),
                'provider_id' => optional($plan)->provider_id ?? null,
                'provider_name' => optional($provider)->name ?? '',
                'plan_name' => optional($plan)->name ?? '',
                'plan_type' => optional($plan)->plan_type ?? '',
                'customer_limit' => optional($plan)->customer_limit ?? null,
                'plan_id' => optional($plan)->id ?? null,
                'license' => $displayQty,
                'licenses' => $displayQty,
                'license_label' => $displayQty . ' ' . ($displayQty === 1 ? 'User' : 'Users'),
                'original_license' => $originalQty,
                'original_licenses' => $originalQty,
                'total_licenses' => $displayQty,
                'upgraded_licenses' => $childMovedQty,
                'partial_upgraded_licenses' => $childMovedQty,
                'remaining_licenses' => $qty,
                'active_licenses' => $qty,
                'price_per_license_per_year' => round(optional($plan)->price ?? 0, 2),
                'subtotal' => round(
                    (optional($plan)->price ?? 0) * max(1, $displayQty),
                    2
                ),
                'domain' => $order->domain_name ?? '',
                'subscription_start_date' => $order->subscription_start_date
                    ? date('d M Y', strtotime($order->subscription_start_date))
                    : null,
                'subscription_end_date' => $order->subscription_end_date
                    ? date('d M Y', strtotime($order->subscription_end_date))
                    : null,
                // Per-plan display status
                'status' => $planLineStatus,
                'renewal_status' => $planRenewalStatus,
                // Per-plan upgrade/downgrade visibility
                'item_status' => $itemStatus,
                'plan_change_status' => $planChangeStatus,
                'hide_renew' => $hideRenew,
                'hide_add_license' => $hideAddLicense,
                'hide_upgrade' => $hideUpgrade,
                'hide_downgrade' => $hideDowngrade,
                'hide_partial_upgrade' => $hidePartialUpgrade,
                'change_via' => $upgradeFlags['change_via'],
                'requires_request' => $upgradeFlags['requires_request'],
                'change_order_id' => $changeOrderId,
                'change_order_no' => $changeOrderNo,
                'change_order_status' => $changeOrderStatus,
                'new_plan_id' => $newPlanId,
                'new_plan_name' => $newPlanName,
                // OPTIONAL
                'days_left' => $daysToExpire,
                'customer_id' => $customer->id ?? null,
                'initiate_message' => $initiateMessage,
            ];
        }

        // Do not merge activated upgrade/downgrade/renewal child plans into parent
        // CURRENT SUBSCRIPTION â€” those belong only on the change order.

        $plansInfo = $this->dedupeSubscriptionPlansInfo($plansInfo);

        $subscriptionNo = (string) collect($plansInfo)
            ->pluck('subscription_no')
            ->map(fn($v) => trim((string) $v))
            ->first(fn($v) => $v !== '', '');
        if ($subscriptionNo === '') {
            $subscriptionNo = (string) ($orderItems->first()->subscription_id ?? '');
        }

        $enrollment_category = $this->resolveEnrollmentTypeLabel($order);
        $enrollment_type = $enrollment_category;
        if (strtolower(trim((string) ($order->domain_transfer ?? ''))) === 'yes') {
            $enrollment_type = 'Transfer Service';
        } else {
            $enrollment_type = 'New Service';
        }

        $pendingTime = null; // Wait, let's keep the blank line or original content below
        $pendingRenewalLicenses = (int) ($partial['pending_renewal_licenses'] ?? 0);
        $claimedRenewalQty = is_array($replacement) ? (int) ($replacement['replaced_qty'] ?? 0) : 0;
        if ($isCancelledOrder) {
            $status = 'Cancelled';
        } elseif ($isChangeOrderSelf) {
            $status = $this->preferPlanWiseStatus(
                $order,
                $orderRawStatus,
                $orderRawCategory === 'upgrade' ? 'upgrade_pending' : (
                    $orderRawCategory === 'downgrade' ? 'downgrade_pending' : (
                        in_array($orderRawCategory, ['renewal', 'renew'], true) ? 'renewal_pending' : ''
                    )
                ),
                $status,
                false
            );
        } elseif (in_array(strtolower(trim((string) $status)), ['upgrade pending', 'downgrade pending', 'renewal pending'], true) && $treatAsLive) {
            // Parent with leftover seats: keep live order status; plan rows carry pending labels.
            $status = in_array($orderLevel['status'], ['Active', 'Expiring', 'Expired'], true)
                ? $orderLevel['status']
                : 'Active';
        } elseif (!$treatAsLive && (
            strtolower(trim((string) ($order->status ?? ''))) === 'upgraded'
            || strtolower(trim((string) ($order->order_category ?? ''))) === 'upgraded'
        )) {
            $status = 'Upgraded';
        } elseif (!$treatAsLive && (
            strtolower(trim((string) ($order->status ?? ''))) === 'downgraded'
            || strtolower(trim((string) ($order->order_category ?? ''))) === 'downgraded'
        )) {
            $status = 'Downgraded';
        } elseif (!$treatAsLive && (
            strtolower(trim((string) ($order->status ?? ''))) === 'renewed'
            || strtolower(trim((string) ($order->order_category ?? ''))) === 'renewed'
        )) {
            $status = 'Renewed';
        } elseif (!$isChangeOrderSelf && (strcasecmp((string) $status, 'Pending') === 0
            || strtolower(trim((string) ($order->status ?? ''))) === 'pending'
        )) {
            $status = 'Pending';
        } elseif (!$isChangeOrderSelf && (strcasecmp((string) $status, 'Processing') === 0
            || strtolower(trim((string) ($order->status ?? ''))) === 'processing'
        )) {
            $status = 'Processing';
        }
        $statusDisplay = [
            'status' => $status,
            'renewal_status' => null,
            'statuses' => [$status],
            'status_detail' => null,
        ];
        $mergedPlanLicenses = (int) collect($plansInfo)->sum(fn($p) => (int) ($p['licenses'] ?? 0));
        $displayLicenses = $mergedPlanLicenses > 0
            ? $mergedPlanLicenses
            : ($remainingLicenses > 0 ? $remainingLicenses : max(1, (int) ($order->quantity ?? $order->licenses ?? 1)));
        if ($hasMergedLicenseAdd) {
            $mergedFloor = max(
                $mergedPlanLicenses,
                (int) ($order->quantity ?? 0),
                (int) ($order->licenses ?? 0)
            );
            if ($mergedFloor > $displayLicenses) {
                $displayLicenses = $mergedFloor;
            }
            // Keep plans[].license in sync with order-list merged seats
            if ($mergedFloor > $mergedPlanLicenses && count($plansInfo) === 1) {
                $plansInfo[0]['license'] = $mergedFloor;
                $plansInfo[0]['licenses'] = $mergedFloor;
                $plansInfo[0]['license_label'] = $mergedFloor . ' ' . ($mergedFloor === 1 ? 'User' : 'Users');
                $plansInfo[0]['total_licenses'] = $mergedFloor;
                $plansInfo[0]['remaining_licenses'] = $mergedFloor;
                $plansInfo[0]['active_licenses'] = $mergedFloor;
                $unit = (float) ($plansInfo[0]['price_per_license_per_year'] ?? 0);
                $plansInfo[0]['subtotal'] = round($unit * max(1, $mergedFloor), 2);
            }
        }

        // Plan-wise: pending upgrade/downgrade labels live on plans[].status.
        // Only partial renew keeps a dual order-level badge for leftover seats.
        $pendingUpgradeLicenses = (int) ($partial['pending_upgrade_licenses'] ?? 0);
        $pendingDowngradeLicenses = (int) ($partial['pending_downgrade_licenses'] ?? 0);
        $replacementStatus = is_array($replacement) ? (string) ($replacement['status'] ?? '') : '';
        if (
            !$isCancelledOrder
            && $treatAsLive
            && $claimedRenewalQty > 0
            && $pendingUpgradeLicenses <= 0
            && $pendingDowngradeLicenses <= 0
            && $replacementStatus === 'Renewed'
            && count($plansInfo) <= 1
        ) {
            $pendingRenewalLicenses = $pendingRenewalLicenses > 0 ? $pendingRenewalLicenses : $claimedRenewalQty;
            $liveLabel = in_array($status, ['Active', 'Expiring', 'Expired'], true) ? $status : 'Expiring';
            $leftoverQty = max(1, $remainingLicenses > 0 ? $remainingLicenses : 1);
            if (!$hasMergedLicenseAdd) {
                $displayLicenses = $leftoverQty;
            }
            $statusDisplay = $this->buildSubscriptionStatusDisplay(
                $liveLabel,
                $pendingRenewalLicenses,
                $hasMergedLicenseAdd ? $displayLicenses : $leftoverQty,
                true,
                'Renewal Pending'
            );
            $status = $statusDisplay['status'];

            // Ensure leftover plan lines show leftover qty + live status (not Renewed / full qty).
            foreach ($plansInfo as &$planRow) {
                $rowStatus = strtolower(trim((string) ($planRow['item_status'] ?? 'active')));
                if ($rowStatus === '') {
                    $rowStatus = 'active';
                }
                if (!in_array($rowStatus, ['active', 'completed', 'paid', 'success'], true)) {
                    continue;
                }
                if (!$hasMergedLicenseAdd && (int) ($planRow['licenses'] ?? 0) > $leftoverQty) {
                    $planRow['licenses'] = $leftoverQty;
                    $planRow['subtotal'] = round(
                        ((float) ($planRow['price_per_license_per_year'] ?? 0)) * $leftoverQty,
                        2
                    );
                }
                if (in_array((string) ($planRow['status'] ?? ''), ['Renewed', 'Upgraded', 'Downgraded'], true)) {
                    $planRow['status'] = $liveLabel;
                }
            }
            unset($planRow);

            // Do NOT append a synthetic "Renewal Pending" line on the parent.
            // Like upgrade: source plan is hidden; RN order shows Renewal Pending.
        } elseif (!$isCancelledOrder && $this->isRenewalOrderRow($order)) {
            $statusDisplay = $this->resolveRenewalOrderDisplayStatus($order, $status);
            $status = $statusDisplay['status'];
        }

        if ($isCancelledOrder) {
            $status = 'Cancelled';
            $statusDisplay = [
                'status' => 'Cancelled',
                'renewal_status' => null,
                'statuses' => ['Cancelled'],
                'status_detail' => $hasCreditNote
                    ? ('Order cancelled â€” credit note ' . (string) ($creditNote['credit_note_no'] ?? '') . ' issued')
                    : 'Order cancelled',
            ];
            foreach ($plansInfo as &$planRow) {
                $planRow['status'] = 'Cancelled';
                $planRow['renewal_status'] = null;
                $planRow['item_status'] = 'cancelled';
                $planRow['plan_change_status'] = 'cancelled';
                // $planRow['can_upgrade'] = true;
                // $planRow['can_partial_upgrade'] = true;
                // $planRow['can_add_license'] = true;
                $planRow['hide_upgrade'] = false;
                $planRow['hide_partial_upgrade'] = false;
            }
            unset($planRow);
        }

        // Same fallback as Active order list so Active subscriptions still return the PO file URL.
        // For renew/upgrade/downgrade child orders, fall back to the original new-order uploaded PO.
        $sourcePo = $this->resolveParentOrderPoPayload((int) $order->id);
        $poLink = $sourcePo['po_link'] ?? null;

        $rootProviderId = (int) (collect($plansInfo)->pluck('provider_id')->filter()->first() ?? 0);
        $rootUpgradeFlags = $this->upgradeButtonFlags(
            $isCancelledOrder
                || (
                    !$this->isPendingPlanChangeOrder($order)
                    && collect($plansInfo)->contains(fn($row) => empty($row['hide_upgrade']))
                ),
            null,
            ['provider_id' => $rootProviderId]
        );
        if (
            !$isCancelledOrder
            && (
                (int) ($partial['pending_upgrade_licenses'] ?? 0) > 0
                || (int) ($partial['pending_downgrade_licenses'] ?? 0) > 0
            )
        ) {
            $rootUpgradeFlags = $this->upgradeButtonFlags(false, null, ['provider_id' => $rootProviderId]);
        }

        // Cancel button: pending/processing anytime; Tizzy(1)/Microsoft(2) Active within 6 days of start; Google(3) Active = no.
        $canCancel = false;
        if (!$isCancelledOrder) {
            if (in_array($orderRawStatus, ['pending', 'processing', 'waiting', 'draft'], true)) {
                $canCancel = true;
            } elseif (in_array($orderRawStatus, ['completed', 'paid', 'success', 'active'], true)) {
                if ($rootProviderId === 3) {
                    $canCancel = false;
                } elseif (in_array($rootProviderId, [1, 2], true) && !empty($order->subscription_start_date)) {
                    $startDay = Carbon::parse($order->subscription_start_date)->startOfDay();
                    $lastCancelDay = $startDay->copy()->addDays(6);
                    $canCancel = now()->startOfDay()->lte($lastCancelDay);
                }
            }
        }

        // search (plan name, provider, subscription no, status ...) + pagination on the plan lines only.
        // Applied at the end so totals above still use every plan line. Paginated only when page_no / per_page is sent.
        $planSearch = mb_strtolower(trim((string) $request->input('search', '')));
        $planRows = collect($plansInfo);
        if ($planSearch !== '') {
            $planRows = $planRows->filter(fn ($row) => str_contains(
                mb_strtolower(implode(' ', array_filter((array) $row, fn ($v) => is_string($v) || is_numeric($v)))),
                $planSearch
            ))->values();
        }
        $planTotal = $planRows->count();
        $planPaginate = $request->filled('per_page') || $request->filled('page_no') || $request->filled('page');
        $planPerPage = $planPaginate ? max(1, min(100, (int) $request->input('per_page', 10))) : max(1, $planTotal);
        $planPageNo = $planPaginate ? max(1, (int) $request->input('page_no', $request->input('page', 1))) : 1;
        $planPage = $planRows->forPage($planPageNo, $planPerPage)->values()->all();

        return response()->json([
            'success' => true,
            'message' => 'Subscription details fetched successfully',
            'data' => [
                'plans' => $planPage,
                'pagination' => [
                    'total' => $planTotal,
                    'per_page' => $planPerPage,
                    'current_page' => $planPageNo,
                    'last_page' => max(1, (int) ceil($planTotal / $planPerPage)),
                    'from' => $planPage ? ($planPageNo - 1) * $planPerPage + 1 : null,
                    'to' => $planPage ? ($planPageNo - 1) * $planPerPage + count($planPage) : null,
                ],

                'customer' => [
                    'customer_name' => $customer->name ?? '',
                    'company_name' => $customer->company_name ?? '',
                    'email' => $customer->email ?? '',
                    'mobile' => $customer->mobile ?? '',
                ],

                'order_id' => $order->id,
                'order_no' => $order->order_no ?? '',
                'subscription_id' => $subscriptionNo,
                'domain_name' => $order->domain_name ?? '',
                'enrollment_type' => $enrollment_type ?? null,
                'po_link' => $poLink,
                'po_mode' => (string) ($sourcePo['po_mode'] ?? 'generated'),
                'po_number' => (string) ($sourcePo['po_number'] ?? ''),
                'final_po_link' => $sourcePo['final_po_link'] ?? $poLink,
                'is_uploaded_po' => (bool) ($sourcePo['is_uploaded'] ?? false),
                'po_source_order_id' => (int) ($sourcePo['source_order_id'] ?? $order->id),
                'po_date' => !empty(optional($order_po_details)->po_date)
                    ? date('d-m-Y', strtotime((string) $order_po_details->po_date))
                    : null,
                'po_amount' => optional($order_po_details)->po_amount !== null
                    ? round((float) $order_po_details->po_amount, 2)
                    : null,
                'is_cancelled' => $isCancelledOrder,
                'has_credit_note' => $hasCreditNote,
                'credit_note' => $creditNote,
                'credit_note_id' => $creditNote['credit_note_id'] ?? null,
                'credit_note_no' => $creditNote['credit_note_no'] ?? null,
                'credit_note_amount' => $creditNote['credit_note_amount'] ?? null,
                'credit_note_link' => $creditNote['credit_note_link'] ?? null,
                'credit_note_status' => $creditNote['credit_note_status'] ?? null,
                'wallet_credited' => $creditNote['wallet_credited'] ?? false,
                'wallet_withdrawable' => $creditNote['wallet_withdrawable'] ?? false,
                'wallet_status' => $creditNote['wallet_status'] ?? null,

                'subscription_start_date' => $order->subscription_start_date
                    ? date('d-m-Y', strtotime($order->subscription_start_date))
                    : null,

                'subscription_end_date' => $order->subscription_end_date
                    ? date('d-m-Y', strtotime($order->subscription_end_date))
                    : null,

                'status' => $status,
                'renewal_status' => $statusDisplay['renewal_status'],
                'statuses' => $statusDisplay['statuses'],
                'status_detail' => $hasMergedLicenseAdd
                    ? ('Licenses added: +' . $mergedExtraLicenses . ' license(s)')
                    : ($statusDisplay['status_detail'] ?? null),
                'licenses' => $displayLicenses > 0 ? (string) $displayLicenses : null,
                'pending_renewal_licenses' => $pendingRenewalLicenses > 0 ? $pendingRenewalLicenses : null,
                'has_license_add_history' => $licenseAddHistoryOrders->isNotEmpty(),
                'license_add_history' => $licenseAddHistoryOrders->map(function ($child) {
                    return [
                        'order_id' => (int) $child->id,
                        'order_no' => $child->order_no,
                        'added_licenses' => (int) ($child->quantity ?? $child->licenses ?? 1),
                        'created_at' => $child->created_at ? $child->created_at->format('d-m-Y H:i:s') : null,
                        'status' => $child->status,
                    ];
                })->values()->all(),

                'change_via' => $rootUpgradeFlags['change_via'],
                'requires_request' => $rootUpgradeFlags['requires_request'],
                'days_left' => $daysToExpire,
                'can_cancel' => $canCancel,
            ]
        ], 200);
    }


    protected function buildOrderTimeline(Order $order, ?Customer $customer, int $partnerId): array
    {
        $events = [];
        $orderId = (int) $order->id;
        $contactName = strtolower(trim((string) ($customer?->name ?? 'customer')));
        $txnLabel = (string) ($order->order_no ?? "TXN" . str_pad((string)$orderId, 5, '0', STR_PAD_LEFT));

        // Helper closure to insert formatted timeline items
        $push = function (string $event, string $title, string $description, $at, array $extra = []) use (&$events) {
            if (!$at) return;

            $dt = \Carbon\Carbon::parse($at);
            $today = \Carbon\Carbon::now()->startOfDay();
            $dateFormatted = $dt->startOfDay()->equalTo($today)
                ? 'Today'
                : ($dt->startOfDay()->equalTo($today->copy()->subDay()) ? 'Yesterday' : $dt->format('d M Y'));

            $events[] = array_merge([
                'event'       => $event,
                'title'       => $title,
                'description' => $description,
                'date'        => $dateFormatted,
                'timestamp'   => $dt->toIso8601String(),
                '_sort_at'    => $dt->timestamp,
            ], $extra);
        };

        // 1. Order Created
        $push(
            'order_created',
            'Order Created',
            "Order {$txnLabel} was placed by {$contactName}",
            $order->created_at,
            ['order_id' => $orderId, 'order_no' => (string) ($order->order_no ?? '')]
        );

        // 2. PO Details & Identity Verification
        try {
            $poRow = OrderPoDetail::where('order_id', $orderId)->first();
            if ($poRow) {
                $poNo   = trim((string) ($poRow->po_number ?? ''));
                $poMode = strtolower(trim((string) ($poRow->po_mode ?? 'generated')));
                $poAt   = $poRow->created_at ?? $poRow->po_date ?? $order->created_at;

                $push(
                    'po_created',
                    'PO Generated',
                    ($poNo !== '' ? "PO {$poNo} created" : "Purchase order created") . " ({$poMode})",
                    $poAt,
                    ['po_number' => $poNo ?: null, 'po_mode' => $poMode]
                );
            }
        } catch (\Throwable $e) {
            \Log::warning('timeline_po_failed', ['order_id' => $orderId, 'error' => $e->getMessage()]);
        }

        // 3. Invoices & Credit Notes
        $invoices = InvoiceMst::where('order_id', $orderId)->orderBy('id')->get();
        foreach ($invoices as $invoice) {
            $invNo   = trim((string) ($invoice->bill_no_full ?? $invoice->invoice_no ?? $invoice->bill_no ?? ''));
            $isCN    = str_contains(strtoupper($invNo), 'CN/') || strtolower(trim((string)($invoice->action_type ?? ''))) === 'credit_note';
            $amount  = round((float) ($invoice->net_amt ?? 0), 2);

            $push(
                $isCN ? 'credit_note_issued' : 'invoice_generated',
                $isCN ? 'Credit Note Issued' : 'Invoice Generated',
                ($isCN ? 'Credit note ' : 'Invoice ') . ($invNo ?: '#' . $invoice->id) . ' for ₹' . number_format($amount, 2),
                $invoice->bill_date ?? $invoice->created_at,
                ['invoice_id' => (int)$invoice->id, 'invoice_no' => $invNo ?: null, 'amount' => $amount]
            );
        }

        // 4. Partner subscription changes on this subscription
        $changeCounts = [
            'upgrade' => 0,
            'renew' => 0,
            'downgrade' => 0,
            'partial_upgrade' => 0,
            'license_add' => 0,
            'total' => 0,
        ];

        try {
            $rootOrderId = $this->resolveTimelineRootOrderId($order);
            $childOrders = Order::query()
                ->where('parent_order_id', $rootOrderId)
                ->where('partner_id', $partnerId)
                ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('draft', 'cancelled', 'canceled', 'rejected')")
                ->orderBy('created_at')
                ->get();

            foreach ($childOrders as $child) {
                $changeType = $this->resolveTimelineChangeType($child);
                if ($changeType === null) {
                    continue;
                }

                $changeCounts[$changeType]++;
                $changeCounts['total']++;

                $childNo = trim((string) ($child->order_no ?? ''));
                $childLabel = $childNo !== '' ? $childNo : ('#' . (int) $child->id);
                $licenses = max(0, (int) ($child->quantity ?? 0));
                $amount = round((float) ($child->total_amount ?? $child->subtotal ?? 0), 2);
                $statusLabel = ucfirst(strtolower(trim((string) ($child->status ?? 'pending'))));

                switch ($changeType) {
                    case 'upgrade':
                        $event = 'plan_upgraded';
                        $title = 'Plan Upgraded';
                        $description = "Partner upgraded subscription via order {$childLabel}";
                        break;
                    case 'partial_upgrade':
                        $event = 'partial_upgrade';
                        $title = 'Partial Upgrade';
                        $description = "Partner partially upgraded subscription via order {$childLabel}";
                        break;
                    case 'downgrade':
                        $event = 'plan_downgraded';
                        $title = 'Plan Downgraded';
                        $description = "Partner downgraded subscription via order {$childLabel}";
                        break;
                    case 'renew':
                        $event = 'subscription_renewed';
                        $title = 'Subscription Renewed';
                        $description = "Partner renewed subscription via order {$childLabel}";
                        break;
                    case 'license_add':
                        $event = 'license_added';
                        $title = 'Licenses Added';
                        $description = "Partner added " . max(1, $licenses) . " license(s) via order {$childLabel}";
                        break;
                    default:
                        continue 2;
                }

                if ($changeType !== 'license_add' && $licenses > 0) {
                    $description .= " ({$licenses} licenses)";
                }
                if ($amount > 0) {
                    $description .= ' — ₹' . number_format($amount, 2);
                }
                $description .= " — {$statusLabel}";

                $push(
                    $event,
                    $title,
                    $description,
                    $child->created_at ?? $child->updated_at,
                    [
                        'order_id' => (int) $child->id,
                        'order_no' => $childNo ?: null,
                        'change_type' => $changeType,
                        'licenses' => $licenses > 0 ? $licenses : null,
                        'amount' => $amount > 0 ? $amount : null,
                        'status' => strtolower(trim((string) ($child->status ?? ''))),
                    ]
                );
            }
        } catch (\Throwable $e) {
            \Log::warning('timeline_changes_failed', ['order_id' => $orderId, 'error' => $e->getMessage()]);
        }

        // Sort Events by Timestamp ASC (or DESC if needed), using event type as secondary sort
        usort($events, function ($a, $b) {
            $cmp = ($a['_sort_at'] <=> $b['_sort_at']);
            return $cmp !== 0 ? $cmp : strcmp($a['event'], $b['event']);
        });

        // Remove internal sorting key
        $cleanEvents = array_map(function ($evt) {
            unset($evt['_sort_at']);
            return $evt;
        }, $events);

        return [
            'events' => $cleanEvents,
            'change_counts' => $changeCounts,
        ];
    }

    private function resolveTimelineRootOrderId(Order $order): int
    {
        $currentId = (int) $order->id;
        $visited = [];

        while ($currentId > 0 && !isset($visited[$currentId])) {
            $visited[$currentId] = true;
            $parentId = (int) (Order::query()->whereKey($currentId)->value('parent_order_id') ?? 0);
            if ($parentId <= 0) {
                return $currentId;
            }
            $currentId = $parentId;
        }

        return (int) $order->id;
    }

    private function resolveTimelineChangeType(Order $child): ?string
    {
        if ($this->isLicenseAddOrder($child)) {
            return 'license_add';
        }

        $category = strtolower(trim((string) ($child->order_category ?? '')));
        $orderNo = strtoupper(trim((string) ($child->order_no ?? '')));

        if (in_array($category, ['renewal', 'renew', 'renewed'], true) || str_starts_with($orderNo, 'RN')) {
            return 'renew';
        }

        if (in_array($category, ['downgrade', 'downgraded'], true)) {
            return 'downgrade';
        }

        if (
            in_array($category, ['partial_upgrade', 'partial-upgrade', 'partial'], true)
            || $this->isPartialUpgradeOrder($child, $category)
        ) {
            return 'partial_upgrade';
        }

        if (
            in_array($category, ['upgrade', 'upgraded'], true)
            || str_starts_with($orderNo, 'CH')
            || str_starts_with($orderNo, 'UPG')
        ) {
            return 'upgrade';
        }

        return null;
    }

    public function planDetail(Request $request)
    {
        $validator = Validator::make($request->all(), [
            'partner_id'      => 'required|integer',
            'order_id'        => 'required|integer',
            'plan_id'         => 'nullable|integer',
            'order_sub_id'    => 'nullable|integer',
            'subscription_no' => 'nullable|string',
            'subscription_id' => 'nullable|string',
        ]);

        if ($validator->fails()) {
            return response()->json([
                'success' => false,
                'error'   => true,
                'message' => $validator->errors()->first(),
                'data'    => null,
            ], 400);
        }

        $partnerId    = (int) $request->input('partner_id');
        $orderId      = (int) $request->input('order_id');
        $filterPlanId = (int) $request->input('plan_id', 0);
        $orderSubId   = (int) $request->input('order_sub_id', 0);
        $subscriptionKey = trim((string) ($request->input('subscription_no') ?? $request->input('subscription_id') ?? ''));

        if (!Partner::where('id', $partnerId)->exists()) {
            return response()->json(['success' => false, 'error' => true, 'message' => 'Partner not found.', 'data' => null], 404);
        }

        $order = Order::with(['customer', 'plan.provider', 'provider'])
            ->where('id', $orderId)
            ->where('partner_id', $partnerId)
            ->where('status', '!=', 'draft')
            ->first();

        if (!$order) {
            return response()->json(['success' => false, 'error' => true, 'message' => 'Order not found for this partner.', 'data' => null], 404);
        }

        $licenseAddHistoryOrders = collect();

        // If requested order is a license-add order, resolve to parent
        if ($order && $this->isLicenseAddOrder($order)) {
            $parentId = (int) ($order->parent_order_id ?? 0);
            if ($parentId <= 0 && !empty($order->domain_name) && !empty($order->partner_id)) {
                $parentId = (int) (Order::query()
                    ->where('partner_id', $order->partner_id)
                    ->where('domain_name', $order->domain_name)
                    ->where('id', '!=', $order->id)
                    ->where(function ($q) {
                        $q->whereNull('parent_order_id')->orWhere('parent_order_id', 0);
                    })
                    ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('draft', 'cancelled', 'canceled', 'failed', 'rejected')")
                    ->orderBy('id')
                    ->value('id') ?? 0);
                if ($parentId > 0) {
                    Order::where('id', $order->id)->update(['parent_order_id' => $parentId]);
                    $order->parent_order_id = $parentId;
                }
            }
            if ($parentId > 0 && $this->isActivatedLicenseAddStatus($order)) {
                $parentOrder = Order::with(['customer', 'plan.provider', 'provider'])
                    ->where('id', $parentId)
                    ->where('partner_id', $partnerId)
                    ->where('status', '!=', 'draft')
                    ->first();
                // Same as subscriptionDetails / orderIndex: only redirect when plan matches parent
                if (
                    $parentOrder
                    && (int) ($parentOrder->plan_id ?? 0) > 0
                    && (int) ($parentOrder->plan_id ?? 0) === (int) ($order->plan_id ?? 0)
                ) {
                    $order = $parentOrder;
                    $orderId = (int) $parentOrder->id;
                }
            }
        }

        if ($order && !$this->isLicenseAddOrder($order)) {
            $licenseAddHistoryOrders = $this->loadActivatedLicenseAddChildren($orderId, $order);
        }

        // Same SQL as subscriptionDetails: activated addon children by parent_order_id
        $directAddonChildren = Order::query()
            ->where('parent_order_id', $orderId)
            ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) IN ('completed', 'paid', 'success', 'active')")
            ->whereRaw("LOWER(TRIM(COALESCE(order_category, ''))) = 'addon'")
            ->orderBy('id')
            ->get();
        $licenseAddHistoryOrders = collect($licenseAddHistoryOrders)
            ->concat($directAddonChildren)
            ->unique('id')
            ->values();

        $customer = $order->customer ?? ($order->user_id ? Customer::find($order->user_id) : null);

        // Fetch Items & Plans
        $orderItems = OrderItem::where('order_id', $orderId)
            ->where(fn($q) => $q->whereNull('status')->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted')"))
            ->orderBy('id')
            ->get();

        $orderItems = $this->uniqueSubscriptionOrderItems($orderItems);

        // Parent qty before merge (same as subscriptionDetails)
        $parentQtyBeforeMergeByItemId = [];
        foreach ($orderItems as $oi) {
            $parentQtyBeforeMergeByItemId[(int) ($oi->id ?? 0)] = max(1, (int) ($oi->quantity ?? 1));
        }

        $parentPlanId = (int) ($order->plan_id ?? 0);
        if ($parentPlanId <= 0) {
            foreach ($orderItems as $oi) {
                $pid = (int) ($oi->plan_id ?? 0);
                if ($pid > 0) {
                    $parentPlanId = $pid;
                    break;
                }
            }
        }

        // Keep activated addon children (same plan on order OR on order_items)
        $licenseAddHistoryOrders = $licenseAddHistoryOrders->filter(function ($child) use ($parentPlanId) {
            $childPlanId = (int) ($child->plan_id ?? 0);
            if ($parentPlanId <= 0) {
                return true;
            }
            if ($childPlanId <= 0 || $childPlanId === $parentPlanId) {
                return true;
            }

            return OrderItem::query()
                ->where('order_id', (int) $child->id)
                ->where('plan_id', $parentPlanId)
                ->where(function ($q) {
                    $q->whereNull('status')
                        ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted')");
                })
                ->exists();
        })->values();

        $hasMergedLicenseAdd = $licenseAddHistoryOrders->isNotEmpty();
        $mergedExtraLicenses = 0;
        if ($hasMergedLicenseAdd) {
            foreach ($licenseAddHistoryOrders as $child) {
                $childItems = OrderItem::query()
                    ->where('order_id', (int) $child->id)
                    ->where(function ($q) {
                        $q->whereNull('status')
                            ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted')");
                    })
                    ->get();
                $childQtySum = 0;
                foreach ($childItems as $childItem) {
                    if ((int) ($childItem->plan_id ?? 0) > 0
                        && $parentPlanId > 0
                        && (int) ($childItem->plan_id ?? 0) !== $parentPlanId) {
                        continue;
                    }
                    $childQtySum += max(1, (int) ($childItem->quantity ?? 1));
                }
                if ($childQtySum <= 0) {
                    $childQtySum = max(1, (int) ($child->quantity ?? $child->licenses ?? 1));
                }
                $mergedExtraLicenses += $childQtySum;
            }
        }

        $orderItems = $this->mergeLicenseAddItemsIntoParentItems($orderItems, $licenseAddHistoryOrders);

        if ($hasMergedLicenseAdd && $order) {
            $order->quantity = ((int) ($order->quantity ?? 1)) + $mergedExtraLicenses;
            $order->licenses = $order->quantity;
        }

        $allOrderItems = $orderItems;

        if ($filterPlanId > 0) {
            $orderItems = $orderItems->filter(fn($item) => (int)($item->plan_id ?? 0) === $filterPlanId)->values();
        }

        $planIds = $orderItems->pluck('plan_id')->filter()->map(fn($id) => (int)$id)->unique()->values()->all();
        if (empty($planIds) && (int)($order->plan_id ?? 0) > 0) {
            $planIds = [(int)$order->plan_id];
        }

        $plansById = empty($planIds) ? collect() : Plan::with('provider')->whereIn('id', $planIds)->get()->keyBy('id');
        $mainCartId = (int)($order->cart_id ?? $order->source_cart_id ?? 0) ?: (int)\Cache::get('draft_order_cart_' . $orderId, 0) ?: null;

        $today = now();
        $supersededByParentId = $this->buildSupersededSubscriptionStatusByParentId([$orderId]);
        $replacement = $supersededByParentId[$orderId] ?? null;
        $partial = $this->resolvePartialReplacementForOrder($order, $allOrderItems, $replacement);
        $remainingLicenses = (int) ($partial['remaining_licenses'] ?? 0);
        $isFullyReplaced = (bool) ($partial['is_fully_replaced'] ?? false);
        // License-add seats are additive — never let upgrade leftover math wipe the merge.
        if ($hasMergedLicenseAdd && $mergedExtraLicenses > 0) {
            $mergedLiveQty = (int) $allOrderItems->sum(fn($row) => max(1, (int) ($row->quantity ?? 1)));
            if ($mergedLiveQty <= 0) {
                $mergedLiveQty = max(1, (int) ($order->quantity ?? $order->licenses ?? 1));
            }
            $remainingLicenses = max($remainingLicenses, $mergedLiveQty);
            $partial['remaining_licenses'] = $remainingLicenses;
            $partial['live_qty'] = max((int) ($partial['live_qty'] ?? 0), $mergedLiveQty);
            $isFullyReplaced = false;
        }
        $treatAsLive = $remainingLicenses > 0;
        $supersededStatus = $treatAsLive ? null : ($partial['superseded_status'] ?? null);

        $orderLevel = $this->resolveSubscriptionOrderLevelStatus(
            $order,
            $today,
            $allOrderItems,
            $supersededStatus,
            $treatAsLive
        );
        $displayStatus = (string) ($orderLevel['status'] ?? 'Processing');
        $orderStatusRaw = strtolower(trim((string) ($order->status ?? '')));
        $orderRawCategory = strtolower(trim((string) ($order->order_category ?? '')));
        $isCancelledOrder = in_array($orderStatusRaw, ['cancelled', 'canceled', 'rejected'], true);
        $isChangeOrderSelf = in_array($orderRawCategory, ['upgrade', 'downgrade', 'renewal', 'renew'], true)
            || str_starts_with(strtoupper(trim((string) ($order->order_no ?? ''))), 'RN');

        if ($isCancelledOrder) {
            $displayStatus = 'Cancelled';
        } elseif ($isChangeOrderSelf) {
            $displayStatus = $this->preferPlanWiseStatus(
                $order,
                $orderStatusRaw,
                $orderRawCategory === 'upgrade' ? 'upgrade_pending' : (
                    $orderRawCategory === 'downgrade' ? 'downgrade_pending' : (
                        in_array($orderRawCategory, ['renewal', 'renew'], true) ? 'renewal_pending' : ''
                    )
                ),
                $displayStatus,
                false
            );
        } elseif (in_array($orderStatusRaw, ['pending'], true)) {
            $displayStatus = 'Pending';
        } elseif (in_array($orderStatusRaw, ['processing'], true)) {
            $displayStatus = 'Processing';
        }

        $planChangeContext = $this->buildPlanChangeContextForOrders([$orderId]);
        $childChangeOrders = $planChangeContext['child_change_orders_by_parent']->get($orderId, collect());
        $childOrderItems = $planChangeContext['child_order_items'];
        $newPlansById = $planChangeContext['new_plans_by_id'];
        $upgradeStateBySourceSubId = $this->buildUpgradeStateBySourceSubId(
            $orderId,
            $childChangeOrders,
            $childOrderItems,
            $newPlansById
        );

        // Process Plans
        $plans = [];
        $itemsToProcess = $orderItems->isNotEmpty() ? $orderItems : [null];

        foreach ($itemsToProcess as $item) {
            $planId   = (int) ($item?->plan_id ?? $order->plan_id ?? 0);
            $plan     = $planId > 0 ? ($plansById->get($planId) ?? $order->plan) : null;
            $provider = $plan?->provider ?? $order->provider;

            $originalQty = max(1, (int) ($item?->quantity ?? $order->quantity ?? 1));

            // Calculate moved/upgraded licenses from child orders
            $childMovedQty = 0;
            foreach ($childChangeOrders as $co) {
                if (in_array(strtolower(trim((string) ($co->status ?? ''))), ['cancelled', 'canceled', 'rejected', 'failed'], true)) {
                    continue;
                }
                // Addon seats are additive — never treat as upgrade/moved qty.
                if ($this->isLicenseAddOrder($co)
                    || strtolower(trim((string) ($co->order_category ?? ''))) === 'addon') {
                    continue;
                }
                $coCategory = strtolower(trim((string) ($co->order_category ?? '')));
                $coOrderNo = strtoupper(trim((string) ($co->order_no ?? '')));
                $isChildUpgrade = in_array($coCategory, ['upgrade', 'upgraded', 'partial_upgrade', 'partial', 'partial upgrade', 'upgrade service', 'downgrade', 'downgraded', 'partial_downgrade', 'renewal', 'renew'], true)
                    || str_starts_with($coOrderNo, 'CH')
                    || str_starts_with($coOrderNo, 'UPG')
                    || str_starts_with($coOrderNo, 'RN')
                    || $this->isPartialUpgradeOrder($co, $coCategory);

                if (!$isChildUpgrade) {
                    continue;
                }

                $matchesItem = false;
                $coSubId = (int) ($co->parent_order_sub_id ?? 0);
                $coPrevPlan = (int) ($co->previous_plan_id ?? 0);
                if ($item && $coSubId > 0 && $coSubId === (int) $item->id) {
                    $matchesItem = true;
                } elseif ($item && $coPrevPlan > 0 && $coPrevPlan === (int) ($item->plan_id ?? $order->plan_id ?? 0)) {
                    $matchesItem = true;
                } elseif ($allOrderItems->count() <= 1) {
                    $matchesItem = true;
                }
                if ($matchesItem) {
                    $coChildItem = optional($childOrderItems->get((int) $co->id))->first();
                    $cQty = max(1, (int) ($coChildItem->quantity ?? $co->quantity ?? 1));
                    $childMovedQty += $cQty;
                }
            }

            $qty = $originalQty;
            // Same as subscriptionDetails: never subtract/clamp after license-add merge (e.g. 10 → 2).
            if ($childMovedQty > 0 && !$hasMergedLicenseAdd) {
                $qty = max(0, $originalQty - $childMovedQty);
            } elseif (
                !$hasMergedLicenseAdd
                && $remainingLicenses > 0
                && $remainingLicenses < $originalQty
                && $allOrderItems->count() <= 1
            ) {
                $qty = $remainingLicenses;
            }

            $displayQty = $qty > 0 ? $qty : ($isFullyReplaced ? 0 : $originalQty);
            // Final license qty = SQL merge: parent_item_qty + addon_item_qty (same as subscriptionDetails)
            if ($hasMergedLicenseAdd && $mergedExtraLicenses > 0) {
                $baseParentQty = (int) ($parentQtyBeforeMergeByItemId[(int) ($item?->id ?? 0)] ?? 0);
                if ($baseParentQty <= 0) {
                    $baseParentQty = max(1, (int) ($item?->quantity ?? 1) - $mergedExtraLicenses);
                    if ($baseParentQty < 1) {
                        $baseParentQty = 1;
                    }
                }
                $sqlMergedQty = $baseParentQty + $mergedExtraLicenses;
                $displayQty = max(
                    $displayQty,
                    (int) ($item?->quantity ?? 0),
                    $sqlMergedQty
                );
                if ($allOrderItems->count() <= 1) {
                    $displayQty = max(
                        $displayQty,
                        (int) ($order->quantity ?? 0),
                        (int) ($order->licenses ?? 0),
                        $sqlMergedQty
                    );
                }
                $qty = max((int) $qty, $displayQty);
                $originalQty = max($originalQty, $baseParentQty);
            }

            $unitPrice = (float) ($item?->unit_price ?? $plan?->price ?? 0);
            $lineTotal = (float) ($unitPrice * max(1, $displayQty));

            $startDateRaw = $item?->subscription_start_date ?? $order->subscription_start_date ?? $order->created_at;
            $endDateRaw   = $item?->subscription_end_date ?? $order->renewal_at ?? $order->subscription_end_date;

            $subscriptionNo = trim((string)($item?->subscription_id ?? $item?->subscription_no ?? ''));
            if (!$subscriptionNo) {
                $subscriptionNo = 'SUB-' . str_pad((string)($item?->id ?? $order->id), 5, '0', STR_PAD_LEFT);
            }

            $itemStatus = strtolower(trim((string) ($item?->status ?? 'active')));
            if ($itemStatus === '') {
                $itemStatus = 'active';
            }
            $planChangeStatus = '';
            if ($item) {
                $planChangeStatus = $this->resolvePlanChangeStatusForItem(
                    $item,
                    $orderId,
                    $upgradeStateBySourceSubId,
                    $childChangeOrders,
                    $childOrderItems,
                    $newPlansById
                );
            }
            $lineDisplay = $this->resolveSubscriptionPlanLineDisplay(
                $order,
                (string) $planChangeStatus,
                $itemStatus,
                $displayStatus,
                $partial,
                is_array($replacement) ? $replacement : null,
                $treatAsLive,
                $isFullyReplaced
            );
            $status = $this->preferPlanWiseStatus(
                $order,
                $itemStatus,
                (string) ($lineDisplay['plan_change_status'] ?? $planChangeStatus),
                (string) ($lineDisplay['status'] ?? $displayStatus),
                $isCancelledOrder
            );
            if ($status === '') {
                $status = $displayStatus !== '' ? $displayStatus : 'Processing';
            }

            // Resolve specific initiate message
            $initiateMessage = null;
            $pcs = strtolower((string) ($lineDisplay['plan_change_status'] ?? $planChangeStatus));
            if (in_array($pcs, ['upgrade_pending', 'downgrade_pending', 'renewal_pending'], true) || $this->isPendingPlanChangeOrder($order)) {
                if ($pcs === 'downgrade_pending') {
                    $initiateMessage = 'the plan is initiated in downgrade';
                } elseif ($pcs === 'renewal_pending') {
                    $initiateMessage = 'the plan is initiated in renew';
                } elseif ($pcs === 'upgrade_pending') {
                    $childOrder = isset($upgradeStateBySourceSubId[(int) ($item?->id ?? 0)])
                        ? Order::find($upgradeStateBySourceSubId[(int) $item->id]['change_order_id'] ?? 0)
                        : $childChangeOrders->first(fn($co) => in_array(strtolower(trim($co->status ?? '')), ['pending', 'processing', 'draft'], true));
                    if ($childOrder && $this->isPartialUpgradeOrder($childOrder)) {
                        $initiateMessage = 'the plan is initiated in partial upgrade';
                    } elseif ($childOrder && strtolower(trim($childOrder->order_category ?? '')) === 'addon') {
                        $initiateMessage = 'the plan is initiated in add licence';
                    } else {
                        $initiateMessage = 'the plan is initiated in upgrade';
                    }
                } else {
                    $initiateMessage = 'the plan is initiated in upgrade';
                }
            }

            $allowUpgrade = !$isCancelledOrder
                ? (
                    !$this->isPendingPlanChangeOrder($order)
                    && !in_array($itemStatus, ['upgraded', 'downgraded', 'renewed'], true)
                    && !in_array(strtolower($planChangeStatus), [
                        'upgraded',
                        'downgraded',
                        'renewed',
                    ], true)
                )
                : false;
            $upgradeFlags = $this->upgradeButtonFlags($allowUpgrade, null, [
                'provider_id' => (int) ($provider?->id ?? $plan?->provider_id ?? 0),
            ]);

            $hideUpgrade = $upgradeFlags['hide_upgrade'];
            $hidePartialUpgrade = $upgradeFlags['hide_partial_upgrade'];
            $hideAddLicense = $upgradeFlags['hide_add_license'];
            $hideDowngrade = $upgradeFlags['hide_upgrade'];
            $hideRenew = false;

            if ($initiateMessage !== null) {
                $changeKind = null;
                $isPartial = false;
                $isAddon = false;

                if (in_array($pcs, ['upgrade_pending', 'downgrade_pending', 'renewal_pending'], true)) {
                    if ($pcs === 'upgrade_pending') {
                        $changeKind = 'upgrade';
                        $childOrder = isset($upgradeStateBySourceSubId[(int) ($item?->id ?? 0)])
                            ? Order::find($upgradeStateBySourceSubId[(int) $item->id]['change_order_id'] ?? 0)
                            : $childChangeOrders->first(fn($co) => in_array(strtolower(trim($co->status ?? '')), ['pending', 'processing', 'draft'], true));
                        if ($childOrder) {
                            $isPartial = $this->isPartialUpgradeOrder($childOrder);
                            $isAddon = strtolower(trim($childOrder->order_category ?? '')) === 'addon';
                        }
                    } elseif ($pcs === 'downgrade_pending') {
                        $changeKind = 'downgrade';
                    } elseif ($pcs === 'renewal_pending') {
                        $changeKind = 'renewal';
                    }
                } elseif ($this->isPendingPlanChangeOrder($order)) {
                    $changeKind = $this->partnerPlanChangeOrderKind($order);
                    $isPartial = $this->isPartialUpgradeOrder($order);
                    $isAddon = strtolower(trim($order->order_category ?? '')) === 'addon';
                }

                if ($changeKind !== null) {
                    if ($changeKind === 'upgrade') {
                        if ($isPartial) {
                            $hidePartialUpgrade = true;
                        } elseif ($isAddon) {
                            $hideAddLicense = true;
                        } else {
                            $hideUpgrade = true;
                        }
                    } elseif ($changeKind === 'downgrade') {
                        $hideDowngrade = true;
                    } elseif ($changeKind === 'renewal') {
                        $hideRenew = true;
                    }
                }
            }

            $plans[] = [
                'status'                    => $status,
                'plan_status'               => $status,
                'main_cart_id'              => $mainCartId,
                'cart_id'                   => $mainCartId,
                'subscription_no'           => $subscriptionNo,
                'order_sub_id'              => (int)($item?->id ?? 0) ?: null,
                'order_id'                  => (int) $order->id,
                'order_no'                  => (string) ($order->order_no ?? '-'),
                'plan_id'                   => $planId > 0 ? $planId : null,
                'plan_type'                 => (string) ($plan?->plan_type ?? ''),
                'product_name'              => trim((string)($item?->item_name ?? $plan?->name ?? '-')),
                'unit_price'                => round($unitPrice, 2),
                'price_label'               => '₹' . number_format($unitPrice, 0) . ' Per User',
                'price_per_license_per_year' => round($unitPrice, 2),
                'subtotal'                  => round($lineTotal, 2),
                'provider'                  => trim((string)($provider?->name ?? '-')) ?: '-',
                'provider_id'               => $provider?->id ?: null,
                'license'                   => $displayQty,
                'licenses'                  => $displayQty,
                'license_label'             => $displayQty . ' ' . ($displayQty === 1 ? 'User' : 'Users'),
                'original_license'          => $originalQty,
                'original_licenses'         => $originalQty,
                'total_licenses'            => $displayQty,
                'upgraded_licenses'         => $childMovedQty,
                'partial_upgraded_licenses' => $childMovedQty,
                'remaining_licenses'        => $qty,
                'active_licenses'           => $qty,
                'hide_add_license'          => $hideAddLicense,
                'hide_upgrade'              => $hideUpgrade,
                'hide_downgrade'            => $hideDowngrade,
                'hide_partial_upgrade'      => $hidePartialUpgrade,
                'hide_renew'                => $hideRenew,
                'change_via'                => $upgradeFlags['change_via'],
                'requires_request'          => $upgradeFlags['requires_request'],
                'domain'                    => trim((string)($order->domain_name ?? '-')) ?: '-',
                'billing_cycle'             => 'Yearly',
                'start_date'                => $startDateRaw ? \Carbon\Carbon::parse($startDateRaw)->format('d M Y') : '-',
                'renewal_date'              => $endDateRaw ? \Carbon\Carbon::parse($endDateRaw)->format('d M Y') : '-',
                'item_status'               => strtolower((string)($item?->status ?? 'active')),
                'plan_change_status'        => strtolower((string) ($lineDisplay['plan_change_status'] ?? $planChangeStatus)),
                'initiate_message'          => $initiateMessage,
            ];
        }

        // Keep plans[].licenses in sync with order-list merged seats (same as subscriptionDetails)
        if ($hasMergedLicenseAdd) {
            $mergedPlanLicenses = (int) collect($plans)->sum(fn($p) => (int) ($p['licenses'] ?? 0));
            $mergedFloor = max(
                $mergedPlanLicenses,
                (int) ($order->quantity ?? 0),
                (int) ($order->licenses ?? 0)
            );
            if ($mergedFloor > $mergedPlanLicenses && count($plans) === 1) {
                $plans[0]['license'] = $mergedFloor;
                $plans[0]['licenses'] = $mergedFloor;
                $plans[0]['license_label'] = $mergedFloor . ' ' . ($mergedFloor === 1 ? 'User' : 'Users');
                $plans[0]['total_licenses'] = $mergedFloor;
                $plans[0]['remaining_licenses'] = $mergedFloor;
                $plans[0]['active_licenses'] = $mergedFloor;
                $unit = (float) ($plans[0]['price_per_license_per_year'] ?? 0);
                $plans[0]['subtotal'] = round($unit * max(1, $mergedFloor), 2);
            }
        }

        // Selected Plan Match
        $selected = $plans[0] ?? null;
        if ($orderSubId > 0) {
            foreach ($plans as $p) {
                if ((int)($p['order_sub_id'] ?? 0) === $orderSubId) {
                    $selected = $p;
                    break;
                }
            }
        } elseif ($filterPlanId > 0 && $selected) {
            foreach ($plans as $p) {
                if ((int)($p['plan_id'] ?? 0) === $filterPlanId) {
                    $selected = $p;
                    break;
                }
            }
        }

        $pageStatus = trim((string) ($selected['status'] ?? $displayStatus ?? ''));
        if ($pageStatus === '') {
            $pageStatus = 'Processing';
        }

        // Generate Timeline via Isolated Method
        $timelinePayload = $this->buildOrderTimeline($order, $customer, $partnerId);
        $timeline = $timelinePayload['events'] ?? [];
        $changeCounts = $timelinePayload['change_counts'] ?? [];

        // Format Customer Information
        $companyName    = trim((string)($customer?->company_name ?? $customer?->name ?? '-'));
        $contactName    = trim((string)($customer?->name ?? '-'));
        $customerEmail  = trim((string)($customer?->email ?? '-')) ?: '-';
        $customerMobile = trim((string)($customer?->mobile ?? '-')) ?: '-';
        if ($customerMobile !== '-' && !str_starts_with($customerMobile, '+')) {
            $customerMobile = '+91 ' . $customerMobile;
        }

        return response()->json([
            'success' => true,
            'error'   => false,
            'message' => 'Plan detail fetched successfully',
            'data'    => [
                'main_cart_id'          => $mainCartId,
                'cart_id'               => $mainCartId,
                'order_id'              => (int) $order->id,
                'order_no'              => (string) ($order->order_no ?? ''),
                'status'                => $pageStatus,
                'plan_status'           => $pageStatus,
                'order_status'          => $orderStatusRaw,
                'status_detail'         => $hasMergedLicenseAdd
                    ? ('Licenses added: +' . $mergedExtraLicenses . ' license(s)')
                    : null,
                'license'               => (int) ($selected['license'] ?? $selected['licenses'] ?? 1),
                'licenses'              => (int) ($selected['licenses'] ?? $selected['license'] ?? 1),
                'license_label'         => (string) ($selected['license_label'] ?? ''),
                'original_licenses'     => (int) ($selected['original_licenses'] ?? 1),
                'total_licenses'        => (int) ($selected['total_licenses'] ?? 1),
                'upgraded_licenses'     => (int) ($selected['upgraded_licenses'] ?? 0),
                'partial_upgraded_licenses' => (int) ($selected['partial_upgraded_licenses'] ?? 0),
                'remaining_licenses'    => (int) ($selected['remaining_licenses'] ?? 1),
                'active_licenses'       => (int) ($selected['active_licenses'] ?? 1),
                'customer_information'  => [
                    'customer_id'     => $customer?->customer_no ?? str_pad((string)($customer?->id ?? $order->user_id ?? 0), 5, '0', STR_PAD_LEFT),
                    'cust_id'         => (int) ($customer?->id ?? $order->user_id) ?: null,
                    'company_name'    => $companyName,
                    'contact_name'    => $contactName,
                    'primary_contact' => $contactName,
                    'email'           => $customerEmail,
                    'contact_no'      => $customerMobile,
                    'avatar_initial'  => strtoupper(substr($companyName !== '-' ? $companyName : 'C', 0, 1)),
                ],
                'subscription_details' => $selected,
                'plans'                => $plans,
                'plans_count'          => count($plans),
                'can_upgrade'          => (bool) ($selected['can_upgrade'] ?? true),
                'can_partial_upgrade'  => (bool) ($selected['can_partial_upgrade'] ?? true),
                'hide_upgrade'         => (bool) ($selected['hide_upgrade'] ?? false),
                'hide_partial_upgrade' => (bool) ($selected['hide_partial_upgrade'] ?? false),
                'timeline'             => $timeline,
                'timeline_meta'        => [
                    'view_all' => true,
                    'count'    => count($timeline),
                    'order_id' => (int) $orderId,
                    'change_counts' => $changeCounts,
                ],
                'has_license_add_history' => $licenseAddHistoryOrders->isNotEmpty(),
                'license_add_history'     => $licenseAddHistoryOrders->map(function ($child) {
                    return [
                        'order_id'       => (int) $child->id,
                        'order_no'       => $child->order_no,
                        'added_licenses' => (int) ($child->quantity ?? $child->licenses ?? 1),
                        'created_at'     => $child->created_at ? $child->created_at->format('d-m-Y H:i:s') : null,
                        'status'         => $child->status,
                    ];
                })->values()->all(),
                'actions'              => method_exists($this, 'partnerOrderActionFlags') ? $this->partnerOrderActionFlags($order) : [
                    'can_edit' => false,
                    'can_cancel' => false,
                    'edit_blocked_reason' => null,
                    'cancel_blocked_reason' => null
                ],
            ],
        ], 200);
    }


    private function resolveEnrollmentTypeLabel(?object $order, string $hint = ''): string
    {
        $category = strtolower(trim($hint));
        if ($category === '' && $order) {
            $category = strtolower(trim((string) ($order->order_category ?? '')));
        }
        if ($category === '' && $order) {
            $category = strtolower(trim((string) ($order->type ?? $order->order_type ?? '')));
        }

        if (
            in_array($category, ['partial_upgrade', 'partial'], true)
            || $this->isPartialUpgradeOrder($order, $category)
        ) {
            return 'Partial Upgrade';
        }
        if (in_array($category, ['upgrade', 'upgraded'], true)) {
            return 'Upgraded';
        }
        if (in_array($category, ['downgrade', 'downgraded', 'partial_downgrade'], true)) {
            return 'Downgraded';
        }
        if (in_array($category, ['renew', 'renewal', 'renewed'], true)) {
            return 'Renewed';
        }
        if (in_array($category, ['transfer', 'transfer_service'], true)) {
            return 'Transfer Service';
        }

        $transferDomain = strtolower(trim((string) ($order->transfer_domain ?? '')));
        if (in_array($transferDomain, ['yes', '1', 'true'], true)) {
            return 'Transfer Service';
        }

        return 'New Service';
    }

    /**
     * Same-plan license increase on a CH/upgrade order = Partial Upgrade.
     */
    private function isPartialUpgradeOrder(?object $order, string $category = ''): bool
    {
        if (!$order) {
            return false;
        }

        $category = strtolower(trim($category !== '' ? $category : (string) ($order->order_category ?? $order->type ?? '')));
        $orderNo = strtoupper(trim((string) ($order->order_no ?? '')));
        $isUpgradeFlow = in_array($category, ['upgrade', 'upgraded', 'partial_upgrade', 'partial'], true)
            || str_starts_with($orderNo, 'CH');

        if (!$isUpgradeFlow) {
            return false;
        }

        $prev = (int) ($order->previous_plan_id ?? 0);
        $curr = (int) ($order->plan_id ?? 0);
        if ($prev > 0 && $curr > 0 && $prev === $curr) {
            return true;
        }

        $parentSubId = (int) ($order->parent_order_sub_id ?? 0);
        if ($parentSubId > 0 && $curr > 0) {
            $sourcePlan = (int) (OrderItem::query()->whereKey($parentSubId)->value('plan_id') ?? 0);
            if ($sourcePlan > 0 && $sourcePlan === $curr) {
                return true;
            }
        }

        $parentId = (int) ($order->parent_order_id ?? 0);
        if ($parentId > 0 && $curr > 0) {
            $parentHasSamePlan = OrderItem::query()
                ->where('order_id', $parentId)
                ->where('plan_id', $curr)
                ->where(function ($q) {
                    $q->whereNull('status')->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) != 'delete'");
                })
                ->exists();
            if ($parentHasSamePlan) {
                return true;
            }
            $parentPlan = (int) ($this->order->newQuery()->whereKey($parentId)->value('plan_id') ?? 0);
            if ($parentPlan > 0 && $parentPlan === $curr) {
                return true;
            }
        }

        return false;
    }

    private function resolveParentOrderPoPayload(int $orderId): array
    {
        $empty = [
            'source_order_id' => max(0, $orderId),
            'po_link' => null,
            'final_po_link' => null,
            'po_mode' => 'generated',
            'po_number' => '',
            'is_uploaded' => false,
        ];

        if ($orderId <= 0) {
            return $empty;
        }

        $visited = [];
        $currentId = $orderId;
        $fallback = $empty;
        $maxHops = 20;

        while ($currentId > 0 && $maxHops-- > 0 && !isset($visited[$currentId])) {
            $visited[$currentId] = true;

            $poRow = $this->orderPoDetail->newQuery()->where('order_id', $currentId)->first();
            $orderPoUrl = trim((string) (
                $this->order->newQuery()->whereKey($currentId)->value('po_document_url') ?? ''
            ));

            $poDocumentUrl = trim((string) ($poRow->po_document_url ?? ''));
            $finalPoLink = trim((string) ($poRow->final_po_link ?? ''));
            $poMode = strtolower(trim((string) ($poRow->po_mode ?? 'generated')));
            if (!in_array($poMode, ['generated', 'uploaded'], true)) {
                $poMode = 'generated';
            }
            $poNumber = trim((string) ($poRow->po_number ?? ''));

            $poLink = $poDocumentUrl !== ''
                ? $poDocumentUrl
                : ($finalPoLink !== '' ? $finalPoLink : $orderPoUrl);

            $payload = [
                'source_order_id' => $currentId,
                'po_link' => $poLink !== '' ? $poLink : null,
                'final_po_link' => $finalPoLink !== '' ? $finalPoLink : ($poLink !== '' ? $poLink : null),
                'po_mode' => $poMode,
                'po_number' => $poNumber,
                'is_uploaded' => $poMode === 'uploaded',
            ];

            if ($payload['po_link'] !== null) {
                return $payload;
            }

            if ($fallback === $empty && ($poRow || $poNumber !== '')) {
                $fallback = $payload;
            }

            $parentId = (int) (
                $this->order->newQuery()->whereKey($currentId)->value('parent_order_id') ?? 0
            );
            if ($parentId <= 0 || $parentId === $currentId) {
                break;
            }
            $currentId = $parentId;
        }

        return $fallback;
    }

    public function saveNotificationPreferences(Request $request)
    {
        $partnerId = (int) $request->input('partner_id', 0);
        $data = [
            'subscription_sms'        => $request->subscription_sms ?? 0,
            'subscription_whatsapp'   => $request->subscription_whatsapp ?? 0,
            'subscription_email'      => $request->subscription_email ?? 0,
            'security_sms'            => $request->security_sms ?? 0,
            'security_whatsapp'       => $request->security_whatsapp ?? 0,
            'security_email'          => $request->security_email ?? 0,
            'service_sms'             => $request->service_sms ?? 0,
            'service_whatsapp'        => $request->service_whatsapp ?? 0,
            'service_email'           => $request->service_email ?? 0,
            'offers_sms'              => $request->offers_sms ?? 0,
            'offers_whatsapp'         => $request->offers_whatsapp ?? 0,
            'offers_email'            => $request->offers_email ?? 0,
        ];

        $notification = NotificationPreference::updateOrCreate(
            ['partner_id' => $partnerId],
            $data
        );

        return response()->json([
            'success' => true,
            'message' => 'Notification preferences saved successfully',
            'data' => $notification
        ]);
    }


