    public function getNotificationPreferences(Request $request)
    {
        $notification = NotificationPreference::where(
            'partner_id',
            $request->partner_id
        )->first();

        $defaultPreferences = [
            'subscription_sms'      => false,
            'subscription_whatsapp' => false,
            'subscription_email'    => true,

            'security_sms'          => false,
            'security_whatsapp'     => false,
            'security_email'        => true,

            'service_sms'           => false,
            'service_whatsapp'     => false,
            'service_email'         => true,

            'offers_sms'            => false,
            'offers_whatsapp'       => false,
            'offers_email'          => true,
        ];

        // Override only SMS and WhatsApp values from database.
        // Email will always remain true.
        if ($notification) {
            $defaultPreferences['subscription_sms'] =
                (bool) $notification->subscription_sms;

            $defaultPreferences['subscription_whatsapp'] =
                (bool) $notification->subscription_whatsapp;

            $defaultPreferences['security_sms'] =
                (bool) $notification->security_sms;

            $defaultPreferences['security_whatsapp'] =
                (bool) $notification->security_whatsapp;

            $defaultPreferences['service_sms'] =
                (bool) $notification->service_sms;

            $defaultPreferences['service_whatsapp'] =
                (bool) $notification->service_whatsapp;

            $defaultPreferences['offers_sms'] =
                (bool) $notification->offers_sms;

            $defaultPreferences['offers_whatsapp'] =
                (bool) $notification->offers_whatsapp;
        }

        return response()->json([
            'success' => true,
            'data' => $defaultPreferences,
        ]);
    }
    
    /**
     * Render Sales Report chart UI for a partner (presentation + partner-scoped chart data).
     */
    public function renderSalesReportChart(Request $request)
    {
        $partnerId = (int) $request->input('partner_id', $request->query('partner_id', 0));
        if ($partnerId <= 0) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Partner ID is required.',
                'data' => null,
            ], 422);
        }

        $partner = Partner::find($partnerId);
        if (!$partner) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Partner not found.',
                'data' => null,
            ], 404);
        }

        $activePeriod = strtolower(trim((string) $request->input('period', $request->input('range', 'yearly'))));
        if (!in_array($activePeriod, ['weekly', 'monthly', 'yearly'], true)) {
            $activePeriod = 'yearly';
        }

        $periods = [
            'weekly' => is_array($request->input('weekly')) ? $request->input('weekly') : [],
            'monthly' => is_array($request->input('monthly')) ? $request->input('monthly') : [],
            'yearly' => is_array($request->input('yearly')) ? $request->input('yearly') : [],
        ];

        $hasIncomingChart = false;
        foreach (['weekly', 'monthly', 'yearly'] as $periodKey) {
            $set = $periods[$periodKey];
            if (is_array($set) && !empty($set['labels'])) {
                $hasIncomingChart = true;
                break;
            }
        }

        if (!$hasIncomingChart) {
            $paidStatusValues = ['completed', 'success', 'paid', 'active', 'delivered'];

            $buildPartnerBucket = function (Carbon $start, Carbon $end, string $label) use ($partnerId, $paidStatusValues) {
                $orders = $this->order->newQuery()
                    ->where('partner_id', $partnerId)
                    ->whereRaw("LOWER(COALESCE(order_type, 'b2c')) = 'b2b'")
                    ->whereIn(DB::raw('LOWER(status)'), $paidStatusValues)
                    ->whereBetween('created_at', [$start, $end])
                    ->get(['id', 'plan_id', 'total_amount', 'subtotal', 'credit_used']);

                $tizzy = 0.0;
                $microsoft = 0.0;
                $google = 0.0;

                if ($orders->isNotEmpty()) {
                    $items = OrderItem::query()
                        ->whereIn('order_id', $orders->pluck('id')->all())
                        ->where(function ($q) {
                            $q->whereNull('status')
                                ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted')");
                        })
                        ->get(['order_id', 'plan_id', 'total_amount', 'unit_price', 'quantity']);

                    $planIds = $items->pluck('plan_id')->filter()->unique()->values();
                    if ($planIds->isEmpty()) {
                        $planIds = $orders->pluck('plan_id')->filter()->unique()->values();
                    }
                    $plansById = $planIds->isEmpty()
                        ? collect()
                        : $this->plan->newQuery()->whereIn('id', $planIds)->get(['id', 'provider_id'])->keyBy('id');

                    if ($items->isNotEmpty()) {
                        foreach ($items as $item) {
                            $amount = round((float) ($item->total_amount ?? 0), 2);
                            if ($amount <= 0) {
                                $amount = round((float) ($item->unit_price ?? 0) * max(1, (int) ($item->quantity ?? 1)), 2);
                            }
                            $providerId = (int) ($plansById->get($item->plan_id)->provider_id ?? 0);
                            if ($providerId === 1) {
                                $tizzy += $amount;
                            } elseif ($providerId === 2) {
                                $microsoft += $amount;
                            } elseif ($providerId === 3) {
                                $google += $amount;
                            }
                        }
                    } else {
                        foreach ($orders as $order) {
                            $amount = round((float) ($order->total_amount ?? 0), 2);
                            if ($amount <= 0) {
                                $amount = round((float) ($order->credit_used ?? $order->subtotal ?? 0), 2);
                            }
                            $providerId = (int) ($plansById->get($order->plan_id)->provider_id ?? 0);
                            if ($providerId === 1) {
                                $tizzy += $amount;
                            } elseif ($providerId === 2) {
                                $microsoft += $amount;
                            } elseif ($providerId === 3) {
                                $google += $amount;
                            }
                        }
                    }
                }

                $tizzy = round($tizzy, 2);
                $microsoft = round($microsoft, 2);
                $google = round($google, 2);

                return [
                    'label' => $label,
                    'tizzy_sales' => $tizzy,
                    'microsoft_sales' => $microsoft,
                    'google_sales' => $google,
                    'total_sales' => round($tizzy + $microsoft + $google, 2),
                ];
            };

            $weeklyLabels = [];
            $weeklyTizzy = [];
            $weeklyMicrosoft = [];
            $weeklyGoogle = [];
            $weeklyTotal = [];
            for ($i = 7; $i >= 0; $i--) {
                $start = now()->copy()->startOfWeek()->subWeeks($i);
                $end = $start->copy()->endOfWeek();
                $row = $buildPartnerBucket($start, $end, $start->format('d M'));
                $weeklyLabels[] = $row['label'];
                $weeklyTizzy[] = $row['tizzy_sales'];
                $weeklyMicrosoft[] = $row['microsoft_sales'];
                $weeklyGoogle[] = $row['google_sales'];
                $weeklyTotal[] = $row['total_sales'];
            }
            $periods['weekly'] = [
                'labels' => $weeklyLabels,
                'tizzy_sales' => $weeklyTizzy,
                'microsoft_sales' => $weeklyMicrosoft,
                'google_sales' => $weeklyGoogle,
                'total_sales' => $weeklyTotal,
            ];

            $monthlyLabels = [];
            $monthlyTizzy = [];
            $monthlyMicrosoft = [];
            $monthlyGoogle = [];
            $monthlyTotal = [];
            for ($i = 5; $i >= 0; $i--) {
                $start = now()->copy()->startOfMonth()->subMonths($i);
                $end = $start->copy()->endOfMonth();
                $row = $buildPartnerBucket($start, $end, $start->format('M'));
                $monthlyLabels[] = $row['label'];
                $monthlyTizzy[] = $row['tizzy_sales'];
                $monthlyMicrosoft[] = $row['microsoft_sales'];
                $monthlyGoogle[] = $row['google_sales'];
                $monthlyTotal[] = $row['total_sales'];
            }
            $periods['monthly'] = [
                'labels' => $monthlyLabels,
                'tizzy_sales' => $monthlyTizzy,
                'microsoft_sales' => $monthlyMicrosoft,
                'google_sales' => $monthlyGoogle,
                'total_sales' => $monthlyTotal,
            ];

            $yearlyLabels = [];
            $yearlyTizzy = [];
            $yearlyMicrosoft = [];
            $yearlyGoogle = [];
            $yearlyTotal = [];
            for ($i = 11; $i >= 0; $i--) {
                $start = now()->copy()->startOfMonth()->subMonths($i);
                $end = $start->copy()->endOfMonth();
                $row = $buildPartnerBucket($start, $end, $start->format('M y'));
                $yearlyLabels[] = $row['label'];
                $yearlyTizzy[] = $row['tizzy_sales'];
                $yearlyMicrosoft[] = $row['microsoft_sales'];
                $yearlyGoogle[] = $row['google_sales'];
                $yearlyTotal[] = $row['total_sales'];
            }
            $periods['yearly'] = [
                'labels' => $yearlyLabels,
                'tizzy_sales' => $yearlyTizzy,
                'microsoft_sales' => $yearlyMicrosoft,
                'google_sales' => $yearlyGoogle,
                'total_sales' => $yearlyTotal,
            ];
        }

        $providerChart = $request->input('provider_chart', $request->input('providerChart', []));
        if (!is_array($providerChart)) {
            $providerChart = [];
        }
        if (!empty($providerChart['labels']) && empty($periods['yearly'])) {
            $periods['yearly'] = $providerChart;
        }

        $salesGraph = $request->input('sales_graph', $request->input('salesGraph', []));
        if (is_array($salesGraph) && !empty($salesGraph['labels']) && empty($periods['yearly'])) {
            $periods['yearly'] = [
                'labels' => $salesGraph['labels'],
                'tizzy_sales' => $salesGraph['tizzy_sales'] ?? [],
                'microsoft_sales' => $salesGraph['microsoft_sales'] ?? [],
                'google_sales' => $salesGraph['google_sales'] ?? [],
                'total_sales' => $salesGraph['total_sales'] ?? ($salesGraph['salesSeries'] ?? []),
            ];
        }

        $monthlyData = $request->input('monthlyData', $request->input('monthly_data', []));
        if (is_array($monthlyData) && $monthlyData !== [] && empty($periods['yearly'])) {
            $labels = [];
            $tizzy = [];
            $microsoft = [];
            $google = [];
            $total = [];
            foreach ($monthlyData as $row) {
                if (!is_array($row)) {
                    continue;
                }
                $labels[] = (string) ($row['month'] ?? $row['label'] ?? '');
                $tizzy[] = (float) ($row['tizzy_sales'] ?? 0);
                $microsoft[] = (float) ($row['microsoft_sales'] ?? 0);
                $google[] = (float) ($row['google_sales'] ?? 0);
                $total[] = (float) ($row['total_sales'] ?? $row['revenue'] ?? 0);
            }
            $periods['yearly'] = [
                'labels' => $labels,
                'tizzy_sales' => $tizzy,
                'microsoft_sales' => $microsoft,
                'google_sales' => $google,
                'total_sales' => $total,
            ];
        }

        foreach (['weekly', 'monthly', 'yearly'] as $periodKey) {
            $set = $periods[$periodKey];
            if (!is_array($set) || $set === []) {
                $periods[$periodKey] = [
                    'labels' => [],
                    'tizzy_sales' => [],
                    'microsoft_sales' => [],
                    'google_sales' => [],
                    'total_sales' => [],
                ];
                continue;
            }
            if (!empty($set['labels'])) {
                $periods[$periodKey] = [
                    'labels' => array_values($set['labels'] ?? []),
                    'tizzy_sales' => array_values($set['tizzy_sales'] ?? []),
                    'microsoft_sales' => array_values($set['microsoft_sales'] ?? []),
                    'google_sales' => array_values($set['google_sales'] ?? []),
                    'total_sales' => array_values($set['total_sales'] ?? ($set['salesSeries'] ?? [])),
                ];
                continue;
            }
            $rows = $set['monthlyData'] ?? $set['monthly_data'] ?? (isset($set[0]) && is_array($set[0]) ? $set : []);
            if (!is_array($rows) || $rows === []) {
                $periods[$periodKey] = [
                    'labels' => [],
                    'tizzy_sales' => [],
                    'microsoft_sales' => [],
                    'google_sales' => [],
                    'total_sales' => [],
                ];
                continue;
            }
            $labels = [];
            $tizzy = [];
            $microsoft = [];
            $google = [];
            $total = [];
            foreach ($rows as $row) {
                if (!is_array($row)) {
                    continue;
                }
                $labels[] = (string) ($row['month'] ?? $row['label'] ?? '');
                $tizzy[] = (float) ($row['tizzy_sales'] ?? 0);
                $microsoft[] = (float) ($row['microsoft_sales'] ?? 0);
                $google[] = (float) ($row['google_sales'] ?? 0);
                $total[] = (float) ($row['total_sales'] ?? $row['revenue'] ?? 0);
            }
            $periods[$periodKey] = [
                'labels' => $labels,
                'tizzy_sales' => $tizzy,
                'microsoft_sales' => $microsoft,
                'google_sales' => $google,
                'total_sales' => $total,
            ];
        }


        $html = '';

        $responseData = [
            'partner_id' => $partnerId,
            'period' => $activePeriod,
            'chart' => $periods,
            'html' => $html,
        ];

        if ($request->boolean('html_only') || $request->input('format') === 'html') {
            return response($html, 200)->header('Content-Type', 'text/html; charset=UTF-8');
        }

        return response()->json([
            'success' => true,
            'error' => false,
            'message' => 'Sales report chart fetched successfully.',
            'data' => $responseData,
        ]);
    }

    /**
     * Sales report chart data for partner dashboard (JSON only).
     */
    public function salesReport(Request $request): JsonResponse
    {
        $partnerId = (int) $request->query('partner_id', $request->input('partner_id', 0));
        if ($partnerId <= 0) {
            return response()->json([
                'status' => false,
                'message' => 'Partner ID is required.',
            ], 422);
        }

        $partner = Partner::find($partnerId);
        if (!$partner) {
            return response()->json([
                'status' => false,
                'message' => 'Partner not found.',
            ], 404);
        }

        $period = strtolower(trim((string) $request->input('period', $request->query('period', 'monthly'))));
        if (!in_array($period, ['weekly', 'monthly', 'yearly'], true)) {
            $period = 'monthly';
        }

        $labels = [];
        $tizzyMail = [];
        $microsoftSolution = [];
        $googleCloud = [];
        $totalSales = [];

        $paidStatusValues = ['completed', 'success', 'paid', 'active', 'delivered'];

        $buildPartnerBucket = function (Carbon $start, Carbon $end, string $label) use ($partnerId, $paidStatusValues) {
            $orders = $this->order->newQuery()
                ->where('partner_id', $partnerId)
                ->whereRaw("LOWER(COALESCE(order_type, 'b2c')) = 'b2b'")
                ->whereIn(DB::raw('LOWER(status)'), $paidStatusValues)
                ->whereBetween('created_at', [$start, $end])
                ->get(['id', 'plan_id', 'total_amount', 'subtotal', 'credit_used']);

            $tizzy = 0.0;
            $microsoft = 0.0;
            $google = 0.0;

            if ($orders->isNotEmpty()) {
                $items = OrderItem::query()
                    ->whereIn('order_id', $orders->pluck('id')->all())
                    ->where(function ($q) {
                        $q->whereNull('status')
                            ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted')");
                    })
                    ->get(['order_id', 'plan_id', 'total_amount', 'unit_price', 'quantity']);

                $planIds = $items->pluck('plan_id')->filter()->unique()->values();
                if ($planIds->isEmpty()) {
                    $planIds = $orders->pluck('plan_id')->filter()->unique()->values();
                }
                $plansById = $planIds->isEmpty()
                    ? collect()
                    : $this->plan->newQuery()->whereIn('id', $planIds)->get(['id', 'provider_id'])->keyBy('id');

                if ($items->isNotEmpty()) {
                    foreach ($items as $item) {
                        $amount = round((float) ($item->total_amount ?? 0), 2);
                        if ($amount <= 0) {
                            $amount = round((float) ($item->unit_price ?? 0) * max(1, (int) ($item->quantity ?? 1)), 2);
                        }
                        $providerId = (int) ($plansById->get($item->plan_id)->provider_id ?? 0);
                        if ($providerId === 1) {
                            $tizzy += $amount;
                        } elseif ($providerId === 2) {
                            $microsoft += $amount;
                        } elseif ($providerId === 3) {
                            $google += $amount;
                        }
                    }
                } else {
                    // Old orders without items â€” use order header amount once.
                    foreach ($orders as $order) {
                        $amount = round((float) ($order->total_amount ?? 0), 2);
                        if ($amount <= 0) {
                            $amount = round((float) ($order->credit_used ?? $order->subtotal ?? 0), 2);
                        }
                        $providerId = (int) ($plansById->get($order->plan_id)->provider_id ?? 0);
                        if ($providerId === 1) {
                            $tizzy += $amount;
                        } elseif ($providerId === 2) {
                            $microsoft += $amount;
                        } elseif ($providerId === 3) {
                            $google += $amount;
                        }
                    }
                }
            }

            $tizzy = round($tizzy, 2);
            $microsoft = round($microsoft, 2);
            $google = round($google, 2);

            return [
                'label' => $label,
                'tizzy_sales' => $tizzy,
                'microsoft_sales' => $microsoft,
                'google_sales' => $google,
                'total_sales' => round($tizzy + $microsoft + $google, 2),
            ];
        };

        if ($period === 'weekly') {
            for ($i = 7; $i >= 0; $i--) {
                $start = now()->copy()->startOfWeek()->subWeeks($i);
                $end = $start->copy()->endOfWeek();
                $row = $buildPartnerBucket($start, $end, $start->format('d M'));
                $labels[] = $row['label'];
                $tizzyMail[] = $row['tizzy_sales'];
                $microsoftSolution[] = $row['microsoft_sales'];
                $googleCloud[] = $row['google_sales'];
                $totalSales[] = $row['total_sales'];
            }
        } elseif ($period === 'yearly') {
            for ($i = 11; $i >= 0; $i--) {
                $start = now()->copy()->startOfMonth()->subMonths($i);
                $end = $start->copy()->endOfMonth();
                $row = $buildPartnerBucket($start, $end, $start->format('M y'));
                $labels[] = $row['label'];
                $tizzyMail[] = $row['tizzy_sales'];
                $microsoftSolution[] = $row['microsoft_sales'];
                $googleCloud[] = $row['google_sales'];
                $totalSales[] = $row['total_sales'];
            }
        } else {
            for ($i = 5; $i >= 0; $i--) {
                $start = now()->copy()->startOfMonth()->subMonths($i);
                $end = $start->copy()->endOfMonth();
                $row = $buildPartnerBucket($start, $end, $start->format('M'));
                $labels[] = $row['label'];
                $tizzyMail[] = $row['tizzy_sales'];
                $microsoftSolution[] = $row['microsoft_sales'];
                $googleCloud[] = $row['google_sales'];
                $totalSales[] = $row['total_sales'];
            }
        }

        // Add x_axis and y_axis keys in response
        $xAxis = [
            'label' => 'Period',
            'values' => $labels,
        ];
        $yAxis = [
