                    'data'  => $tizzyMail,
                ],
                [
                    'label' => 'Microsoft Solution',
                    'key'   => 'microsoft_solution',
                    'data'  => $microsoftSolution,
                ],
                [
                    'label' => 'Google Cloud',
                    'key'   => 'google_cloud',
                    'data'  => $googleCloud,
                ],
                [
                    'label' => 'Total Sales',
                    'key'   => 'total_sales',
