    public function notificationList(Request $request)
    {
        $partnerId = (int) ($this->resolvePartnerId($request) ?? 0);
        if ($partnerId <= 0) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Partner ID is required.',
                'data' => [],
            ], 422);
        }

        $partnerExists = Partner::query()->whereKey($partnerId)->exists();
        if (!$partnerExists) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Partner not found.',
                'data' => [],
            ], 404);
        }

        $notifications = Notification::query()
            ->where('partner_id', $partnerId)
            ->orderByDesc('created_at')
            ->get([
                'id',
                'partner_id',
                'title',
                'message',
                'is_read',
                'order_id',
                'order_sub_id',
                'main_cart_id',
                'type',
                'created_at',
            ]);

        $orderIds = $notifications->pluck('order_id')
            ->filter(static fn($id) => (int) $id > 0)
            ->map(static fn($id) => (int) $id)
            ->unique()
            ->values()
            ->all();

        $customerIdByOrderId = $orderIds !== []
            ? Order::query()->whereIn('id', $orderIds)->pluck('user_id', 'id')
            : collect();

        $cartIds = $notifications->pluck('main_cart_id')
            ->filter(static fn($id) => (int) $id > 0)
            ->map(static fn($id) => (int) $id)
            ->unique()
            ->values()
            ->all();

        $licensesByCartId = $cartIds !== []
            ? PurchaseRequest::query()
                ->whereIn('cart_id', $cartIds)
                ->orderByDesc('id')
                ->get(['cart_id', 'licenses'])
                ->unique('cart_id')
                ->pluck('licenses', 'cart_id')
            : collect();

        $notifications = $notifications->map(static function ($row) use ($customerIdByOrderId, $licensesByCartId) {
            $orderId  = (int) ($row->order_id ?? 0);
            $mainCartId = (int) ($row->main_cart_id ?? 0);
            if($row->type === 'renew'){
                $type = 'renew-plan';
            }elseif($row->type === 'license_add'){
                $type = 'add-license';
            }else{
                if($row->title === 'Order cancelled — credit note generated'){
                    $type = 'credit-note';
                }else{
                    $type = $row->type;
                }
            }
            if($row->main_cart_id != ''){
                $OrderItem = OrderItem::where('id', $row->order_sub_id)->first();
                if($OrderItem){
                    $plan_id = $OrderItem->plan_id;
                }else{
                    $plan_id = null;
                }
            }else{
                $plan_id = null;
            }

            $licenses = $mainCartId > 0
                ? (int) ($licensesByCartId->get($mainCartId) ?? 0)
                : 0;
            
            return [
                'notification_id' => (int) $row->id,
                'id' => (int) $row->id,
                'partner_id' => (int) $row->partner_id,
                'title' => (string) ($row->title ?? ''),
                'message' => (string) ($row->message ?? ''),
                'is_read' => (bool) $row->is_read,
                'order_id' => $orderId > 0 ? $orderId : null,
                'main_cart_id' => $mainCartId > 0 ? $mainCartId : null,
                'customer_id' => $orderId > 0 ? (int) ($customerIdByOrderId->get($orderId) ?? 0) : null,
                'created_at' => $row->created_at,
                'order_sub_id' => (int) ($row->order_sub_id ?? 0) ?: null,
                'type' => (string) ($type ?? ''),
                'plan_id' => $plan_id,
                'licenses' => $licenses > 0 ? $licenses : null,
            ];
        })->values();

        $unreadCount = $notifications->where('is_read', false)->count();

        return response()->json([
            'success' => true,
            'message' => 'Notifications fetched successfully.',
            'data' => $notifications,
            'unread_count' => (int) $unreadCount,
        ]);
    }

    /**
     * Partner credit notes list (cancellation CNs) with wallet credit status.
     * POST /api/partner/credit-notes  body: partner_id
     */
    public function creditNotesList(Request $request): JsonResponse
    {
        $partnerId = (int) ($this->resolvePartnerId($request) ?? 0);
        if ($partnerId <= 0) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Partner ID is required.',
                'data' => [],
            ], 422);
        }

        $partner = Partner::query()->whereKey($partnerId)->first();
        if (!$partner) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Partner not found.',
                'data' => [],
            ], 404);
        }

        $list = app(\App\Services\OrderCancellationCreditNoteService::class)->listForPartner($partnerId);
        $credited = collect($list)->where('wallet_credited', true)->values();
        $pending = collect($list)->where('wallet_credited', false)->values();
        $availableBalance = round(PartnerCreditService::remainingPurchaseAllowance($partnerId), 2);

        // Each row gets filter_status = Credited | Pending | Cancelled | Failed (matches the frontend chips)
        $rows = collect($list)->map(function ($row) {
            $row = (array) $row;
            $raw = strtolower(implode(' ', array_filter([
                $row['status'] ?? '', $row['wallet_status'] ?? '', $row['credit_note_status'] ?? '',
            ], 'is_string')));
            $row['filter_status'] = !empty($row['wallet_credited']) ? 'Credited'
                : (str_contains($raw, 'cancel') ? 'Cancelled' : (str_contains($raw, 'fail') ? 'Failed' : 'Pending'));

            return $row;
        });

        // search: any text/number field (credit note no, order no, domain, customer, amount ...)
        $search = mb_strtolower(trim((string) $request->input('search', '')));
        if ($search !== '') {
            $rows = $rows->filter(fn ($row) => str_contains(
                mb_strtolower(implode(' ', array_filter($row, fn ($v) => is_string($v) || is_numeric($v)))),
                $search
            ))->values();
        }

        // Chip counts follow search but not the status filter
        $statusCount = collect(['Credited', 'Pending', 'Cancelled', 'Failed'])
            ->map(fn ($s) => ['key' => $s, 'value' => $rows->where('filter_status', $s)->count()])->all();

        // status=credited | pending,failed (comma separated)
        $statusFilter = collect(explode(',', strtolower((string) $request->input('status', ''))))
            ->map(fn ($s) => trim($s))->filter(fn ($s) => $s !== '' && $s !== 'all')->values()->all();
        if ($statusFilter) {
            $rows = $rows->filter(fn ($row) => in_array(strtolower($row['filter_status']), $statusFilter, true))->values();
        }

        // Paginate only when page_no / per_page is sent, so existing callers still get the full list
        $total = $rows->count();
        $paginate = $request->filled('per_page') || $request->filled('page_no') || $request->filled('page');
        $perPage = $paginate ? max(1, min(100, (int) $request->input('per_page', 10))) : max(1, $total);
        $pageNo = $paginate ? max(1, (int) $request->input('page_no', $request->input('page', 1))) : 1;
        $pageRows = $rows->forPage($pageNo, $perPage)->values()->all();

        return response()->json([
            'success' => true,
            'message' => 'Credit notes fetched successfully.',
            'data' => [
                'count' => [
                    [
                        "key" => "Total Credit Notes",
                        "value" => count($list)
                    ],
                    [
                        "key" => "Credited to Wallet",
                        "value" => $credited->count()
                    ],
                    [
                        "key" => "Pending Wallet Credit",
                        "value" => $pending->count()
                    ],
                    [
                        "key" => "Total Credit Note Amount",
                        "value" => round((float) collect($list)->sum('credit_note_amount'), 2)
                    ],
                    [
                        "key" => "Total Credited Amount",
                        "value" => round((float) $credited->sum('credit_note_amount'), 2)
                    ]
                ],
                'credit_notes' => $pageRows,
                'status_count' => $statusCount,
                'pagination' => [
                    'total' => $total,
                    'per_page' => $perPage,
                    'current_page' => $pageNo,
                    'last_page' => max(1, (int) ceil($total / $perPage)),
                    'from' => $pageRows ? ($pageNo - 1) * $perPage + 1 : null,
                    'to' => $pageRows ? ($pageNo - 1) * $perPage + count($pageRows) : null,
                ],
                'wallet_balance' => $availableBalance,
                'available_balance' => $availableBalance,
                'credit_limit' => round((float) ($partner->credit_limit ?? 0), 2),
                'credit_used' => round(PartnerCreditService::summarizeUsedCredit($partnerId), 2),
                'remaining_credit_limit' => $availableBalance,
                'summary' => [
                    'total_credit_note_amount' => round((float) collect($list)->sum('credit_note_amount'), 2),
                    'total_credited_amount' => round((float) $credited->sum('credit_note_amount'), 2),
                ]
            ],
        ]);
    }

    /**
     * Submit / refresh a renewal license decrease request (pending SuperAdmin approval).
     * POST /api/partner/license-decrease-request
     */
    public function licenseDecreaseRequest(Request $request): JsonResponse
    {
        // Accept common aliases from partner apps.
        if (!$request->filled('requested_licenses')) {
            if ($request->filled('licenses')) {
                $request->merge(['requested_licenses' => (int) $request->input('licenses')]);
            } elseif ($request->filled('license_count')) {
                $request->merge(['requested_licenses' => (int) $request->input('license_count')]);
            }
        }

        $validated = $request->validate([
            'partner_id' => ['required', 'integer'],
            'order_id' => ['required', 'integer'],
            'requested_licenses' => ['required', 'integer', 'min:1'],
            'licenses' => ['nullable', 'integer', 'min:1'],
            'license_count' => ['nullable', 'integer', 'min:1'],
            'cart_id' => ['nullable', 'integer'],
            'plan_id' => ['nullable', 'integer'],
            'remarks' => ['nullable', 'string', 'max:500'],
        ]);

        $partnerId = (int) $validated['partner_id'];
        $requested = (int) ($validated['requested_licenses'] ?? 0);

        $result = app(\App\Services\LicenseDecreaseRequestService::class)->createOrUpdatePending(
            $partnerId,
            (int) $validated['order_id'],
            $requested,
            isset($validated['cart_id']) ? (int) $validated['cart_id'] : null,
            isset($validated['plan_id']) ? (int) $validated['plan_id'] : null,
            (string) ($validated['remarks'] ?? '')
        );

        $req = $result['request'] ?? null;
        $statusCode = !empty($result['ok']) ? 200 : 422;

        return response()->json([
            'success' => !empty($result['ok']),
            'message' => (string) ($result['message'] ?? ''),
            'code' => !empty($result['requires_approval'])
                ? 'license_decrease_approval_required'
                : (!empty($result['ok']) ? null : 'license_decrease_not_applicable'),
            'data' => [
                'requires_approval' => (bool) ($result['requires_approval'] ?? false),
                'request_id' => $req ? (int) $req->id : null,
                'status' => $req ? (string) $req->status : null,
                'order_id' => (int) $validated['order_id'],
                'current_licenses' => (int) ($result['current_licenses'] ?? 0),
                'requested_licenses' => (int) ($result['requested_licenses'] ?? $requested),
            ],
        ], $statusCode);
    }

