    public function notificationDelete(Request $request): JsonResponse
    {
        $params = $this->resolveNotificationRequestParams($request);
        $partnerId = $params['partner_id'];
        $id = $params['notification_id'];

        if ($id <= 0) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Notification ID is required.',
                'data' => [],
            ], 422);
        }

        if ($partnerId <= 0) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Partner ID is required.',
                'data' => [],
            ], 422);
        }

        $deleted = Notification::query()
            ->where('partner_id', $partnerId)
            ->whereKey($id)
            ->delete();

        if (!$deleted) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Notification not found.',
                'data' => [],
            ], 404);
        }

        return response()->json([
            'success' => true,
            'message' => 'Notification deleted successfully.',
            'data' => [],
        ]);
    }

    public function notificationRead(Request $request): JsonResponse
    {
        $params = $this->resolveNotificationRequestParams($request);
        $partnerId = $params['partner_id'];
        $id = $params['notification_id'];

        if ($partnerId <= 0 || $id <= 0) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Partner ID and notification ID are required.',
                'data' => [],
            ], 422);
        }

        $notification = Notification::query()
            ->where('partner_id', $partnerId)
            ->whereKey($id)
            ->first();

        if (!$notification) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Notification not found.',
                'data' => [],
            ], 404);
        }

        $notification->update(['is_read' => true]);

        return response()->json([
            'success' => true,
            'message' => 'Notification marked as read.',
            'data' => $notification->fresh()->only([
                'id',
                'partner_id',
                'title',
                'message',
                'is_read',
                'created_at',
            ]),
        ]);
    }

    /**
     * Resolve partner + notification ids from body, query, or Bearer token.
     * Accepts id, notification_id, and notificationId (list API returns notification_id).
     */
    private function resolveNotificationRequestParams(Request $request): array
    {
        $partnerId = (int) ($this->resolvePartnerId($request) ?? 0);

        $notificationId = $request->input(
            'notification_id',
            $request->input(
                'notificationId',
                $request->input(
                    'id',
                    $request->query(
                        'notification_id',
                        $request->query('notificationId', $request->query('id', 0))
                    )
                )
            )
        );

        return [
            'partner_id'      => $partnerId,
            'notification_id' => (int) $notificationId,
        ];
    }


    public function renewcart(Request $request): JsonResponse
    {
        $validated = $request->validate([
            'partner_id' => ['required', 'integer', 'exists:pgsql_auth.partners,id'],
            'order_id' => ['required', 'integer', 'exists:pgsql_billing.orders,id'],
            'order_sub_id' => ['required', 'integer', 'exists:pgsql_billing.order_items,id'],
            'plan_id' => ['required', 'integer', 'exists:pgsql_product.plans,id'],
        ]);

        $partnerId = (int) $validated['partner_id'];
        $orderId = (int) $validated['order_id'];
        $orderSubId = (int) $validated['order_sub_id'];

        $order = Order::query()
            ->whereKey($orderId)
            ->where('partner_id', $partnerId)
            ->first();

        if (!$order) {
            return response()->json([
                'success' => false,
                'message' => 'Order not found for this partner.',
            ], 404);
        }

        // --- GET PROCESSING ORDERS FOR CREDIT CHECK (Provider Independent) ---
        $processingOrdersAmount = 0;
        $processingOrdersCount = 0;
        try {
            $processingOrders = Order::query()
                ->where('partner_id', $partnerId)
                ->where('order_type', 'b2b')
                ->whereIn('status', ['processing', 'pending', 'waiting'])
                ->get();

            $processingOrdersCount = $processingOrders->count();
            foreach ($processingOrders as $order) {
                $amount = round((float) ($order->total_amount ?? $order->subtotal ?? 0), 2);
                $processingOrdersAmount += $amount;
            }
        } catch (\Throwable $e) {
            Log::warning('Failed to fetch processing orders for credit check', [
                'partner_id' => $partnerId,
                'error' => $e->getMessage(),
            ]);
        }

        $partner = Partner::query()->whereKey($partnerId)->first();

        // --- CREDIT CALCULATIONS ---
        $creditLimit = round((float) ($partner->credit_limit ?? 0), 2);
        $creditUsedTotal = round(PartnerCreditService::summarizeUsedCredit((int) $partnerId), 2);
        $remainingLimit = round(PartnerCreditService::remainingPurchaseAllowance((int) $partnerId), 2);
        $creditLimitReached = PartnerCreditService::isCreditLimitFullyUsed((int) $partnerId);

        // --- CREDIT LOCKED BY PROCESSING ORDERS (Provider Independent) ---
        $creditLockedByProcessing = false;
        $creditLockedMessage = null;
        $availableCreditForPurchase = $remainingLimit;

        if ($processingOrdersAmount > 0 && $processingOrdersAmount > $availableCreditForPurchase) {
            $creditLockedByProcessing = true;
            $creditLockedMessage = '₹' . number_format($processingOrdersAmount, 2) . ' worth of orders are in processing state. Available credit: ₹' . number_format($availableCreditForPurchase, 2);
        } elseif ($processingOrdersAmount > 0 && $availableCreditForPurchase <= 0) {
            $creditLockedByProcessing = true;
            $creditLockedMessage = 'Credit balance is fully utilized by ' . $processingOrdersCount . ' processing order(s).';
        } elseif ($processingOrdersAmount > 0 && $creditLimitReached) {
            $creditLockedByProcessing = true;
            $creditLockedMessage = 'Credit limit is fully used by ' . $processingOrdersCount . ' processing order(s).';
        } elseif ($processingOrdersAmount > 0 && $availableCreditForPurchase > 0 && $availableCreditForPurchase >= $processingOrdersAmount) {
            $creditLockedByProcessing = false;
            $creditLockedMessage = null;
        } else {
            $creditLockedByProcessing = false;
            $creditLockedMessage = null;
        }

        $selectedPlanId = (int) ($validated['plan_id'] ?? $order->plan_id ?? 0);
        if ($selectedPlanId <= 0) {
            return response()->json([
                'success' => false,
                'message' => 'Plan is required for renew.',
            ], 422);
        }

        // Get the specific order item for this plan
        $selectedItem = OrderItem::query()
            ->where('id', $orderSubId)
            ->where('plan_id', $selectedPlanId)
            ->where(function ($q) {
                $q->whereNull('status')
                    ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted', 'cancelled')");
            })
            ->orderByDesc('id')
            ->first();

        if (!$selectedItem) {
            $selectedItem = OrderItem::query()
                ->where('id', $orderSubId)
                ->where(function ($q) {
                    $q->whereNull('status')
                        ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted', 'cancelled')");
                })
                ->orderByDesc('id')
                ->first();

            if (!$selectedItem) {
                return response()->json([
                    'success' => false,
                    'message' => 'No active order items found for this order.',
                ], 422);
            }
        }

        $licenses = max(1, (int) ($selectedItem->quantity ?? 1));

        $unitPrice = round((float) ($selectedItem->unit_price ?? $order->price ?? 0), 2);
        if ($unitPrice <= 0) {
            $baseQty = max(1, (int) ($selectedItem->quantity ?? $order->quantity ?? 1));
            $baseTotal = (float) ($selectedItem->total_amount ?? $order->total_amount ?? 0);
            if ($baseTotal > 0) {
                $unitPrice = round($baseTotal / $baseQty, 2);
            }
        }

        $existingCart = Cart::query()
            ->with(['items.plan'])
            ->where('partner_id', $partnerId)
            ->where('order_id', $orderId)
            ->where('type', Cart::TYPE_RENEW)
            ->whereNotIn('status', [Cart::STATUS_CONVERTED, 'inactive'])
            ->orderByDesc('id')
            ->first();

        if ($existingCart) {
            $cart = $existingCart;
            $action = 'fetched';
        } else {
            $coupon = trim((string) ($order->promo_code ?? ''));
            $subtotal = round(max(0, $unitPrice * $licenses), 2);
            $discount = round((float) ($selectedItem->discount_amount ?? 0), 2);
            $gstPercent = round((float) ($selectedItem->tax_rate ?? $order->gst_rate ?? $order->gst_percentage ?? 0), 2);
            if ($gstPercent <= 0) {
                $gstPercent = 18.0;
            }
            $gstAmount = round(max(0, (($subtotal - $discount) * $gstPercent) / 100), 2);
            $grandTotal = round(max(0, $subtotal - $discount + $gstAmount), 2);

            $renewalDates = app(B2bSubscriptionRenewalService::class)
                ->calculateRenewalSummary($order, $licenses);

            // --- CALCULATE CAN PURCHASE ---
            $canPurchase = false;
            if (!$creditLimitReached) {
                if ($grandTotal <= 0.005) {
                    $canPurchase = true;
                } elseif ($grandTotal <= $availableCreditForPurchase) {
                    $canPurchase = true;
                } elseif ($creditLockedByProcessing && $grandTotal <= ($availableCreditForPurchase + $processingOrdersAmount)) {
                    $canPurchase = true;
                }
            }

            // --- BUILD PURCHASE BLOCK MESSAGE ---
            $purchaseBlockMessage = null;
            if ($creditLockedByProcessing) {
                $purchaseBlockMessage = 'Credit is locked because ₹' . number_format($processingOrdersAmount, 2) . ' worth of orders are in processing state. Available credit: ₹' . number_format($availableCreditForPurchase, 2);
            } elseif ($creditLimitReached) {
                $purchaseBlockMessage = 'Credit limit reached. You cannot buy additional items.';
            } elseif (!$canPurchase && $grandTotal > $availableCreditForPurchase) {
                $purchaseBlockMessage = 'Insufficient credit. Required: ₹' . number_format($grandTotal, 2) . ', Available: ₹' . number_format($availableCreditForPurchase, 2);
            } else {
                $purchaseBlockMessage = 'Sufficient credit allocation available to complete this purchase';
            }

            if (!$canPurchase) {
                return response()->json([
                    'success' => false,
                    'message' => (string) ($purchaseBlockMessage ?? PartnerCreditService::CREDIT_LIMIT_REACHED_MESSAGE),
                    'code' => 'credit_limit_exceeded',
                    // --- CREDIT KEYS ---
                    'credit_limit' => $creditLimit,
                    'credit_used' => $creditUsedTotal,
                    'remaining_credit_limit' => $remainingLimit,
                    'credit_limit_reached' => $creditLimitReached,
                    'can_purchase' => $canPurchase,
                    'purchase_block_message' => $purchaseBlockMessage,
                    'credit_applicable' => true,
                    'credit_zero_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
                    'is_credit_applicable' => true,
                    'credit_blocked' => $creditLockedByProcessing,
                    'credit_block_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
                    'processing_orders_amount' => round($processingOrdersAmount, 2),
                    'processing_orders_count' => $processingOrdersCount,
                    'credit_locked_by_processing_orders' => $creditLockedByProcessing,
                    'credit_lock_message' => $creditLockedMessage,
                    'available_credit_for_purchase' => round($availableCreditForPurchase, 2),
                ], 422);
            }

            $cart = Cart::query()->create([
                'partner_id' => $partnerId,
                'order_id' => $orderId,
                'customer_id' => (int) ($order->user_id ?? 0) ?: null,
                'provider_id' => !empty($order->provider_id) ? (int) $order->provider_id : null,
                'domain_name' => trim((string) ($order->domain_name ?? '')) ?: null,
                'type' => Cart::TYPE_RENEW,
                'coupen' => $coupon !== '' ? strtoupper($coupon) : null,
                'status' => Cart::STATUS_ACTIVE,
                'currency' => trim((string) ($order->currency ?? 'INR')) ?: 'INR',
                'discount_amount' => $discount,
                'gst_percentage' => $gstPercent,
                'order_sub_id' => $orderSubId,
                'gst_amount' => $gstAmount,
                'grand_total' => $grandTotal,
            ]);

            // Store the cart item in a variable
            $cartItem = CartItem::query()->create([
                'cart_id' => (int) $cart->id,
                'plan_id' => $selectedPlanId,
                'licenses' => $licenses,
                'unit_price' => $unitPrice,
                'grand_total' => $subtotal,
                'subscription_start_date' => $renewalDates['subscription_start_date'] ?? null,
                'subscription_end_date' => $renewalDates['subscription_end_date'] ?? null,
                'added_at' => now(),
            ]);

            // Load the cart with items
            $cart->load(['items.plan']);
            $action = 'created';
        }

        // Use the cart item we created, or fetch it if cart existed
        if ($action === 'created') {
            $savedCartItem = $cartItem;
        } else {
            $savedCartItem = CartItem::where('cart_id', $cart->id)
                ->where('plan_id', $selectedPlanId)
                ->first();
        }
        if (!$savedCartItem) {
            $savedCartItem = CartItem::create([
                'cart_id' => $cart->id,
                'plan_id' => $selectedPlanId,
                'licenses' => $licenses,
                'unit_price' => $unitPrice,
                'grand_total' => $subtotal,
                'subscription_start_date' => $renewalDates['subscription_start_date'],
                'subscription_end_date' => $renewalDates['subscription_end_date'],
                'added_at' => now(),
            ]);

            $cart->load('items.plan');
        }

        // Use the saved cart item licenses
        $responseLicenses = max(1, (int) ($savedCartItem->licenses ?? 1));
        $responseUnitPrice = round((float) ($savedCartItem->unit_price ?? 0), 2);
        $subtotal = round(max(0, $responseUnitPrice * $responseLicenses), 2);
        $discount = round((float) ($cart->discount_amount ?? 0), 2);
        $gstPercent = round((float) ($cart->gst_percentage ?? 18), 2);
        $gstAmount = round((float) ($cart->gst_amount ?? 0), 2);
        $grandTotal = round((float) ($cart->grand_total ?? 0), 2);
        $coupon = trim((string) ($cart->coupen ?? ''));
        $cartStatus = (string) ($cart->status ?? Cart::STATUS_ACTIVE);

        // --- RECALCULATE CAN PURCHASE ---
        $canPurchase = false;
        if (!$creditLimitReached) {
            if ($grandTotal <= 0.005) {
                $canPurchase = true;
            } elseif ($grandTotal <= $availableCreditForPurchase) {
                $canPurchase = true;
            } elseif ($creditLockedByProcessing && $grandTotal <= ($availableCreditForPurchase + $processingOrdersAmount)) {
                $canPurchase = true;
            }
        }

        // --- BUILD PURCHASE BLOCK MESSAGE ---
        $purchaseBlockMessage = null;
        if ($creditLockedByProcessing) {
            $purchaseBlockMessage = 'Credit is locked because ₹' . number_format($processingOrdersAmount, 2) . ' worth of orders are in processing state. Available credit: ₹' . number_format($availableCreditForPurchase, 2);
        } elseif ($creditLimitReached) {
            $purchaseBlockMessage = 'Credit limit reached. You cannot buy additional items.';
        } elseif (!$canPurchase && $grandTotal > $availableCreditForPurchase) {
            $purchaseBlockMessage = 'Insufficient credit. Required: ₹' . number_format($grandTotal, 2) . ', Available: ₹' . number_format($availableCreditForPurchase, 2);
        } else {
            $purchaseBlockMessage = 'Sufficient credit allocation available to complete this purchase';
        }

        $plan = Plan::query()->whereKey($selectedPlanId)->first();
        $planName = (string) ($savedCartItem->item_name ?? '');
        if ($planName === '') {
            $planName = (string) ($plan->name ?? '');
        }
        $renewFlags = $this->upgradeButtonFlags(true, null, [
            'provider_id' => (int) ($plan->provider_id ?? $order->provider_id ?? 0),
        ]);

        $isApprovedRequest = PurchaseRequest::query()
            ->where('cart_id', (int) $cart->id)
            ->where('status', PurchaseRequest::STATUS_APPROVED)
            ->exists();
        if ($isApprovedRequest) {
            $renewFlags['requires_request'] = false;
            $renewFlags['change_via'] = 'cart';
        }

        $renewalDates = app(B2bSubscriptionRenewalService::class)
            ->calculateRenewalSummary($order, $responseLicenses);
        $renewalStartRaw = (string) ($renewalDates['subscription_start_date'] ?? '');
        $renewalEndRaw = (string) ($renewalDates['subscription_end_date'] ?? '');
        if ($renewalStartRaw !== '' && $renewalEndRaw !== '') {
            $savedCartItem->subscription_start_date = $renewalStartRaw;
            $savedCartItem->subscription_end_date = $renewalEndRaw;
            if ($savedCartItem->isDirty()) {
                $savedCartItem->save();
            }
        }
        $renewalStartDate = $renewalStartRaw !== ''
            ? Carbon::parse($renewalStartRaw)->format('d-m-Y')
            : null;
        $renewalEndDate = $renewalEndRaw !== ''
            ? Carbon::parse($renewalEndRaw)->format('d-m-Y')
            : null;
        $renewFromDate = !empty($renewalDates['renew_from'])
            ? Carbon::parse((string) $renewalDates['renew_from'])->format('d M Y')
            : null;

        $sourcePo = $this->resolveParentOrderPoPayload($orderId);

        return response()->json([
            'success' => true,
            'message' => $action === 'created'
                ? 'Renew cart created successfully.'
                : 'Renew cart fetched successfully.',
            'data' => [
                'company_info' => [
                    'partner_id' => $partnerId,
                    'order_id' => $orderId,
                    'company_name' => (string) ($partner->company_name ?? $partner->name ?? ''),
                ],
                'status' => $cartStatus,
                'requires_request' => $renewFlags['requires_request'],
                'change_via' => $renewFlags['change_via'],
                'plans' => [[
                    'provider_id' => $plan->provider_id ?? null,
                    'subscription_start_date' => $renewalStartDate,
                    'subscription_end_date' => $renewalEndDate,
                    'domain' => (string) ($order->domain_name ?? ''),
                    'customer_limit' => (int) ($plan->customer_limit ?? 1),
                    'plan_id' => $selectedPlanId,
                    'plan_name' => $planName,
                    'licenses' => $responseLicenses,
                    'unit_price' => $responseUnitPrice,
                    'subtotal' => $subtotal,
                    'discount_amount' => $discount,
                    'gst_amount' => $gstAmount,
                    'total_amount' => $grandTotal,
                    'coupen' => $coupon,
                    'requires_request' => $renewFlags['requires_request'],
                    'change_via' => $renewFlags['change_via'],
                    // --- CREDIT KEYS PER PLAN ---
                    'credit_limit' => $creditLimit,
                    'credit_used' => $creditUsedTotal,
                    'remaining_credit_limit' => $remainingLimit,
                    'credit_limit_reached' => $creditLimitReached,
                    'can_purchase' => $canPurchase,
                    'purchase_block_message' => $purchaseBlockMessage,
                    'credit_applicable' => true,
                    'credit_zero_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
                    'is_credit_applicable' => true,
                    'credit_blocked' => $creditLockedByProcessing,
                    'credit_block_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
                    'processing_orders_amount' => round($processingOrdersAmount, 2),
                    'processing_orders_count' => $processingOrdersCount,
                    'credit_locked_by_processing_orders' => $creditLockedByProcessing,
                    'credit_lock_message' => $creditLockedMessage,
                    'available_credit_for_purchase' => round($availableCreditForPurchase, 2),
                ]],
                'renew_plan' => [
                    'main_cart_id' => (int) $cart->id,
                    'continue_same_subscription' => true,
                    'renew_from' => $renewFromDate,
                    'duration' => (string) ($order->duration ?? '12 month'),
                    'price_per_year_all' => $subtotal,
                ],
                'renewal_summary' => [
                    'total_licenses' => $responseLicenses,
                    'subtotal' => $subtotal,
                    'discount_amount' => $discount,
                    'gst_percentage' => $gstPercent,
                    'gst_amount' => $gstAmount,
                    'total_amount' => $grandTotal,
                    'subscription_start_date' => $renewalStartDate,
                    'subscription_end_date' => $renewalEndDate,
                    'renew_from' => $renewFromDate,
                ],
                'wallet_info' => [
                    'wallet_balance' => $walletBalance ?? $availableCreditForPurchase,
                    'available_balance' => $availableCreditForPurchase,
                    'credit_limit' => $creditLimit,
                    'credit_used' => $creditUsedTotal,
                    'remaining_credit_limit' => $remainingLimit,
                    'credit_limit_reached' => $creditLimitReached,
                    'can_purchase' => $canPurchase,
                    'purchase_block_message' => $purchaseBlockMessage,
                    'credit_applicable' => true,
                    'credit_zero_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
                    'is_credit_applicable' => true,
                    'credit_blocked' => $creditLockedByProcessing,
                    'credit_block_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
                    'processing_orders_amount' => round($processingOrdersAmount, 2),
                    'processing_orders_count' => $processingOrdersCount,
                    'credit_locked_by_processing_orders' => $creditLockedByProcessing,
                    'credit_lock_message' => $creditLockedMessage,
                    'available_credit_for_purchase' => round($availableCreditForPurchase, 2),
                    'is_sufficient_balance' => $canPurchase,
                    'required_amount' => $canPurchase ? 0.0 : round(max(0, $grandTotal - $availableCreditForPurchase), 2),
                    'message' => $purchaseBlockMessage,
                ],
                'order_status' => (string) ($order->status ?? 'pending'),
                'po' => $sourcePo,
                'po_link' => $sourcePo['po_link'] ?? null,
                'po_mode' => $sourcePo['po_mode'] ?? 'generated',
                'po_number' => $sourcePo['po_number'] ?? '',
                'final_po_link' => $sourcePo['final_po_link'] ?? null,
                'is_uploaded_po' => (bool) ($sourcePo['is_uploaded'] ?? false),
            ],
            // --- TOP LEVEL CREDIT KEYS ---
            'credit_limit' => $creditLimit,
            'credit_used' => $creditUsedTotal,
            'remaining_credit_limit' => $remainingLimit,
            'credit_limit_reached' => $creditLimitReached,
            'can_purchase' => $canPurchase,
            'purchase_block_message' => $purchaseBlockMessage,
            'credit_applicable' => true,
            'credit_zero_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
            'is_credit_applicable' => true,
            'credit_blocked' => $creditLockedByProcessing,
            'credit_block_reason' => $creditLockedByProcessing ? $creditLockedMessage : null,
            'processing_orders_amount' => round($processingOrdersAmount, 2),
            'processing_orders_count' => $processingOrdersCount,
            'credit_locked_by_processing_orders' => $creditLockedByProcessing,
            'credit_lock_message' => $creditLockedMessage,
            'available_credit_for_purchase' => round($availableCreditForPurchase, 2),
        ]);
    }

    /**
     * Credit-limit fields for cart API responses (limit, used, remaining).
     *
     * @return array<string, mixed>
     */
    private function partnerB2bCreditSummary(int $partnerId, float $orderAmount = 0): array
    {
        $info = $this->partnerB2bWalletInfo($partnerId, $orderAmount);

        return [
            'credit_limit' => $info['credit_limit'],
            'credit_used' => $info['credit_used'],
            'remaining_credit_limit' => $info['remaining_credit_limit'],
            'available_balance' => $info['available_balance'],
            'wallet_balance' => $info['wallet_balance'],
            'credit_limit_reached' => $info['credit_limit_reached'],
            'can_purchase' => $info['can_purchase'],
            'purchase_block_message' => $info['purchase_block_message'],
        ];
    }

    /**
     * B2B credit-allocation context for partner API responses.
     * wallet_balance is aliased to available allocation (remaining) for app compatibility â€”
     * there is no separate prepaid wallet.
     *
     * @return array<string, mixed>
     */
    private function partnerB2bWalletInfo(int $partnerId, float $orderAmount, ?int $excludeOrderId = null): array
    {
        $partner = $partnerId > 0 ? Partner::query()->whereKey($partnerId)->first() : null;
        $creditLimit = round((float) ($partner->credit_limit ?? 0), 2);
        $creditUsed = round(PartnerCreditService::summarizeUsedCredit($partnerId, $excludeOrderId), 2);
        $remainingLimit = round(PartnerCreditService::remainingPurchaseAllowance($partnerId), 2);
        // Same number as remaining â€” one allocation, not a separate wallet pot.
        $walletBalance = $remainingLimit;
        $creditLimitReached = PartnerCreditService::isCreditLimitFullyUsed($partnerId);
        $creditCheck = PartnerCreditService::validateB2bPurchaseAmount($partnerId, $orderAmount, false, $excludeOrderId);
        $canPurchase = !$creditLimitReached
            && ($orderAmount <= 0.005 || !empty($creditCheck['ok']));

        $message = null;
        if ($creditLimitReached) {
            $message = PartnerCreditService::CREDIT_LIMIT_REACHED_MESSAGE;
        } elseif (empty($creditCheck['ok']) && $orderAmount > 0.005) {
            $message = (string) ($creditCheck['message'] ?? PartnerCreditService::CREDIT_LIMIT_REACHED_MESSAGE);
        } elseif ($canPurchase) {
            $message = 'Sufficient credit allocation available to complete this purchase';
        } else {
            $message = 'Insufficient credit allocation to complete this purchase';
        }

        return [
            'wallet_balance' => $walletBalance,
            'available_balance' => $remainingLimit,
            'credit_limit' => $creditLimit,
            'credit_used' => $creditUsed,
            'remaining_credit_limit' => $remainingLimit,
            'credit_limit_reached' => $creditLimitReached,
            'can_purchase' => $canPurchase,
            'purchase_block_message' => $message,
            'is_sufficient_balance' => $canPurchase,
            'required_amount' => $canPurchase
                ? 0.0
                : round(max(0, $orderAmount - $remainingLimit), 2),
            'message' => $message,
        ];
    }

    /**
     * Normalize upgrade cart request keys (mobile may send new_plan_id / planId).
     */
    private function resolveSelectedPartialUpgradeLicenses(Request $request, ?Cart $cart = null, int $totalCurrentLicenses = 0, int $fallback = 1): int
    {
        $selected = (int) (
            $request->input('licenses')
            ?? $request->input('license_count')
            ?? 0
        );

        if ($selected <= 0 && $cart && $cart->items && $cart->items->isNotEmpty()) {
            $selected = (int) ($cart->items->first()->licenses ?? 0);
        }

        if ($selected <= 0) {
            $selected = $fallback;
        }

        $selected = max(1, $selected);

        if ($totalCurrentLicenses > 0 && $selected >= $totalCurrentLicenses) {
            $selected = max(1, $totalCurrentLicenses - 1);
        }

        return $selected;
    }

    private function normalizeUpgradeCartRequest(Request $request): void
    {
        foreach (['main_cart_id', 'cart_id'] as $key) {
            $value = $request->input($key);
            if ($value === '' || $value === '0' || $value === 0) {
                $request->merge([$key => null]);
            }
        }

        $upgradeMode = strtolower(trim((string) $request->input('upgrade_mode', '')));
        $isPartialUpgrade = filter_var(
            $request->input('is_partial_upgrade', $request->input('partial_upgrade', false)),
            FILTER_VALIDATE_BOOLEAN
        ) || strtolower(trim((string) $request->input('order_category', ''))) === 'partial_upgrade';
        if ($upgradeMode === '' && $isPartialUpgrade) {
            $upgradeMode = 'partial';
        }
        if ($upgradeMode === 'partial') {
            $request->attributes->set('_upgrade_mode', 'partial');
        }

        $partnerId = (int) ($request->input('partner_id') ?? $request->input('data.partner_id') ?? 0);
        $customerId = (int) ($request->input('customer_id') ?? $request->input('data.customer_id') ?? 0);
        $orderId = (int) ($request->input('order_id') ?? $request->input('data.order_id') ?? 0);
        $orderSubId = (int) ($request->input('order_sub_id') ?? $request->input('order_item_id') ?? $request->input('data.order_sub_id') ?? 0);
        $fromPlanId = (int) ($request->input('from_plan_id') ?? $request->input('current_plan_id') ?? $request->input('data.from_plan_id') ?? 0);

        // --- FIX: For partial upgrades, DO NOT auto-set plan_id from source ---
        // Only set plan_id if it was explicitly provided as target_plan_id or new_plan_id
        $planId = $this->resolveUpgradePlanIdFromRequest($request);

        // If plan_id is provided, keep it as is (it's the TARGET plan)
        // If no plan_id is provided, don't set it from source
        if ($planId > 0) {
            $request->merge(['plan_id' => $planId]);
        }
        // For partial upgrades, we keep from_plan_id as the source
        if ($fromPlanId > 0) {
            $request->merge(['from_plan_id' => $fromPlanId, 'current_plan_id' => $fromPlanId]);
        }
    }
    private function resolveUpgradePlanIdFromRequest(Request $request): int
    {
        $bags = [
            $request->all(),
            $request->query(),
            is_array($request->input('data')) ? $request->input('data') : [],
        ];
        $keys = [
            'new_plan_id',
            'to_plan_id',
            'target_plan_id',
            'upgrade_plan_id',
            'selected_plan_id',
            'newPlanId',
            'toPlanId',
            'targetPlanId',
            'upgradePlanId',
            'selectedPlanId',
            'plan_id',
            'planId',
        ];
        foreach ($bags as $bag) {
            if (!is_array($bag)) {
                continue;
            }
            foreach ($keys as $key) {
                $value = $bag[$key] ?? null;
                if (is_array($value)) {
                    $value = $value['id'] ?? $value['plan_id'] ?? $value[0] ?? null;
                }
                if ($value !== null && $value !== '' && (int) $value > 0) {
                    return (int) $value;
                }
            }
            $firstPlan = $bag['plans'][0] ?? $bag['plan'] ?? null;
            if (is_array($firstPlan)) {
                $nested = (int) ($firstPlan['plan_id'] ?? $firstPlan['new_plan_id'] ?? $firstPlan['id'] ?? 0);
                if ($nested > 0) {
                    return $nested;
                }
            }
        }

        return 0;
    }

    /**
     * Reuse the target plan from an existing upgrade/partial cart when FE omits plan_id.
     */
    private function resolveUpgradePlanIdFromActiveCart(Request $request): int
    {
        $partnerId = (int) ($request->input('partner_id') ?? $request->input('data.partner_id') ?? 0);
        if ($partnerId <= 0) {
            return 0;
        }

        $customerId = (int) ($request->input('customer_id') ?? $request->input('data.customer_id') ?? 0);
        $orderId = (int) ($request->input('order_id') ?? $request->input('data.order_id') ?? 0);
        $orderSubId = (int) ($request->input('order_sub_id') ?? $request->input('order_item_id') ?? $request->input('data.order_sub_id') ?? 0);
        $fromPlanId = (int) ($request->input('from_plan_id') ?? $request->input('current_plan_id') ?? $request->input('data.from_plan_id') ?? 0);

        $sourcePlanId = $fromPlanId;
        if ($sourcePlanId <= 0 && ($orderId > 0 || $customerId > 0 || $orderSubId > 0)) {
            [$sourceOrder, $sourceItem] = array_slice(
                $this->resolveUpgradeSourceSubscription($partnerId, $customerId ?: null, $orderId ?: null, $orderSubId ?: null),
                0,
                2
            );
            $sourcePlanId = (int) ($sourceItem->plan_id ?? $sourceOrder->plan_id ?? 0);
        }

        $cartId = (int) (
            $request->input('main_cart_id')
            ?? $request->input('cart_id')
            ?? $request->input('data.main_cart_id')
            ?? $request->input('data.cart_id')
            ?? 0
        );
        if ($cartId > 0) {
            $fromCart = (int) (
                Cart::query()
                ->whereKey($cartId)
                ->where('partner_id', $partnerId)
                ->whereIn('type', [Cart::TYPE_UPGRADE, 'upgrade'])
                ->value('id') ?? 0
            );
            if ($fromCart > 0) {
                $planId = (int) (\App\Models\CartItem::query()
                    ->where('cart_id', $fromCart)
                    ->when($sourcePlanId > 0, function ($q) use ($sourcePlanId) {
                        $q->where('plan_id', '!=', $sourcePlanId);
                    })
                    ->orderByDesc('id')
                    ->value('plan_id') ?? 0);
                if ($planId > 0 && $planId !== $sourcePlanId) {
                    return $planId;
                }
            }
        }

        $query = Cart::query()
            ->where('partner_id', $partnerId)
            ->whereIn('type', [Cart::TYPE_UPGRADE, 'upgrade'])
            ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) = 'active'")
            ->orderByDesc('id');
        if ($customerId > 0) {
            $query->where('customer_id', $customerId);
        }
        if ($orderId > 0 && Schema::connection('pgsql_billing')->hasColumn('carts', 'order_id')) {
            $query->where(function ($q) use ($orderId) {
                $q->where('order_id', $orderId)->orWhereNull('order_id')->orWhere('order_id', 0);
            });
        }
        $cart = $query->first();
        if (!$cart) {
            return 0;
        }

        return (int) ($cart->items()->orderBy('id')->value('plan_id') ?? 0);
    }

    /**
     * Clear order_id from the request when the value is a cart ID (not a real order ID).
     * The frontend sometimes sends cart_id as order_id for upgrade/partial-upgrade flows.
     */
    private function sanitizeOrderIdInRequest(Request $request): void
    {
        $rawOrderId = (int) ($request->input('order_id') ?? 0);
        if ($rawOrderId > 0 && !Order::query()->whereKey($rawOrderId)->exists()) {
            $request->merge(['order_id' => null]);
        }
    }

    /**
     * Create upgrade cart via upgradeAddToCart when missing (no separate /upgrade-cart route).
     */
    private function resolveUpgradeMainCartId(Request $request, int $partnerId): int
    {
        $mainCartId = (int) (
            $request->input('main_cart_id')
            ?? $request->input('cart_id')
            ?? 0
        );
        $orderId = (int) ($request->input('order_id') ?? 0);
        $customerId = (int) ($request->input('customer_id') ?? 0);
        $isUpgrade = !array_key_exists('is_upgrade', $request->all())
            || filter_var($request->input('is_upgrade'), FILTER_VALIDATE_BOOLEAN);
        $cartType = $isUpgrade ? Cart::TYPE_UPGRADE : Cart::TYPE_DOWNGRADE;

        $findActiveCart = function () use ($partnerId, $cartType, $orderId, $customerId) {
            $query = Cart::query()
                ->ofType($cartType)
                ->where('partner_id', $partnerId)
                ->whereNotIn('status', [Cart::STATUS_CONVERTED, 'inactive'])
                ->orderByDesc('id');

            if ($customerId > 0) {
                $query->where('customer_id', $customerId);
            }

            if ($orderId > 0 && Schema::connection('pgsql_billing')->hasColumn('carts', 'order_id')) {
                $query->where(function ($q) use ($orderId) {
                    $q->where('order_id', $orderId)
                        ->orWhereNull('order_id')
                        ->orWhere('order_id', 0);
                });
            }

            return $query->first();
        };

        if ($mainCartId > 0) {
            $cart = Cart::query()
                ->whereKey($mainCartId)
                ->where('partner_id', $partnerId)
                ->first();

            if ($cart && !in_array((string) ($cart->status ?? ''), [Cart::STATUS_CONVERTED, 'inactive'], true)) {
                if ($cart->status === 'pending_approval') {
                    $approved = PurchaseRequest::query()
                        ->where('cart_id', $cart->id)
                        ->where('partner_id', $partnerId)
                        ->where('status', PurchaseRequest::STATUS_APPROVED)
                        ->exists();
                    if ($approved) {
                        $cart->status = Cart::STATUS_ACTIVE;
                        $cart->save();
                    }
                }

                return (int) $cart->id;
            }

            $approvedRequest = PurchaseRequest::query()
                ->where('cart_id', $mainCartId)
                ->where('partner_id', $partnerId)
                ->where('status', PurchaseRequest::STATUS_APPROVED)
                ->orderByDesc('id')
                ->first();

            if ($approvedRequest) {
                $replacement = $findActiveCart();
                if ($replacement) {
                    return (int) $replacement->id;
                }
            }

            return 0;
        }

        $peekCart = $findActiveCart();

        return $peekCart ? (int) $peekCart->id : 0;
    }

    private function ensureUpgradeCartFromRequest(Request $request): ?\Illuminate\Http\JsonResponse
    {
        if ($this->resolveUpgradePlanIdFromRequest($request) <= 0) {
            return null;
        }

        $request->attributes->set('_bypass_request_block', true);
        $addResponse = $this->upgradeAddToCart($request);
        $request->attributes->remove('_bypass_request_block');
        $payload = json_decode($addResponse->getContent(), true);
        if (!($payload['success'] ?? false)) {
            return $addResponse;
        }

        $mainCartId = (int) (
            $payload['data']['main_cart_id']
            ?? $payload['data']['plans'][0]['main_cart_id']
            ?? 0
        );
        if ($mainCartId > 0) {
            $request->merge(['main_cart_id' => $mainCartId]);
        }

        return null;
    }

    /**
     * Create downgrade cart via downgradeCart when missing.
     */
    private function ensureDowngradeCartFromRequest(Request $request): ?\Illuminate\Http\JsonResponse
    {
        if ($this->resolveUpgradePlanIdFromRequest($request) <= 0) {
            return null;
        }

        $request->attributes->set('_bypass_request_block', true);
        $addResponse = $this->downgradeCart($request);
        $request->attributes->remove('_bypass_request_block');
        $payload = json_decode($addResponse->getContent(), true);
        if (!($payload['success'] ?? false)) {
            return $addResponse;
        }

        $mainCartId = (int) (
            $payload['data']['main_cart_id']
            ?? $payload['data']['cart_id']
            ?? $payload['data']['plans'][0]['main_cart_id']
            ?? $payload['main_cart_id']
            ?? 0
        );
        if ($mainCartId > 0) {
            $request->merge(['main_cart_id' => $mainCartId]);
        }

        // Request-style success without a cart must not stop details; create failed.
        if ($mainCartId <= 0 && !empty($payload['data']['requires_request'])) {
            return null;
        }

        return null;
    }

    /**
     * Resolve the active subscription order/item for upgrade proration.
     * Prefer explicit order_sub_id / from_plan_id so multi-plan orders don't fall back to the 1st line.
     *
     * @return array{0: ?Order, 1: ?OrderItem, 2: int}
     */
    private function resolveUpgradeSourceSubscription(
        int $partnerId,
        ?int $customerId = null,
        ?int $orderIdHint = null,
        ?int $orderSubId = null,
        ?int $fromPlanId = null
    ): array {
        $sourceItem = ($orderSubId ?? 0) > 0
            ? OrderItem::query()
            ->whereKey((int) $orderSubId)
            ->where(function ($q) {
                $q->whereNull('status')->orWhere('status', '!=', 'delete');
            })
            ->first()
            : null;
        $orderId = 0;

        // Explicit line item wins: use its order_id
        if ($sourceItem) {
            $orderId = (int) ($sourceItem->order_id ?? 0);
        }

        if ($orderId <= 0 && $customerId) {
            try {
                $orderId = (int) app(B2bSubscriptionUpgradeService::class)->resolveSubscriptionId(
                    $partnerId,
                    ($orderIdHint ?? 0) > 0 ? (int) $orderIdHint : null,
                    $customerId,
                    null
                );
            } catch (\Throwable $e) {
                $orderId = 0;
            }
        }

        if ($orderId <= 0 && ($orderIdHint ?? 0) > 0) {
            $orderId = (int) $orderIdHint;
        }

        $sourceOrder = $orderId > 0
            ? Order::query()->whereKey($orderId)->where('partner_id', $partnerId)->first()
            : null;

        if (!$sourceItem && $sourceOrder) {
            $itemQuery = OrderItem::query()
                ->where('order_id', $orderId)
                ->where(function ($q) {
                    $q->whereNull('status')->orWhere('status', '!=', 'delete');
                });

            if (($fromPlanId ?? 0) > 0) {
                $itemQuery->where('plan_id', (int) $fromPlanId);
            }

            $sourceItem = $itemQuery->orderBy('id')->first();

            // --- FIX: If we still don't have a source item, try to get it from the order's plan_id ---
            if (!$sourceItem && $sourceOrder && (int) $sourceOrder->plan_id > 0) {
                $sourceItem = OrderItem::query()
                    ->where('order_id', $orderId)
                    ->where('plan_id', (int) $sourceOrder->plan_id)
                    ->where(function ($q) {
                        $q->whereNull('status')->orWhere('status', '!=', 'delete');
                    })
                    ->orderBy('id')
                    ->first();
            }
        }

        // --- FIX: If sourceItem is null, create a synthetic one from the order ---
        if (!$sourceItem && $sourceOrder) {
            // Create a fake order item with the order's plan_id and quantity
            $sourceItem = new OrderItem();
            $sourceItem->id = null;
            $sourceItem->order_id = $sourceOrder->id;
            $sourceItem->plan_id = $sourceOrder->plan_id;
            $sourceItem->quantity = $sourceOrder->quantity ?? 1;
            $sourceItem->unit_price = $sourceOrder->price ?? 0;
            $sourceItem->total_amount = $sourceOrder->total_amount ?? 0;
            $sourceItem->subscription_start_date = $sourceOrder->subscription_start_date;
            $sourceItem->subscription_end_date = $sourceOrder->subscription_end_date;
        }

        Log::info('resolveUpgradeSourceSubscription result', [
            'order_id' => $orderId,
            'source_item_plan_id' => $sourceItem->plan_id ?? null,
            'source_item_quantity' => $sourceItem->quantity ?? null,
            'source_order_plan_id' => $sourceOrder->plan_id ?? null,
            'source_order_quantity' => $sourceOrder->quantity ?? null,
            'customer_id' => $customerId,
            'from_plan_id' => $fromPlanId,
            'order_sub_id' => $orderSubId,
        ]);

        return [$sourceOrder, $sourceItem, $orderId];
    }
    /**
     * Read order_sub_id / from_plan_id from upgrade/downgrade requests (multiple aliases).
     * If request omits them (common on update-cart), recover from cart / cache.
     *
     * @return array{0: int, 1: int} [order_sub_id, from_plan_id]
     */
    /**
     * Read order_sub_id / from_plan_id from upgrade/downgrade requests (multiple aliases).
     * If request omits them (common on update-cart), recover from cart / cache.
     *
     * @return array{0: int, 1: int} [order_sub_id, from_plan_id]
     */
    private function resolveUpgradeSourceLineHints(Request $request, array $validated = [], ?Cart $cart = null): array
    {
        $orderSubId = 0;
        foreach (['order_sub_id', 'order_item_id', 'source_order_item_id', 'orderSubId'] as $key) {
            $value = $validated[$key] ?? $request->input($key, $request->query($key));
            if ($value !== null && $value !== '' && (int) $value > 0) {
                $orderSubId = (int) $value;
                break;
            }
        }

        $fromPlanId = 0;
        // --- FIX: Check from_plan_id first, then current_plan_id ---
        foreach (['from_plan_id', 'current_plan_id', 'source_plan_id', 'old_plan_id'] as $key) {
            $value = $validated[$key] ?? $request->input($key, $request->query($key));
            if ($value !== null && $value !== '' && (int) $value > 0) {
                $fromPlanId = (int) $value;
                break;
            }
        }

        // If fromPlanId is still 0, try to get it from the order
        if ($fromPlanId <= 0 && !empty($validated['order_id'])) {
            $orderId = (int) $validated['order_id'];
            $order = Order::query()->find($orderId);
            if ($order) {
                $fromPlanId = (int) ($order->plan_id ?? 0);
                // If order plan_id is 0, try to get from order_items
                if ($fromPlanId <= 0) {
                    $item = OrderItem::query()
                        ->where('order_id', $orderId)
                        ->where(function ($q) {
                            $q->whereNull('status')->orWhere('status', '!=', 'delete');
                        })
                        ->orderBy('id')
                        ->first();
                    if ($item) {
                        $fromPlanId = (int) $item->plan_id;
                    }
                }
            }
        }

        // If still no fromPlanId, try to get it from order_sub_id
        if ($fromPlanId <= 0 && !empty($validated['order_sub_id'])) {
            $orderItem = OrderItem::query()->find((int) $validated['order_sub_id']);
            if ($orderItem && (int) $orderItem->plan_id > 0) {
                $fromPlanId = (int) $orderItem->plan_id;
            }
        }

        // If still no fromPlanId and we have a cart, try to recall it
        if ($cart && $fromPlanId <= 0) {
            $fromPlanId = $this->recallUpgradeSourcePlanId($cart);
        }

        // --- FIX: For partial upgrades, don't override from_plan_id if already set ---
        $upgradeMode = $request->attributes->get('_upgrade_mode')
            ?? $request->input('upgrade_mode', '');
        if ($upgradeMode === 'partial' && $fromPlanId <= 0) {
            // Try to get from the request directly
            $fromPlanId = (int) ($validated['from_plan_id'] ?? $request->input('from_plan_id', 0));
        }

        // Store in request for later use
        if ($fromPlanId > 0) {
            $request->merge([
                'from_plan_id' => $fromPlanId,
                'current_plan_id' => $fromPlanId,
            ]);
        }

        return [$orderSubId, $fromPlanId];
    }
    private function upgradeCartSourceCacheKey(int $cartId): string
    {
        return 'upgrade_cart_source_sub:' . $cartId;
    }

    private function upgradeCartSourcePlanCacheKey(int $cartId): string
    {
        return 'upgrade_cart_source_plan:' . $cartId;
    }

    /**
     * Parent subscription domain only — never the leftover upgrade cart CSV.
     */
    private function subscriptionDomainNameForCart($sourceOrder = null, int $subscriptionOrderId = 0): string
    {
        $order = $sourceOrder;
        if (!$order && $subscriptionOrderId > 0) {
            $order = Order::query()->whereKey($subscriptionOrderId)->first();
        }
        if (!$order) {
            return '';
        }

        $domain = OrderDomainHelper::normalizeStored($order->domain_name ?? '');
        if ($domain !== '') {
            return $domain;
        }

        $parentId = (int) ($order->parent_order_id ?? 0);
        if ($parentId > 0) {
            $domain = OrderDomainHelper::normalizeStored(
                Order::query()->whereKey($parentId)->value('domain_name')
            );
        }

        return $domain;
    }

    private function applySubscriptionDomainToCart(?Cart $cart, $sourceOrder = null, int $subscriptionOrderId = 0): string
    {
        if (!$cart) {
            return '';
        }

        $orderId = $subscriptionOrderId > 0 ? $subscriptionOrderId : 0;
        if ($orderId <= 0 && $sourceOrder) {
            $orderId = (int) ($sourceOrder->id ?? 0);
        }
        if ($orderId <= 0) {
            $orderId = (int) ($cart->order_id ?? 0);
        }
        $domain = $this->subscriptionDomainNameForCart($sourceOrder, $orderId);
        if ($domain === '') {
            return OrderDomainHelper::normalizeStored($cart->domain_name ?? '');
        }

        if (
            Schema::connection('pgsql_billing')->hasColumn('carts', 'domain_name')
            && OrderDomainHelper::normalizeStored($cart->domain_name ?? '') !== $domain
        ) {
            $cart->domain_name = $domain;
            $cart->save();
        }

        return $domain;
    }

    /**
     * Persist which subscription line the upgrade/downgrade cart is for.
     * update-cart often omits order_sub_id even when cart-details sends it.
     */
    private function rememberUpgradeSourceLine(?Cart $cart, ?OrderItem $sourceItem): void
    {
        if (!$cart || !$sourceItem) {
            return;
        }

        $orderSubId = (int) ($sourceItem->id ?? 0);
        $fromPlanId = (int) ($sourceItem->plan_id ?? 0);
        if ($orderSubId <= 0) {
            return;
        }

        $cartId = (int) $cart->id;
        Cache::put($this->upgradeCartSourceCacheKey($cartId), $orderSubId, now()->addDays(2));
        if ($fromPlanId > 0) {
            Cache::put($this->upgradeCartSourcePlanCacheKey($cartId), $fromPlanId, now()->addDays(2));
        }

        $dirty = false;
        if (Schema::connection('pgsql_billing')->hasColumn('carts', 'order_sub_id')) {
            $cart->order_sub_id = $orderSubId;
            $dirty = true;
        }
        if (Schema::connection('pgsql_billing')->hasColumn('carts', 'item_type')) {
            $mode = '';
            if (request()->attributes->get('_upgrade_mode') === 'partial') {
                $mode = ':mode:partial';
            } elseif (request()->attributes->get('_upgrade_mode') === 'license_add') {
                $mode = ':mode:license_add';
            } elseif ($fromPlanId > 0) {
                $cartPlanId = (int) ($cart->items()->value('plan_id') ?? 0);
                if ($cartPlanId > 0 && $cartPlanId === $fromPlanId) {
                    $mode = ':mode:license_add';
                }
            }
            $cart->item_type = 'order_sub:' . $orderSubId
                . ($fromPlanId > 0 ? (':plan:' . $fromPlanId) : '')
                . $mode;
            $dirty = true;
        }
        if ($dirty) {
            $cart->save();
        }
    }

    private function recallUpgradeSourceSubId(Cart $cart): int
    {
        $cartId = (int) $cart->id;

        if (Schema::connection('pgsql_billing')->hasColumn('carts', 'order_sub_id')) {
            $stored = (int) ($cart->order_sub_id ?? 0);
            if ($stored > 0) {
                return $stored;
            }
        }

        $itemType = trim((string) ($cart->item_type ?? ''));
        if (preg_match('/^order_sub:(\d+)/', $itemType, $m)) {
            return (int) $m[1];
        }

        return (int) Cache::get($this->upgradeCartSourceCacheKey($cartId), 0);
    }

    private function recallUpgradeSourcePlanId(Cart $cart): int
    {
        $cartId = (int) $cart->id;

        $itemType = trim((string) ($cart->item_type ?? ''));
        if (preg_match('/:plan:(\d+)/', $itemType, $m)) {
            return (int) $m[1];
        }

        return (int) Cache::get($this->upgradeCartSourcePlanCacheKey($cartId), 0);
    }



    /**
     * @return array{start: ?string, end: ?string}
     */
    private function formatUpgradeSubscriptionDates(
        ?Order $sourceOrder,
        ?OrderItem $sourceItem = null,
        $cartItem = null
    ): array {
        $start = $sourceOrder?->subscription_start_date
            ?? $sourceItem?->subscription_start_date
            ?? $cartItem?->subscription_start_date
            ?? null;

        $planId = (int) ($sourceItem->plan_id ?? $sourceOrder->plan_id ?? $cartItem->plan_id ?? 0);
        $plan = $planId > 0 ? Plan::query()->find($planId) : null;

        $end = null;
        if ($plan && !empty($start)) {
            try {
                $startCarbon = Carbon::parse((string) $start)->startOfDay();
                $end = app(PartnerCartService::class)
                    ->computeSubscriptionEnd($startCarbon, $plan)
                    ->format('Y-m-d');
            } catch (\Throwable $e) {
                $end = null;
            }
        }
        if ($end === null) {
            $end = $sourceOrder?->subscription_end_date
                ?? $sourceItem?->subscription_end_date
                ?? $cartItem?->subscription_end_date
                ?? null;
        }

        return [
            'start' => !empty($start) ? date('d-m-Y', strtotime((string) $start)) : null,
            'end' => !empty($end) ? date('d-m-Y', strtotime((string) $end)) : null,
        ];
    }

    /**
     * @param  list<int>  $parentOrderIds
     * @return array{
     *   child_change_orders_by_parent: \Illuminate\Support\Collection,
     *   child_order_items: \Illuminate\Support\Collection,
     *   new_plans_by_id: \Illuminate\Support\Collection
     * }
     */
    private function buildPlanChangeContextForOrders(array $parentOrderIds): array
    {
        $parentOrderIds = array_values(array_unique(array_filter(array_map('intval', $parentOrderIds))));
        if ($parentOrderIds === []) {
            return [
                'child_change_orders_by_parent' => collect(),
                'child_order_items' => collect(),
                'new_plans_by_id' => collect(),
            ];
        }

        $childChangeOrders = Order::query()
            ->whereIn('parent_order_id', $parentOrderIds)
            ->where(function ($q) {
                $q->whereIn('order_category', [
                    'upgrade',
                    'upgraded',
                    'partial_upgrade',
                    'downgrade',
                    'downgraded',
                    'renewal',
                    'renew',
                    'renewed',
                ])
                    ->orWhereRaw("UPPER(TRIM(COALESCE(order_no, ''))) LIKE 'RN%'")
                    ->orWhereRaw("UPPER(TRIM(COALESCE(order_no, ''))) LIKE 'CH%'");
            })
            ->orderByDesc('id')
            ->get();

        // groupBy may stringify keys â€” normalize to int for reliable lookups.
        $childChangeOrdersByParent = $childChangeOrders
            ->groupBy(fn($row) => (int) ($row->parent_order_id ?? 0));

        $childOrderIds = $childChangeOrders->pluck('id')->filter()->map(fn($id) => (int) $id)->all();
        $childOrderItems = $childOrderIds !== []
            ? OrderItem::query()->whereIn('order_id', $childOrderIds)->get()->groupBy('order_id')
            : collect();

        $newPlanIds = $childChangeOrders->pluck('plan_id')->filter()->map(fn($id) => (int) $id)->unique()->all();
        $newPlansById = $newPlanIds !== []
            ? Plan::query()->whereIn('id', $newPlanIds)->get()->keyBy('id')
            : collect();

        return [
            'child_change_orders_by_parent' => $childChangeOrdersByParent,
            'child_order_items' => $childOrderItems,
            'new_plans_by_id' => $newPlansById,
        ];
    }

    /**
     * Resolve leftover seats after child upgrade/downgrade/renewal replacements.
     *
     * @param  \Illuminate\Support\Collection<int, OrderItem>|null  $orderItems
     * @param  array{status?: string, replaced_qty?: int, pending_renewal_qty?: int}|string|null  $replacement
     * @return array{
     *   superseded_status: ?string,
     *   remaining_licenses: int,
     *   pending_renewal_licenses: int,
     *   is_fully_replaced: bool,
     *   live_qty: int,
     *   live_items: \Illuminate\Support\Collection
     * }
     */
    private function resolvePartialReplacementForOrder(Order $order, $orderItems, $replacement): array
    {
        $orderItems = $orderItems ?? collect();
        $supersededStatus = is_array($replacement) ? ($replacement['status'] ?? null) : $replacement;
        $replacedQty = is_array($replacement) ? (int) ($replacement['replaced_qty'] ?? 0) : 0;
        $pendingRenewalQty = is_array($replacement) ? (int) ($replacement['pending_renewal_qty'] ?? 0) : 0;
        $pendingUpgradeQty = is_array($replacement) ? (int) ($replacement['pending_upgrade_qty'] ?? 0) : 0;
        $pendingDowngradeQty = is_array($replacement) ? (int) ($replacement['pending_downgrade_qty'] ?? 0) : 0;

        $totalMovedQty = $replacedQty;

        $liveItems = $orderItems->filter(function ($item) {
            $s = strtolower(trim((string) ($item->status ?? 'active')));
            if ($s === '') {
                $s = 'active';
            }

            return in_array($s, ['active', 'completed', 'paid', 'success'], true);
        });
        $liveQty = (int) $liveItems->sum(fn($row) => max(1, (int) ($row->quantity ?? 1)));
        if ($liveQty <= 0) {
            $liveQty = max(1, (int) ($order->quantity ?? 1));
        }

        $baseQty = max(1, (int) ($order->quantity ?? $liveQty));

        $hasMarkedLines = $orderItems->contains(function ($item) {
            return in_array(strtolower(trim((string) ($item->status ?? ''))), ['upgraded', 'downgraded', 'renewed'], true);
        });

        $remainingAfterReplace = $liveQty;
        if ($hasMarkedLines) {
            $remainingAfterReplace = (int) $liveItems->sum(fn($row) => max(0, (int) ($row->quantity ?? 0)));
            if ($remainingAfterReplace <= 0 && $totalMovedQty > 0) {
                $remainingAfterReplace = $baseQty > $totalMovedQty ? ($baseQty - $totalMovedQty) : 0;
            }
        } elseif ($totalMovedQty > 0) {
            if ($liveQty > $totalMovedQty) {
                $remainingAfterReplace = $liveQty - $totalMovedQty;
            } elseif ($baseQty > $totalMovedQty) {
                $remainingAfterReplace = $baseQty - $totalMovedQty;
            } else {
                $remainingAfterReplace = 0;
            }
        }

        // Only fully superseded when no leftover seats remain.
        if ($supersededStatus && $remainingAfterReplace > 0) {
            $supersededStatus = null;
        }

        return [
            'superseded_status' => $supersededStatus,
            'remaining_licenses' => max(0, $remainingAfterReplace),
            'upgraded_licenses' => $totalMovedQty,
            'pending_renewal_licenses' => max(0, $pendingRenewalQty),
            'pending_upgrade_licenses' => max(0, $pendingUpgradeQty),
            'pending_downgrade_licenses' => max(0, $pendingDowngradeQty),
            'is_fully_replaced' => $supersededStatus !== null && $remainingAfterReplace <= 0,
            'live_qty' => $liveQty,
            'live_items' => $liveItems,
            'original_licenses' => $baseQty,
        ];
    }

    /**
     * Map parent order id → replacement info when a child change/renewal has replaced seats.
     * Covers: direct renewal, completed downgrade/upgrade, and change-orders later marked renewed.
     *
     * @param  array<int, int>  $parentOrderIds
     * @return array<int, array{status: string, replaced_qty: int, pending_renewal_qty: int}>
     */
    private function buildSupersededSubscriptionStatusByParentId(array $parentOrderIds): array
    {
        $parentOrderIds = array_values(array_unique(array_filter(array_map('intval', $parentOrderIds))));
        if ($parentOrderIds === []) {
            return [];
        }

        // Include "processing" — CH orders are set to processing after generate.
        $successfulStatuses = ['completed', 'paid', 'success', 'active', 'renewed', 'upgraded', 'downgraded', 'pending', 'processing'];
        $children = Order::query()
            ->whereIn('parent_order_id', $parentOrderIds)
            ->get(['id', 'parent_order_id', 'order_category', 'status', 'quantity', 'order_no', 'plan_id', 'previous_plan_id']);

        $childIds = $children->pluck('id')->map(fn($id) => (int) $id)->filter()->values()->all();
        $qtyByChildId = [];
        if ($childIds !== []) {
            $qtyByChildId = OrderItem::query()
                ->whereIn('order_id', $childIds)
                ->where(function ($q) {
                    $q->whereNull('status')
                        ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted')");
                })
                ->get(['order_id', 'quantity'])
                ->groupBy('order_id')
                ->map(fn($rows) => (int) $rows->sum(fn($r) => max(1, (int) ($r->quantity ?? 1))))
                ->all();
        }

        $map = [];
        foreach ($children as $child) {
            $parentId = (int) ($child->parent_order_id ?? 0);
            if ($parentId <= 0) {
                continue;
            }

            $category = strtolower(trim((string) ($child->order_category ?? '')));
            $status = strtolower(trim((string) ($child->status ?? '')));
            $orderNo = strtoupper(trim((string) ($child->order_no ?? '')));
            // Draft / unsigned renewals (aadhaar not done) must not show or append on parent.
            if (in_array($status, ['cancelled', 'canceled', 'rejected', 'failed'], true)) {
                continue;
            }
            if ($this->isUnsignedRenewalChild($child)) {
                continue;
            }
            // Renewal / CH change orders claim seats from the parent (even when category is blank).
            $isRenewal = in_array($category, ['renewal', 'renew'], true)
                || str_starts_with($orderNo, 'RN');
            $isDowngrade = in_array($category, ['downgrade', 'downgraded', 'partial_downgrade'], true);
            $isUpgrade = in_array($category, ['upgrade', 'upgraded', 'partial_upgrade', 'partial', 'partial upgrade', 'upgrade service'], true)
                || str_starts_with($orderNo, 'UPG')
                || (str_starts_with($orderNo, 'CH') && !$isRenewal)
                || $this->isPartialUpgradeOrder($child, $category);
            if ($isChChange = (str_starts_with($orderNo, 'CH') && !$isRenewal)) {
                if (!$isUpgrade && !$isDowngrade) {
                    $kind = $this->partnerPlanChangeOrderKind($child);
                    $isDowngrade = $kind === 'downgrade';
                    $isUpgrade = $kind === 'upgrade' || (!$isDowngrade && $isChChange);
                }
            }

            if (
                !in_array($status, $successfulStatuses, true)
                && $category !== 'renewed'
                && !$isRenewal
                && !$isChChange
                && !$isUpgrade
                && !$isDowngrade
            ) {
                continue;
            }
            if ($isRenewal && in_array($status, ['rejected', 'cancelled', 'canceled', 'failed'], true)) {
                continue;
            }

            $resolved = null;
            if ($isRenewal) {
                $resolved = 'Renewed';
            } elseif ($isDowngrade || $status === 'downgraded') {
                $resolved = 'Downgraded';
            } elseif ($isUpgrade || $status === 'upgraded' || $isChChange) {
                $resolved = 'Upgraded';
            } elseif ($category === 'renewed' || $status === 'renewed') {
                $resolved = 'Renewed';
            }

            // Invoice may still be pending while order.status is already "completed".
            $isPendingChange = in_array($status, ['pending', 'processing', 'draft'], true);
            $isPendingRenewal = $isRenewal && $isPendingChange;
            $isPendingUpgrade = !$isRenewal && $isUpgrade && $isPendingChange;
            $isPendingDowngrade = !$isRenewal && $isDowngrade && $isPendingChange;

            // Pending upgrade/downgrade must not mark the parent as fully Upgraded/Downgraded yet.
            if ($isPendingUpgrade || $isPendingDowngrade) {
                $resolved = null;
            }

            $childId = (int) $child->id;
            $childQty = (int) ($qtyByChildId[$childId] ?? 0);
            if ($childQty <= 0) {
                $childQty = max(1, (int) ($child->quantity ?? 1));
            }

            $replacedQty = $isPendingChange ? 0 : $childQty;

            if (!isset($map[$parentId])) {
                $map[$parentId] = [
                    'status' => $resolved,
                    'replaced_qty' => $replacedQty,
                    'pending_renewal_qty' => $isPendingRenewal ? $childQty : 0,
                    'pending_upgrade_qty' => $isPendingUpgrade ? $childQty : 0,
                    'pending_downgrade_qty' => $isPendingDowngrade ? $childQty : 0,
                ];
                continue;
            }

            $map[$parentId]['replaced_qty'] += $replacedQty;
            if ($isPendingRenewal) {
                $map[$parentId]['pending_renewal_qty'] += $childQty;
            }
            if ($isPendingUpgrade) {
                $map[$parentId]['pending_upgrade_qty'] += $childQty;
            }
            if ($isPendingDowngrade) {
                $map[$parentId]['pending_downgrade_qty'] += $childQty;
            }

            // Prefer Downgraded/Upgraded over Renewed when mixed completed children exist.
            $existing = $map[$parentId]['status'];
            if ($resolved !== null) {
                if ($existing === null || ($existing === 'Renewed' && in_array($resolved, ['Downgraded', 'Upgraded'], true))) {
                    $map[$parentId]['status'] = $resolved;
                }
            }
        }

        return $map;
    }

    /**
     * @return array{
     *   status: string,
     *   days_to_expire: int|null,
     *   end_date: Carbon|null,
     *   summary_bucket: string|null
     * }
     */
    private function resolveSubscriptionOrderLevelStatus(
        Order $order,
        Carbon $today,
        $orderItems = null,
        ?string $supersededBy = null,
        bool $treatAsLiveSubscription = false
    ): array {
        $endDate = $order->subscription_end_date
            ? Carbon::parse($order->subscription_end_date)
            : null;
        $daysToExpire = $endDate ? $today->diffInDays($endDate, false) : null;

        $rawStatus = strtolower(trim((string) ($order->status ?? '')));
        $rawCategory = strtolower(trim((string) ($order->order_category ?? '')));

        // Cancelled / rejected must win over "completed + near end date = Expiring".
        if (in_array($rawStatus, ['rejected', 'cancelled', 'canceled', 'failed'], true)) {
            return [
                'status' => 'Cancelled',
                'days_to_expire' => $daysToExpire,
                'end_date' => $endDate,
                'summary_bucket' => null,
            ];
        }

        // Partial renew left seats on this order â€” ignore whole-order "renewed" markers.
        if (!$treatAsLiveSubscription) {
            if ($rawStatus === 'renewed' || $rawCategory === 'renewed') {
                return [
                    'status' => 'Renewed',
                    'days_to_expire' => $daysToExpire,
                    'end_date' => $endDate,
                    'summary_bucket' => null,
                ];
            }
            if ($rawStatus === 'upgraded' || $rawCategory === 'upgraded') {
                return [
                    'status' => 'Upgraded',
                    'days_to_expire' => $daysToExpire,
                    'end_date' => $endDate,
                    'summary_bucket' => null,
                ];
            }
            if ($rawStatus === 'downgraded' || $rawCategory === 'downgraded') {
                return [
                    'status' => 'Downgraded',
                    'days_to_expire' => $daysToExpire,
                    'end_date' => $endDate,
                    'summary_bucket' => null,
                ];
            }

            // Replaced by a child renewal / downgrade / upgrade â€” never show as Active/Expiring.
            if (in_array($supersededBy, ['Renewed', 'Downgraded', 'Upgraded'], true)) {
                return [
                    'status' => $supersededBy,
                    'days_to_expire' => $daysToExpire,
                    'end_date' => $endDate,
                    'summary_bucket' => null,
                ];
            }
        } else {
            // Live leftover seats: treat order as still completed for Active/Expiring math.
            if (in_array($rawStatus, ['renewed', 'upgraded', 'downgraded'], true)) {
                $rawStatus = 'completed';
            }
        }

        // Parent still "completed" but every line was upgraded/downgraded/cancelled â†’ not Expiring.
        if ($orderItems !== null && $orderItems->isNotEmpty()) {
            $liveItems = $orderItems->filter(function ($item) {
                $s = strtolower(trim((string) ($item->status ?? 'active')));
                if ($s === '') {
                    $s = 'active';
                }

                return in_array($s, ['active', 'completed', 'paid', 'success'], true);
            });

            if ($liveItems->isEmpty()) {
                $hasDowngraded = $orderItems->contains(function ($item) {
                    return strtolower(trim((string) ($item->status ?? ''))) === 'downgraded';
                });
                $hasUpgraded = $orderItems->contains(function ($item) {
                    return strtolower(trim((string) ($item->status ?? ''))) === 'upgraded';
                });

                return [
                    'status' => $hasDowngraded ? 'Downgraded' : ($hasUpgraded ? 'Upgraded' : 'Cancelled'),
                    'days_to_expire' => $daysToExpire,
                    'end_date' => $endDate,
                    'summary_bucket' => null,
                ];
            }
        }

        if (in_array($rawStatus, ['completed', 'active', 'paid', 'success'], true)) {
            // New upgrade/downgrade orders become Active once activated (source becomes Upgraded separately).
            $isChangeOrder = in_array($rawCategory, ['upgrade', 'downgrade'], true);

            if ($endDate && $endDate->lt($today)) {
                return [
                    'status' => 'Expired',
                    'days_to_expire' => $daysToExpire,
                    'end_date' => $endDate,
                    'summary_bucket' => $isChangeOrder ? null : 'expired',
                ];
            }
            if ($daysToExpire !== null && $daysToExpire <= 30 && $daysToExpire >= 0) {
                return [
                    'status' => 'Expiring',
                    'days_to_expire' => $daysToExpire,
                    'end_date' => $endDate,
                    'summary_bucket' => $isChangeOrder ? null : 'expiring',
                ];
            }

            return [
                'status' => 'Active',
                'days_to_expire' => $daysToExpire,
                'end_date' => $endDate,
                'summary_bucket' => $isChangeOrder ? null : 'active',
            ];
        }
        if (in_array($rawStatus, ['pending', 'processing', 'draft'], true)) {
            // New upgrade/downgrade/renewal order awaiting activation.
            $changeKind = $this->partnerPlanChangeOrderKind($order);
            if ($changeKind === 'upgrade') {
                return [
                    'status' => 'Upgrade Pending',
                    'days_to_expire' => $daysToExpire,
                    'end_date' => $endDate,
                    'summary_bucket' => 'processing',
                ];
            }
            if ($changeKind === 'downgrade') {
                return [
                    'status' => 'Downgrade Pending',
                    'days_to_expire' => $daysToExpire,
                    'end_date' => $endDate,
                    'summary_bucket' => 'processing',
                ];
            }
            if ($changeKind === 'renewal') {
                // Unsigned draft renewals stay Draft (handled below); pending/processing = Renewal Pending.
                if ($rawStatus !== 'draft') {
                    return [
                        'status' => 'Renewal Pending',
                        'days_to_expire' => $daysToExpire,
                        'end_date' => $endDate,
                        'summary_bucket' => 'processing',
                    ];
                }
            }

            return [
                'status' => $rawStatus === 'draft' ? 'Draft' : ($rawStatus === 'pending' ? 'Pending' : 'Processing'),
                'days_to_expire' => $daysToExpire,
                'end_date' => $endDate,
                'summary_bucket' => $rawStatus === 'draft' ? null : 'processing',
            ];
        }

        return [
            'status' => 'Processing',
            'days_to_expire' => $daysToExpire,
            'end_date' => $endDate,
            'summary_bucket' => 'processing',
        ];
    }

    /**
     * @param  \Illuminate\Support\Collection<int, Order>  $childChangeOrders
     * @param  \Illuminate\Support\Collection  $childOrderItems
     * @param  \Illuminate\Support\Collection  $newPlansById
     * @return array<int, array<string, mixed>>
     */
    private function buildUpgradeStateBySourceSubId(
        int $parentOrderId,
        $childChangeOrders,
        $childOrderItems,
        $newPlansById
    ): array {
        $successfulChildStatuses = ['completed', 'paid', 'success', 'active'];
        $pendingChildStatuses = ['pending', 'processing', 'draft'];
        $upgradeStateBySourceSubId = [];

        foreach ($childChangeOrders as $childOrder) {
            $childId = (int) $childOrder->id;
            $childItem = optional($childOrderItems->get($childId))->first();
            $childMeta = is_array($childItem->meta ?? null) ? $childItem->meta : [];
            $childStatus = strtolower(trim((string) ($childOrder->status ?? '')));
            $changeCategory = strtolower(trim((string) ($childOrder->order_category ?? '')));
            $isRenewal = $this->isRenewalChangeOrder($childOrder);
            if (in_array($childStatus, ['cancelled', 'canceled', 'rejected', 'failed'], true)) {
                continue;
            }
            if ($changeCategory === '' || $changeCategory === 'new') {
                $inferred = $this->partnerPlanChangeOrderKind($childOrder);
                if ($inferred === 'downgrade') {
                    $changeCategory = 'downgrade';
                } elseif ($inferred === 'upgrade') {
                    $changeCategory = 'upgrade';
                } elseif ($inferred === 'renewal') {
                    $changeCategory = 'renewal';
                } else {
                    $changeCategory = 'upgrade';
                }
            }

            // Draft renewals are not submitted yet â€” don't claim parent lines.
            if ($isRenewal && $childStatus === 'draft') {
                continue;
            }

            $candidateSourceIds = array_values(array_unique(array_filter([
                (int) ($childOrder->parent_order_sub_id ?? 0),
                (int) ($childItem->previous_order_sub_id ?? 0),
                (int) ($childMeta['previous_order_sub_id'] ?? 0),
                (int) ($childMeta['order_sub_id'] ?? 0),
            ])));

            $oldPlanId = (int) ($childMeta['old_plan_id'] ?? $childOrder->previous_plan_id ?? 0);
            // Renewals keep the same plan â€” use child plan_id when old_plan_id is missing.
            if ($oldPlanId <= 0 && $isRenewal) {
                $oldPlanId = (int) ($childItem->plan_id ?? $childOrder->plan_id ?? 0);
            }
            if ($oldPlanId > 0 && $candidateSourceIds === []) {
                $activeSamePlanIds = OrderItem::query()
                    ->where('order_id', $parentOrderId)
                    ->where('plan_id', $oldPlanId)
                    ->where(function ($q) {
                        $q->whereNull('status')
                            ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) IN ('', 'active', 'completed', 'paid', 'success')");
                    })
                    ->orderBy('id')
                    ->pluck('id')
                    ->map(fn($id) => (int) $id)
                    ->all();
                if (count($activeSamePlanIds) === 1) {
                    $candidateSourceIds[] = $activeSamePlanIds[0];
                } elseif (count($activeSamePlanIds) > 1) {
                    // Upgrade/downgrade/renewal: claim first unmatched active line of that plan.
                    foreach ($activeSamePlanIds as $sid) {
                        if (!isset($upgradeStateBySourceSubId[$sid])) {
                            $candidateSourceIds[] = $sid;
                            break;
                        }
                    }
                }
            }

            // Last-resort BEFORE mapping: never steal leftover Active sibling after
            // another plan on the same parent was upgraded/downgraded/renewed.
            if ($candidateSourceIds === [] && !$isRenewal) {
                $replacedSiblingIds = OrderItem::query()
                    ->where('order_id', $parentOrderId)
                    ->where(function ($q) use ($oldPlanId) {
                        $q->whereRaw("LOWER(TRIM(COALESCE(status, ''))) IN ('upgraded', 'downgraded', 'renewed')");
                        if ($oldPlanId > 0) {
                            $q->where('plan_id', $oldPlanId);
                        }
                    })
                    ->orderBy('id')
                    ->pluck('id')
                    ->map(fn($id) => (int) $id)
                    ->filter(fn($id) => $id > 0 && !isset($upgradeStateBySourceSubId[$id]))
                    ->values()
                    ->all();
                if ($replacedSiblingIds !== []) {
                    $candidateSourceIds[] = (int) $replacedSiblingIds[0];
                } else {
                    $soleLiveId = $this->soleUnmatchedLiveParentItemId(
                        $parentOrderId,
                        $upgradeStateBySourceSubId
                    );
                    if ($soleLiveId > 0) {
                        $candidateSourceIds[] = $soleLiveId;
                    }
                }
            }

            $mappedPlanChangeStatus = null;
            if (in_array($childStatus, $pendingChildStatuses, true)) {
                if ($isRenewal) {
                    $mappedPlanChangeStatus = 'renewal_pending';
                } else {
                    $mappedPlanChangeStatus = $changeCategory === 'downgrade' ? 'downgrade_pending' : 'upgrade_pending';
                }
            } elseif (in_array($childStatus, $successfulChildStatuses, true)) {
                if ($isRenewal) {
                    $mappedPlanChangeStatus = 'renewed';
                } else {
                    $mappedPlanChangeStatus = $changeCategory === 'downgrade' ? 'downgraded' : 'upgraded';
                }
            }
            if ($mappedPlanChangeStatus === null || $candidateSourceIds === []) {
                continue;
            }

            $newPlanIdForChild = (int) ($childOrder->plan_id ?? 0);
            $mappedAny = false;
            foreach ($candidateSourceIds as $sourceSubId) {
                if ($sourceSubId <= 0 || isset($upgradeStateBySourceSubId[$sourceSubId])) {
                    continue;
                }
                $upgradeStateBySourceSubId[$sourceSubId] = [
                    'plan_change_status' => $mappedPlanChangeStatus,
                    'change_order_id' => $childId,
                    'change_order_no' => (string) ($childOrder->order_no ?? ''),
                    'change_order_status' => $childStatus,
                    'new_plan_id' => $newPlanIdForChild,
                    'new_plan_name' => (string) (optional($newPlansById->get($newPlanIdForChild))->name ?? $childOrder->plan_name ?? ''),
                ];
                $mappedAny = true;
            }

            // Wrong old_plan_id may point at an already-claimed line â€” only claim when
            // exactly one unmatched live line remains (never steal sibling Active plans).
            if (!$mappedAny) {
                // Prefer already-replaced lines over stealing a leftover Active sibling
                // (2 plans -> upgrade 1 -> leftover must stay on parent / renewals).
                $replacedParentIds = OrderItem::query()
                    ->where('order_id', $parentOrderId)
                    ->where(function ($q) use ($oldPlanId) {
                        $q->whereRaw("LOWER(TRIM(COALESCE(status, ''))) IN ('upgraded', 'downgraded', 'renewed')");
                        if ($oldPlanId > 0) {
                            $q->where('plan_id', $oldPlanId);
                        }
                    })
                    ->orderBy('id')
                    ->pluck('id')
                    ->map(fn($id) => (int) $id)
                    ->filter(fn($id) => $id > 0 && !isset($upgradeStateBySourceSubId[$id]))
                    ->values()
                    ->all();

                $fallbackSourceId = 0;
                if ($replacedParentIds !== []) {
                    $fallbackSourceId = (int) $replacedParentIds[0];
                } else {
                    $fallbackSourceId = $this->soleUnmatchedLiveParentItemId(
                        $parentOrderId,
                        $upgradeStateBySourceSubId
                    );
                }

                if ($fallbackSourceId > 0) {
                    $upgradeStateBySourceSubId[$fallbackSourceId] = [
                        'plan_change_status' => $mappedPlanChangeStatus,
                        'change_order_id' => $childId,
                        'change_order_no' => (string) ($childOrder->order_no ?? ''),
                        'change_order_status' => $childStatus,
                        'new_plan_id' => $newPlanIdForChild,
                        'new_plan_name' => (string) (optional($newPlansById->get($newPlanIdForChild))->name ?? $childOrder->plan_name ?? ''),
                    ];
                }
            }
        }

        // Final pass: pair leftover live parent lines 1:1 with leftover CH/RN children
        // (both plans renewed / both downgraded / mixed upgrade+renew, etc.).
        $usedChildIds = collect($upgradeStateBySourceSubId)
            ->pluck('change_order_id')
            ->map(fn($id) => (int) $id)
            ->filter()
            ->unique()
            ->all();

        $unmatchedLiveIds = OrderItem::query()
            ->where('order_id', $parentOrderId)
            ->where(function ($q) {
                $q->whereNull('status')
                    ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) IN ('', 'active', 'completed', 'paid', 'success')");
            })
            ->orderBy('id')
            ->pluck('id')
            ->map(fn($id) => (int) $id)
            ->filter(fn($id) => $id > 0 && !isset($upgradeStateBySourceSubId[$id]))
            ->values()
            ->all();

        foreach ($childChangeOrders as $childOrder) {
            if ($unmatchedLiveIds === []) {
                break;
            }
            $childId = (int) $childOrder->id;
            if ($childId <= 0 || in_array($childId, $usedChildIds, true)) {
                continue;
            }

            $childStatus = strtolower(trim((string) ($childOrder->status ?? '')));
            if (in_array($childStatus, ['cancelled', 'canceled', 'rejected', 'failed'], true)) {
                continue;
            }
            $isRenewal = $this->isRenewalChangeOrder($childOrder);
            if ($isRenewal && $childStatus === 'draft') {
                continue;
            }
            if ($isRenewal && $this->isUnsignedRenewalChild($childOrder)) {
                continue;
            }

            // Already linked to a specific parent line (even if that line is upgraded/renewed) â€”
            // never steal a leftover sibling Active plan on a later pass.
            $childItem = optional($childOrderItems->get($childId))->first()
                ?? optional($childOrderItems->get((string) $childId))->first();
            $childMeta = is_array($childItem->meta ?? null) ? $childItem->meta : [];
            $explicitSourceId = (int) (
                $childOrder->parent_order_sub_id
                ?? $childItem->previous_order_sub_id
                ?? $childMeta['previous_order_sub_id']
                ?? $childMeta['order_sub_id']
                ?? 0
            );
            if ($explicitSourceId > 0) {
                $usedChildIds[] = $childId;
                continue;
            }

            $kind = $this->partnerPlanChangeOrderKind($childOrder);
            if ($kind === null) {
                continue;
            }

            $mappedPlanChangeStatus = null;
            if (in_array($childStatus, $pendingChildStatuses, true)) {
                $mappedPlanChangeStatus = match ($kind) {
                    'downgrade' => 'downgrade_pending',
                    'renewal' => 'renewal_pending',
                    default => 'upgrade_pending',
                };
            } elseif (in_array($childStatus, $successfulChildStatuses, true)) {
                $mappedPlanChangeStatus = match ($kind) {
                    'downgrade' => 'downgraded',
                    'renewal' => 'renewed',
                    default => 'upgraded',
                };
            }
            if ($mappedPlanChangeStatus === null) {
                continue;
            }

            $oldPlanId = (int) ($childMeta['old_plan_id'] ?? $childOrder->previous_plan_id ?? 0);
            if ($oldPlanId <= 0 && $isRenewal) {
                $oldPlanId = (int) ($childItem->plan_id ?? $childOrder->plan_id ?? 0);
            }
            $childPlanId = (int) ($childItem->plan_id ?? $childOrder->plan_id ?? 0);
            $livePlanIds = $unmatchedLiveIds === []
                ? collect()
                : OrderItem::query()->whereIn('id', $unmatchedLiveIds)->pluck('plan_id', 'id');

            $matchAt = null;
            foreach ($unmatchedLiveIds as $idx => $liveId) {
                $livePlanId = (int) ($livePlanIds[$liveId] ?? $livePlanIds[(string) $liveId] ?? 0);
                if ($oldPlanId > 0 && $livePlanId === $oldPlanId) {
                    $matchAt = $idx;
                    break;
                }
                if ($oldPlanId <= 0 && $childPlanId > 0 && $livePlanId === $childPlanId) {
                    $matchAt = $idx;
                    break;
                }
            }
            if ($matchAt === null) {
                continue;
            }

            $sourceSubId = (int) $unmatchedLiveIds[$matchAt];
            unset($unmatchedLiveIds[$matchAt]);
            $unmatchedLiveIds = array_values($unmatchedLiveIds);
            $newPlanIdForChild = (int) ($childOrder->plan_id ?? 0);
            $upgradeStateBySourceSubId[$sourceSubId] = [
                'plan_change_status' => $mappedPlanChangeStatus,
                'change_order_id' => $childId,
                'change_order_no' => (string) ($childOrder->order_no ?? ''),
                'change_order_status' => $childStatus,
                'new_plan_id' => $newPlanIdForChild,
                'new_plan_name' => (string) (optional($newPlansById->get($newPlanIdForChild))->name ?? $childOrder->plan_name ?? ''),
            ];
            $usedChildIds[] = $childId;
        }

        return $upgradeStateBySourceSubId;
    }

    /**
     * @param  array<int, array<string, mixed>>  $upgradeStateBySourceSubId
     * @param  \Illuminate\Support\Collection<int, Order>  $childChangeOrders
     * @param  \Illuminate\Support\Collection  $childOrderItems
     * @param  \Illuminate\Support\Collection  $newPlansById
     */
    private function resolvePlanChangeStatusForItem(
        OrderItem $item,
        int $parentOrderId,
        array $upgradeStateBySourceSubId,
        $childChangeOrders,
        $childOrderItems,
        $newPlansById
    ): string {
        $itemStatus = strtolower(trim((string) ($item->status ?? 'active')));
        if ($itemStatus === '') {
            $itemStatus = 'active';
        }

        if (in_array($itemStatus, ['upgraded', 'downgraded'], true)) {
            return $itemStatus;
        }

        if (isset($upgradeStateBySourceSubId[(int) $item->id])) {
            return (string) ($upgradeStateBySourceSubId[(int) $item->id]['plan_change_status'] ?? $itemStatus);
        }

        foreach ($childChangeOrders as $childOrder) {
            $matchesLine = false;
            $parentSubId = (int) ($childOrder->parent_order_sub_id ?? 0);
            $childItem = optional($childOrderItems->get((int) $childOrder->id))->first();
            $childMeta = is_array($childItem->meta ?? null) ? $childItem->meta : [];
            $previousSubId = (int) ($childItem->previous_order_sub_id ?? $childMeta['previous_order_sub_id'] ?? 0);
            if ($previousSubId > 0 && $previousSubId === (int) $item->id) {
                $matchesLine = true;
            } elseif ($parentSubId > 0 && $parentSubId === (int) $item->id) {
                $matchesLine = true;
            } else {
                $oldPlanId = (int) ($childMeta['old_plan_id'] ?? $childOrder->previous_plan_id ?? 0);
                $isRenewalChild = $this->isRenewalChangeOrder($childOrder);
                if ($oldPlanId <= 0 && $isRenewalChild) {
                    $oldPlanId = (int) ($childItem->plan_id ?? $childOrder->plan_id ?? 0);
                }
                if ($oldPlanId > 0 && $oldPlanId === (int) $item->plan_id) {
                    if ($parentSubId > 0 || $previousSubId > 0) {
                        // Explicit sub-id on child that didn't match this item â†’ not this line.
                        $matchesLine = false;
                    } else {
                        $samePlanCount = (int) OrderItem::query()
                            ->where('order_id', $parentOrderId)
                            ->where('plan_id', $oldPlanId)
                            ->where(function ($q) {
                                $q->whereNull('status')
                                    ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted', 'upgraded', 'downgraded', 'renewed')");
                            })
                            ->count();
                        $matchesLine = $samePlanCount === 1;
                    }
                }
            }

            if (!$matchesLine) {
                continue;
            }

            $childStatus = strtolower(trim((string) ($childOrder->status ?? '')));
            $changeCategory = strtolower(trim((string) ($childOrder->order_category ?? 'upgrade')));
            $isRenewalChild = $this->isRenewalChangeOrder($childOrder);

            // Draft renew only â€” pending RN (like CH upgrade) claims the parent line.
            if ($isRenewalChild && $childStatus === 'draft') {
                continue;
            }
            if (in_array($childStatus, ['cancelled', 'canceled', 'rejected', 'failed'], true)) {
                continue;
            }

            if (in_array($childStatus, ['pending', 'processing', 'draft'], true)) {
                if ($isRenewalChild) {
                    return 'renewal_pending';
                }

                return $changeCategory === 'downgrade' ? 'downgrade_pending' : 'upgrade_pending';
            }
            if (in_array($childStatus, ['completed', 'paid', 'success', 'active'], true)) {
                if ($isRenewalChild) {
                    return 'renewed';
                }

                return $changeCategory === 'downgrade' ? 'downgraded' : 'upgraded';
            }

            break;
        }

        return $itemStatus;
    }

    private function formatPlanLineDisplayStatus(string $planChangeStatus, string $itemStatus, string $orderLevelStatus): string
    {
        return match (true) {
            $planChangeStatus === 'upgraded', $itemStatus === 'upgraded' => 'Upgraded',
            $planChangeStatus === 'downgraded', $itemStatus === 'downgraded' => 'Downgraded',
            $planChangeStatus === 'upgrade_pending' => 'Upgrade Pending',
            $planChangeStatus === 'downgrade_pending' => 'Downgrade Pending',
            $planChangeStatus === 'renewal_pending', $itemStatus === 'pending_renewal' => 'Renewal Pending',
            $planChangeStatus === 'renewed', $itemStatus === 'renewed' => 'Renewed',
            default => $orderLevelStatus,
        };
    }

    /**
     * True for upgrade/downgrade/renewal child orders (CH* / RN* or matching category).
     */
    private function isPartnerPlanChangeOrder(Order $order): bool
    {
        return $this->partnerPlanChangeOrderKind($order) !== null;
    }

    /**
     * @return 'upgrade'|'downgrade'|'renewal'|null
     */
    private function partnerPlanChangeOrderKind(Order $order): ?string
    {
        $category = strtolower(trim((string) ($order->order_category ?? '')));
        $orderNo = strtoupper(trim((string) ($order->order_no ?? '')));
        $parentId = (int) ($order->parent_order_id ?? 0);

        // Root ORD* is NEVER a change-order row â€” even if category was stamped renewal/renewed
        // or parent_order_id was set by mistake. Only RN*/CH* (or non-ORD children) qualify.
        if (str_starts_with($orderNo, 'ORD')) {
            return null;
        }

        $isRn = str_starts_with($orderNo, 'RN');
        $isCh = str_starts_with($orderNo, 'CH');
        if (!$isRn && !$isCh && $parentId <= 0) {
            return null;
        }

        // "renewed" is a completed SOURCE marker â€” not a change-order kind.
        if ($isRn || in_array($category, ['renewal', 'renew'], true)) {
            return 'renewal';
        }
        if (in_array($category, ['downgrade', 'downgraded'], true)) {
            return 'downgrade';
        }
        if (in_array($category, ['upgrade', 'upgraded', 'partial_upgrade'], true)) {
            return 'upgrade';
        }
        if ($isCh) {
            // Infer when category missing: cheaper new plan = downgrade.
            $prevPlanId = (int) ($order->previous_plan_id ?? 0);
            $newPlanId = (int) ($order->plan_id ?? 0);
            if ($prevPlanId > 0 && $newPlanId > 0 && $prevPlanId !== $newPlanId) {
                $prices = Plan::query()
                    ->whereIn('id', [$prevPlanId, $newPlanId])
                    ->pluck('price', 'id');
                $oldPrice = (float) ($prices[$prevPlanId] ?? 0);
                $newPrice = (float) ($prices[$newPlanId] ?? 0);
                if ($oldPrice > 0 && $newPrice > 0) {
                    return $newPrice < $oldPrice ? 'downgrade' : 'upgrade';
                }
            }

            return 'upgrade';
        }

        return null;
    }

    /**
     * CH/RN child is live (no longer pending) — only then it replaces the parent plan.
     */
    private function isActivatedPlanChangeOrder(object $order): bool
    {
        if (!$this->isPartnerPlanChangeOrder($order)) {
            return false;
        }

        $status = strtolower(trim((string) ($order->status ?? '')));

        return in_array($status, ['completed', 'paid', 'success', 'active', 'upgraded', 'downgraded', 'renewed'], true);
    }

    /**
     * CH/RN child is still in flight — parent plan must stay Active.
     */
    private function isPendingPlanChangeOrder(object $order): bool
    {
        if (!$this->isPartnerPlanChangeOrder($order)) {
            return false;
        }

        $status = strtolower(trim((string) ($order->status ?? '')));

        return in_array($status, ['pending', 'processing', 'draft'], true);
    }

    /**
     * Parent plan line stays on the ORD card while the child is pending.
     * After the child is Active, hide the source line unless leftover seats remain.
     *
     * @param  array<int, array<string, mixed>>  $upgradeStateBySourceSubId
     */
    private function parentSourceLineRemainsOnParent(
        object $item,
        array $upgradeStateBySourceSubId,
        $childOrderItems,
        $childChangeOrders
    ): bool {
        $itemStatus = strtolower(trim((string) ($item->status ?? 'active')));
        if ($itemStatus === '') {
            $itemStatus = 'active';
        }
        if (in_array($itemStatus, ['delete', 'deleted'], true)) {
            return false;
        }

        $itemId = (int) ($item->id ?? 0);
        $lineQty = max(1, (int) ($item->quantity ?? 1));
        $pcs = '';
        if ($itemId > 0 && isset($upgradeStateBySourceSubId[$itemId])) {
            $pcs = strtolower(trim((string) ($upgradeStateBySourceSubId[$itemId]['plan_change_status'] ?? '')));
        }

        if (in_array($pcs, ['upgrade_pending', 'downgrade_pending', 'renewal_pending'], true)) {
            return true;
        }

        $activated = in_array($itemStatus, ['upgraded', 'downgraded', 'renewed'], true)
            || in_array($pcs, ['upgraded', 'downgraded', 'renewed'], true);
        if ($activated) {
            $moved = $this->resolveMovedLicensesForSourceLine(
                $itemId,
                $upgradeStateBySourceSubId,
                $childOrderItems,
                $childChangeOrders
            );
            $leftoverQty = $this->leftoverQtyAfterPlanChange(
                $lineQty,
                $moved,
                $itemStatus,
                $this->mappedChangeIsSamePlan($item, $upgradeStateBySourceSubId)
            );

            return $leftoverQty !== null && $leftoverQty > 0;
        }

        return in_array($itemStatus, ['active', 'completed', 'paid', 'success'], true);
    }

    /**
     * Licenses moved onto a CH/RN child for a parent order_sub line.
     * Used so partial upgrades keep leftover seats Active on the parent.
     *
     * @param  array<int, array<string, mixed>>  $upgradeStateBySourceSubId
     * @param  \Illuminate\Support\Collection  $childOrderItems
     * @param  \Illuminate\Support\Collection  $childChangeOrders
     */
    private function resolveMovedLicensesForSourceLine(
        int $sourceItemId,
        array $upgradeStateBySourceSubId,
        $childOrderItems,
        $childChangeOrders
    ): int {
        if ($sourceItemId <= 0 || !isset($upgradeStateBySourceSubId[$sourceItemId])) {
            return 0;
        }

        $childId = (int) ($upgradeStateBySourceSubId[$sourceItemId]['change_order_id'] ?? 0);
        if ($childId <= 0) {
            return 0;
        }

        $childOrder = collect($childChangeOrders)->firstWhere('id', $childId)
            ?? collect($childChangeOrders)->first(fn($o) => (int) ($o->id ?? 0) === $childId);
        if (!$childOrder || !$this->isActivatedPlanChangeOrder($childOrder)) {
            return 0;
        }

        $childItems = collect($childOrderItems->get($childId) ?? []);
        if ($childItems->isEmpty()) {
            $childItems = collect($childOrderItems->get((string) $childId) ?? []);
        }
        $qty = (int) $childItems->sum(fn($row) => max(1, (int) ($row->quantity ?? 1)));
        if ($qty > 0) {
            return $qty;
        }

        return max(1, (int) ($childOrder->quantity ?? 1));
    }

    /**
     * Claim a live parent line only when that order has exactly one live plan.
     * Unmatched leftover count of 1 is not enough — leftover Enterprise + Platinum
     * would otherwise let a second CH steal Platinum.
     *
     * @param  array<int, array<string, mixed>>  $upgradeStateBySourceSubId
     */
    private function soleUnmatchedLiveParentItemId(int $parentOrderId, array $upgradeStateBySourceSubId): int
    {
        $allLiveIds = OrderItem::query()
            ->where('order_id', $parentOrderId)
            ->where(function ($q) {
                $q->whereNull('status')
                    ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) IN ('', 'active', 'completed', 'paid', 'success')");
            })
            ->orderBy('id')
            ->pluck('id')
            ->map(fn($id) => (int) $id)
            ->filter(fn($id) => $id > 0)
            ->values()
            ->all();

        if (count($allLiveIds) !== 1) {
            return 0;
        }

        $onlyId = (int) $allLiveIds[0];
        if ($onlyId <= 0 || isset($upgradeStateBySourceSubId[$onlyId])) {
            return 0;
        }

        $anyReplacedSibling = OrderItem::query()
            ->where('order_id', $parentOrderId)
            ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) IN ('upgraded', 'downgraded', 'renewed')")
            ->exists();

        return $anyReplacedSibling ? 0 : $onlyId;
    }

    /**
     * True when the mapped CH/RN actually replaced this plan (same source plan or
     * same-plan license change). False for an untouched sibling like Platinum.
     *
     * @param  array<int, array<string, mixed>>  $upgradeStateBySourceSubId
     */
    private function mappedChangeTargetsSourcePlan(
        object $item,
        array $upgradeStateBySourceSubId,
        $childOrderItems,
        $childChangeOrders
    ): bool {
        $itemId = (int) ($item->id ?? 0);
        $itemPlanId = (int) ($item->plan_id ?? 0);
        if ($itemId <= 0 || $itemPlanId <= 0 || !isset($upgradeStateBySourceSubId[$itemId])) {
            return true;
        }

        $mapped = $upgradeStateBySourceSubId[$itemId];
        $newPlanId = (int) ($mapped['new_plan_id'] ?? 0);
        if ($newPlanId > 0 && $newPlanId === $itemPlanId) {
            return true;
        }

        $childId = (int) ($mapped['change_order_id'] ?? 0);
        $childItems = collect($childOrderItems->get($childId) ?? []);
        if ($childItems->isEmpty()) {
            $childItems = collect($childOrderItems->get((string) $childId) ?? []);
        }
        $childItem = $childItems->first();
        $childMeta = is_array($childItem->meta ?? null) ? $childItem->meta : [];
        $oldPlanId = (int) ($childMeta['old_plan_id'] ?? 0);
        if ($oldPlanId <= 0) {
            $childOrder = collect($childChangeOrders)->first(
                fn($row) => (int) ($row->id ?? 0) === $childId
            );
            $oldPlanId = (int) (optional($childOrder)->previous_plan_id ?? 0);
        }
        if ($oldPlanId > 0) {
            return $oldPlanId === $itemPlanId;
        }

        return !($newPlanId > 0 && $newPlanId !== $itemPlanId);
    }

    /**
     * Leftover seats on a parent source line after a partial upgrade/downgrade/renew.
     * Line qty may still be original (5) or already reduced (2 after moving 3).
     *
     * Same-plan full replace (renew 2 of 2) hides. Different-plan leftover (2→1) stays.
     *
     * @return int|null leftover qty to keep visible, or null to hide the line
     */
    private function leftoverQtyAfterPlanChange(
        int $lineQty,
        int $movedLicenses,
        string $itemStatus,
        bool $samePlanReplace = false
    ): ?int {
        $lineQty = max(0, $lineQty);
        $movedLicenses = max(0, $movedLicenses);
        $itemStatus = strtolower(trim($itemStatus));
        if ($itemStatus === '') {
            $itemStatus = 'active';
        }

        if ($movedLicenses <= 0) {
            return $lineQty > 0 ? $lineQty : null;
        }

        // Original qty still on the line (not reduced yet): 5 - 3 = 2 leftover.
        if ($lineQty > $movedLicenses) {
            return $lineQty - $movedLicenses;
        }

        // Full same-plan renewal / license change where all seats moved — hide parent line.
        if ($samePlanReplace && $lineQty === $movedLicenses) {
            return null;
        }

        // Qty already reduced to leftover after a move (e.g. lineQty is 2, moved was 3)
        if ($lineQty > 0) {
            return $lineQty;
        }

        return null;
    }

    /**
     * Renewal / same-plan license change vs leftover after a plan upgrade.
     *
     * @param  array<int, array<string, mixed>>  $upgradeStateBySourceSubId
     */
    private function mappedChangeIsSamePlan(object $item, array $upgradeStateBySourceSubId): bool
    {
        $itemId = (int) ($item->id ?? 0);
        if ($itemId <= 0 || !isset($upgradeStateBySourceSubId[$itemId])) {
            return false;
        }

        $mapped = $upgradeStateBySourceSubId[$itemId];
        $pcs = strtolower(trim((string) ($mapped['plan_change_status'] ?? '')));
        if (in_array($pcs, ['renewed', 'renewal_pending'], true)) {
            return true;
        }

        $itemPlanId = (int) ($item->plan_id ?? 0);
        $newPlanId = (int) ($mapped['new_plan_id'] ?? 0);

        return $itemPlanId > 0 && $newPlanId > 0 && $itemPlanId === $newPlanId;
    }

    /**
     * Frontend flags to show/hide Upgrade, Partial Upgrade, and License Add.
     *
     * Microsoft (direct cart):
     *   Upgrade         → all current licenses to a higher plan (qty locked).
     *   Partial Upgrade → fewer licenses to a higher plan (old + new both remain in the order list).
     *   License Add     → extra seats on the same plan (separate from upgrade/partial).
     *
     * Google / Tizzy:
     *   Upgrade / partial / license add are request-based.
     *   Downgrade is a lower plan with the same license count.
     *
     * @param  array{allow_add_license?: bool, provider_id?: int, via_request?: bool}  $opts
     * @return array<string, mixed>
     */
    private function upgradeButtonFlags(bool $allowFull, ?bool $allowPartial = null, array $opts = []): array
    {
        if ($allowPartial === null) {
            $allowPartial = $allowFull;
        }
        $allowAddLicense = array_key_exists('allow_add_license', $opts)
            ? (bool) $opts['allow_add_license']
            : $allowFull;
        $providerId = (int) ($opts['provider_id'] ?? 0);
        $viaRequest = array_key_exists('via_request', $opts)
            ? (bool) $opts['via_request']
            : $this->isRequestBasedChangeProvider($providerId);

        return [
            'can_upgrade' => $allowFull,
            'can_partial_upgrade' => $allowPartial,
            'can_add_license' => $allowAddLicense,
            'hide_upgrade' => !$allowFull,
            'hide_partial_upgrade' => !$allowPartial,
            'upgrade_action' => 'plan_change_all_licenses',
            'partial_upgrade_action' => 'subset_licenses_higher_plan',
            'add_license_action' => 'same_plan_license_add',
            'add_license_endpoint' => 'license-add-to-cart',
            'same_plan_use_partial_upgrade' => false,
            'license_qty_editable' => false,
            'partial_license_qty_editable' => true,
            'hide_add_license' => !$allowAddLicense,
            'change_via' => $viaRequest ? 'request' : 'cart',
            'requires_request' => $viaRequest,
            'provider_id' => $providerId > 0 ? $providerId : null,
        ];
    }

    private function isMicrosoftProvider(?int $providerId): bool
    {
        return (int) $providerId === OrderCancellationPolicy::PROVIDER_MICROSOFT;
    }

    private function isRequestBasedChangeProvider(?int $providerId): bool
    {
        $id = (int) $providerId;

        if ($id === OrderCancellationPolicy::PROVIDER_GOOGLE || $id === OrderCancellationPolicy::PROVIDER_TIZZY) {
            return true;
        }

        if ($id > 0) {
            $provider = Provider::query()->find($id);
            if ($provider) {
                $name = strtolower(trim($provider->name ?? ''));
                if (str_contains($name, 'tizzy') || str_contains($name, 'google')) {
                    return true;
                }
            }
        }

        return false;
    }

    private function planRankPrice(?Plan $plan): float
    {
        if (!$plan) {
            return 0.0;
        }

        return round((float) ($plan->price ?? $plan->selling_price ?? $plan->actual_price ?? 0), 2);
    }

    private function isHigherPlan(Plan $newPlan, int $sourcePlanId): bool
    {
        if ($sourcePlanId <= 0) {
            return false;
        }

        // Same plan is never an upgrade
        if ((int) $newPlan->id === $sourcePlanId) {
            return false;
        }

        $old = Plan::query()->find($sourcePlanId);

        // If source plan cannot be found, allow the upgrade
        if (!$old) {
            return true;
        }

        /*
        |--------------------------------------------------------------------------
        | Get prices
        |--------------------------------------------------------------------------
        */

        $oldPrice = round((float) $this->planRankPrice($old), 2);
        $newPrice = round((float) $this->planRankPrice($newPlan), 2);

        $oldActualPrice = round((float) ($old->actual_price ?? 0), 2);
        $newActualPrice = round((float) ($newPlan->actual_price ?? 0), 2);

        /*
        |--------------------------------------------------------------------------
        | PRIMARY CHECK
        |--------------------------------------------------------------------------
        | Price should determine whether the requested plan is higher.
        |
        | Example:
        | Old plan      = ₹7,980
        | Requested     = ₹10,320
        |
        | 10,320 > 7,980 = HIGHER PLAN
        |--------------------------------------------------------------------------
        */

        if ($newPrice > $oldPrice) {
            Log::info('isHigherPlan: higher plan by price', [
                'source_plan_id' => $sourcePlanId,
                'source_plan_name' => $old->name,
                'source_price' => $oldPrice,

                'target_plan_id' => $newPlan->id,
                'target_plan_name' => $newPlan->name,
                'target_price' => $newPrice,

                'result' => true,
            ]);

            return true;
        }

        /*
        |--------------------------------------------------------------------------
        | ACTUAL PRICE FALLBACK
        |--------------------------------------------------------------------------
        */

        if ($newActualPrice > $oldActualPrice) {
            Log::info('isHigherPlan: higher plan by actual price', [
                'source_plan_id' => $sourcePlanId,
                'source_plan_name' => $old->name,
                'source_actual_price' => $oldActualPrice,

                'target_plan_id' => $newPlan->id,
                'target_plan_name' => $newPlan->name,
                'target_actual_price' => $newActualPrice,

                'result' => true,
            ]);

            return true;
        }

        /*
        |--------------------------------------------------------------------------
        | EQUAL PRICE
        |--------------------------------------------------------------------------
        | If prices are equal, use sr_no as secondary comparison.
        |--------------------------------------------------------------------------
        */

        $oldSr = (int) ($old->sr_no ?? 0);
        $newSr = (int) ($newPlan->sr_no ?? 0);

        if ($newPrice == $oldPrice && $newSr > $oldSr) {
            Log::info('isHigherPlan: higher plan by sr_no', [
                'source_plan_id' => $sourcePlanId,
                'source_plan_name' => $old->name,
                'source_sr' => $oldSr,
                'source_price' => $oldPrice,

                'target_plan_id' => $newPlan->id,
                'target_plan_name' => $newPlan->name,
                'target_sr' => $newSr,
                'target_price' => $newPrice,

                'result' => true,
            ]);

            return true;
        }

        /*
        |--------------------------------------------------------------------------
        | MICROSOFT SR_NO FALLBACK
        |--------------------------------------------------------------------------
        | Only use sr_no when there is no useful price difference.
        |--------------------------------------------------------------------------
        */

        $providerId = (int) ($newPlan->provider_id ?? $old->provider_id ?? 0);

        if ($providerId === 2) {
            if (
                $oldPrice <= 0 &&
                $newPrice <= 0 &&
                $oldActualPrice <= 0 &&
                $newActualPrice <= 0 &&
                $oldSr > 0 &&
                $newSr > 0
            ) {
                return $newSr > $oldSr;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | DEBUG
        |--------------------------------------------------------------------------
        */

        Log::info('isHigherPlan comparison: NOT HIGHER', [
            'source_plan_id' => $sourcePlanId,
            'source_plan_name' => $old->name,
            'source_provider_id' => $old->provider_id,
            'source_sr' => $oldSr,
            'source_price' => $oldPrice,
            'source_actual_price' => $oldActualPrice,

            'target_plan_id' => $newPlan->id,
            'target_plan_name' => $newPlan->name,
            'target_provider_id' => $newPlan->provider_id,
            'target_sr' => $newSr,
            'target_price' => $newPrice,
            'target_actual_price' => $newActualPrice,

            'result' => false,
        ]);

        return false;
    }

    private function isLowerPlan(Plan $newPlan, int $sourcePlanId): bool
    {
        if ($sourcePlanId <= 0 || (int) $newPlan->id === $sourcePlanId) {
            return false;
        }
        $old = Plan::query()->find($sourcePlanId);
        if (!$old) {
            return true;
        }

        return $this->planRankPrice($newPlan) < $this->planRankPrice($old);
    }

    private function changeRequestRequiredResponse(string $action, int $providerId, array $details = []): \Illuminate\Http\JsonResponse
    {
        $provider = $providerId === OrderCancellationPolicy::PROVIDER_GOOGLE ? 'Google' : 'Tizzy';
        $req = request();
        $partnerId = (int) ($req->input('partner_id') ?? 0);
        $enquiryId = null;

        $currentPlanId = (int) ($details['current_plan_id'] ?? $req->input('from_plan_id', $req->input('current_plan_id', 0)));
        $requestedPlanId = (int) ($details['plan_id'] ?? $req->input('plan_id', 0));
        $licenses = max(1, (int) ($details['licenses'] ?? $req->input('licenses', $req->input('license_count', 1))));

        if ($partnerId > 0) {
            $lines = [
                $provider . ' ' . $action . ' request',
                'Order ID: ' . (int) ($details['order_id'] ?? $req->input('order_id', 0)),
                'Order sub ID: ' . (int) ($details['order_sub_id'] ?? $req->input('order_sub_id', $req->input('order_item_id', 0))),
                'Current plan ID: ' . $currentPlanId,
                'Requested plan ID: ' . $requestedPlanId,
                'Licenses: ' . $licenses,
                'Customer ID: ' . (int) ($details['customer_id'] ?? $req->input('customer_id', 0)),
            ];
            try {
                $enquiry = Enquiry::query()->create([
                    'partner_id' => $partnerId,
                    'message' => implode("\n", $lines),
                    'status' => 'new',
                ]);
                $enquiryId = (int) ($enquiry->id ?? 0);
            } catch (\Throwable $e) {
                return response()->json([
                    'success' => false,
                    'requires_request' => true,
                    'change_via' => 'request',
                    'action' => $action,
                    'provider_id' => $providerId,
                    'message' => $provider . ' ' . $action . ' must be submitted as a request, but the request could not be saved.',
                    'error' => $e->getMessage(),
                ], 422);
            }
        }

        $currentPlanObj = $currentPlanId > 0 ? Plan::query()->find($currentPlanId) : null;
        $requestedPlanObj = $requestedPlanId > 0 ? Plan::query()->find($requestedPlanId) : null;

        $currentPlanData = null;
        if ($currentPlanObj) {
            $currentPlanData = [
                'id' => (int) $currentPlanObj->id,
                'plan_id' => (int) $currentPlanObj->id,
                'name' => (string) ($currentPlanObj->name ?? $currentPlanObj->title ?? ''),
                'title' => (string) ($currentPlanObj->title ?? $currentPlanObj->name ?? ''),
                'plan_name' => (string) ($currentPlanObj->name ?? $currentPlanObj->title ?? ''),
                'price' => (float) ($currentPlanObj->price ?? 0),
                'amount' => (float) ($currentPlanObj->price ?? 0),
                'licenses' => $licenses,
                'provider_id' => (int) ($currentPlanObj->provider_id ?? 0),
                'provider_name' => $provider,
            ];
        }

        $selectedPlanData = null;
        if ($requestedPlanObj) {
            $selectedPlanData = [
                'id' => (int) $requestedPlanObj->id,
                'plan_id' => (int) $requestedPlanObj->id,
                'name' => (string) ($requestedPlanObj->name ?? $requestedPlanObj->title ?? ''),
                'title' => (string) ($requestedPlanObj->title ?? $requestedPlanObj->name ?? ''),
                'plan_name' => (string) ($requestedPlanObj->name ?? $requestedPlanObj->title ?? ''),
                'price' => (float) ($requestedPlanObj->price ?? 0),
                'amount' => (float) ($requestedPlanObj->price ?? 0),
                'licenses' => $licenses,
                'provider_id' => (int) ($requestedPlanObj->provider_id ?? 0),
                'provider_name' => $provider,
            ];
        }

        // Resolve coupon code (accept coupon_code / coupen / promo_code from request).
        $couponCodeRaw = strtoupper(trim((string) (
            $req->input('coupon_code')
            ?? $req->input('coupen')
            ?? $req->input('promo_code')
            ?? ($details['coupon_code'] ?? '')
        )));
        $couponDiscountPercent = $couponCodeRaw !== ''
            ? app(PartnerCartService::class)->resolveCouponDiscountPercent($couponCodeRaw)
            : 0.0;

        // Resolve supplementary context to mirror the cart-update response structure.
        $reqCartId       = (int) ($details['cart_id']      ?? $req->input('cart_id')      ?? 0) ?: null;
        $reqMainCartId   = (int) ($details['main_cart_id'] ?? $req->input('main_cart_id') ?? $reqCartId ?? 0) ?: null;
        $reqOrderId      = (int) ($details['order_id']     ?? $req->input('order_id')     ?? 0) ?: null;
        $reqOrderSubId   = (int) ($details['order_sub_id'] ?? $req->input('order_sub_id') ?? $req->input('order_item_id') ?? 0) ?: null;
        $reqCustomerId   = (int) ($details['customer_id']  ?? $req->input('customer_id')  ?? 0) ?: null;
        $reqCompanyName  = trim((string) ($details['company_name'] ?? $req->input('company_name') ?? ''));
        $reqDomainName   = $req->input('domain_name')   ?? $details['domain_name']   ?? null;
        $reqTransfer     = $req->input('transfer_domain') ?? $details['transfer_domain'] ?? null;

        $partnerObj  = $partnerId    > 0 ? Partner::find($partnerId)    : null;
        $customerObj = $reqCustomerId > 0 ? Customer::find($reqCustomerId) : null;

        $actionLower = strtolower(trim($action));
        $isUpgrade = str_contains($actionLower, 'upgrade');
        $isDowngrade = str_contains($actionLower, 'downgrade');
        $isLicenseAdd = str_contains($actionLower, 'license add');

        $orderIdHint = $reqOrderId > 0 ? $reqOrderId : null;

        [$sourceOrder, $sourceItem, $resolvedSourceOrderId] = $this->resolveUpgradeSourceSubscription(
            $partnerId,
            $reqCustomerId ?: null,
            $orderIdHint,
            $reqOrderSubId > 0 ? $reqOrderSubId : null,
            $currentPlanId > 0 ? $currentPlanId : null
        );

        $cartCalc = app(PartnerCartService::class);
        $gstPercentage = 18.0;

        $newUnitPrice = round((float) ($requestedPlanObj->price ?? 0), 2);

        $licenseTotals = $this->resolveUpgradeLicenseTotals($sourceOrder, $sourceItem);
        $oldTotalLicenses = (int) ($licenseTotals['old_total_licenses'] ?? 0);
        $newTotalLicenses = (int) ($licenseTotals['new_total_licenses'] ?? 0);
        $currentLicenses = max(1, (int) ($licenseTotals['current_licenses'] ?? 1));

        $subscriptionDates = [];
        if ($sourceOrder && $sourceItem) {
            $planChangeItem = new OrderItem(['plan_id' => $requestedPlanId, 'licenses' => $licenses]);
            $subscriptionDates = $this->formatUpgradeSubscriptionDates($sourceOrder, $sourceItem, $planChangeItem);
        }
        $reqStartDate = $subscriptionDates['start'] ?? $req->input('subscription_start_date') ?? $details['subscription_start_date'] ?? null;
        $reqEndDate   = $subscriptionDates['end'] ?? $req->input('subscription_end_date')   ?? $details['subscription_end_date']   ?? null;
        if ($reqStartDate === null && $sourceItem && !empty($sourceItem->subscription_start_date)) {
            $reqStartDate = \Carbon\Carbon::parse($sourceItem->subscription_start_date)->format('Y-m-d');
            $reqEndDate = \Carbon\Carbon::parse($sourceItem->subscription_end_date)->format('Y-m-d');
        }

        if ($isUpgrade || $isDowngrade || $isLicenseAdd) {
            $calculation = $isLicenseAdd
                ? $this->resolveLicenseAddProration(
                    $sourceOrder,
                    $sourceItem,
                    $newUnitPrice,
                    $licenses,
                    $gstPercentage,
                    $couponDiscountPercent
                )
                : $this->resolveUpgradeProration(
                    $sourceOrder,
                    $sourceItem,
                    $newUnitPrice,
                    $licenses,
                    $gstPercentage,
                    $couponDiscountPercent,
                    $requestedPlanId
                );
            $lineAmounts = [
                'subtotal' => round((float) ($calculation['new_plan_cost'] ?? $calculation['subtotal'] ?? 0), 2),
                'plan_discount_amount' => 0,
                'coupon_discount_amount' => round((float) ($calculation['coupon_discount'] ?? 0), 2),
                'discount_amount' => round((float) ($calculation['coupon_discount'] ?? 0), 2),
            ];
        } else {
            $lineAmounts = $cartCalc->calculateLineAmounts(
                $requestedPlanObj,
                $licenses,
                $gstPercentage,
                $couponDiscountPercent
            );
            $calculation = [
                'subtotal' => $lineAmounts['subtotal'],
                'new_plan_cost' => $lineAmounts['subtotal'],
                'gst_amount' => $lineAmounts['gst_amount'],
                'final_payable' => $lineAmounts['grand_total'],
                'taxable_amount' => $lineAmounts['after_discount'],
                'coupon_discount' => $lineAmounts['coupon_discount_amount'],
                'remaining_value' => 0,
                'remaining_credit' => 0,
                'pro_rata_adjustment' => 0,
                'applied_pro_rata' => 0,
                'credit_licenses' => 0,
                'current_licenses' => $licenses,
                'current_unit_price' => round((float) ($currentPlanObj->price ?? 0), 2),
                'daily_rate_per_license' => 0,
                'remaining_days' => 0,
            ];
        }

        if (is_array($selectedPlanData)) {
            $selectedPlanData['remaining_value'] = round((float) ($calculation['remaining_value'] ?? 0), 2);
        }

        $walletBalance = $partnerId > 0
            ? round(PartnerCreditService::remainingPurchaseAllowance($partnerId), 2)
            : 0.0;

        $payableAmount = round((float) ($calculation['final_payable'] ?? 0), 2);
        $creditDetails = $this->partnerB2bCreditSummary($partnerId, $payableAmount);

        $responseData = [
            // Identity / routing — matches existing callers.
            'request_id'       => $enquiryId,
            'action'           => $action,
            'action_type'      => $action,
            'requires_request' => true,
            'change_via'       => 'request',
            'request_endpoint' => '/api/partner/' . str_replace(' ', '-', strtolower($action)) . '-request',
            'request_message'  => 'This ' . $provider . ' ' . $action . ' requires a request for approval.',

            // Cart / order identifiers.
            'main_cart_id' => $reqMainCartId,
            'cart_id'      => $reqCartId,
            'order_id'     => $reqOrderId,
            'order_sub_id' => $reqOrderSubId,

            // Parties.
            'partner_id'   => $partnerId,
            'customer_id'  => $reqCustomerId,
            'provider_id'  => $providerId,
            'provider_name' => $provider,
            'company_name' => $reqCompanyName,

            // Plan identifiers (kept for backward-compat).
            'plan_id'          => $requestedPlanId,
            'current_plan_id'  => $currentPlanId,
            'selected_plan_id' => $requestedPlanId,
            'current_plan'     => $currentPlanData,
            'selected_plan'    => $selectedPlanData,
            'requested_plan'   => $selectedPlanData,
            'currentplandetails' => $sourceItem ? $sourceItem->toArray() : $currentPlanData,
            'plans'            => $selectedPlanData ? [$selectedPlanData] : [],

            // Partner details.
            'partner' => [
                'name'              => optional($partnerObj)->name,
                'email'             => optional($partnerObj)->email,
                'mobile'            => optional($partnerObj)->mobile,
                'wallet_balance'    => $walletBalance,
                'available_balance' => $walletBalance,
                'credit_limit'      => round((float) (optional($partnerObj)->credit_limit ?? 0), 2),
            ],

            // Customer details.
            'customer' => [
                'id'           => optional($customerObj)->id,
                'name'         => optional($customerObj)->name,
                'email'        => optional($customerObj)->email,
                'mobile'       => optional($customerObj)->mobile,
                'company_name' => optional($customerObj)->company_name ?? ($reqCompanyName ?: '-'),
                'address'      => optional($customerObj)->address,
            ],

            // Requested plan details.
            'plan' => [
                'plan_name'     => (string) ($requestedPlanObj->name     ?? ''),
                'title'         => (string) ($requestedPlanObj->title    ?? ''),
                'storage'       => (string) ($requestedPlanObj->storage  ?? ''),
                'billing_cycle' => (string) ($requestedPlanObj->billing_cycle ?? ''),
                'actual_price'  => (float)  ($requestedPlanObj->actual_price  ?? 0),
                'selling_price' => (float)  ($requestedPlanObj->price         ?? 0),
                'provider_id'   => (int)    ($requestedPlanObj->provider_id   ?? $providerId),
            ],

            'domain_name'             => $reqDomainName,
            'transfer_domain'         => $reqTransfer,
            'subscription_start_date' => $reqStartDate,
            'subscription_end_date'   => $reqEndDate,

            // Licensing & pricing.
            'licenses'               => $licenses,
            'unit_price'             => $newUnitPrice,
            'coupen'                 => $couponCodeRaw !== '' ? $couponCodeRaw : null,
            'coupon_code'            => $couponCodeRaw !== '' ? $couponCodeRaw : null,
            'coupon_discount_percent' => $couponDiscountPercent,
            'remaining_value'        => round((float) ($calculation['remaining_value'] ?? 0), 2),
            'remaining_credit'       => round((float) ($calculation['remaining_credit'] ?? 0), 2),
            'pro_rata_adjustment'    => round((float) ($calculation['pro_rata_adjustment'] ?? 0), 2),
            'applied_pro_rata'       => round((float) ($calculation['applied_pro_rata'] ?? 0), 2),
            'new_plan_cost'          => round((float) ($calculation['new_plan_cost'] ?? $lineAmounts['subtotal'] ?? 0), 2),
            'subtotal'               => round((float) ($calculation['new_plan_cost'] ?? $lineAmounts['subtotal'] ?? 0), 2),
            'credit_licenses'        => (int) ($calculation['credit_licenses'] ?? 0),
            'old_total_licenses'     => $oldTotalLicenses,
            'new_total_licenses'     => $newTotalLicenses,
            'current_licenses'       => $currentLicenses,
            'total_licenses'         => $currentLicenses,
            'current_unit_price'     => round((float) ($calculation['current_unit_price'] ?? 0), 2),
            'daily_rate_per_license' => round((float) ($calculation['daily_rate_per_license'] ?? 0), 2),
            'remaining_days'         => (int) ($calculation['remaining_days'] ?? 0),
            'taxable_amount'         => round((float) ($calculation['taxable_amount'] ?? 0), 2),
            'gst_amount'             => round((float) ($calculation['gst_amount'] ?? 0), 2),
            'final_payable'          => round((float) ($calculation['final_payable'] ?? 0), 2),


            'pricing' => [
                'subtotal'               => $lineAmounts['subtotal'],
                'new_plan_cost'          => round((float) ($calculation['new_plan_cost'] ?? $lineAmounts['subtotal']), 2),
                'remaining_credit'       => round((float) ($calculation['remaining_credit'] ?? 0), 2),
                'remaining_value'        => round((float) ($calculation['remaining_value'] ?? 0), 2),
                'wallet_credit'          => round((float) ($calculation['wallet_credit'] ?? 0), 2),
                'remaining_days'         => (int) ($calculation['remaining_days'] ?? 0),
                'credit_licenses'        => (int) ($calculation['credit_licenses'] ?? 0),
                'current_licenses'       => (int) ($calculation['current_licenses'] ?? 0),
                'current_unit_price'     => round((float) ($calculation['current_unit_price'] ?? 0), 2),
                'daily_rate_per_license' => round((float) ($calculation['daily_rate_per_license'] ?? 0), 2),
                'final_payable'          => round((float) ($calculation['final_payable'] ?? 0), 2),
                'plan_discount_amount'   => $lineAmounts['plan_discount_amount'],
                'coupon_discount_amount' => $lineAmounts['coupon_discount_amount'],
                'discount_amount'        => $lineAmounts['discount_amount'],
                'pro_rata_adjustment'    => round((float) ($calculation['pro_rata_adjustment'] ?? 0), 2),
                'applied_pro_rata'       => round((float) ($calculation['applied_pro_rata'] ?? 0), 2),
                'gst_percentage'         => round($gstPercentage, 2),
                'gst_amount'             => round((float) ($calculation['gst_amount'] ?? 0), 2),
                'taxable_amount'         => round((float) ($calculation['taxable_amount'] ?? 0), 2),
                'grand_total'            => round((float) ($calculation['final_payable'] ?? 0), 2),
                'item_grand_total'       => round((float) ($calculation['new_plan_cost'] ?? 0), 2),
            ],

            // Timestamps & credit limits.
            'created_at'             => null,
            'updated_at'             => null,
            'credit_limit'           => 0,
            'credit_used'            => 0,
            'remaining_credit_limit' => 0,
            'credit_limit_reached'   => false,
            'can_purchase'           => true,
            'purchase_block_message' => null,
            'license_decrease'       => null,
        ];

        return response()->json([
            'success' => true,
            'message' => $provider . ' ' . $action . ' request has been submitted. Direct cart checkout is only for Microsoft.',
            'data' => $responseData,
        ]);
    }

    /**
     * Hide source plan lines that already have a pending/completed upgrade/downgrade/renewal
     * child order. Those plans must not appear as "Upgrade Pending" on the parent â€”
     * only the new CH/RN order shows pending, and leftover Active plans stay on the parent.
     */
    private function shouldHideReplacedSourcePlanFromCurrentList(
        Order $order,
        string $itemStatus,
        string $planChangeStatus,
        string $displayStatus = ''
    ): bool {
        // Always keep the NEW change order visible (Upgrade/Downgrade/Renewal Pending).
        if ($this->isPartnerPlanChangeOrder($order)) {
            return false;
        }

        $itemStatus = strtolower(trim($itemStatus));
        $planChangeStatus = strtolower(trim($planChangeStatus));
        $displayStatus = strtolower(trim($displayStatus));

        if (in_array($itemStatus, ['upgraded', 'downgraded', 'renewed'], true)) {
            return true;
        }

        // Pending renewal/upgrade/partial upgrade stays on the parent as Active.
        if (in_array($planChangeStatus, [
            'upgrade_pending',
            'downgrade_pending',
            'renewal_pending',
        ], true)) {
            return false;
        }

        if (in_array($planChangeStatus, [
            'upgraded',
            'downgraded',
            'renewed',
        ], true)) {
            return true;
        }

        if (in_array($displayStatus, [
            'upgrade pending',
            'downgrade pending',
            'renewal pending',
        ], true)) {
            return false;
        }

        if (in_array($displayStatus, [
            'upgraded',
            'downgraded',
            'renewed',
        ], true)) {
            return true;
        }

        return false;
    }

    /**
     * Plan-wise status wins over whole-order category labels.
     * - Source plan lines: upgraded / upgrade_pending / active per line
     * - New change-order plans: pending â†’ Upgrade/Downgrade/Renewal Pending, then Active
     */
    private function preferPlanWiseStatus(
        Order $order,
        string $itemStatus,
        string $planChangeStatus,
        string $fallbackStatus,
        bool $isCancelledOrder = false
    ): string {
        if ($isCancelledOrder) {
            return 'Cancelled';
        }

        $itemStatus = strtolower(trim($itemStatus));
        $planChangeStatus = strtolower(trim($planChangeStatus));
        $orderStatus = strtolower(trim((string) ($order->status ?? '')));
        $changeKind = $this->partnerPlanChangeOrderKind($order);

        // This row is the NEW upgrade/downgrade/renewal order's plan.
        if ($changeKind !== null) {
            if (
                in_array($orderStatus, ['pending', 'processing'], true)
                || ($orderStatus === 'draft' && $changeKind !== 'renewal')
            ) {
                if ($changeKind === 'upgrade') {
                    return 'Upgrade Pending';
                }
                if ($changeKind === 'downgrade') {
                    return 'Downgrade Pending';
                }
                if ($changeKind === 'renewal' && $orderStatus !== 'draft') {
                    return 'Renewal Pending';
                }
            }
            if (in_array($orderStatus, ['completed', 'paid', 'success', 'active'], true)) {
                return in_array($fallbackStatus, ['Active', 'Expiring', 'Expired'], true)
                    ? $fallbackStatus
                    : 'Active';
            }
        }

        $fromPlan = $this->formatPlanLineDisplayStatus($planChangeStatus, $itemStatus, $fallbackStatus);
        // Pending labels belong only on the CH/RN row â€” never on the parent ORD source line.
        if ($changeKind === null && in_array($fromPlan, [
            'Upgrade Pending',
            'Downgrade Pending',
            'Renewal Pending',
        ], true)) {
            return 'Active';
        }
        if (in_array($fromPlan, [
            'Upgraded',
            'Downgraded',
            'Renewed',
            'Upgrade Pending',
            'Downgrade Pending',
            'Renewal Pending',
        ], true)) {
            return $fromPlan;
        }

        return $fallbackStatus;
    }

    /**
     * Per-plan status for subscription details â€” includes renewal pending on plan lines.
     *
     * @param  array{pending_renewal_licenses?: int, remaining_licenses?: int}|array<string, mixed>  $partial
     * @param  array{status?: string, replaced_qty?: int, pending_renewal_qty?: int}|null  $replacement
     * @return array{
     *   status: string,
     *   plan_change_status: string,
     *   item_status: string,
     *   renewal_status: ?string
     * }
     */
    private function resolveSubscriptionPlanLineDisplay(
        Order $order,
        string $planChangeStatus,
        string $itemStatus,
        string $orderLevelStatus,
        array $partial,
        ?array $replacement,
        bool $treatAsLive,
        bool $isFullyReplaced
    ): array {
        $pendingRenewalQty = max(
            (int) ($partial['pending_renewal_licenses'] ?? 0),
            (int) ($replacement['pending_renewal_qty'] ?? 0)
        );

        $status = $this->formatPlanLineDisplayStatus($planChangeStatus, $itemStatus, $orderLevelStatus);
        $renewalStatus = null;

        // Leftover seats keep Active/Expiring only when THIS line is not the pending change source.
        // Do not clear renewal_pending/upgrade_pending here â€” that blocked hide-on-parent (duplicate Expired).

        if ($this->isRenewalOrderRow($order)) {
            $renewalDisplay = $this->resolveRenewalOrderDisplayStatus($order, $status);
            $status = (string) ($renewalDisplay['status'] ?? $status);
            $renewalStatus = $renewalDisplay['renewal_status'] ?? null;
            if ($status === 'Renewal Pending') {
                $planChangeStatus = 'renewal_pending';
            }
        } elseif ($planChangeStatus === 'renewal_pending' || $itemStatus === 'pending_renewal') {
            // Parent ORD source line: mark for hide â€” never paint "Renewal Pending" on ORD itself.
            // Only the RN* row shows Renewal Pending.
            $planChangeStatus = 'renewal_pending';
            $status = 'Active';
        } elseif ($itemStatus === 'renewed' && $pendingRenewalQty > 0) {
            $planChangeStatus = 'renewal_pending';
            $itemStatus = 'pending_renewal';
            $status = 'Active';
        } elseif ($isFullyReplaced && $pendingRenewalQty > 0) {
            $planChangeStatus = 'renewal_pending';
            $status = 'Active';
        } elseif (
            $treatAsLive
            && !$isFullyReplaced
            && in_array($status, ['Renewed', 'Upgraded', 'Downgraded'], true)
        ) {
            $status = in_array($orderLevelStatus, ['Active', 'Expiring', 'Expired'], true) ? $orderLevelStatus : 'Active';
            $planChangeStatus = 'active';
        }

        return [
            'status' => $status,
            'plan_change_status' => $planChangeStatus,
            'item_status' => $itemStatus,
            'renewal_status' => $renewalStatus,
        ];
    }

    /**
     * Child renewal exists but e-sign/aadhaar is not done yet â€” parent must stay Expiring.
     */
    private function isUnsignedRenewalChild(object $order): bool
    {
        if (!$this->isRenewalChangeOrder($order)) {
            return false;
        }

        $status = strtolower(trim((string) ($order->status ?? '')));
        if ($status === 'draft') {
            return true;
        }

        // Pending renew before aadhaar verify must not flip parent to Renewal Pending.
        if ($status !== 'pending') {
            return false;
        }

        $orderId = (int) ($order->id ?? 0);
        if ($orderId <= 0) {
            return true;
        }

        $verified = (int) OrderPoDetail::query()
            ->where('order_id', $orderId)
            ->value('aadhar_verified');

        return $verified !== 1;
    }

    private function isRenewalOrderRow(Order $order): bool
    {
        return $this->isRenewalChangeOrder($order);
    }

    /**
     * Child or standalone order row created for subscription renewal (not upgrade/downgrade).
     */
    private function isRenewalChangeOrder(object $order): bool
    {
        $category = strtolower(trim((string) ($order->order_category ?? '')));
        $orderNo = strtoupper(trim((string) ($order->order_no ?? '')));
        $parentId = (int) ($order->parent_order_id ?? 0);

        // Parent ORD* is never a renewal row â€” only RN* (or a non-ORD child renewal).
        if (str_starts_with($orderNo, 'ORD')) {
            return false;
        }

        if (str_starts_with($orderNo, 'RN')) {
            return true;
        }

        if ($parentId > 0 && in_array($category, ['renewal', 'renew'], true)) {
            return true;
        }

        return false;
    }

    /**
     * @return array{
     *   status: string,
     *   renewal_status: ?string,
     *   statuses: list<string>,
     *   status_detail: ?string
     * }
     */
    private function buildSubscriptionStatusDisplay(
        string $subscriptionStatus,
        int $pendingLicenses,
        int $leftoverLicenses = 0,
        bool $includeCountsInDetail = false,
        string $pendingLabel = 'Renewal Pending'
    ): array {
        $subscriptionStatus = trim($subscriptionStatus) !== '' ? $subscriptionStatus : 'Expiring';
        $pendingLabel = trim($pendingLabel) !== '' ? $pendingLabel : 'Renewal Pending';
        $renewalStatus = null;
        $statuses = [$subscriptionStatus];

        if ($pendingLicenses > 0) {
            $renewalStatus = $pendingLabel;
            $statuses[] = $pendingLabel;
        }

        $statusDetail = null;
        if ($pendingLicenses > 0) {
            $statusDetail = $includeCountsInDetail && $leftoverLicenses > 0
                ? $leftoverLicenses . ' ' . $subscriptionStatus . ' Â· ' . $pendingLicenses . ' ' . $pendingLabel
                : implode(' Â· ', $statuses);
        }

        return [
            'status' => $subscriptionStatus,
            'renewal_status' => $renewalStatus,
            'statuses' => $statuses,
            'status_detail' => $statusDetail,
        ];
    }

    /**
     * @return array{
     *   status: string,
     *   renewal_status: ?string,
     *   statuses: list<string>,
     *   status_detail: ?string
     * }
     */
    private function resolveRenewalOrderDisplayStatus(Order $order, string $resolvedStatus): array
    {
        if (!$this->isRenewalOrderRow($order)) {
            return [
                'status' => $resolvedStatus,
                'renewal_status' => null,
                'statuses' => [$resolvedStatus],
                'status_detail' => null,
            ];
        }

        $rawStatus = strtolower(trim((string) ($order->status ?? '')));
        // Draft / aadhaar not done â†’ do not treat as Renewal Pending (parent stays Expiring).
        if ($rawStatus === 'draft' || $this->isUnsignedRenewalChild($order)) {
            return [
                'status' => $resolvedStatus,
                'renewal_status' => null,
                'statuses' => [$resolvedStatus],
                'status_detail' => null,
            ];
        }
        if (
            $rawStatus === 'pending'
            || $rawStatus === 'processing'
            || in_array($resolvedStatus, ['Pending', 'Draft', 'Processing', 'Renewal Pending'], true)
        ) {
            return [
                'status' => 'Renewal Pending',
                'renewal_status' => 'Renewal Pending',
                'statuses' => ['Renewal Pending'],
                'status_detail' => null,
            ];
        }

        if (in_array($rawStatus, ['completed', 'paid', 'success', 'active'], true)) {
            // New renewal order becomes Active once activated; source order shows Renewed.
            return [
                'status' => 'Active',
                'renewal_status' => null,
                'statuses' => ['Active'],
                'status_detail' => null,
            ];
        }

        return [
            'status' => $resolvedStatus,
            'renewal_status' => null,
            'statuses' => [$resolvedStatus],
            'status_detail' => null,
        ];
    }

    /**
     * Order list: completed renewals show Active/Expiring/Expired (not Renewed).
     *
     * @return array{
     *   status: string,
     *   renewal_status: ?string,
     *   statuses: list<string>,
     *   status_detail: ?string
     * }
     */
    private function resolveOrderListStatusDisplay(
        Order $order,
        Carbon $today,
        $orderItems,
        string $resolvedStatus
    ): array {
        if ($this->isRenewalOrderRow($order)) {
            $renewalDisplay = $this->resolveRenewalOrderDisplayStatus($order, $resolvedStatus);
            if (($renewalDisplay['status'] ?? '') === 'Renewal Pending') {
                return $renewalDisplay;
            }
        }

        if (
            $this->isRenewalOrderRow($order)
            && in_array(strtolower(trim((string) ($order->status ?? ''))), ['completed', 'paid', 'success', 'active'], true)
        ) {
            $live = $this->resolveSubscriptionOrderLevelStatus($order, $today, $orderItems, null, true);
            $liveStatus = (string) ($live['status'] ?? 'Active');

            return [
                'status' => $liveStatus,
                'renewal_status' => null,
                'statuses' => [$liveStatus],
                'status_detail' => null,
            ];
        }

        return [
            'status' => $resolvedStatus,
            'renewal_status' => null,
            'statuses' => [$resolvedStatus],
            'status_detail' => null,
        ];
    }

    /**
     * Collapse accidental duplicate order_items on one order (same plan + qty + status).
     * Keeps the latest row id so upgrade links stay stable.
     *
     * @param  \Illuminate\Support\Collection<int, OrderItem>  $orderItems
     * @return \Illuminate\Support\Collection<int, OrderItem>
     */
    private function uniqueSubscriptionOrderItems($orderItems)
    {
        return $orderItems
            ->sortByDesc(fn($item) => (int) ($item->id ?? 0))
            ->unique(function ($item) {
                $status = strtolower(trim((string) ($item->status ?? 'active')));
                if ($status === '') {
                    $status = 'active';
                }

                return implode(':', [
                    (int) ($item->plan_id ?? 0),
                    (int) ($item->quantity ?? 1),
                    $status,
                    round((float) ($item->unit_price ?? 0), 2),
                ]);
            })
            ->sortBy(fn($item) => (int) ($item->id ?? 0))
            ->values();
    }

    private function isLicenseAddOrder($order): bool
    {
        if (!$order) {
            return false;
        }

        $category = strtolower(trim((string) ($order->order_category ?? '')));
        $type = strtolower(trim((string) ($order->order_type ?? '')));
        $parentId = (int) ($order->parent_order_id ?? 0);
        $orderNo = strtoupper(trim((string) ($order->order_no ?? '')));

        // orders.order_category is always 'addon' for license-add (never 'license_add').
        if (in_array($category, ['addon'], true)
            || in_array($type, ['addon'], true)
            || ($parentId > 0 && in_array($category, ['addon'], true))) {
            return true;
        }

        // If it's explicitly a change or renewal order, it's not license add
        if (in_array($category, ['upgrade', 'downgrade', 'renewal', 'renew'], true)
            || str_starts_with($orderNo, 'RN')
            || str_starts_with($orderNo, 'CH')
            || str_starts_with($orderNo, 'UPG')) {
            return false;
        }

        if ($parentId > 0) {
            return true;
        }

        // Check cart if order has cart_id or source_cart_id
        $cartId = (int) ($order->cart_id ?? $order->source_cart_id ?? 0);
        if ($cartId > 0) {
            $cart = Cart::find($cartId);
            if ($cart) {
                $cType = strtolower(trim((string) ($cart->type ?? '')));
                $cItemType = strtolower(trim((string) ($cart->item_type ?? '')));
                $cOrderId = (int) ($cart->order_id ?? 0);
                if (in_array($cType, ['license_add', 'addon'], true)
                    || str_contains($cItemType, 'mode:license_add')
                    || $cOrderId > 0) {
                    return true;
                }
            }
        }

        // Check if there is an active/converted cart for this domain with license_add
        if (!empty($order->domain_name) && (int) ($order->partner_id ?? 0) > 0) {
            $hasAddonCart = Cart::query()
                ->where('partner_id', (int) $order->partner_id)
                ->where('domain_name', (string) $order->domain_name)
                ->where(function ($q) {
                    $q->whereIn('type', ['license_add', 'addon'])
                        ->orWhere('item_type', 'like', '%mode:license_add%');
                })
                ->exists();
            if ($hasAddonCart) {
                $hasOlderParent = Order::query()
                    ->where('partner_id', (int) $order->partner_id)
                    ->where('domain_name', (string) $order->domain_name)
                    ->where(function ($q) {
                        $q->whereNull('parent_order_id')->orWhere('parent_order_id', 0);
                    })
                    ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('draft', 'cancelled', 'canceled', 'failed', 'rejected')")
                    ->exists();
                
                if ($hasOlderParent) {
                    return true;
                }
            }
        }

        return false;
    }

    private function isActivatedLicenseAddStatus($order): bool
    {
        $status = strtolower(trim((string) ($order->status ?? '')));

        // Match order-list merge: only activated addon seats fold into parent.
        return in_array($status, ['completed', 'paid', 'success', 'active'], true);
    }

    /**
     * Activated license-add child orders that belong on the parent subscription.
     *
     * @return \Illuminate\Support\Collection<int, Order>
     */
    private function loadActivatedLicenseAddChildren(int $parentOrderId, $parentOrder = null)
    {
        if ($parentOrderId <= 0) {
            return collect();
        }

        $validStatuses = ['completed', 'paid', 'success', 'active'];
        $validStatusesSql = "'" . implode("','", $validStatuses) . "'";

        // 1. Direct children by parent_order_id (same as orderIndex — no plan_id SQL filter)
        $parent = $parentOrder ?: Order::find($parentOrderId);
        $parentPlanId = (int) ($parent->plan_id ?? 0);
        if ($parentPlanId <= 0 && $parent) {
            $parentPlanId = (int) (OrderItem::query()
                ->where('order_id', $parentOrderId)
                ->where(function ($q) {
                    $q->whereNull('status')
                        ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted')");
                })
                ->orderBy('id')
                ->value('plan_id') ?? 0);
        }

        $children = Order::query()
            ->where('parent_order_id', $parentOrderId)
            ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) IN ($validStatusesSql)")
            ->orderBy('id')
            ->get()
            ->filter(function ($child) use ($parentPlanId) {
                if (!$this->isLicenseAddOrder($child)) {
                    return false;
                }
                // Same plan only when both sides have plan_id (orderIndex merge rule)
                $childPlanId = (int) ($child->plan_id ?? 0);
                if ($parentPlanId > 0 && $childPlanId > 0 && $childPlanId !== $parentPlanId) {
                    // Still keep if child order_items have the parent plan
                    return OrderItem::query()
                        ->where('order_id', (int) $child->id)
                        ->where('plan_id', $parentPlanId)
                        ->where(function ($q) {
                            $q->whereNull('status')
                                ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted')");
                        })
                        ->exists();
                }

                return true;
            });

        // 2. Also check by partner_id + domain_name if parent order exists
        if ($parent && !empty($parent->domain_name) && !empty($parent->partner_id)) {
            $candidateOrders = Order::query()
                ->where('partner_id', $parent->partner_id)
                ->where('domain_name', $parent->domain_name)
                ->where('id', '!=', $parentOrderId)
                ->where(function ($q) use ($parentOrderId) {
                    $q->whereNull('parent_order_id')
                        ->orWhere('parent_order_id', 0)
                        ->orWhere('parent_order_id', $parentOrderId);
                })
                ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) IN ($validStatusesSql)")
                ->whereRaw("LOWER(TRIM(COALESCE(order_category, ''))) NOT IN ('renewal', 'renew', 'renewed', 'downgrade', 'downgraded')")
                ->orderBy('id')
                ->get();

            $unlinkedAddons = collect();
            foreach ($candidateOrders as $cand) {
                if (!$this->isLicenseAddOrder($cand)) {
                    continue;
                }
                $candPlanId = (int) ($cand->plan_id ?? 0);
                $planOk = $parentPlanId <= 0
                    || $candPlanId <= 0
                    || $candPlanId === $parentPlanId
                    || OrderItem::query()
                        ->where('order_id', (int) $cand->id)
                        ->where('plan_id', $parentPlanId)
                        ->where(function ($q) {
                            $q->whereNull('status')
                                ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted')");
                        })
                        ->exists();
                if (!$planOk) {
                    continue;
                }
                if (empty($cand->parent_order_id)) {
                    Order::where('id', $cand->id)->update([
                        'parent_order_id' => $parentOrderId,
                        'order_category' => 'addon',
                    ]);
                    $cand->parent_order_id = $parentOrderId;
                    $cand->order_category = 'addon';
                }
                $unlinkedAddons->push($cand);
            }

            $children = $children->concat($unlinkedAddons)->unique('id')->values();
        }

        return $children->values();
    }

    /**
     * Upgrade / partial upgrade seat count: original line qty plus activated license-add qty.
     * 
     * @return array{old_total_licenses:int,new_total_licenses:int,current_licenses:int}
     */
    private function resolveUpgradeLicenseTotals($sourceOrder, $sourceItem = null): array
    {
        $oldTotal = 0;
        if ($sourceItem) {
            $oldTotal = (int) ($sourceItem->quantity ?? $sourceItem->licenses ?? $sourceItem->license_count ?? 0);
            // Also check the order's quantity as fallback
            if ($oldTotal <= 0 && $sourceOrder) {
                $oldTotal = (int) ($sourceOrder->quantity ?? 0);
            }
        } elseif ($sourceOrder) {
            $oldTotal = (int) ($sourceOrder->quantity ?? 0);
        }

        // If oldTotal is still 0, default to 1
        if ($oldTotal <= 0) {
            $oldTotal = 1;
        }

        $newTotal = 0;
        $parentOrderId = (int) ($sourceOrder->id ?? 0);
        $planId = (int) ($sourceItem->plan_id ?? $sourceOrder->plan_id ?? 0);

        // Get activated license-add children for the same plan
        if ($parentOrderId > 0 && $planId > 0) {
            $children = $this->loadActivatedLicenseAddChildren($parentOrderId, $sourceOrder);

            foreach ($children as $child) {
                // Get child items for this specific plan
                $childItems = OrderItem::query()
                    ->where('order_id', (int) $child->id)
                    ->where('plan_id', $planId)
                    ->where(function ($q) {
                        $q->whereNull('status')
                            ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted')");
                    })
                    ->get();

                if ($childItems->isNotEmpty()) {
                    foreach ($childItems as $childItem) {
                        $childQty = (int) ($childItem->quantity ?? $childItem->licenses ?? 1);
                        $newTotal += $childQty;
                    }
                } else {
                    $newTotal += max(1, (int) ($child->quantity ?? $child->licenses ?? 1));
                }
            }
        }

        // Total = original + all license-add additions
        $current = $oldTotal + $newTotal;

        // Ensure we have at least 1
        if ($current <= 0) {
            $current = 1;
        }

        return [
            'old_total_licenses' => $oldTotal,
            'new_total_licenses' => $newTotal,
            'current_licenses' => $current,
        ];
    }

    /**
     * Display-only: add activated license-add quantities onto the matching parent plan.
     * Matches orderIndex total licenses. Does not write to the database.
     *
     * @param  \Illuminate\Support\Collection<int, OrderItem>  $orderItems
     * @param  \Illuminate\Support\Collection<int, Order>  $childOrders
     * @return \Illuminate\Support\Collection<int, OrderItem>
     */
    private function mergeLicenseAddItemsIntoParentItems($orderItems, $childOrders)
    {
        $orderItems = collect($orderItems)->values();
        $childOrders = collect($childOrders);
        if ($childOrders->isEmpty()) {
            return $orderItems;
        }

        // Same as orderIndex: resolve parent plan from order items when needed.
        $parentPlanId = 0;
        foreach ($orderItems as $item) {
            $pid = (int) ($item->plan_id ?? 0);
            if ($pid > 0) {
                $parentPlanId = $pid;
                break;
            }
        }

        $childOrdersById = $childOrders->keyBy(fn($o) => (int) $o->id);
        $mergedChildOrderIds = [];

        $childItems = OrderItem::query()
            ->whereIn('order_id', $childOrders->pluck('id')->all())
            ->where(function ($q) {
                $q->whereNull('status')
                    ->orWhereRaw("LOWER(TRIM(COALESCE(status, ''))) NOT IN ('delete', 'deleted')");
            })
            ->orderBy('id')
            ->get();

        foreach ($childItems as $childItem) {
            $itemPlanId = (int) ($childItem->plan_id ?? 0);
            $childOrder = $childOrdersById->get((int) ($childItem->order_id ?? 0));
            $childOrderPlanId = (int) ($childOrder->plan_id ?? 0);

            // Only seats for the same plan_id (orderIndex behavior)
            if ($itemPlanId > 0 && $parentPlanId > 0 && $itemPlanId !== $parentPlanId) {
                continue;
            }
            if (
                $itemPlanId <= 0
                && $childOrderPlanId > 0
                && $parentPlanId > 0
                && $childOrderPlanId !== $parentPlanId
            ) {
                continue;
            }

            $addQty = max(1, (int) ($childItem->quantity ?? 1));
            $matchIndex = $orderItems->search(function ($item) use ($itemPlanId, $parentPlanId, $childOrderPlanId) {
                $status = strtolower(trim((string) ($item->status ?? 'active')));
                if ($status === '') {
                    $status = 'active';
                }
                if (in_array($status, ['delete', 'deleted', 'upgraded', 'downgraded', 'renewed'], true)) {
                    return false;
                }

                $pid = (int) ($item->plan_id ?? 0);
                // Child item has plan_id → match exact plan line
                if ($itemPlanId > 0) {
                    return $pid === $itemPlanId;
                }
                // Child item plan_id missing → fall back to child/parent order plan (orderIndex)
                $fallbackPlan = $childOrderPlanId > 0 ? $childOrderPlanId : $parentPlanId;

                return $fallbackPlan > 0 && $pid === $fallbackPlan;
            });

            if ($matchIndex !== false) {
                $parentItem = clone $orderItems[$matchIndex];
                $parentItem->quantity = (int) ($parentItem->quantity ?? 1) + $addQty;
                $orderItems[$matchIndex] = $parentItem;
                $mergedChildOrderIds[(int) ($childItem->order_id ?? 0)] = true;
            }
        }

        // Fallback for children without OrderItem rows, or items that never matched a parent line
        foreach ($childOrders as $childOrder) {
            $childOrderId = (int) ($childOrder->id ?? 0);
            if (isset($mergedChildOrderIds[$childOrderId])) {
                continue;
            }

            $planId = (int) ($childOrder->plan_id ?? 0);
            if ($planId <= 0) {
                $planId = $parentPlanId;
            }
            if ($planId <= 0 || ($parentPlanId > 0 && $planId !== $parentPlanId)) {
                continue;
            }

            $addQty = max(1, (int) ($childOrder->quantity ?? $childOrder->licenses ?? 1));
            $matchIndex = $orderItems->search(function ($item) use ($planId) {
                $status = strtolower(trim((string) ($item->status ?? 'active')));
                if ($status === '') {
                    $status = 'active';
                }

                return (int) ($item->plan_id ?? 0) === $planId
                    && !in_array($status, ['delete', 'deleted', 'upgraded', 'downgraded', 'renewed'], true);
            });

            if ($matchIndex !== false) {
                $parentItem = clone $orderItems[$matchIndex];
                $parentItem->quantity = (int) ($parentItem->quantity ?? 1) + $addQty;
                $orderItems[$matchIndex] = $parentItem;
            }
        }

        return $orderItems->values();
    }

    /**
     * Final safety net for API cards that look identical in the UI.
     *
     * @param  list<array<string, mixed>>  $plansInfo
     * @return list<array<string, mixed>>
     */
    private function dedupeSubscriptionPlansInfo(array $plansInfo): array
    {
        $seen = [];
        $out = [];

        foreach ($plansInfo as $plan) {
            $key = implode('|', [
                (int) ($plan['plan_id'] ?? 0),
                (int) ($plan['licenses'] ?? 0),
                strtolower(trim((string) ($plan['status'] ?? ''))),
                strtolower(trim((string) ($plan['item_status'] ?? ''))),
                strtolower(trim((string) ($plan['plan_change_status'] ?? ''))),
                (string) ($plan['domain'] ?? ''),
                (string) ($plan['subscription_start_date'] ?? ''),
                (string) ($plan['subscription_end_date'] ?? ''),
                (int) ($plan['change_order_id'] ?? 0),
            ]);

            if (isset($seen[$key])) {
                continue;
            }

            $seen[$key] = true;
            $out[] = $plan;
        }

        return $out;
    }

    /**
     * Upgrade pro-rata aligned with super-admin update_plan:
     * remaining value = (current_unit_price / 365) × remaining_days × min(upgrade_qty, current_licenses).
     * pro_rata_adjustment / remaining_credit / remaining_value show the full remaining value.
     * Taxable/payable apply min(remaining_value, new_plan_cost).
     */
    private function resolveUpgradeProration(
        ?Order $sourceOrder,
        ?OrderItem $sourceItem,
        float $newUnitPrice,
        int $upgradeLicenses,
        float $gstRate = 18.0,
        float $couponPercent = 0.0,
        ?int $newPlanId = null,
        ?int $currentLicensesOverride = null
    ): array {
        return app(UpgradeProrationService::class)->resolve(
            $sourceOrder,
            $sourceItem,
            $newUnitPrice,
            $upgradeLicenses,
            $gstRate,
            $couponPercent,
            $newPlanId,
            $currentLicensesOverride
        );
    }

    private function resolveLicenseAddProration(
        ?Order $sourceOrder,
        ?OrderItem $sourceItem,
        float $unitPrice,
        int $extraLicenses,
        float $gstRate = 18.0,
        float $couponPercent = 0.0
    ): array {
        return app(UpgradeProrationService::class)->resolveLicenseAdd(
            $sourceOrder,
            $sourceItem,
            $unitPrice,
            $extraLicenses,
            $gstRate,
            $couponPercent
        );
    }

    /**
     * Map order_id â†’ partner-facing refund label for cancelled paid invoices.
     *
     * @param  array<int, int>  $orderIds
     * @return array<int, string|null>
     */
    private function buildInvoiceRefundStatusByOrderId(array $orderIds): array
    {
        $orderIds = array_values(array_unique(array_filter(array_map('intval', $orderIds))));
        if ($orderIds === []) {
            return [];
        }

        $map = [];
        $applyRefundStatus = function (int $oid, string $st) use (&$map): void {
            if ($oid <= 0 || array_key_exists($oid, $map)) {
                return;
            }
            $st = strtolower(trim($st));
            if (in_array($st, [
                PaymentRefund::STATUS_PROCESSED,
                PaymentRefund::STATUS_PENDING,
                PaymentRefund::STATUS_PROCESSING,
                PaymentRefund::STATUS_FAILED,
            ], true)) {
                // Bank credit still takes a few days after Razorpay accepts the refund.
                $map[$oid] = 'Refund Soon';
            }
        };

        try {
            $rows = PaymentRefund::query()
                ->whereIn('order_id', $orderIds)
                ->orderByDesc('id')
                ->get(['order_id', 'status']);

            foreach ($rows as $row) {
                $applyRefundStatus((int) ($row->order_id ?? 0), (string) ($row->status ?? ''));
            }

            // Invoice-page Razorpay payments may store refunds on the transaction
            // without order_id (older rows) â€” map via invoice â†’ order.
            $invoiceOrderMap = InvoiceMst::query()
                ->whereIn('order_id', $orderIds)
                ->pluck('order_id', 'id');
            $invoiceIds = $invoiceOrderMap->keys()->map(fn($id) => (int) $id)->all();
            if ($invoiceIds !== []) {
                $txnToInvoice = \App\Models\InvoicePaymentTransactionItem::query()
                    ->whereIn('invoice_id', $invoiceIds)
                    ->get(['invoice_payment_transaction_id', 'invoice_id']);

                $txnIds = $txnToInvoice
                    ->pluck('invoice_payment_transaction_id')
                    ->map(fn($id) => (int) $id)
                    ->unique()
                    ->filter(fn($id) => $id > 0)
                    ->values()
                    ->all();

                if ($txnIds !== []) {
                    $txnRefunds = PaymentRefund::query()
                        ->whereIn('invoice_payment_transaction_id', $txnIds)
                        ->orderByDesc('id')
                        ->get(['invoice_payment_transaction_id', 'status']);

                    $invoiceByTxn = [];
                    foreach ($txnToInvoice as $item) {
                        $tid = (int) $item->invoice_payment_transaction_id;
                        if ($tid > 0 && !isset($invoiceByTxn[$tid])) {
                            $invoiceByTxn[$tid] = (int) $item->invoice_id;
                        }
                    }

                    foreach ($txnRefunds as $row) {
                        $tid = (int) ($row->invoice_payment_transaction_id ?? 0);
                        $invoiceId = $invoiceByTxn[$tid] ?? 0;
                        $oid = (int) ($invoiceOrderMap[$invoiceId] ?? 0);
                        $applyRefundStatus($oid, (string) ($row->status ?? ''));
                    }
                }
            }
        } catch (\Throwable $e) {
            return $map;
        }

        return $map;
    }

    /**
     * Invoice IDs that had a successful online (or recorded) payment.
     *
     * @param  array<int, int>  $invoiceIds
     * @return array<int, true>
     */
    private function buildPaidInvoiceIdSet(array $invoiceIds): array
    {
        $invoiceIds = array_values(array_unique(array_filter(array_map('intval', $invoiceIds))));
        if ($invoiceIds === []) {
            return [];
        }

        $paid = [];
        try {
            $txnIds = \App\Models\InvoicePaymentTransactionItem::query()
                ->whereIn('invoice_id', $invoiceIds)
                ->pluck('invoice_payment_transaction_id')
                ->map(fn($id) => (int) $id)
                ->unique()
                ->filter(fn($id) => $id > 0)
                ->values()
                ->all();

            if ($txnIds === []) {
                return [];
            }

            $successTxnIds = \App\Models\InvoicePaymentTransaction::query()
                ->whereIn('id', $txnIds)
                ->whereRaw("LOWER(TRIM(COALESCE(status, ''))) IN ('success', 'paid', 'captured', 'completed')")
                ->pluck('id')
                ->map(fn($id) => (int) $id)
                ->all();

            if ($successTxnIds === []) {
                return [];
            }

            $linked = \App\Models\InvoicePaymentTransactionItem::query()
                ->whereIn('invoice_payment_transaction_id', $successTxnIds)
                ->whereIn('invoice_id', $invoiceIds)
                ->pluck('invoice_id');

            foreach ($linked as $id) {
                $paid[(int) $id] = true;
            }
        } catch (\Throwable $e) {
            return [];
        }

        return $paid;
    }

    /**
     * Partner invoice list/detail display: Cancelled + Refund Soon after paid cancel.
     *
     * @return array{status: string, refund_status: string|null, can_pay: bool}
     */
    private function resolvePartnerInvoiceDisplayStatus(
        object $invoice,
        mixed $order,
        ?string $refundStatusFromRefunds,
        bool $hasSuccessfulPaymentTxn = false
    ): array {
        $rawInvoice = strtolower(trim((string) ($invoice->status ?? 'pending')));
        $orderStatus = strtolower(trim((string) ($order->status ?? '')));
        $orderCancelled = in_array($orderStatus, ['rejected', 'cancelled', 'canceled', 'failed', 'void'], true);
        $invoiceCancelled = in_array($rawInvoice, ['cancelled', 'canceled', 'rejected', 'void'], true);

        $creditUsed = (float) ($order->credit_used ?? 0);
        $orderPaymentStatus = strtolower(trim((string) ($order->payment_status ?? $order->payment_state ?? '')));
        $wasPaid = in_array($rawInvoice, ['paid', 'success', 'completed', 'succeeded'], true)
            || $hasSuccessfulPaymentTxn
            || $refundStatusFromRefunds !== null
            || trim((string) ($order->razorpay_payment_id ?? '')) !== ''
            || $creditUsed > 0.009
            || in_array($orderPaymentStatus, ['paid', 'success', 'completed', 'captured', 'succeeded'], true);

        if ($orderCancelled || $invoiceCancelled) {
            $refundStatus = $refundStatusFromRefunds;
            // Any payment before cancel (Razorpay / wallet credit / txn) â†’ show refund key.
            if ($refundStatus === null && $wasPaid) {
                $refundStatus = 'Refund Soon';
            }

            return [
                'status' => 'Cancelled',
                'refund_status' => $refundStatus,
                'can_pay' => false,
            ];
        }

        $invoiceSettled = in_array($rawInvoice, ['paid', 'success', 'completed', 'succeeded'], true)
            || $hasSuccessfulPaymentTxn
            || trim((string) ($order->razorpay_payment_id ?? '')) !== ''
            || in_array($orderPaymentStatus, ['paid', 'success', 'completed', 'captured', 'succeeded'], true)
            || ($order && strtolower(trim((string) ($order->status ?? ''))) === 'paid');

        if ($invoiceSettled) {
            $this->healPaidInvoiceStatusIfNeeded($invoice, $hasSuccessfulPaymentTxn, $order);

            return [
                'status' => 'Paid',
                'refund_status' => null,
                'can_pay' => false,
            ];
        }

        $label = ucfirst($rawInvoice !== '' ? $rawInvoice : 'pending');
        if (in_array($label, ['Unpaid', 'Failed'], true)) {
            $label = 'Pending';
        }

        return [
            'status' => $label,
            'refund_status' => null,
            'can_pay' => in_array($label, ['Pending', 'Unpaid', 'Overdue', 'Failed'], true),
        ];
    }

    /**
     * Payment succeeded but invoice_mst.status was left pending — sync once for list/detail APIs.
     */
    private function healPaidInvoiceStatusIfNeeded(object $invoice, bool $hasSuccessfulPaymentTxn, mixed $order): void
    {
        $rawInvoice = strtolower(trim((string) ($invoice->status ?? 'pending')));
        if (in_array($rawInvoice, ['paid', 'success', 'completed', 'succeeded'], true)) {
            return;
        }

        $settled = $hasSuccessfulPaymentTxn
            || trim((string) ($order->razorpay_payment_id ?? '')) !== ''
            || ($order && strtolower(trim((string) ($order->status ?? ''))) === 'paid');
        if (!$settled) {
            return;
        }

        $invoiceId = (int) ($invoice->id ?? 0);
        if ($invoiceId <= 0) {
            return;
        }

        try {
            InvoiceMst::query()->whereKey($invoiceId)->update([
                'status' => 'paid',
                'updated_at' => now(),
            ]);
        } catch (\Throwable $e) {
            Log::warning('healPaidInvoiceStatusIfNeeded failed', [
                'invoice_id' => $invoiceId,
                'error' => $e->getMessage(),
            ]);
        }
    }


    private function applyPaymentLinkRetryToInvoiceRow(array $display, ?Order $order, ?array $sharedPartnerGate = null): array
    {
        $defaults = [
            'payment_link_expired' => false,
            'payment_link_allowed' => $display['can_pay'] ?? false,
            'failed_payment_attempts' => 0,
            'remaining_attempts' => Order::PAYMENT_LINK_MAX_ATTEMPTS,
            'remaining_hrs' => 0,
            'payment_link_expires_at' => null,
            'payment_link_message' => null,
            'payment_retry' => [
                'payment_link_expired' => false,
                'payment_link_allowed' => $display['can_pay'] ?? false,
                'failed_payment_attempts' => 0,
                'remaining_attempts' => Order::PAYMENT_LINK_MAX_ATTEMPTS,
                'remaining_hrs' => 0,
                'payment_link_expires_at' => null,
                'payment_link_message' => null,
            ],
        ];

        $status = (string) ($display['status'] ?? '');
        $payableLabels = ['Pending', 'Unpaid', 'Overdue', 'Failed'];
        $isPayableStatus = in_array($status, $payableLabels, true);

        // Billing list path: use shared partner attempts only (no per-order DB writes).
        if (is_array($sharedPartnerGate)) {
            $failed = (int) ($sharedPartnerGate['failed_payment_attempts'] ?? 0);
            $remaining = (int) ($sharedPartnerGate['remaining_attempts'] ?? Order::PAYMENT_LINK_MAX_ATTEMPTS);
            $hrs = (int) ($sharedPartnerGate['remaining_hrs'] ?? 0);
            $partnerLocked = !empty($sharedPartnerGate['payment_link_expired']);
            $message = $sharedPartnerGate['payment_link_message'] ?? null;
            $expiresAt = $sharedPartnerGate['payment_link_expires_at'] ?? null;

            // Optional per-order 24h window label (read-only from order_note).
            if ($order instanceof Order) {
                try {
                    $meta = $order->paymentRetryMeta();
                    if (!empty($meta['expires_at'])) {
                        $expiresAt = \Carbon\Carbon::parse((string) $meta['expires_at'])
                            ->timezone('Asia/Kolkata')
                            ->format('d-m-Y, h:i A') . ' IST';
                    }
                } catch (\Throwable) {
                    // keep partner expiresAt
                }
            }

            $linkExpired = $partnerLocked;
            $linkAllowed = !$linkExpired && $remaining > 0 && $isPayableStatus;

            if ($status === 'Paid' || ($order instanceof Order && $order->isPaymentLinkPaid())) {
                $linkAllowed = false;
                $linkExpired = false;
                $display['can_pay'] = false;
            } elseif ($status === 'Cancelled') {
                $display['can_pay'] = false;
                $linkAllowed = false;
            } elseif ($isPayableStatus) {
                $display['can_pay'] = $linkAllowed;
            } else {
                $display['can_pay'] = false;
                $linkAllowed = false;
            }

            if (!$message) {
                $message = sprintf(
                    'You have %d payment attempt(s) remaining across all invoices.',
                    $remaining
                );
                if ($expiresAt) {
                    $message .= ' Link expires ' . $expiresAt . '.';
                }
            }

            $retry = [
                'payment_link_expired' => $linkExpired,
                'payment_link_allowed' => $linkAllowed,
                'failed_payment_attempts' => $failed,
                'remaining_attempts' => $partnerLocked ? 0 : $remaining,
                'remaining_hrs' => $hrs,
                'payment_link_expires_at' => $expiresAt,
                'payment_link_message' => $message,
            ];

            return array_merge($display, [
                'payment_link_expired' => $linkExpired,
                'payment_link_allowed' => $linkAllowed,
                'failed_payment_attempts' => $failed,
                'remaining_attempts' => $partnerLocked ? 0 : $remaining,
                'remaining_hrs' => $hrs,
                'payment_link_expires_at' => $expiresAt,
                'payment_link_message' => $message,
                'payment_retry' => $retry,
            ]);
        }

        if (!$order instanceof Order) {
            return array_merge($display, $defaults);
        }

        // Already settled online — never reopen payment link.
        if ($order->isPaymentLinkPaid() || $status === 'Paid') {
            $failed = 0;
            $remaining = Order::PAYMENT_LINK_MAX_ATTEMPTS;

            $retry = [
                'payment_link_expired' => false,
                'payment_link_allowed' => false,
                'failed_payment_attempts' => $failed,
                'remaining_attempts' => $remaining,
                'remaining_hrs' => 0,
                'payment_link_expires_at' => null,
                'payment_link_message' => 'This order is already paid.',
            ];

            $display['can_pay'] = false;

            return array_merge($display, [
                'payment_link_expired' => false,
                'payment_link_allowed' => false,
                'failed_payment_attempts' => $failed,
                'remaining_attempts' => $remaining,
                'remaining_hrs' => 0,
                'payment_link_expires_at' => null,
                'payment_link_message' => 'This order is already paid.',
                'payment_retry' => $retry,
            ]);
        }

        try {
            $retry = $order->paymentLinkRetryForApi();
        } catch (\Throwable $e) {
            \Illuminate\Support\Facades\Log::warning('invoice_row_payment_retry_failed', [
                'order_id' => (int) ($order->id ?? 0),
                'error' => $e->getMessage(),
            ]);

            return array_merge($display, $defaults);
        }

        $linkAllowed = (bool) ($retry['payment_link_allowed'] ?? false);
        $linkExpired = (bool) ($retry['payment_link_expired'] ?? false);

        if ($status === 'Cancelled') {
            $onlinePaid = trim((string) ($order->razorpay_payment_id ?? '')) !== '';
            if ($onlinePaid) {
                $linkAllowed = false;
            }
            $display['can_pay'] = $linkAllowed;
        } elseif ($isPayableStatus) {
            $display['can_pay'] = !($linkExpired || !$linkAllowed);
            if ($linkExpired || !$linkAllowed) {
                $display['can_pay'] = false;
            } else {
                $display['can_pay'] = true;
            }
        } else {
            $display['can_pay'] = false;
            $linkAllowed = false;
        }

        if (in_array($status, ['Failed', 'Payment Link Expired'], true) && $linkAllowed) {
            $display['status'] = 'Pending';
        }

        return array_merge($display, [
            'payment_link_expired' => $linkExpired,
            'payment_link_allowed' => $linkAllowed,
            'total_payment_attempts' => Order::PAYMENT_LINK_MAX_ATTEMPTS,
            'failed_payment_attempts' => (int) ($retry['failed_payment_attempts'] ?? 0),
            'successful_payment_attempts' => $order && $order->isPaymentLinkPaid() ? 1 : 0,
            'remaining_attempts' => (int) ($retry['remaining_attempts'] ?? Order::PAYMENT_LINK_MAX_ATTEMPTS),
            'remaining_hrs' => (int) ($retry['remaining_hrs'] ?? 0),
            'payment_link_expires_at' => $retry['payment_link_expires_at'] ?? null,
            'payment_link_message' => $retry['payment_link_message'] ?? null,
            'payment_retry' => $retry,
        ]);
    }

    /**
     * @param  array<int, int>  $orderIds
     * @return array<int, string>
     */
    private function buildOrderInvoiceLinks(array $orderIds): array
    {
        if ($orderIds === []) {
            return [];
        }

        $billing = app(BillingController::class);
        $linksByOrderId = [];

        foreach ($orderIds as $orderId) {
            $orderId = (int) $orderId;
            if ($orderId <= 0) {
                continue;
            }

            try {
                // PERF: reuse the stored invoice PDF; it is only rendered when the file does not exist yet
                // (force=true re-rendered every order's PDF on each list request → ~25s responses).
                $invoiceLink = '';
                if (method_exists($billing, 'persistOrderInvoicePdfToStorage')) {
                    $persisted = $billing->persistOrderInvoicePdfToStorage($orderId, false);
                    $invoiceLink = trim((string) ($persisted['public_url'] ?? ''));
                }

                if ($invoiceLink === '' && method_exists($billing, 'getOrderDocumentLinks')) {
                    $links = (array) $billing->getOrderDocumentLinks($orderId);
                    $invoiceLink = trim((string) ($links['invoice_link'] ?? $links['e_invoice_link'] ?? ''));
                }

                if ($invoiceLink === '') {
                    $invoiceLink = url('/superadmin/orders-invoice/' . $orderId);
                }

                if ($invoiceLink !== '' && !$this->isCreditNoteDocumentRef($invoiceLink)) {
                    $linksByOrderId[$orderId] = $this->normalizePublicDocumentUrl($invoiceLink);
                }
            } catch (\Throwable $e) {
                Log::warning('b2bBilling: failed to resolve invoice document link', [
                    'order_id' => $orderId,
                    'error' => $e->getMessage(),
                ]);
                $linksByOrderId[$orderId] = $this->normalizePublicDocumentUrl(
                    url('/superadmin/orders-invoice/' . $orderId)
                );
            }
        }

        return $linksByOrderId;
    }

    private function resolveInvoicePdfUrl(object $invoice, ?int $orderId = null, array $orderInvoiceLinks = []): ?string
    {
        if ($orderId && !empty($orderInvoiceLinks[$orderId])) {
            $linked = (string) $orderInvoiceLinks[$orderId];
            if (!$this->isCreditNoteDocumentRef($linked)) {
                return $linked;
            }
        }

        foreach (
            [
                $invoice->invoice_pdf_url ?? null,
                $invoice->pdf_url ?? null,
                $invoice->invoice_link ?? null,
                $invoice->e_invoice_pdf_url ?? null,
                $invoice->e_invoice_link ?? null,
                $invoice->signed_invoice_url ?? null,
                $invoice->invoice_path ?? null,
            ] as $candidate
        ) {
            $candidate = trim((string) $candidate);
            if ($candidate === '' || $this->isCreditNoteDocumentRef($candidate)) {
                continue;
            }

            return $this->normalizePublicDocumentUrl($candidate);
        }

        if ($orderId && $orderId > 0) {
            return $this->normalizePublicDocumentUrl(url('/superadmin/orders-invoice/' . $orderId));
        }

        return null;
    }

    private function isCreditNoteDocumentRef(?string $value): bool
    {
        $value = strtoupper(trim((string) $value));
        if ($value === '') {
            return false;
        }

        $file = basename(parse_url($value, PHP_URL_PATH) ?: $value);

        return str_starts_with($value, 'CN/')
            || str_starts_with($value, 'CN-')
            || str_starts_with($file, 'CN')
            || str_contains($value, '/CREDIT-NOTES/')
            || str_contains($value, '/CREDIT_NOTES/');
    }

    private function normalizePublicDocumentUrl(string $url): string
    {
        $url = trim($url);
        if ($url === '') {
            return $url;
        }

        if (preg_match('/^https?:\/\//i', $url)) {
            return $url;
        }

        if (str_starts_with($url, '/')) {
            return url($url);
        }

        return url('/' . ltrim($url, '/'));
    }


    public function updateProfile(Request $request)
    {
        $request->validate([
            'partner_id' => ['required', 'integer', 'exists:pgsql_auth.partners,id'],
            'name' => ['required', 'string', 'max:255'],
            'mobile' => ['required', 'string', 'max:15'],
            'email' => ['required', 'email', 'max:255'],
        ]);

        $partner = Partner::query()->whereKey((int) $request->partner_id)->first();
        if (!$partner) {
            return response()->json([
                'success' => false,
                'message' => 'Partner not found.',
            ], 404);
        }

        $emailExists = Partner::query()
            ->where('email', $request->email)
            ->where('id', '!=', $partner->id)
            ->exists();
        if ($emailExists) {
            return response()->json([
                'success' => false,
                'message' => 'Email already used by another partner.',
            ], 422);
        }

        $mobileExists = Partner::query()
            ->where('mobile', $request->mobile)
            ->where('id', '!=', $partner->id)
            ->exists();
        if ($mobileExists) {
            return response()->json([
                'success' => false,
                'message' => 'Mobile already used by another partner.',
            ], 422);
        }

        $partner->name = $request->name;
        $partner->mobile = $request->mobile;
        $partner->email = $request->email;
        $partner->save();

        return response()->json([
            'success' => true,
            'message' => 'Profile updated successfully.',
            'data' => [
                'partner_id' => (int) $partner->id,
                'name' => (string) $partner->name,
                'mobile' => (string) $partner->mobile,
                'email' => (string) $partner->email,
            ],
        ], 200);
    }
    public function revenueHistory(Request $request)
    {
        $request->validate([
            'partner_id' => ['required', 'integer', 'exists:pgsql_auth.partners,id'],
        ]);

        $partnerId = (int) $request->partner_id;
        $partner = Partner::find($partnerId);
        if (!$partner) {
            return response()->json([
                'success' => false,
                'message' => 'Partner not found.',
            ], 404);
        }

        $paidStatuses = ['completed', 'success', 'paid', 'active', 'delivered'];

        $orders = Order::query()
            ->where('partner_id', $partnerId)
            ->whereRaw("LOWER(COALESCE(order_type, '')) = 'b2b'")
            ->whereIn(DB::raw('LOWER(status)'), $paidStatuses)
            ->get(['id', 'total_amount', 'subtotal', 'credit_used', 'order_category', 'status', 'created_at']);

        $amountOf = static function ($order): float {
            $amount = round((float) ($order->total_amount ?? 0), 2);
            if ($amount <= 0) {
                $amount = round((float) ($order->subtotal ?? 0), 2);
            }
            return $amount;
        };

        $totalRevenue = 0.0;
        $thisMonth = 0.0;
        $lastMonth = 0.0;
        $newOrders = 0.0;
        $renewals = 0.0;
        $upgrades = 0.0;
        $creditsUsed = 0.0;
        $paymentsReceived = 0.0;
        $outstanding = 0.0;

        $monthStart = Carbon::now()->startOfMonth();
        $lastMonthStart = Carbon::now()->subMonth()->startOfMonth();
        $lastMonthEnd = Carbon::now()->subMonth()->endOfMonth();

        $overviewMap = [];
        for ($i = 5; $i >= 0; $i--) {
            $key = Carbon::now()->subMonths($i)->format('Y-m');
            $overviewMap[$key] = [
                'month' => Carbon::now()->subMonths($i)->format('M'),
                'amount' => 0.0,
            ];
        }

        foreach ($orders as $order) {
            $amount = $amountOf($order);
            $created = $order->created_at ? Carbon::parse($order->created_at) : null;
            $category = strtolower(trim((string) ($order->order_category ?? 'new')));
            $status = strtolower(trim((string) ($order->status ?? '')));

            $totalRevenue += $amount;
            $creditsUsed += round((float) ($order->credit_used ?? 0), 2);

            if (in_array($status, ['completed', 'success', 'paid', 'active', 'delivered'], true)) {
                $paymentsReceived += $amount;
            }

            if ($created && $created->gte($monthStart)) {
                $thisMonth += $amount;
            }
            if ($created && $created->between($lastMonthStart, $lastMonthEnd)) {
                $lastMonth += $amount;
            }

            if (in_array($category, ['renewal', 'renew', 'renewed'], true)) {
                $renewals += $amount;
            } elseif (in_array($category, ['upgrade', 'upgraded'], true)) {
                $upgrades += $amount;
            } else {
                $newOrders += $amount;
            }

            if ($created) {
                $key = $created->format('Y-m');
                if (isset($overviewMap[$key])) {
                    $overviewMap[$key]['amount'] += $amount;
                }
            }
        }

        $pendingOrders = Order::query()
            ->where('partner_id', $partnerId)
            ->whereRaw("LOWER(COALESCE(order_type, '')) = 'b2b'")
            ->whereRaw("LOWER(status) = 'processing'")
            ->get(['total_amount', 'subtotal']);

        foreach ($pendingOrders as $order) {
            $outstanding += $amountOf($order);
        }

        $growthPercent = 0.0;
        if ($lastMonth > 0) {
            $growthPercent = round((($thisMonth - $lastMonth) / $lastMonth) * 100, 2);
        } elseif ($thisMonth > 0) {
            $growthPercent = 100.0;
        }

        $overview = [];
        foreach ($overviewMap as $row) {
            $overview[] = [
                'month' => $row['month'],
                'amount' => round($row['amount'], 2),
            ];
        }

        return response()->json([
            'success' => true,
            'message' => 'Revenue history fetched successfully.',
            'data' => [
                'partner_id' => $partnerId,
                'total_revenue' => round($totalRevenue, 2),
                'this_month' => round($thisMonth, 2),
                'last_month' => round($lastMonth, 2),
                'growth_percent' => $growthPercent,
                'revenue_overview' => $overview,
                'revenue_breakdown' => [
                    'new_orders' => round($newOrders, 2),
                    'renewals' => round($renewals, 2),
                    'upgrades' => round($upgrades, 2),
                ],
                'payment_status' => [
                    'credits_used' => round($creditsUsed, 2),
                    'payments_received' => round($paymentsReceived, 2),
                    'outstanding_amount' => round($outstanding, 2),
                ],
            ],
        ], 200);
    }

    public function getPartnerUserManagement(Request $request)
    {
        $request->validate([
            'partner_id' => ['required', 'integer', 'exists:pgsql_auth.partners,id'],
            'partner_user_id' => ['required', 'integer'],
        ]);

        $user = PartnerUser::query()
            ->where('partner_id', (int) $request->partner_id)
            ->whereKey((int) $request->partner_user_id)
            ->first();

        if (!$user) {
            return response()->json([
                'success' => false,
                'message' => 'Partner user not found.',
            ], 404);
        }

        $permissions = $this->mapPartnerModulePermissions(
            PartnerPermission::query()
                ->where('partner_user_id', $user->id)
                ->get()
                ->keyBy('module_key')
        );

        return response()->json([
            'success' => true,
            'message' => 'Partner user management details fetched successfully.',
            'data' => [
                'partner_id' => (int) $user->partner_id,
                'partner_user_id' => (int) $user->id,
                'name' => (string) ($user->name ?? ''),
                'email' => (string) ($user->email ?? ''),
                'mobile' => (string) ($user->mobile ?? ''),
                'employee_id' => (string) ($user->employee_id ?? ''),
                'designation' => (string) ($user->designation ?? ''),
                'status' => (string) ($user->status ?? 'active'),
                'last_login' => $user->last_login_at
                    ? Carbon::parse($user->last_login_at)->format('d M Y, h:i A')
                    : null,
                'permissions' => $permissions,
            ],
        ], 200);
    }

    public function updatePartnerUserManagement(Request $request)
    {
        $request->validate([
            'partner_id' => ['required', 'integer', 'exists:pgsql_auth.partners,id'],
            'partner_user_id' => ['required', 'integer'],
            'permissions' => ['nullable', 'array'],
            'permissions.*.module_key' => ['required_with:permissions', 'string', 'max:100'],
            'permissions.*.module_name' => ['nullable', 'string', 'max:255'],
            'permissions.*.group_name' => ['nullable', 'string', 'max:255'],
            'permissions.*.can_view' => ['nullable', 'boolean'],
            'permissions.*.can_add' => ['nullable', 'boolean'],
            'permissions.*.can_edit' => ['nullable', 'boolean'],
            'permissions.*.can_delete' => ['nullable', 'boolean'],
        ]);

        $user = PartnerUser::query()
            ->where('partner_id', (int) $request->partner_id)
            ->whereKey((int) $request->partner_user_id)
            ->first();

        if (!$user) {
            return response()->json([
                'success' => false,
                'message' => 'Partner user not found.',
            ], 404);
        }

        if ($request->has('permissions') && is_array($request->permissions)) {
            $this->savePartnerUserPermissions($user, $request->permissions);
