                'designation' => (string) ($user->designation ?? ''),
                'mobile' => (string) ($user->mobile ?? ''),
                'email' => (string) ($user->email ?? ''),
                'status' => (string) ($user->status ?? 'active'),
                'last_login_at' => $user->last_login_at
                    ? Carbon::parse($user->last_login_at)->format('d M Y, h:i A')
                    : null,
                'permissions' => $permissions,
                'device_login_info' => [
                    'available' => $sessionService->isReady(),
                    'has_active' => collect($devices)->contains('is_active', true),
                    'devices' => $devices,
                ],
            ],
        ], 200);
    }

    
    public function partnerUserDeactivateDevice(Request $request)
    {
        $request->validate([
            'partner_id' => ['required', 'integer', 'exists:pgsql_auth.partners,id'],
            'partner_user_id' => ['required', 'integer'],
            'session_id' => ['nullable', 'integer'],
            'type' => ['nullable', 'string', 'in:active,inactive,deactive,Active,Inactive,Deactive'],
            'block_device' => ['nullable', 'boolean'],
        ]);

        $user = PartnerUser::query()
            ->where('partner_id', (int) $request->partner_id)
            ->whereKey((int) $request->partner_user_id)
            ->first();

        if (!$user) {
            return response()->json([
                'success' => false,
                'message' => 'Partner user not found.',
            ], 404);
        }

        $sessionService = app(PartnerUserSessionService::class);
        if (!$sessionService->isReady()) {
            return response()->json([
                'success' => false,
                'message' => 'Device sessions are not available yet.',
            ], 503);
        }

        if (strtolower((string) $request->input('type', 'inactive')) === 'active') {
            $user->status = 'active';
            $user->save();

            try {
                \App\Models\PartnerSession::query()
                    ->where('partner_user_id', (int) $user->id)
                    ->whereNotNull('blocked_at')
                    ->update(['blocked_at' => null]);
            } catch (\Throwable $e) {
                Log::info('Partner device unblock skipped: ' . $e->getMessage(), ['partner_user_id' => $user->id]);
            }

            return response()->json([
                'success' => true,
                'message' => 'User activated successfully.',
                'data' => [
                    'partner_user_id' => (int) $user->id,
                    'status' => 'active',
                    'blocked' => ['user_blocked' => false, 'device_blocked' => false, 'device_id' => null],
                    'devices' => $sessionService->devicesFor($user, $this->currentBearerTokenId($request)),
                ],
            ], 200);
        }

        $sessionId = $request->filled('session_id') ? (int) $request->session_id : null;

        // Device of the given session (if the app sent device_id at login), blocked too on a best-effort basis
        $blockDeviceId = $sessionId
            ? trim((string) \App\Models\PartnerSession::query()
                ->where('partner_id', (int) $user->partner_id)
                ->where('partner_user_id', (int) $user->id)
                ->whereKey($sessionId)
                ->value('device_id')) ?: null
            : null;

        try {
            // Deleting the Sanctum tokens makes every later request with them fail with 401 (forced logout).
            // A session_id only logs out that device, but the user is blocked either way.
            $count = $sessionService->deactivate($user, $sessionId);

            // Non-active users are rejected at send-otp / verify-otp, so no new token can be issued
            $user->status = 'blocked';
            $user->save();
        } catch (\Throwable $e) {
            Log::error('Partner user device deactivate failed: ' . $e->getMessage(), [
                'partner_id' => $user->partner_id,
                'partner_user_id' => $user->id,
                'session_id' => $sessionId,
            ]);

            return response()->json([
                'success' => false,
                'message' => 'Failed to deactivate and block user.',
            ], 500);
        }

        $deviceBlocked = false;
        if ($blockDeviceId) {
            try {
                $deviceBlocked = $sessionService->blockDevice($user, $blockDeviceId) > 0;
            } catch (\Throwable $e) {
                Log::warning('Partner device block skipped (run the blocked_at SQL): ' . $e->getMessage(), [
                    'partner_user_id' => $user->id,
                    'device_id' => $blockDeviceId,
                ]);
            }
        }

        $blocked = [
            'user_blocked' => true,
            'device_blocked' => $deviceBlocked,
            'device_id' => $blockDeviceId,
        ];

        $message = $count > 0
            ? ($count === 1 ? 'Device logged out and user blocked successfully.' : "{$count} devices logged out and user blocked successfully.")
            : 'User blocked successfully. No active device was logged in.';

        return response()->json([
            'success' => true,
            'message' => $message,
            'data' => [
                'deactivated' => $count,
                'blocked' => $blocked,
                'devices' => $sessionService->devicesFor($user, $this->currentBearerTokenId($request)),
            ],
        ], 200);
    }

    private function currentBearerTokenId(Request $request): ?int
    {
        $bearer = $request->bearerToken();
        if (!$bearer) {
            return null;
        }

        $token = PersonalAccessToken::findToken($bearer);

        return $token ? (int) $token->id : null;
    }

    public function partnerUserAdd(Request $request)
    {
        $request->validate([
            'partner_id' => ['required', 'integer', 'exists:pgsql_auth.partners,id'],
            'name' => ['required', 'string', 'max:255'],
            'mobile' => ['required', 'string', 'max:15'],
            'email' => ['required', 'email', 'max:255'],
            'employee_id' => ['nullable', 'string', 'max:50'],
            'designation' => ['nullable', 'string', 'max:255'],
            'status' => ['nullable', 'string', 'max:50'],
            'permissions' => ['nullable', 'array'],
            'permissions.*.module_key' => ['required_with:permissions', 'string', 'max:100'],
            'permissions.*.can_view' => ['nullable', 'boolean'],
            'permissions.*.can_add' => ['nullable', 'boolean'],
            'permissions.*.can_edit' => ['nullable', 'boolean'],
            'permissions.*.can_delete' => ['nullable', 'boolean'],
        ]);

        $email = strtolower(trim((string) $request->email));
        $mobile = trim((string) $request->mobile);
        $conflict = match (true) {
            Partner::query()->whereRaw('LOWER(TRIM(email)) = ?', [$email])->exists() => 'This email is already registered as a partner account.',
            Partner::query()->whereRaw('TRIM(mobile) = ?', [$mobile])->exists() => 'This mobile no. is already registered as a partner account.',
            PartnerUser::query()->whereRaw('LOWER(TRIM(email)) = ?', [$email])->exists() => 'Email already used by another partner user.',
            PartnerUser::query()->whereRaw('TRIM(mobile) = ?', [$mobile])->exists() => 'Mobile no. already used by another partner user.',
            default => null,
        };
        if ($conflict) {
            return response()->json(['success' => false, 'message' => $conflict], 422);
        }

        $user = PartnerUser::create([
            'partner_id' => (int) $request->partner_id,
            'name' => $request->name,
            'mobile' => $request->mobile,
            'email' => $request->email,
            'employee_id' => $request->employee_id ?? null,
            'designation' => $request->designation ?? null,
            'status' => $request->status ?? 'active',
        ]);

        if ($request->has('permissions') && is_array($request->permissions)) {
            $this->savePartnerUserPermissions($user, $request->permissions);
        }

        return response()->json([
            'success' => true,
            'message' => 'Partner user added successfully.',
            'data' => [
                'partner_user_id' => (int) $user->id,
                'partner_id' => (int) $user->partner_id,
                'name' => (string) $user->name,
                'mobile' => (string) $user->mobile,
                'email' => (string) $user->email,
                'employee_id' => (string) ($user->employee_id ?? ''),
                'designation' => (string) ($user->designation ?? ''),
                'status' => (string) ($user->status ?? 'active'),
            ],
        ], 201);
    }

    public function partnerUserUpdate(Request $request)
    {
        $request->validate([
            'partner_id' => ['required', 'integer', 'exists:pgsql_auth.partners,id'],
            'partner_user_id' => ['required', 'integer'],
            'name' => ['required', 'string', 'max:255'],
            'mobile' => ['required', 'string', 'max:15'],
            'email' => ['required', 'email', 'max:255'],
            'employee_id' => ['nullable', 'string', 'max:50'],
            'designation' => ['nullable', 'string', 'max:255'],
            'status' => ['nullable', 'string', 'max:50'],
        ]);

        $user = PartnerUser::query()
            ->where('partner_id', (int) $request->partner_id)
            ->whereKey((int) $request->partner_user_id)
            ->first();

        if (!$user) {
            return response()->json([
                'success' => false,
                'message' => 'Partner user not found.',
            ], 404);
        }

        $email = strtolower(trim((string) $request->email));
        $mobile = trim((string) $request->mobile);
        $conflict = match (true) {
            Partner::query()->whereRaw('LOWER(TRIM(email)) = ?', [$email])->exists() => 'This email is already registered as a partner account.',
            Partner::query()->whereRaw('TRIM(mobile) = ?', [$mobile])->exists() => 'This mobile no. is already registered as a partner account.',
            PartnerUser::query()->whereRaw('LOWER(TRIM(email)) = ?', [$email])->where('id', '!=', $user->id)->exists() => 'Email already used by another partner user.',
            PartnerUser::query()->whereRaw('TRIM(mobile) = ?', [$mobile])->where('id', '!=', $user->id)->exists() => 'Mobile no. already used by another partner user.',
            default => null,
        };
        if ($conflict) {
            return response()->json(['success' => false, 'message' => $conflict], 422);
        }

        $user->name = $request->name;
        $user->mobile = $request->mobile;
        $user->email = $request->email;
        $user->employee_id = $request->employee_id ?? $user->employee_id;
        $user->designation = $request->designation ?? $user->designation;
        if ($request->filled('status')) {
            $user->status = $request->status;
        }
        $user->save();

        return response()->json([
            'success' => true,
            'message' => 'Partner user updated successfully.',
            'data' => [
                'partner_user_id' => (int) $user->id,
                'partner_id' => (int) $user->partner_id,
                'name' => (string) $user->name,
                'mobile' => (string) $user->mobile,
                'email' => (string) $user->email,
                'employee_id' => (string) ($user->employee_id ?? ''),
                'q' => (string) ($user->designation ?? ''),
                'status' => (string) ($user->status ?? 'active'),
            ],
        ], 200);
    }

    public function partnerUserStatus(Request $request)
    {
        $request->validate([
            'partner_id' => ['required', 'integer', 'exists:pgsql_auth.partners,id'],
            'partner_user_id' => ['required', 'integer'],
            'status' => ['required', 'string', 'in:active,inactive'],
        ]);

        $user = PartnerUser::query()
            ->where('partner_id', (int) $request->partner_id)
            ->whereKey((int) $request->partner_user_id)
            ->first();

        if (!$user) {
            return response()->json([
                'success' => false,
                'message' => 'Partner user not found.',
            ], 404);
        }

        $user->status = $request->status;
        $user->save();

        $loggedOut = $request->status === 'inactive'
            ? app(PartnerUserSessionService::class)->deactivate($user)
            : 0;

        return response()->json([
            'success' => true,
            'message' => $request->status === 'inactive'
                ? 'Partner user deleted successfully.'
                : 'Partner user activated successfully.',
            'data' => [
                'partner_user_id' => (int) $user->id,
                'partner_id' => (int) $user->partner_id,
                'name' => (string) $user->name,
                'status' => (string) $user->status,
                'devices_logged_out' => $loggedOut,
            ],
        ], 200);
    }

    /**
     * Partner support ticket list (dashboard cards + ticket cards).
     * GET /get-tickets?partner_id=1&status=all|active|in_process|resolved&q=&page=1&per_page=12
     */
    public function getTickets(Request $request): JsonResponse
    {
        // Validate partner_id manually before running any queries
        if (!$request->filled('partner_id') || !is_numeric($request->partner_id)) {
            return response()->json([
                'success' => false,
                'message' => 'The partner_id field is required and must be an integer.',
            ], 422);
        }

        // Validate partner exists, using correct connection and model
        $partnerId = (int) $request->partner_id;
        try {
            $partnerExists = \DB::connection('pgsql_auth')
                ->table('partners')
                ->where('id', $partnerId)
                ->exists();
        } catch (\Exception $e) {
            return response()->json([
                'success' => false,
                'message' => 'Auth database not ready or partners table missing: ' . $e->getMessage(),
            ], 500);
        }

        if (!$partnerExists) {
            return response()->json([
                'success' => false,
                'message' => 'Partner not found.',
            ], 404);
        }

        // Laravel built-in validation for other fields
        $validator = Validator::make($request->all(), [
            'status' => ['nullable', 'string', 'max:100'],
            'priority' => ['nullable', 'string', 'max:100'],
            'q' => ['nullable', 'string', 'max:255'],
            'page' => ['nullable', 'integer', 'min:1'],
            'per_page' => ['nullable', 'integer', 'min:1', 'max:50'],
            '1' => ['nullable', 'integer'],
        ]);
        if ($validator->fails()) {
            return response()->json([
                'success' => false,
                'message' => $validator->errors()->first(),
            ], 422);
        }

        // status / priority accept comma separated values, e.g. status=open,in_process & priority=high,urgent
        $statusFilter = array_filter(array_map('trim', explode(',', strtolower((string) $request->input('status', '')))));
        $priorityFilter = array_values(array_intersect(
            array_map('trim', explode(',', strtolower((string) $request->input('priority', '')))),
            ['low', 'medium', 'high', 'urgent']
        ));
        $search = trim($request->input('q', $request->input('search', '')));
        $perPage = (int) $request->input('per_page', 12);

        $partnerUserId = $this->resolvePartnerUserIdForTickets($request, $partnerId);
        if ($partnerUserId === false) {
            return response()->json([
                'success' => false,
                'message' => 'Partner user not found for this partner.',
            ], 422);
        }

        // Only 3 status groups for the partner app; every stored status falls in one of them
        $groups = [
            'open' => ['Open', 'Reopened', 'Pending', SupportTicket::STATUS_PENDING_ASSIGNMENT, SupportTicket::STATUS_ESCALATED],
            'in_process' => ['In Progress', 'Waiting for Customer'],
            'resolved' => ['Resolved', 'Closed'],
        ];
        $selectedStatuses = collect($statusFilter)->flatMap(fn ($key) => $groups[$key] ?? [])->unique()->values()->all();

        // Defensive: Check support_tickets table exists before running queries
        try {
            // Check support_tickets table existence (pgsql_support connection if used)
            if (!\Schema::connection('pgsql_support')->hasTable('support_tickets')) {
                return response()->json([
                    'success' => false,
                    'message' => 'Support ticket system is not yet fully set up (missing tables).',
                ], 500);
            }
        } catch (\Exception $e) {
            return response()->json([
                'success' => false,
                'message' => 'Support ticket system is not yet fully set up: ' . $e->getMessage(),
            ], 500);
        }

        try {
            $baseQuery = fn () => SupportTicket::query()->forPartnerActor($partnerId, $partnerUserId);

            $count = function (array $statuses) use ($baseQuery) {
                return $baseQuery()->whereIn('status', $statuses)->count();
            };

            $stats = [
                ['key' => 'Total Tickets', 'value' => $baseQuery()->count()],
                ['key' => 'Open Tickets', 'value' => $count($groups['open'])],
                ['key' => 'In Process Tickets', 'value' => $count($groups['in_process'])],
                ['key' => 'Resolved Tickets', 'value' => $count($groups['resolved'])],
            ];

            $query = $baseQuery()
                ->with([
                    'activities' => function ($q) {
                        $q->where('type', 'created')->orderBy('id');
                    },
                    'attachments',
                ])
                ->orderByDesc('id');

            if ($selectedStatuses) {
                $query->whereIn('status', $selectedStatuses);
            }
            if ($priorityFilter) {
                $query->whereIn(\DB::raw("LOWER(TRIM(COALESCE(priority, '')))"), $priorityFilter);
            }

            if ($search !== '') {
                $query->where(function ($q) use ($search) {
                    $q->where('ticket_no', 'ilike', '%' . $search . '%')
                        ->orWhere('subject', 'ilike', '%' . $search . '%')
                        ->orWhere('email', 'ilike', '%' . $search . '%')
                        ->orWhere('service', 'ilike', '%' . $search . '%')
                        ->orWhere('requester', 'ilike', '%' . $search . '%')
                        ->orWhere('domain', 'ilike', '%' . $search . '%');
                });
            }

            $paginator = $query->paginate($perPage);

            $customers = Customer::whereIn(
                'email',
                collect($paginator->items())->pluck('email')->filter()->unique()
            )->get()->keyBy('email');
            $partner = Partner::find($partnerId);

            $statusLabel = array_merge(
                array_fill_keys($groups['open'], 'Open'),
                array_fill_keys($groups['in_process'], 'In Process'),
                array_fill_keys($groups['resolved'], 'Resolved')
            );

            $tickets = collect($paginator->items())->map(function (SupportTicket $ticket) use ($statusLabel, $customers, $partner) {

                $customer = $customers->get($ticket->email);

                return [
                    'ticket_id' => (int) $ticket->id,
                    'ticket_no' => (string) ($ticket->ticket_no ?? ''),
                    'status' => $statusLabel[$ticket->status] ?? (string) ($ticket->status ?? ''),
                    'priority' => (string) ($ticket->priority ?? ''),
                    'subject' => (string) ($ticket->subject ?? ''),
                    'description' => (string) optional($ticket->activities->first())->message,
                    'service' => (string) ($ticket->service ?? ''),
                    'domain' => (string) ($ticket->domain ?? ''),
                    'email' => (string) ($ticket->email ?? ''),

                    // Customer company name -> Partner company name -> Ticket requester
                    'company_name' => (string) (
                        $customer?->company_name
                        ?? $partner?->company_name
                        ?? $ticket->requester
                        ?? ''
                    ),

                    // Customer name -> Partner name -> Ticket requester
                    'name' => (string) (
                        $customer?->name
                        ?? $partner?->name
                        ?? $ticket->requester
                        ?? ''
                    ),

                    'date' => $ticket->created_at
                        ? $ticket->created_at->format('d M, Y')
                        : '',

                    'attachments_count' => (function () use ($ticket) {
                        $createdId = (int) optional(
                            $ticket->activities->firstWhere('type', 'created')
                        )->id;
                        if ($createdId <= 0) {
                            return 0;
                        }

                        return $ticket->attachments
                            ->filter(fn (SupportAttachment $f) => empty($f->is_internal)
                                && (int) ($f->activity_id ?? 0) === $createdId)
                            ->count();
                    })(),
                ];
            })->values();

            return response()->json([
                'success' => true,
                'message' => 'Tickets fetched successfully.',
                'data' => [
                    'stats' => $stats,
                    'filters' => [
                        'status' => [
                            ['key' => 'open', 'label' => 'Open'],
                            ['key' => 'in_process', 'label' => 'In Process'],
                            ['key' => 'resolved', 'label' => 'Resolved'],
                        ],
                        'priority' => [
                            ['key' => 'low', 'label' => 'Low'],
                            ['key' => 'medium', 'label' => 'Medium'],
                            ['key' => 'high', 'label' => 'High'],
                            ['key' => 'urgent', 'label' => 'Urgent'],
                        ],
                    ],
                    'tickets' => $tickets,
                    'pagination' => [
                        'current_page' => $paginator->currentPage(),
                        'per_page' => $paginator->perPage(),
                        'total' => $paginator->total(),
                        'last_page' => $paginator->lastPage(),
                    ],
                ],
            ], 200);
        } catch (\Illuminate\Database\QueryException $ex) {
            if (str_contains($ex->getMessage(), 'does not exist')) {
                return response()->json([
                    'success' => false,
                    'message' => 'Support ticket system is not yet fully set up (missing tables).',
                ], 500);
            }
            return response()->json([
                'success' => false,
                'message' => 'Database query error: ' . $ex->getMessage(),
            ], 500);
        } catch (\Exception $ex) {
            return response()->json([
                'success' => false,
                'message' => 'Unexpected error: ' . $ex->getMessage(),
            ], 500);
        }
    }

    public function getTicketDetail(Request $request): JsonResponse
    {
        $request->validate([
            'partner_id' => ['required', 'integer', 'exists:pgsql_auth.partners,id'],
            'ticket_id' => ['required', 'integer'],
            'partner_user_id' => ['nullable', 'integer'],
        ]);

        $partnerId = (int) $request->partner_id;
        $partnerUserId = $this->resolvePartnerUserIdForTickets($request, $partnerId);
        if ($partnerUserId === false) {
            return response()->json([
                'success' => false,
                'message' => 'Partner user not found for this partner.',
            ], 422);
        }

        $ticket = SupportTicket::with([
            'activities' => fn ($q) => $q->orderByDesc('id'),
            'attachments',
        ])
            ->forPartnerActor($partnerId, $partnerUserId)
            ->where('id', (int) $request->ticket_id)
            ->first();

        if (!$ticket) {
            return response()->json(['success' => false, 'message' => 'Ticket not found.'], 404);
        }

        $partner = Partner::find($partnerId);
        $createdActivity = $ticket->activities->where('type', 'created')->sortBy('id')->first();

        $statusTypes = ['created', 'status_change', 'closed', 'resolved', 'reopened'];
        $activityTitles = [
            'created' => 'Create Ticket',
            'status_change' => 'Status Changed',
            'resolved' => 'Ticket Resolved',
            'closed' => 'Ticket Closed',
            'reopened' => 'Ticket Reopened',
        ];

        $activities = $ticket->activities
            ->filter(fn (SupportActivity $a) => in_array(strtolower((string) ($a->type ?? '')), $statusTypes, true))
            ->map(function (SupportActivity $a) use ($activityTitles) {
                $by = 'System';
                if ($a->user_type === 'partner') {
                    $p = $a->user_id ? Partner::find($a->user_id) : null;
                    $by = $p?->name ?? $p?->company_name ?? 'Partner';
                } elseif (in_array($a->user_type, ['superadmin', 'admin', 'agent'], true)) {
                    $by = 'Support Team';
                } elseif (!empty($a->user_type)) {
                    $by = ucfirst((string) $a->user_type);
                }

                $type = strtolower((string) ($a->type ?? ''));
                $oldStatus = (string) ($a->old_status ?? '');
                $newStatus = (string) ($a->new_status ?? '');
                $description = (string) ($a->message ?? '');
                if ($type === 'created') {
                    $description = 'Ticket created';
                } elseif ($oldStatus !== '' && $newStatus !== '') {
                    $description = "Status changed from {$oldStatus} to {$newStatus}";
                }

                return [
                    'id' => (int) $a->id,
                    'type' => (string) ($a->type ?? 'status_change'),
                    'title' => $activityTitles[$type] ?? $activityTitles[$a->type] ?? 'Status Changed',
                    'description' => $description,
                    'old_status' => $oldStatus !== '' ? $oldStatus : null,
                    'new_status' => $newStatus !== '' ? $newStatus : null,
                    'by' => $by,
                    'date' => $a->created_at
                        ? ($a->created_at->isToday()
                            ? 'Today · ' . $a->created_at->format('g:i A')
                            : $a->created_at->format('d M Y, g:i A'))
                        : '',
                ];
            })
            ->values();
            
        $createdActivityId = $createdActivity ? (int) $createdActivity->id : 0;

        $attachments = $ticket->attachments
            ->filter(function (SupportAttachment $file) use ($createdActivityId) {
                if (!empty($file->is_internal)) {
                    return false;
                }
                if ($createdActivityId <= 0) {
                    return false;
                }

                return (int) ($file->activity_id ?? 0) === $createdActivityId;
            })
            ->map(function (SupportAttachment $file) {
                $path = ltrim(str_replace('\\', '/', (string) ($file->file_path ?? '')), '/');
                $path = preg_replace('#^(storage/app/public/|public/|storage/)#', '', $path);

                return [
                    'id' => (int) $file->id,
                    'filename' => (string) $file->filename,
                    'mime_type' => (string) ($file->mime_type ?? ''),
                    'file_size' => (int) ($file->file_size ?? 0),
                    'url' => $path !== ''
                        ? rtrim((string) config('app.url'), '/') . '/storage/' . $path
                        : null,
                ];
            })
            ->values();

        $statusKey = strtolower(trim((string) ($ticket->status ?? '')));
        $reopenCount = $ticket->activities->where('type', 'reopened')->count();
        $closedAt = $ticket->closed_at ?? $ticket->resolved_at ?? $ticket->status_changed_at ?? $ticket->updated_at;
        $within72 = $closedAt && now()->lessThanOrEqualTo(\Carbon\Carbon::parse($closedAt)->addHours(72));
        $showReopenButton = in_array($statusKey, ['closed', 'resolved'], true)
            && $within72
            && $reopenCount < 2;

        $assignMeta = SupportTicket::assignedAgentPayload(
            $ticket->assigned_to ? (int) $ticket->assigned_to : null
        );

        $orderId = (int) ($ticket->order_id ?? 0);
        $planId = (int) ($ticket->plan_id ?? 0);
        $subscriptionId = null;
        if ($orderId > 0) {
            $subscriptionId = OrderItem::query()
                ->where('order_id', $orderId)
                ->where('plan_id', $planId)
                ->first();
            $subscriptionId =  $subscriptionId->subscription_id;
        }
        $orderdetails = Order::where('id', $orderId)->first();
        return response()->json([
            'success' => true,
            'message' => 'Ticket details fetched successfully.',
            'data' => [
                'ticket_id' => (int) $ticket->id,
                'ticket_no' => (string) ($ticket->ticket_no ?? ''),
                'customer_name' => (string) ($partner?->name ?? ''),
                'company_name' => (string) ($partner?->company_name ?? $partner?->name ?? ''),
                'name' => (string) ($ticket->requester ?? ''),
                'email' => (string) ($ticket->email ?? ''),
                'domain' => (string) ($ticket->domain ?? ''),
                'service' => (string) ($ticket->service ?? ''),
                'priority' => (string) ($ticket->priority ?? ''),
                'plan_id' => $planId > 0 ? $planId : null,
                'order_id' => $orderId > 0 ? $orderId : null,
                'order_no' => (string) ($orderdetails ? $orderdetails->order_no : ''),
                'subscription_id' => $subscriptionId !== null && $subscriptionId !== ''
                    ? (string) $subscriptionId
                    : null,
                'provider_id' => (int) ($ticket->provider_id ?? 0),

                'status' => (string) ($ticket->status ?? ''),
                'previous_status' => (string) ($ticket->previous_status ?? ''),
                'status_changed_at' => $ticket->status_changed_at ? $ticket->status_changed_at->format('Y-m-d H:i:s'): null,
                'order_category' => (string) ($orderdetails ? ($orderdetails->transfer_domain  == 'yes' ? 'Transfer Domain' : 'New Service') : ''),
                'subject' => (string) ($ticket->subject ?? ''),
                'description' => (string) optional($createdActivity)->message,
                'created_on' => $ticket->created_at ? $ticket->created_at->format('d M, Y · h:i A') : '',
                'attachments' => $attachments,

                'attachments_count' => $attachments->count(),
                'attachments_scope' => 'create_ticket_only',
                'attachments_note' => 'Returns only create-ticket attachments (activity_id = created activity). Chat/reply attachments are excluded.',
                'activities' => $activities,
                'cc_emails' => (array) ($ticket->cc_emails ?? []),
                'show_reopen_button' => (bool) $showReopenButton,
                'reopen_count' => (int) $reopenCount,
                'max_reopens' => 2,
                
                'closed_at' => $closedAt ? \Carbon\Carbon::parse($closedAt)->format('Y-m-d H:i:s') : null,
            ] + $assignMeta,
        ], 200);
    }

    // Get order details by partner_id and optional order_no (LIKE search).

    public function getOrdersByPartner(Request $request): JsonResponse
    {
        $request->validate([
            'partner_id' => ['required', 'integer', 'exists:pgsql_auth.partners,id'],
            'order_no' => ['nullable', 'string', 'max:255'],
        ]);

        try {
            $partnerId = (int) $request->input('partner_id', $request->query('partner_id'));
            $orderNo = trim((string) $request->input('order_no', $request->query('order_no', '')));

            $ordersQuery = Order::query()
                ->with(['customer:id,name,email', 'plan:id,name,title', 'items.plan:id,name,title'])
                ->where('partner_id', $partnerId)
                ->orderByDesc('id');

            if ($orderNo !== '') {
                $ordersQuery->where('order_no',  $orderNo);
            }

            $order = $ordersQuery->first();

            if (!$order) {
                return response()->json([
                    'success' => false,
                    'message' => 'Order not found.',
                    'data' => null,
                ], 404);
            }

            $planList = $order->items
                ->pluck('plan')
                ->filter()
                ->map(function ($plan) {
                    return (string) ($plan->title ?? $plan->name ?? '');
                })
                ->filter()
                ->unique()
                ->values();

            if ($planList->isEmpty()) {
                $fallbackPlan = (string) (optional($order->plan)->title ?? optional($order->plan)->name ?? '');
                if ($fallbackPlan !== '') {
                    $planList = collect([$fallbackPlan]);
                }
            }

            $data = [
                'order_id' => (int) $order->id,
                'order_no' => (string) ($order->order_no ?? ''),
                'partner_id' => (int) ($order->partner_id ?? 0),
                'plan_list' => $planList->all(),
                'name' => (string) (optional($order->customer)->name ?? ''),
                'email' => (string) (optional($order->customer)->email ?? ''),
                'domain' => (string) ($order->domain_name ?? ''),
            ] + $this->partnerOrderActionFlags($order);

            return response()->json([
                'success' => true,
                'message' => 'Order fetched successfully.',
                'data' => $data,
            ], 200);
        } catch (\Exception $e) {
            return response()->json([
                'success' => false,
                'message' => 'Failed to fetch orders: ' . $e->getMessage(),
            ], 500);
        }
    }


    public function addTicket(Request $request)
    {
        // Normalize: single file under "attachments" â†’ array
        if ($request->hasFile('attachments') && !is_array($request->file('attachments'))) {
            $request->files->set('attachments', [$request->file('attachments')]);
        }

        if (!$request->hasFile('attachments')) {
            $request->request->remove('attachments');
            $request->files->remove('attachments');
        }

        $rules = [
            'partner_id' => ['required', 'integer', 'exists:pgsql_auth.partners,id'],
            'customer_id' => ['required', 'integer', 'exists:pgsql_billing.customers,id'],
            'provider_id' => ['required', 'integer', 'exists:pgsql_product.providers,id'],
            'plan_id' => ['nullable', 'integer', 'exists:pgsql_product.plans,id'],
            'order_id' => ['nullable', 'integer', 'exists:pgsql_billing.orders,id'],
            'partner_user_id' => ['nullable', 'integer'],
            // CC emails: optional array only (not comma string / not separate columns)
            'cc_emails' => ['nullable', 'array'],
            'cc_emails.*' => ['email', 'max:255'],
            'domain' => ['required', 'string', 'max:255'],
            'service' => ['required', 'string', 'max:255'],
            'subject' => ['required', 'string', 'max:255'],
            'priority' => ['required', 'string', 'in:Low,Medium,High,Urgent'],
            'description' => ['required', 'string'],
        ];

        if ($request->hasFile('attachments')) {
            $rules['attachments'] = ['array', 'max:5'];
            $rules['attachments.*'] = ['file', 'max:5120', 'extensions:jpg,jpeg,png,gif,pdf,doc,docx,xls,xlsx,txt,zip'];
        }

        $request->validate($rules);

        try {
            $partnerId = (int) $request->partner_id;
            $customerId = (int) $request->customer_id;
            $providerId = (int) $request->provider_id;
            $planId = $request->filled('plan_id') ? (int) $request->plan_id : null;
            $orderId = $request->filled('order_id') ? (int) $request->order_id : null;

            $partnerUserId = $this->resolvePartnerUserIdForTickets($request, $partnerId);
            if ($partnerUserId === false) {
                return response()->json([
                    'success' => false,
                    'message' => 'Partner user not found for this partner.',
                ], 422);
            }

            $createdByType = $partnerUserId ? 'partner_user' : 'partner';
            $activityUserId = $partnerUserId ?: $partnerId;
            $activityUserType = $partnerUserId ? 'partner_user' : 'partner';

            // Normalize CC list → unique lowercase emails array (empty when omitted)
            $ccEmails = collect($request->input('cc_emails', []))
                ->filter(fn ($e) => is_string($e) && trim($e) !== '')
                ->map(fn ($e) => strtolower(trim($e)))
                ->unique()
                ->values()
                ->all();

            $customerBelongsToPartner = Customer::query()
                ->where('id', $customerId)
                ->where('partner_id', $partnerId)
                ->exists();
            if (!$customerBelongsToPartner) {
                return response()->json([
                    'success' => false,
                    'message' => 'Customer not found for this partner.',
                ], 422);
            }

            if ($orderId) {
                $orderBelongsToPartner = Order::query()
                    ->where('id', $orderId)
                    ->where('partner_id', $partnerId)
                    ->exists();
                if (!$orderBelongsToPartner) {
                    return response()->json([
                        'success' => false,
                        'message' => 'Order not found for this partner.',
                    ], 422);
                }

                // If plan_id omitted, take it from the order line item when available.
                if (!$planId) {
                    $planId = OrderItem::query()
                        ->where('order_id', $orderId)
                        ->whereNotNull('plan_id')
                        ->value('plan_id');
                    $planId = $planId ? (int) $planId : null;
                }
            }

            $ticket = DB::transaction(function () use (
                $request,
                $partnerId,
                $customerId,
                $providerId,
                $ccEmails,
                $planId,
                $orderId,
                $partnerUserId,
                $createdByType,
                $activityUserId,
                $activityUserType
            ) {
                $ticketNo = app(SupportTicketIdService::class)->nextTicketNo();

                $ticketPayload = [
                    'ticket_no' => $ticketNo,
                    'partner_id' => $partnerId,
                    'customer_id' => $customerId,
                    'provider_id' => $providerId,
                    'plan_id' => $planId,
                    'order_id' => $orderId,
                    'cc_emails' => $ccEmails,
                    'domain' => $request->domain,
                    'service' => $request->service,
                    'subject' => $request->subject,
                    'priority' => $request->priority,
                    'status' => 'Pending',
                ];

                if (SupportTicket::hasOwnershipColumns()) {
                    $ticketPayload['created_by_partner_user_id'] = $partnerUserId;
                    $ticketPayload['created_by_type'] = $createdByType;
                }

                $ticket = SupportTicket::create($ticketPayload);

                $activity = SupportActivity::create([
                    'ticket_id' => $ticket->id,
                    'user_id' => $activityUserId,
                    'user_type' => $activityUserType,
                    'message' => $request->description,
                    'type' => 'created',
                ]);

                if (
                    $request->hasFile('attachments')
                    && Schema::connection('pgsql_support')->hasTable('ticket_attachments')
                ) {
                    foreach ($request->file('attachments') as $file) {
                        if (!$file->isValid()) {
                            continue;
                        }

                        $storedPath = $file->store('support-tickets/' . $ticket->id, 'public');
                        SupportAttachment::create([
                            'ticket_id' => $ticket->id,
                            'activity_id' => $activity->id,
                            'file_path' => $storedPath,
                            'filename' => $file->getClientOriginalName(),
                            'mime_type' => $file->getClientMimeType(),
                            'file_size' => $file->getSize(),
                            'uploaded_by' => $partnerId,
                        ]);
                    }
                }

                return $ticket;
            });

            try {
                $ticket->autoAssignOnCreate();
                $ticket->refresh();
            } catch (\Throwable $e) {
                Log::error('Ticket auto-assign failed: ' . $e->getMessage(), ['ticket_id' => $ticket->id]);
            }

            $ticket->load('attachments');

            $mailStatus = [
                'mail_sent' => false,
                'message' => 'Mail not attempted.',
                'to' => null,
                'cc' => [],
                'error' => null,
            ];
            try {
                $mailStatus = (new \App\Services\TicketMailService())->sendTicketCreatedNotifications($ticket);
            } catch (\Exception $e) {
                Log::error('Ticket notification error: ' . $e->getMessage());
                $mailStatus = [
                    'mail_sent' => false,
                    'message' => 'Mail send failed: ' . $e->getMessage(),
                    'to' => null,
                    'cc' => [],
                    'error' => $e->getMessage(),
                ];
            }

            $assignMeta = SupportTicket::assignedAgentPayload(
                $ticket->assigned_to ? (int) $ticket->assigned_to : null
            );

            $attachments = $ticket->attachments->map(function (SupportAttachment $attachment) {
                $path = ltrim(str_replace('\\', '/', (string) ($attachment->file_path ?? '')), '/');
                $path = preg_replace('#^(storage/app/public/|public/|storage/)#', '', $path);

                return [
                    'id' => (int) $attachment->id,
                    'filename' => (string) $attachment->filename,
                    'mime_type' => (string) ($attachment->mime_type ?? ''),
                    'file_size' => (int) ($attachment->file_size ?? 0),
                    'url' => $path !== ''
                        ? rtrim((string) config('app.url'), '/') . '/storage/' . $path
                        : null,
                ];
            })->values()->all();

            return response()->json([
                'success' => true,
                'message' => 'Ticket created successfully.'
                    . ((bool) ($mailStatus['mail_sent'] ?? false)
                        ? ' Mail sent.'
                        : ' Mail not sent.'),
                'data' => [
                    'ticket_id' => (int) $ticket->id,
                    'ticket_no' => (string) $ticket->ticket_no,
                    'partner_id' => (int) $ticket->partner_id,
                    'customer_id' => (int) ($ticket->customer_id ?? 0),
                    'provider_id' => (int) ($ticket->provider_id ?? 0),
                    'plan_id' => (int) ($ticket->plan_id ?? 0) ?: null,
                    'order_id' => (int) ($ticket->order_id ?? 0) ?: null,
                    'created_by_partner_user_id' => (int) ($ticket->created_by_partner_user_id ?? 0) ?: null,
                    'created_by_type' => (string) ($ticket->created_by_type ?? 'partner'),
                    'cc_emails' => is_array($ticket->cc_emails) ? $ticket->cc_emails : [],
                    'domain' => (string) ($ticket->domain ?? ''),
                    'service' => (string) ($ticket->service ?? ''),
                    'subject' => (string) $ticket->subject,
                    'priority' => (string) $ticket->priority,
                    'status' => (string) $ticket->status,
                    'description' => (string) $request->description,
                    'attachments' => $attachments,
                    'mail_sent' => (bool) ($mailStatus['mail_sent'] ?? false),
                    'mail_message' => (string) ($mailStatus['message'] ?? ''),
                    'mail_to' => $mailStatus['to'] ?? null,
                    'mail_cc' => $mailStatus['cc'] ?? [],
                    'mail_error' => $mailStatus['error'] ?? null,
                ] + $assignMeta,
            ], 200);
        } catch (\Exception $e) {
            return response()->json([
                'success' => false,
                'message' => 'Failed to create ticket: ' . $e->getMessage(),
            ], 500);
        }
    }

    private function mapPartnerModulePermissions($savedByModuleKey)
    {
        return PartnerModule::query()
            ->where('status', 1)
            ->orderBy('sort_order')
            ->orderBy('id')
            ->get()
            ->map(function (PartnerModule $module) use ($savedByModuleKey) {
                $row = $savedByModuleKey->get($module->module_key);
                $allow = $module->allowFlags();

                if ($this->isDashboardModule($module)) {
                    // Dashboard is always fully accessible, regardless of saved rows or allow flags.
                    $canView = $canAdd = $canEdit = $canDelete = true;
                } else {
                    $canView = $row ? (bool) $row->can_view : false;
                    $canAdd = $row ? (bool) $row->can_add : false;
                    $canEdit = $row ? (bool) $row->can_edit : false;
                    $canDelete = $row ? (bool) $row->can_delete : false;

                    // Disallowed actions cannot be granted
                    if (!$allow['allow_view']) {
                        $canView = false;
                    }
                    if (!$allow['allow_add']) {
                        $canAdd = false;
                    }
                    if (!$allow['allow_edit']) {
                        $canEdit = false;
                    }
                    if (!$allow['allow_delete']) {
                        $canDelete = false;
                    }
                }

                return [
                    'module_id' => (int) $module->id,
                    'module_key' => (string) $module->module_key,
                    'module_name' => (string) $module->module_name,
                    'group_name' => (string) $module->group_name,
                    'is_visible_view' => (bool) $allow['allow_view'],
                    'is_visible_add' => (bool) $allow['allow_add'],
                    'is_visible_edit' => (bool) $allow['allow_edit'],
                    'is_visible_delete' => (bool) $allow['allow_delete'],
                    'can_view' => $canView,
                    'can_add' => $canAdd,
                    'can_edit' => $canEdit,
                    'can_delete' => $canDelete,
                ];
            })->values();
    }

    private function isDashboardModule(PartnerModule $module): bool
    {
        return strcasecmp(trim((string) $module->module_name), 'Dashboard') === 0;
    }

    private function resolvePartnerUserIdForTickets(Request $request, int $partnerId)
    {
        if (!$request->filled('partner_user_id')) {
            return null;
        }

        $partnerUserId = (int) $request->partner_user_id;
        if ($partnerUserId <= 0) {
            return null;
        }

        $exists = PartnerUser::query()
            ->where('partner_id', $partnerId)
            ->whereKey($partnerUserId)
            ->exists();

        return $exists ? $partnerUserId : false;
    }

    private function savePartnerUserPermissions(PartnerUser $user, array $permissions): void
    {
        $keptModuleKeys = [];

        foreach ($permissions as $row) {
            $module = null;
            if (!empty($row['module_id'])) {
                $module = PartnerModule::query()->whereKey((int) $row['module_id'])->first();
            }
            if (!$module && !empty($row['module_key'])) {
                $module = PartnerModule::query()->where('module_key', $row['module_key'])->first();
            }
            if (!$module) {
                continue;
            }

            $allow = $module->allowFlags();
            $moduleKey = (string) $module->module_key;
            $keptModuleKeys[] = $moduleKey;

            PartnerPermission::query()->updateOrCreate(
                [
                    'partner_user_id' => $user->id,
                    'module_key' => $moduleKey,
                ],
                [
                    'partner_id' => $user->partner_id,
                    'module_id' => $module->id,
                    'module_name' => $module->module_name,
                    'group_name' => $module->group_name,
                    'can_view' => $allow['allow_view'] && !empty($row['can_view']),
                    'can_add' => $allow['allow_add'] && !empty($row['can_add']),
                    'can_edit' => $allow['allow_edit'] && !empty($row['can_edit']),
                    'can_delete' => $allow['allow_delete'] && !empty($row['can_delete']),
                ]
            );
        }

        $deleteQuery = PartnerPermission::query()->where('partner_user_id', $user->id);
        if (!empty($keptModuleKeys)) {
            $deleteQuery->whereNotIn('module_key', array_values(array_unique($keptModuleKeys)));
        }
        $deleteQuery->delete();
    }

    // order list api by partner id 
    public function orderListByPartner(Request $request): JsonResponse
    {
        $request->validate([
            'partner_id' => ['required', 'integer', 'exists:pgsql_auth.partners,id'],
        ]);
        $orderNo = $request->input('order_no', '');
        $orders = Order::select('id', 'order_no')->where('partner_id', $request->partner_id)->where('order_no', 'like', '%' . $orderNo . '%')->get();
        return response()->json([
            'success' => true,
            'message' => 'Order list fetched successfully.',
            'data' => $orders,
        ], 200);
    }

    /**
     * Partner Panel: cancel order.
     * Active Tizzy/Microsoft: within 6 days of subscription start. Google: not after activation.
     * Pending/processing: cancel anytime.
     */
    public function orderCancel(Request $request): JsonResponse
    {
        $request->validate([
            'order_id' => ['required', 'integer', 'exists:pgsql_billing.orders,id'],
            'partner_id' => ['nullable', 'integer'],
            'rejection_reason' => ['nullable', 'string', 'max:1000'],
            'cancel_reason' => ['nullable', 'string', 'max:1000'],
        ]);

        try {
            $order = Order::query()->whereKey((int) $request->order_id)->first();
            if (!$order) {
                return response()->json(['success' => false, 'message' => 'Order not found.'], 404);
            }

            $partnerId = (int) ($request->input('partner_id') ?: $request->user()?->partner_id ?? 0);
            if ($partnerId > 0 && (int) ($order->partner_id ?? 0) !== $partnerId) {
                return response()->json(['success' => false, 'message' => 'Order does not belong to this partner.'], 403);
            }
            if ($partnerId <= 0) {
                $partnerId = (int) ($order->partner_id ?? 0);
            }

            $flags = $this->partnerOrderActionFlags($order);
            if (empty($flags['can_cancel'])) {
                return response()->json([
                    'success' => false,
                    'message' => (string) ($flags['cancel_blocked_reason'] ?? 'Order cannot be canceled.'),
                    'actions' => $flags,
                ], 422);
            }

            $reason = trim((string) (
                $request->input('rejection_reason')
                ?: $request->input('cancel_reason')
                ?: ''
            ));
            if ($reason === '') {
                return response()->json([
                    'success' => false,
                    'message' => 'Cancellation reason is required.',
                    'actions' => $flags,
                ], 422);
            }

            $actionRequest = Request::create(
                '/superadmin/orders-action/' . (int) $order->id,
                'POST',
                [
                    'action' => 'cancel',
                    'rejection_reason' => $reason,
                    'partner_panel_cancel' => '1',
                ]
            );
            $actionRequest->headers->set('Accept', 'application/json');
            $actionRequest->headers->set('X-Requested-With', 'XMLHttpRequest');

            $response = app(BillingController::class)->orderAction($actionRequest, (int) $order->id);
            $payload = json_decode($response->getContent(), true) ?: [];
            $fresh = Order::query()->whereKey((int) $order->id)->first() ?: $order;
            $payload['actions'] = $this->partnerOrderActionFlags($fresh);
            if (!isset($payload['success'])) {
                $payload['success'] = $response->getStatusCode() < 400;
            }
            if (empty($payload['message'])) {
                $payload['message'] = !empty($payload['success'])
                    ? 'Order cancelled successfully.'
                    : 'Cancel failed.';
            }

            return response()->json(
                $payload,
                $response->getStatusCode() >= 400 ? $response->getStatusCode() : 200
            );
        } catch (\Throwable $e) {
            Log::warning('partner orderCancel failed', [
                'order_id' => (int) $request->input('order_id'),
                'error' => $e->getMessage(),
            ]);

            return response()->json([
                'success' => false,
                'message' => 'Failed to cancel order: ' . $e->getMessage(),
            ], 500);
        }
    }

    /**
     * Partner Panel action flags (edit/cancel within 6 days of creation; never for Google).
     *
     * @return array<string, mixed>
     */
    private function partnerOrderActionFlags(object $order, ?int $providerIdHint = null): array
    {
        try {
            if (!class_exists(OrderCancellationPolicy::class)
                || !method_exists(OrderCancellationPolicy::class, 'partnerPanelActionFlags')
            ) {
                return [
                    'can_edit' => false,
                    'can_cancel' => false,
                    'edit_blocked_reason' => null,
                    'cancel_blocked_reason' => null,
                ];
            }

            return app(OrderCancellationPolicy::class)->partnerPanelActionFlags($order, $providerIdHint);
        } catch (\Throwable $e) {
            Log::warning('partnerOrderActionFlags_failed', [
                'order_id' => (int) ($order->id ?? 0),
                'error' => $e->getMessage(),
            ]);

            return [
                'can_edit' => false,
                'can_cancel' => false,
                'edit_blocked_reason' => null,
                'cancel_blocked_reason' => null,
            ];
        }
    }

