        ], 200);
    }

    /**
     * Get module permissions for a partner user (or full access for partner owner).
     * POST body: partner_id (required), partner_user_id (optional — omit for partner owner).
     */
    public function getUserPermissions(Request $request): JsonResponse
    {
        $validator = Validator::make($request->all(), [
            'partner_id' => ['required', 'integer', 'exists:pgsql_auth.partners,id'],
            'partner_user_id' => ['nullable', 'integer'],
        ]);

        if ($validator->fails()) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => $validator->errors()->first(),
                'data' => null,
            ], 400);
        }

        $partnerId = (int) $request->input('partner_id');
        $partnerUserId = (int) $request->input('partner_user_id', 0);

        if (!Partner::where('id', $partnerId)->exists()) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Partner not found.',
                'data' => null,
            ], 404);
        }

        // Partner owner (no partner_user_id): full access on every allowed module action.
        if ($partnerUserId <= 0) {
            $permissions = PartnerModule::query()
                ->where('status', 1)
                ->orderBy('sort_order')
                ->orderBy('id')
                ->get()
                ->map(function (PartnerModule $module) {
                    $allow = $module->allowFlags();
                    $isDashboard = $this->isDashboardModule($module);

                    return [
                        'module_id' => (int) $module->id,
                        'module_key' => (string) $module->module_key,
                        'module_name' => (string) $module->module_name,
                        'group_name' => (string) $module->group_name,
                        'is_visible_view' => (bool) $allow['allow_view'],
                        'is_visible_add' => (bool) $allow['allow_add'],
                        'is_visible_edit' => (bool) $allow['allow_edit'],
                        'is_visible_delete' => (bool) $allow['allow_delete'],
                        'can_view' => $isDashboard || (bool) $allow['allow_view'],
                        'can_add' => $isDashboard || (bool) $allow['allow_add'],
                        'can_edit' => $isDashboard || (bool) $allow['allow_edit'],
                        'can_delete' => $isDashboard || (bool) $allow['allow_delete'],
                    ];
                })
                ->values()
                ->all();

            return response()->json([
                'success' => true,
                'error' => false,
                'message' => 'User permissions fetched successfully.',
                'data' => [
                    'partner_id' => $partnerId,
                    'partner_user_id' => null,
                    'login_as' => 'partner',
                    'permissions' => $permissions,
                ],
            ], 200);
        }

        $user = PartnerUser::query()
            ->where('partner_id', $partnerId)
            ->whereKey($partnerUserId)
            ->first();

        if (!$user) {
            return response()->json([
                'success' => false,
                'error' => true,
                'message' => 'Partner user not found.',
                'data' => null,
            ], 404);
        }

        $permissions = $this->mapPartnerModulePermissions(
            PartnerPermission::query()
                ->where('partner_user_id', $user->id)
                ->get()
                ->keyBy('module_key')
        )->all();

        return response()->json([
            'success' => true,
            'error' => false,
            'message' => 'User permissions fetched successfully.',
            'data' => [
                'partner_id' => $partnerId,
                'partner_user_id' => (int) $user->id,
                'login_as' => 'partner_user',
                'name' => (string) ($user->name ?? ''),
                'email' => (string) ($user->email ?? ''),
                'mobile' => (string) ($user->mobile ?? ''),
                'status' => (string) ($user->status ?? 'active'),
                'permissions' => $permissions,
            ],
        ], 200);
    }
}
